interface AuditRow {
  id: number;
  saint_id: string;
  action: "insert" | "update" | "delete";
  changed_by: string | null;
  changed_at: string;
  old_full_bio: string | null;
  new_full_bio: string | null;
  old_prayer: string | null;
  new_prayer: string | null;
