};

const fmt = (iso: string | null) => (iso ? new Date(iso).toLocaleString("pt-BR") : "—");

const SaintsReimportRunsPanel: React.FC<{ onApplied?: () => void }> = ({ onApplied }) => {
  const [rows, setRows] = useState<RunRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState<string | null>(null);
  const [expanded, setExpanded] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("saints_reimport_runs" as any)
      .select("*")
      .order("created_at", { ascending: false })
      .limit(20);
    setLoading(false);
    if (!error) setRows((data || []) as unknown as RunRow[]);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const act = async (runId: string, action: "apply" | "reject") => {
    if (action === "apply" && !confirm("Aplicar este run e reimportar os santos listados?")) return;
    setBusy(runId);
    try {
      const { data, error } = await supabase.functions.invoke("admin-apply-saints-reimport-run", {
        body: { run_id: runId, action },
      });
      if (error) throw error;
      if (action === "apply") {
        toast.success("Run aplicado", {
          description: `Atualizados: ${data?.applied ?? 0} · Falhas: ${data?.failed ?? 0}`,
        });
        onApplied?.();
      } else {
        toast.info("Run rejeitado");
      }
      load();
    } catch (e: any) {
      toast.error("Falha na ação", { description: e?.message ?? String(e) });
    } finally {
      setBusy(null);
    }
  };

  const pending = rows.filter((r) => r.status === "pending_approval");

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between gap-3 flex-wrap">
        <CardTitle className="text-lg flex items-center gap-2">
          <Icons.Clock className="w-4 h-4" /> Runs agendados de reimport
          {pending.length > 0 && (
            <Badge
              variant="outline"
              className="ml-2 text-[10px] border-amber-500/40 text-amber-700 dark:text-amber-300"
            >
              {pending.length} aguardando aprovação
            </Badge>
          )}
        </CardTitle>
        <div className="flex items-center gap-3">
          <span className="text-[11px] text-muted-foreground">Cron diário 03:00 UTC · dry-run</span>
          <Button variant="ghost" size="sm" onClick={load}>
            <Icons.RefreshCw className={`w-4 h-4 mr-1 ${loading ? "animate-spin" : ""}`} />{" "}
            Atualizar
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {rows.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            Ainda não há runs registrados. O cron diário criará um dry-run automaticamente às 03:00
            UTC.
          </p>
        ) : (
          <div className="space-y-2">
            {rows.map((r) => {
              const open = expanded === r.id;
              return (
                <div key={r.id} className="border rounded-md">
                  <div className="flex items-center gap-3 p-3 flex-wrap">
                    <Badge
                      variant="outline"
                      className={`${STATUS_COLORS[r.status]} text-[10px] uppercase`}
                    >
                      {r.status.replace("_", " ")}
                    </Badge>
                    <Badge variant="outline" className="text-[10px] uppercase">
                      {r.source}
                    </Badge>
                    <div className="text-xs text-muted-foreground">{fmt(r.created_at)}</div>
                    <div className="text-xs ml-auto">
                      considerados: <b>{r.summary?.considered ?? 0}</b> · atualizariam:{" "}
                      <b className="text-blue-600 dark:text-blue-400">
                        {r.summary?.would_update ?? 0}
                      </b>{" "}
                      · inalterados: {r.summary?.unchanged ?? 0} · falhas: {r.summary?.failed ?? 0}
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setExpanded(open ? null : r.id)}
                    >
                      {open ? "Recolher" : "Ver prévia"}
                    </Button>
                    {r.status === "pending_approval" && (
                      <>
                        <Button
                          size="sm"
                          onClick={() => act(r.id, "apply")}
                          disabled={busy === r.id || (r.summary?.would_update ?? 0) === 0}
                        >
                          {busy === r.id
                            ? "Aplicando…"
                            : `Aplicar (${r.summary?.would_update ?? 0})`}
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => act(r.id, "reject")}
                          disabled={busy === r.id}
                        >
                          Rejeitar
                        </Button>
                      </>
                    )}
                    {r.applied_summary && (
                      <span className="text-[11px] text-muted-foreground">
                        aplicado {fmt(r.approved_at)} · {r.applied_summary.applied}/
                        {r.applied_summary.targets} ok · {r.applied_summary.failed} falhas
                      </span>
                    )}
                  </div>
                  {open && (
                    <div className="border-t divide-y max-h-72 overflow-y-auto text-sm">
                      {(r.preview || []).length === 0 && (
                        <p className="p-3 text-muted-foreground text-sm">Prévia vazia.</p>
                      )}
                      {(r.preview || []).map((p) => (
                        <div key={p.id} className="py-2 px-3 flex items-center gap-3">
                          <Badge
                            variant="outline"
                            className={
                              p.reason === "would_fill_full_bio"
                                ? "border-emerald-500/40 text-emerald-700 dark:text-emerald-300"
                                : p.reason === "would_update"
                                  ? "border-blue-500/40 text-blue-700 dark:text-blue-300"
                                  : p.reason === "fetch_failed"
                                    ? "border-red-500/40 text-red-700 dark:text-red-300"
                                    : "border-border text-muted-foreground"
                            }
                          >
                            {REASON_LABEL[p.reason] || p.reason}
                          </Badge>
                          <div className="min-w-0 flex-1">
                            <p className="font-medium truncate">{p.name || p.id}</p>
                            <p className="text-[11px] text-muted-foreground truncate">
                              {p.source_url}
                            </p>
                          </div>
                          <span className="font-mono text-[10px] text-muted-foreground shrink-0">
                            {(p.old_hash || "—").slice(0, 8)} → {(p.new_hash || "—").slice(0, 8)}
                          </span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default SaintsReimportRunsPanel;

import { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { GitCompareArrows, Download, Link2 } from "lucide-react";
import { toast } from "sonner";
import { fingerprintQuery, shortFingerprint } from "./queryFingerprint";
import type { SnapshotHistoryRow } from "./useSnapshotHistory";
import { supabase } from "@/lib/db";

const fmtMs = (v: number) => (v >= 1000 ? `${(v / 1000).toFixed(2)} s` : `${v.toFixed(2)} ms`);
const fmtInt = (v: number) => (v ?? 0).toLocaleString("pt-BR");

interface Agg {
  fingerprint: string;
  example: string;
  calls: number;
  totalMs: number;
  meanMs: number;
  p95Ms: number;
}

function aggregate(snapshots: SnapshotHistoryRow[]): Map<string, Agg> {
  const map = new Map<string, Agg>();
  for (const s of snapshots) {
    for (const r of s.rows || []) {
      const fp = fingerprintQuery(r.query);
      const cur = map.get(fp) || {
        fingerprint: fp,
        example: r.query,
        calls: 0,
        totalMs: 0,
        meanMs: 0,
        p95Ms: 0,
      };
      cur.calls += r.calls || 0;
      cur.totalMs += r.total_exec_time || 0;
      cur.p95Ms = Math.max(cur.p95Ms, r.max_exec_time || 0);
      map.set(fp, cur);
    }
  }
  for (const v of map.values()) {
    v.meanMs = v.calls > 0 ? v.totalMs / v.calls : 0;
  }
  return map;
}

function toIsoDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function todayIso(): string {
  return toIsoDate(new Date());
}
function daysAgoIso(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() - days);
  return toIsoDate(d);
}

const DEFAULT_REG_MEAN_PCT = 20;
const DEFAULT_REG_P95_PCT = 25;

function readParam(name: string, fallback: string): string {
  if (typeof window === "undefined") return fallback;
  return new URLSearchParams(window.location.search).get(name) ?? fallback;
}

export function IntervalCompareCard({ snapshots }: { snapshots: SnapshotHistoryRow[] }) {
  const [aFrom, setAFrom] = useState(() => readParam("aFrom", daysAgoIso(14)));
  const [aTo, setATo] = useState(() => readParam("aTo", daysAgoIso(7)));
  const [bFrom, setBFrom] = useState(() => readParam("bFrom", daysAgoIso(7)));
  const [bTo, setBTo] = useState(() => readParam("bTo", todayIso()));
  const [onlyRegressions, setOnlyRegressions] = useState(() => readParam("onlyReg", "") === "1");
  const [userId, setUserId] = useState<string | null>(null);
  const [regMean, setRegMean] = useState<number>(DEFAULT_REG_MEAN_PCT);
  const [regP95, setRegP95] = useState<number>(DEFAULT_REG_P95_PCT);

  // load user + persisted thresholds (per user, fallback session)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const { data } = await supabase.auth.getUser();
      const uid = data.user?.id ?? null;
      if (cancelled) return;
      setUserId(uid);
      const key = uid ? `pgstats:reg:${uid}` : "pgstats:reg:session";
      const raw = uid ? localStorage.getItem(key) : sessionStorage.getItem(key);
      if (raw) {
        try {
          const parsed = JSON.parse(raw);
          if (typeof parsed.mean === "number") setRegMean(parsed.mean);
          if (typeof parsed.p95 === "number") setRegP95(parsed.p95);
        } catch {
          /* ignore */
        }
      }
      // URL params override persisted
      const urlMean = Number(readParam("regMean", ""));
      const urlP95 = Number(readParam("regP95", ""));
      if (Number.isFinite(urlMean) && urlMean > 0) setRegMean(urlMean);
      if (Number.isFinite(urlP95) && urlP95 > 0) setRegP95(urlP95);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // persist thresholds
  useEffect(() => {
    const payload = JSON.stringify({ mean: regMean, p95: regP95 });
    const key = userId ? `pgstats:reg:${userId}` : "pgstats:reg:session";
    try {
      if (userId) localStorage.setItem(key, payload);
      else sessionStorage.setItem(key, payload);
    } catch {
      /* ignore quota */
    }
  }, [regMean, regP95, userId]);

  const filterByRange = (from: string, to: string) => {
    const fromT = new Date(from + "T00:00:00").getTime();
    const toT = new Date(to + "T23:59:59").getTime();
    return snapshots.filter((s) => {
      const t = new Date(s.taken_at).getTime();
      return t >= fromT && t <= toT;
    });
  };

  const rangeA = useMemo(() => filterByRange(aFrom, aTo), [snapshots, aFrom, aTo]);
  const rangeB = useMemo(() => filterByRange(bFrom, bTo), [snapshots, bFrom, bTo]);

  const rows = useMemo(() => {
    const a = aggregate(rangeA);
    const b = aggregate(rangeB);
    const keys = new Set<string>([...a.keys(), ...b.keys()]);
    const out: Array<{
      fingerprint: string;
      example: string;
      aMean: number;
      bMean: number;
      dMeanPct: number;
      aP95: number;
      bP95: number;
      dP95Pct: number;
      aCalls: number;
      bCalls: number;
      dCallsPct: number;
      aTotal: number;
      bTotal: number;
      regression: boolean;
    }> = [];
    for (const k of keys) {
      const ra = a.get(k);
      const rb = b.get(k);
      const aMean = ra?.meanMs ?? 0;
      const bMean = rb?.meanMs ?? 0;
      const aP95 = ra?.p95Ms ?? 0;
      const bP95 = rb?.p95Ms ?? 0;
      const aCalls = ra?.calls ?? 0;
      const bCalls = rb?.calls ?? 0;
      const dMeanPct = aMean > 0 ? ((bMean - aMean) / aMean) * 100 : bMean > 0 ? 100 : 0;
      const dP95Pct = aP95 > 0 ? ((bP95 - aP95) / aP95) * 100 : bP95 > 0 ? 100 : 0;
      const dCallsPct = aCalls > 0 ? ((bCalls - aCalls) / aCalls) * 100 : bCalls > 0 ? 100 : 0;
      const regression = (dMeanPct >= regMean && bMean > 5) || (dP95Pct >= regP95 && bP95 > 20);
      out.push({
        fingerprint: k,
        example: rb?.example || ra?.example || "",
        aMean,
        bMean,
        dMeanPct,
        aP95,
        bP95,
        dP95Pct,
        aCalls,
        bCalls,
        dCallsPct,
        aTotal: ra?.totalMs ?? 0,
        bTotal: rb?.totalMs ?? 0,
        regression,
      });
    }
    out.sort((x, y) => y.bTotal + y.aTotal - (x.bTotal + x.aTotal));
    return onlyRegressions ? out.filter((r) => r.regression) : out.slice(0, 50);
  }, [rangeA, rangeB, onlyRegressions, regMean, regP95]);

  const buildShareUrl = () => {
    const params = new URLSearchParams(window.location.search);
    params.set("aFrom", aFrom);
    params.set("aTo", aTo);
    params.set("bFrom", bFrom);
    params.set("bTo", bTo);
    params.set("onlyReg", onlyRegressions ? "1" : "0");
    params.set("regMean", String(regMean));
    params.set("regP95", String(regP95));
    return `${window.location.origin}${window.location.pathname}?${params.toString()}`;
  };

  const copyShareUrl = async () => {
    try {
      const url = buildShareUrl();
      await navigator.clipboard.writeText(url);
      window.history.replaceState(null, "", url);
      toast.success("Link copiado — filtros e intervalos preservados");
    } catch {
      toast.error("Falha ao copiar link");
    }
  };

  const exportCsv = () => {
    const escape = (v: unknown) => {
      const s = v == null ? "" : String(v);
      return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    const header = [
      "fingerprint",
      "regression",
      "a_mean_ms",
      "b_mean_ms",
      "delta_mean_pct",
      "a_p95_ms",
      "b_p95_ms",
      "delta_p95_pct",
      "a_calls",
      "b_calls",
      "delta_calls_pct",
      "a_total_ms",
      "b_total_ms",
      "example",
    ];
    const lines = [header.join(",")];
    for (const r of rows) {
      lines.push(
        [
          r.fingerprint,
          r.regression ? "1" : "0",
          r.aMean.toFixed(3),
          r.bMean.toFixed(3),
          r.dMeanPct.toFixed(1),
          r.aP95.toFixed(3),
          r.bP95.toFixed(3),
          r.dP95Pct.toFixed(1),
          r.aCalls,
          r.bCalls,
          r.dCallsPct.toFixed(1),
          r.aTotal.toFixed(3),
          r.bTotal.toFixed(3),
          r.example,
        ]
          .map(escape)
          .join(","),
      );
    }
    const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `pg_stat_compare_${aFrom}_${aTo}__vs__${bFrom}_${bTo}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    toast.success(`${rows.length} linhas exportadas`);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-base flex items-center gap-2">
          <GitCompareArrows className="h-4 w-4" />
          Comparar intervalos (A × B)
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="rounded-md border p-3 space-y-2">
            <p className="text-xs font-medium">Intervalo A ({rangeA.length} snapshots)</p>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">De</Label>
                <Input type="date" value={aFrom} onChange={(e) => setAFrom(e.target.value)} />
              </div>
              <div>
                <Label className="text-xs">Até</Label>
                <Input type="date" value={aTo} onChange={(e) => setATo(e.target.value)} />
              </div>
            </div>
          </div>
          <div className="rounded-md border p-3 space-y-2">
            <p className="text-xs font-medium">Intervalo B ({rangeB.length} snapshots)</p>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <Label className="text-xs">De</Label>
                <Input type="date" value={bFrom} onChange={(e) => setBFrom(e.target.value)} />
              </div>
              <div>
                <Label className="text-xs">Até</Label>
                <Input type="date" value={bTo} onChange={(e) => setBTo(e.target.value)} />
              </div>
            </div>
          </div>
        </div>

        <div className="flex flex-wrap items-end gap-2">
          <Button
            size="sm"
            variant={onlyRegressions ? "default" : "outline"}
            onClick={() => setOnlyRegressions((v) => !v)}
          >
            {onlyRegressions ? "Mostrando só regressões" : "Só regressões"}
          </Button>
          <Button size="sm" variant="outline" onClick={exportCsv} disabled={rows.length === 0}>
            <Download className="h-4 w-4 mr-2" /> CSV
          </Button>
          <Button size="sm" variant="outline" onClick={copyShareUrl}>
            <Link2 className="h-4 w-4 mr-2" /> Copiar link
          </Button>
          <div className="flex items-center gap-2 ml-auto rounded-md border px-3 py-1.5">
            <span className="text-xs text-muted-foreground">Limiares REG:</span>
            <div className="flex items-center gap-1">
              <Label htmlFor="reg-mean" className="text-[11px]">
                média ≥
              </Label>
              <Input
                id="reg-mean"
                type="number"
                min={1}
                max={500}
                className="h-7 w-16 text-xs"
                value={regMean}
                onChange={(e) =>
                  setRegMean(Math.max(1, Math.min(500, Number(e.target.value) || 0)))
                }
              />
              <span className="text-[11px]">%</span>
            </div>
            <div className="flex items-center gap-1">
              <Label htmlFor="reg-p95" className="text-[11px]">
                p95 ≥
              </Label>
              <Input
                id="reg-p95"
                type="number"
                min={1}
                max={500}
                className="h-7 w-16 text-xs"
                value={regP95}
                onChange={(e) => setRegP95(Math.max(1, Math.min(500, Number(e.target.value) || 0)))}
              />
              <span className="text-[11px]">%</span>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Fingerprint</TableHead>
                <TableHead className="text-right">Média A</TableHead>
                <TableHead className="text-right">Média B</TableHead>
                <TableHead className="text-right">Δ média</TableHead>
                <TableHead className="text-right">p95 A</TableHead>
                <TableHead className="text-right">p95 B</TableHead>
                <TableHead className="text-right">Δ p95</TableHead>
                <TableHead className="text-right">Δ calls</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.length === 0 && (
                <TableRow>
                  <TableCell colSpan={8} className="text-center text-muted-foreground py-6 text-sm">
                    Nenhum dado nos intervalos selecionados.
                  </TableCell>
                </TableRow>
              )}
              {rows.map((r, i) => (
                <TableRow key={i} className={r.regression ? "bg-destructive/5" : ""}>
                  <TableCell className="font-mono text-xs max-w-md truncate">
                    {r.regression && (
                      <Badge variant="destructive" className="mr-2 text-[10px]">
                        REG
                      </Badge>
                    )}
                    {shortFingerprint(r.fingerprint, 90)}
                  </TableCell>
                  <TableCell className="text-right text-xs">{fmtMs(r.aMean)}</TableCell>
                  <TableCell className="text-right text-xs">{fmtMs(r.bMean)}</TableCell>
                  <TableCell
                    className={`text-right text-xs font-medium ${
                      r.dMeanPct > 0 ? "text-destructive" : r.dMeanPct < 0 ? "text-primary" : ""
                    }`}
                  >
                    {r.dMeanPct > 0 ? "+" : ""}
                    {r.dMeanPct.toFixed(1)}%
                  </TableCell>
                  <TableCell className="text-right text-xs">{fmtMs(r.aP95)}</TableCell>
                  <TableCell className="text-right text-xs">{fmtMs(r.bP95)}</TableCell>
                  <TableCell
                    className={`text-right text-xs font-medium ${
                      r.dP95Pct > 0 ? "text-destructive" : r.dP95Pct < 0 ? "text-primary" : ""
                    }`}
                  >
                    {r.dP95Pct > 0 ? "+" : ""}
                    {r.dP95Pct.toFixed(1)}%
                  </TableCell>
                  <TableCell
                    className={`text-right text-xs ${
                      r.dCallsPct > 0 ? "text-muted-foreground" : ""
                    }`}
                  >
                    {fmtInt(r.aCalls)} → {fmtInt(r.bCalls)}{" "}
                    <span className="opacity-60">
                      ({r.dCallsPct > 0 ? "+" : ""}
                      {r.dCallsPct.toFixed(0)}%)
                    </span>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { supabase } from "@/lib/db";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Activity, RefreshCw, ChevronRight, ChevronDown } from "lucide-react";
import { toast } from "sonner";

interface BreakdownEntry {
  label: string;
  ms: number;
}

interface EventRow {
  correlation_id: string | null;
  abbrev: string;
  chapter: number;
  cache: string | null;
  total_ms: number | null;
  sql_ms: number | null;
  edge_ms: number | null;
  bolls_ms: number | null;
  sql_breakdown: BreakdownEntry[] | null;
  created_at: string;
}

function cacheBadgeVariant(
  cache: string | null,
): "default" | "secondary" | "destructive" | "outline" {
  if (cache === "HIT") return "default";
  if (cache === "MISS") return "destructive";
  if (cache?.startsWith("STALE")) return "secondary";
  return "outline";
}

export default function SqlBreakdownSection() {
  const [rows, setRows] = useState<EventRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [abbrevFilter, setAbbrevFilter] = useState("");
  const [correlationFilter, setCorrelationFilter] = useState("");
  const [limit, setLimit] = useState(50);
  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const load = async () => {
    setLoading(true);
    let q = supabase
      .from("bible_cache_metric_events")
      .select(
        "correlation_id, abbrev, chapter, cache, total_ms, sql_ms, edge_ms, bolls_ms, sql_breakdown, created_at",
      )
      .not("sql_breakdown", "is", null)
      .order("created_at", { ascending: false })
      .limit(Math.max(1, Math.min(500, limit)));
    if (abbrevFilter.trim()) q = q.eq("abbrev", abbrevFilter.trim());
    if (correlationFilter.trim()) q = q.eq("correlation_id", correlationFilter.trim());
    const { data, error } = await q;
    setLoading(false);
    if (error) {
      toast.error(error.message);
      return;
    }
    setRows((data ?? []) as unknown as EventRow[]);
  };

  useEffect(() => {
    load(); /* eslint-disable-next-line */
  }, []);

  const stats = useMemo(() => {
    if (!rows.length) return null;
    const total = rows.length;
    const hits = rows.filter((r) => r.cache === "HIT").length;
    const avgSql = Math.round(rows.reduce((s, r) => s + (r.sql_ms ?? 0), 0) / total);
    const avgTotal = Math.round(rows.reduce((s, r) => s + (r.total_ms ?? 0), 0) / total);
    return {
      total,
      hitRate: Math.round((hits / total) * 100),
      avgSql,
      avgTotal,
    };
  }, [rows]);

  const toggle = (id: string) => {
    const next = new Set(expanded);
    next.has(id) ? next.delete(id) : next.add(id);
    setExpanded(next);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-sm flex items-center gap-2">
          <Activity className="w-4 h-4" /> Breakdown por <code>correlation_id</code>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-end gap-2">
          <div className="space-y-1">
            <Label className="text-xs">Livro (abbrev)</Label>
            <Input
              value={abbrevFilter}
              onChange={(e) => setAbbrevFilter(e.target.value)}
              placeholder="ex: Lv"
              className="w-28"
            />
          </div>
          <div className="space-y-1">
            <Label className="text-xs">correlation_id</Label>
            <Input
              value={correlationFilter}
              onChange={(e) => setCorrelationFilter(e.target.value)}
              placeholder="opcional"
              className="w-72"
            />
          </div>
          <div className="space-y-1">
            <Label className="text-xs">Limite</Label>
            <Input
              type="number"
              min={1}
              max={500}
              value={limit}
              onChange={(e) => setLimit(Number(e.target.value) || 50)}
              className="w-24"
            />
          </div>
          <Button size="sm" variant="outline" onClick={load} disabled={loading}>
            <RefreshCw className={`mr-2 h-4 w-4 ${loading ? "animate-spin" : ""}`} /> Buscar
          </Button>
          {stats && (
            <div className="ml-auto text-xs text-muted-foreground flex gap-3">
              <span>{stats.total} eventos</span>
              <span>cache hit {stats.hitRate}%</span>
              <span>avg sql {stats.avgSql}ms</span>
              <span>avg total {stats.avgTotal}ms</span>
            </div>
          )}
        </div>

        <p className="text-[11px] text-muted-foreground">
          Mostra apenas eventos com <code>sql_breakdown</code> persistido. Clique numa linha para
          expandir as etapas SQL com tempo (wall-clock) por <em>label</em>.
        </p>

        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-8"></TableHead>
                <TableHead>Quando</TableHead>
                <TableHead>Livro</TableHead>
                <TableHead>Cap</TableHead>
                <TableHead>Cache</TableHead>
                <TableHead className="text-right">total ms</TableHead>
                <TableHead className="text-right">sql ms</TableHead>
                <TableHead className="text-right">edge ms</TableHead>
                <TableHead className="text-right">upstream ms</TableHead>
                <TableHead>correlation_id</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.length === 0 && (
                <TableRow>
                  <TableCell colSpan={10} className="text-center text-muted-foreground py-6">
                    Sem eventos.
                  </TableCell>
                </TableRow>
              )}
              {rows.map((r, i) => {
                const id = `${r.correlation_id ?? "nil"}-${i}`;
                const open = expanded.has(id);
                const entries = Array.isArray(r.sql_breakdown) ? r.sql_breakdown : [];
                const sumEntries = entries.reduce((s, e) => s + (Number(e.ms) || 0), 0);
                return (
                  <React.Fragment key={id}>
                    <TableRow
                      className="cursor-pointer hover:bg-muted/40"
                      onClick={() => toggle(id)}
                    >
                      <TableCell>
                        {open ? (
                          <ChevronDown className="w-4 h-4" />
                        ) : (
                          <ChevronRight className="w-4 h-4" />
                        )}
                      </TableCell>
                      <TableCell className="text-xs">
                        {new Date(r.created_at).toLocaleString()}
                      </TableCell>
                      <TableCell className="font-mono">{r.abbrev}</TableCell>
                      <TableCell>{r.chapter}</TableCell>
                      <TableCell>
                        <Badge variant={cacheBadgeVariant(r.cache)}>{r.cache ?? "—"}</Badge>
                      </TableCell>
                      <TableCell className="text-right">{r.total_ms ?? "—"}</TableCell>
                      <TableCell className="text-right">{r.sql_ms ?? "—"}</TableCell>
                      <TableCell className="text-right">{r.edge_ms ?? "—"}</TableCell>
                      <TableCell className="text-right">{r.bolls_ms ?? "—"}</TableCell>
                      <TableCell
                        className="font-mono text-[11px] truncate max-w-[200px]"
                        title={r.correlation_id ?? ""}
                      >
                        {r.correlation_id ?? "—"}
                      </TableCell>
                    </TableRow>
                    {open && (
                      <TableRow>
                        <TableCell colSpan={10} className="bg-muted/30">
                          {entries.length === 0 ? (
                            <p className="text-xs text-muted-foreground">Sem etapas registradas.</p>
                          ) : (
                            <div className="space-y-2">
                              <div className="text-xs text-muted-foreground">
                                Soma das etapas: <strong>{sumEntries}ms</strong> · sql_ms
                                (wall-clock fundido): <strong>{r.sql_ms ?? 0}ms</strong>
                                {sumEntries > (r.sql_ms ?? 0) && (
                                  <span className="ml-2 text-amber-600">
                                    (diferença = paralelismo)
                                  </span>
                                )}
                              </div>
                              <Table>
                                <TableHeader>
                                  <TableRow>
                                    <TableHead>Etapa</TableHead>
                                    <TableHead className="text-right">ms</TableHead>
                                    <TableHead className="text-right">% do sql_ms</TableHead>
                                  </TableRow>
                                </TableHeader>
                                <TableBody>
                                  {[...entries]
                                    .sort((a, b) => b.ms - a.ms)
                                    .map((e, j) => {
                                      const pct = r.sql_ms
                                        ? Math.round((e.ms / r.sql_ms) * 100)
                                        : 0;
                                      return (
                                        <TableRow key={j}>
                                          <TableCell className="font-mono text-xs">
                                            {e.label}
                                          </TableCell>
                                          <TableCell className="text-right">{e.ms}</TableCell>
                                          <TableCell className="text-right">{pct}%</TableCell>
                                        </TableRow>
                                      );
                                    })}
                                </TableBody>
                              </Table>
                            </div>
                          )}
                        </TableCell>
                      </TableRow>
                    )}
                  </React.Fragment>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  );
}

import { Icons } from "@/constants";
import React, { useState, useMemo, useEffect, useRef } from "react";
import { useNavigate, useLocation } from "@/lib/rr-compat";
import SEOHead from "@/components/SEOHead";
import { AppRoute } from "@/types";
import { motion } from "framer-motion";

import { Button } from "@/components/ui/button";
import AZFaithQuiz from "./AZFaithQuiz";
import { useGlossary } from "@/hooks/useGlossary";
import AlphabetBar from "./encyclopedia/AlphabetBar";
import EncyclopediaTermList from "./encyclopedia/EncyclopediaTermList";
import EncyclopediaTermDetail from "./encyclopedia/EncyclopediaTermDetail";
import ContemplativeLayout from "./ContemplativeLayout";

export interface FaithTerm {
  term: string;
  definition: string;
  reference?: string;
  category?: string;
  deepInterpretation?: string;
  practicalApplication?: string;
  bibleVerses?: string[];
  catechismReferences?: string[];
  magisteriumReferences?: string[];
  journey_id?: string;
}

const FEATURED_TERMS = ["Amor", "Fé", "Graça", "Eucaristia", "Trindade", "Perdão"];

const AZFaithPage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedLetter, setSelectedLetter] = useState<string | null>("A");
  const [selectedTerm, setSelectedTerm] = useState<FaithTerm | null>(null);
  const [quizMode, setQuizMode] = useState(false);
  const detailRef = useRef<HTMLDivElement>(null);

  const { data: dbTerms, isLoading } = useGlossary();

  // Fallback to empty if loading, but in reality we should show a skeleton
  const allTerms = dbTerms || [];

  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

  const letterStatus = useMemo(() => {
    const status: Record<string, boolean> = {};
    alphabet.forEach((l) => {
      status[l] = allTerms.some((t) => t.term.toUpperCase().startsWith(l));
    });
    return status;
  }, [allTerms]);

  useEffect(() => {
    if (selectedTerm && window.innerWidth < 768) {
      setTimeout(() => {
        detailRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 100);
    }
  }, [selectedTerm]);

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const q = params.get("q");
    if (q && allTerms.length > 0) {
      setSearchQuery(q);
      setSelectedLetter(null);

      const exactMatch = allTerms.find((t) => t.term.toLowerCase() === q.toLowerCase());
      if (exactMatch) {
        setSelectedTerm(exactMatch);
      }
    }
  }, [location.search, allTerms]);

  const filteredTerms = useMemo(() => {
    let result = allTerms;
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (t) =>
          t.term.toLowerCase().includes(q) ||
          t.definition.toLowerCase().includes(q) ||
          t.category?.toLowerCase().includes(q),
      );
    } else if (selectedLetter) {
      result = result.filter((t) => t.term.toUpperCase().startsWith(selectedLetter));
    }
    return result.sort((a, b) => a.term.localeCompare(b.term));
  }, [searchQuery, selectedLetter, allTerms]);

  const handleLetterClick = (letter: string) => {
    setSelectedLetter(letter);
    setSearchQuery("");
    setSelectedTerm(null);
  };

  const handleTermClick = (term: FaithTerm) => {
    setSelectedTerm(selectedTerm?.term === term.term ? null : term);
  };

  if (isLoading && allTerms.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="animate-spin rounded-premium h-spacing-2xl w-spacing-2xl border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <ContemplativeLayout
      title="A–Z da Fé"
      subtitle="Glossarium Fidei"
      icon={Icons.BookOpen}
      headerActions={
        <Button
          variant={quizMode ? "default" : "outline"}
          onClick={() => setQuizMode(!quizMode)}
          className="rounded-premium-full gap-spacing-xs font-bold text-premium-xs uppercase tracking-widest"
        >
          <Icons.Brain className="w-spacing-md h-spacing-md" />
          {quizMode ? "Voltar ao Índice" : "🧠 Testar Conhecimento"}
        </Button>
      }
    >
      <SEOHead
        title="A–Z da Fé | Cathedra"
        description="Explore o índice alfabético de termos bíblicos e teológicos."
        path="/az-faith"
      />

      {quizMode ? (
        <AZFaithQuiz terms={allTerms} onClose={() => setQuizMode(false)} />
      ) : (
        <>
          <div className="relative w-full mb-spacing-lg">
            <Icons.Search className="absolute left-spacing-md top-spacing-2xs/2 -translate-y-1/2 w-spacing-md h-spacing-md text-muted-foreground" />
            <input
              type="text"
              placeholder="Buscar..."
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                if (e.target.value) setSelectedLetter(null);
              }}
              className="w-full pl-spacing-xl pr-spacing-xl py-spacing-sm bg-card border border-border rounded-premium-full focus:outline-none focus:ring-2 focus:ring-primary/30 text-premium-sm"
            />
            {searchQuery && (
              <Button
                onClick={() => setSearchQuery("")}
                className="absolute right-spacing-md top-spacing-2xs/2 -translate-y-1/2"
              >
                <Icons.X className="w-spacing-md h-spacing-md text-muted-foreground" />
              </Button>
            )}
          </div>

          <div className="flex justify-center gap-spacing-md mb-spacing-2xl flex-wrap w-full px-spacing-md">
            {FEATURED_TERMS.map((name, idx) => {
              const term = allTerms.find((t) => t.term === name);
              if (!term) return null;
              const isActive = selectedTerm?.term === name;
              return (
                <motion.button
                  key={name}
                  initial={{ scale: 0.9, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  transition={{ delay: idx * 0.05 }}
                  whileHover={{ scale: 1.05, y: -2 }}
                  whileTap={{ scale: 0.95 }}
                  onClick={() => handleTermClick(term)}
                  className={`px-spacing-xl py-spacing-md rounded-premium-full text-premium-xs font-bold uppercase tracking-[0.2em] border transition-all relative overflow-hidden group focus-visible:ring-4 focus-visible:ring-primary/20 outline-none shadow-premium-md
                      ${
                        isActive
                          ? "bg-primary text-primary-foreground border-primary shadow-premium ring-4 ring-primary/10"
                          : "bg-card  text-primary border-primary/20 hover:border-primary/50 hover:shadow-premium"
                      }`}
                >
                  <div className="flex items-center gap-spacing-xs relative z-10">
                    <span className="opacity-80 group-hover:scale-125 transition-transform duration-500">
                      🫧
                    </span>
                    {name}
                  </div>
                </motion.button>
              );
            })}
          </div>

          <AlphabetBar
            alphabet={alphabet}
            selectedLetter={selectedLetter}
            letterStatus={letterStatus}
            onLetterClick={handleLetterClick}
          />

          <div className="grid grid-cols-1 md:grid-cols-12 gap-spacing-lg min-h-[400px]">
            <EncyclopediaTermList
              terms={filteredTerms}
              selectedTerm={selectedTerm}
              onTermClick={handleTermClick}
            />

            <EncyclopediaTermDetail
              selectedTerm={selectedTerm}
              detailRef={detailRef}
              navigate={navigate}
              onStudyWithLogos={(term) =>
                navigate(`${AppRoute.STUDY_MODE}?topic=${encodeURIComponent(term)}`)
              }
              onLiveThis={(term) => {
                if (term.journey_id) {
                  navigate(`/jornadas/${term.journey_id}`);
                } else {
                  const ref = term.reference?.split(";")[0].trim();
                  navigate(
                    `${AppRoute.LECTIO_DIVINA}${ref ? `?ref=${encodeURIComponent(ref)}` : ""}`,
                  );
                }
              }}
            />
          </div>
        </>
      )}
    </ContemplativeLayout>
  );
};

export default AZFaithPage;

import React, { useEffect, useState } from "react";
import { useLocation } from "@/lib/rr-compat";

const AboveTheFoldTest: React.FC = () => {
  const [report, setReport] = useState<any>(null);
  const location = useLocation();

  useEffect(() => {
    // Wait for content to settle
    const timer = setTimeout(() => {
      const header = document.querySelector("header");
      const headerHeight = header?.getBoundingClientRect().height || 0;
      const viewportHeight = window.innerHeight;
      const foldThreshold = viewportHeight * 0.15; // Tightened: Premium requirement is content very high

      const mainContent = document.getElementById("main-content");
      const contentTop = mainContent?.getBoundingClientRect().top || 0;

      // Detection for Layout Shifts
      const entries = performance.getEntriesByType("layout-shift");
      const cls = entries.reduce(
        (sum, entry: any) => sum + (entry.hadRecentInput ? 0 : entry.value),
        0,
      );

      const results = {
        path: location.pathname,
        headerHeight,
        contentTop,
        viewportHeight,
        cls,
        status: contentTop < foldThreshold && cls < 0.05 ? "PASS" : "FAIL",
        details: `Top: ${contentTop}px (Fold: ${foldThreshold.toFixed(0)}px), CLS: ${cls.toFixed(4)}`,
      };

      console.log("--- PREMIUM SPRINT AUDIT ---");
      console.log(JSON.stringify(results, null, 2));
      setReport(results);
    }, 3000);

    return () => clearTimeout(timer);
  }, [location.pathname]);

  if (!import.meta.env.DEV) return null;

  return (
    <div className="fixed bottom-0 right-0 z-[1000] p-spacing-xs bg-black/80 text-white text-[8px] font-mono pointer-events-none">
      {report && (
        <div className={report.status === "PASS" ? "text-green-400" : "text-red-400"}>
          {report.status}: {report.details}
        </div>
      )}
    </div>
  );
};

export default AboveTheFoldTest;

