  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import * as XLSX from "xlsx";

interface Project {
  id: string;
  name: string;
  description: string | null;
  status: string;
  created_at: string;
}

interface ConstructionData {
  id: string;
  project_id: string;
  type: "budget" | "schedule";
  item_name: string;
  planned_value: number | null;
  actual_value: number | null;
  planned_start_date: string | null;
  planned_end_date: string | null;
  actual_start_date: string | null;
  actual_end_date: string | null;
  progress: number;
  category: string | null;
}

const AdminConstructionTab: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [isAddProjectDialogOpen, setIsAddProjectDialogOpen] = useState(false);
  const [isUploadDialogOpen, setIsUploadDialogOpen] = useState(false);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [uploadType, setUploadType] = useState<"budget" | "schedule">("budget");
  const [uploading, setUploading] = useState(false);

  const [newProject, setNewProject] = useState({
    name: "",
    description: "",
    status: "em_andamento",
  });

  useEffect(() => {
    fetchProjects();
  }, []);

  const fetchProjects = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("construction_projects")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setProjects(data || []);
    } catch (error: any) {
      toast.error("Erro ao buscar obras: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleCreateProject = async () => {
    if (!newProject.name) {
      toast.error("Nome da obra é obrigatório");
      return;
    }

    try {
      const { data, error } = await supabase
        .from("construction_projects")
        .insert([newProject])
        .select()
        .single();

      if (error) throw error;

      setProjects([data, ...projects]);
      toast.success("Obra criada com sucesso");
      setIsAddProjectDialogOpen(false);
      setNewProject({ name: "", description: "", status: "em_andamento" });
    } catch (error: any) {
      toast.error("Erro ao criar obra: " + error.message);
    }
  };

  const handleDeleteProject = async (id: string) => {
    if (!window.confirm("Tem certeza que deseja excluir esta obra e todos os seus dados?")) return;

    try {
      const { error } = await supabase.from("construction_projects").delete().eq("id", id);

      if (error) throw error;

      setProjects((prev) => prev.filter((p) => p.id !== id));
      toast.success("Obra excluída");
    } catch (error: any) {
      toast.error("Erro ao excluir obra: " + error.message);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedProjectId) return;

    setUploading(true);
    const reader = new FileReader();

    reader.onload = async (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet);

        if (jsonData.length === 0) {
          toast.error("A planilha está vazia");
          setUploading(false);
          return;
        }

        // Process data based on type
        const formattedData = jsonData.map((row: any) => {
          if (uploadType === "budget") {
            return {
              project_id: selectedProjectId,
              type: "budget",
              item_name: row["Item"] || row["Nome"] || row["Descrição"] || "Sem nome",
              planned_value: row["Previsto"] || row["Orçado"] || 0,
              actual_value: row["Real"] || row["Gasto"] || 0,
              category: row["Categoria"] || "Geral",
            };
          } else {
            return {
              project_id: selectedProjectId,
              type: "schedule",
              item_name: row["Tarefa"] || row["Atividade"] || "Sem nome",
              planned_start_date: row["Início Previsto"] || row["Start"] || null,
              planned_end_date: row["Fim Previsto"] || row["End"] || null,
              actual_start_date: row["Início Real"] || null,
              actual_end_date: row["Fim Real"] || null,
              progress: row["Progresso"] || row["%"] || 0,
              category: row["Fase"] || "Geral",
            };
          }
        });

        // Insert/Update in database using upsert with our new unique constraint
        const { error } = await supabase
          .from("construction_data")
          .upsert(formattedData, { onConflict: "project_id,type,item_name,category" });

        if (error) throw error;

        toast.success(
          `Planilha de ${uploadType === "budget" ? "orçamento" : "cronograma"} processada com sucesso!`,
        );
        setIsUploadDialogOpen(false);
      } catch (error: any) {
        console.error("Upload error:", error);
        toast.error("Erro ao processar planilha: Verifique os nomes das colunas.");
      } finally {
        setUploading(false);
      }
    };

    reader.readAsArrayBuffer(file);
  };

  const filteredProjects = projects.filter((p) =>
    p.name.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  return (
    <div className="space-y-spacing-lg">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-spacing-md">
        <div>
          <h2 className="text-premium-xl font-bold">Gestão de Obras</h2>
          <p className="text-premium-sm text-muted-foreground">
            Gerencie orçamentos e cronogramas de construção.
          </p>
        </div>
        <div className="flex gap-spacing-xs">
          <div className="relative">
            <Icons.Search className="absolute left-spacing-xs top-spacing-xs h-spacing-md w-spacing-md text-muted-foreground" />
            <Input
              placeholder="Buscar obra..."
              className="pl-spacing-xl w-full sm:w-[250px]"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Button className="gap-spacing-xs" onClick={() => setIsAddProjectDialogOpen(true)}>
            <Icons.Plus className="w-spacing-md h-spacing-md" /> Nova Obra
          </Button>
        </div>
      </div>

      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-spacing-lg">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="h-spacing-4xl rounded-premium bg-muted/40 animate-pulse border border-border"
            />
          ))}
        </div>
      ) : filteredProjects.length === 0 ? (
        <Card className="border-dashed border-2 py-spacing-2xl">
          <CardContent className="flex flex-col items-center text-center space-y-spacing-md">
            <div className="w-spacing-3xl h-spacing-3xl rounded-premium bg-muted flex items-center justify-center">
              <Icons.Building2 className="w-spacing-xl h-spacing-xl text-muted-foreground" />
            </div>
            <div className="space-y-spacing-2xs">
              <p className="font-semibold">Nenhuma obra cadastrada</p>
              <p className="text-premium-sm text-muted-foreground">
                Comece criando uma nova obra paroquial.
              </p>
            </div>
            <Button onClick={() => setIsAddProjectDialogOpen(true)}>Criar Primeira Obra</Button>
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-spacing-lg">
          {filteredProjects.map((project) => (
            <Card
              key={project.id}
              className="overflow-hidden group hover:border-primary/50 transition-all"
            >
              <CardHeader className="pb-spacing-sm flex flex-row items-start justify-between">
                <div>
                  <CardTitle className="text-premium-lg">{project.name}</CardTitle>
                  <CardDescription className="line-clamp-spacing-2xs">
                    {project.description || "Sem descrição"}
                  </CardDescription>
                </div>
                <Badge variant={project.status === "concluida" ? "default" : "secondary"}>
                  {project.status === "concluida" ? "Concluída" : "Em Andamento"}
                </Badge>
              </CardHeader>
              <CardContent className="pb-spacing-sm space-y-spacing-md">
                <div className="grid grid-cols-2 gap-spacing-md">
                  <div className="p-spacing-sm rounded-premium bg-muted/50 border space-y-spacing-2xs">
                    <div className="flex items-center gap-spacing-xs text-premium-xs font-bold text-muted-foreground uppercase tracking-widest">
                      <Icons.DollarSign className="w-spacing-sm h-spacing-sm" /> Orçamento
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full h-spacing-xl gap-spacing-xs text-premium-xs font-black uppercase tracking-widest"
                      onClick={() => {
                        setSelectedProjectId(project.id);
                        setUploadType("budget");
                        setIsUploadDialogOpen(true);
                      }}
                    >
                      <Icons.Upload className="w-spacing-sm h-spacing-sm" /> Subir Planilha
                    </Button>
                  </div>
                  <div className="p-spacing-sm rounded-premium bg-muted/50 border space-y-spacing-2xs">
                    <div className="flex items-center gap-spacing-xs text-premium-xs font-bold text-muted-foreground uppercase tracking-widest">
                      <Icons.Calendar className="w-spacing-sm h-spacing-sm" /> Cronograma
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full h-spacing-xl gap-spacing-xs text-premium-xs font-black uppercase tracking-widest"
                      onClick={() => {
                        setSelectedProjectId(project.id);
                        setUploadType("schedule");
                        setIsUploadDialogOpen(true);
                      }}
                    >
                      <Icons.Upload className="w-spacing-sm h-spacing-sm" /> Subir Planilha
                    </Button>
                  </div>
                </div>
              </CardContent>
              <CardFooter className="bg-muted/10 py-spacing-sm flex justify-between">
                <span className="text-premium-xs text-muted-foreground">
                  Criada em: {new Date(project.created_at).toLocaleDateString()}
                </span>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-spacing-lg text-destructive hover:text-destructive hover:bg-destructive/10"
                  onClick={() => handleDeleteProject(project.id)}
                >
                  <Icons.Trash2 className="w-spacing-sm h-spacing-sm" />
                </Button>
              </CardFooter>
            </Card>
          ))}
        </div>
      )}

      {/* Add Project Dialog */}
      <Dialog open={isAddProjectDialogOpen} onOpenChange={setIsAddProjectDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Nova Obra</DialogTitle>
            <DialogDescription>Cadastre uma nova obra ou reforma paroquial.</DialogDescription>
          </DialogHeader>
          <div className="space-y-spacing-md py-spacing-xs">
            <div className="space-y-spacing-xs">
              <Label htmlFor="project-name">Nome da Obra</Label>
              <Input
                id="project-name"
                placeholder="Ex: Reforma do Telhado da Matriz"
                value={newProject.name}
                onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
              />
            </div>
            <div className="space-y-spacing-xs">
              <Label htmlFor="project-desc">Descrição</Label>
              <Input
                id="project-desc"
                placeholder="Breve descrição dos objetivos..."
                value={newProject.description}
                onChange={(e) => setNewProject({ ...newProject, description: e.target.value })}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsAddProjectDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleCreateProject}>Criar Obra</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Icons.Upload Dialog */}
      <Dialog open={isUploadDialogOpen} onOpenChange={setIsUploadDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              Subir Planilha de {uploadType === "budget" ? "Orçamento" : "Cronograma"}
            </DialogTitle>
            <DialogDescription>
              Selecione um arquivo .xlsx ou .csv. A planilha deve conter colunas como:
              {uploadType === "budget"
                ? ' "Item", "Previsto", "Real"'
                : ' "Tarefa", "Início Previsto", "Fim Previsto", "Progresso"'}
            </DialogDescription>
          </DialogHeader>
          <div className="flex flex-col items-center justify-center py-spacing-xl border-2 border-dashed rounded-premium gap-spacing-md bg-muted/5">
            <div className="w-spacing-2xl h-spacing-2xl rounded-premium bg-primary/10 flex items-center justify-center">
              <Icons.FileSpreadsheet className="w-spacing-lg h-spacing-lg text-primary" />
            </div>
            <div className="text-center px-spacing-md">
              <p className="text-premium-sm font-medium">
                Arraste sua planilha aqui ou clique no botão
              </p>
              <p className="text-premium-xs text-muted-foreground mt-spacing-2xs">
                Formato suportado: XLSX, XLS, CSV
              </p>
            </div>
            <div className="relative">
              <Button disabled={uploading} className="relative z-10">
                {uploading ? (
                  <Icons.Loader2 className="w-spacing-md h-spacing-md animate-spin mr-spacing-xs" />
                ) : (
                  <Icons.Upload className="w-spacing-md h-spacing-md mr-spacing-xs" />
                )}
                Selecionar Arquivo
              </Button>
              <input
                type="file"
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
                accept=".xlsx, .xls, .csv"
                onChange={handleFileUpload}
                disabled={uploading}
              />
            </div>
          </div>
          <div className="bg-amber-500/10 border border-amber-500/20 rounded-premium p-spacing-sm flex gap-spacing-sm">
            <Icons.AlertCircle className="w-spacing-md h-spacing-md text-amber-500 shrink-0" />
            <div className="text-premium-xs text-amber-800">
              <p className="font-bold">Atenção!</p>
              <p>
                Ao subir uma nova planilha, os dados serão adicionados aos já existentes. Para
                atualizar um dado real, certifique-se que o nome do item é idêntico.
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsUploadDialogOpen(false)}>
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default AdminConstructionTab;

import { Icons } from "@/constants";
import React, { useState, useEffect, Suspense, lazy } from "react";
import { supabase } from "@/lib/db";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { BIBLE_DATA } from "@/data/bible-books";

const CatechismDebug = lazy(() => import("./CatechismDebug"));
const BibleKnowledgeAudit = lazy(() =>
  import("./BibleKnowledgeAudit").then((m) => ({ default: m.BibleKnowledgeAudit })),
);

interface Post {
  id: string;
  title: string | null;
  content: string;
  status: "pending" | "approved" | "rejected";
  user_id: string;
  created_at: string;
  category: string | null;
  profiles?: {
    name: string | null;
  };
}

const AdminContentTab: React.FC = () => {
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState("pending");

  const auditData = React.useMemo(() => {
    const allBooks = Object.values(BIBLE_DATA)
      .flat()
      .flatMap((cat) => cat.books);
    // Em produção estes dados viriam de uma consulta real de cobertura
    return {
      totalBooks: allBooks.length,
      coveredBooks: allBooks.length - 8,
      emptyBooks: [
        "Tobias",
        "Judite",
        "Ester",
        "1 Macabeus",
        "2 Macabeus",
        "Sabedoria",
        "Eclesiástico",
        "Baruc",
      ],
      totalChapters: allBooks.reduce((acc, b) => acc + b.chapters, 0),
      themesCount: 42,
      theologicalThemes: [],
    };
  }, []);

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("community_posts")
        .select("*, profiles(name)")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setPosts((data as any[]) || []);
    } catch (error: any) {
      toast.error("Erro ao buscar conteúdos: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (id: string, newStatus: "approved" | "rejected" | "pending") => {
    try {
      const { error } = await supabase
        .from("community_posts")
        .update({ status: newStatus })
        .eq("id", id);

      if (error) throw error;

      setPosts((prev) => prev.map((p) => (p.id === id ? { ...p, status: newStatus } : p)));
      toast.success(
        `Conteúdo ${newStatus === "approved" ? "aprovado" : newStatus === "rejected" ? "rejeitado" : "marcado como pendente"} com sucesso.`,
      );
    } catch (error: any) {
      toast.error("Erro ao atualizar conteúdo: " + error.message);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este conteúdo permanentemente?")) return;

    try {
      const { error } = await supabase.from("community_posts").delete().eq("id", id);

      if (error) throw error;

      setPosts((prev) => prev.filter((p) => p.id !== id));
      toast.success("Conteúdo excluído com sucesso.");
    } catch (error: any) {
      toast.error("Erro ao excluir conteúdo: " + error.message);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "approved":
        return (
          <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 gap-spacing-2xs">
            <Icons.CheckCircle2 className="w-spacing-sm h-spacing-sm" /> Aprovado
          </Badge>
        );
      case "rejected":
        return (
          <Badge variant="destructive" className="gap-spacing-2xs">
            <Icons.XCircle className="w-spacing-sm h-spacing-sm" /> Rejeitado
          </Badge>
        );
      default:
        return (
          <Badge
            variant="secondary"
            className="gap-spacing-2xs bg-amber-500/10 text-amber-500 border-amber-500/20"
          >
            <Icons.Clock className="w-spacing-sm h-spacing-sm" /> Pendente
          </Badge>
        );
    }
  };

  const filteredPosts = posts.filter(
    (p) =>
      (p.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.title?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.profiles?.name?.toLowerCase().includes(searchQuery.toLowerCase())) &&
      (activeTab === "all" || p.status === activeTab),
  );

  const pendingCount = posts.filter((p) => p.status === "pending").length;

  if (loading) {
    return (
      <div className="space-y-spacing-md">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="h-spacing-4xl bg-muted/40 animate-pulse" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-spacing-lg">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-spacing-md">
        <div>
          <h2 className="text-premium-xl font-bold">Gestão de Conteúdo</h2>
          <p className="text-premium-sm text-muted-foreground">Modere postagens da comunidade.</p>
        </div>
        <div className="relative">
          <Icons.Search className="absolute left-spacing-xs top-spacing-xs h-spacing-md w-spacing-md text-muted-foreground" />
          <Input
            placeholder="Buscar conteúdo ou autor..."
            className="pl-spacing-xl w-full sm:w-[300px]"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-spacing-lg">
        <TabsList>
          <TabsTrigger value="pending" className="gap-spacing-xs">
            Pendentes
            {pendingCount > 0 && (
              <span className="bg-primary text-primary-foreground px-spacing-2xs py-spacing-3xs rounded-premium-full text-premium-xs font-bold">
                {pendingCount}
              </span>
            )}
          </TabsTrigger>
          <TabsTrigger value="approved">Aprovados</TabsTrigger>
          <TabsTrigger value="rejected">Rejeitados</TabsTrigger>
          <TabsTrigger value="all">Todos</TabsTrigger>
          <TabsTrigger value="catechism">Depuração CIC</TabsTrigger>
          <TabsTrigger value="bible-audit">Auditoria Bíblica</TabsTrigger>
        </TabsList>

        <TabsContent
          value="bible-audit"
          className="relative h-[800px] overflow-hidden rounded-premium border border-primary/5"
        >
          <Suspense fallback={<Card className="h-full animate-pulse" />}>
            <BibleKnowledgeAudit onClose={() => setActiveTab("pending")} auditData={auditData} />
          </Suspense>
        </TabsContent>

        <TabsContent
          value={activeTab === "bible-audit" ? "none" : activeTab}
          className="space-y-spacing-md"
        >
          {filteredPosts.length === 0 ? (
            <Card className="border-dashed border-2 py-spacing-2xl text-center">
              <Icons.MessageSquare className="w-spacing-2xl h-spacing-2xl text-muted-foreground mx-auto mb-spacing-md opacity-20" />
              <p className="font-medium">Nenhum conteúdo encontrado</p>
            </Card>
          ) : (
            filteredPosts.map((post) => (
              <Card key={post.id} className="overflow-hidden shadow-premium-none border-border/40">
                <CardHeader className="flex flex-row items-center justify-between pb-spacing-2xs pt-spacing-sm px-spacing-sm">
                  <div className="flex items-center gap-spacing-xs">
                    <Icons.User className="w-spacing-sm h-spacing-sm text-muted-foreground" />
                    <span className="text-premium-xs font-bold">
                      {post.profiles?.name || "Usuário"}
                    </span>
                    <span className="text-premium-xs text-muted-foreground">
                      • {new Date(post.created_at).toLocaleDateString("pt-BR")}
                    </span>
                    {post.category && (
                      <Badge
                        variant="outline"
                        className="text-premium-xs uppercase h-spacing-md px-spacing-2xs"
                      >
                        {post.category}
                      </Badge>
                    )}
                  </div>
                  <div className="scale-90 origin-right">{getStatusBadge(post.status)}</div>
                </CardHeader>
                <CardContent className="px-spacing-sm pb-spacing-xs pt-spacing-2xs">
                  {post.title && (
                    <h3 className="text-premium-sm font-bold mb-spacing-3xs">{post.title}</h3>
                  )}
                  <p className="text-premium-xs text-muted-foreground whitespace-pre-wrap line-clamp-spacing-sm">
                    {post.content}
                  </p>
                </CardContent>
                <CardFooter className="bg-muted/10 border-t border-border/10 py-spacing-2xs px-spacing-sm flex justify-end gap-spacing-2xs">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => handleDelete(post.id)}
                    className="text-destructive h-spacing-lg text-premium-xs font-bold uppercase tracking-widest px-spacing-xs"
                  >
