        .from("journeys")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setJourneys(data || []);
    } catch (error: any) {
      toast.error("Erro ao buscar jornadas: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchSteps = async (journeyId: string) => {
    try {
      setStepsLoading(true);
      const { data, error } = await supabase
        .from("journey_steps")
        .select("*")
        .eq("journey_id", journeyId)
        .order("step_order", { ascending: true });

      if (error) throw error;
      setSteps(data || []);
    } catch (error: any) {
      toast.error("Erro ao buscar passos: " + error.message);
    } finally {
      setStepsLoading(false);
    }
  };

  const toggleJourneySteps = (journeyId: string) => {
    if (selectedJourneyId === journeyId) {
      setSelectedJourneyId(null);
      setSteps([]);
    } else {
      setSelectedJourneyId(journeyId);
      fetchSteps(journeyId);
    }
  };

  const handleEditStep = (step: Step) => {
    setEditingStep(step);
    setStepContentString(JSON.stringify(step.content, null, 2));
    setIsEditStepDialogOpen(true);
  };

  const handleSaveStep = async () => {
    if (!editingStep) return;

    try {
      console.log(`Saving step: ${editingStep.title} (${editingStep.id})`);
      let parsedContent = editingStep.content;
      try {
        parsedContent =
          typeof stepContentString === "string" ? JSON.parse(stepContentString) : stepContentString;
      } catch (e) {
        console.error("Invalid JSON in step content:", e);
        toast.error("JSON inválido no conteúdo do passo. Verifique a sintaxe.");
        return;
      }

      const { error } = await supabase
        .from("journey_steps")
        .update({
          title: editingStep.title,
          subtitle: editingStep.subtitle,
          step_order: editingStep.step_order,
          step_type: editingStep.step_type,
          content: parsedContent,
        })
        .eq("id", editingStep.id);

      if (error) {
        console.error("Error saving step:", error);
        toast.error(`Falha ao salvar o passo: ${error.message}`);
        throw error;
      }

      setSteps((prev) =>
        prev.map((s) => (s.id === editingStep.id ? { ...editingStep, content: parsedContent } : s)),
      );
      toast.success(`Passo "${editingStep.title}" atualizado.`);
      setIsEditStepDialogOpen(false);
    } catch (error: any) {
      console.error("Critical error saving step:", error);
      toast.error("Erro ao salvar passo: " + (error.message || "Falha na rede"));
    }
  };

  const handleDeleteStep = async (stepId: string) => {
    if (!window.confirm("Tem certeza que deseja excluir este passo?")) return;

    try {
      console.log(`Deleting step: ${stepId}`);
      const { error } = await supabase.from("journey_steps").delete().eq("id", stepId);

      if (error) {
        console.error("Error deleting step:", error);
        throw error;
      }

      setSteps((prev) => prev.filter((s) => s.id !== stepId));
      toast.success("Passo removido com sucesso.");
    } catch (error: any) {
      console.error("Step deletion error:", error);
      toast.error("Erro ao excluir passo: " + (error.message || "Erro no servidor"));
    }
  };

  const handleSaveJourney = async () => {
    if (!editingJourney) return;

    try {
      console.log(`Updating journey: ${editingJourney.title} (${editingJourney.id})`);
      const { error } = await supabase
        .from("journeys")
        .update({
          title: editingJourney.title,
          subtitle: editingJourney.subtitle,
          description: editingJourney.description,
          category: editingJourney.category,
          difficulty: editingJourney.difficulty,
          is_active: editingJourney.is_active,
          is_premium: editingJourney.is_premium,
          estimated_days: editingJourney.estimated_days,
        })
        .eq("id", editingJourney.id);

      if (error) {
        console.error("Error updating journey:", error);
        throw error;
      }

      setJourneys((prev) => prev.map((j) => (j.id === editingJourney.id ? editingJourney : j)));
      toast.success("Jornada atualizada com sucesso.");
      setIsEditDialogOpen(false);
    } catch (error: any) {
      console.error("Save journey error:", error);
      toast.error("Erro ao salvar jornada: " + (error.message || "Falha na conexão"));
    }
  };

  const initiateDeleteJourney = async (journey: Journey) => {
    try {
      // Fetch step count for confirmation modal
      const { count, error } = await supabase
        .from("journey_steps")
        .select("*", { count: "exact", head: true })
        .eq("journey_id", journey.id);

      if (error) throw error;

      setStepsToDeleteCount(count || 0);
      setJourneyToDelete(journey);
      setIsDeleteDialogOpen(true);
    } catch (error: any) {
      console.error("Error fetching step count for deletion:", error);
      toast.error("Erro ao preparar exclusão: " + error.message);
    }
  };

  const confirmDeleteJourney = async () => {
    if (!journeyToDelete) return;

    setIsDeleting(true);
    try {
      console.log(`Attempting to delete journey: ${journeyToDelete.title} (${journeyToDelete.id})`);

      const { error } = await supabase.from("journeys").delete().eq("id", journeyToDelete.id);

      if (error) {
        console.error("Database error during journey deletion:", error);
        throw error;
      }

      setJourneys((prev) => prev.filter((j) => j.id !== journeyToDelete.id));
      if (selectedJourneyId === journeyToDelete.id) {
        setSelectedJourneyId(null);
        setSteps([]);
      }

      toast.success(
        `Jornada "${journeyToDelete.title}" e seus ${stepsToDeleteCount} passos foram excluídos com sucesso.`,
      );
      setIsDeleteDialogOpen(false);
      setJourneyToDelete(null);
    } catch (error: any) {
      console.error("Critical error deleting journey:", error);
      toast.error("Erro ao excluir jornada: " + (error.message || "Erro desconhecido"));
    } finally {
      setIsDeleting(false);
    }
  };

  const handleCreateJourney = async () => {
    try {
      console.log("Creating new journey:", newJourney.title);
      const { data, error } = await supabase
        .from("journeys")
        .insert([newJourney])
        .select()
        .single();

      if (error) {
        console.error("Error creating journey:", error);
        toast.error(`Falha ao criar jornada: ${error.message}`);
        throw error;
      }

      setJourneys([data, ...journeys]);
      toast.success(`Jornada "${newJourney.title}" criada com sucesso.`);
      setIsAddJourneyDialogOpen(false);
      setNewJourney({
        title: "",
        subtitle: "",
        description: "",
        category: "Formação",
        difficulty: "Iniciante",
        is_active: true,
        is_premium: false,
        estimated_days: 7,
      });
    } catch (error: any) {
      console.error("Create journey error:", error);
      toast.error("Erro ao criar jornada: " + (error.message || "Erro inesperado"));
    }
  };

  const handleCreateStep = async (journeyId: string) => {
    try {
      const nextOrder = steps.length > 0 ? Math.max(...steps.map((s) => s.step_order)) + 1 : 1;
      const newStep = {
        journey_id: journeyId,
        title: "Novo Passo",
        step_order: nextOrder,
        step_type: "reflexão",
        content: { intro: "", reflection: "", practice: "", prayer: "" },
      };

      const { data, error } = await supabase
        .from("journey_steps")
        .insert([newStep])
        .select()
        .single();

      if (error) throw error;

      setSteps([...steps, data]);
      handleEditStep(data);
      toast.success("Passo adicionado.");
    } catch (error: any) {
      toast.error("Erro ao adicionar passo: " + error.message);
    }
  };

  const filteredJourneys = journeys.filter(
    (j) =>
      j.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      j.category?.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  if (loading) {
    return (
      <div className="space-y-spacing-md animate-pulse">
        {[1, 2, 3].map((i) => (
          <div key={i} className="h-spacing-3xl bg-muted/40 rounded-premium" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-spacing-lg">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-spacing-md">
        <div>
          <h2 className="text-premium-xl font-bold">Gestão de Jornadas</h2>
          <p className="text-premium-sm text-muted-foreground">
            Crie e edite trilhas de crescimento espiritual.
          </p>
        </div>
        <div className="flex gap-spacing-xs">
          <div className="relative">
            <Icons.Search className="absolute left-spacing-xs top-spacing-xs h-spacing-md w-spacing-md text-muted-foreground" />
            <Input
              placeholder="Buscar jornada..."
              className="pl-spacing-xl w-full sm:w-[250px]"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <Button className="gap-spacing-xs" onClick={() => setIsAddJourneyDialogOpen(true)}>
            <Icons.Plus className="w-spacing-md h-spacing-md" /> Nova Jornada
          </Button>
        </div>
      </div>

      <div className="grid gap-spacing-md">
        {filteredJourneys.map((journey) => (
          <div key={journey.id} className="border rounded-premium overflow-hidden bg-card">
            <div className="p-spacing-md flex items-center justify-between">
              <div
                className="flex items-center gap-spacing-sm cursor-pointer flex-1"
                onClick={() => toggleJourneySteps(journey.id)}
              >
                {selectedJourneyId === journey.id ? (
                  <Icons.ChevronDown className="w-spacing-md h-spacing-md text-muted-foreground" />
                ) : (
                  <Icons.ChevronRight className="w-spacing-md h-spacing-md text-muted-foreground" />
                )}
                <div className="w-spacing-xl h-spacing-xl rounded-premium bg-primary/10 flex items-center justify-center">
                  <Icons.Map className="w-spacing-md h-spacing-md text-primary" />
                </div>
                <div>
                  <h3 className="font-bold flex items-center gap-spacing-xs">
                    {journey.title}
                    {journey.is_premium && (
                      <Badge
                        variant="secondary"
                        className="text-premium-xs bg-amber-500/10 text-amber-500 border-amber-500/20"
                      >
                        PRO
                      </Badge>
                    )}
                    {!journey.is_active && (
                      <Badge variant="outline" className="text-premium-xs">
                        Inativa
                      </Badge>
                    )}
                  </h3>
                  <p className="text-premium-xs text-muted-foreground">
                    {journey.category} • {journey.estimated_days} dias
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-spacing-xs">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => {
                    setEditingJourney({ ...journey });
                    setIsEditDialogOpen(true);
                  }}
                >
                  <Icons.Edit className="w-spacing-md h-spacing-md" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="text-destructive hover:bg-destructive/10"
                  onClick={(e) => {
                    e.stopPropagation();
                    initiateDeleteJourney(journey);
                  }}
                >
                  <Icons.Trash2 className="w-spacing-md h-spacing-md" />
                </Button>
              </div>
            </div>

            {selectedJourneyId === journey.id && (
              <div className="bg-muted/30 border-t p-spacing-md space-y-spacing-sm">
                <div className="flex items-center justify-between mb-spacing-xs">
                  <h4 className="text-premium-sm font-semibold flex items-center gap-spacing-xs">
                    <Icons.Layers className="w-spacing-md h-spacing-md" /> Passos da Jornada
                  </h4>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-spacing-xl text-premium-xs gap-spacing-2xs"
                    onClick={() => handleCreateStep(journey.id)}
                  >
                    <Icons.Plus className="w-spacing-sm h-spacing-sm" /> Adicionar Passo
                  </Button>
                </div>
                {stepsLoading ? (
                  <div className="space-y-spacing-xs">
                    {[1, 2].map((i) => (
                      <div key={i} className="h-spacing-xl bg-muted animate-pulse rounded" />
                    ))}
                  </div>
                ) : steps.length === 0 ? (
                  <p className="text-premium-sm text-muted-foreground italic text-center py-spacing-md">
                    Nenhum passo cadastrado nesta jornada.
                  </p>
                ) : (
                  <div className="space-y-spacing-xs">
                    {steps.map((step) => (
                      <div
                        key={step.id}
                        className="flex items-center justify-between bg-card p-spacing-sm rounded-premium border text-premium-sm group"
                      >
                        <div className="flex items-center gap-spacing-sm">
                          <span className="w-spacing-lg h-spacing-lg rounded bg-muted flex items-center justify-center font-bold text-premium-xs">
                            {step.step_order}
                          </span>
                          <div>
                            <p className="font-medium">{step.title}</p>
                            <p className="text-premium-xs text-muted-foreground">
                              {step.step_type}
                            </p>
                          </div>
                        </div>
                        <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-spacing-lg w-spacing-lg"
                            onClick={() => handleEditStep(step)}
                          >
                            <Icons.Edit className="w-spacing-sm h-spacing-sm" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-spacing-lg w-spacing-lg text-destructive"
                            onClick={() => handleDeleteStep(step.id)}
                          >
                            <Icons.Trash2 className="w-spacing-sm h-spacing-sm" />
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>

      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="w-full">
          <DialogHeader>
            <DialogTitle>Editar Jornada</DialogTitle>
          </DialogHeader>
          {editingJourney && (
            <div className="grid gap-spacing-md py-spacing-md">
              <div className="grid grid-cols-2 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label>Título</Label>
                  <Input
                    value={editingJourney.title}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, title: e.target.value })
                    }
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label>Subtítulo</Label>
                  <Input
                    value={editingJourney.subtitle || ""}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, subtitle: e.target.value })
                    }
                  />
                </div>
              </div>
              <div className="space-y-spacing-xs">
                <Label>Descrição</Label>
                <Textarea
                  value={editingJourney.description || ""}
                  onChange={(e) =>
                    setEditingJourney({ ...editingJourney, description: e.target.value })
                  }
                />
              </div>
              <div className="grid grid-cols-3 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label>Categoria</Label>
                  <Input
                    value={editingJourney.category || ""}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, category: e.target.value })
                    }
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label>Dificuldade</Label>
                  <Input
                    value={editingJourney.difficulty || ""}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, difficulty: e.target.value })
                    }
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label>Dias Estimados</Label>
                  <Input
                    type="number"
                    value={editingJourney.estimated_days || 0}
                    onChange={(e) =>
                      setEditingJourney({
                        ...editingJourney,
                        estimated_days: parseInt(e.target.value),
                      })
                    }
                  />
                </div>
              </div>
              <div className="flex gap-spacing-md">
                <label className="flex items-center gap-spacing-xs cursor-pointer">
                  <input
                    type="checkbox"
                    checked={editingJourney.is_active}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, is_active: e.target.checked })
                    }
                    className="rounded border-gray-300"
                  />
                  <span className="text-premium-sm">Ativa</span>
                </label>
                <label className="flex items-center gap-spacing-xs cursor-pointer">
                  <input
                    type="checkbox"
                    checked={editingJourney.is_premium}
                    onChange={(e) =>
                      setEditingJourney({ ...editingJourney, is_premium: e.target.checked })
                    }
                    className="rounded border-gray-300"
                  />
                  <span className="text-premium-sm">Premium (PRO)</span>
                </label>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSaveJourney} className="gap-spacing-xs">
              <Icons.Save className="w-spacing-md h-spacing-md" /> Salvar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isEditStepDialogOpen} onOpenChange={setIsEditStepDialogOpen}>
        <DialogContent className="w-full max-h-[90vh] flex flex-col">
          <DialogHeader>
            <DialogTitle>Editar Passo da Jornada</DialogTitle>
          </DialogHeader>
          {editingStep && (
            <div className="flex-1 overflow-y-auto pr-spacing-xs space-y-spacing-md py-spacing-md">
              <div className="grid grid-cols-2 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label>Título</Label>
                  <Input
                    value={editingStep.title}
                    onChange={(e) => setEditingStep({ ...editingStep, title: e.target.value })}
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label>Subtítulo</Label>
                  <Input
                    value={editingStep.subtitle || ""}
                    onChange={(e) => setEditingStep({ ...editingStep, subtitle: e.target.value })}
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label>Tipo de Passo</Label>
                  <Input
                    value={editingStep.step_type}
                    onChange={(e) => setEditingStep({ ...editingStep, step_type: e.target.value })}
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label>Ordem</Label>
                  <Input
                    type="number"
                    value={editingStep.step_order}
                    onChange={(e) =>
                      setEditingStep({ ...editingStep, step_order: parseInt(e.target.value) })
                    }
                  />
                </div>
              </div>
              <div className="space-y-spacing-xs">
                <Label>Conteúdo (JSON)</Label>
                <div className="relative group">
                  <Textarea
                    className="font-mono text-premium-xs h-[300px]"
                    value={stepContentString}
                    onChange={(e) => setStepContentString(e.target.value)}
                  />
                  <div className="absolute right-spacing-xs top-spacing-xs opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-spacing-lg text-premium-xs uppercase tracking-tighter"
                      onClick={() => {
                        try {
                          const parsed = JSON.parse(stepContentString);
                          setStepContentString(JSON.stringify(parsed, null, 2));
                          toast.success("JSON formatado.");
                        } catch (e) {
                          toast.error("Erro ao formatar JSON.");
                        }
                      }}
                    >
                      Formatar
                    </Button>
                  </div>
                </div>
                <p className="text-premium-xs text-muted-foreground italic">
                  Dica: use chaves como 'intro', 'reflection', 'practice', 'prayer' para que o
                  conteúdo apareça no app.
                </p>
              </div>
            </div>
          )}
          <DialogFooter className="pt-spacing-md border-t">
            <Button variant="outline" onClick={() => setIsEditStepDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSaveStep} className="gap-spacing-xs">
              <Icons.Save className="w-spacing-md h-spacing-md" /> Salvar Passo
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isAddJourneyDialogOpen} onOpenChange={setIsAddJourneyDialogOpen}>
        <DialogContent className="w-full">
          <DialogHeader>
            <DialogTitle>Nova Jornada</DialogTitle>
            <DialogDescription>Crie uma nova trilha espiritual para os usuários.</DialogDescription>
          </DialogHeader>
          <div className="grid gap-spacing-md py-spacing-md">
            <div className="grid grid-cols-2 gap-spacing-md">
              <div className="space-y-spacing-xs">
                <Label>Título</Label>
                <Input
                  placeholder="Ex: Caminho de Santidade"
                  value={newJourney.title}
                  onChange={(e) => setNewJourney({ ...newJourney, title: e.target.value })}
                />
              </div>
              <div className="space-y-spacing-xs">
                <Label>Subtítulo</Label>
                <Input
                  placeholder="Ex: 7 dias de reflexão"
                  value={newJourney.subtitle}
                  onChange={(e) => setNewJourney({ ...newJourney, subtitle: e.target.value })}
                />
              </div>
            </div>
            <div className="space-y-spacing-xs">
              <Label>Descrição</Label>
              <Textarea
                placeholder="Descreva o propósito desta jornada..."
                value={newJourney.description}
                onChange={(e) => setNewJourney({ ...newJourney, description: e.target.value })}
              />
            </div>
            <div className="grid grid-cols-3 gap-spacing-md">
              <div className="space-y-spacing-xs">
                <Label>Categoria</Label>
                <Input
                  value={newJourney.category}
                  onChange={(e) => setNewJourney({ ...newJourney, category: e.target.value })}
                />
              </div>
              <div className="space-y-spacing-xs">
                <Label>Dificuldade</Label>
                <Input
                  value={newJourney.difficulty}
                  onChange={(e) => setNewJourney({ ...newJourney, difficulty: e.target.value })}
                />
              </div>
              <div className="space-y-spacing-xs">
                <Label>Dias Estimados</Label>
                <Input
                  type="number"
                  value={newJourney.estimated_days}
                  onChange={(e) =>
                    setNewJourney({ ...newJourney, estimated_days: parseInt(e.target.value) })
                  }
                />
              </div>
            </div>
            <div className="flex gap-spacing-md">
              <label className="flex items-center gap-spacing-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={newJourney.is_active}
                  onChange={(e) => setNewJourney({ ...newJourney, is_active: e.target.checked })}
                  className="rounded border-gray-300"
                />
                <span className="text-premium-sm font-medium">Ativa</span>
              </label>
              <label className="flex items-center gap-spacing-xs cursor-pointer">
                <input
                  type="checkbox"
                  checked={newJourney.is_premium}
                  onChange={(e) => setNewJourney({ ...newJourney, is_premium: e.target.checked })}
                  className="rounded border-gray-300"
                />
                <span className="text-premium-sm font-medium">Premium (PRO)</span>
              </label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsAddJourneyDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleCreateJourney} disabled={!newJourney.title}>
              Criar Jornada
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-spacing-xs text-destructive">
              <Icons.AlertTriangle className="w-spacing-md h-spacing-md" /> Confirmar Exclusão
            </AlertDialogTitle>
            <AlertDialogDescription>
              Você está prestes a excluir a jornada{" "}
              <strong className="text-foreground">"{journeyToDelete?.title}"</strong>.
              <br />
              <br />
              Esta ação removerá permanentemente a jornada e{" "}
              <strong className="text-destructive font-bold">
                {stepsToDeleteCount} passos
              </strong>{" "}
              associados. Esta ação não pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => {
                e.preventDefault();
                confirmDeleteJourney();
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              disabled={isDeleting}
            >
              {isDeleting ? "Excluindo..." : "Sim, Excluir Tudo"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default AdminJourneysTab;

import { Icons } from "@/constants";
import React, { useState, useEffect } from "react";
import { supabase } from "@/lib/db";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

import { toast } from "sonner";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface Partner {
  id: string;
  name: string;
  description: string | null;
  logo_url: string | null;
  website_url: string | null;
  status: "pending" | "approved" | "rejected";
  contact_email: string | null;
  created_at: string;
}

const AdminPartnersTab: React.FC = () => {
  const [partners, setPartners] = useState<Partner[]>([]);
  const [loading, setLoading] = useState(true);
  const [editingPartner, setEditingPartner] = useState<Partner | null>(null);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState("pending");

  useEffect(() => {
    fetchPartners();
  }, []);

  const fetchPartners = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("partners")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;
      setPartners((data as Partner[]) || []);
    } catch (error: any) {
      toast.error("Erro ao buscar parceiros: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateStatus = async (id: string, newStatus: "approved" | "rejected") => {
    try {
      const { error } = await supabase.from("partners").update({ status: newStatus }).eq("id", id);

      if (error) throw error;

      setPartners((prev) => prev.map((p) => (p.id === id ? { ...p, status: newStatus } : p)));
      toast.success(`Parceiro ${newStatus === "approved" ? "aprovado" : "rejeitado"} com sucesso.`);
    } catch (error: any) {
      toast.error("Erro ao atualizar parceiro: " + error.message);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir este parceiro permanentemente?")) return;

    try {
      const { error } = await supabase.from("partners").delete().eq("id", id);

      if (error) throw error;

      setPartners((prev) => prev.filter((p) => p.id !== id));
      toast.success("Parceiro excluído com sucesso.");
    } catch (error: any) {
      toast.error("Erro ao excluir parceiro: " + error.message);
    }
  };

  const handleSaveEdit = async () => {
    if (!editingPartner) return;

    try {
      const { error } = await supabase
        .from("partners")
        .update({
          name: editingPartner.name,
          description: editingPartner.description,
          logo_url: editingPartner.logo_url,
          website_url: editingPartner.website_url,
          contact_email: editingPartner.contact_email,
          status: editingPartner.status,
        })
        .eq("id", editingPartner.id);

      if (error) throw error;

      setPartners((prev) => prev.map((p) => (p.id === editingPartner.id ? editingPartner : p)));
      toast.success("Dados do parceiro atualizados.");
      setIsEditDialogOpen(false);
      setEditingPartner(null);
    } catch (error: any) {
      toast.error("Erro ao salvar alterações: " + error.message);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "approved":
        return (
          <Badge className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 gap-spacing-2xs">
            <Icons.CheckCircle2 className="w-spacing-sm h-spacing-sm" /> Aprovado
          </Badge>
        );
      case "rejected":
        return (
          <Badge variant="destructive" className="gap-spacing-2xs">
            <Icons.XCircle className="w-spacing-sm h-spacing-sm" /> Rejeitado
          </Badge>
        );
      default:
        return (
          <Badge
            variant="secondary"
            className="gap-spacing-2xs bg-amber-500/10 text-amber-500 border-amber-500/20"
          >
            <Icons.Clock className="w-spacing-sm h-spacing-sm" /> Pendente
          </Badge>
        );
    }
  };

  const filteredPartners = partners.filter(
    (p) =>
      (p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.contact_email?.toLowerCase().includes(searchQuery.toLowerCase())) &&
      (activeTab === "all" || p.status === activeTab),
  );

  const pendingCount = partners.filter((p) => p.status === "pending").length;

  if (loading) {
    return (
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-spacing-lg">
        {[1, 2, 3].map((i) => (
          <div
            key={i}
            className="h-spacing-4xl rounded-premium bg-muted/40 animate-pulse border border-border"
          />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-spacing-lg">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-spacing-md">
        <div>
          <h2 className="text-premium-xl font-bold">Gestão de Parceiros</h2>
          <p className="text-premium-sm text-muted-foreground">
            Analise solicitações e gerencie instituições parceiras.
          </p>
        </div>
        <div className="flex items-center gap-spacing-xs">
          <div className="relative">
            <Icons.Search className="absolute left-spacing-xs top-spacing-xs h-spacing-md w-spacing-md text-muted-foreground" />
            <Input
              placeholder="Buscar parceiro..."
              className="pl-spacing-xl w-[200px] sm:w-[300px]"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-spacing-lg">
        <TabsList>
          <TabsTrigger value="pending" className="gap-spacing-xs">
            Solicitações
            {pendingCount > 0 && (
              <span className="bg-primary text-primary-foreground px-spacing-2xs py-spacing-3xs rounded-premium-full text-premium-xs font-bold">
                {pendingCount}
              </span>
            )}
          </TabsTrigger>
          <TabsTrigger value="approved">Aprovados</TabsTrigger>
          <TabsTrigger value="rejected">Rejeitados</TabsTrigger>
          <TabsTrigger value="all">Todos</TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab} className="mt-spacing-0">
          {filteredPartners.length === 0 ? (
            <Card className="border-dashed border-2 py-spacing-2xl">
              <CardContent className="flex flex-col items-center text-center space-y-spacing-md">
                <div className="w-spacing-3xl h-spacing-3xl rounded-premium bg-muted flex items-center justify-center">
                  <Icons.Building2 className="w-spacing-xl h-spacing-xl text-muted-foreground" />
                </div>
                <div className="space-y-spacing-2xs">
                  <p className="font-semibold">Nenhum parceiro nesta categoria</p>
                  <p className="text-premium-sm text-muted-foreground">
                    Use a busca ou mude o filtro para encontrar parceiros.
                  </p>
                </div>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-spacing-md">
              {filteredPartners.map((partner) => (
                <Card
                  key={partner.id}
                  className="group hover:border-primary/30 transition-all bg-card "
                >
                  <CardHeader className="flex flex-row items-start justify-between pb-spacing-sm">
                    <div className="flex items-center gap-spacing-md">
                      <div className="w-spacing-2xl h-spacing-2xl rounded-premium bg-white flex items-center justify-center overflow-hidden border p-spacing-2xs shadow-premium-md">
                        {partner.logo_url ? (
                          <img
                            src={partner.logo_url}
                            alt={partner.name}
                            className="w-full h-full object-contain"
                          />
                        ) : (
                          <Icons.Building2 className="w-spacing-lg h-spacing-lg text-muted-foreground" />
                        )}
                      </div>
                      <div>
                        <CardTitle className="text-premium-lg flex items-center gap-spacing-xs">
                          {partner.name}
                          {getStatusBadge(partner.status)}
                        </CardTitle>
                        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-premium-sm text-muted-foreground mt-spacing-2xs">
                          <span className="flex items-center gap-spacing-2xs">
                            <Icons.Mail className="w-spacing-sm h-spacing-sm" />{" "}
                            {partner.contact_email}
                          </span>
                          <span className="flex items-center gap-spacing-2xs">
                            <Icons.Clock className="w-spacing-sm h-spacing-sm" />{" "}
                            {new Date(partner.created_at).toLocaleDateString("pt-BR")}
                          </span>
                        </div>
                      </div>
                    </div>

                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-spacing-xl w-spacing-xl">
                          <Icons.MoreHorizontal className="w-spacing-md h-spacing-md" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={() => {
                            setEditingPartner({ ...partner });
                            setIsEditDialogOpen(true);
                          }}
                        >
                          <Icons.Edit className="w-spacing-md h-spacing-md mr-spacing-xs" /> Editar
                          Detalhes
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={() => handleUpdateStatus(partner.id, "approved")}
                          className="text-emerald-500"
                        >
                          <Icons.CheckCircle2 className="w-spacing-md h-spacing-md mr-spacing-xs" />{" "}
                          Aprovar
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => handleUpdateStatus(partner.id, "rejected")}
                          className="text-destructive"
                        >
                          <Icons.XCircle className="w-spacing-md h-spacing-md mr-spacing-xs" />{" "}
                          Rejeitar
                        </DropdownMenuItem>
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={() => handleDelete(partner.id)}
                          className="text-destructive"
                        >
                          <Icons.Trash2 className="w-spacing-md h-spacing-md mr-spacing-xs" />{" "}
                          Excluir permanentemente
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </CardHeader>

                  <CardContent className="pb-spacing-md">
                    <p className="text-premium-sm text-muted-foreground line-clamp-spacing-xs italic">
                      "{partner.description || "Nenhuma descrição fornecida."}"
                    </p>
                  </CardContent>

                  <CardFooter className="pt-spacing-0 flex items-center justify-between border-t border-border/50 mt-spacing-xs py-spacing-sm bg-muted/5">
                    <div className="flex items-center gap-spacing-xs">
                      {partner.website_url && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-spacing-xl gap-spacing-2xs text-premium-xs text-primary hover:text-primary hover:bg-primary/10"
                          asChild
                        >
                          <a href={partner.website_url} target="_blank" rel="noopener noreferrer">
                            Site <Icons.ExternalLink className="w-spacing-sm h-spacing-sm" />
                          </a>
                        </Button>
                      )}
                    </div>

                    <div className="flex items-center gap-spacing-xs">
                      {partner.status === "pending" && (
                        <>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-spacing-xl text-destructive hover:bg-destructive/10 hover:text-destructive gap-spacing-2xs"
                            onClick={() => handleUpdateStatus(partner.id, "rejected")}
                          >
                            <Icons.X className="w-spacing-md h-spacing-md" /> Rejeitar
                          </Button>
                          <Button
                            size="sm"
                            className="h-spacing-xl bg-emerald-500 hover:bg-emerald-600 text-white gap-spacing-2xs"
                            onClick={() => handleUpdateStatus(partner.id, "approved")}
                          >
                            <Icons.Check className="w-spacing-md h-spacing-md" /> Aprovar
                          </Button>
                        </>
                      )}
                      {partner.status !== "pending" && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-spacing-xl gap-spacing-2xs"
                          onClick={() => {
                            setEditingPartner({ ...partner });
                            setIsEditDialogOpen(true);
                          }}
                        >
                          <Icons.Edit className="w-spacing-md h-spacing-md" /> Editar
                        </Button>
                      )}
                    </div>
                  </CardFooter>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Icons.Edit Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="w-full">
          <DialogHeader>
            <DialogTitle>Editar Parceiro</DialogTitle>
            <DialogDescription>
              Atualize as informações do parceiro ou modifique seu status manualmente.
            </DialogDescription>
          </DialogHeader>

          {editingPartner && (
            <div className="space-y-spacing-md py-spacing-md">
              <div className="grid grid-cols-2 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label htmlFor="edit-name">Nome</Label>
                  <Input
                    id="edit-name"
                    value={editingPartner.name}
                    onChange={(e) => setEditingPartner({ ...editingPartner, name: e.target.value })}
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label htmlFor="edit-email">Email de Contato</Label>
                  <Input
                    id="edit-email"
                    type="email"
                    value={editingPartner.contact_email || ""}
                    onChange={(e) =>
                      setEditingPartner({ ...editingPartner, contact_email: e.target.value })
                    }
                  />
                </div>
              </div>

              <div className="space-y-spacing-xs">
                <Label htmlFor="edit-description">Descrição</Label>
                <Textarea
                  id="edit-description"
                  value={editingPartner.description || ""}
                  onChange={(e) =>
                    setEditingPartner({ ...editingPartner, description: e.target.value })
                  }
                  className="min-h-[80px]"
                />
              </div>

              <div className="grid grid-cols-2 gap-spacing-md">
                <div className="space-y-spacing-xs">
                  <Label htmlFor="edit-website">Site (URL)</Label>
                  <Input
                    id="edit-website"
                    value={editingPartner.website_url || ""}
                    onChange={(e) =>
                      setEditingPartner({ ...editingPartner, website_url: e.target.value })
                    }
                  />
                </div>
                <div className="space-y-spacing-xs">
                  <Label htmlFor="edit-logo">Logo (URL)</Label>
                  <Input
                    id="edit-logo"
                    value={editingPartner.logo_url || ""}
                    onChange={(e) =>
                      setEditingPartner({ ...editingPartner, logo_url: e.target.value })
                    }
                  />
                </div>
              </div>

              <div className="space-y-spacing-xs">
                <Label>Status Atual</Label>
                <div className="flex gap-spacing-xs">
                  <Button
                    variant={editingPartner.status === "pending" ? "secondary" : "outline"}
                    size="sm"
                    className="flex-1"
                    onClick={() => setEditingPartner({ ...editingPartner, status: "pending" })}
                  >
                    Pendente
                  </Button>
                  <Button
                    variant={editingPartner.status === "approved" ? "default" : "outline"}
                    size="sm"
                    className={`flex-1 ${editingPartner.status === "approved" ? "bg-emerald-500 hover:bg-emerald-600" : ""}`}
                    onClick={() => setEditingPartner({ ...editingPartner, status: "approved" })}
                  >
                    Aprovado
                  </Button>
                  <Button
                    variant={editingPartner.status === "rejected" ? "destructive" : "outline"}
                    size="sm"
                    className="flex-1"
                    onClick={() => setEditingPartner({ ...editingPartner, status: "rejected" })}
                  >
                    Rejeitado
                  </Button>
                </div>
              </div>
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSaveEdit}>Salvar Alterações</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

