  const [newContent, setNewContent] = useState({
    content_type: "bible",
    reference: "",
    title: "",
    text_content: "",
  });

  const [editingContent, setEditingContent] = useState<ThemeContent | null>(null);

  const { data: themes, isLoading: loadingThemes } = useQuery({
    queryKey: ["admin-themes"],
    queryFn: async () => {
      const { data, error } = await supabase.from("themes").select("*").order("name");
      if (error) throw error;
      return data as Theme[];
    },
  });

  const { data: contents, isLoading: loadingContents } = useQuery({
    queryKey: ["admin-theme-contents", selectedTheme?.id],
    queryFn: async () => {
      if (!selectedTheme) return [];
      const { data, error } = await supabase
        .from("theme_contents")
        .select("*")
        .eq("theme_id", selectedTheme.id)
        .order("content_type");
      if (error) throw error;
      return data as ThemeContent[];
    },
    enabled: !!selectedTheme,
  });

  const createThemeMutation = useMutation({
    mutationFn: async (theme: {
      name: string;
      slug: string;
      description: string;
      emoji?: string;
      category?: string;
      order_index?: number;
    }) => {
      const { error } = await supabase.from("themes").insert([theme]);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-themes"] });
      setShowNewTheme(false);
      setNewTheme({
        name: "",
        slug: "",
        description: "",
        emoji: "⛪",
        category: "Espiritualidade",
        order_index: 0,
      });
      toast.success("Tema criado com sucesso!");
    },
    onError: (e: any) => toast.error(`Erro: ${e.message}`),
  });

  const updateThemeMutation = useMutation({
    mutationFn: async (theme: Theme) => {
      const { error } = await supabase
        .from("themes")
        .update({
          name: theme.name,
          slug: theme.slug,
          description: theme.description,
          emoji: theme.emoji,
          category: theme.category,
          image_url: theme.image_url,
          order_index: theme.order_index,
        })
        .eq("id", theme.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-themes"] });
      setShowEditTheme(false);
      setEditingTheme(null);
      toast.success("Tema atualizado com sucesso!");
