                                                            detail: {
                                                              book: selectedBook.abbr,
                                                              chapter: selectedChapter,
                                                              verse: v.number,
                                                              ...conn,
                                                            },
                                                          }),
                                                        );
                                                      } catch {}
                                                      setExpandedConnection(conn);
