                                                  aria-describedby={`nexus-popover-desc-${v.number}-${idx}`}
                                                  className="w-[min(22rem,calc(100vw-24px))] z-[200] p-spacing-md rounded-2xl border border-primary/10 bg-card shadow-premium"
