                                                        {meta.icon}
                                                      </span>
                                                      <div className="min-w-0">
                                                        <p
                                                          className={cn(
                                                            "text-[9px] font-black uppercase tracking-[0.2em]",
                                                            meta.tone,
                                                          )}
                                                        >
                                                          {meta.kicker}
                                                        </p>
                                                        <h4
                                                          id={`nexus-popover-title-${v.number}-${idx}`}
                                                          className="text-sm font-display font-bold text-primary truncate"
