                                                          console.info("[Nexus] navigate", {
                                                            from: "bible",
                                                            to: conn.type,
                                                            id: conn.id,
                                                          });
                                                          if (conn.type === "catechism")
                                                            navigate(`/catechism?p=${conn.id}`);
                                                          else if (conn.type === "document")
                                                            navigate(`/magisterium?doc=${conn.id}`);
                                                          else if (
                                                            conn.type === "bible" ||
                                                            conn.type === "cross_ref"
                                                          ) {
                                                            const parts = String(conn.id).split(
                                                              "-",
                                                            );
                                                            if (parts.length >= 2)
                                                              navigate(
                                                                `/bible?book=${parts[0]}&ch=${parts[1]}${parts[2] ? `&v=${parts[2]}` : ""}`,
