                                                        <Icons.BookOpen className="w-3.5 h-3.5 mr-spacing-xs text-secondary" />
                                                        Abrir referência
                                                      </Button>
                                                    </div>
                                                  </div>
                                                </PopoverContent>
                                              </Popover>
                                            );
                                          })}
                                        </div>
