interface TimeseriesRow {
  bucket_start: string;
  abbrev: string;
  total: number;
  hits: number;
  misses: number;
  stale: number;
  l1_fresh: number;
  l1_stale: number;
  l1_miss: number;
  l1_bypass: number;
  edge_avg_ms: number | null;
  edge_p50_ms: number;
  edge_p95_ms: number;
  edge_max_ms: number;
  total_avg_ms: number | null;
  total_p50_ms: number;
  total_p95_ms: number;
  total_max_ms: number;
  sql_avg_ms: number | null;
  sql_p95_ms: number;
  worst_correlation_ids: string[] | null;
}

interface DrilldownRow {
  created_at: string;
  abbrev: string;
  chapter: number | null;
  cache: string | null;
  l1_phase: string | null;
  correlation_id: string | null;
  total_ms: number | null;
  sql_ms: number | null;
  edge_ms: number | null;
  bolls_ms: number | null;
  bolls_ok: boolean | null;
  status_code: number | null;
  cold_start: boolean | null;
  cache_level: "L1" | "L2" | "DB" | "UNAVAILABLE" | null;
  total_wall_clock_ms: number | null;
  instance_id: string | null;
  request_source: string | null;
  sql_breakdown: Array<{ label: string; ms: number }> | null;
}

interface DiagnosticRun {
  id: string;
  started_at: string;
  completed_at: string | null;
  status: string;
  triggered_by: string;
  total_books_checked: number;
  total_chapters_checked: number;
