const CATEGORIES = ["Todos", ...Array.from(new Set(QUIZ_BANK.map((q) => q.category)))];

const Certamen: React.FC = () => {
  const [category, setCategory] = useState("Todos");
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [score, setScore] = useState(0);
  const [answered, setAnswered] = useState(0);
  const [showResult, setShowResult] = useState(false);

  const filtered = useMemo(() => {
    const pool =
      category === "Todos" ? [...QUIZ_BANK] : QUIZ_BANK.filter((q) => q.category === category);
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    return pool;
  }, [category, showResult]);

  const question = filtered[currentIndex];

  const handleAnswer = (idx: number) => {
    if (selected !== null) return;
    setSelected(idx);
    setAnswered((a) => a + 1);
    if (idx === question.correct) setScore((s) => s + 1);
  };

  const nextQuestion = () => {
    if (currentIndex >= filtered.length - 1) {
      setShowResult(true);
    } else {
      setCurrentIndex((i) => i + 1);
      setSelected(null);
    }
  };

  const restart = () => {
    setCurrentIndex(0);
    setSelected(null);
    setScore(0);
    setAnswered(0);
    setShowResult(false);
  };

  const shareResult = () => {
    const pct = Math.round((score / (answered || 1)) * 100);
    const date = new Date().toLocaleDateString("pt-BR");
    const text = `Meu resultado no Certamen Fidei (Quiz da Fé):\nScore: ${score}/${answered} (${pct}%)\nData: ${date}\n\n"Pois quem busca, encontra." (Mt 7,8)`;
    if (navigator.share) {
      navigator.share({ title: "Meu Resultado no Quiz da Fé", text });
    } else {
      navigator.clipboard.writeText(text);
      alert("Resultado copiado para a área de transferência!");
    }
  };

  if (showResult) {
    const pct = Math.round((score / (answered || 1)) * 100);
    return (
      <div className="w-full space-y-spacing-xl p-spacing-md">
        <div className="bg-card border border-border rounded-premium p-spacing-xl text-center space-y-spacing-lg shadow-premium-hover">
          <div className="w-spacing-3xl h-spacing-3xl rounded-premium bg-primary/10 flex items-center justify-center mx-auto text-primary">
            {pct >= 80 ? (
              <Icons.Trophy className="w-spacing-xl h-spacing-xl" />
            ) : pct >= 50 ? (
              <Icons.BookOpen className="w-spacing-xl h-spacing-xl" />
            ) : (
              <Icons.Heart className="w-spacing-xl h-spacing-xl" />
            )}
          </div>
          <h2 className="text-premium-3xl font-serif font-bold text-foreground">
            Resultado do Aprendizado
          </h2>
          <p className="text-premium-5xl font-black text-primary">
            {score}/{answered}
          </p>
          <div className="space-y-spacing-xs">
            <p className="text-premium-lg text-muted-foreground font-serif italic">
              {pct >= 80
                ? "Excelente! Conhecimento sólido da fé!"
                : pct >= 50
                  ? "Bom progresso. Continue estudando!"
                  : "Continue sua formação. A fé se aprofunda com o estudo."}
            </p>
            <p className="text-premium-xs text-muted-foreground">
              Avaliação realizada em {new Date().toLocaleDateString("pt-BR")}
            </p>
          </div>

          <div className="flex flex-col sm:flex-row gap-spacing-md justify-center pt-spacing-md">
            <Button
              onClick={restart}
              className="px-spacing-xl py-spacing-md bg-secondary text-secondary-foreground rounded-premium-full font-black uppercase text-premium-xs tracking-widest hover:bg-secondary/80 transition-all flex items-center justify-center gap-spacing-xs"
            >
              <Icons.RotateCcw className="w-spacing-md h-spacing-md" />
              Tentar Novamente
            </Button>
            <Button
              onClick={shareResult}
              className="px-spacing-xl py-spacing-md bg-primary text-primary-foreground rounded-premium-full font-black uppercase text-premium-xs tracking-widest hover:bg-primary/90 transition-all flex items-center justify-center gap-spacing-xs shadow-premium shadow-primary/20"
            >
              <Icons.Share2 className="w-spacing-md h-spacing-md" />
              Compartilhar Resultado
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (!question) return null;

  return (
    <div className="w-full space-y-spacing-xl p-spacing-md">
      <div className="text-center space-y-spacing-sm">
        <div className="inline-flex items-center gap-spacing-xs px-spacing-sm py-spacing-2xs bg-primary/10 rounded-premium">
          <Icons.Star className="w-spacing-md h-spacing-md text-primary" />
          <span className="text-premium-xs font-black uppercase tracking-[0.2em] text-primary">
            Certamen Fidei
          </span>
        </div>
        <h1 className="text-premium-3xl md:text-premium-5xl font-serif font-bold text-foreground">
          Quiz da Fé
        </h1>
        <p className="text-muted-foreground font-serif italic">
          Teste seus conhecimentos teológicos e compartilhe com sua comunidade.
        </p>
      </div>

      <div className="flex flex-wrap gap-spacing-xs justify-center">
        {CATEGORIES.map((cat) => (
          <Button
            key={cat}
            onClick={() => {
              setCategory(cat);
              restart();
            }}
            className={`px-spacing-md py-spacing-xs rounded-premium-full text-premium-xs font-bold transition-all ${cat === category ? "bg-foreground text-background shadow-premium scale-105" : "bg-card border border-border text-foreground hover:bg-primary/5"}`}
          >
            {cat}
          </Button>
        ))}
      </div>

      <div className="flex items-center justify-between text-premium-sm px-spacing-xs">
        <span className="text-muted-foreground font-bold">
          Pergunta {currentIndex + 1}/{filtered.length}
        </span>
        <div className="h-spacing-xs flex-1 mx-spacing-md bg-muted rounded-premium overflow-hidden">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${((currentIndex + 1) / filtered.length) * 100}%` }}
            className="h-full bg-primary"
          />
        </div>
        <span className="text-primary font-black">{score} acertos</span>
      </div>

      <div className="bg-card border border-border rounded-premium p-spacing-xl space-y-spacing-lg shadow-premium-md">
        <span className="text-premium-xs font-black uppercase tracking-widest text-primary bg-primary/10 px-spacing-xs py-spacing-2xs rounded">
          {question.category}
        </span>
        <h2 className="text-premium-xl md:text-premium-2xl font-serif font-bold text-foreground leading-tight">
          {question.question}
        </h2>

        <div className="space-y-spacing-sm">
          {question.options.map((opt, idx) => {
            let cls = "bg-muted border-border hover:border-primary/50 hover:bg-primary/5";
            if (selected !== null) {
              if (idx === question.correct)
                cls = "bg-emerald-500/10 border-emerald-500/50 text-emerald-700 font-bold";
              else if (idx === selected)
                cls = "bg-destructive/10 border-destructive/50 text-destructive font-bold";
              else cls = "opacity-50 bg-muted border-border";
            }
            return (
              <Button
                key={idx}
                onClick={() => handleAnswer(idx)}
                className={`w-full text-left p-spacing-md rounded-premium-full border font-bold text-premium-sm transition-all flex items-center gap-spacing-md ${cls}`}
              >
                <span className="w-spacing-xl h-spacing-xl rounded-premium-full bg-background flex items-center justify-center text-muted-foreground text-premium-xs">
                  {String.fromCharCode(65 + idx)}
                </span>
                <span className="flex-1">{opt}</span>
              </Button>
            );
          })}
        </div>

        {selected !== null && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-muted rounded-premium-full p-spacing-lg space-y-spacing-sm border border-border"
          >
            <p className="text-premium-sm font-bold text-foreground flex items-center gap-spacing-xs">
              {selected === question.correct
                ? "✅ Resposta Correta!"
                : "❌ Ops, não foi dessa vez."}
            </p>
            <p className="text-premium-sm text-muted-foreground font-serif leading-relaxed italic">
              {question.explanation}
            </p>

            <Button
              onClick={nextQuestion}
              className="w-full mt-spacing-md py-spacing-md bg-primary text-primary-foreground rounded-premium-full font-black uppercase text-premium-xs tracking-widest hover:bg-primary/90 transition-all flex items-center justify-center gap-spacing-xs"
            >
              {currentIndex >= filtered.length - 1 ? "Ver Resultado Final" : "Próxima Pergunta"}
              <Icons.ArrowRight className="w-spacing-md h-spacing-md" />
            </Button>
          </motion.div>
        )}
      </div>
    </div>
  );
};

export default Certamen;

import { Icons } from "@/constants";
import React, { useEffect, useState, useRef } from "react";
import { Button } from "@/components/ui/button";
import { useNavigate, useSearchParams } from "@/lib/rr-compat";
import { AppRoute } from "@/types";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { motion } from "framer-motion";

import confetti from "canvas-confetti";

type ResultState = "loading" | "success" | "pending" | "failure";

const CheckoutResultPage: React.FC = () => {
  const navigate = useNavigate();
  const { refreshProfile } = useAuth();
  const [searchParams] = useSearchParams();
  const checkoutState = searchParams.get("status");
  const paymentId = searchParams.get("payment_id");
  const externalReference = searchParams.get("external_reference");

  const [state, setState] = useState<ResultState>(() => {
    if (checkoutState === "failure") return "failure";
    if (checkoutState === "pending") return "pending";
    return "loading";
  });
  const [txData, setTxData] = useState<any>(null);

  const firedConfetti = useRef(false);

  useEffect(() => {
    if (state === "success" && !firedConfetti.current) {
      firedConfetti.current = true;
      const duration = 2000;
      const end = Date.now() + duration;
      const frame = () => {
        confetti({ particleCount: 3, angle: 60, spread: 55, origin: { x: 0 } });
        confetti({ particleCount: 3, angle: 120, spread: 55, origin: { x: 1 } });
        if (Date.now() < end) requestAnimationFrame(frame);
      };
      frame();
    }
  }, [state]);

  useEffect(() => {
    if (checkoutState === "failure" || checkoutState === "pending") return;

    if (checkoutState !== "success") {
      navigate(AppRoute.CHECKOUT, { replace: true });
      return;
    }

    // If no payment identifiers, assume webhook already processed it
    if (!paymentId && !externalReference) {
      setState("success");
      return;
    }

    void supabase.functions
      .invoke("mercadopago-sync-payment", {
        body: {
          paymentId: paymentId || undefined,
          transactionId: externalReference || undefined,
        },
      })
      .then(async ({ data, error }) => {
        if (error) throw error;
        if (data?.error) throw new Error(data.error);

        // Fetch transaction details for the summary
        const txId = data.transactionId || externalReference;
        if (txId) {
          const { data: tx } = await supabase
            .from("transactions")
            .select("*")
            .eq("id", txId)
            .maybeSingle();
          if (tx) setTxData(tx);
        }

        if (data?.status === "approved") {
          setState("success");
          void refreshProfile();
          return;
        }
        if (data?.status === "pending") {
          setState("pending");
          return;
        }
        setState("failure");
      })
      .catch(() => {
        setState("failure");
      });
  }, [checkoutState, paymentId, externalReference, navigate, refreshProfile]);

  const config: Record<
    Exclude<ResultState, "loading">,
    {
      icon: React.ReactNode;
      iconBg: string;
      title: string;
      description: string;
      primaryAction: { label: string; route: string };
      secondaryAction?: { label: string; route: string };
    }
  > = {
    success: {
      icon: <Icons.CheckCircle2 className="w-spacing-xl h-spacing-xl text-primary" />,
      iconBg: "bg-primary/10",
      title: "Pagamento aprovado!",
      description:
        "Seu acesso PRO foi liberado. Aproveite todos os recursos exclusivos do Cathedra.",
      primaryAction: { label: "Ir para o Dashboard", route: AppRoute.DASHBOARD },
      secondaryAction: { label: "Explorar Trilhas", route: AppRoute.TRILHAS },
    },
    pending: {
      icon: <Icons.Clock className="w-spacing-xl h-spacing-xl text-accent-foreground" />,
      iconBg: "bg-accent",
      title: "Pagamento em análise",
      description:
        "Seu pagamento foi recebido e está sendo processado. Assim que for aprovado, seu acesso PRO será liberado automaticamente.",
      primaryAction: { label: "Voltar ao Dashboard", route: AppRoute.DASHBOARD },
    },
    failure: {
      icon: <Icons.XCircle className="w-spacing-xl h-spacing-xl text-destructive" />,
      iconBg: "bg-destructive/10",
      title: "Pagamento não concluído",
      description:
        "O pagamento foi cancelado ou recusado. Nenhuma cobrança foi realizada. Você pode tentar novamente quando quiser.",
      primaryAction: { label: "Tentar novamente", route: AppRoute.CHECKOUT },
      secondaryAction: { label: "Voltar ao início", route: AppRoute.DASHBOARD },
    },
  };

  if (state === "loading") {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-spacing-lg">
        <div className="w-spacing-3xl h-spacing-3xl border-4 border-secondary border-t-transparent rounded-premium animate-spin" />
        <p className="text-muted-foreground font-serif italic text-premium-lg">
          Confirmando seu pagamento...
        </p>
      </div>
    );
  }

  const c = config[state];

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
      className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-spacing-xl w-full py-spacing-2xl"
    >
      <div
        className={`w-spacing-4xl h-spacing-4xl rounded-premium-full ${c.iconBg} flex items-center justify-center`}
      >
        {c.icon}
      </div>

      <div className="space-y-spacing-sm">
        <h1 className="text-premium-3xl md:text-premium-4xl font-serif font-bold text-foreground">
          {c.title}
        </h1>
        <p className="text-muted-foreground font-serif italic text-premium-base leading-relaxed">
          {c.description}
        </p>
      </div>

      {txData && (
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="w-full bg-muted/50 rounded-premium-full p-spacing-lg border border-border/50 space-y-spacing-md"
        >
          <div className="flex justify-between items-center pb-spacing-xs border-b border-border/50">
            <span className="text-premium-xs font-black uppercase tracking-widest text-muted-foreground">
              Resumo da Transação
            </span>
            <span className="text-premium-xs font-mono text-muted-foreground">
              #{txData.payment_id || txData.id.slice(0, 8)}
            </span>
          </div>

          <div className="space-y-spacing-sm">
            <div className="flex justify-between items-center">
              <span className="text-premium-sm text-muted-foreground">Descrição</span>
              <span className="text-premium-sm font-bold text-foreground">
                {txData.description || "Contribuição Cathedra"}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-premium-sm text-muted-foreground">Valor</span>
              <span className="text-premium-lg font-black text-primary">
                {new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(
                  txData.amount,
                )}
