const CommandCenter: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [globalResults, setGlobalResults] = useState<UnifiedResult[]>([]);
  const [globalLoading, setGlobalLoading] = useState(false);
  const [lastBible, setLastBible] = useState<{ book_abbr: string; chapter: number } | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const searchTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const listRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();

  useEffect(() => {
    const loadLastRead = async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) return;
      const { data } = await (supabase as any)
        .from("bible_chapters_read")
        .select("book_abbr, chapter")
        .eq("user_id", user.id)
        .order("read_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (data) setLastBible(data);
    };
    loadLastRead();
  }, []);

  // Page filter (instant)
  const filteredPages = useMemo(() => {
    const commands = PAGE_COMMANDS.map((c) => {
      if (c.path === AppRoute.BIBLE && lastBible) {
        return {
          ...c,
          path: `${AppRoute.BIBLE}?book=${lastBible.book_abbr}&ch=${lastBible.chapter}`,
          description: `Continuar em ${lastBible.book_abbr} ${lastBible.chapter}`,
        };
      }
      return c;
    });

    if (!query) return commands;
    const q = query.toLowerCase();
    return commands.filter(
      (c) =>
        c.label.toLowerCase().includes(q) ||
        c.description.toLowerCase().includes(q) ||
        c.keywords.some((k) => k.includes(q)),
    );
  }, [query, lastBible]);

  // Saints search via DB hook
  const { data: dbSaintsResults = [] } = useSearchSaints(query);

  const filteredSaints = useMemo(() => {
    if (query.length < 2 || !dbSaintsResults.length) return [];

    const results: UnifiedResult[] = dbSaintsResults.slice(0, 8).map((s) => ({
      type: "saint" as const,
      label: s.name,
      description: `${s.title} • Festa: ${s.feastDay}`,
      path: `${AppRoute.SAINTS}?saint=${s.id}`,
      icon: s.image ? (
        <img
          src={s.image}
          alt={s.name}
          className="w-spacing-md h-spacing-md rounded-premium-full object-cover"
        />
      ) : (
        <Icons.SaintHalo className="w-spacing-md h-spacing-md" />
      ),
    }));

    return results;
  }, [query, dbSaintsResults]);

  // Global search (debounced DB queries)
  const runGlobalSearch = useCallback(async (q: string) => {
    if (q.length < 3) {
      setGlobalResults([]);
      return;
    }
    setGlobalLoading(true);
    const results: UnifiedResult[] = [];

    const promises: Promise<void>[] = [
      // Bible search
      supabase.functions
        .invoke("bible-search", { body: { query: q } })
        .then(({ data }) => {
          if (data?.results) {
            data.results.slice(0, 4).forEach((v: any) => {
              results.push({
                type: "bible",
                label: `${v.bookAbbrev} ${v.chapter},${v.verse}`,
                description: v.text?.substring(0, 80) + "...",
                path: `/bible?book=${v.bookAbbrev}&ch=${v.chapter}`,
                icon: <Icons.Book className="w-spacing-md h-spacing-md" />,
              });
            });
          }
        })
        .catch(() => {}),

      // Catechism search
      (async () => {
        // Search in local data
        const localMatches = Object.values(CATECHISM_LOCAL_DATA)
          .filter(
            (p: any) =>
              p.conteudo.toLowerCase().includes(q.toLowerCase()) ||
              p.titulo.toLowerCase().includes(q.toLowerCase()),
          )
          .slice(0, 4)
          .map((p: any) => ({
            type: "catechism" as const,
            label: `§${p.paragraph} (Local)`,
            description: p.conteudo.substring(0, 80) + "...",
            path: `${AppRoute.CATECHISM}?p=${p.paragraph}`,
            icon: <Icons.Cross className="w-spacing-md h-spacing-md" />,
          }));

        results.push(...localMatches);

        // Search in DB cache (if not enough local matches or to get more)
        if (results.filter((r) => r.type === "catechism").length < 4) {
          const { data } = await supabase
            .from("catechism_cache")
            .select("paragraph, content")
            .ilike("content", `%${q}%`)
            .limit(4);

          data?.forEach((p: any) => {
            // Avoid duplicates
            if (
              !results.some((r) => r.type === "catechism" && r.label.includes(`§${p.paragraph}`))
            ) {
              results.push({
                type: "catechism",
                label: `§${p.paragraph}`,
                description: p.content.substring(0, 80) + "...",
                path: `${AppRoute.CATECHISM}?p=${p.paragraph}`,
                icon: <Icons.Cross className="w-spacing-md h-spacing-md" />,
              });
            }
          });
        }
      })().catch(() => {}),

      // Journeys search
      Promise.resolve(
        supabase
          .from("journeys")
          .select("id, title, description, category")
          .or(`title.ilike.%${q}%,description.ilike.%${q}%`)
          .eq("is_active", true)
          .limit(4),
      )
        .then(({ data }) => {
          data?.forEach((j) => {
            results.push({
              type: "journey",
              label: j.title,
              description: j.description?.substring(0, 80) + "...",
              path: `/jornadas/${j.id}`,
              icon: <Icons.Compass className="w-spacing-md h-spacing-md" />,
            });
          });
        })
        .catch(() => {}),

      // Glossary search
      Promise.resolve(
        supabase
          .from("glossary")
          .select("term, definition, category")
          .or(`term.ilike.%${q}%,definition.ilike.%${q}%`)
          .limit(4),
      )
        .then(({ data }) => {
          data?.forEach((g) => {
            results.push({
              type: "glossary",
              label: g.term,
              description: g.definition.substring(0, 80) + "...",
              path: `${AppRoute.GLOSSARY}?q=${encodeURIComponent(g.term)}`,
              icon: <Icons.Glossary className="w-spacing-md h-spacing-md" />,
            });
          });
        })
        .catch(() => {}),

      // Themes search
      Promise.resolve(
        supabase
          .from("themes")
          .select("id, name, slug, description")
          .or(`name.ilike.%${q}%,description.ilike.%${q}%`)
          .limit(4),
      )
        .then(({ data }) => {
          data?.forEach((t) => {
            results.push({
              type: "theme",
              label: t.name,
              description: t.description?.substring(0, 80) + "...",
              path: `${AppRoute.TEMAS}/${t.slug}`,
              icon: <Icons.Tag className="w-spacing-md h-spacing-md" />,
            });
          });
        })
        .catch(() => {}),

      // Community search
      Promise.resolve(
        supabase
          .from("community_posts")
          .select("id, title, content, category")
          .is("parent_id", null)
          .or(`title.ilike.%${q}%,content.ilike.%${q}%`)
          .limit(3),
      )
        .then(({ data }) => {
          data?.forEach((p) => {
            results.push({
              type: "community",
              label: p.title || "Discussão",
              description: p.content.substring(0, 80) + "...",
              path: AppRoute.COMMUNITY,
              icon: <Icons.Message className="w-spacing-md h-spacing-md" />,
            });
          });
        })
        .catch(() => {}),
    ];

    await Promise.allSettled(promises);
    setGlobalResults(results);
    setGlobalLoading(false);
  }, []);

  useEffect(() => {
    if (query.length >= 3) {
      clearTimeout(searchTimer.current);
      searchTimer.current = setTimeout(() => runGlobalSearch(query), 400);
    } else {
      setGlobalResults([]);
    }
    return () => clearTimeout(searchTimer.current);
  }, [query, runGlobalSearch]);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setIsOpen((prev) => !prev);
      }
      if (e.key === "Escape") setIsOpen(false);
    };

    const openHandler = () => setIsOpen(true);
    window.addEventListener("keydown", handler);
    window.addEventListener("open-command-center", openHandler);
    return () => {
      window.removeEventListener("keydown", handler);
      window.removeEventListener("open-command-center", openHandler);
    };
  }, []);

  useEffect(() => {
    if (isOpen) {
      setQuery("");
      setSelectedIndex(0);
      setGlobalResults([]);
      setTimeout(() => inputRef.current?.focus(), 50);
    }
  }, [isOpen]);

  useEffect(() => {
    setSelectedIndex(0);
  }, [query]);

  // Unified results: pages first, then saints (local), then DB results
  const allItems = useMemo(() => {
    if (query.length < 2) return filteredPages;
    return [...filteredPages.slice(0, 5), ...filteredSaints, ...globalResults];
  }, [filteredPages, filteredSaints, globalResults, query]);

  const go = useCallback(
    (path?: string) => {
      if (path) navigate(path);
      setIsOpen(false);
    },
    [navigate],
  );

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setSelectedIndex((i) => Math.min(i + 1, allItems.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSelectedIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter" && allItems[selectedIndex]) {
      go(allItems[selectedIndex].path);
    }
  };

  // Scroll selected into view
  useEffect(() => {
    const el = listRef.current?.children[selectedIndex] as HTMLElement | undefined;
    el?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [selectedIndex]);

  if (!isOpen) return null;

  const resultCount = allItems.length;
  const hasGlobalResults = globalResults.length > 0;

  return (
    <div
      className="fixed inset-0 z-[200] flex items-start justify-center pt-spacing-md sm:pt-[12vh] px-spacing-sm sm:px-spacing-0"
      onClick={() => setIsOpen(false)}
      role="dialog"
      aria-modal="true"
      aria-label="Central de comandos e busca"
    >
      <div className="absolute inset-0 bg-black/60" aria-hidden="true" />
      <div
        className="relative w-full max-w-spacing-xl bg-card border border-border rounded-[2rem] shadow-premium overflow-hidden animate-in fade-in slide-in-from-top-spacing-md duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search input */}
        <div
          className="flex items-center gap-spacing-sm px-spacing-md py-spacing-md border-b border-border"
          role="combobox"
          aria-haspopup="listbox"
          aria-expanded={isOpen}
          aria-owns="command-list"
        >
          <Icons.Search
            className="w-spacing-md h-spacing-md text-primary shrink-0"
            aria-hidden="true"
          />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Buscar em tudo: Bíblia, Catecismo, Santos, Jornadas..."
            className="flex-1 bg-transparent text-foreground text-premium-sm placeholder:text-muted-foreground focus:outline-none"
            aria-autocomplete="list"
            aria-controls="command-list"
            aria-activedescendant={allItems[selectedIndex] ? `item-${selectedIndex}` : undefined}
          />

          {query && (
            <Button
              onClick={() => setQuery("")}
              className="text-muted-foreground hover:text-foreground transition-colors"
            >
              <Icons.X className="w-spacing-md h-spacing-md" />
            </Button>
          )}
          <kbd className="hidden sm:inline-flex items-center px-spacing-xs py-spacing-3xs rounded bg-muted text-muted-foreground text-premium-xs font-mono font-bold">
            ESC
          </kbd>
        </div>

        {/* Loading indicator */}
        {globalLoading && (
          <div className="h-spacing-3xs w-full bg-muted overflow-hidden">
            <div
              className="h-full w-spacing-2xs/3 bg-primary animate-[shimmer_1s_ease-in-out_infinite] rounded-premium"
              style={{ animation: "shimmer 1s ease-in-out infinite", animationName: "none" }}
            />
            <div className="h-full bg-primary/60 animate-pulse rounded-premium" />
          </div>
        )}

        {/* Results */}
        <div
          ref={listRef}
          id="command-list"
          role="listbox"
          className="max-h-[40vh] sm:max-h-[55vh] overflow-y-auto py-spacing-2xs"
        >
          {query.length >= 2 && !globalLoading && resultCount > 0 && (
            <div
              className="px-spacing-md py-spacing-xs text-premium-xs font-black uppercase tracking-widest text-muted-foreground"
              aria-live="polite"
            >
              {resultCount} resultado{resultCount !== 1 ? "s" : ""} encontrado
              {resultCount !== 1 ? "s" : ""}
            </div>
          )}

          {allItems.length === 0 && !globalLoading && (
            <p className="text-center text-premium-sm text-muted-foreground py-spacing-xl italic">
              {query.length < 2
                ? "Digite para buscar em todos os módulos..."
                : "Nenhum resultado encontrado."}
            </p>
          )}

          {allItems.map((item, i) => {
            // Group header
            const prevType = i > 0 ? allItems[i - 1].type : null;
            const showGroupHeader = item.type !== prevType && query.length >= 2;

            return (
              <React.Fragment key={`${item.type}-${item.label}-${i}`}>
                {showGroupHeader && (
                  <div
                    className="px-spacing-md pt-spacing-sm pb-spacing-2xs text-premium-xs font-black uppercase tracking-widest text-muted-foreground/60 flex items-center gap-spacing-xs"
                    role="presentation"
                  >
                    <div className="w-spacing-md h-px bg-border" />
                    {TYPE_LABELS[item.type] || item.type}
                  </div>
                )}
                <Button
                  id={`item-${i}`}
                  role="option"
                  aria-selected={i === selectedIndex}
                  onClick={() => go(item.path)}
                  onMouseEnter={() => setSelectedIndex(i)}
                  className={`w-full flex items-center gap-spacing-sm px-spacing-md py-spacing-xs text-left transition-all outline-none focus:ring-0 ${
                    i === selectedIndex
                      ? "bg-primary/10 text-primary"
                      : "text-foreground hover:bg-muted/50"
                  }`}
                >
                  <span
                    className={`p-spacing-2xs rounded-premium-full ${i === selectedIndex ? "bg-primary/20" : "bg-muted"}`}
                  >
                    {item.icon}
                  </span>
                  <div className="flex-1 min-w-spacing-0">
                    <p className="text-premium-sm font-semibold truncate">{item.label}</p>
                    <p className="text-premium-xs text-muted-foreground truncate">
                      {item.description}
                    </p>
                  </div>
                  <span
                    className={`text-premium-xs font-black uppercase tracking-widest px-spacing-xs py-spacing-3xs rounded-premium-full ${
                      TYPE_STYLES[item.type] || "bg-muted text-muted-foreground"
                    }`}
                  >
                    {TYPE_LABELS[item.type] || item.type}
                  </span>
                </Button>
              </React.Fragment>
            );
          })}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-spacing-md py-spacing-xs border-t border-border bg-muted/30">
          <div className="flex items-center gap-spacing-sm">
            <span className="text-premium-xs text-muted-foreground">↑↓ navegar</span>
            <span className="text-premium-xs text-muted-foreground">↵ abrir</span>
          </div>
          <div className="flex items-center gap-spacing-xs">
            {hasGlobalResults && (
              <span className="text-premium-xs text-primary font-medium">
                Buscando em {new Set(globalResults.map((r) => r.type)).size} módulos
              </span>
            )}
            <span className="text-premium-xs text-muted-foreground font-mono">⌘K</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CommandCenter;

import React, { useState, useEffect, useCallback } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Icons } from "../../constants";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { getLevelInfo } from "@/lib/levels";
import { useNavigate } from "@/lib/rr-compat";
import { AppRoute } from "@/types";
import { toast } from "sonner";
import { useFuzzySearch } from "@/hooks/useFuzzySearch";
import { RelevanceBadge } from "./RelevanceBadge";
import { FuzzySearchInput } from "./FuzzySearchInput";
import { ListSkeleton, PageHeaderSkeleton } from "./SacredSkeleton";
import { getTabProps, getTabPanelProps, useTabNavigation } from "./TabUtils";
import ContemplativeLayout from "./ContemplativeLayout";

const CATEGORIES = [
  { id: "geral", label: "Geral" },
  { id: "testemunho", label: "✝ Testemunho" },
  { id: "partilha", label: "💬 Partilha" },
  { id: "teologia", label: "Teologia" },
  { id: "biblia", label: "Bíblia" },
  { id: "liturgia", label: "Liturgia" },
  { id: "moral", label: "Moral" },
  { id: "espiritualidade", label: "Espiritualidade" },
];

interface Post {
  id: string;
  user_id: string;
  parent_id: string | null;
  title: string | null;
  content: string;
  category: string;
  likes_count: number;
  created_at: string;
  status: string | null;
  author_name?: string;
  replies_count?: number;
  user_liked?: boolean;
  similarityScore?: number;
}

interface LeaderboardEntry {
  id: string;
  name: string;
  avatar_url: string | null;
  posts: number;
  likes: number;
  score: number;
  levelName: string;
  levelIdx: number;
}

const CommunityPage: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const { handleKeyDown: handleTabKeyDown } = useTabNavigation();
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [category, setCategory] = useState("geral");
  const [showNewPost, setShowNewPost] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [newCategory, setNewCategory] = useState("geral");
  const [selectedPost, setSelectedPost] = useState<Post | null>(null);
  const [replies, setReplies] = useState<Post[]>([]);
  const [replyContent, setReplyContent] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [tab, setTab] = useState<"forum" | "ranking">("forum");
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [lbLoading, setLbLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<Post[] | null>(null);

  // Shared hook handles debounce (300ms) + RPC + similarityScore decoration.
  const { results: rawSearchResults, isPending: isSearchPending } = useFuzzySearch<Post>({
    rpc: "search_community_posts_fuzzy",
    query: searchQuery,
    primaryField: "title",
    secondaryField: "content",
    secondaryWeight: 0.6,
  });

  const fetchLeaderboard = useCallback(async () => {
    setLbLoading(true);
    const { data: allPosts } = await supabase
      .from("community_posts")
      .select("user_id, likes_count");

    if (!allPosts) {
      setLbLoading(false);
      return;
    }

    const userMap = new Map<string, { posts: number; likes: number }>();
    for (const p of allPosts) {
      const entry = userMap.get(p.user_id) || { posts: 0, likes: 0 };
      entry.posts += 1;
      entry.likes += p.likes_count;
      userMap.set(p.user_id, entry);
    }

    const userIds = [...userMap.keys()];
    if (userIds.length === 0) {
      setLeaderboard([]);
      setLbLoading(false);
      return;
    }

    const { data: profiles } = (await supabase
      .from("public_profiles" as any)
      .select("id, name, avatar_url")
      .in("id", userIds)) as {
      data: { id: string; name: string; avatar_url: string | null }[] | null;
    };

    const entries: LeaderboardEntry[] = (profiles || [])
      .map((p) => {
        const s = userMap.get(p.id) || { posts: 0, likes: 0 };
        const score = s.posts * 10 + s.likes * 5;
        const xp = s.posts * 30 + s.likes * 10 + s.likes * 5;
        const { levelIdx, levelName } = getLevelInfo(xp);
        return {
          id: p.id,
          name: p.name || "Anônimo",
          avatar_url: p.avatar_url,
          posts: s.posts,
          likes: s.likes,
          score,
          levelName,
          levelIdx,
        };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, 20);

    setLeaderboard(entries);
    setLbLoading(false);
  }, []);

  useEffect(() => {
    if (tab === "ranking") fetchLeaderboard();
  }, [tab, fetchLeaderboard]);

  const fetchPosts = useCallback(async () => {
    setLoading(true);
    const query = supabase
      .from("community_posts")
      .select("*")
      .is("parent_id", null)
      .order("created_at", { ascending: false })
      .limit(50);

    if (category !== "geral") {
      query.eq("category", category);
    }

    const { data, error } = await query;
    if (!error && data) {
      const userIds = [...new Set(data.map((p) => p.user_id))];
      const { data: profiles } = (await supabase
        .from("public_profiles" as any)
        .select("id, name")
        .in("id", userIds)) as { data: { id: string; name: string }[] | null };

      const profileMap = new Map(profiles?.map((p) => [p.id, p.name]) || []);

      let likedPostIds = new Set<string>();
      if (user) {
        const { data: likes } = await supabase
          .from("community_likes")
          .select("post_id")
          .eq("user_id", user.id);
        likedPostIds = new Set(likes?.map((l) => l.post_id) || []);
      }

      const enriched = data.map((p) => ({
        ...p,
        author_name: profileMap.get(p.user_id) || "Anônimo",
        user_liked: likedPostIds.has(p.id),
      }));
      setPosts(enriched.filter((p) => p.status === "approved" || p.user_id === user?.id));
    }
    setLoading(false);
  }, [category, user, tab]);

  useEffect(() => {
    fetchPosts();
  }, [fetchPosts]);

  useEffect(() => {
    if (rawSearchResults === null) {
      setSearchResults(null);
      return;
    }
    let cancelled = false;
    (async () => {
      const rows = rawSearchResults;
      const userIds = [...new Set(rows.map((p) => p.user_id))];
      let profileMap = new Map<string, string>();
      if (userIds.length) {
        const { data: profiles } = (await supabase
          .from("public_profiles" as any)
          .select("id, name")
          .in("id", userIds)) as { data: { id: string; name: string }[] | null };
        profileMap = new Map(profiles?.map((p) => [p.id, p.name]) || []);
      }
      let likedPostIds = new Set<string>();
      if (user && rows.length) {
        const { data: likes } = await supabase
          .from("community_likes")
          .select("post_id")
          .eq("user_id", user.id)
          .in(
            "post_id",
            rows.map((r) => r.id),
          );
        likedPostIds = new Set(likes?.map((l) => l.post_id) || []);
      }
      if (cancelled) return;
      setSearchResults(
        rows.map((p) => ({
          ...p,
          author_name: profileMap.get(p.user_id) || "Anônimo",
          user_liked: likedPostIds.has(p.id),
        })),
      );
    })();
    return () => {
      cancelled = true;
    };
  }, [rawSearchResults, user]);

  const openPost = async (post: Post) => {
    setSelectedPost(post);
    const { data } = await supabase
      .from("community_posts")
      .select("*")
      .eq("parent_id", post.id)
      .order("created_at", { ascending: true });

    if (data) {
      const userIds = [...new Set(data.map((r) => r.user_id))];
      const { data: profiles } = (await supabase
        .from("public_profiles" as any)
        .select("id, name")
        .in("id", userIds.length ? userIds : [""])) as {
        data: { id: string; name: string }[] | null;
      };
      const profileMap = new Map(profiles?.map((p) => [p.id, p.name]) || []);
      setReplies(data.map((r) => ({ ...r, author_name: profileMap.get(r.user_id) || "Anônimo" })));
    }
  };

  const toggleLike = async (post: Post) => {
    if (!user) {
      navigate(AppRoute.LOGIN);
      return;
    }
    if (post.user_liked) {
      await supabase.from("community_likes").delete().eq("post_id", post.id).eq("user_id", user.id);
    } else {
      await supabase.from("community_likes").insert({ post_id: post.id, user_id: user.id });
    }
    fetchPosts();
  };

  const submitReply = async () => {
    if (!user || !selectedPost || !replyContent.trim()) return;
    setSubmitting(true);
    const { error } = await supabase.from("community_posts").insert({
      user_id: user.id,
      parent_id: selectedPost.id,
      content: replyContent.trim(),
      category: selectedPost.category,
    });
    if (!error) {
      setReplyContent("");
      openPost(selectedPost);
      toast.success("Resposta enviada!");
    }
    setSubmitting(false);
  };

  const timeAgo = (dateStr: string) => {
    const diff = Date.now() - new Date(dateStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 60) return `${mins}min`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h`;
    const days = Math.floor(hours / 24);
    return `${days}d`;
  };

  if (selectedPost) {
    return (
      <div className="w-full space-y-spacing-lg py-spacing-xl px-spacing-md">
        <Button
          onClick={() => {
            setSelectedPost(null);
            setReplies([]);
          }}
          className="flex items-center gap-spacing-xs text-premium-sm text-muted-foreground hover:text-foreground transition-colors focus-visible:ring-2 focus-visible:ring-primary outline-none rounded-premium-full px-spacing-xs py-spacing-2xs"
          aria-label="Voltar para a lista de discussões"
        >
          <Icons.ChevronLeft className="w-spacing-md h-spacing-md" /> Voltar
        </Button>

        <div className="bg-card border border-border rounded-premium p-spacing-lg space-y-spacing-md">
          <div className="flex items-center gap-spacing-sm">
            <div className="w-spacing-xl h-spacing-xl rounded-premium bg-foreground text-background flex items-center justify-center font-black text-premium-sm">
              {(selectedPost.author_name || "A").charAt(0).toUpperCase()}
            </div>
            <div>
              <p className="text-premium-sm font-bold text-foreground">
                {selectedPost.author_name}
              </p>
              <p className="text-premium-xs text-muted-foreground">
                {timeAgo(selectedPost.created_at)}
              </p>
            </div>
            <span className="ml-auto text-premium-xs font-black uppercase tracking-widest text-primary bg-primary/10 px-spacing-xs py-spacing-2xs rounded-premium-full">
              {CATEGORIES.find((c) => c.id === selectedPost.category)?.label ||
                selectedPost.category}
            </span>
          </div>
          <h2 className="text-premium-xl font-serif font-bold text-foreground">
            {selectedPost.title}
          </h2>
          <p className="text-foreground/80 leading-relaxed whitespace-pre-wrap">
            {selectedPost.content}
          </p>
          <div className="flex items-center gap-spacing-md pt-spacing-xs border-t border-border">
            <Button
              onClick={() => toggleLike(selectedPost)}
              className="flex items-center gap-spacing-2xs text-premium-sm text-muted-foreground hover:text-primary transition-colors focus-visible:ring-2 focus-visible:ring-primary outline-none rounded-premium-full px-spacing-xs py-spacing-2xs"
              aria-label={selectedPost.user_liked ? "Remover curtida" : "Curtir discussão"}
              aria-pressed={selectedPost.user_liked}
            >
              <Icons.Heart
                className={`w-spacing-md h-spacing-md ${selectedPost.user_liked ? "fill-primary text-primary" : ""}`}
              />
              {selectedPost.likes_count}
            </Button>
            <span className="text-premium-sm text-muted-foreground">
              {replies.length} respostas
            </span>
          </div>
        </div>

        <div className="space-y-spacing-sm">
          {replies.map((r) => (
            <div
              key={r.id}
              className="bg-card border border-border rounded-premium p-spacing-md ml-spacing-lg"
            >
              <div className="flex items-center gap-spacing-xs mb-spacing-xs">
                <div className="w-spacing-lg h-spacing-lg rounded-premium bg-muted flex items-center justify-center text-premium-xs font-bold text-foreground">
                  {(r.author_name || "A").charAt(0).toUpperCase()}
                </div>
                <span className="text-premium-xs font-bold text-foreground">{r.author_name}</span>
                <span className="text-premium-xs text-muted-foreground">
                  {timeAgo(r.created_at)}
                </span>
              </div>
              <p className="text-premium-sm text-foreground/80 whitespace-pre-wrap">{r.content}</p>
            </div>
          ))}
        </div>

        {user ? (
          <div className="bg-card border border-border rounded-premium p-spacing-md space-y-spacing-sm">
            <textarea
              value={replyContent}
              onChange={(e) => setReplyContent(e.target.value)}
