import React, { useMemo, useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Icons } from "../../constants";
import { DeepContent, AppRoute } from "@/types";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { useNavigate } from "@/lib/rr-compat";

import { parseTheologicalReferences } from "@/lib/theologicalRefParser";
import BibleVersePopover from "./BibleVersePopover";
import CatechismPopover from "./CatechismPopover";
import { supabase } from "@/lib/db";
import { toast } from "sonner";

interface DeepContentSectionProps {
  content: DeepContent & {
    explicacao?: string;
    interpretacaoProfunda?: string;
    aplicacaoPratica?: string;
    reflexaoFinal?: string;
    exercicio?: string;
    status?: string;
  };
  title?: string;
  contentType?: "bible" | "catechism" | "apparition" | "other";
}

const DeepContentSection: React.FC<DeepContentSectionProps> = ({ content, title, contentType }) => {
  const { isPremium, user } = useAuth();
  const navigate = useNavigate();
  const [reflectionText, setReflectionText] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasReflected, setHasReflected] = useState(false);

  // Load existing reflection if any
  const fetchReflection = React.useCallback(async () => {
    if (!user || !contentType) return;
    const { data } = await supabase
      .from("reading_reflections" as any)
      .select("content")
      .eq("user_id", user.id)
      .eq("reading_type", contentType)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    if (data) {
      setHasReflected(true);
    } else {
      setHasReflected(false);
    }
  }, [user, contentType]);

  useEffect(() => {
    if (!user || !contentType) return;
    fetchReflection();

    // Realtime sync for reflections
    const channel = supabase
      .channel(`reading_reflections_${contentType}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "reading_reflections",
          filter: `user_id=eq.${user.id}`,
        },
        () => fetchReflection(),
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, contentType, fetchReflection]);

  const saveReflection = async () => {
    if (!user || !reflectionText.trim()) return;
    setIsSubmitting(true);
    try {
      const { error } = await supabase.from("reading_reflections" as any).insert({
        user_id: user.id,
        content: reflectionText.trim(),
        reading_type: contentType || "other",
        // Add metadata if needed to link back to specific verse/para
      } as any);

      if (error) throw error;

      setHasReflected(true);
      setReflectionText("");
      toast.success("Reflexão guardada no seu diário espiritual.");
    } catch (err) {
      console.error("Error saving reflection:", err);
      toast.error("Erro ao guardar reflexão.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const sections = useMemo(() => {
    const s = [
      {
        id: "textoBase",
        label: "Acesso Inicial",
        icon: <Icons.Book className="w-spacing-md h-spacing-md" />,
        value: content.textoBase,
        isPremium: false,
      },
      {
        id: "explicacao",
        label: "Explicação",
        icon: <Icons.Info className="w-spacing-md h-spacing-md" />,
        value: content.explicacao,
        isPremium: true,
      },
      {
        id: "interpretacaoProfunda",
        label: "Sentido Profundo",
        icon: <Icons.Sparkle className="w-spacing-md h-spacing-md" />,
        value: content.interpretacaoProfunda,
        isPremium: true,
      },
      {
        id: "aplicacaoPratica",
        label: "Vida Prática",
        icon: <Icons.Zap className="w-spacing-md h-spacing-md" />,
        value: content.aplicacaoPratica,
        isPremium: true,
      },
      {
        id: "reflexaoFinal",
        label: "Reflexão",
        icon: <Icons.Heart className="w-spacing-md h-spacing-md" />,
        value: content.reflexaoFinal,
        isPremium: true,
      },
      {
        id: "exercicio",
        label: "Exercício de Fé",
        icon: <Icons.PenTool className="w-spacing-md h-spacing-md" />,
        value: content.exercicio,
        isPremium: true,
      },
    ];

    // If it's catechism, we might want to show all sections even if empty to satisfy the "clear message" requirement
    if (contentType === "catechism") {
      return s;
    }

    return s.filter((sec) => !!sec.value);
  }, [content, contentType]);

  if (sections.length === 0) return null;

  return (
    <section
      className="space-y-spacing-xl animate-in fade-in slide-in-from-bottom-spacing-md duration-500"
      aria-label="Aprofundamento teológico"
    >
      {title && (
        <div className="flex items-center gap-spacing-sm mb-spacing-lg">
          <div className="h-px flex-1 bg-border/40" />
          <h3 className="text-premium-xs font-black uppercase tracking-[0.3em] text-primary whitespace-nowrap">
            {title}
          </h3>
          <div className="h-px flex-1 bg-border/40" />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-spacing-lg">
        {sections.map((section, idx) => {
          const isLocked = section.isPremium && !isPremium;

          return (
            <motion.div
              key={`${section.id}-${idx}`}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: idx * 0.1 }}
              className={`p-spacing-lg rounded-premium border transition-all relative overflow-hidden ${
                section.id === "textoBase"
                  ? "bg-primary/5 border-primary/20 md:col-span-2"
