const GlobalSearchPage = React.forwardRef<HTMLDivElement>((_props, ref) => {
  const navigate = useNavigate();
  useRenderPerf("Logos Search", 20);

  useAutoFocus();
  const [searchParams, setSearchParams] = useSearchParams();
  const [query, setQuery] = useState(() => searchParams.get("q") ?? "");
  const bibleLivro = searchParams.get("livro") ?? "";
  const bibleCapitulo = searchParams.get("capitulo") ?? "";
  const hasBibleFilter = Boolean(bibleLivro && bibleCapitulo);
  const clearBibleFilter = () => {
    const next = new URLSearchParams(searchParams);
    next.delete("livro");
    next.delete("capitulo");
    setSearchParams(next, { replace: true });
  };

  // Sincroniza URL ↔ estado: mudanças externas (link, back/forward) hidratam o input.
  useEffect(() => {
    const urlQ = searchParams.get("q") ?? "";
    if (urlQ !== query) setQuery(urlQ);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams]);

  // Reflete o que o usuário digita na URL (replace = sem poluir histórico).
  useEffect(() => {
    const current = searchParams.get("q") ?? "";
    if (query === current) return;
    const next = new URLSearchParams(searchParams);
    if (query.trim().length >= 2) next.set("q", query);
    else next.delete("q");
    setSearchParams(next, { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);
  const viewportHeight = useVisualViewport();
  const [lastHeight, setLastHeight] = useState(viewportHeight);
  const [savedScroll, setSavedScroll] = useState(0);

  useEffect(() => {
    if (lastHeight && viewportHeight) {
      const delta = viewportHeight - lastHeight;
      // Keyboard Closing (viewport height increases significantly)
      if (delta > 150) {
        window.scrollTo({ top: savedScroll, behavior: "smooth" });
      }
      // Keyboard Opening (viewport height decreases significantly)
      else if (delta < -150) {
        setSavedScroll(window.scrollY);
      }
    }
    setLastHeight(viewportHeight);
  }, [viewportHeight, lastHeight, savedScroll]);

  useEffect(() => {
    if (query.length >= 2 && viewportHeight && viewportHeight < 600) {
      const container = document.getElementById("search-results-container");
      if (container) {
        container.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }
  }, [query, viewportHeight]);

  const tagsRef = React.useRef<HTMLDivElement>(null);

  const saints = useFuzzySearch<Saint>({
    rpc: "search_saints_fuzzy",
    query,
    primaryField: "name",
    secondaryField: "title",
    resultLimit: 10,
  });
  const glossary = useFuzzySearch<GlossaryRow>({
    rpc: "search_glossary_fuzzy",
    query,
    primaryField: "term",
    secondaryField: "definition",
    resultLimit: 10,
  });
  const community = useFuzzySearch<CommunityPost>({
    rpc: "search_community_posts_fuzzy",
    query,
    primaryField: "title",
    secondaryField: "content",
    resultLimit: 10,
  });
  const tags = useFuzzySearch<Tag>({
    rpc: "search_tags_fuzzy",
    query,
    primaryField: "label",
    secondaryField: "category",
    resultLimit: 10,
  });
  const journeys = useFuzzySearch<Journey>({
    rpc: "search_journeys_fuzzy",
    query,
    primaryField: "title",
    secondaryField: "description",
    resultLimit: 10,
  });

  const anyPending =
    saints.isPending ||
    glossary.isPending ||
    community.isPending ||
    tags.isPending ||
    journeys.isPending;
  const hasQuery = query.trim().length >= 2;
  const counts = {
    santos: saints.results?.length ?? 0,
    glossario: glossary.results?.length ?? 0,
    comunidade: community.results?.length ?? 0,
    temas: tags.results?.length ?? 0,
    jornadas: journeys.results?.length ?? 0,
  };
  const isAllEmpty = hasQuery && !anyPending && Object.values(counts).every((c) => c === 0);
  const errors = [saints.error, glossary.error, community.error, tags.error, journeys.error].filter(
    Boolean,
  ) as Error[];
  const hasError = hasQuery && !anyPending && errors.length > 0;
  const retryAll = () => {
    saints.refetch();
    glossary.refetch();
    community.refetch();
    tags.refetch();
    journeys.refetch();
  };
  const clearSearch = () => setQuery("");

  const { activeIndex: tagsActiveIndex, handleKeyDown: handleTagsKeyDown } = useRovingTabindex(
    tags.results?.length || 0,
    tagsRef,
  );

  const EmptyState = ({ text }: { text: string }) => (
    <p className="text-center text-premium-sm text-muted-foreground py-spacing-lg">{text}</p>
