                  variant="default"
                  className="min-h-11"
                >
                  <Icons.BookOpen className="w-4 h-4 mr-2" aria-hidden="true" />
                  Abrir capítulo
                </Button>
                <Button onClick={clearBibleFilter} variant="ghost" className="min-h-11">
                  <Icons.X className="w-4 h-4 mr-2" aria-hidden="true" />
                  Limpar filtro
                </Button>
              </div>
            </motion.div>
          )}

          {anyPending && (
            <div className="mt-spacing-lg">
              <Tabs defaultValue="santos" className="mt-spacing-lg">
                <TabsList className="w-full flex-wrap h-auto gap-spacing-2xs bg-muted/50 p-spacing-2xs rounded-premium-full opacity-60">
                  <TabsTrigger value="santos" disabled className="text-premium-xs flex-1 min-h-11">
                    Santos (...)
                  </TabsTrigger>
                  <TabsTrigger
                    value="glossario"
                    disabled
                    className="text-premium-xs flex-1 min-h-11"
                  >
                    Glossário (...)
                  </TabsTrigger>
                  <TabsTrigger
                    value="comunidade"
                    disabled
                    className="text-premium-xs flex-1 min-h-11"
                  >
                    Comunidade (...)
                  </TabsTrigger>
                </TabsList>

                <div className="mt-spacing-md">
                  <SearchResultSkeleton count={3} />
                </div>
              </Tabs>
            </div>
          )}

          {hasError && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              role="alert"
              aria-live="assertive"
              className="text-center py-spacing-2xl space-y-spacing-md"
            >
              <span className="block mx-auto w-px h-10 bg-destructive/50" aria-hidden="true" />
              <p className="editorial-display text-2xl italic text-foreground">
                A busca não pôde ser concluída.
              </p>
              <p className="text-premium-sm text-muted-foreground/70 max-w-[42ch] mx-auto">
                {errors[0]?.message?.slice(0, 160) ||
                  "Ocorreu um erro ao consultar a sabedoria. Tente novamente em instantes."}
              </p>
              <div className="flex items-center justify-center gap-spacing-sm flex-wrap pt-spacing-xs">
                <Button onClick={retryAll} variant="default" className="min-h-11">
                  <Icons.RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                  Tentar novamente
