import React, { useState, useEffect } from "react";
import { useParams, useNavigate, Link } from "@/lib/rr-compat";
import { motion } from "framer-motion";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Icons } from "@/constants";
import SEOHead from "@/components/SEOHead";
import {
  EditorialKicker,
  EditorialMeta,
  EditorialGoldMarker,
} from "@/components/editorial/primitives";

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { toast } from "sonner";

type ComplementaryReading = { title: string; url?: string; source?: string; note?: string };
type RelatedModule = { label: string; to: string; kind?: string; description?: string };
type ItinerariumMetadata = {
  presentation?: string;
  objectives?: string[];
  prerequisites?: string[];
  complementary_readings?: ComplementaryReading[];
  related_modules?: RelatedModule[];
};

const ItinerariumDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [itinerarium, setItinerarium] = useState<any>(null);
  const [steps, setSteps] = useState<any[]>([]);
  const [completedSteps, setCompletedSteps] = useState<Set<string>>(new Set());
  const [reflections, setReflections] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, user]);

  const loadData = async () => {
    setLoading(true);
    const [itRes, stepsRes] = await Promise.all([
      supabase.from("itineraria").select("*").eq("id", id!).single(),
      supabase
        .from("itineraria_steps")
        .select("*")
        .eq("itinerarium_id", id!)
        .order("step_order", { ascending: true }),
    ]);

    if (itRes.data) setItinerarium(itRes.data);
    if (stepsRes.data) setSteps(stepsRes.data);

    if (user && id) {
      const { data: progress } = await supabase
        .from("itineraria_progress")
        .select("step_id, reflection")
        .eq("user_id", user.id)
        .eq("itinerarium_id", id);

      if (progress) {
        setCompletedSteps(new Set(progress.map((p) => p.step_id)));
        const reflectionsMap: Record<string, string> = {};
        progress.forEach((p) => {
          if (p.reflection) reflectionsMap[p.step_id] = p.reflection;
        });
        setReflections(reflectionsMap);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    if (!user || !id) return;

    const channel = supabase
      .channel("itinerarium_detail_sync")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "itineraria_progress",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          const newData = payload.new as any;
          if (payload.eventType === "INSERT") {
            if (newData?.step_id) {
              setCompletedSteps((prev) => new Set([...Array.from(prev), newData.step_id]));
              if (newData.reflection) {
                setReflections((prev) => ({ ...prev, [newData.step_id]: newData.reflection }));
              }
            }
          } else if (payload.eventType === "UPDATE") {
            if (newData?.step_id && newData.reflection) {
              setReflections((prev) => ({ ...prev, [newData.step_id]: newData.reflection }));
            }
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, id]);

  const exportFullPDF = () => {
    if (!itinerarium || !steps.length) return;

    const doc = new jsPDF();

    doc.setFontSize(26);
    doc.setTextColor(41, 128, 185);
    doc.text(itinerarium.title, 20, 30);

    doc.setFontSize(14);
    doc.setTextColor(100);
    const splitDesc = doc.splitTextToSize(itinerarium.description || "", 170);
    doc.text(splitDesc, 20, 45);

    doc.setFontSize(12);
    doc.text(`Progresso: ${Math.round((completedSteps.size / steps.length) * 100)}%`, 20, 70);

    const tableData = steps.map((step) => [
      `Capítulo ${step.step_order}: ${step.title}`,
      completedSteps.has(step.id) ? "Concluído" : "Pendente",
      reflections[step.id] || "-",
    ]);

    autoTable(doc, {
      startY: 80,
      head: [["Capítulo", "Status", "Minhas Reflexões"]],
      body: tableData,
      theme: "striped",
      headStyles: { fillColor: [41, 128, 185] },
      styles: { font: "helvetica", fontSize: 10 },
      columnStyles: {
        0: { cellWidth: 60 },
        1: { cellWidth: 30 },
        2: { cellWidth: 90 },
      },
    });

    doc.save(`trilha-${itinerarium.title.toLowerCase().replace(/\s+/g, "-")}.pdf`);
    toast.success("PDF da trilha gerado com sucesso!");
  };

  if (loading || !itinerarium) {
    return (
      <div className="w-full py-spacing-4xl space-y-spacing-lg" aria-busy="true">
        <div className="h-6 w-40 rounded-full bg-muted/40 animate-pulse" />
        <div className="h-16 w-3/4 rounded-lg bg-muted/40 animate-pulse" />
        <div className="h-4 w-full rounded bg-muted/30 animate-pulse" />
        <div className="h-4 w-5/6 rounded bg-muted/30 animate-pulse" />
      </div>
    );
  }

  const metadata: ItinerariumMetadata = (itinerarium.metadata ?? {}) as ItinerariumMetadata;
  const progress = steps.length ? (completedSteps.size / steps.length) * 100 : 0;
  const firstIncompleteIdx = steps.findIndex((s) => !completedSteps.has(s.id));
  const resumeStep = firstIncompleteIdx >= 0 ? steps[firstIncompleteIdx] : steps[0];
  const isComplete = steps.length > 0 && completedSteps.size === steps.length;

  return (
    <>
      <SEOHead
        title={`${itinerarium.title} — Trilha de Formação`}
        description={itinerarium.description}
        path={`/itineraria/${id}`}
      />

      <div className="w-full py-spacing-2xl md:py-spacing-3xl space-y-spacing-4xl">
        {/* Breadcrumb / Voltar */}
        <motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }}>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate("/itineraria")}
            className="group gap-spacing-xs text-[10px] font-black uppercase tracking-widest text-muted-foreground/60 hover:text-primary transition-colors"
          >
            <Icons.ArrowLeft className="w-spacing-sm h-spacing-sm group-hover:-translate-x-0.5 transition-transform" />
            Voltar para Trilhas
          </Button>
        </motion.div>

        {/* HERO EDITORIAL */}
        <header className="relative overflow-hidden rounded-[2.5rem] border border-primary/10 bg-gradient-to-br from-primary/[0.03] via-background to-primary/[0.02] p-spacing-2xl md:p-spacing-4xl">
          <div
            aria-hidden
            className="absolute inset-0 pointer-events-none opacity-[0.04]"
            style={{
              backgroundImage:
                "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence baseFrequency='0.9' /></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.5'/></svg>\")",
            }}
          />
          <div className="relative z-10 space-y-spacing-xl max-w-[68ch]">
            <EditorialKicker>
              CATHEDRA · TRILHA {itinerarium.category ? `· ${itinerarium.category}` : ""}
            </EditorialKicker>

            <h1 className="font-serif text-premium-4xl md:text-premium-6xl leading-[1.05] tracking-tight text-foreground">
              {itinerarium.title}
            </h1>

            {itinerarium.subtitle && (
              <p className="font-sans text-premium-lg md:text-premium-xl text-muted-foreground leading-relaxed">
                {itinerarium.subtitle}
              </p>
            )}

            <EditorialGoldMarker />

            <div className="flex flex-wrap items-center gap-x-spacing-lg gap-y-spacing-xs">
              <EditorialMeta>{steps.length} capítulos</EditorialMeta>
              <EditorialMeta>{itinerarium.estimated_days} dias</EditorialMeta>
              <EditorialMeta>Nível · {itinerarium.difficulty || "—"}</EditorialMeta>
            </div>

            <div className="flex flex-wrap items-center gap-spacing-sm pt-spacing-md">
              {resumeStep && (
                <Button
                  size="lg"
                  className="rounded-premium-full gap-spacing-xs bg-primary text-primary-foreground shadow-premium hover:opacity-90"
                  onClick={() => navigate(`/itineraria/${id}/step?step=${resumeStep.id}`)}
                >
                  {completedSteps.size === 0
                    ? "Iniciar Trilha"
                    : isComplete
                      ? "Revisitar Trilha"
                      : "Continuar de onde parei"}
                  <Icons.ChevronRight className="w-spacing-md h-spacing-md" />
                </Button>
              )}
              <Button
                variant="outline"
                size="lg"
                onClick={exportFullPDF}
                className="rounded-premium-full gap-spacing-xs border-primary/20 text-[11px] font-black uppercase tracking-widest"
              >
                <Icons.FileDown className="w-spacing-md h-spacing-md" /> Exportar Reflexões
              </Button>
            </div>
          </div>
        </header>

        {/* PROGRESSO */}
        {user && steps.length > 0 && (
          <section aria-label="Progresso da trilha" className="space-y-spacing-md">
            <div className="flex items-baseline justify-between gap-spacing-md">
              <EditorialKicker>Progresso</EditorialKicker>
              <span className="font-sans text-premium-sm text-muted-foreground">
                {completedSteps.size} de {steps.length} · {Math.round(progress)}%
              </span>
            </div>
            <Progress value={progress} className="h-2 bg-primary/5" />
          </section>
        )}

        {/* APRESENTAÇÃO */}
        {(metadata.presentation || itinerarium.description) && (
          <section className="space-y-spacing-lg max-w-[68ch]">
            <EditorialKicker>Apresentação</EditorialKicker>
            <div className="font-serif text-premium-lg md:text-premium-xl leading-[1.75] text-foreground/90 whitespace-pre-line">
              {metadata.presentation || itinerarium.description}
            </div>
          </section>
        )}

        {/* OBJETIVOS + PRÉ-REQUISITOS */}
        {(metadata.objectives?.length || metadata.prerequisites?.length) && (
          <section className="grid gap-spacing-xl md:grid-cols-2">
            {metadata.objectives?.length ? (
              <Card className="premium-card rounded-[2rem] border-primary/10 bg-primary/[0.02]">
                <CardContent className="p-spacing-xl space-y-spacing-md">
                  <div className="flex items-center gap-spacing-xs">
                    <Icons.Target className="w-spacing-md h-spacing-md text-primary" />
                    <EditorialKicker>Objetivos</EditorialKicker>
                  </div>
                  <ul className="space-y-spacing-sm font-sans text-premium-base leading-relaxed">
                    {metadata.objectives.map((obj, i) => (
                      <li key={i} className="flex gap-spacing-sm">
                        <Icons.Check className="w-4 h-4 mt-1 flex-shrink-0 text-primary" />
                        <span>{obj}</span>
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            ) : null}

            {metadata.prerequisites?.length ? (
              <Card className="premium-card rounded-[2rem] border-primary/10 bg-background">
                <CardContent className="p-spacing-xl space-y-spacing-md">
                  <div className="flex items-center gap-spacing-xs">
                    <Icons.BookOpen className="w-spacing-md h-spacing-md text-primary" />
                    <EditorialKicker>Pré-requisitos</EditorialKicker>
                  </div>
                  <ul className="space-y-spacing-sm font-sans text-premium-base leading-relaxed text-muted-foreground">
                    {metadata.prerequisites.map((req, i) => (
                      <li key={i} className="flex gap-spacing-sm">
                        <span className="text-primary/60 mt-1">·</span>
                        <span>{req}</span>
                      </li>
                    ))}
                  </ul>
                </CardContent>
              </Card>
            ) : null}
          </section>
        )}

        {/* CAPÍTULOS */}
        <section className="space-y-spacing-xl">
          <div className="flex items-center gap-spacing-md">
            <EditorialKicker>Capítulos</EditorialKicker>
            <div className="flex-1 h-px bg-primary/10" />
          </div>

          <ol className="space-y-spacing-md" aria-label="Lista de capítulos da trilha">
            {steps.map((step, idx) => {
              const isCompleted = completedSteps.has(step.id);
              const isLocked = !isCompleted && idx > 0 && !completedSteps.has(steps[idx - 1].id);

              return (
                <motion.li
                  key={step.id}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: idx * 0.04 }}
                >
                  <Card
                    className={`premium-card transition-all duration-500 border-primary/5 rounded-[1.75rem] shadow-premium-none group ${
                      isLocked
                        ? "opacity-40 grayscale pointer-events-none"
                        : "hover:border-primary/25 hover:bg-primary/[0.02]"
                    } ${isCompleted ? "bg-primary/[0.03]" : ""}`}
                  >
                    <CardContent className="p-spacing-lg md:p-spacing-xl flex items-center justify-between gap-spacing-lg">
                      <div className="flex items-center gap-spacing-lg flex-1 min-w-0">
                        <div
                          className={`w-12 h-12 rounded-full flex-shrink-0 flex items-center justify-center font-serif text-premium-lg transition-all ${
                            isCompleted
                              ? "bg-primary text-primary-foreground shadow-premium"
                              : "bg-primary/5 text-primary/70 border border-primary/15"
                          }`}
                          aria-hidden
                        >
                          {isCompleted ? (
                            <Icons.Check className="w-5 h-5" />
                          ) : (
                            <span>{idx + 1}</span>
                          )}
                        </div>

                        <div className="flex-1 min-w-0 space-y-spacing-2xs">
                          <div className="flex items-center gap-spacing-xs">
                            <h3 className="font-serif text-premium-lg md:text-premium-xl text-foreground truncate">
                              {step.title}
                            </h3>
                            {!step.is_free && (
                              <Icons.Lock
                                className="w-4 h-4 text-primary/60"
                                aria-label="Conteúdo premium"
                              />
                            )}
                          </div>
                          {step.subtitle && (
                            <p className="font-sans text-premium-sm text-muted-foreground line-clamp-1">
                              {step.subtitle}
                            </p>
                          )}
                          <div className="flex items-center gap-spacing-sm text-[10px] font-black uppercase tracking-widest text-muted-foreground/60">
                            <span className="flex items-center gap-spacing-2xs">
                              <Icons.Clock className="w-3 h-3" />
                              {step.duration_minutes} min
                            </span>
                            <span aria-hidden>·</span>
                            <span>{step.step_type}</span>
                          </div>
                        </div>
                      </div>

                      {!isLocked && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => navigate(`/itineraria/${id}/step?step=${step.id}`)}
                          className="group/btn h-10 px-spacing-lg rounded-premium-full border border-primary/10 hover:bg-primary hover:text-primary-foreground transition-all text-[10px] font-black uppercase tracking-widest"
                        >
                          {isCompleted ? "Revisitar" : "Iniciar"}
                          <Icons.ChevronRight className="w-4 h-4 ml-1 group-hover/btn:translate-x-0.5 transition-transform" />
                        </Button>
                      )}
                    </CardContent>
                  </Card>
                </motion.li>
              );
            })}
          </ol>
        </section>

        {/* LEITURA COMPLEMENTAR */}
        {metadata.complementary_readings?.length ? (
          <section className="space-y-spacing-lg">
            <div className="flex items-center gap-spacing-md">
              <EditorialKicker>Leitura Complementar</EditorialKicker>
              <div className="flex-1 h-px bg-primary/10" />
            </div>
            <ul className="grid gap-spacing-md md:grid-cols-2">
              {metadata.complementary_readings.map((r, i) => {
                const inner = (
                  <Card className="premium-card h-full rounded-[1.5rem] border-primary/10 hover:border-primary/30 transition-colors">
                    <CardContent className="p-spacing-lg space-y-spacing-xs">
                      <div className="flex items-start gap-spacing-sm">
                        <Icons.BookOpen className="w-4 h-4 mt-1 text-primary flex-shrink-0" />
                        <div className="flex-1 min-w-0">
                          <h4 className="font-serif text-premium-lg text-foreground leading-snug">
                            {r.title}
                          </h4>
                          {r.source && (
                            <p className="font-sans text-[10px] font-black uppercase tracking-widest text-muted-foreground/60 mt-1">
                              {r.source}
                            </p>
                          )}
                          {r.note && (
                            <p className="font-sans text-premium-sm text-muted-foreground mt-2 leading-relaxed">
                              {r.note}
                            </p>
                          )}
                        </div>
                        {r.url && (
                          <Icons.ExternalLink className="w-4 h-4 text-primary/60 flex-shrink-0" />
                        )}
                      </div>
                    </CardContent>
                  </Card>
                );
                return (
                  <li key={i}>
                    {r.url ? (
                      <a
                        href={r.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="block focus:outline-none focus:ring-2 focus:ring-primary/40 rounded-[1.5rem]"
                      >
                        {inner}
                      </a>
                    ) : (
                      inner
                    )}
                  </li>
                );
              })}
            </ul>
          </section>
        ) : null}

        {/* CONEXÕES / MÓDULOS RELACIONADOS */}
        {metadata.related_modules?.length ? (
          <section className="space-y-spacing-lg">
            <div className="flex items-center gap-spacing-md">
              <EditorialKicker>Conexões</EditorialKicker>
              <div className="flex-1 h-px bg-primary/10" />
            </div>
            <div className="flex flex-wrap gap-spacing-sm">
              {metadata.related_modules.map((m, i) => (
                <Link
                  key={i}
                  to={m.to}
                  className="group inline-flex items-center gap-spacing-xs rounded-premium-full border border-primary/15 bg-primary/[0.02] px-spacing-md py-spacing-sm hover:border-primary/40 hover:bg-primary/[0.05] transition-colors focus:outline-none focus:ring-2 focus:ring-primary/40"
                >
                  {m.kind && (
                    <Badge
                      variant="outline"
                      className="text-[9px] font-black uppercase tracking-widest border-primary/20 text-primary/70"
                    >
                      {m.kind}
                    </Badge>
                  )}
                  <span className="font-serif text-premium-base text-foreground group-hover:text-primary transition-colors">
                    {m.label}
                  </span>
                  <Icons.ArrowUpRight className="w-3.5 h-3.5 text-primary/60 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
                </Link>
              ))}
            </div>
          </section>
        ) : null}
      </div>
    </>
  );
};

export default ItinerariumDetailPage;

import React, { useState, useEffect, useMemo, useRef, useCallback } from "react";
import { createPortal } from "react-dom";
import { useParams, useNavigate, useSearchParams } from "@/lib/rr-compat";
import { motion, AnimatePresence } from "framer-motion";

import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import Relatio from "./Relatio";
import LogosAI from "./LogosAI";
import { Icons } from "@/constants";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { useSwipeNavigation } from "@/hooks/useSwipeNavigation";
import { useReadingSettings } from "@/contexts/ReadingSettingsContext";
import { useReadingMarks } from "@/hooks/useReadingMarks";
import { useIsMobile } from "@/hooks/use-mobile";
import DOMPurify from "dompurify";

const ItinerariumStepPage: React.FC = () => {
  const { id: itinerariumId } = useParams<{ id: string }>();
  const [searchParams] = useSearchParams();
  const stepId = searchParams.get("step");
  const navigate = useNavigate();
  const { user } = useAuth();

  const [step, setStep] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [completed, setCompleted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [reflection, setReflection] = useState("");
  const [isLogosOpen, setIsLogosOpen] = useState(false);
  const [logosQuery, setLogosQuery] = useState("");
  const [allSteps, setAllSteps] = useState<any[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(-1);
  const { settings } = useReadingSettings();
  const { saveLastRead } = useReadingMarks();
  const isMobile = useIsMobile();
  const autoSaveTimer = useRef<number | null>(null);
  const lastSavedReflection = useRef<string>("");

  // Auto-save reflexão (debounced) e progresso de leitura local
  useEffect(() => {
    if (!user || !stepId || reflection === lastSavedReflection.current) return;
    if (autoSaveTimer.current) window.clearTimeout(autoSaveTimer.current);
    autoSaveTimer.current = window.setTimeout(async () => {
      try {
        await supabase.from("itineraria_progress").upsert(
          {
            user_id: user.id,
            itinerarium_id: itinerariumId!,
            step_id: stepId,
            reflection: reflection || null,
            completed_at: completed ? new Date().toISOString() : new Date().toISOString(),
          },
          { onConflict: "user_id,step_id" },
        );
        lastSavedReflection.current = reflection;
      } catch (e) {
        console.warn("auto-save reflection failed", e);
      }
    }, 1500);
    return () => {
      if (autoSaveTimer.current) window.clearTimeout(autoSaveTimer.current);
    };
  }, [reflection, user, stepId, itinerariumId, completed]);

  // Persistir último ponto visitado (retomada natural sincronizada)
  useEffect(() => {
    if (!stepId || !itinerariumId || !step?.title) return;

    const persistReadingMark = async () => {
      try {
        // Local fallback
        localStorage.setItem(
          "cathedra:last-itineraria-step",
          JSON.stringify({
            itinerariumId,
            stepId,
            at: Date.now(),
          }),
        );

        // Sync to DB for global resumption
        await saveLastRead({
          content_type: "itinerarium",
          content_id: stepId,
          label: `${step.title} (Itinerarium)`,
          url: `/itineraria/${itinerariumId}/step?step=${stepId}`,
          is_last_read: true,
        });

        // Update general history
        await supabase.from("user_history").insert({
          user_id: user?.id,
          title: step.title,
          route: `/itineraria/${itinerariumId}/step?step=${stepId}`,
          type: "itinerarium",
        } as any);
      } catch (e) {
        console.warn("Failed to persist reading mark", e);
      }
    };

    persistReadingMark();
  }, [stepId, itinerariumId, step?.title, user?.id]);

  useEffect(() => {
    if (stepId) {
      loadStep();
      loadAllSteps();
    }
  }, [stepId, user]);

  const loadAllSteps = async () => {
    if (!itinerariumId) return;
    const { data } = await supabase
      .from("itineraria_steps")
      .select("id, title, step_order")
      .eq("itinerarium_id", itinerariumId)
      .order("step_order", { ascending: true });

    if (data) {
      setAllSteps(data);
      setCurrentStepIndex(data.findIndex((s) => s.id === stepId));
    }
  };

  const loadStep = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("itineraria_steps")
        .select("*")
        .eq("id", stepId!)
        .single();

      if (data) setStep(data);

      if (user && stepId) {
        const { data: progress } = await supabase
          .from("itineraria_progress")
          .select("*")
          .eq("user_id", user.id)
          .eq("step_id", stepId)
          .maybeSingle();

        if (progress) {
          setCompleted(true);
          setReflection(progress.reflection || "");
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const checkAchievements = async () => {
    if (!user) return;

    // Icons.Check total steps completed
    const { count } = await supabase
      .from("itineraria_progress")
      .select("*", { count: "exact", head: true })
      .eq("user_id", user.id);

    if (count) {
      const { data: achievements } = await supabase
        .from("achievements")
        .select("*")
        .eq("requirement_type", "steps_completed")
        .lte("requirement_value", count);

      if (achievements) {
        for (const ach of achievements) {
          await supabase.from("user_achievements").upsert(
            {
              user_id: user.id,
              achievement_id: ach.id,
            },
            { onConflict: "user_id,achievement_id" },
          );
        }
      }
    }

    // Update weekly goals
    const today = new Date();
    const day = today.getDay();
    const diff = today.getDate() - day + (day === 0 ? -6 : 1);
    const weekStart = new Date(today.setDate(diff)).toISOString().split("T")[0];

    const { data: goal } = await supabase
      .from("weekly_goals_history")
      .select("*")
      .eq("user_id", user.id)
      .eq("week_start_date", weekStart)
      .maybeSingle();

    if (goal) {
      await supabase
        .from("weekly_goals_history")
        .update({ achieved_count: goal.achieved_count + 1 })
        .eq("id", goal.id);
    }
  };

  const handleComplete = async () => {
    if (!user || !stepId || !itinerariumId) return;
    setSaving(true);
    try {
      const { error } = await supabase.from("itineraria_progress").upsert(
        {
          user_id: user.id,
          itinerarium_id: itinerariumId,
          step_id: stepId,
          reflection: reflection.trim() || null,
          completed_at: new Date().toISOString(),
        },
        { onConflict: "user_id,step_id" },
      );

      if (error) throw error;

      await checkAchievements();

      setCompleted(true);
      toast.success("Passo concluído! Caminhada honrada.");
    } catch (err) {
      console.error(err);
      toast.error("Erro ao salvar progresso.");
    } finally {
      setSaving(false);
    }
  };

  // Real-time sync subscription
  useEffect(() => {
    if (!user || !stepId) return;

    const channel = supabase
      .channel(`itinerarium_step_sync_${stepId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "itineraria_progress",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          if (payload.eventType === "INSERT" || payload.eventType === "UPDATE") {
            const newData = payload.new as any;
            if (newData && newData.step_id === stepId) {
              setCompleted(true);
              setReflection(newData.reflection || "");
              lastSavedReflection.current = newData.reflection || "";
            }
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, stepId]);

  const navigateToStep = useCallback(
    (index: number) => {
      const targetStep = allSteps[index];
      if (targetStep) {
        navigate(`/itineraria/${itinerariumId}/step?step=${targetStep.id}`);
      }
    },
    [allSteps, itinerariumId, navigate],
  );

  // Navegação por gestos (mobile) e tap-to-reveal da UI
  const revealTimer = useRef<number | null>(null);
  const revealChrome = useCallback(() => {
    document.documentElement.classList.add("reveal-chrome");
    if (revealTimer.current) window.clearTimeout(revealTimer.current);
    revealTimer.current = window.setTimeout(() => {
      document.documentElement.classList.remove("reveal-chrome");
    }, 2800);
  }, []);

  useSwipeNavigation({
    enabled: isMobile,
    onSwipeLeft: () => {
      if (currentStepIndex >= 0 && currentStepIndex < allSteps.length - 1) {
        navigateToStep(currentStepIndex + 1);
      }
    },
    onSwipeRight: () => {
      if (currentStepIndex > 0) {
        navigateToStep(currentStepIndex - 1);
      }
    },
    onTap: () => {
      if (settings.autoHideUI || settings.contemplativeMode) revealChrome();
    },
  });

  const exportStepPDF = () => {
    if (!step) return;
    const doc = new jsPDF();

    // Header
    doc.setFontSize(22);
    doc.setTextColor(41, 128, 185);
    doc.text(step.title, 20, 30);

    doc.setFontSize(12);
    doc.setTextColor(100);
    doc.text(`Itinerarium Step ${step.step_order} - ${step.step_type}`, 20, 40);

    // Content
    doc.setTextColor(0);
    doc.setFontSize(14);
    doc.text("Sua Reflexão:", 20, 60);

    doc.setFontSize(12);
    const splitReflection = doc.splitTextToSize(reflection || "Nenhuma reflexão registrada.", 170);
    doc.text(splitReflection, 20, 70);

    doc.save(`reflexao-${step.title.toLowerCase().replace(/\s+/g, "-")}.pdf`);
    toast.success("PDF gerado com sucesso!");
  };

  if (loading || !step)
    return <div className="p-spacing-4xl text-center">Iniciando passo contemplativo...</div>;

  return createPortal(
    <div className="fixed inset-0 bg-background z-[200] flex flex-col overflow-hidden">
      <div
        data-reading-chrome
        className="reading-chrome px-spacing-lg py-spacing-md border-b border-border/50 flex items-center justify-between bg-background/80 backdrop-blur-xl"
      >
        <div className="flex items-center gap-spacing-md">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => navigate(`/itineraria/${itinerariumId}`)}
            aria-label="Voltar para o itinerário"
          >
            <Icons.X className="w-spacing-md h-spacing-md text-primary" />
          </Button>
          <div className="space-y-spacing-3xs" aria-live="polite">
            <h1 className="text-premium-sm font-bold truncate max-w-[200px] text-primary">
              {step.title}
            </h1>
            <p className="text-[10px] text-foreground font-bold uppercase tracking-widest flex items-center gap-spacing-xs">
              <Icons.Clock className="w-spacing-sm h-spacing-sm text-primary" />{" "}
              {step.duration_minutes} min • Passo {step.step_order}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-spacing-xs">
          <Button
            variant="ghost"
            size="sm"
            className="gap-spacing-xs text-[10px] font-black uppercase tracking-widest hidden md:flex"
            onClick={exportStepPDF}
          >
            <Icons.FileText className="w-spacing-sm h-spacing-sm" /> PDF
          </Button>
          <Button
            variant="outline"
            size="sm"
            className="gap-spacing-xs text-[10px] font-black uppercase tracking-widest border-primary/20"
            onClick={() => setIsLogosOpen(true)}
          >
            <Icons.Sparkles className="w-spacing-sm h-spacing-sm text-primary" /> Logos IA
          </Button>
        </div>
      </div>

      <div
        className="flex-1 overflow-y-auto custom-scrollbar"
        data-side-margins={settings.sideMargins}
        style={{ maxWidth: `${settings.columnWidth}ch`, margin: "0 auto" }}
      >
        <div className="mx-auto px-spacing-md md:px-spacing-lg py-spacing-2xl space-y-spacing-2xl pb-spacing-4xl reader-text">
          <header className="text-center space-y-spacing-md">
            <Badge variant="outline" className="text-primary/60 border-primary/10">
              {step.step_type}
            </Badge>
            <h2 className="text-premium-3xl font-display font-bold leading-tight">
              {step.subtitle || step.title}
            </h2>
          </header>

          <article className="prose prose-premium dark:prose-invert max-w-none font-serif text-premium-lg md:text-premium-xl leading-[1.8] text-foreground/90 selection:bg-primary/10">
            <div
              className="space-y-spacing-lg"
              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(step.content.html || "") }}
            />
            {!step.content.html && (
              <div className="flex flex-col items-center justify-center py-spacing-3xl space-y-spacing-lg opacity-30">
                <Icons.Sparkles className="w-spacing-2xl h-spacing-2xl animate-pulse" />
                <p className="italic text-center font-serif">
                  O conteúdo deste passo está sendo preparado em silêncio...
                </p>
              </div>
            )}
          </article>

          <div className="space-y-spacing-md pt-spacing-2xl border-t border-border/10">
            <div className="flex items-center gap-spacing-xs text-primary">
              <Icons.PenLine className="w-spacing-md h-spacing-md" />
              <h3 className="text-premium-sm font-black uppercase tracking-widest">Sua Reflexão</h3>
            </div>
            <textarea
              className="w-full bg-muted/30 border border-border/50 rounded-premium p-spacing-lg font-serif italic focus:ring-2 focus:ring-primary/20 outline-none min-h-[150px] transition-all"
              placeholder="O que o Espírito diz ao seu coração hoje?"
              value={reflection}
              onChange={(e) => setReflection(e.target.value)}
            />
          </div>

          <Relatio
            context={{
              type: "theme",
              tags: step.content.tags || [],
              id: step.id,
            }}
            onSelectLogosQuery={(query) => {
              setLogosQuery(query);
              setIsLogosOpen(true);
            }}
          />
        </div>
      </div>

      <div
        data-reading-chrome
        className="reading-chrome fixed bottom-spacing-0 left-0 right-0 p-spacing-lg bg-gradient-to-t from-background via-background to-transparent pointer-events-none"
      >
        <div className="max-w-spacing-2xl mx-auto flex items-center justify-between gap-spacing-md pointer-events-auto">
          <Button
            variant="outline"
            size="lg"
            className="rounded-premium-full w-spacing-2xl h-spacing-2xl p-spacing-0 flex-shrink-0 border-primary/20 hover:border-primary/40 bg-background/50"
            disabled={currentStepIndex <= 0}
            onClick={() => navigateToStep(currentStepIndex - 1)}
            aria-label="Passo anterior"
          >
            <Icons.ChevronLeft className="w-spacing-lg h-spacing-lg" />
          </Button>

          <Button
            className="flex-1 h-spacing-2xl rounded-premium-full shadow-premium text-premium-sm font-black uppercase tracking-[0.2em] bg-primary text-primary-foreground hover:opacity-90"
            onClick={handleComplete}
            disabled={saving}
          >
            {completed ? "Passo Concluído" : saving ? "Salvando..." : "Concluir Passo"}
          </Button>

          <Button
            variant="outline"
            size="lg"
            className="rounded-premium-full w-spacing-2xl h-spacing-2xl p-spacing-0 flex-shrink-0 border-primary/20 hover:border-primary/40 bg-background/50"
            disabled={currentStepIndex === -1 || currentStepIndex >= allSteps.length - 1}
            onClick={() => navigateToStep(currentStepIndex + 1)}
            aria-label="Próximo passo"
          >
            <Icons.ChevronRight className="w-spacing-lg h-spacing-lg" />
          </Button>
        </div>
      </div>

      <LogosAI
        isOpen={isLogosOpen}
        onClose={() => setIsLogosOpen(false)}
        initialQuery={logosQuery}
        context={`itineraria_step_${step.id}`}
      />
    </div>,
    document.body,
  );
};

export default ItinerariumStepPage;

/**
 * JornadaCompletePage — refino editorial Logos 2030.
 *
 * Preserva integralmente lógica de recompensas (XP/badges), reflexões,
 * próxima jornada e compartilhamento do certificado. Realinha o visual
 * ao padrão stitch-* usado em /jornadas e no leitor de passo.
 */

import React, { useEffect, useRef, useState } from "react";
import { useParams, useNavigate, Link } from "@/lib/rr-compat";
import { Helmet } from "@/lib/helmet-compat";
import { motion } from "framer-motion";
import { toast } from "sonner";
import {
  ArrowLeft,
  ArrowRight,
  Award,
  BookOpen,
  ChevronRight,
  Circle,
  Eye,
  Quote,
  Share2,
  Sparkles,
  Star,
  Zap,
} from "lucide-react";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { AppRoute } from "@/types";
import { checkNewBadges, getBadgeById, BadgeContext } from "@/lib/badges";
import { useNextPath } from "@/hooks/useNextPath";
import NextPathPanel from "@/components/cathedra/NextPathPanel";

const JornadaCompletePage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [journey, setJourney] = useState<any>(null);
  const [reflections, setReflections] = useState<
    { title: string; reflection: string; completed_at: string }[]
  >([]);

  const [loading, setLoading] = useState(true);
  const [sharing, setSharing] = useState(false);
  const [xpAwarded, setXpAwarded] = useState(0);
  const [newBadges, setNewBadges] = useState<string[]>([]);
  const [rewardsProcessed, setRewardsProcessed] = useState(false);
  const [totalSteps, setTotalSteps] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(0);
  const [pendingSteps, setPendingSteps] = useState<
    { id: string; title: string; step_order: number }[]
  >([]);
  const [showPreview, setShowPreview] = useState(false);
  const certificateRef = useRef<HTMLDivElement>(null);

  const isJourneyComplete = totalSteps > 0 && completedSteps >= totalSteps;

  // Nexus Intelligence: próximo caminho coerente após esta jornada.
  const nextPath = useNextPath(
    journey && isJourneyComplete
      ? {
          id: journey.id,
          slug: journey.slug ?? null,
          title: journey.title,
          subtitle: journey.subtitle,
          category: journey.category,
          tags: journey.tags,
          difficulty: journey.difficulty,
          sort_order: journey.sort_order,
        }
      : null,
    user?.id,
  );
  const hasCertificateData = !!journey?.title;
  const canShareCertificate = hasCertificateData && isJourneyComplete;

  useEffect(() => {
    if (id && user) loadData();
  }, [id, user]);

  useEffect(() => {
    if (!loading && journey) {
      import("canvas-confetti").then((mod) => {
        mod.default({
          particleCount: 180,
          spread: 110,
          origin: { y: 0.4 },
          colors: ["#c9a84c", "#e8c547", "#b8860b", "#0B1F3A"],
        });
      });
    }
  }, [loading, journey]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [journeyRes, progressRes, totalRes] = await Promise.all([
        supabase.from("journeys").select("*").eq("id", id!).single(),
        supabase
          .from("journey_progress")
          .select("reflection, completed_at, step_id")
          .eq("user_id", user!.id)
          .eq("journey_id", id!)
          .order("completed_at", { ascending: true }),
        supabase
          .from("journey_steps")
          .select("*", { count: "exact", head: true })
          .eq("journey_id", id!),
      ]);

      if (journeyRes.data) setJourney(journeyRes.data);
      setTotalSteps(totalRes.count || 0);
      setCompletedSteps(progressRes.data?.length || 0);

      // Buscar TODAS as etapas para calcular pendentes + títulos das reflexões
      const { data: allSteps } = await supabase
        .from("journey_steps")
        .select("id, title, step_order")
        .eq("journey_id", id!)
        .order("step_order", { ascending: true });

      const doneIds = new Set(progressRes.data?.map((p) => p.step_id) || []);
      if (allSteps) {
        setPendingSteps(allSteps.filter((s) => !doneIds.has(s.id)));
      }

      if (progressRes.data) {
        const stepMap = new Map(allSteps?.map((s) => [s.id, s.title]) || []);
        setReflections(
          progressRes.data
            .filter((p) => p.reflection)
            .map((p) => ({
              title: stepMap.get(p.step_id) || "Etapa",
              reflection: p.reflection!,
              completed_at: p.completed_at,
            })),
        );
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (!loading && journey && user && !rewardsProcessed) {
      processRewards();
    }
  }, [loading, journey, user, rewardsProcessed]);

  const processRewards = async () => {
    if (!user) return;
    setRewardsProcessed(true);
    try {
      const { data: profile } = await supabase
        .from("profiles")
        .select("xp, badges, streak, completed_books, total_minutes_read")
        .eq("id", user.id)
        .single();
      if (!profile) return;

      const { data: allJourneys } = await supabase
        .from("journeys")
        .select("id")
        .eq("is_active", true);

      let completedJourneyCount = 0;
      if (allJourneys) {
        for (const j of allJourneys) {
          const { count: totalSteps } = await supabase
            .from("journey_steps")
            .select("*", { count: "exact", head: true })
            .eq("journey_id", j.id);
          const { count: doneSteps } = await supabase
            .from("journey_progress")
            .select("*", { count: "exact", head: true })
            .eq("user_id", user.id)
            .eq("journey_id", j.id);
          if (totalSteps && doneSteps && doneSteps >= totalSteps) {
            completedJourneyCount++;
          }
        }
      }

      const xpGain = 100;
      const newXp = (profile.xp || 0) + xpGain;
      setXpAwarded(xpGain);

      const ctx: BadgeContext = {
        completedBooks: new Set(profile.completed_books || []),
        chaptersRead: {},
        totalMinutesRead: profile.total_minutes_read || 0,
        streak: profile.streak || 0,
        completedJourneys: completedJourneyCount,
      };

      const earned = checkNewBadges(profile.badges || [], ctx);
      setNewBadges(earned);

      const updatedBadges = [...(profile.badges || []), ...earned];
      await supabase
        .from("profiles")
        .update({ xp: newXp, badges: updatedBadges })
        .eq("id", user.id);

      earned.forEach((badgeId) => {
        const badge = getBadgeById(badgeId);
        if (badge) {
          toast.success(`${badge.icon} Nova conquista: ${badge.name}!`, {
            description: badge.description,
            duration: 5000,
          });
        }
      });
    } catch (err) {
      console.error("Rewards error:", err);
    }
  };

  const shareCertificate = async () => {
    if (!certificateRef.current) return;
    if (!canShareCertificate) {
      toast.error(
        !hasCertificateData
          ? "Dados da jornada indisponíveis."
          : "Conclua todas as etapas antes de compartilhar o certificado.",
      );
      return;
    }
    setSharing(true);
    try {
      const { default: html2canvas } = await import("html2canvas");
      const canvas = await html2canvas(certificateRef.current, {
        backgroundColor: null,
        scale: 2,
        useCORS: true,
      });
      const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"));
      if (!blob) throw new Error("Failed to generate image");

      const file = new File(
        [blob],
        `cathedra-certificado-${journey.title.replace(/\s+/g, "-").toLowerCase()}.png`,
        { type: "image/png" },
      );

      if (navigator.share && navigator.canShare?.({ files: [file] })) {
        await navigator.share({
          title: `Certificado: ${journey.title}`,
          text: `Concluí a jornada "${journey.title}" no Cathedra.`,
          files: [file],
        });
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = file.name;
        a.click();
        URL.revokeObjectURL(url);
        toast.success("Certificado salvo como imagem.");
      }
    } catch (err: any) {
      if (err?.name !== "AbortError") {
        toast.error("Erro ao compartilhar certificado");
      }
    } finally {
      setSharing(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen w-full bg-stitch-background">
        <div className="mx-auto max-w-[900px] px-5 pt-16 md:px-16">
          <div className="h-4 w-32 animate-pulse bg-stitch-surface-container-high" />
          <div className="mt-8 h-[280px] w-full animate-pulse border border-stitch-outline-variant/20 bg-stitch-surface-container-lowest" />
          <div className="mt-8 h-16 w-full animate-pulse bg-stitch-surface-container-high" />
        </div>
      </div>
    );
  }

  if (!journey) return null;

  const completionDate = new Date().toLocaleDateString("pt-BR", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });

  return (
    <div
      className="min-h-screen w-full bg-stitch-background text-stitch-on-background"
      style={{
        backgroundImage: 'url("https://www.transparenttextures.com/patterns/p6.png")',
      }}
    >
      <Helmet>
        <title>Jornada concluída — {journey.title} — Cathedra</title>
      </Helmet>

      <section className="mx-auto w-full max-w-[900px] px-5 pb-24 pt-8 md:px-16 md:pt-12 animate-fade-in">
        {/* Breadcrumb */}
        <Link
          to={AppRoute.JORNADAS}
          className="inline-flex items-center gap-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant transition-colors hover:text-stitch-secondary"
        >
          <ArrowLeft className="h-3 w-3" /> Formação
        </Link>

        {/* Kicker de conclusão */}
        <div className="mt-6 flex items-center gap-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.32em] text-stitch-secondary">
          <Sparkles className="h-3 w-3" /> Jornada Concluída
        </div>
        <h1 className="mt-2 font-stitch-display text-[32px] italic leading-[40px] text-stitch-primary md:text-[48px] md:leading-[58px] md:tracking-[-0.02em]">
          Deo gratias.
        </h1>
        <p className="mt-3 max-w-[62ch] font-stitch-body text-[16px] leading-[28px] text-stitch-on-surface-variant md:text-[18px] md:leading-[30px]">
          Você percorreu <span className="italic text-stitch-primary">{journey.title}</span>. Que o
          que foi lido se torne oração, e o que foi orado se torne vida.
        </p>

        {/* ─── Barra de progresso final ─────────────── */}
        <div className="mt-8 max-w-[520px]" role="group" aria-label="Progresso da jornada">
          <div className="flex items-baseline justify-between font-stitch-body text-[11px] font-bold uppercase tracking-[0.24em] text-stitch-on-surface-variant">
            <span>Progresso</span>
            <span className={isJourneyComplete ? "text-stitch-secondary" : "text-destructive"}>
              {totalSteps > 0
                ? `${Math.round((completedSteps / totalSteps) * 100)}% · ${completedSteps}/${totalSteps}`
                : "—"}
              {isJourneyComplete ? " · Completa" : ""}
            </span>
          </div>
          <div
            className="mt-2 h-[2px] w-full overflow-hidden bg-stitch-surface-container-high"
            role="progressbar"
            aria-valuenow={totalSteps > 0 ? Math.round((completedSteps / totalSteps) * 100) : 0}
            aria-valuemin={0}
            aria-valuemax={100}
          >
            <motion.div
              initial={{ width: 0 }}
              animate={{
                width: totalSteps > 0 ? `${(completedSteps / totalSteps) * 100}%` : "0%",
              }}
              transition={{ duration: 1.2, ease: "easeOut" }}
              className="h-full bg-stitch-secondary"
            />
          </div>
          {!isJourneyComplete && totalSteps > 0 && (
            <p role="alert" className="mt-3 font-stitch-body text-[12px] italic text-destructive">
              Você ainda tem {totalSteps - completedSteps} etapa
              {totalSteps - completedSteps === 1 ? "" : "s"} pendente
              {totalSteps - completedSteps === 1 ? "" : "s"}. Conclua-as para liberar o certificado.
            </p>
          )}
        </div>

        {/* ─── Etapas pendentes (só quando incompleta) ─────────────── */}
        {!isJourneyComplete && pendingSteps.length > 0 && (
          <motion.section
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            className="mt-10"
            aria-labelledby="pending-steps-heading"
          >
            <h2
              id="pending-steps-heading"
              className="mb-4 flex items-center gap-2 font-stitch-display text-[20px] italic text-stitch-primary md:text-[24px]"
            >
              <Circle className="h-4 w-4 text-destructive" /> Etapas pendentes
            </h2>
            <ul className="space-y-2">
              {pendingSteps.map((s) => (
                <li key={s.id}>
                  <button
                    onClick={() => navigate(`/jornadas/${id}/step?step=${s.id}`)}
                    className="group flex w-full items-center gap-4 border border-stitch-outline-variant/25 bg-stitch-surface-container-lowest p-4 text-left transition-colors hover:border-stitch-secondary/50"
                    aria-label={`Ir para etapa ${s.step_order}: ${s.title}`}
                  >
                    <span className="font-stitch-display text-[18px] italic leading-none text-stitch-secondary/60">
                      {String(s.step_order).padStart(2, "0")}
                    </span>
                    <span className="flex-1 font-stitch-body text-[14px] text-stitch-on-surface">
                      {s.title}
                    </span>
                    <ChevronRight className="h-4 w-4 flex-shrink-0 text-stitch-on-surface-variant transition-transform group-hover:translate-x-1 group-hover:text-stitch-secondary" />
                  </button>
                </li>
              ))}
            </ul>
          </motion.section>
        )}

        {/* ─── Certificado ───────────────────────────── */}
        <motion.section
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="mt-10"
        >
          <div ref={certificateRef}>
            <div
              className="relative overflow-hidden border border-stitch-secondary/30 bg-stitch-surface-container-lowest p-8 text-center md:p-12"
              style={{
                backgroundImage:
                  'url("https://www.transparenttextures.com/patterns/parchment.png")',
              }}
            >
              <div className="pointer-events-none absolute inset-3 border border-stitch-secondary/20" />
              <div className="relative">
                <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full border border-stitch-secondary/40 bg-stitch-secondary/10">
                  <Award className="h-7 w-7 text-stitch-secondary" />
                </div>
                <p className="mt-6 font-stitch-body text-[11px] font-bold uppercase tracking-[0.32em] text-stitch-secondary">
                  Certificado de Conclusão
                </p>
                <h2 className="mt-3 font-stitch-display text-[26px] italic leading-[34px] text-stitch-primary md:text-[36px] md:leading-[44px]">
                  {journey.title}
                </h2>
                {journey.subtitle && (
                  <p className="mt-2 font-stitch-body text-[14px] italic text-stitch-on-surface-variant md:text-[15px]">
                    {journey.subtitle}
                  </p>
                )}
                <div className="mx-auto mt-8 max-w-xs border-t border-b border-stitch-secondary/20 py-4">
                  <p className="font-stitch-body text-[10px] font-bold uppercase tracking-[0.28em] text-stitch-on-surface-variant">
                    Concluída em
                  </p>
                  <p className="mt-1 font-stitch-display text-[16px] italic text-stitch-primary">
                    {completionDate}
                  </p>
                </div>
                <p className="mt-6 font-stitch-body text-[10px] font-bold uppercase tracking-[0.4em] text-stitch-secondary">
                  Cathedra · Digital Sanctuarium
                </p>
              </div>
            </div>
          </div>

          <div className="mt-4 flex justify-center">
            <button
              onClick={() => {
                if (!canShareCertificate) {
                  toast.error(
                    !hasCertificateData
                      ? "Dados da jornada indisponíveis."
                      : "Conclua todas as etapas antes de compartilhar o certificado.",
                  );
                  return;
                }
                setShowPreview(true);
              }}
              disabled={sharing || !canShareCertificate}
              aria-disabled={!canShareCertificate}
              aria-label={
                canShareCertificate
                  ? "Visualizar e compartilhar certificado"
                  : "Conclua todas as etapas para compartilhar o certificado"
              }
              title={
                canShareCertificate
                  ? "Visualizar antes de compartilhar"
                  : "Conclua todas as etapas para liberar"
              }
              className="inline-flex items-center gap-2 border border-stitch-outline-variant/40 px-5 py-2.5 font-stitch-body text-[12px] font-bold uppercase tracking-[0.2em] text-stitch-primary transition-colors hover:border-stitch-secondary hover:text-stitch-secondary disabled:cursor-not-allowed disabled:opacity-40"
            >
              <Eye className="h-3.5 w-3.5" />
              Visualizar e Compartilhar
            </button>
          </div>
        </motion.section>

        {/* ─── Recompensas ───────────────────────────── */}
        {(xpAwarded > 0 || newBadges.length > 0) && (
          <motion.section
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.3 }}
            className="mt-14"
          >
            <div className="mb-4 flex items-baseline justify-between">
              <h2 className="flex items-center gap-2 font-stitch-display text-[22px] italic text-stitch-primary md:text-[26px]">
                <Star className="h-4 w-4 text-stitch-secondary" /> Recompensas
              </h2>
            </div>
            <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
              {xpAwarded > 0 && (
                <div className="flex items-center gap-4 border border-stitch-outline-variant/25 bg-stitch-surface-container-lowest p-4">
                  <div className="flex h-12 w-12 items-center justify-center rounded-full bg-stitch-secondary/15 text-stitch-secondary">
                    <Zap className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="font-stitch-display text-[20px] italic leading-none text-stitch-primary">
                      +{xpAwarded} XP
                    </p>
                    <p className="mt-1 font-stitch-body text-[12px] text-stitch-on-surface-variant">
                      Por concluir esta jornada
                    </p>
                  </div>
                </div>
              )}
              {newBadges.map((badgeId) => {
                const badge = getBadgeById(badgeId);
                if (!badge) return null;
                return (
                  <div
                    key={badgeId}
                    className="flex items-center gap-4 border border-stitch-outline-variant/25 bg-stitch-surface-container-lowest p-4"
                  >
                    <div className="flex h-12 w-12 items-center justify-center rounded-full bg-stitch-secondary/10 text-[22px]">
                      {badge.icon}
                    </div>
                    <div className="min-w-0">
                      <p className="font-stitch-display text-[17px] italic text-stitch-primary">
                        {badge.name}
                      </p>
                      <p className="mt-0.5 font-stitch-body text-[12px] leading-snug text-stitch-on-surface-variant">
                        {badge.description}
                      </p>
                    </div>
                  </div>
                );
              })}
            </div>
          </motion.section>
        )}

        {/* ─── Reflexões ─────────────────────────────── */}
        {reflections.length > 0 && (
          <motion.section
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 }}
            className="mt-14"
          >
            <div className="mb-6 flex items-baseline justify-between">
              <h2 className="flex items-center gap-2 font-stitch-display text-[22px] italic text-stitch-primary md:text-[26px]">
                <BookOpen className="h-4 w-4 text-stitch-secondary" /> Suas Reflexões
              </h2>
              <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant">
                {reflections.length} registro{reflections.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="space-y-3">
              {reflections.map((r, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.5 + i * 0.06 }}
                  className="border border-stitch-outline-variant/25 bg-stitch-surface-container-lowest p-5"
                >
                  <p className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.22em] text-stitch-secondary">
                    {r.title}
                  </p>
                  <div className="mt-3 flex gap-3">
                    <Quote className="h-4 w-4 flex-shrink-0 text-stitch-secondary/60" />
                    <p className="font-stitch-body text-[15px] italic leading-[26px] text-stitch-on-surface md:text-[16px] md:leading-[28px]">
                      {r.reflection}
                    </p>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.section>
        )}

        {/* ─── Nexus Intelligence — próximo caminho coerente ─── */}
        {nextPath.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.65 }}
          >
            <NextPathPanel recommendations={nextPath} className="mt-14" />
          </motion.div>
        )}

        {/* ─── Ações ─────────────────────────────────── */}
        <motion.section
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.85 }}
          className="mt-14 flex flex-col gap-2 sm:flex-row"
        >
          <button
            onClick={() => navigate(AppRoute.JORNADAS)}
            className="inline-flex flex-1 items-center justify-center gap-2 bg-stitch-primary px-5 py-3 font-stitch-body text-[12px] font-bold uppercase tracking-[0.22em] text-stitch-primary-foreground transition-colors hover:bg-stitch-primary/90"
          >
            Ver todas as jornadas <ArrowRight className="h-3.5 w-3.5" />
          </button>
          <button
            onClick={() => navigate(`/jornadas/${id}`)}
            className="inline-flex flex-1 items-center justify-center gap-2 border border-stitch-outline-variant/40 px-5 py-3 font-stitch-body text-[12px] font-bold uppercase tracking-[0.22em] text-stitch-primary transition-colors hover:border-stitch-secondary hover:text-stitch-secondary"
          >
            Rever etapas
          </button>
        </motion.section>

        <p className="mt-16 border-t border-stitch-secondary/10 pt-6 text-center font-stitch-body text-[13px] italic text-stitch-on-surface-variant">
          "Combati o bom combate, terminei a corrida, guardei a fé." — 2Tm 4,7
        </p>
      </section>

      {/* ─── Preview do Certificado ────────────────────────────── */}
      <Dialog open={showPreview} onOpenChange={setShowPreview}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle className="font-stitch-display italic">
              Pré-visualização do Certificado
            </DialogTitle>
            <DialogDescription>
              Confira o que será compartilhado antes de prosseguir.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-2">
            <div
              className="relative overflow-hidden border border-stitch-secondary/30 bg-stitch-surface-container-lowest p-6 text-center"
              style={{
                backgroundImage:
                  'url("https://www.transparenttextures.com/patterns/parchment.png")',
              }}
            >
              <div className="pointer-events-none absolute inset-2 border border-stitch-secondary/20" />
              <div className="relative">
                <Award className="mx-auto h-6 w-6 text-stitch-secondary" />
                <p className="mt-3 font-stitch-body text-[9px] font-bold uppercase tracking-[0.3em] text-stitch-secondary">
                  Certificado de Conclusão
                </p>
                <p className="mt-2 font-stitch-display text-[18px] italic text-stitch-primary">
                  {journey?.title}
                </p>
                <p className="mt-3 font-stitch-body text-[11px] italic text-stitch-on-surface-variant">
                  Concluída em {completionDate}
                </p>
              </div>
            </div>

            <dl className="space-y-2 border border-stitch-outline-variant/20 bg-stitch-surface-container-lowest p-4 font-stitch-body text-[12px]">
              <div className="flex justify-between gap-3">
                <dt className="text-stitch-on-surface-variant">Jornada</dt>
                <dd className="text-right text-stitch-primary">{journey?.title}</dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-stitch-on-surface-variant">Etapas</dt>
                <dd className="text-stitch-primary">
                  {completedSteps}/{totalSteps}
                </dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-stitch-on-surface-variant">XP conquistado</dt>
                <dd className="text-stitch-primary">{xpAwarded > 0 ? `+${xpAwarded}` : "—"}</dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-stitch-on-surface-variant">Distintivos</dt>
                <dd className="text-stitch-primary">{newBadges.length || "—"}</dd>
              </div>
            </dl>
          </div>

          <DialogFooter className="gap-2 sm:gap-2">
            <button
              onClick={() => setShowPreview(false)}
              className="border border-stitch-outline-variant/40 px-4 py-2 font-stitch-body text-[11px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant hover:text-stitch-primary"
            >
              Cancelar
            </button>
            <button
              onClick={async () => {
                setShowPreview(false);
                await shareCertificate();
              }}
              disabled={sharing}
              className="inline-flex items-center gap-2 bg-stitch-primary px-4 py-2 font-stitch-body text-[11px] font-bold uppercase tracking-[0.2em] text-stitch-primary-foreground hover:bg-stitch-primary/90 disabled:opacity-50"
            >
              {sharing ? (
                <span className="h-3 w-3 animate-spin rounded-full border-2 border-current border-t-transparent" />
              ) : (
                <Share2 className="h-3 w-3" />
              )}
              {sharing ? "Gerando…" : "Compartilhar"}
            </button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default JornadaCompletePage;

/**
 * JornadaDetailPage — refino editorial Logos 2030 (SEG-3 / Jornada Editorial).
 *
 * Sem alteração de banco ou rotas. Aproveita campos já existentes em `journeys`:
 * hero_kicker, hero_quote, hero_image_url, narrative_intro, closing_message,
 * estimated_days, difficulty, subtitle.
 *
 * Camadas editoriais:
 *  1. Hero com backdrop opcional (hero_image_url), kicker versalete e quote.
 *  2. Intro narrativa (narrative_intro) em coluna 68ch.
 *  3. "Próxima etapa" destacada antes da timeline.
 *  4. Timeline vertical dignificada (índice, tipo, tempo, CTA).
 *  5. Bloco de conclusão com closing_message.
 *  6. "Continuar depois" — jornadas relacionadas (mesma categoria).
 */

import React, { useEffect, useMemo, useState } from "react";
import { useParams, useNavigate, Link } from "@/lib/rr-compat";
import { Helmet } from "@/lib/helmet-compat";
import { motion } from "framer-motion";
import {
  ArrowLeft,
  ArrowRight,
  Award,
  BookOpen,
  Check,
  ChevronRight,
  Clock,
  Compass,
  Hand,
  HelpCircle,
  Lock,
  PartyPopper,
  PenLine,
  Sparkles,
} from "lucide-react";

import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { AppRoute } from "@/types";
import { EditorialQuote } from "@/components/editorial/primitives";
import { NexusPanel } from "@/components/nexus/NexusPanel";
import { ReaderContinuation } from "@/components/shared/ReaderContinuation";
import { useJourneyNexus, JOURNEY_NEXUS_ORDER } from "@/hooks/useJourneyNexus";

const STEP_META: Record<
  string,
  { label: string; Icon: React.ComponentType<{ className?: string }> }
> = {
  reading: { label: "Leitura", Icon: BookOpen },
  prayer: { label: "Oração", Icon: Hand },
  reflection: { label: "Reflexão", Icon: PenLine },
  quiz: { label: "Quiz", Icon: HelpCircle },
};

const DIFFICULTY_LABELS: Record<string, string> = {
  iniciante: "Iniciante",
  intermediario: "Intermediário",
  avancado: "Avançado",
  avançado: "Avançado",
};

const JornadaDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user, isPremium } = useAuth();
  const [journey, setJourney] = useState<any>(null);
  const [steps, setSteps] = useState<any[]>([]);
  const [completedStepIds, setCompletedStepIds] = useState<Set<string>>(new Set());
  const [related, setRelated] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) loadJourney();
  }, [id, user]);

  const loadJourney = async () => {
    setLoading(true);
    try {
      const [journeyRes, stepsRes] = await Promise.all([
        supabase.from("journeys").select("*").eq("id", id!).single(),
        supabase
          .from("journey_steps")
          .select("*")
          .eq("journey_id", id!)
          .order("step_order", { ascending: true }),
      ]);
      const j = journeyRes.data;
      if (j) setJourney(j);
      if (stepsRes.data) setSteps(stepsRes.data);
      if (user && j) {
        const { data: progress } = await supabase
          .from("journey_progress")
          .select("step_id")
          .eq("user_id", user.id)
          .eq("journey_id", id!);
        if (progress) setCompletedStepIds(new Set(progress.map((p) => p.step_id)));
      }
      if (j?.category) {
        const { data: rel } = await supabase
          .from("journeys")
          .select("id, title, subtitle, category, difficulty, estimated_days")
          .eq("category", j.category)
          .eq("is_active", true)
          .neq("id", j.id)
          .order("sort_order", { ascending: true })
          .limit(3);
        if (rel) setRelated(rel);
      }
    } catch (err) {
      console.error("Failed to load journey:", err);
    } finally {
      setLoading(false);
    }
  };

  const totalSteps = steps.length;
  const completedCount = completedStepIds.size;
  const progressPercent = totalSteps > 0 ? Math.round((completedCount / totalSteps) * 100) : 0;
  const isLocked = journey?.is_premium && !isPremium;
  const isJourneyComplete = totalSteps > 0 && completedCount === totalSteps;

  const nextStepIndex = useMemo(() => {
    if (!steps.length) return -1;
    for (let i = 0; i < steps.length; i++) {
      if (!completedStepIds.has(steps[i].id)) return i;
    }
    return -1;
  }, [steps, completedStepIds]);

  const nextStep = nextStepIndex >= 0 ? steps[nextStepIndex] : null;

  const nexus = useJourneyNexus(
    journey
      ? {
          id: journey.id,
          slug: journey.slug,
          title: journey.title,
          subtitle: journey.subtitle,
          category: journey.category,
          tags: journey.tags,
        }
      : null,
  );

  const nexusTotal = useMemo(
    () => (nexus ? Object.values(nexus.byBucket).reduce((n, arr) => n + (arr?.length ?? 0), 0) : 0),
    [nexus],
  );

  const continuationSuggestions = nexus?.suggestions ?? [];

  const primaryCta = useMemo(() => {
    if (!steps.length) return null;
    if (isJourneyComplete) {
      return { label: "Ver conclusão", to: `/jornadas/${id}/complete` };
    }
    const idx = nextStepIndex >= 0 ? nextStepIndex : 0;
    const step = steps[idx];
    if (!step) return null;
    const label = completedCount === 0 ? "Iniciar Jornada" : "Continuar";
    return { label, to: `/jornadas/${id}/step?step=${step.id}` };
  }, [steps, nextStepIndex, isJourneyComplete, completedCount, id]);

  if (loading) {
    return (
      <div className="min-h-screen w-full bg-stitch-background">
        <div className="mx-auto max-w-[1120px] px-5 pt-16 md:px-16">
          <div className="h-6 w-40 animate-pulse bg-stitch-surface-container-high" />
          <div className="mt-6 h-14 w-3/4 animate-pulse bg-stitch-surface-container-high" />
          <div className="mt-10 space-y-3">
            {[0, 1, 2, 3].map((i) => (
              <div
                key={i}
                className="h-20 animate-pulse border border-stitch-outline-variant/20 bg-stitch-surface-container-lowest"
              />
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (!journey) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center">
        <div className="text-center space-y-4">
          <p className="font-stitch-body text-stitch-on-surface-variant">Jornada não encontrada.</p>
          <Link
            to={AppRoute.JORNADAS}
            className="inline-flex items-center gap-2 border border-stitch-secondary/40 px-5 py-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.15em] text-stitch-secondary hover:bg-stitch-secondary/10"
          >
            <ArrowLeft className="h-3.5 w-3.5" /> Voltar
          </Link>
        </div>
      </div>
    );
  }

  const kicker = journey.hero_kicker || journey.category || "Jornada";
  const canonical = `https://www.cathedradigital.com.br/jornadas/${journey.id}`;

  return (
    <div
      className="min-h-screen w-full bg-stitch-background text-stitch-on-background"
      style={{
        backgroundImage: 'url("https://www.transparenttextures.com/patterns/p6.png")',
      }}
    >
      <Helmet>
        <title>{journey.title} — Cathedra</title>
        {journey.description && <meta name="description" content={journey.description} />}
        <link rel="canonical" href={canonical} />
        <meta property="og:title" content={`${journey.title} — Cathedra`} />
        {journey.description && <meta property="og:description" content={journey.description} />}
        <meta property="og:type" content="article" />
        <meta property="og:url" content={canonical} />
        {journey.hero_image_url && <meta property="og:image" content={journey.hero_image_url} />}
        <meta name="twitter:card" content="summary_large_image" />
      </Helmet>

      <section className="mx-auto w-full max-w-[1120px] px-5 pb-24 pt-8 md:px-16 md:pt-12 animate-fade-in">
        {/* Breadcrumb */}
        <Link
          to={AppRoute.JORNADAS}
          className="inline-flex items-center gap-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant transition-colors hover:text-stitch-secondary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-stitch-secondary/60 focus-visible:ring-offset-2 focus-visible:ring-offset-stitch-background"
        >
          <ArrowLeft className="h-3 w-3" /> Formação
        </Link>

        {/* ─── Hero editorial ─────────────────────────── */}
        <section
          data-testid="jornada-hero"
          className="relative mt-6 overflow-hidden border-b border-stitch-secondary/10 pb-12"
        >
          {journey.hero_image_url && (
            <div
              aria-hidden
              className="pointer-events-none absolute inset-0 -z-0 opacity-[0.08]"
              style={{
                backgroundImage: `url("${journey.hero_image_url}")`,
                backgroundSize: "cover",
                backgroundPosition: "center",
              }}
            />
          )}
          <div className="relative">
            <span className="mb-3 flex flex-wrap items-center gap-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.32em] text-stitch-secondary">
              <Compass className="h-3 w-3" />
              {kicker}
              {journey.is_premium && (
                <>
                  <span className="text-stitch-outline-variant">·</span>
                  <span className="inline-flex items-center gap-1 text-stitch-secondary">
                    <Sparkles className="h-3 w-3" /> PRO
                  </span>
                </>
              )}
            </span>
            <h1 className="font-stitch-display text-[34px] italic leading-[42px] text-stitch-primary md:text-[56px] md:leading-[64px] md:tracking-[-0.02em]">
              {journey.title}
            </h1>
            {journey.subtitle && (
              <p className="mt-3 max-w-[62ch] font-stitch-body text-[16px] italic leading-[26px] text-stitch-on-surface-variant md:text-[18px]">
                {journey.subtitle}
              </p>
            )}
            {journey.description && (
              <p className="mt-6 max-w-[68ch] font-stitch-body text-[17px] leading-[30px] text-stitch-on-surface-variant md:text-[19px] md:leading-[32px]">
                {journey.description}
              </p>
            )}

            {/* Meta + CTA */}
            <div className="mt-8 flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
              <div
                data-testid="jornada-meta"
                className="flex flex-wrap items-center gap-x-5 gap-y-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.18em] text-stitch-on-surface-variant"
              >
                <span className="inline-flex items-center gap-1.5">
                  <Clock className="h-3.5 w-3.5" />~{journey.estimated_days ?? "—"} dias
                </span>
                <span className="text-stitch-outline-variant">·</span>
                <span>{totalSteps} etapas</span>
                {journey.difficulty && (
                  <>
                    <span className="text-stitch-outline-variant">·</span>
                    <span>{DIFFICULTY_LABELS[journey.difficulty] ?? journey.difficulty}</span>
                  </>
                )}
              </div>

              {!isLocked && primaryCta && (
                <Link
                  to={primaryCta.to}
                  data-testid="jornada-cta"
                  className="group inline-flex items-center justify-center gap-2 bg-stitch-primary px-7 py-3 font-stitch-body text-[13px] font-bold uppercase tracking-[0.18em] text-stitch-primary-foreground transition-all hover:bg-stitch-primary/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-stitch-secondary focus-visible:ring-offset-2 focus-visible:ring-offset-stitch-background"
                >
                  {primaryCta.label}
                  <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                </Link>
              )}
            </div>
          </div>
        </section>

        {/* ─── Intro narrativa + quote editorial ─────── */}
        {(journey.narrative_intro || journey.hero_quote) && (
          <section data-testid="jornada-intro" className="pt-12">
            <div className="grid gap-10 md:grid-cols-[minmax(0,1fr)_minmax(0,340px)]">
              {journey.narrative_intro ? (
                <div className="max-w-[68ch] font-stitch-body text-[17px] leading-[30px] text-stitch-on-background md:text-[18px] md:leading-[32px]">
                  {String(journey.narrative_intro)
                    .split(/\n\n+/)
                    .map((para: string, i: number) => (
                      <p key={i} className={i === 0 ? "" : "mt-5"}>
                        {para}
                      </p>
                    ))}
                </div>
              ) : (
                <div />
              )}
              {journey.hero_quote && (
                <EditorialQuote className="text-[20px] md:text-[22px]">
                  {journey.hero_quote}
                </EditorialQuote>
              )}
            </div>
          </section>
        )}

        {/* ─── Próxima Etapa (destaque) ──────────────── */}
        {!isLocked && nextStep && !isJourneyComplete && (
          <section data-testid="jornada-next-step" className="pt-14">
            <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.24em] text-stitch-on-surface-variant">
              A próxima etapa
            </span>
            <Link
              to={`/jornadas/${id}/step?step=${nextStep.id}`}
              data-testid="jornada-next-step-link"
              className="mt-3 group flex flex-col gap-5 border border-stitch-secondary/40 bg-stitch-surface-container-lowest p-6 transition-all hover:border-stitch-secondary hover:shadow-lg md:flex-row md:items-center md:justify-between md:p-8"
            >
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-3">
                  <span className="font-stitch-display text-[28px] italic leading-none text-stitch-secondary/60">
                    {String(nextStepIndex + 1).padStart(2, "0")}
                  </span>
                  <span className="inline-flex items-center gap-1.5 font-stitch-body text-[11px] font-bold uppercase tracking-[0.18em] text-stitch-secondary">
                    {(() => {
                      const M = STEP_META[nextStep.step_type] ?? STEP_META.reading;
                      return (
                        <>
                          <M.Icon className="h-3 w-3" /> {M.label}
                        </>
                      );
                    })()}
                  </span>
                  <span className="text-stitch-outline-variant">·</span>
                  <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.15em] text-stitch-on-surface-variant">
                    <Clock className="mr-1 inline h-3 w-3" />
                    {nextStep.duration_minutes ?? 5} min
                  </span>
                </div>
                <h3 className="mt-3 font-stitch-display text-[24px] italic leading-snug text-stitch-primary md:text-[28px]">
                  {nextStep.title}
                </h3>
                {nextStep.description && (
                  <p className="mt-2 max-w-[60ch] font-stitch-body text-[15px] leading-relaxed text-stitch-on-surface-variant">
                    {nextStep.description}
                  </p>
                )}
              </div>
              <span className="inline-flex flex-shrink-0 items-center gap-2 self-start bg-stitch-primary px-6 py-3 font-stitch-body text-[12px] font-bold uppercase tracking-[0.18em] text-stitch-primary-foreground transition-all group-hover:bg-stitch-primary/90 md:self-auto">
                {completedCount === 0 ? "Iniciar" : "Continuar"}
                <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
              </span>
            </Link>
          </section>
        )}

        {/* ─── Progresso ─────────────────────────────── */}
        {totalSteps > 0 && !isLocked && (
          <section data-testid="jornada-progress" className="pt-12">
            <div className="mb-3 flex items-center justify-between font-stitch-body text-[12px] font-bold uppercase tracking-[0.18em]">
              <span className="text-stitch-on-surface-variant">Progresso</span>
              <span className="text-stitch-secondary">
                {completedCount}/{totalSteps} · {progressPercent}%
              </span>
            </div>
            <div
              className="h-[3px] w-full overflow-hidden bg-stitch-surface-container-high"
              role="progressbar"
              aria-valuenow={progressPercent}
              aria-valuemin={0}
              aria-valuemax={100}
            >
              <div
                className="h-full bg-stitch-secondary transition-all duration-500"
                style={{ width: `${progressPercent}%` }}
              />
            </div>

            {isJourneyComplete && (
              <motion.div
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                className="mt-8 flex flex-col items-start gap-4 border border-stitch-secondary/30 bg-stitch-surface-container-lowest p-6 md:flex-row md:items-center md:justify-between"
              >
                <div className="flex items-start gap-4">
                  <div className="flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-stitch-secondary/15">
                    <Award className="h-6 w-6 text-stitch-secondary" />
                  </div>
                  <div>
                    <p className="flex items-center gap-2 font-stitch-display text-[20px] italic text-stitch-primary">
                      <PartyPopper className="h-4 w-4 text-stitch-secondary" /> Jornada concluída
                    </p>
                    <p className="mt-1 max-w-[52ch] font-stitch-body text-[14px] leading-relaxed text-stitch-on-surface-variant">
                      {journey.closing_message ??
                        "Veja seu certificado e as reflexões finais desta jornada."}
                    </p>
                  </div>
                </div>
                <Link
                  to={`/jornadas/${id}/complete`}
                  className="inline-flex items-center gap-2 border border-stitch-secondary px-5 py-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.18em] text-stitch-secondary transition-colors hover:bg-stitch-secondary hover:text-stitch-primary"
                >
                  Abrir <ChevronRight className="h-3.5 w-3.5" />
                </Link>
              </motion.div>
            )}
          </section>
        )}

        {/* ─── Timeline de etapas ────────────────────── */}
        <section data-testid="jornada-timeline" className="pt-14">
          <div className="mb-6 flex items-baseline justify-between">
            <h2 className="font-stitch-display text-[24px] italic leading-[32px] text-stitch-primary md:text-[28px]">
              Etapas
            </h2>
            <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant">
              {totalSteps} {totalSteps === 1 ? "passo" : "passos"}
            </span>
          </div>

          {totalSteps === 0 ? (
            <p className="border-t border-stitch-secondary/10 pt-8 text-center font-stitch-body text-[14px] italic text-stitch-on-surface-variant">
              Nenhuma etapa disponível ainda.
            </p>
          ) : (
            <ol className="relative border-l border-stitch-outline-variant/30">
              {steps.map((step, index) => {
                const isCompleted = completedStepIds.has(step.id);
                const isStepLocked = isLocked && !step.is_free;
                const isNext = !isCompleted && !isStepLocked && index === nextStepIndex;
                const meta = STEP_META[step.step_type] ?? STEP_META.reading;

                return (
                  <motion.li
                    key={step.id}
                    initial={{ opacity: 0, y: 8 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: Math.min(index * 0.04, 0.3) }}
                    className={`relative pl-8 md:pl-12 ${index === steps.length - 1 ? "" : "pb-6"} ${
                      isStepLocked ? "opacity-50" : ""
                    }`}
                  >
                    {/* Bullet */}
                    <span
                      className={`absolute -left-[11px] top-4 flex h-5 w-5 items-center justify-center rounded-full border-2 ${
                        isCompleted
                          ? "border-stitch-secondary bg-stitch-secondary text-stitch-primary"
                          : isNext
                            ? "border-stitch-secondary bg-stitch-background text-stitch-secondary"
                            : "border-stitch-outline-variant/60 bg-stitch-background text-stitch-on-surface-variant"
                      }`}
                    >
                      {isCompleted ? (
                        <Check className="h-3 w-3" strokeWidth={3} />
                      ) : isStepLocked ? (
                        <Lock className="h-2.5 w-2.5" />
                      ) : (
                        <span className="h-1.5 w-1.5 rounded-full bg-current" />
                      )}
                    </span>

                    <div
                      className={`group flex flex-col gap-4 border p-5 transition-all md:flex-row md:items-center md:justify-between md:p-6 ${
                        isNext
                          ? "border-stitch-secondary/50 bg-stitch-surface-container-lowest shadow-sm"
                          : isCompleted
                            ? "border-stitch-outline-variant/20 bg-stitch-surface-container-lowest/50"
                            : "border-stitch-outline-variant/20 bg-stitch-surface-container-lowest hover:border-stitch-secondary/30"
                      }`}
                    >
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-3">
                          <span className="font-stitch-display text-[22px] italic leading-none text-stitch-secondary/40">
                            {String(index + 1).padStart(2, "0")}
                          </span>
                          <span className="inline-flex items-center gap-1.5 font-stitch-body text-[11px] font-bold uppercase tracking-[0.18em] text-stitch-secondary">
                            <meta.Icon className="h-3 w-3" /> {meta.label}
                          </span>
                          {isStepLocked && (
                            <span className="inline-flex items-center gap-1 font-stitch-body text-[10px] font-bold uppercase tracking-[0.15em] text-stitch-secondary">
                              <Lock className="h-2.5 w-2.5" /> PRO
                            </span>
                          )}
                        </div>
                        <h3 className="mt-2 font-stitch-display text-[19px] leading-snug text-stitch-primary md:text-[21px]">
                          {step.title}
                        </h3>
                        {step.description && (
                          <p className="mt-1.5 line-clamp-2 font-stitch-body text-[14px] leading-relaxed text-stitch-on-surface-variant">
                            {step.description}
                          </p>
                        )}
                        <p className="mt-3 font-stitch-body text-[11px] font-bold uppercase tracking-[0.15em] text-stitch-on-surface-variant">
                          <Clock className="mr-1.5 inline h-3 w-3" />
                          {step.duration_minutes ?? 5} min
                        </p>
                      </div>

                      {!isStepLocked && (
                        <button
                          type="button"
                          onClick={() => navigate(`/jornadas/${id}/step?step=${step.id}`)}
                          className={`inline-flex flex-shrink-0 items-center gap-2 self-start px-5 py-2 font-stitch-body text-[12px] font-bold uppercase tracking-[0.18em] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-stitch-secondary focus-visible:ring-offset-2 focus-visible:ring-offset-stitch-background md:self-auto ${
                            isNext
                              ? "bg-stitch-primary text-stitch-primary-foreground hover:bg-stitch-primary/90"
                              : "border border-stitch-outline-variant/40 text-stitch-primary hover:border-stitch-secondary hover:text-stitch-secondary"
                          }`}
                        >
                          {isCompleted ? "Rever" : isNext ? "Iniciar" : "Abrir"}
                          <ChevronRight className="h-3.5 w-3.5" />
                        </button>
                      )}
                    </div>
                  </motion.li>
                );
              })}
            </ol>
          )}
        </section>

        {/* ─── Reflexão Logos ─────────────────────────── */}
        {(journey.closing_message || journey.hero_quote) && (
          <section data-testid="jornada-reflexao" className="pt-16">
            <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.24em] text-stitch-secondary">
              Reflexão Logos
            </span>
            <div className="mt-4 max-w-[68ch] border-l-2 border-stitch-secondary/40 pl-6">
              <p className="font-stitch-display text-[22px] italic leading-relaxed text-stitch-primary md:text-[26px] md:leading-[38px]">
                {journey.closing_message ?? journey.hero_quote}
              </p>
              {journey.closing_message && journey.hero_quote && (
                <p className="mt-4 font-stitch-body text-[14px] italic text-stitch-on-surface-variant">
                  “{journey.hero_quote}”
                </p>
              )}
            </div>
          </section>
        )}

        {/* ─── Nexus Theologicus (heurístico + curadoria) ───── */}
        {nexus && nexusTotal > 0 && (
          <section id="nexus" data-testid="jornada-nexus" className="pt-16">
            <NexusPanel
              output={nexus}
              order={JOURNEY_NEXUS_ORDER}
              kicker="Conexões desta jornada"
              limitPerBucket={4}
            />
            {continuationSuggestions.length > 0 && (
              <div className="mt-10">
                <ReaderContinuation
                  context={{
                    kind: "journey-step",
                    id: journey.id,
                    meta: { journeyId: journey.id, nextStepId: nextStep?.id },
                  }}
                  suggestions={continuationSuggestions}
                />
              </div>
            )}
          </section>
        )}

        {/* ─── Continuar depois — jornadas relacionadas ─── */}
        {related.length > 0 && (
          <section className="pt-16">
            <div className="mb-6 flex items-baseline justify-between">
              <h2 className="font-stitch-display text-[22px] italic leading-[30px] text-stitch-primary md:text-[26px]">
                Continuar depois
              </h2>
              <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.2em] text-stitch-on-surface-variant">
                {kicker}
              </span>
            </div>
            <div className="grid grid-cols-1 gap-5 md:grid-cols-3">
              {related.map((r) => (
                <Link
                  key={r.id}
                  to={`/jornadas/${r.id}`}
                  className="group relative flex flex-col border border-stitch-outline-variant/20 bg-stitch-surface-container-lowest p-5 transition-all hover:border-stitch-secondary/40 hover:shadow-md"
                >
                  <div className="absolute left-0 top-0 h-full w-1 origin-top scale-y-0 bg-stitch-secondary transition-transform group-hover:scale-y-100" />
                  <span className="font-stitch-body text-[11px] font-bold uppercase tracking-[0.18em] text-stitch-secondary">
                    {r.category ?? "Jornada"}
                  </span>
                  <h3 className="mt-1 font-stitch-display text-[18px] leading-snug text-stitch-primary group-hover:text-stitch-secondary">
                    {r.title}
                  </h3>
                  {r.subtitle && (
                    <p className="mt-2 line-clamp-2 font-stitch-body text-[13px] text-stitch-on-surface-variant">
                      {r.subtitle}
                    </p>
                  )}
                  <div className="mt-4 flex items-center justify-between font-stitch-body text-[11px] font-bold uppercase tracking-[0.15em] text-stitch-on-surface-variant">
                    <span>
                      {r.estimated_days ? `~${r.estimated_days} dias` : "—"}
                      {r.difficulty ? ` · ${DIFFICULTY_LABELS[r.difficulty] ?? r.difficulty}` : ""}
                    </span>
                    <ArrowRight className="h-3.5 w-3.5 text-stitch-secondary transition-transform group-hover:translate-x-1" />
                  </div>
                </Link>
              ))}
            </div>
          </section>
        )}

        {/* ─── Lock PRO ──────────────────────────────── */}
        {isLocked && (
          <section className="mt-14 border border-stitch-secondary/30 bg-stitch-surface-container-lowest p-8 text-center md:p-12">
            <Sparkles className="mx-auto h-8 w-8 text-stitch-secondary" />
            <h3 className="mt-4 font-stitch-display text-[24px] italic text-stitch-primary md:text-[28px]">
              Jornada exclusiva PRO
            </h3>
            <p className="mx-auto mt-3 max-w-md font-stitch-body text-[15px] leading-relaxed text-stitch-on-surface-variant">
              Assine para acessar esta e todas as trilhas de formação, biblioteca completa e o Nexus
              Theologicus.
            </p>
            <Link
              to={AppRoute.PRICING}
              className="mt-6 inline-flex items-center gap-2 bg-stitch-primary px-7 py-3 font-stitch-body text-[13px] font-bold uppercase tracking-[0.18em] text-stitch-primary-foreground transition-all hover:bg-stitch-primary/90"
            >
              Ver planos <ArrowRight className="h-4 w-4" />
            </Link>
          </section>
        )}
      </section>
    </div>
  );
};

