          ariaLabel={`Etapa ${step.step_order} — ${step.title}`}
          hero={
            <EditorialHero align="center" density="balanced">
              {bibleRef && <EditorialHero.Eyebrow>{bibleRef}</EditorialHero.Eyebrow>}
              <EditorialHero.Title>{step.title}</EditorialHero.Title>
