                    className="rounded-premium-full gap-spacing-xs text-[10px] font-black uppercase tracking-widest border-primary/20 hover:bg-primary/5"
                  >
                    <Icons.Bell className="w-spacing-sm h-spacing-sm" /> Lembrete
                  </Button>
                </DialogTrigger>
                <DialogContent className="sm:max-w-[425px]">
                  <DialogHeader>
                    <DialogTitle className="font-display text-premium-2xl text-primary">
                      Lembrete de Jornada
                    </DialogTitle>
                  </DialogHeader>
                  <div className="py-spacing-md space-y-spacing-lg">
                    <div className="space-y-spacing-sm">
                      <label className="text-premium-xs font-bold uppercase tracking-widest text-primary/60">
                        Horário Preferencial
                      </label>
                      <div className="flex gap-spacing-xs">
