              </div>
              <div className="w-px h-spacing-xl bg-border" />
              <div className="text-center">
                <p className="text-premium-base sm:text-premium-lg font-black text-primary">
                  {stats.started}
                </p>
                <p className="text-premium-xs sm:text-premium-xs font-black uppercase tracking-widest text-muted-foreground">
                  Iniciadas
                </p>
              </div>
              <div className="w-px h-spacing-xl bg-border" />
              <div className="text-center">
