  const [newDesc, setNewDesc] = useState("");
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchAllowlist();
  }, []);

  const fetchAllowlist = async () => {
    setIsLoading(true);
    const { data, error } = await supabase.from("language_allowlist").select("*").order("term");
