                      {ev.contentLength !== undefined ? ` · ${ev.contentLength}c` : ""}
                      {ev.message ? ` · ${ev.message}` : ""}
                    </li>
                  ))}
                </ul>
              </ScrollArea>
            </details>
          )}
        </div>
      )}
    </div>
  );
};

