              </div>

              {/* Nexus & Continuity - Adicionados para padronização com Leitor de Santos */}
              <div className="pt-spacing-xl border-t border-white/10 space-y-spacing-xl">
                <NexusPanel
                  output={{
                    selfId: `prayer:${prayer?.slug || "rosario"}`,
                    suggestions: [],
                    byBucket: {},
                    labels: {},
                  }}
                  kicker="Por que rezamos o Rosário?"
                />
                <ReaderContinuation
                  context={{
                    kind: "prayer",
                    id: prayer?.slug || "rosario",
                    meta: { prayerCategory: "rosario" },
                  }}
                />
              </div>

              <div className="text-center space-y-spacing-md py-spacing-xl">
                <div className="relative inline-block font-serif">
                  <Icons.Heart className="w-spacing-3xl h-spacing-3xl text-secondary/20 mx-auto" />
                  <Icons.Sparkles className="absolute -top-spacing-2xs -right-spacing-2xs w-spacing-lg h-spacing-lg text-secondary/40 animate-pulse" />
                </div>
                <div className="space-y-spacing-xs">
                  <p className="text-secondary font-serif font-bold text-premium-2xl">
                    Rosário Completo!
                  </p>
                  <p className="text-premium-base text-secondary/40 font-serif italic max-w-[280px] mx-auto leading-relaxed">
                    Que Nossa Senhora interceda por vós e por todas as vossas intenções.
                  </p>
                </div>
              </div>

              <Button
                onClick={onClose}
                className="w-full py-spacing-md bg-secondary text-primary rounded-premium-full font-black uppercase text-premium-xs tracking-[0.2em] hover:bg-secondary transition-all shadow-premium-hover shadow-secondary/20"
              >
                <Icons.Cross className="w-spacing-md h-spacing-md inline mr-spacing-xs" /> Amém —
                Finalizar
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

