    if (!user) return;
    const fetchAll = async () => {
      const [postsRes, likesRes, notesRes, historyRes, donRes, auditRes, achRes] =
        await Promise.all([
          supabase
            .from("community_posts")
            .select("id", { count: "exact", head: true })
            .eq("user_id", user.id),
          supabase
            .from("community_likes")
            .select("id", { count: "exact", head: true })
            .eq("user_id", user.id),
          supabase
            .from("user_notes")
            .select("id", { count: "exact", head: true })
            .eq("user_id", user.id),
          supabase.from("user_history").select("visited_at").eq("user_id", user.id),
          supabase
            .from("transactions")
            .select("id, created_at, amount, status, description, payment_id, is_donation")
            .eq("user_id", user.id)
            .order("created_at", { ascending: false }),
          supabase
            .from("audit_logs")
            .select("id, created_at, event_type, path, metadata")
            .eq("user_id", user.id)
            .order("created_at", { ascending: false })
            .limit(200),
          supabase
            .from("user_achievements")
            .select("achievement_id, earned_at")
            .eq("user_id", user.id),
        ]);
      const uniqueDays = new Set((historyRes.data || []).map((h: any) => h.visited_at.slice(0, 10)))
        .size;
      setStats({
        posts: postsRes.count || 0,
        likes: likesRes.count || 0,
        notes: notesRes.count || 0,
        daysActive: uniqueDays,
      });
      setDonations(((donRes.data as any[]) || []) as DonationRow[]);
      setAuditRows(((auditRes.data as any[]) || []) as AuditRow[]);
      const map: Record<string, string> = {};
      ((achRes.data as any[]) || []).forEach((a) => {
        map[a.achievement_id] = a.earned_at;
      });
      setEarnedMap(map);
    };
    fetchAll();
  }, [user]);

  const badges = useMemo(() => {
    const unlockedIds = new Set([...(profile?.badges || []), ...Object.keys(earnedMap)]);
    return BADGE_DEFINITIONS.map((b) => ({
      id: b.id,
      label: b.name,
      description: b.description,
      icon: b.icon,
      unlocked: unlockedIds.has(b.id),
      earnedAt: earnedMap[b.id] || null,
    }));
  }, [profile?.badges, earnedMap]);

  const unlockedCount = useMemo(() => badges.filter((b) => b.unlocked).length, [badges]);

  const totalXp = profile?.xp || 0;
  const {
    levelIdx: currentLevelIdx,
    levelName,
    nextLevel,
    progress: xpProgress,
  } = getLevelInfo(totalXp);

  useEffect(() => {
    if (prevLevelRef.current !== null && currentLevelIdx > prevLevelRef.current) {
      setShowLevelUp(true);
      setTimeout(() => setShowLevelUp(false), 4000);
    }
    prevLevelRef.current = currentLevelIdx;
  }, [currentLevelIdx]);

  // Activity feed unificado
  const activityItems = useMemo<ActivityItem[]>(() => {
    const items: ActivityItem[] = [];
    donations.forEach((d) =>
      items.push({
        id: `d-${d.payment_id || d.created_at}`,
        kind: "donation",
        date: d.created_at || "",
        title: d.is_donation ? "Doação" : "Assinatura",
        subtitle: d.description || "—",
        amount: d.amount,
        status: d.status || undefined,
      }),
    );
    auditRows.forEach((a) =>
      items.push({
        id: `a-${(a as any).id || a.created_at}`,
        kind: "audit",
        date: a.created_at || "",
        title: a.event_type,
        subtitle: a.path || "—",
      }),
    );
    return items.sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [donations, auditRows]);

  const filteredActivity = useMemo(
    () =>
      activityFilter === "all"
        ? activityItems
        : activityItems.filter((i) => i.kind === activityFilter),
    [activityItems, activityFilter],
  );
  const totalPages = Math.max(1, Math.ceil(filteredActivity.length / PAGE_SIZE));
  const pagedActivity = filteredActivity.slice(
    (activityPage - 1) * PAGE_SIZE,
    activityPage * PAGE_SIZE,
  );

  useEffect(() => {
    setActivityPage(1);
  }, [activityFilter]);

  const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    if (file.size > 2 * 1024 * 1024) {
      toast.error("A imagem deve ter no máximo 2MB");
      return;
    }
    setUploading(true);
    const ext = (file.name.split(".").pop() || "png").toLowerCase();
    // Bucket privado: guardamos apenas o path; leitura é via Signed URL.
    const path = `${user.id}/avatar-${Date.now()}.${ext}`;
    const { error: uploadError } = await supabase.storage
      .from("avatars")
      .upload(path, file, { upsert: true });
    if (uploadError) {
      toast.error("Erro ao enviar avatar");
      setUploading(false);
      return;
    }
    await supabase
      .from("profiles")
      .update({ avatar_url: path } as any)
      .eq("id", user.id);
    setAvatarUrl(path);
    setUploading(false);
    toast.success("Avatar atualizado!");
  };

  const handleSave = async () => {
    if (!user || saving) return;
    setSaving(true);
    const toastId = toast.loading("Salvando alterações...");
    try {
      try {
        if (pushEnabled) await subscribe();
        else await unsubscribe();
      } catch (err) {
        console.error("BG Push update failed:", err);
      }

      const { error } = await supabase
        .from("profiles")
        .update({
          name,
          bio,
          whatsapp_number: whatsappNumber,
          whatsapp_enabled: whatsappEnabled,
          push_enabled: pushEnabled,
          ritual_reminder_time: reminderTime,
          weekly_goal: weeklyGoal,
          estado: estado || null,
          diocese: diocese || null,
          paroquia: paroquia || null,
          movimento_pastoral: movimentoPastoral || null,
        } as any)
        .eq("id", user.id);
      if (error) throw error;
      toast.success("Perfil atualizado com sucesso!", { id: toastId });
    } catch (err: any) {
      console.error("Failed to save profile:", err);
      toast.error(`Erro ao salvar: ${err?.message || "tente novamente"}`, { id: toastId });
    } finally {
      setSaving(false);
    }
  };

  const handleExportPdf = async () => {
