                      Ver Contexto <Icons.ArrowRight className="w-spacing-sm h-spacing-sm" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
};

