import React, { useState, useEffect, useMemo, lazy, Suspense } from "react";
import { Icons } from "../../constants";
import { resolveColors, buildImageSrc, getInitials } from "@/lib/sacredPalette";

interface SacredImageProps {
  src?: string | string[] | null;
  alt: string;
  className: string;
  priority?: boolean;
  liturgicalColor?: string;
  dominantColor?: string;
  /** Categoria do santo (doctor/father/martyr/saint) para colorir o fallback. */
  category?: string;
}

const SacredImage = React.forwardRef<HTMLDivElement, SacredImageProps>(
  ({ src, alt, className, priority = false, liturgicalColor, dominantColor, category }, ref) => {
    const [isLoaded, setIsLoaded] = useState(false);
    const [error, setError] = useState(false);
    const [currentSrcIndex, setCurrentSrcIndex] = useState(0);

    const sources = useMemo(() => {
      if (!src) return [];
      const s = Array.isArray(src) ? src : [src];
      return s.filter(Boolean).map((url) => buildImageSrc(url as string, priority));
    }, [src, priority]);

    const mainSrc = sources[currentSrcIndex];
    const colors = useMemo(
      () => resolveColors(liturgicalColor, dominantColor, category),
      [liturgicalColor, dominantColor, category],
    );
    const initials = useMemo(() => getInitials(alt || ""), [alt]);
    const noSource = sources.length === 0;

    useEffect(() => {
      // Sem fonte alguma: mostra fallback editorial (sem spinner, sem erro).
      if (noSource) {
        setError(false);
        setIsLoaded(true);
        return;
      }
      if (!mainSrc) {
        if (currentSrcIndex < sources.length - 1) {
          setCurrentSrcIndex((prev) => prev + 1);
        } else {
          setError(true);
          setIsLoaded(true);
        }
        return;
      }

      setIsLoaded(false);
      setError(false);

      const img = new Image();
      // STAB-003C: Wikimedia (upload.wikimedia.org) bloqueia parte das
      // requisições cross-origin com ERR_BLOCKED_BY_ORB quando o Referer é
      // enviado. `no-referrer` evita o bloqueio sem alterar o fallback.
      (img as any).referrerPolicy = "no-referrer";
      const timeout = setTimeout(() => {
        if (!isLoaded) {
          handleImageError();
        }
      }, 10000);

      const handleImageError = () => {
        clearTimeout(timeout);
        console.warn(`SacredImage: Failed to load ${mainSrc}`);
        if (currentSrcIndex < sources.length - 1) {
          setCurrentSrcIndex((prev) => prev + 1);
        } else {
          setError(true);
          setIsLoaded(true);
        }
      };

      img.src = mainSrc;
      img.onload = () => {
        clearTimeout(timeout);
        setIsLoaded(true);
      };
      img.onerror = handleImageError;

      return () => {
        clearTimeout(timeout);
        img.onload = null;
        img.onerror = null;
      };
    }, [mainSrc, currentSrcIndex, sources.length]);

    return (
      <div ref={ref} className={`relative bg-[#0c0a09] overflow-hidden ${className}`}>
        {/* Gradient background — always visible as base layer / fallback */}
        <div
          className={`absolute inset-0 z-0 transition-opacity duration-1000 ${isLoaded && !error ? "opacity-0" : "opacity-100"}`}
          style={{ backgroundColor: colors.base }}
        >
          <div
            className="absolute inset-[-50%] opacity-60"
            style={{
              background: `radial-gradient(circle at 40% 40%, ${colors.accent} 0%, transparent 70%)`,
              animation: "drift-slow 15s ease-in-out infinite",
            }}
          />
          <div className="absolute inset-0 " />
          {(error || noSource) && (
            <div className="absolute inset-0 flex flex-col items-center justify-center z-[5] p-4 text-center gap-2">
              <Icons.Cross className="w-8 h-8 text-white/40" aria-hidden />
              <span
                className="font-serif font-bold text-white/80 select-none"
                style={{
                  fontSize: "clamp(1.5rem, 5vw, 3.5rem)",
                  textShadow: `0 2px 12px ${colors.depth}`,
                }}
              >
                {initials}
              </span>
              <span
                className="text-white/60 text-[10px] uppercase tracking-widest select-none"
                role="status"
              >
                {noSource ? "Retrato em curadoria" : "Retrato indisponível"}
              </span>
            </div>
          )}
        </div>

        {/* Actual image — só quando há fonte válida */}
        {!error && !noSource && (
          <img
            src={mainSrc}
            alt={alt}
            loading={priority ? "eager" : "lazy"}
            fetchPriority={priority ? "high" : "auto"}
            decoding="async"
            referrerPolicy="no-referrer"
            className={`relative z-[2] w-full h-full object-cover transition-all ${isLoaded ? "opacity-100 scale-100 blur-0" : "opacity-0 scale-105 blur-md"}`}
            style={{ transitionDuration: "2000ms" }}
          />
        )}

        {/* Loading spinner — só quando esperando imagem real */}
        {!isLoaded && !noSource && (
          <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
            <Icons.Cross
              className="w-spacing-xl h-spacing-xl opacity-20 text-secondary animate-spin"
              style={{ animationDuration: "12s" }}
            />
          </div>
        )}

        {/* Subtle overlay */}
        <div className="absolute inset-0 z-[3] pointer-events-none bg-gradient-to-b from-black/20 via-transparent to-black/60 opacity-50" />
      </div>
    );
  },
);

SacredImage.displayName = "SacredImage";

export default SacredImage;

import React, { useState } from "react";
import { motion } from "framer-motion";
import { Icons } from "../../constants";
import { Button } from "@/components/ui/button";
import { supabase } from "@/lib/db";
import { toast } from "sonner";
import type { Saint, SaintAIReflection } from "@/data/saints";

interface Props {
  saint: Saint;
}

/**
 * "Aprenda com este Santo" — bloco reutilizável de reflexão editorial
 * gerada por IA a partir da biografia, virtudes, escritos e frases do santo.
 * Cacheada em saints.ai_reflection pela Edge Function `saint-ai-reflection`.
 */
const SaintAILearn: React.FC<Props> = ({ saint }) => {
  const [reflection, setReflection] = useState<SaintAIReflection | null>(
    saint.aiReflection ?? null,
  );
  const [loading, setLoading] = useState(false);

  const generate = async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("saint-ai-reflection", {
        body: { saint_id: saint.id },
      });
      if (error) throw error;
      if (data?.reflection) {
        setReflection(data.reflection);
      } else if (data?.error) {
        toast.error(data.error);
      }
    } catch (err: any) {
      console.error("saint-ai-reflection error", err);
      toast.error("Não foi possível gerar a reflexão agora.", {
        description: err?.message,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <section
      aria-labelledby="ai-learn-heading"
      className="space-y-spacing-md rounded-[2rem] border border-primary/15 bg-primary/5 p-spacing-lg md:p-spacing-xl"
    >
      <header className="flex items-center gap-spacing-sm text-primary">
        <Icons.Sparkles className="w-spacing-md h-spacing-md" aria-hidden="true" />
        <h3
          id="ai-learn-heading"
          className="text-premium-small font-black uppercase tracking-[0.2em]"
        >
          Aprenda com este Santo
        </h3>
      </header>

      {!reflection ? (
        <div className="space-y-spacing-md">
          <p className="text-premium-sm text-muted-foreground font-serif italic leading-relaxed">
            Gere uma reflexão espiritual — resumo, ensinamentos, meditação e oração — inspirada nos
            escritos e testemunho de {saint.name}.
          </p>
          <Button
            onClick={generate}
            disabled={loading}
            className="h-spacing-2xl px-spacing-xl bg-primary hover:bg-primary/90 text-primary-foreground font-black uppercase text-premium-xs tracking-[0.2em] rounded-premium-full shadow-premium shadow-primary/20"
          >
            {loading ? (
              <>
                <Icons.Cross className="w-spacing-md h-spacing-md mr-spacing-xs animate-spin" />
                Compondo reflexão…
              </>
            ) : (
              <>
                <Icons.Sparkles className="w-spacing-md h-spacing-md mr-spacing-xs" />
                Gerar reflexão espiritual
              </>
            )}
          </Button>
        </div>
      ) : (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-spacing-lg"
        >
          <p className="text-premium-xs text-muted-foreground uppercase tracking-widest">
            Reflexão baseada nos textos e ensinamentos de {saint.name}.
          </p>

          {reflection.summary && (
            <div className="space-y-spacing-2xs">
              <h4 className="text-premium-xs font-black uppercase tracking-widest text-primary">
                Resumo espiritual
              </h4>
              <p className="text-premium-sm leading-relaxed text-foreground">
                {reflection.summary}
              </p>
            </div>
          )}

          {reflection.teachings?.length > 0 && (
