export default SantoDoDiaHero;

import React from "react";
import { Icons } from "../../constants";
import type { Saint } from "@/data/saints";
import SaintAILearn from "./SaintAILearn";
import { parseTheologicalReferences } from "@/lib/theologicalRefParser";
import BibleVersePopover from "./BibleVersePopover";
import CatechismPopover from "./CatechismPopover";
import { CATEGORY_LABELS } from "./SaintDetail.categories";
import SaintVirtues from "./sanctum/SaintVirtues";

/**
 * SantoProfile — Perfil editorial reutilizável de um Santo.
 *
 * Renderiza, no padrão canônico da Biblioteca dos Santos, os blocos:
 * Identidade · História · Virtudes · Ensinamentos · Escritos · Aprenda com este Santo.
 *
 * É usado tanto pela ficha modal (`SaintDetail`) quanto por futuras
 * páginas/perfis dedicados, garantindo consistência entre milhares
 * de santos sem alteração de código.
 */
export interface SantoProfileProps {
  saint: Saint;
  /** Se true, mostra também um cabeçalho enxuto (imagem + nome). Padrão false — o container já cuida do header. */
  showHeader?: boolean;
  /** Ocultar bloco de reflexão IA — útil em previews. */
  hideAILearn?: boolean;
}

const renderRich = (text?: string) => {
  if (!text) return null;
  return parseTheologicalReferences(text).map((seg, i) => {
    if (seg.type === "bibleRef")
      return (
        <BibleVersePopover
          key={i}
          abbr={seg.abbr!}
          chapter={seg.chapter!}
          verse={seg.verse}
          label={seg.value}
        />
      );
    if (seg.type === "catechismRef") return <CatechismPopover key={i} paragraph={seg.paragraph!} />;
    return <span key={i}>{seg.value}</span>;
  });
};

const SantoProfile: React.FC<SantoProfileProps> = ({
  saint,
  showHeader = false,
  hideAILearn = false,
}) => {
  const virtues = saint.virtues ?? [];
  const quotesRich = saint.quotesRich ?? [];
  const legacyQuotes = (saint.quotes ?? []).map((text) => ({ text }));
  const teachingQuotes = quotesRich.length ? quotesRich : legacyQuotes;
  const works = saint.works ?? [];
  const timeline = saint.timeline ?? [];

  return (
    <article className="space-y-spacing-2xl" aria-label={`Perfil de ${saint.name}`}>
      {showHeader && (
        <header className="space-y-spacing-xs">
          <p className="text-premium-xs font-black uppercase tracking-[0.2em] text-primary">
            {CATEGORY_LABELS[saint.category] || "Testemunha da Fé"}
          </p>
          <h2 className="font-serif text-premium-3xl text-foreground leading-tight">
            {saint.name}
          </h2>
          {saint.title && (
            <p className="text-premium-sm text-muted-foreground font-serif italic">{saint.title}</p>
          )}
        </header>
      )}

      {/* ── Identidade ─────────────────────────────────────────── */}
      <section aria-labelledby="ident-heading" className="space-y-spacing-md">
        <h3 id="ident-heading" className="sr-only">
          Identidade
        </h3>
        <dl className="grid grid-cols-2 md:grid-cols-4 gap-spacing-md">
          <IdentityCell
            icon={<Icons.Calendar className="w-spacing-md h-spacing-md" />}
            label="Festa"
            value={saint.feastDay}
          />
          <IdentityCell
            icon={<Icons.User className="w-spacing-md h-spacing-md" />}
            label="Nascimento"
            value={saint.born}
          />
          <IdentityCell
            icon={<Icons.XCircle className="w-spacing-md h-spacing-md" />}
            label="Falecimento"
            value={saint.died}
          />
          <IdentityCell
            icon={<Icons.Globe className="w-spacing-md h-spacing-md" />}
            label="País"
            value={saint.country}
          />
          <IdentityCell
            icon={<Icons.Heart className="w-spacing-md h-spacing-md" />}
            label="Vocação"
            value={saint.vocation}
          />
          <IdentityCell
            icon={<Icons.Star className="w-spacing-md h-spacing-md" />}
            label="Século"
            value={saint.century ? `Século ${saint.century}` : undefined}
          />
          <IdentityCell
            icon={<Icons.Shield className="w-spacing-md h-spacing-md" />}
            label="Categoria"
            value={CATEGORY_LABELS[saint.category] || saint.category}
          />
          <IdentityCell
            icon={<Icons.Star className="w-spacing-md h-spacing-md" />}
            label="Virtude principal"
            value={virtues[0]}
          />
        </dl>
      </section>

      {/* ── História ───────────────────────────────────────────── */}
      {(saint.fullBio || saint.bio || saint.historicalContext || timeline.length > 0) && (
        <section aria-labelledby="hist-heading" className="space-y-spacing-md">
          <div className="flex items-center gap-spacing-xs text-primary">
            <Icons.BookOpen className="w-spacing-md h-spacing-md" aria-hidden="true" />
            <h3
              id="hist-heading"
              className="text-premium-small font-black uppercase tracking-[0.2em]"
            >
              História
            </h3>
          </div>

          {(saint.fullBio || saint.bio) && (
            <div className="prose-editorial max-w-none">
              <p className="text-premium-sm leading-relaxed text-foreground whitespace-pre-line font-serif">
                {renderRich(saint.fullBio || saint.bio)}
              </p>
            </div>
          )}

          {saint.historicalContext && (
            <div className="rounded-premium border border-border/60 bg-secondary/20 p-spacing-md space-y-spacing-2xs">
              <p className="text-premium-xs font-black uppercase tracking-widest text-primary">
                Contexto histórico
              </p>
              <p className="text-premium-sm leading-relaxed text-muted-foreground font-serif italic">
                {saint.historicalContext}
              </p>
            </div>
          )}

          {timeline.length > 0 && (
            <ol className="relative border-l border-primary/20 pl-spacing-lg space-y-spacing-md">
              {timeline.map((ev, i) => (
                <li key={i} className="relative">
                  <span
                    className="absolute -left-[calc(theme(spacing.spacing-lg)+0.4rem)] top-1 w-spacing-xs h-spacing-xs rounded-premium-full bg-primary"
                    aria-hidden="true"
                  />
                  <p className="text-premium-xs font-black uppercase tracking-widest text-primary">
                    {ev.year ?? "—"}
                    {ev.place ? ` · ${ev.place}` : ""}
                  </p>
                  <p className="text-premium-sm text-foreground">{ev.event}</p>
                </li>
              ))}
            </ol>
          )}
        </section>
      )}

      {/* ── Virtudes ───────────────────────────────────────────── */}
      <SaintVirtues saint={saint} />

      {/* ── Ensinamentos ───────────────────────────────────────── */}
      {teachingQuotes.length > 0 && (
        <section aria-labelledby="ens-heading" className="space-y-spacing-md">
          <div className="flex items-center gap-spacing-xs text-primary">
            <Icons.Quote className="w-spacing-md h-spacing-md" aria-hidden="true" />
            <h3
              id="ens-heading"
              className="text-premium-small font-black uppercase tracking-[0.2em]"
            >
              Ensinamentos
            </h3>
          </div>
          <ul className="space-y-spacing-md" role="list">
            {teachingQuotes.slice(0, 6).map((q, i) => (
              <li
                key={i}
                className="relative rounded-premium border border-border/60 bg-secondary/20 p-spacing-md group"
              >
                <Icons.Quote
                  className="absolute top-spacing-xs right-spacing-xs w-spacing-lg h-spacing-lg text-primary/10"
                  aria-hidden="true"
                />
                <p className="text-premium-sm text-foreground font-serif italic leading-relaxed">
                  {renderRich(q.text)}
                </p>
                {(q as any).source && (
                  <p className="text-premium-xs text-muted-foreground uppercase tracking-widest mt-spacing-2xs">
                    {(q as any).source}
                    {(q as any).reference ? ` · ${(q as any).reference}` : ""}
                  </p>
                )}
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* ── Escritos ───────────────────────────────────────────── */}
      {works.length > 0 && (
        <section aria-labelledby="obras-heading" className="space-y-spacing-md">
          <div className="flex items-center gap-spacing-xs text-primary">
            <Icons.Book className="w-spacing-md h-spacing-md" aria-hidden="true" />
            <h3
              id="obras-heading"
              className="text-premium-small font-black uppercase tracking-[0.2em]"
            >
              Escritos do Santo
            </h3>
          </div>
          <ul className="grid grid-cols-1 sm:grid-cols-2 gap-spacing-md" role="list">
            {works.map((w, i) => {
              const anyW = w as any;
              return (
                <li key={i}>
                  <div className="flex items-start justify-between gap-spacing-sm rounded-premium border border-border bg-card p-spacing-md hover:border-primary/40 transition-all h-full">
                    <div className="flex items-start gap-spacing-sm min-w-0">
                      <div className="w-spacing-xl h-spacing-xl rounded-premium bg-primary/10 flex items-center justify-center text-primary shrink-0">
                        <Icons.BookOpen className="w-spacing-md h-spacing-md" aria-hidden="true" />
                      </div>
                      <div className="min-w-0">
                        <p className="text-premium-sm font-bold text-foreground truncate">
                          {w.title}
                        </p>
                        {anyW.type && (
                          <p className="text-premium-xs uppercase tracking-widest text-primary">
                            {anyW.type}
                          </p>
                        )}
                        {anyW.description && (
                          <p className="text-premium-xs text-muted-foreground line-clamp-spacing-2xs mt-spacing-2xs">
                            {anyW.description}
                          </p>
                        )}
                        {w.year && (
                          <p className="text-premium-xs text-muted-foreground uppercase mt-spacing-2xs">
                            {w.year}
                          </p>
                        )}
                        {anyW.author && anyW.author !== saint.name && (
                          <p className="text-premium-xs text-muted-foreground italic">
                            por {anyW.author}
                          </p>
                        )}
                      </div>
                    </div>
                    {w.url && (
                      <a
                        href={w.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="shrink-0 text-primary hover:underline text-premium-xs font-black uppercase tracking-widest inline-flex items-center gap-spacing-2xs focus-visible:ring-2 focus-visible:ring-primary rounded-premium-full px-spacing-xs py-spacing-2xs"
                        aria-label={`Ler ${w.title} — abre em nova aba`}
                      >
                        Ler{" "}
                        <Icons.ArrowRight
                          className="w-spacing-sm h-spacing-sm"
                          aria-hidden="true"
                        />
                      </a>
                    )}
                  </div>
                </li>
              );
            })}
          </ul>
        </section>
      )}

      {/* ── Aprenda com este Santo (IA) ────────────────────────── */}
      {!hideAILearn && <SaintAILearn saint={saint} />}
    </article>
  );
};

const IdentityCell: React.FC<{ icon: React.ReactNode; label: string; value?: string | null }> = ({
  icon,
  label,
  value,
}) => {
  if (!value) return null;
  return (
    <div className="flex items-start gap-spacing-sm">
      <div className="w-spacing-xl h-spacing-xl shrink-0 rounded-premium bg-primary/10 flex items-center justify-center text-primary">
        {icon}
      </div>
      <div className="min-w-0">
        <dt className="text-premium-xs font-black uppercase tracking-widest text-muted-foreground">
          {label}
        </dt>
        <dd className="text-premium-sm font-bold text-foreground truncate">{value}</dd>
      </div>
    </div>
  );
};

export default SantoProfile;

import React, { useState } from "react";
import { Trash2, Edit2, Copy, UserPlus, Search, Check, X, ExternalLink } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { SavedFilter, useSavedFilters } from "@/hooks/useSavedFilters";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { supabase } from "@/lib/db";
import { ScrollArea } from "@/components/ui/scroll-area";

interface SavedFiltersManagerProps {
  projectId: string;
  onApply: (filter: SavedFilter) => void;
}

export const SavedFiltersManager: React.FC<SavedFiltersManagerProps> = ({ projectId, onApply }) => {
  const { filters, deleteFilter, updateFilter, duplicateToUser } = useSavedFilters(projectId);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [isShareDialogOpen, setIsShareDialogOpen] = useState(false);
  const [selectedFilter, setSelectedFilter] = useState<SavedFilter | null>(null);
  const [userSearch, setUserSearch] = useState("");
  const [foundUsers, setFoundUsers] = useState<any[]>([]);
  const [isSearchingUsers, setIsSearchingUsers] = useState(false);

  const handleStartEdit = (filter: SavedFilter) => {
    setEditingId(filter.id);
    setEditName(filter.name);
  };

  const handleSaveEdit = async (id: string) => {
    if (!editName) return;
    await updateFilter(id, { name: editName });
    setEditingId(null);
    toast.success("Filtro atualizado");
  };

  const handleSearchUsers = async () => {
    if (userSearch.length < 3) return;
    setIsSearchingUsers(true);
    const { data, error } = await supabase
      .from("profiles")
      .select("id, name")
      .ilike("name", `%${userSearch}%`)
      .limit(5);

    if (!error) setFoundUsers(data || []);
    setIsSearchingUsers(false);
  };

  const handleDuplicate = async (targetUserId: string) => {
    if (!selectedFilter) return;
    const result = await duplicateToUser(selectedFilter, targetUserId);
    if (result) {
      toast.success("Filtro duplicado para o usuário com sucesso!");
    }
  };

  const handleCopyLink = (filter: SavedFilter) => {
    const url = new URL(window.location.href);
    url.searchParams.set("q", filter.query || "");
    url.searchParams.set("f", filter.filter_by || "all");
    navigator.clipboard.writeText(url.toString());
    toast.success("Link compartilhavel copiado!");
  };

  return (
    <div className="space-y-4">
      <ScrollArea className="h-[400px] pr-4">
        <div className="space-y-3">
          {filters.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground italic text-sm">
              Nenhum filtro salvo ainda.
            </div>
          ) : (
            filters.map((filter) => (
              <div
                key={filter.id}
                className="group bg-muted/30 border border-border rounded-xl p-3 transition-all hover:bg-muted/50"
              >
                <div className="flex items-center justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    {editingId === filter.id ? (
                      <div className="flex items-center gap-2">
                        <Input
                          value={editName}
                          onChange={(e) => setEditName(e.target.value)}
                          className="h-8 text-sm"
                          autoFocus
                        />
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-8 w-8 text-green-500"
                          onClick={() => handleSaveEdit(filter.id)}
                        >
                          <Check className="h-4 w-4" />
                        </Button>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-8 w-8 text-destructive"
                          onClick={() => setEditingId(null)}
                        >
                          <X className="h-4 w-4" />
                        </Button>
                      </div>
                    ) : (
                      <div className="flex flex-col">
                        <span className="font-medium text-sm truncate">{filter.name}</span>
                        <span className="text-[10px] text-muted-foreground truncate">
                          Query: {filter.query || "(vazio)"} • Campo: {filter.filter_by}
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={() => onApply(filter)}
                      title="Aplicar"
                    >
                      <ExternalLink className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={() => handleStartEdit(filter)}
                      title="Editar"
                    >
                      <Edit2 className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={() => handleCopyLink(filter)}
                      title="Copiar Link"
                    >
                      <Copy className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8"
                      onClick={() => {
                        setSelectedFilter(filter);
                        setIsShareDialogOpen(true);
                      }}
                      title="Duplicar para outro usuário"
                    >
                      <UserPlus className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 text-destructive hover:text-destructive"
                      onClick={() => deleteFilter(filter.id)}
                      title="Excluir"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </ScrollArea>

      <Dialog open={isShareDialogOpen} onOpenChange={setIsShareDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Duplicar filtro para outro usuário</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <label className="text-sm font-medium">Buscar usuário por nome</label>
              <div className="flex gap-2">
                <Input
                  placeholder="Mínimo 3 caracteres..."
                  value={userSearch}
                  onChange={(e) => setUserSearch(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleSearchUsers()}
                />
                <Button size="icon" onClick={handleSearchUsers} disabled={isSearchingUsers}>
                  <Search className="h-4 w-4" />
                </Button>
              </div>
            </div>

            <div className="space-y-2">
              {foundUsers.map((u) => (
                <div
                  key={u.id}
                  className="flex items-center justify-between p-2 bg-muted rounded-lg"
                >
                  <span className="text-sm font-medium">{u.name}</span>
                  <Button size="sm" variant="outline" onClick={() => handleDuplicate(u.id)}>
                    Duplicar para este
                  </Button>
                </div>
              ))}
              {userSearch.length >= 3 && foundUsers.length === 0 && !isSearchingUsers && (
                <p className="text-xs text-center text-muted-foreground">
                  Nenhum usuário encontrado.
                </p>
              )}
            </div>
          </div>
          <DialogFooter>
            <Button variant="ghost" onClick={() => setIsShareDialogOpen(false)}>
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

import React, { useEffect, useState, useCallback, useMemo, useRef } from "react";
import { supabase } from "@/lib/db";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Icons } from "@/constants";
import { toast } from "sonner";
import { Skeleton } from "@/components/ui/skeleton";
import Telemetry from "@/lib/telemetry";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";

// Configurações de Cache e Retry
const CACHE_KEY = "security_alerts_cache";
const CACHE_TTL = 5 * 60 * 1000; // 5 minutos
const INITIAL_BACKOFF = 1000;
const MAX_RETRIES = 3;

const SecurityAlertsPage = () => {
  const [alerts, setAlerts] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedAlert, setSelectedAlert] = useState<any>(null);
  const [metrics, setMetrics] = useState({ fetchCount: 0, lastFetch: 0, errors: 0 });

  const isInitialMount = useRef(true);
  const abortControllerRef = useRef<AbortController | null>(null);

  // Memoization de métricas para evitar disparos desnecessários
  const stats = useMemo(
    () => ({
      unreadCount: alerts.filter((a) => !a.is_read).length,
      totalCount: alerts.length,
    }),
    [alerts],
  );

  // Implementação de Backoff Exponencial
  const fetchWithRetry = useCallback(async (retryCount = 0): Promise<any> => {
    try {
      const { data, error } = await supabase
        .from("security_alerts" as any)
        .select(
          `
          *,
          security_findings (*)
        `,
        )
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data;
    } catch (err) {
      if (retryCount < MAX_RETRIES) {
        const backoff = INITIAL_BACKOFF * Math.pow(2, retryCount);
        console.warn(`[Security] Falha na consulta. Tentando novamente em ${backoff}ms...`, err);
        await new Promise((resolve) => setTimeout(resolve, backoff));
        return fetchWithRetry(retryCount + 1);
      }
      throw err;
    }
  }, []);

  // Busca de alertas com Cache, Debounce e Controle de Concorrência
  const fetchAlerts = useCallback(
    async (force = false) => {
      // Bloqueia se já estiver carregando
      if (loading) return;

      // Log de disparo do Effect/Action para Telemetria
      const fetchStart = Date.now();
      Telemetry.log({
        type: "effect_trigger",
        component: "SecurityAlertsPage",
        metadata: { reason: force ? "Manual" : "Automático" },
      });

      console.log(`[Security] Disparando fetchAlerts. Motivo: ${force ? "Manual" : "Automático"}`);

      // Verificação de Cache (Debounce implícito por tempo)
      const now = Date.now();
      const cached = localStorage.getItem(CACHE_KEY);
      if (!force && cached) {
        const { data, timestamp } = JSON.parse(cached);
        if (now - timestamp < CACHE_TTL) {
          console.log("[Security] Usando dados do cache.");
          setAlerts(data);
          return;
        }
      }

      setLoading(true);
      setMetrics((prev) => ({ ...prev, fetchCount: prev.fetchCount + 1 }));

      try {
        const data = await fetchWithRetry();
        setAlerts(data || []);

        // Atualiza Cache
        localStorage.setItem(CACHE_KEY, JSON.stringify({ data, timestamp: now }));
        setMetrics((prev) => ({ ...prev, lastFetch: now }));

        // Log de Sucesso na Telemetria
        Telemetry.log({
          type: "request",
          component: "SecurityAlertsPage",
          responseTime: Date.now() - fetchStart,
        });
      } catch (err) {
        console.error("[Security] Erro crítico após retries:", err);
        setMetrics((prev) => ({ ...prev, errors: prev.errors + 1 }));

        // Log de Erro na Telemetria
        Telemetry.log({
          type: "error",
          component: "SecurityAlertsPage",
          metadata: { error: String(err) },
        });

        toast.error("Erro ao carregar alertas após múltiplas tentativas.");
      } finally {
        setLoading(false);
      }
    },
    [loading, fetchWithRetry],
  );

  // Effect otimizado com controle de montagem e limpeza
  useEffect(() => {
    if (isInitialMount.current) {
      fetchAlerts();
      isInitialMount.current = false;
    }

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [fetchAlerts]);

  const markAsRead = async (id: string) => {
    const { error } = await supabase
      .from("security_alerts" as any)
      .update({ is_read: true })
      .eq("id", id);

    if (error) {
      toast.error("Erro ao marcar como lido");
    } else {
      const updatedAlerts = alerts.map((a) => (a.id === id ? { ...a, is_read: true } : a));
      setAlerts(updatedAlerts);
      // Invalida cache local
      localStorage.removeItem(CACHE_KEY);
    }
  };

  const getSeverityBadge = (severity: string) => {
    switch (severity?.toUpperCase()) {
      case "CRITICAL":
      case "CRÍTICO":
      case "HIGH":
        return (
          <Badge variant="destructive" className="font-bold uppercase tracking-widest text-[10px]">
            Crítico
          </Badge>
        );
      case "MEDIUM":
      case "AVISO":
      case "WARNING":
        return (
          <Badge
            variant="outline"
            className="border-amber-500 text-amber-600 font-bold uppercase tracking-widest text-[10px]"
          >
            Aviso
          </Badge>
        );
      default:
        return (
          <Badge variant="secondary" className="uppercase tracking-widest text-[10px]">
            {severity}
          </Badge>
        );
    }
  };

  return (
    <div className="p-spacing-md sm:p-spacing-xl space-y-spacing-xl animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-spacing-md">
        <div>
          <h1 className="text-premium-3xl font-black uppercase tracking-tight flex items-center gap-spacing-xs text-primary">
            <Icons.Bell className="w-spacing-xl h-spacing-xl" />
            Alertas de Segurança
          </h1>
          <div className="flex items-center gap-spacing-md mt-spacing-xs">
            <p className="text-muted-foreground font-serif italic">
              Notificações de vulnerabilidades e novos achados.
            </p>
            <div className="flex items-center gap-spacing-xs bg-primary/5 px-spacing-sm py-spacing-3xs rounded-full border border-primary/10">
              <span className="text-[9px] font-black uppercase tracking-widest text-primary/60">
                Métricas:
              </span>
              <span className="text-[9px] font-bold text-primary">{metrics.fetchCount} reqs</span>
              <span className="text-[9px] font-bold text-emerald-600">
                {stats.unreadCount} novos
              </span>
              {metrics.errors > 0 && (
                <span className="text-[9px] font-bold text-destructive">
                  {metrics.errors} falhas
                </span>
              )}
            </div>
          </div>
        </div>
        <Button
          onClick={() => fetchAlerts(true)}
          variant="outline"
          size="sm"
          disabled={loading}
          className="rounded-premium-full gap-spacing-xs"
        >
          <Icons.RefreshCw
            className={`w-spacing-sm h-spacing-sm ${loading ? "animate-spin" : ""}`}
          />
          {loading ? "Sincronizando..." : "Atualizar"}
        </Button>
      </div>

      <Card className="rounded-[2rem] border-primary/10 shadow-premium overflow-hidden">
        <CardContent className="p-0">
          <Table>
            <TableHeader className="bg-muted/30">
              <TableRow className="border-border/40">
                <TableHead className="text-premium-xs font-black uppercase tracking-widest py-spacing-lg px-spacing-lg w-spacing-4xl">
                  Data
                </TableHead>
                <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                  Achado / Título
                </TableHead>
                <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                  Severidade
                </TableHead>
                <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                  Impacto
                </TableHead>
                <TableHead className="text-premium-xs font-black uppercase tracking-widest text-right px-spacing-lg">
                  Ações
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {loading ? (
                Array(5)
                  .fill(0)
                  .map((_, i) => (
                    <TableRow key={i}>
                      <TableCell colSpan={5} className="p-spacing-lg">
                        <Skeleton className="h-spacing-lg w-full rounded-premium" />
                      </TableCell>
                    </TableRow>
                  ))
              ) : alerts.length > 0 ? (
                alerts.map((alert) => (
                  <TableRow
                    key={alert.id}
                    className={`hover:bg-muted/10 transition-colors border-border/40 ${!alert.is_read ? "bg-primary/[0.02]" : ""}`}
                  >
                    <TableCell className="px-spacing-lg py-spacing-md font-mono text-[10px]">
                      {new Date(alert.created_at).toLocaleString("pt-BR")}
                    </TableCell>
                    <TableCell className="max-w-[300px]">
                      <div className="flex flex-col gap-spacing-3xs">
                        <span className="font-bold text-premium-sm">{alert.title}</span>
                        <span className="text-[10px] text-muted-foreground uppercase tracking-widest font-bold">
                          {alert.security_findings?.category || "General"}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell>{getSeverityBadge(alert.severity)}</TableCell>
                    <TableCell className="font-medium text-premium-sm italic font-serif text-muted-foreground max-w-[400px]">
                      {alert.message.split("\n")[0]}
                    </TableCell>
                    <TableCell className="text-right px-spacing-lg">
                      <div className="flex justify-end gap-spacing-xs">
                        {!alert.is_read && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-spacing-xl px-spacing-sm rounded-premium-full hover:bg-primary/5 text-primary text-[10px] font-bold uppercase"
                            onClick={() => markAsRead(alert.id)}
                          >
                            Lido
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-spacing-xl px-spacing-sm rounded-premium-full hover:bg-primary/5 text-primary text-[10px] font-bold uppercase"
                          onClick={() => setSelectedAlert(alert)}
                        >
                          Expandir
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={5}
                    className="text-center py-spacing-3xl text-muted-foreground font-serif italic"
                  >
                    Nenhum alerta encontrado.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Details Dialog */}
      <Dialog open={!!selectedAlert} onOpenChange={() => setSelectedAlert(null)}>
        <DialogContent className="max-w-spacing-4xl rounded-[2.5rem] border-primary/10 shadow-2xl p-0 overflow-hidden bg-background">
          <div className="bg-primary/5 p-spacing-xl border-b border-primary/10">
            <DialogHeader>
              <div className="flex items-center gap-spacing-sm mb-spacing-xs">
                {getSeverityBadge(selectedAlert?.severity)}
                <Badge
                  variant="outline"
                  className="bg-background/50 border-primary/20 text-[10px] uppercase font-bold tracking-widest"
                >
                  {selectedAlert?.security_findings?.category}
                </Badge>
              </div>
              <DialogTitle className="text-premium-2xl font-black uppercase tracking-tight text-primary">
                {selectedAlert?.title}
              </DialogTitle>
              <DialogDescription className="font-serif italic text-premium-md text-muted-foreground">
                Detectado em{" "}
                {selectedAlert && new Date(selectedAlert.created_at).toLocaleString("pt-BR")}
              </DialogDescription>
            </DialogHeader>
          </div>

          <div className="p-spacing-xl space-y-spacing-xl">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-spacing-xl">
              <div className="space-y-spacing-md">
                <div className="space-y-spacing-xs">
                  <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60">
                    Descrição & Impacto
                  </h4>
                  <div className="bg-muted/30 p-spacing-lg rounded-premium text-premium-sm border border-border/20 italic font-serif leading-relaxed text-foreground/80">
                    {selectedAlert?.message}
                  </div>
                </div>

                <div className="space-y-spacing-xs">
                  <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60">
                    Recomendação
                  </h4>
                  <div className="bg-emerald-500/5 p-spacing-lg rounded-premium border border-emerald-500/20">
                    <p className="text-premium-sm text-emerald-900 dark:text-emerald-100 font-medium">
                      {selectedAlert?.security_findings?.recommendation ||
                        "Nenhuma recomendação disponível."}
                    </p>
                  </div>
                </div>
              </div>

              <div className="space-y-spacing-xs">
                <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60">
                  Evidências Técnicas
                </h4>
                <div className="relative">
                  <pre className="bg-zinc-950 text-emerald-400 p-spacing-lg rounded-premium text-[11px] font-mono overflow-auto max-h-[400px] border border-white/10 shadow-inner custom-scrollbar">
                    {selectedAlert?.security_findings?.evidence
                      ? JSON.stringify(selectedAlert.security_findings.evidence, null, 2)
                      : "Nenhuma evidência capturada."}
                  </pre>
                  <div className="absolute top-spacing-xs right-spacing-xs">
                    <Icons.Code className="w-spacing-md h-spacing-md opacity-20" />
                  </div>
                </div>
              </div>
            </div>
          </div>

          <DialogFooter className="p-spacing-lg bg-muted/20 border-t border-border/40 flex items-center justify-between sm:justify-between px-spacing-xl">
            <p className="text-[10px] font-black uppercase tracking-widest opacity-40 italic">
              AD MAIOREM DEI GLORIAM — Security Alert Protocol
            </p>
            <Button
              onClick={() => setSelectedAlert(null)}
              className="rounded-premium-full font-bold uppercase tracking-widest text-[10px] h-spacing-xl px-spacing-xl shadow-premium"
            >
              Fechar Notificação
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

