import React from "react";
import { useNavigate, useLocation } from "@/lib/rr-compat";
import { motion, useDragControls, PanInfo } from "framer-motion";
import { AppRoute } from "../../types";

interface SwipeNavigationProps {
  children: React.ReactNode;
}

const SwipeNavigation: React.FC<SwipeNavigationProps> = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const currentPath = location.pathname;

  // Define the swipeable routes in order
  const routes = [
    "/", // Hoje
    AppRoute.BIBLE,
    AppRoute.CATECHISM,
    AppRoute.MAGISTERIUM,
    AppRoute.LITURGIA,
    AppRoute.BIBLIOTECA,
  ];

  const currentIndex = routes.findIndex((route) =>
    route === "/"
      ? currentPath === "/" ||
        currentPath === "/home" ||
        currentPath === "/hoje" ||
        currentPath.startsWith("/hoje/")
      : currentPath.startsWith(route),
  );

  const handleDragEnd = (event: any, info: PanInfo) => {
    // Only handle swipes on mobile (simple check)
    if (window.innerWidth >= 1024) return;

    // Check if the interaction was actually a deliberate swipe and not a stray touch
    // Increased ratio and threshold to prevent accidental navigation to CIC
    const isHorizontalSwipe = Math.abs(info.offset.x) > Math.abs(info.offset.y) * 3;
    if (!isHorizontalSwipe) return;

    const threshold = 120; // Increased from 80 to 120px to be more deliberate
    const velocity = 0.5; // Increased from 0.3 to 0.5

    if (info.offset.x < -threshold || info.velocity.x < -velocity) {
      // Swipe Left -> Next
      if (currentIndex !== -1 && currentIndex < routes.length - 1) {
        // Log to telemetry if available or just proceed
        navigate(routes[currentIndex + 1]);
        window.scrollTo({ top: 0, behavior: "instant" });
      }
    } else if (info.offset.x > threshold || info.velocity.x > velocity) {
      // Swipe Right -> Previous
      if (currentIndex !== -1 && currentIndex > 0) {
        navigate(routes[currentIndex - 1]);
        window.scrollTo({ top: 0, behavior: "instant" });
      }
    }
  };

  // If we are not on one of the swipeable routes, just return children
  if (currentIndex === -1) return <>{children}</>;

  return (
    <motion.div
      className="w-full min-h-screen will-change-transform swipe-navigation pointer-events-auto"
      drag="x"

      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.2}
      onDragEnd={handleDragEnd}
      style={{ touchAction: "pan-y" }} // Allow vertical scroll, block horizontal for drag
    >
      {children}
    </motion.div>
  );
};

export default SwipeNavigation;

import React, { useCallback } from "react";

/**
 * Hook to manage arrow navigation between focusable elements (tabs).
 * Supports horizontal (Left/Right) navigation.
 */
export function useTabNavigation() {
  const handleKeyDown = useCallback(
    (
      e: React.KeyboardEvent,
      currentIndex: number,
      totalCount: number,
      onSelect: (index: number) => void,
      tabPrefixId: string = "tab-",
    ) => {
      let nextIndex = -1;

      if (e.key === "ArrowRight") {
        nextIndex = (currentIndex + 1) % totalCount;
      } else if (e.key === "ArrowLeft") {
        nextIndex = (currentIndex - 1 + totalCount) % totalCount;
      } else if (e.key === "Home") {
        nextIndex = 0;
      } else if (e.key === "End") {
        nextIndex = totalCount - 1;
      }

      if (nextIndex !== -1) {
        e.preventDefault();
        const nextTab = document.getElementById(`${tabPrefixId}${nextIndex}`);
        if (nextTab) {
          nextTab.focus();
          // Option to auto-select tab on focus (common in some implementations)
          // onSelect(nextIndex);
        }
      }
    },
    [],
  );

  return { handleKeyDown };
}

/**
 * Hook for roving tabindex in a generic list (e.g., tags, search results).
 * Manages which item is currently focusable.
 */
export function useRovingTabindex(totalCount: number, containerRef?: React.RefObject<HTMLElement>) {
  const [activeIndex, setActiveIndex] = React.useState(0);

  // Reset active index when total count changes (e.g. filtering)
  React.useEffect(() => {
    setActiveIndex(0);
  }, [totalCount]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent, index: number, onSelect?: (index: number) => void) => {
      // Prevent focus loss during rapid navigation by checking if element exists
      const root = containerRef?.current || document;
      const getElements = () =>
        Array.from(
          root.querySelectorAll('[data-roving-item="true"], [data-roving-item]'),
        ) as HTMLElement[];

      let nextIndex = -1;
      if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        nextIndex = (index + 1) % totalCount;
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        nextIndex = (index - 1 + totalCount) % totalCount;
      } else if (e.key === "Home") {
        nextIndex = 0;
      } else if (e.key === "End") {
        nextIndex = totalCount - 1;
      }

      if (nextIndex !== -1) {
        e.preventDefault();
        setActiveIndex(nextIndex);

        // Focus the next element after state update
        setTimeout(() => {
          const els = getElements();
          if (els[nextIndex]) {
            els[nextIndex].focus();
          }
        }, 0);
      }

      if ((e.key === "Enter" || e.key === " ") && onSelect) {
        e.preventDefault();
        onSelect(index);
      }
    },
    [totalCount],
  );

  return { activeIndex, setActiveIndex, handleKeyDown };
}

/**
 * Shared utility for tab attributes to ensure consistency.
 */
export const getTabProps = (
  id: string,
  panelId: string,
  isSelected: boolean,
  className?: string,
) => ({
  id,
  role: "tab",
  "aria-selected": isSelected,
  "aria-controls": panelId,
  tabIndex: isSelected ? 0 : -1,
  className,
});

export const getTabPanelProps = (
  id: string,
  tabId: string,
  isVisible: boolean,
  className?: string,
) => ({
  id,
  role: "tabpanel",
  "aria-labelledby": tabId,
  tabIndex: isVisible ? 0 : -1,
  hidden: !isVisible,
  className,
});

