      transition={{ delay: index * 0.1 }}
    >
      <Card className="border-border/40 bg-card/30 hover:bg-card transition-all duration-300 rounded-premium overflow-hidden group hover:shadow-premium-hover hover:border-primary/20">
        <CardContent className="p-spacing-lg sm:p-spacing-xl space-y-spacing-md">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-spacing-xs">
              <div
                className={`p-spacing-xs rounded-premium-full ${accentColor.replace("text-", "bg-")}/10`}
              >
                <Icon className={`w-spacing-md h-spacing-md ${accentColor}`} />
              </div>
              <span
                className={`text-premium-xs font-black uppercase tracking-widest ${accentColor}`}
              >
                {content.reference}
              </span>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={onAction}
              className={`h-spacing-xl rounded-premium-full text-premium-xs font-black uppercase tracking-widest hover:bg-primary/5 hover:text-primary gap-spacing-2xs px-spacing-md transition-all duration-300`}
            >
              {buttonText} <Icons.ExternalLink className="w-spacing-sm h-spacing-sm" />
            </Button>
          </div>
          <p className="text-premium-base sm:text-premium-lg text-foreground/80 leading-relaxed font-serif">
            {content.content_type === "bible" ? `"${content.text_content}"` : content.text_content}
          </p>

          {otherTags.length > 0 && (
            <div className="pt-spacing-md border-t border-border/10">
              <p className="text-premium-xs font-black uppercase tracking-widest text-muted-foreground/60 mb-spacing-xs">
                Conexões relacionadas:
              </p>
              <div className="flex flex-wrap gap-spacing-xs">
                {otherTags.map((tag, idx) => (
                  <BubbleTag
                    key={tag.id}
                    label={tag.label}
                    emoji={tag.emoji}
                    index={idx}
                    size="sm"
                    onClick={() => navigate(`${AppRoute.TEMAS}/${tag.slug}`)}
                  />
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </motion.div>
  );
};

const ContentSkeleton = () => (
  <div className="space-y-spacing-md" data-testid="content-skeleton">
    {[1, 2, 3].map((i) => (
      <Card key={i} className="border-border/40 bg-card/20 rounded-premium overflow-hidden">
        <CardContent className="p-spacing-lg sm:p-spacing-xl space-y-spacing-md">
          <div className="flex items-center gap-spacing-xs">
            <Skeleton className="w-spacing-xl h-spacing-xl rounded-premium-full" />
            <Skeleton className="h-spacing-sm w-spacing-4xl" />
          </div>
          <div className="space-y-spacing-xs">
            <Skeleton className="h-spacing-md w-full" />
            <Skeleton className="h-spacing-md w-[90%]" />
            <Skeleton className="h-spacing-md w-[70%]" />
          </div>
        </CardContent>
      </Card>
    ))}
  </div>
);

const TemaDetailPage = () => {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [logosInsight, setLogosInsight] = useState<string | null>(null);
  const [loadingLogos, setLoadingLogos] = useState(false);
  const [bibleLimit, setBibleLimit] = useState(5);
  const [traditionLimit, setTraditionLimit] = useState(5);
  const [magisteriumLimit, setMagisteriumLimit] = useState(5);
  const [autoLoaded, setAutoLoaded] = useState(false);
  const [activeTab, setActiveTab] = useState("bible");
  const [debouncedTab, setDebouncedTab] = useState("bible");
  const relatedRef = React.useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedTab(activeTab);
    }, 0);
    return () => clearTimeout(timer);
  }, [activeTab]);

  const { data: tags } = useQuery({
    queryKey: ["tags"],
    queryFn: async () => {
      const { data, error } = await supabase.from("themes").select("*").order("name");
      if (error) throw error;
      return (data || []).map((t: any) => ({
        id: t.id,
        label: t.name,
        slug: t.slug,
        emoji: t.emoji || "⛪",
        category: t.category || "Geral",
      })) as Tag[];
    },
  });

  const selectedTag = tags?.find((t) => t.slug === slug);

  const {
    data: contents,
    isLoading: loadingContents,
    isFetching: isFetchingContents,
    error: contentError,
    refetch,
  } = useQuery({
    queryKey: ["tag-contents", selectedTag?.id, debouncedTab],
    queryFn: async ({ signal }) => {
      if (!selectedTag) return [];
      const results = await fetchNexusTagContent(selectedTag, signal);
      return (results || []).map((r) => ({
        id: r.id,
        content_type: r.type,
        reference:
          r.title ||
          (r.type === "bible" ? "Escritura" : r.type === "catechism" ? "Catecismo" : "Tradição"),
        title: r.title,
        text_content: r.content_text,
        tags: r.metadata?.tags || [],
      }));
    },
    enabled: !!selectedTag,
  });

  const { profileId } = useSpiritualProfile();
  const suggestedSlugs = React.useMemo(() => {
    if (!profileId || !tags) return new Set<string>();
    const profile = PROFILES[profileId];
    if (!profile) return new Set<string>();
    const relevantLabels = [profile.theme, profile.pain.label, "Oração", "Jesus", "Fé"];
    return new Set(
      tags
        .filter((t) => relevantLabels.some((l) => t.label.toLowerCase().includes(l.toLowerCase())))
        .slice(0, 8)
        .map((t) => t.slug),
    );
  }, [profileId, tags]);

  const prefetchTag = useCallback(
    (tag: Tag) => {
      queryClient.prefetchQuery({
        queryKey: ["tag-contents", tag.id, tag.label],
        queryFn: async () => {
          const results = await fetchNexusTagContent(tag);
          return (results || []).map((r) => ({
            id: r.id,
            content_type: r.type,
            reference:
              r.title ||
              (r.type === "bible"
                ? "Escritura"
                : r.type === "catechism"
                  ? "Catecismo"
                  : "Tradição"),
            title: r.title,
            text_content: r.content_text,
            tags: r.metadata?.tags || [],
          }));
        },
        staleTime: 1000 * 60 * 5,
      });
    },
    [queryClient],
  );

  const handleLoadInsight = () => {
    if (!selectedTag || loadingLogos) return;
    setLoadingLogos(true);
    supabase.functions
      .invoke("logos-spiritual-insight", {
        body: { query: selectedTag.label },
      })
      .then(({ data, error }) => {
        if (error) {
          console.error("Spiritual insight error:", error);
          // Handle specific status codes if possible via error object
          const status = (error as any).status || (error as any).status_code;
          if (status === 402) {
            window.dispatchEvent(
              new CustomEvent("ai-status-error", {
                detail: { type: "credits_exhausted" },
              }),
            );
          } else if (status === 429) {
            window.dispatchEvent(
              new CustomEvent("ai-status-error", {
                detail: { type: "rate_limited" },
              }),
            );
          }
        } else if (data?.insight) {
          setLogosInsight(data.insight);
        } else if (data?.error) {
          // The function might return { error: "..." } with a 200/500 status
          if (data.error.includes("esgotados")) {
            window.dispatchEvent(
              new CustomEvent("ai-status-error", {
                detail: { type: "credits_exhausted" },
              }),
            );
          }
        }
        setLoadingLogos(false);
      });
  };

  const relatedThemes = React.useMemo(() => {
    if (!tags || !selectedTag) return [];

    // 1) Connections via shared tags in content
    const sharedContentTagIds = new Set<string>();
    contents?.forEach((c) => {
      c.tags?.forEach((tLabel) => {
        const matchingTag = tags.find((tag) => tag.label.toLowerCase() === tLabel.toLowerCase());
        if (matchingTag && matchingTag.id !== selectedTag.id) {
          sharedContentTagIds.add(matchingTag.id);
        }
      });
    });
    const fromContent = tags
      .filter((t) => sharedContentTagIds.has(t.id))
      .map((t) => ({ ...t, priorityGroup: "content" }));

    // 2) Connections via the user's spiritual profile (priority signal)
    const profileSlugs = new Set<string>();
    if (profileId) {
      const profile = PROFILES[profileId];
      if (profile) {
        const labels = [profile.theme, profile.pain.label, "Oração", "Jesus", "Fé"];
        tags
          .filter((t) => labels.some((l) => t.label.toLowerCase().includes(l.toLowerCase())))
          .forEach((t) => {
            if (t.id !== selectedTag.id) profileSlugs.add(t.slug);
          });
      }
    }
    const fromProfile = tags
      .filter(
        (t) =>
          profileSlugs.has(t.slug) && !sharedContentTagIds.has(t.id) && t.id !== selectedTag.id,
      )
      .map((t) => ({ ...t, priorityGroup: "profile" }));

    // 3) Same category fallback
    const fromCategory = tags
      .filter(
        (t) =>
          t.category &&
          t.category === selectedTag.category &&
          t.id !== selectedTag.id &&
          !sharedContentTagIds.has(t.id) &&
          !profileSlugs.has(t.slug),
      )
      .map((t) => ({ ...t, priorityGroup: "category" }));

    // Dedupe by id, preserve order
    const seen = new Set<string>();
    return [...fromContent, ...fromProfile, ...fromCategory]
      .filter((t) => (seen.has(t.id) ? false : (seen.add(t.id), true)))
      .slice(0, 12);
  }, [tags, selectedTag, contents, profileId]);

  const { activeIndex, handleKeyDown: handleRelatedKeyDown } = useRovingTabindex(
    relatedThemes.length,
    relatedRef,
  );

  useEffect(() => {
    if (selectedTag && !logosInsight && !loadingLogos && !autoLoaded) {
      setAutoLoaded(true);
      const timer = setTimeout(() => {
        handleLoadInsight();
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [selectedTag, logosInsight, loadingLogos, autoLoaded]);

  if (!selectedTag && tags) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60dvh] space-y-spacing-md">
        <h2 className="text-premium-2xl font-bold">Tema não encontrado</h2>
        <Button onClick={() => navigate(AppRoute.TEMAS)}>Voltar para Temas</Button>
      </div>
    );
  }

  const isLoadingAny = loadingContents || isFetchingContents || activeTab !== debouncedTab;

  const bibleVerses = contents?.filter((c) => c.content_type === "bible") || [];
  const catechism = contents?.filter((c) => c.content_type === "catechism") || [];
  const magisterium = contents?.filter((c) => c.content_type === "magisterium") || [];
  const journeys = contents?.filter((c) => c.content_type === "journey") || [];

  const getCategoryColor = (category?: string) => {
    switch (category?.toLowerCase()) {
      case "dores":
        return "from-red-500/10 via-background to-background";
      case "fundamentos":
        return "from-blue-500/10 via-background to-background";
      case "virtudes":
        return "from-amber-500/10 via-background to-background";
      default:
        return "from-primary/10 via-background to-background";
    }
  };

  return (
    <div className="space-y-spacing-2xl animate-in fade-in slide-in-from-bottom-spacing-md duration-700 max-w-5xl mx-auto pb-spacing-4xl px-spacing-md relative">
      <div
        className={`fixed inset-0 bg-gradient-to-b ${getCategoryColor(selectedTag?.category)} -z-10 pointer-events-none opacity-40`}
      />
      <SEOHead
        title={`${selectedTag?.label || "Tema"} - Cathedra`}
        description={`Explore conteúdos sagrados sobre ${selectedTag?.label}.`}
        path={`/temas/${slug}`}
      />

      <nav className="flex items-center gap-spacing-sm text-premium-xs font-black uppercase tracking-[0.2em] text-muted-foreground/50 mb-spacing-xl overflow-x-auto whitespace-nowrap pb-spacing-xs scrollbar-none">
        <Button
          onClick={() => navigate(AppRoute.HOME)}
          className="hover:text-primary transition-colors flex items-center gap-spacing-2xs"
        >
          <Icons.ChevronLeft className="w-spacing-sm h-spacing-sm" /> Início
        </Button>
        <span className="opacity-30">/</span>
        <Button
          onClick={() => navigate(AppRoute.TEMAS)}
          className="hover:text-primary transition-colors"
        >
          Temas
        </Button>
        <span className="opacity-30">/</span>
        <Button
          onClick={() => navigate(`${AppRoute.TEMAS}?category=${selectedTag?.category}`)}
          className="hover:text-primary transition-colors"
        >
          {selectedTag?.category}
        </Button>
        <span className="opacity-30">/</span>
        <span className="text-primary/80">{selectedTag?.label}</span>
      </nav>

      <header className="space-y-spacing-lg">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-spacing-lg">
          <div className="flex items-center gap-spacing-md">
            <div className="w-spacing-3xl h-spacing-3xl rounded-premium bg-primary/10 flex items-center justify-center text-primary shadow-premium-md border border-primary/20">
              {selectedTag && getTagIcon(selectedTag.emoji, "w-spacing-xl h-spacing-xl")}
            </div>
            <div>
              <div className="flex items-center gap-spacing-xs mb-spacing-2xs">
                <span className="text-premium-xs font-black uppercase tracking-[0.3em] text-primary/60">
                  {selectedTag?.category}
                </span>
                <div className="w-spacing-2xs h-spacing-2xs rounded-premium bg-primary/30" />
                <Badge
                  variant="outline"
                  className="text-premium-xs font-black uppercase tracking-widest border-primary/20 text-primary/70"
                >
                  Nexus
                </Badge>
              </div>
              <h1 className="text-premium-4xl sm:text-premium-5xl font-black tracking-tight text-foreground">
                {selectedTag?.label}
              </h1>
            </div>
          </div>

          <Relatio
            context={{
              type: "theme",
              id: selectedTag?.id,
              tags: [selectedTag?.label || "", selectedTag?.category || "", "Tema Espiritual"],
            }}
            onNavigateToBible={(abbr, ch) => navigate(`/bible?book=${abbr}&chapter=${ch}`)}
            onNavigateToCIC={(p) => navigate(`/catechism?p=${p}`)}
            onNavigateToDoc={(docId) => navigate(`/magisterium/${docId}`)}
            className="mb-spacing-xl"
          />

          <Button
            onClick={handleLoadInsight}

            disabled={loadingLogos || !!logosInsight}
            className="rounded-premium-full h-spacing-2xl px-spacing-xl bg-primary text-primary-foreground font-black uppercase tracking-widest shadow-premium-hover shadow-primary/20 hover:scale-[1.02] active:scale-[0.98] transition-all group overflow-hidden relative"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/10 to-white/0 -translate-x-full group-hover:animate-shimmer" />
            {loadingLogos ? (
              <Icons.Loader2 className="w-spacing-md h-spacing-md animate-spin" />
            ) : (
              <>
                <Icons.Sparkles className="w-spacing-md h-spacing-md mr-spacing-xs group-hover:rotate-12 transition-transform" />
                Insight do Logos
              </>
            )}
          </Button>
        </div>

        <AnimatePresence>
          {(logosInsight || loadingLogos) && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              className="relative"
            >
              <div className="absolute inset-0 bg-secondary/5 rounded-premium-lg" />
              <Card className="border-secondary/30 bg-card rounded-premium overflow-hidden relative z-10 shadow-premium">
                <CardContent className="p-spacing-xl sm:p-spacing-xl">
                  <div className="flex items-center justify-between mb-spacing-xl">
                    <div className="flex items-center gap-spacing-sm">
                      <div className="w-spacing-2xl h-spacing-2xl rounded-premium bg-secondary/10 flex items-center justify-center border border-secondary/20 shadow-premium-md">
                        <Icons.Sparkles className="w-spacing-lg h-spacing-lg text-secondary" />
                      </div>
                      <div>
                        <p className="text-premium-small font-black uppercase tracking-[0.3em] text-secondary">
                          Logos Theologicus
                        </p>
                        <p className="text-premium-sm text-muted-foreground font-medium">
                          Sentido & Aplicação
                        </p>
                      </div>
                    </div>
                    <Badge
                      variant="outline"
                      className="text-premium-xs font-black uppercase tracking-widest border-secondary/20 text-secondary animate-pulse px-spacing-sm"
                    >
                      IA Ativa
                    </Badge>
                  </div>
                  {loadingLogos && !logosInsight ? (
                    <div className="space-y-spacing-md">
                      <div className="h-spacing-md w-full bg-muted animate-pulse rounded-premium" />
                      <div className="h-spacing-md w-[90%] bg-muted animate-pulse rounded-premium opacity-70" />
                      <div className="h-spacing-md w-[75%] bg-muted animate-pulse rounded-premium opacity-40" />
                    </div>
                  ) : (
                    <div className="space-y-spacing-lg">
                      <p className="text-premium-xl sm:text-premium-2xl text-foreground/90 leading-relaxed font-serif italic first-letter:text-premium-5xl first-letter:font-black first-letter:mr-spacing-xs first-letter:float-left first-letter:text-secondary selection:bg-secondary/20">
                        {logosInsight}
                      </p>

                      <div className="pt-spacing-lg border-t border-secondary/10 flex items-start gap-spacing-sm opacity-80">
                        <Icons.CheckCircle className="w-spacing-md h-spacing-md text-secondary shrink-0 mt-spacing-2xs" />
                        <div>
                          <p className="text-premium-xs font-black uppercase tracking-widest text-secondary mb-spacing-2xs">
                            Aplicação Prática
                          </p>
                          <p className="text-premium-sm text-muted-foreground italic leading-relaxed">
                            "Busque viver este mistério hoje através de um ato de caridade ou de um
                            momento de silêncio contemplativo."
                          </p>
                        </div>
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            </motion.div>
          )}
        </AnimatePresence>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-spacing-xl">
        <div className="md:col-span-2 space-y-spacing-xl">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="w-full bg-muted/40 p-spacing-2xs rounded-premium-full border border-border/40 grid grid-cols-4">
              <TabsTrigger
                value="bible"
                className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest py-spacing-xs"
              >
                Escrituras
              </TabsTrigger>
              <TabsTrigger
                value="tradition"
                className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest py-spacing-xs"
              >
                Tradição
              </TabsTrigger>
              <TabsTrigger
                value="magisterium"
                className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest py-spacing-xs"
              >
                Magistério
              </TabsTrigger>
              <TabsTrigger
                value="journeys"
                className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest py-spacing-xs"
              >
                Jornadas
              </TabsTrigger>
            </TabsList>

            {contentError ? (
              <div className="p-spacing-2xl text-center space-y-spacing-md bg-red-500/5 rounded-[2rem] border border-red-500/10">
                <Icons.AlertTriangle className="w-spacing-2xl h-spacing-2xl text-red-500 mx-auto" />
                <p className="text-premium-lg font-bold text-red-600">
                  Erro ao carregar conexões de{" "}
                  {activeTab === "bible"
                    ? "Escrituras"
                    : activeTab === "tradition"
                      ? "Tradição"
                      : activeTab === "magisterium"
                        ? "Magistério"
                        : "Jornadas"}{" "}
                  no Nexus
                </p>
                <p className="text-premium-sm text-muted-foreground italic max-w-spacing-md mx-auto">
                  Não foi possível estabelecer uma conexão estável com o banco de dados teológico.
                  Por favor, tente novamente em alguns instantes.
                </p>
                <Button
                  variant="outline"
                  onClick={() => {
                    refetch();
                  }}
                  className="h-spacing-xl rounded-premium-full px-spacing-lg"
                  disabled={isLoadingAny}
                  aria-busy={isLoadingAny}
                  aria-live="polite"
                  data-testid="retry-button"
                >
                  {isFetchingContents || isLoadingAny ? "Processando..." : "Tentar Novamente"}
                </Button>
              </div>
            ) : (
              <>
                <TabsContent value="bible" className="mt-spacing-lg space-y-spacing-md">
                  {isLoadingAny ? (
                    <ContentSkeleton />
                  ) : bibleVerses.length > 0 ? (
                    <>
                      <div className="space-y-spacing-md">
                        {bibleVerses.slice(0, bibleLimit).map((c, i) => (
                          <ThemeContentCard
                            key={c.id}
                            content={c}
                            index={i}
                            icon={Icons.BookOpen}
                            accentColor="text-primary"
                            buttonText="Ler na Bíblia"
                            onAction={() =>
                              navigate(
                                `/bible?ref=${encodeURIComponent(c.reference)}&from=temas&tema=${slug}`,
                              )
                            }
                            allThemes={tags}
                            currentTagId={selectedTag?.id}
                          />
                        ))}
                      </div>
                      {bibleLimit < bibleVerses.length && (
                        <div className="pt-spacing-md flex justify-center">
                          <Button
                            variant="ghost"
                            onClick={() => setBibleLimit((prev) => prev + 5)}
                            className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest gap-spacing-xs"
                          >
                            Carregar mais escrituras ({bibleVerses.length - bibleLimit})
                          </Button>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-center py-spacing-2xl text-muted-foreground italic">
                      Nenhum versículo catalogado para este tema.
                    </div>
                  )}
                </TabsContent>

                <TabsContent value="tradition" className="mt-spacing-lg space-y-spacing-md">
                  {isLoadingAny ? (
                    <ContentSkeleton />
                  ) : catechism.length > 0 ? (
                    <>
                      <div className="space-y-spacing-md">
                        {catechism.slice(0, traditionLimit).map((c, i) => (
                          <ThemeContentCard
                            key={c.id}
                            content={c}
                            index={i}
                            icon={Icons.Shield}
                            accentColor="text-amber-600"
                            buttonText="Ver no Catecismo"
                            onAction={() => {
                              const paragraph = (c.reference || "").replace(/\D/g, "");
                              navigate(`/catechism?p=${paragraph}&from=temas&tema=${slug}`);
                            }}
                            allThemes={tags}
                            currentTagId={selectedTag?.id}
                          />
                        ))}
                      </div>
                      {traditionLimit < catechism.length && (
                        <div className="pt-spacing-md flex justify-center">
                          <Button
                            variant="ghost"
                            onClick={() => setTraditionLimit((prev) => prev + 5)}
                            className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest gap-spacing-xs"
                          >
                            Carregar mais Tradição ({catechism.length - traditionLimit})
                          </Button>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-center py-spacing-2xl text-muted-foreground italic">
                      Conteúdo da Tradição em aprofundamento.
                    </div>
                  )}
                </TabsContent>

                <TabsContent value="magisterium" className="mt-spacing-lg space-y-spacing-md">
                  {isLoadingAny ? (
                    <ContentSkeleton />
                  ) : magisterium.length > 0 ? (
                    <>
                      <div className="space-y-spacing-md">
                        {magisterium.slice(0, magisteriumLimit).map((c, i) => (
                          <ThemeContentCard
                            key={c.id}
                            content={c}
                            index={i}
                            icon={Icons.Globe}
                            accentColor="text-blue-600"
                            buttonText="Ver Documento"
                            onAction={() =>
                              navigate(
                                `/magisterium?doc=${encodeURIComponent(c.reference)}&from=temas&tema=${slug}`,
                              )
                            }
                            allThemes={tags}
                            currentTagId={selectedTag?.id}
                          />
                        ))}
                      </div>
                      {magisteriumLimit < magisterium.length && (
                        <div className="pt-spacing-md flex justify-center">
                          <Button
                            variant="ghost"
                            onClick={() => setMagisteriumLimit((prev) => prev + 5)}
                            className="rounded-premium-full text-premium-xs font-black uppercase tracking-widest gap-spacing-xs"
                          >
                            Carregar mais Magistério ({magisterium.length - magisteriumLimit})
                          </Button>
                        </div>
                      )}
                    </>
                  ) : (
                    <div className="text-center py-spacing-2xl text-muted-foreground italic">
                      Documentos do Magistério em aprofundamento.
                    </div>
                  )}
                </TabsContent>

                <TabsContent value="journeys" className="mt-spacing-lg space-y-spacing-md">
                  {isLoadingAny ? (
                    <ContentSkeleton />
                  ) : journeys.length > 0 ? (
                    <div className="space-y-spacing-md">
                      {journeys.map((c, i) => (
                        <ThemeContentCard
                          key={c.id}
                          content={c}
                          index={i}
                          icon={Icons.Flame}
                          accentColor="text-orange-500"
                          buttonText="Iniciar Jornada"
                          onAction={() => navigate(`/jornadas/${c.id}`)}
                          allThemes={tags}
                          currentTagId={selectedTag?.id}
                        />
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-spacing-2xl text-muted-foreground italic">
                      Nenhuma jornada específica vinculada a este tema.
                    </div>
                  )}
                </TabsContent>
              </>
            )}
          </Tabs>
        </div>

        <aside className="space-y-spacing-lg">
          <div className="bg-card border border-border/40 rounded-[2rem] p-spacing-lg space-y-spacing-lg">
            <h3 className="text-premium-xs font-black uppercase tracking-widest text-foreground/60">
              Temas Relacionados
            </h3>
            <div ref={relatedRef} className="flex flex-wrap gap-spacing-xs">
              {relatedThemes.length > 0 ? (
                relatedThemes.map((tag, idx) => (
                  <TagBubble
                    key={tag.id}
                    tag={tag}
                    index={idx}
                    isSuggested={suggestedSlugs.has(tag.slug)}
                    onKeyDown={(e) =>
                      handleRelatedKeyDown(e, idx, () => navigate(`${AppRoute.TEMAS}/${tag.slug}`))
                    }
                    tabIndex={activeIndex === idx ? 0 : -1}
                    size="sm"
                    profileId={profileId as ProfileId}
                    navigateOnClick={true}
                    priorityGroup={tag.priorityGroup}
                  />
                ))
              ) : (
                <p className="text-premium-xs text-muted-foreground italic leading-relaxed">
                  Estamos tecendo novas conexões para este tema.
                </p>
              )}
            </div>
          </div>

          <Card className="border-primary/20 bg-primary/5 rounded-[2rem] overflow-hidden">
            <CardContent className="p-spacing-lg space-y-spacing-md">
              <div className="w-spacing-xl h-spacing-xl rounded-premium bg-primary/20 flex items-center justify-center">
                <Icons.Quote className="w-spacing-md h-spacing-md text-primary" />
              </div>
              <p className="text-premium-xs text-muted-foreground leading-relaxed italic">
                "A fé e a razão são como as duas asas com as quais o espírito humano se eleva à
                contemplação da verdade."
              </p>
              <div className="pt-spacing-xs">
                <p className="text-premium-xs font-black uppercase tracking-widest text-primary">
                  S. João Paulo II
                </p>
                <p className="text-premium-xs text-muted-foreground/60">Fides et Ratio</p>
              </div>
            </CardContent>
          </Card>
        </aside>
      </div>
    </div>
  );
};

export default TemaDetailPage;

import { Icons } from "@/constants";
import { Button } from "@/components/ui/button";
import React, { useState, useEffect, useMemo, useCallback } from "react";
import { normalizeText } from "@/lib/utils";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { fetchNexusTagContent } from "@/lib/nexusContent";
import { useSearchParams, useNavigate } from "@/lib/rr-compat";
import { supabase } from "@/lib/db";
import { motion } from "framer-motion";
import { AppRoute } from "@/types";

import { useFuzzySearch } from "@/hooks/useFuzzySearch";
import { FuzzySearchInput } from "./FuzzySearchInput";
import { BubbleTag } from "./BubbleTag";
import { TagBubble } from "./ThemeChip";
import { getTabProps, getTabPanelProps, useTabNavigation, useRovingTabindex } from "./TabUtils";
import { useSpiritualProfile } from "@/hooks/useSpiritualProfile";
import { PROFILES, type ProfileId } from "./SpiritualQuiz";
import ContemplativeLayout from "./ContemplativeLayout";

interface Tag {
  id: string;
  label: string;
  slug: string;
  emoji: string;
  category: string;
  similarityScore?: number;
  [key: string]: unknown;
}

const TemasPage = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState("");
  const tagsContainerRef = React.useRef<HTMLDivElement>(null);
  const { handleKeyDown: handleTabKeyDown } = useTabNavigation();
  const [activeCategory, setActiveCategory] = useState<string>(() => {
    const fromUrl = searchParams.get("category");
    if (fromUrl) return fromUrl;
    return localStorage.getItem("nexus_bubbles_filter") || "all";
  });

  useEffect(() => {
    localStorage.setItem("nexus_bubbles_filter", activeCategory);
    if (activeCategory !== "all") {
      setSearchParams({ category: activeCategory }, { replace: true });
    } else {
      setSearchParams({}, { replace: true });
    }
  }, [activeCategory, setSearchParams]);

  const { data: tags, isLoading: loadingTags } = useQuery({
    queryKey: ["tags"],
    queryFn: async () => {
      const { data, error } = await supabase.from("themes").select("*").order("name");
      if (error) throw error;
      return (data || []).map((t: any) => ({
        id: t.id,
        label: t.name,
        slug: t.slug,
        emoji: t.emoji || "⛪",
        category: t.category || "Geral",
      })) as Tag[];
    },
  });

  const categories = useMemo(() => {
    if (!tags) return ["all"];
    const distinct = Array.from(new Set(tags.map((t) => t.category)));
    return ["all", ...distinct];
  }, [tags]);

  const { results: fuzzyTags, isPending: isSearchPending } = useFuzzySearch<Tag>({
    rpc: "search_tags_fuzzy",
    query: searchQuery,
    primaryField: "label",
    secondaryField: "category",
    secondaryWeight: 0.5,
  });
  const isSearchActive = searchQuery.trim().length >= 2;

  const filteredTags = useMemo(() => {
    if (!tags) return [];
    const base: Tag[] = isSearchActive ? (fuzzyTags ?? []) : tags;
    if (isSearchActive || activeCategory === "all") return base;
    return base.filter((tag) => tag.category === activeCategory);
  }, [tags, fuzzyTags, isSearchActive, activeCategory]);

  const { activeIndex, handleKeyDown: handleRovingKeyDown } = useRovingTabindex(
    filteredTags.length,
    tagsContainerRef,
  );

  // Suggested tags based on the user's spiritual profile (sparkle highlight)
  const { profileId } = useSpiritualProfile();
  const suggestedSlugs = useMemo(() => {
    if (!profileId || !tags) return new Set<string>();
    const profile = PROFILES[profileId];
    if (!profile) return new Set<string>();
    const relevantLabels = [profile.theme, profile.pain.label, "Oração", "Jesus", "Fé"];
    return new Set(
      tags
        .filter((t) => relevantLabels.some((l) => t.label.toLowerCase().includes(l.toLowerCase())))
        .slice(0, 8)
        .map((t) => t.slug),
    );
  }, [profileId, tags]);

  useEffect(() => {
    const temaSlug = searchParams.get("tema");
    if (temaSlug) {
      navigate(`${AppRoute.TEMAS}/${temaSlug}`, { replace: true });
    }
  }, [searchParams, navigate]);

  const handleTagSelect = (tag: Tag) => {
    navigate(`${AppRoute.TEMAS}/${tag.slug}`);
  };

  const prefetchTag = useCallback(
    (tag: Tag) => {
      queryClient.prefetchQuery({
        queryKey: ["tag-contents", tag.id, tag.label],
        queryFn: () => fetchNexusTagContent(tag),
        staleTime: 1000 * 60 * 5,
      });
    },
    [queryClient],
  );

  return (
    <ContemplativeLayout>
      <div className="desktop-main px-spacing-md stack-rhythm">
        <header className="space-y-spacing-md text-center header-margin-rhythm">
          <div className="flex justify-center mb-spacing-md">
            <div className="w-spacing-3xl h-spacing-2xs bg-gradient-to-r from-transparent via-primary/50 to-transparent rounded-premium shadow-[0_0_15px_rgba(var(--primary),0.3)]" />
          </div>
          <h1 className="text-premium-4xl sm:text-premium-6xl md:text-premium-8xl font-black tracking-tighter bg-gradient-to-b from-foreground to-foreground/70 bg-clip-text text-transparent leading-[0.9] flex flex-col sm:block">
            <span>Nexus</span> <span className="text-primary/90">Temas</span>
          </h1>
          <p className="text-muted-foreground text-premium-base sm:text-premium-xl max-w-spacing-2xl mx-auto font-serif italic leading-relaxed">
            "Fides quaerens intellectum" — Explore conexões sagradas entre as Escrituras e a
            Tradição.
          </p>
        </header>

        <div className="stack-rhythm">
          <div className="flex flex-col sm:flex-row items-center gap-spacing-xs sm:gap-spacing-md bg-card/60 p-spacing-xs sm:p-spacing-sm rounded-premium border border-border/40 shadow-premium-hover sticky top-spacing-xs sm:top-spacing-md z-20 transition-all duration-500 hover:shadow-premium-hover hover:border-primary/20 group/nav">
            <FuzzySearchInput
              className="flex-1 w-full"
              value={searchQuery}
              onChange={setSearchQuery}
              placeholder="Buscar tema (ex: Amor, Graça...)"
              isSearching={isSearchPending}
            />

            <div
              role="tablist"
              aria-label="Filtrar temas por categoria"
              className="flex items-center gap-spacing-2xs overflow-x-auto w-full sm:w-auto px-spacing-xs pb-spacing-xs sm:pb-spacing-0 scrollbar-none scroll-smooth"
            >
              {categories.map((cat, idx) => (
                <motion.button
                  key={cat}
                  {...getTabProps(
                    `tab-category-${idx}`,
                    `panel-temas`,
                    activeCategory === cat,
                    `
                    whitespace-nowrap px-spacing-sm sm:px-spacing-md py-spacing-xs sm:py-spacing-xs rounded-premium-full sm:rounded-premium-full text-premium-xs sm:text-premium-xs font-black uppercase tracking-[0.15em] sm:tracking-[0.2em] transition-all duration-300 focus-visible:ring-2 focus-visible:ring-primary outline-none
                    ${
                      activeCategory === cat
                        ? "bg-primary text-primary-foreground shadow-premium shadow-primary/20 scale-105"
                        : "bg-muted/40 text-muted-foreground/70 hover:bg-muted hover:text-foreground hover:scale-102 border border-transparent hover:border-border/50"
                    }
                  `,
                  )}
                  initial={false}
                  animate={{ opacity: 1, scale: 1 }}
                  transition={{ delay: idx * 0.02 }}
                  onClick={() => setActiveCategory(cat)}
                  onKeyDown={(e) =>
                    handleTabKeyDown(
                      e,
                      idx,
                      categories.length,
                      (newIdx) => setActiveCategory(categories[newIdx]),
                      "tab-category-",
                    )
                  }
                >
                  {cat === "all" ? "Todos" : cat.charAt(0).toUpperCase() + cat.slice(1)}
                </motion.button>
              ))}
            </div>
          </div>

          <div className="relative">
            <div className="absolute inset-0 bg-gradient-to-b from-primary/5 via-transparent to-transparent  opacity-30 pointer-events-none" />

            <div
              {...getTabPanelProps(
                "panel-temas",
                `tab-category-${categories.indexOf(activeCategory)}`,
                true,
                "relative overflow-hidden rounded-premium border border-border/30 bg-card/20 outline-none",
              )}
            >
              {loadingTags ? (
                <div className="flex flex-col items-center gap-spacing-md py-spacing-2xl w-full justify-center">
                  <div className="relative">
                    <Icons.Loader2 className="h-spacing-xl w-spacing-xl animate-spin text-primary/60" />
                    <div className="absolute inset-0 bg-primary/20  animate-pulse rounded-premium" />
                  </div>
                  <span className="text-premium-sm font-bold text-muted-foreground/60 tracking-widest uppercase">
                    Consultando Nexus...
                  </span>
                </div>
              ) : filteredTags.length === 0 ? (
                <div className="py-spacing-3xl px-spacing-xl text-center w-full space-y-spacing-md">
                  <div className="w-spacing-3xl h-spacing-3xl bg-muted/30 rounded-premium flex items-center justify-center mx-auto">
                    <Icons.Search className="w-spacing-lg h-spacing-lg text-muted-foreground/60" />
                  </div>
                  <p className="text-premium-sm text-muted-foreground/60 italic font-medium tracking-wide">
                    Nenhum tema encontrado para sua busca teológica.
                  </p>
                </div>
              ) : (
                <>
                  {isSearchActive && activeCategory !== "all" && (
                    <div className="px-spacing-lg pt-spacing-lg flex items-center justify-between">
                      <div className="flex items-center gap-spacing-xs px-spacing-sm py-spacing-2xs rounded-premium bg-primary/5 border border-primary/10">
                        <Icons.Sparkles className="w-spacing-sm h-spacing-sm text-primary/40" />
                        <span className="text-premium-xs font-bold text-primary/60 uppercase tracking-widest">
                          Busca Global Ativa
                        </span>
                      </div>
                      <Button
                        onClick={() => setActiveCategory("all")}
                        className="text-premium-xs font-black uppercase tracking-widest text-primary hover:underline underline-offset-4 transition-all"
                      >
                        Limpar Filtro
                      </Button>
                    </div>
                  )}
                  <div className="relative p-spacing-lg sm:p-spacing-xl">
                    <div
                      className="flex flex-wrap justify-center gap-spacing-xs sm:gap-spacing-sm max-w-5xl mx-auto"
                      role="list"
                      ref={tagsContainerRef}
                    >
                      {filteredTags.map((tag, idx) => (
                        <div key={tag.id} role="listitem">
                          <TagBubble
                            tag={tag}
                            index={idx}
                            isSuggested={suggestedSlugs.has(tag.slug)}
                            onKeyDown={(e) => handleRovingKeyDown(e, idx, () => {})}
                            tabIndex={activeIndex === idx ? 0 : -1}
                            className="px-spacing-md py-spacing-xs text-premium-xs sm:text-premium-small uppercase tracking-widest"
                            profileId={profileId as ProfileId}
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="flex items-center justify-center gap-spacing-sm px-spacing-xl pb-spacing-lg pt-spacing-xs">
                    <div className="flex items-center gap-spacing-xs bg-muted/20 px-spacing-md py-spacing-2xs rounded-premium border border-border/20">
                      <span className="text-premium-xs font-black uppercase tracking-widest text-muted-foreground/60 tabular-nums">
                        {filteredTags.length} conexões sagradas
                      </span>
                      <div className="w-spacing-2xs h-spacing-2xs rounded-premium bg-primary/30" />
                      <Icons.Sparkles className="w-spacing-sm h-spacing-sm text-primary/40 animate-pulse" />
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>

        <div className="min-h-[400px] mt-spacing-2xl">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="h-[300px] flex flex-col items-center justify-center text-center p-spacing-2xl bg-muted/10 rounded-premium border border-dashed border-border/40 relative overflow-hidden group"
          >
            <div className="absolute inset-0 bg-gradient-to-br from-primary/5 via-transparent to-secondary/5 opacity-50" />
            <div className="w-spacing-4xl h-spacing-4xl rounded-premium bg-primary/5 flex items-center justify-center mb-spacing-xl border border-primary/10 shadow-premium-md group-hover:scale-110 transition-transform duration-500">
              <Icons.Tag className="h-spacing-2xl w-spacing-2xl text-primary/60" />
            </div>
            <h3 className="text-premium-3xl font-black mb-spacing-md text-foreground tracking-tight">
              Descubra os tesouros da Fé
            </h3>
            <p className="text-muted-foreground text-premium-lg max-w-spacing-md font-serif italic">
              Selecione uma das "bolhas" acima para navegar pelos conteúdos da Bíblia, Catecismo e
              Magistério relacionados ao tema.
            </p>
          </motion.div>
        </div>
      </div>
    </ContemplativeLayout>
  );
};

export default TemasPage;

