const WebhookAlerts = () => {
  const [alerts, setAlerts] = useState<any[]>([]);
  const [settings, setSettings] = useState<any>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    const [{ data: alertData }, { data: settingsData }] = await Promise.all([
      supabase
        .from("webhook_alerts")
        .select("*")
        .order("last_occurrence", { ascending: false })
        .limit(5),
      supabase.from("webhook_settings").select("*").single(),
    ]);
    if (alertData) setAlerts(alertData);
    if (settingsData) setSettings(settingsData);
  };

  const updateSettings = async (field: string, value: any) => {
    setIsSaving(true);
    const { error } = await supabase
      .from("webhook_settings")
      .update({ [field]: value, updated_at: new Date().toISOString() } as any)
      .eq("id", settings.id);

    if (error) toast.error("Erro ao salvar configurações");
    else {
      setSettings({ ...settings, [field]: value });
      toast.success("Configuração atualizada");
    }
    setIsSaving(false);
  };

  if (alerts.length === 0 && !settings)
    return <p className="text-sm text-muted-foreground italic">Carregando...</p>;

  return (
    <div className="space-y-6">
      <div className="space-y-3">
        <h5 className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
          Alertas Ativos
        </h5>
        {alerts.length === 0 ? (
          <p className="text-sm text-muted-foreground italic">Sem alertas críticos no momento.</p>
        ) : (
          alerts.map((alert) => (
            <div
              key={alert.id}
              className={`p-3 border rounded-xl flex items-start gap-3 ${
                alert.severity === "critical"
                  ? "bg-red-50 border-red-200"
                  : "bg-amber-50 border-amber-200"
              }`}
            >
              <AlertCircle
                className={`w-4 h-4 mt-1 shrink-0 ${
                  alert.severity === "critical" ? "text-red-500" : "text-amber-500"
                }`}
              />
              <div>
                <p
                  className={`text-xs font-bold uppercase ${
                    alert.severity === "critical" ? "text-red-700" : "text-amber-700"
                  }`}
                >
                  {alert.alert_type.replace("_", " ")} ({alert.count}x)
                </p>
                <p
                  className={`text-[11px] line-clamp-2 ${
                    alert.severity === "critical" ? "text-red-600" : "text-amber-600"
                  }`}
                >
                  {alert.message}
                </p>
                <p className="text-[10px] text-muted-foreground mt-1">
                  {format(new Date(alert.last_occurrence), "HH:mm - dd/MM")}
                </p>
              </div>
            </div>
          ))
        )}
      </div>

      {settings && (
        <div className="space-y-4 pt-4 border-t border-border/50">
          <h5 className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
            Limites e Retentativas
          </h5>
          <div className="grid gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase text-muted-foreground">
                Taxa de Timeout p/ Alerta (%)
              </label>
              <Select
                value={(settings.alert_threshold_timeout * 100).toString()}
                onValueChange={(val) =>
                  updateSettings("alert_threshold_timeout", parseFloat(val) / 100)
                }
              >
                <SelectTrigger className="h-8 text-xs rounded-lg">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="1">1% (Crítico)</SelectItem>
                  <SelectItem value="5">5%</SelectItem>
                  <SelectItem value="10">10%</SelectItem>
                  <SelectItem value="20">20%</SelectItem>
                  <SelectItem value="50">50%</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase text-muted-foreground">
                Assinaturas Inválidas p/ Alerta (%)
              </label>
              <Select
                value={(settings.alert_threshold_invalid_sig * 100).toString()}
                onValueChange={(val) =>
                  updateSettings("alert_threshold_invalid_sig", parseFloat(val) / 100)
                }
              >
                <SelectTrigger className="h-8 text-xs rounded-lg">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="0">Qualquer falha (0%)</SelectItem>
                  <SelectItem value="1">1%</SelectItem>
                  <SelectItem value="5">5%</SelectItem>
                  <SelectItem value="10">10%</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase text-muted-foreground">
                Janela de Observação (min)
              </label>
              <Select
                value={(settings.alert_window_minutes || 60).toString()}
                onValueChange={(val) => updateSettings("alert_window_minutes", parseInt(val))}
              >
                <SelectTrigger className="h-8 text-xs rounded-lg">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="15">15 minutos</SelectItem>
                  <SelectItem value="60">1 hora</SelectItem>
                  <SelectItem value="360">6 horas</SelectItem>
                  <SelectItem value="1440">24 horas</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase text-muted-foreground">
                E-mail para Alertas Críticos
              </label>
              <div className="flex gap-2">
                <input
                  type="email"
                  placeholder="admin@exemplo.com"
                  className="flex h-8 w-full rounded-lg border border-input bg-background px-3 py-1 text-xs shadow-sm transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
                  defaultValue={settings.alert_notification_email || ""}
                  onBlur={(e) => updateSettings("alert_notification_email", e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold uppercase text-muted-foreground">
                Máximo de Retentativas
              </label>
              <Select
                value={settings.max_retries.toString()}
                onValueChange={(val) => updateSettings("max_retries", parseInt(val))}
              >
                <SelectTrigger className="h-8 text-xs rounded-lg">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="3">3 tentativas</SelectItem>
                  <SelectItem value="5">5 tentativas</SelectItem>
                  <SelectItem value="10">10 tentativas</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

