              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-spacing-md">
          {transactions.map((tx, idx) => (
            <motion.div
              key={tx.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.05 }}
            >
              <Card className="overflow-hidden border-border/50 hover:border-primary/30 transition-all">
                <CardContent className="p-spacing-0">
                  <div className="p-spacing-md md:p-spacing-lg flex flex-col md:flex-row items-start md:items-center justify-between gap-spacing-md">
                    <div className="flex items-center gap-spacing-md">
                      <div
                        className={`w-spacing-xl h-spacing-xl rounded-premium-full flex items-center justify-center ${tx.is_donation ? "bg-secondary/10 text-secondary" : "bg-primary/10 text-primary"}`}
                      >
                        {tx.is_donation ? (
                          <Icons.Heart className="w-spacing-md h-spacing-md fill-current" />
                        ) : (
                          <Icons.Star className="w-spacing-md h-spacing-md fill-current" />
