                      <div>
                        <p className="text-premium-sm font-bold text-foreground">
                          {tx.description ||
                            (tx.is_donation ? "Doação Voluntária" : "Assinatura PRO")}
                        </p>
                        <p className="text-premium-xs text-muted-foreground">
                          {format(new Date(tx.created_at), "dd 'de' MMMM 'de' yyyy, HH:mm", {
                            locale: ptBR,
                          })}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center justify-between w-full md:w-auto gap-spacing-lg">
                      <div className="text-right">
                        <p className="text-premium-lg font-black text-foreground">
                          {new Intl.NumberFormat("pt-BR", {
                            style: "currency",
                            currency: "BRL",
                          }).format(tx.amount)}
                        </p>
                        <p className="text-premium-xs text-muted-foreground uppercase font-bold tracking-tighter">
                          Valor
