                Tentar novamente
              </Button>
            </div>
          )}

          {hasMore && !loadingMore && !error && (
            <div
              ref={loaderRef}
              className="flex flex-col items-center justify-center py-spacing-xl space-y-spacing-md"
            >
              <div className="w-spacing-lg h-spacing-lg border-2 border-primary border-t-transparent rounded-premium animate-spin opacity-50" />
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  const nextPage = page + 1;
                  setPage(nextPage);
                  fetchTransactions(nextPage);
                }}
                className="text-premium-xs uppercase font-bold text-muted-foreground hover:text-primary"
              >
                Carregar mais
              </Button>
            </div>
          )}
        </div>
      )}

      <Dialog
        open={!!selectedTx}
        onOpenChange={(open) => {
          if (!open) {
            setSelectedTx(null);
            setAnnouncement("Modal de detalhes fechado.");
