  return (
    <EditorialSurface
      interactive
      tier="low"
      className={cn("p-6 flex flex-col gap-2", className)}
      {...rest}
    >
      {kicker && (
        <span className="font-stitch-label text-stitch-label-sm text-stitch-on-surface-variant uppercase">
