import React, { useState } from "react";
import { HomeButton } from "@/components/cathedra/HomeButton";
import { trackEvent } from "@/lib/analytics";
import { useToast } from "@/hooks/use-toast";
import { Icons } from "@/constants";
import { supabase } from "@/lib/db";

const LeadCaptureForm = () => {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !email.includes("@")) {
      toast({
        title: "Erro na validação",
        description: "Por favor, insira um e-mail válido.",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    trackEvent("conversion", { type: "lead_capture_attempt" });

    try {
      const { error } = await supabase.from("landing_leads" as any).insert([{ email } as any]);

      if (error) throw error;

      setSubmitted(true);
      trackEvent("conversion", { type: "lead_capture_success" });
      toast({
        title: "Sucesso!",
        description: "Recebemos seu e-mail. Você receberá conteúdos exclusivos em breve.",
      });
    } catch (error) {
      toast({
        title: "Erro inesperado",
        description: "Não foi possível processar sua solicitação no momento.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <div className="text-center space-y-spacing-md py-spacing-xl animate-in fade-in duration-1000">
        <div className="w-spacing-2xl h-spacing-2xl rounded-premium-full bg-primary/10 flex items-center justify-center mx-auto text-primary">
          <Icons.Check className="w-spacing-lg h-spacing-lg" />
        </div>
        <h3 className="text-premium-xl font-bold font-display">Bem-vindo à Irmandade!</h3>
        <p className="text-muted-foreground font-serif">
          Seu e-mail foi cadastrado. Fique atento à sua caixa de entrada.
        </p>
      </div>
    );
  }

  return (
    <div className="w-full max-w-spacing-3xl mx-auto space-y-spacing-xl">
      <div className="text-center space-y-spacing-sm">
        <h2 className="text-premium-2xl font-display font-bold">Junte-se ao Acervo Cathedra</h2>
        <p className="text-muted-foreground text-premium-sm font-serif">
          Receba reflexões teológicas, notícias do Vaticano e atualizações exclusivas do projeto.
        </p>
      </div>

      <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row gap-spacing-md">
        <div className="flex-1 relative">
          <input
            type="email"
            placeholder="Seu melhor e-mail"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            disabled={loading}
            className="w-full h-spacing-3xl px-spacing-xl rounded-premium-full bg-background border border-border focus:border-primary/40 focus:ring-1 focus:ring-primary/20 outline-none transition-all text-premium-base font-serif"
            required
          />
        </div>
        <HomeButton
          type="submit"
          disabled={loading}
          className="h-spacing-3xl px-spacing-2xl flex-shrink-0"
        >
          {loading ? "Processando..." : "Inscrever-me"}
        </HomeButton>
      </form>
      <p className="text-[10px] text-center text-muted-foreground/60 uppercase tracking-widest font-bold">
        Respeitamos sua privacidade. Sem spam, apenas fé.
      </p>
    </div>
  );
};

export default LeadCaptureForm;

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "@/lib/rr-compat";
import { BookOpen, ArrowLeft } from "lucide-react";
import { MobileSheet } from "./MobileSheet";
import { BIBLE_DATA, type BibleBook } from "@/data/bible-books";
import { buildBibleUrl } from "@/lib/bibleUrl";
import { cn } from "@/lib/utils";

const LAST_KEY = "cathedra:bible:last";

export type BibleLastRead = { abbr: string; chapter: number };

export function getBibleLastRead(): BibleLastRead | null {
  try {
    const raw = localStorage.getItem(LAST_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed.abbr === "string" && Number.isFinite(parsed.chapter)) {
      return parsed as BibleLastRead;
    }
  } catch {}
  return null;
}

export function setBibleLastRead(last: BibleLastRead) {
  try {
    localStorage.setItem(LAST_KEY, JSON.stringify(last));
  } catch {}
}

type Testament = keyof typeof BIBLE_DATA;

interface BiblePickerSheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Se true, ao escolher, dispara `onSelect` e não navega. */
  selectionOnly?: boolean;
  onSelect?: (sel: BibleLastRead) => void;
  /** Pré-seleciona livro (e capítulo) ao abrir — sincroniza com URL. */
  initialSelection?: BibleLastRead | null;
}

/**
 * BiblePickerSheet — bottom-sheet mobile para seleção de Livro → Capítulo.
 * Reusa BIBLE_DATA e buildBibleUrl. Persiste a última leitura em localStorage.
 */
export function BiblePickerSheet({
  open,
  onOpenChange,
  selectionOnly = false,
  onSelect,
  initialSelection,
}: BiblePickerSheetProps) {
  const navigate = useNavigate();
  const [testament, setTestament] = useState<Testament>("Novo Testamento");
  const [book, setBook] = useState<BibleBook | null>(null);

  useEffect(() => {
    if (!open) return;
    // Prioridade: seleção vinda da URL > último lido em localStorage.
    const seed = initialSelection ?? getBibleLastRead();
    if (seed) {
      for (const t of Object.keys(BIBLE_DATA) as Testament[]) {
        for (const cat of BIBLE_DATA[t]) {
          const found = cat.books.find((b) => b.abbr.toLowerCase() === seed.abbr.toLowerCase());
          if (found) {
            setTestament(t);
            // Se veio da URL, entra direto no grid de capítulos do livro atual.
            if (initialSelection) setBook(found);
            else setBook(null);
            return;
          }
        }
      }
    }
    setBook(null);
  }, [open, initialSelection]);

  const categories = useMemo(() => BIBLE_DATA[testament] ?? [], [testament]);

  const handleChapter = (chapter: number) => {
    if (!book) return;
    const sel: BibleLastRead = { abbr: book.abbr, chapter };
    setBibleLastRead(sel);
    onOpenChange(false);
    if (selectionOnly && onSelect) {
      onSelect(sel);
    } else {
      navigate(buildBibleUrl({ abbr: book.abbr, chapter }));
    }
  };

  return (
    <MobileSheet
      open={open}
      onOpenChange={onOpenChange}
      title={book ? book.name : "Escolher passagem"}
      description={book ? `Selecione um capítulo (${book.chapters})` : "Livro e capítulo"}
      size="full"
    >
      {!book ? (
        <div className="space-y-6">
          {/* Testamento */}
          <div className="flex gap-2 border-b border-stitch-outline-variant/30">
            {(Object.keys(BIBLE_DATA) as Testament[]).map((t) => {
              const active = t === testament;
              return (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTestament(t)}
                  aria-pressed={active}
                  className={cn(
                    "relative -mb-px px-3 py-2.5 font-stitch-body text-[12px] font-bold uppercase tracking-[0.15em] transition-colors",
                    active
                      ? "text-stitch-primary"
                      : "text-stitch-on-surface-variant hover:text-stitch-primary",
                  )}
                >
                  {t}
                  {active && (
                    <span className="absolute inset-x-0 -bottom-px h-[2px] bg-stitch-secondary" />
                  )}
                </button>
              );
            })}
          </div>

          {/* Livros */}
          {categories.map((cat) => (
            <div key={cat.name}>
              <p className="mb-2 font-stitch-body text-[11px] font-bold uppercase tracking-[0.15em] text-stitch-on-surface-variant">
                {cat.name}
              </p>
              <div className="grid grid-cols-3 gap-2">
                {cat.books.map((b) => (
                  <button
                    key={b.abbr}
                    type="button"
                    onClick={() => setBook(b)}
                    style={{ minHeight: "var(--stitch-mobile-touch-min)" }}
                    className={cn(
                      "flex flex-col items-start justify-center rounded-md border border-stitch-outline-variant/30",
                      "bg-stitch-surface-container-lowest px-3 py-2 text-left transition-colors",
                      "hover:border-stitch-secondary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-stitch-secondary",
                    )}
                  >
                    <span className="font-stitch-display text-[15px] leading-tight text-stitch-primary">
                      {b.name}
                    </span>
                    <span className="mt-0.5 font-stitch-body text-[10px] font-bold uppercase tracking-[0.12em] text-stitch-on-surface-variant">
                      {b.abbr} · {b.chapters}
                    </span>
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="space-y-4">
          <button
            type="button"
            onClick={() => setBook(null)}
            className="inline-flex items-center gap-2 font-stitch-body text-[13px] font-bold uppercase tracking-[0.15em] text-stitch-secondary hover:text-stitch-primary"
          >
            <ArrowLeft className="h-4 w-4" />
            Trocar livro
          </button>
          <div className="grid grid-cols-6 gap-2 sm:grid-cols-8">
            {Array.from({ length: book.chapters }, (_, i) => i + 1).map((n) => (
              <button
                key={n}
                type="button"
                onClick={() => handleChapter(n)}
                style={{
                  minHeight: "var(--stitch-mobile-touch-min)",
