  if (buckets.length === 0) {
    return (
      <aside
        className={cn(
          "w-full max-w-[68ch] mx-auto",
          "rounded-premium border border-primary/10 bg-muted/5",
          "p-spacing-lg space-y-spacing-sm opacity-60",
