import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Icons } from "@/constants";
import { Label } from "@/components/ui/label";

interface BrandOnboardingData {
  brandName: string;
  brandNiche: string;
  targetAudience: string;
  brandValues: string;
  brandVoice: string;
  mainObjective: string;
}

interface StepProps {
  data: BrandOnboardingData;
  updateData: (fields: Partial<BrandOnboardingData>) => void;
  onNext: () => void;
  onBack: () => void;
}

const steps = [
  {
    id: "brandName",
    title: "Qual o nome da sua marca?",
    placeholder: "Ex: Cathedra Digital",
    label: "Nome da Marca",
    validation: (val: string) =>
      val.length < 3 ? "O nome deve ter pelo menos 3 caracteres." : null,
  },
  {
    id: "brandNiche",
    title: "Em qual nicho ela atua?",
    placeholder: "Ex: Educação Católica, Tecnologia",
    label: "Nicho de Atuação",
    validation: (val: string) => (val.length < 4 ? "Descreva o nicho com mais detalhes." : null),
  },
  {
    id: "targetAudience",
    title: "Quem é seu público-alvo?",
    placeholder: "Ex: Fiéis em busca de formação",
    label: "Público-Alvo",
    validation: (val: string) => (val.length < 5 ? "Especifique melhor quem é seu público." : null),
  },
  {
    id: "brandValues",
    title: "Quais os valores fundamentais?",
    placeholder: "Ex: Tradição, Verdade, Beleza",
    label: "Valores",
    validation: (val: string) =>
      val.split(",").length < 2 ? "Insira pelo menos 2 valores separados por vírgula." : null,
  },
  {
    id: "brandVoice",
    title: "Qual o tom de voz da marca?",
    placeholder: "Ex: Solene, Acolhedor, Profundo",
    label: "Tom de Voz",
    validation: (val: string) =>
      val.length < 4 ? "O tom de voz precisa ser mais descritivo." : null,
  },
  {
    id: "mainObjective",
    title: "Qual seu objetivo principal?",
    placeholder: "Ex: Evangelizar através do conhecimento",
    label: "Objetivo Principal",
    validation: (val: string) =>
      val.length < 10 ? "O objetivo deve ser uma frase mais completa (mín. 10 caracteres)." : null,
  },
];

export const BrandConceptOnboarding = ({
  onComplete,
}: {
  onComplete: (data: BrandOnboardingData) => void;
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [data, setData] = useState<BrandOnboardingData>({
    brandName: "",
    brandNiche: "",
    targetAudience: "",
    brandValues: "",
    brandVoice: "",
    mainObjective: "",
  });
  const [errors, setErrors] = useState<Record<string, string | null>>({});
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  const validateField = (id: string, value: string) => {
    const step = steps.find((s) => s.id === id);
    if (step?.validation) {
      const error = step.validation(value);
      setErrors((prev) => ({ ...prev, [id]: error }));
      return !error;
    }
    return true;
  };

  const updateData = (fields: Partial<BrandOnboardingData>) => {
    setData((prev) => ({ ...prev, ...fields }));
    // Real-time validation
    Object.keys(fields).forEach((key) => {
      validateField(key, (fields as any)[key]);
    });
  };

  const handleNext = () => {
    const currentId = steps[currentStep].id;
    const isValid = validateField(currentId, (data as any)[currentId]);

    if (!isValid) return;

    if (currentStep < steps.length - 1) {
      setCurrentStep((prev) => prev + 1);
    } else {
      setIsPreviewMode(true);
    }
  };

  const handleBack = () => {
    if (currentStep > 0) {
      setCurrentStep((prev) => prev - 1);
    }
  };

  const stepInfo = steps[currentStep];

  if (isPreviewMode) {
    return (
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-spacing-3xl p-spacing-xl bg-card border border-border rounded-premium-xl space-y-spacing-xl"
      >
        <div className="text-center space-y-spacing-sm">
          <Icons.Sparkles className="w-spacing-xl h-spacing-xl text-primary mx-auto" />
          <h2 className="text-premium-3xl font-serif font-bold text-foreground">
            Conceito-Mãe Gerado
          </h2>
          <p className="text-muted-foreground">
            Aqui está a prévia da identidade da sua marca baseada nos seus valores.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-spacing-lg">
          <div className="space-y-spacing-xs">
            <span className="text-[10px] uppercase tracking-widest text-primary font-black">
              Marca
            </span>
            <p className="text-premium-lg font-bold text-foreground">{data.brandName}</p>
          </div>
          <div className="space-y-spacing-xs">
            <span className="text-[10px] uppercase tracking-widest text-primary font-black">
              Missão
            </span>
            <p className="text-premium-sm text-foreground">{data.mainObjective}</p>
          </div>
          <div className="space-y-spacing-xs md:col-span-2">
            <span className="text-[10px] uppercase tracking-widest text-primary font-black">
              Arquétipo & Tom
            </span>
            <p className="text-premium-sm text-foreground">
              Uma marca com voz <span className="italic">{data.brandVoice}</span>, focada em{" "}
              <span className="italic">{data.brandNiche}</span>
              para impactar <span className="italic">{data.targetAudience}</span> através de{" "}
              <span className="italic">{data.brandValues}</span>.
            </p>
          </div>
        </div>

        <div className="pt-spacing-xl flex gap-spacing-md">
          <Button
            variant="outline"
            onClick={() => setIsPreviewMode(false)}
            className="flex-1 rounded-premium-full"
          >
            Ajustar Dados
          </Button>
          <Button
            onClick={() => onComplete(data)}
            className="flex-1 rounded-premium-full bg-primary text-primary-foreground font-bold"
          >
            Confirmar e Continuar
          </Button>
        </div>
      </motion.div>
    );
  }

  return (
    <div className="w-full max-w-spacing-lg space-y-spacing-2xl">
      <div className="space-y-spacing-xs">
        <div className="w-full h-spacing-3xs bg-muted rounded-full overflow-hidden">
          <motion.div
            className="h-full bg-primary"
            initial={{ width: 0 }}
            animate={{ width: `${((currentStep + 1) / steps.length) * 100}%` }}
          />
        </div>
        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground text-center">
          Passo {currentStep + 1} de {steps.length}
        </p>
      </div>

      <AnimatePresence mode="wait">
        <motion.div
          key={stepInfo.id}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -20 }}
          className="space-y-spacing-xl"
        >
          <div className="text-center space-y-spacing-sm">
            <h2 className="text-premium-2xl lg:text-premium-4xl font-serif font-bold text-foreground leading-tight">
              {stepInfo.title}
            </h2>
          </div>

          <div className="space-y-spacing-md">
            <div className="space-y-spacing-xs">
              <Label
                htmlFor={stepInfo.id}
                className="text-premium-xs uppercase tracking-widest font-black text-muted-foreground"
              >
                {stepInfo.label}
              </Label>
              <Input
                id={stepInfo.id}
                value={(data as any)[stepInfo.id]}
                onChange={(e) => updateData({ [stepInfo.id]: e.target.value })}
                placeholder={stepInfo.placeholder}
                className={`h-spacing-2xl text-premium-lg bg-card border-border focus:ring-primary/20 rounded-premium transition-all ${
                  errors[stepInfo.id] ? "border-destructive/50 focus:ring-destructive/20" : ""
                }`}
                autoFocus
                onKeyDown={(e) => {
                  if (e.key === "Enter") handleNext();
                }}
              />
              {errors[stepInfo.id] && (
                <motion.p
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="text-[10px] font-bold text-destructive uppercase tracking-widest mt-spacing-xs"
                >
                  {errors[stepInfo.id]}
                </motion.p>
              )}
            </div>

            <div className="flex gap-spacing-md pt-spacing-lg">
              {currentStep > 0 && (
                <Button
                  variant="ghost"
                  onClick={handleBack}
                  className="flex-1 h-spacing-xl rounded-premium-full text-muted-foreground"
                >
                  <Icons.ChevronLeft className="w-spacing-md h-spacing-md mr-spacing-xs" /> Voltar
                </Button>
              )}
              <Button
                disabled={!(data as any)[stepInfo.id]}
                onClick={handleNext}
                className="flex-1 h-spacing-xl bg-foreground text-background hover:bg-primary hover:text-primary-foreground rounded-premium-full font-black uppercase text-premium-xs tracking-widest transition-all"
              >
                {currentStep === steps.length - 1 ? "Gerar Conceito" : "Próximo"}
                <Icons.ChevronRight className="w-spacing-md h-spacing-md ml-spacing-xs" />
              </Button>
            </div>
          </div>
        </motion.div>
      </AnimatePresence>
    </div>
  );
};

/**
 * PassageActions — componente oficial de ações para qualquer trecho lido
 * dentro do Cathedra 2.0. Totalmente agnóstico: não conhece Bíblia,
 * Catecismo, Magistério, Busca ou Padres. O consumidor passa apenas o
 * conteúdo (texto + referência + `url` ou `passage`) e callbacks.
 *
 * Ações padrão:
 *  - Copiar trecho           (text)
 *  - Copiar referência       (reference)
 *  - Compartilhar            (Web Share API + fallback)
 *  - Destacar                (delegado via onHighlight — se ausente e
 *                             `passage` for informado, navega para o
 *                             Reader com ?highlight=…)
 *
 * PA-1 endurece: loading/erro por ação, aria-busy/aria-live, foco
 * visível e tap targets 44×44 em todos os breakpoints.
 */
import React, { useCallback, useState } from "react";
import { useNavigate } from "@/lib/rr-compat";
import { toast } from "sonner";
import { Icons } from "@/constants";
import { cn } from "@/lib/utils";
import { useShare } from "@/hooks/useShare";
import { buildPassageUrl, type PassageDescriptor } from "@/lib/passageUrl";

type ActionKey = "text" | "reference" | "share" | "highlight";

export interface PassageActionsProps {
  /** Texto do trecho (o que será copiado como "trecho"). */
  text: string;
  /** Referência canônica curta (ex.: "Jo 6,53" ou "CIC §142"). */
  reference: string;
  /** URL absoluta compartilhável do trecho. Opcional se `passage` for informado. */
  url?: string;
  /** Descritor da passagem — usado por `buildPassageUrl` quando `url` não é fornecido. */
  passage?: PassageDescriptor;
  /** Título usado no share nativo (ex.: "Cathedra — Jo 6,53"). */
  title?: string;
  /** Se fornecido, sobrescreve a navegação padrão do botão Destacar. */
  onHighlight?: () => void | Promise<void>;
  /** Observabilidade opcional após ação bem-sucedida. */
  onCopy?: (kind: "text" | "reference") => void;
  onShare?: () => void;
  /** Tamanho visual dos botões. */
  size?: "sm" | "md";
  /** Classes extras aplicadas ao wrapper. */
  className?: string;
}

async function writeClipboard(value: string): Promise<boolean> {
  try {
    if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
      return true;
    }
  } catch {
    /* fallthrough */
  }
  return false;
}

const PassageActions: React.FC<PassageActionsProps> = ({
  text,
  reference,
  url,
  passage,
  title,
  onHighlight,
  onCopy,
  onShare,
  size = "sm",
  className,
}) => {
  const share = useShare();
  const navigate = useNavigate();
  // Estados INDEPENDENTES por ação (loading/success/error) — nunca globais.
  const [loadingMap, setLoadingMap] = useState<Partial<Record<ActionKey, boolean>>>({});
  const [successMap, setSuccessMap] = useState<Partial<Record<ActionKey, boolean>>>({});
  const [errorMap, setErrorMap] = useState<Partial<Record<ActionKey, string>>>({});
  const [status, setStatus] = useState<string>("");

  // URL efetiva: prop direta ou derivada de `passage`.
  const effectiveUrl = url ?? (passage ? buildPassageUrl(passage) : "");

  // Destaque efetivo: callback custom OU navegação padrão para o Reader.
  const canHighlight = Boolean(onHighlight || passage);

  const run = useCallback(async (key: ActionKey, fn: () => Promise<void>, successMsg?: string) => {
    setLoadingMap((m) => ({ ...m, [key]: true }));
    setErrorMap((m) => ({ ...m, [key]: undefined }));
    setSuccessMap((m) => ({ ...m, [key]: false }));
    try {
      await fn();
      if (successMsg) setStatus(successMsg);
      setSuccessMap((m) => ({ ...m, [key]: true }));
      // limpa o "success" transiente após 1.6s
      window.setTimeout(() => {
        setSuccessMap((m) => ({ ...m, [key]: false }));
      }, 1600);
    } catch (err: any) {
      const message = err?.message ?? "Ação falhou";
      setErrorMap((m) => ({ ...m, [key]: message }));
      setStatus(`Erro: ${message}`);
      toast.error(message);
    } finally {
      setLoadingMap((m) => ({ ...m, [key]: false }));
    }
  }, []);

  const handleCopyText = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      return run(
        "text",
        async () => {
          const ok = await writeClipboard(
            effectiveUrl
              ? `"${text}"\n— ${reference}\n${effectiveUrl}`
              : `"${text}"\n— ${reference}`,
          );
          if (!ok) throw new Error("Não foi possível copiar");
          toast.success("Trecho copiado");
          onCopy?.("text");
        },
        "Trecho copiado",
      );
    },
    [run, text, reference, effectiveUrl, onCopy],
  );

  const handleCopyReference = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      return run(
        "reference",
        async () => {
          const ok = await writeClipboard(reference);
          if (!ok) throw new Error("Não foi possível copiar");
          toast.success("Referência copiada");
          onCopy?.("reference");
        },
        "Referência copiada",
      );
    },
    [run, reference, onCopy],
  );

  const handleShare = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      return run(
        "share",
        async () => {
          await share({
            title: title ?? reference,
            text: `"${text}" — ${reference}`,
            url: effectiveUrl || undefined,
          });
          onShare?.();
        },
        "Compartilhado",
      );
    },
    [run, share, title, reference, text, effectiveUrl, onShare],
  );

  const handleHighlight = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      return run("highlight", async () => {
        if (onHighlight) {
          await onHighlight();
        } else if (passage) {
          const dest = buildPassageUrl({ ...passage, highlight: passage.highlight ?? reference });
          // Extrai apenas pathname+search para navegação SPA
          const rel = dest.startsWith("http") ? dest.replace(/^https?:\/\/[^/]+/, "") : dest;
          navigate(rel);
        }
      });
    },
    [run, onHighlight, passage, reference, navigate],
  );

  const btnBase = cn(
    "inline-flex items-center gap-1.5 rounded-full border border-border/50",
    "bg-background/60 hover:bg-primary/5 hover:border-primary/40",
    "text-muted-foreground hover:text-primary",
    "transition-colors",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background",
    "disabled:opacity-60 disabled:cursor-not-allowed",
    "min-h-[44px] min-w-[44px]",
    size === "sm" ? "px-2.5 py-1 text-[11px]" : "px-3 py-1.5 text-xs",
  );
  const iconSize = size === "sm" ? "w-3.5 h-3.5" : "w-4 h-4";

  const renderIcon = (key: ActionKey, Icon: React.ComponentType<any>) => {
    if (loadingMap[key]) {
      return <Icons.Loader className={cn(iconSize, "animate-spin")} aria-hidden="true" />;
    }
    if (successMap[key]) {
      return <Icons.Check className={cn(iconSize, "text-primary")} aria-hidden="true" />;
    }
    return <Icon className={iconSize} aria-hidden="true" />;
  };

  const firstError = (Object.entries(errorMap).find(([, v]) => !!v) ?? []) as [ActionKey?, string?];

  return (
    <div
      className={cn("flex flex-wrap items-center gap-1.5", className)}
      role="group"
      aria-label={`Ações para ${reference}`}
      onClick={(e) => e.stopPropagation()}
    >
      {/* Live region para leitores de tela: sucesso/erro por ação. */}
      <span className="sr-only" aria-live="polite" aria-atomic="true">
        {status}
      </span>

      <button
        type="button"
        onClick={handleCopyText}
        className={btnBase}
        aria-label={`Copiar trecho de ${reference}`}
        aria-busy={loadingMap.text || undefined}
        disabled={!!loadingMap.text}
      >
        {renderIcon("text", Icons.Quote)}
        <span>Copiar trecho</span>
      </button>

      <button
        type="button"
        onClick={handleCopyReference}
        className={btnBase}
        aria-label={`Copiar referência ${reference}`}
        aria-busy={loadingMap.reference || undefined}
        disabled={!!loadingMap.reference}
      >
        {renderIcon("reference", Icons.Link)}
        <span>Copiar referência</span>
      </button>

      <button
        type="button"
        onClick={handleShare}
        className={btnBase}
        aria-label={`Compartilhar ${reference}`}
        aria-busy={loadingMap.share || undefined}
        disabled={!!loadingMap.share}
      >
        {renderIcon("share", Icons.Share)}
        <span>Compartilhar</span>
      </button>

      {canHighlight && (
        <button
          type="button"
          onClick={handleHighlight}
          className={btnBase}
          aria-label={`Destacar ${reference} no leitor`}
          aria-busy={loadingMap.highlight || undefined}
          disabled={!!loadingMap.highlight}
        >
          {renderIcon("highlight", Icons.Highlighter)}
          <span>Destacar</span>
        </button>
      )}

      {firstError[0] && (
        <span role="alert" className="sr-only">
          Erro em {firstError[0]}: {firstError[1]}
        </span>
      )}
    </div>
  );
};

PassageActions.displayName = "PassageActions";

export default PassageActions;

