  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  isLoading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    { className, variant, size, asChild = false, isLoading = false, children, disabled, ...props },
    ref,
  ) => {
    const Comp = asChild ? Slot : "button";

    // Accessibility: aria-busy and aria-disabled for loading state
    const buttonProps = {
      className: cn(buttonVariants({ variant, size, className })),
      ref,
      disabled: isLoading || disabled,
      "aria-busy": isLoading ? true : undefined,
      "aria-disabled": isLoading || disabled ? true : undefined,
      ...props,
    };

    return (
      <Comp {...buttonProps}>
        {isLoading ? (
          <>
            <Icons.Loader className="animate-spin" />
            {size !== "icon" && size !== "icon-sm" && size !== "icon-xs" && children}
          </>
        ) : (
          children
        )}
      </Comp>
    );
  },
);
