export const getRouteByPath = (path: string) => {
  // STAB-003D: preferir match exato antes de fallback por prefixo, evitando
  // que `/admin/audit` e `/magisterium/:id` retornem duas vezes o pai e gerem
  // chaves duplicadas no breadcrumb do AppHeader.
  return (
    APP_ROUTES.find((r) => r.path === path) ||
    APP_ROUTES.find((r) => r.path !== "/" && path.startsWith(r.path + "/")) ||
    APP_ROUTES.find((r) => r.path !== "/" && path.startsWith(r.path))
  );
};

export const getBreadcrumbs = (path: string) => {
  const parts = path.split("/").filter(Boolean);
  const breadcrumbs: RouteConfig[] = [];
  const seen = new Set<string>();
  let currentPath = "";

  for (const part of parts) {
    currentPath += `/${part}`;
    const route = getRouteByPath(currentPath);
    // STAB-003D: deduplica por path para evitar chaves repetidas quando
    // um segmento filho (ex.: `/magisterium/dce`) não tem rota própria e
    // cai no pai (`/magisterium`).
    if (route && !seen.has(route.path)) {
      seen.add(route.path);
      breadcrumbs.push(route);
    }
  }

  return breadcrumbs;
};

import React, { createContext, useCallback, useContext, useMemo, useState } from "react";

interface CatechismPendingContextValue {
  pending: number[];
  markPending: (paragraph: number) => void;
  clearPending: (paragraph: number) => void;
}

const CatechismPendingContext = createContext<CatechismPendingContextValue | null>(null);

export const CatechismPendingProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [pendingSet, setPendingSet] = useState<Set<number>>(() => new Set());

  const markPending = useCallback((paragraph: number) => {
    setPendingSet((prev) => {
      if (prev.has(paragraph)) return prev;
      const next = new Set(prev);
      next.add(paragraph);
      return next;
    });
  }, []);

  const clearPending = useCallback((paragraph: number) => {
    setPendingSet((prev) => {
      if (!prev.has(paragraph)) return prev;
      const next = new Set(prev);
      next.delete(paragraph);
      return next;
    });
  }, []);

  const pending = useMemo(() => Array.from(pendingSet).sort((a, b) => a - b), [pendingSet]);

  const value = useMemo(
    () => ({ pending, markPending, clearPending }),
    [pending, markPending, clearPending],
  );

  return (
    <CatechismPendingContext.Provider value={value}>{children}</CatechismPendingContext.Provider>
  );
};

export const useCatechismPending = () => {
  const ctx = useContext(CatechismPendingContext);
  // Safe no-op fallback so CatechismContent works outside the reading view too.
  if (!ctx) {
    return {
      pending: [] as number[],
      markPending: (_p: number) => {},
      clearPending: (_p: number) => {},
    };
  }
  return ctx;
};

import React, { createContext, useState, useCallback, useMemo, useEffect } from "react";
import type { Language } from "@/types";
import { UI_TRANSLATIONS } from "@/services/translations";
import {
  DEFAULT_LOCALE,
  detectLocaleFromPath,
  getLocaleDefinition,
  isSupportedLocale,
  withLocalePath,
} from "@/lib/i18n/locales";

export interface LanguageContextType {
  lang: Language;
  setLang: (lang: Language) => void;
  t: (key: string) => string;
}

export const LangContext = createContext<LanguageContextType>({
  lang: DEFAULT_LOCALE,
  setLang: () => {},
  t: (key) => key,
});

/**
 * O idioma é derivado da URL (`/en/...`), que é a fonte de verdade para SEO.
 * O localStorage guarda apenas a preferência para redirecionar o usuário
 * na próxima visita à raiz.
 */
export const LangProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  useEffect(() => {
    // Expondo a função t globalmente para testes E2E
    (window as any).cathedra_t = (key: string) => {
      // Esta é uma implementação simplificada para o teste conseguir acessar o contexto
      // No mundo real, poderíamos usar um CustomEvent ou similar se necessário
      return key;
    };
  }, []);
  const [lang, setLangState] = useState<Language>(() => {
    try {
      const fromPath = detectLocaleFromPath(window.location.pathname);
      if (fromPath !== DEFAULT_LOCALE) return fromPath;
      const stored = localStorage.getItem("cathedra_lang");
      return isSupportedLocale(stored) ? stored : DEFAULT_LOCALE;
    } catch {
      return DEFAULT_LOCALE;
    }
  });

  const t = useCallback(
    (k: string) => {
      const val = UI_TRANSLATIONS[lang]?.[k];
      if (val === undefined) {
        // Fallback para Português se a tradução faltar no idioma atual
        const fallback = UI_TRANSLATIONS[DEFAULT_LOCALE]?.[k];
        if (fallback !== undefined) return fallback;

        // Fallback final: Log e retornar a chave formatada para evitar strings vazias
        console.warn(`[i18n] Chave ausente: "${k}" para o idioma "${lang}"`);
        return k;
      }
      return val;
    },
    [lang],
  );

  useEffect(() => {
    try {
      localStorage.setItem("cathedra_lang", lang);
    } catch {
      /* storage indisponível */
    }
    document.documentElement.lang = getLocaleDefinition(lang).hreflang;
  }, [lang]);

  /**
   * Trocar de idioma muda o prefixo da URL. Como o prefixo é o `basename` do
   * router (definido no boot), a navegação é feita com recarga completa —
   * garante estado limpo e URL canônica correta.
   */
  const setLang = useCallback((next: Language) => {
    if (!isSupportedLocale(next)) return;
    setLangState(next);
    try {
      localStorage.setItem("cathedra_lang", next);
      const target =
        withLocalePath(window.location.pathname, next) +
        window.location.search +
        window.location.hash;
      if (target !== window.location.pathname + window.location.search + window.location.hash) {
        window.location.assign(target);
      }
    } catch {
      /* noop */
    }
  }, []);

  const value = useMemo(() => ({ lang, setLang, t }), [lang, setLang, t]);

  return <LangContext.Provider value={value}>{children}</LangContext.Provider>;
};

