const SettingsSideEffects: React.FC = () => {
  const { settings } = useReadingSettings();

  useEffect(() => {
    if (!settings.focusMode) return;

    const revealUI = () => {
      document.documentElement.classList.add("reveal-chrome");

      // Auto-hide again after 3 seconds of inactivity
      const timeout = setTimeout(() => {
        document.documentElement.classList.remove("reveal-chrome");
      }, 3000);

      return () => clearTimeout(timeout);
    };

    const handleInteraction = () => revealUI();

    window.addEventListener("click", handleInteraction);
    window.addEventListener("touchstart", handleInteraction);
    const handleMouseMove = (e: MouseEvent) => {
      if (e.clientY < 50 || e.clientY > window.innerHeight - 50) {
        handleInteraction();
      }
    };
    window.addEventListener("mousemove", handleMouseMove);

    return () => {
      window.removeEventListener("click", handleInteraction);
      window.removeEventListener("touchstart", handleInteraction);
      window.removeEventListener("mousemove", handleMouseMove);
    };
  }, [settings.focusMode]);

  useEffect(() => {
    // Apply theme to body
    const root = document.documentElement;
    root.classList.remove(
      "reading-theme-paper",
      "reading-theme-sepia",
      "reading-theme-dark",
      "reading-theme-night",
    );
    root.classList.add(`reading-theme-${settings.theme}`);

    // Night mode specific
    if (settings.theme === "night") {
      root.classList.add("reading-night");
      root.classList.add("dark");
    } else if (settings.theme === "dark") {
      root.classList.remove("reading-night");
      root.classList.add("dark");
    } else {
      root.classList.remove("reading-night");
      root.classList.remove("dark");
    }

    // Apply Contrast
    root.classList.remove("contrast-soft", "contrast-high");
    root.setAttribute("data-contrast", settings.contrast);
    if (settings.contrast !== "normal") {
      root.classList.add(`contrast-${settings.contrast}`);
    }

    // Apply Font Size to Root for UI scalability
    root.classList.remove(
      "font-size-small",
      "font-size-medium",
      "font-size-large",
      "font-size-extra-large",
    );
    root.classList.add(`font-size-${settings.fontSize}`);

    // Apply Spacing
    root.setAttribute("data-line-spacing", settings.lineSpacing);
    root.setAttribute("data-letter-spacing", settings.letterSpacing);
    root.setAttribute("data-side-margins", settings.sideMargins);
    root.style.setProperty("--reader-column-width", `${settings.columnWidth}ch`);

    const toggleClass = (cls: string, active: boolean) => {
      if (active) root.classList.add(cls);
      else root.classList.remove(cls);
    };

    toggleClass("auto-hide-ui", settings.autoHideUI);
    toggleClass("visual-silence", settings.visualSilence);
    toggleClass("high-contrast", settings.highContrast);
    toggleClass("contemplative-mode", settings.contemplativeMode);
    toggleClass("visible-focus-mode", settings.visibleFocus);
    toggleClass("reduce-animations", settings.reduceAnimations);
    toggleClass("total-silence", settings.totalSilence);
    toggleClass("full-screen-mode", settings.fullScreen);
    toggleClass("focus-mode", settings.focusMode);
    toggleClass("immersive-mode", settings.immersiveMode);
  }, [settings]);

  // Auto-hide UI ao rolar (mobile / contemplativo)
  useEffect(() => {
    if (!settings.autoHideUI && !settings.contemplativeMode) {
      document.documentElement.classList.remove("reading-scroll-down");
      return;
    }
    let lastY = window.scrollY;
    let ticking = false;
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        const y = window.scrollY;
        if (Math.abs(y - lastY) > 8) {
          if (y > lastY && y > 80) {
            document.documentElement.classList.add("reading-scroll-down");
            document.documentElement.classList.remove("reveal-chrome");
          } else {
            document.documentElement.classList.remove("reading-scroll-down");
          }
          lastY = y;
        }
        ticking = false;
      });
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      document.documentElement.classList.remove("reading-scroll-down");
    };
  }, [settings.autoHideUI, settings.contemplativeMode]);

  return null;
};

export const ReadingSettingsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user, profile, refreshProfile } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const [settings, setSettings] = useState<ReadingSettings>(() => {
    const isMobile = typeof window !== "undefined" && window.innerWidth < 1024;
    const key = isMobile ? "cathedra_reading_settings_mobile" : "cathedra_reading_settings_desktop";
    const stored = localStorage.getItem(key);
    const parsed = stored ? JSON.parse(stored) : defaultSettings;

    // Fallback para chave antiga se necessário
    if (!stored) {
      const legacy = localStorage.getItem("cathedra_reading_settings");
      if (legacy) return { ...defaultSettings, ...JSON.parse(legacy) };
    }

    return { ...defaultSettings, ...parsed };
  });

  // Sync with profile if available
  useEffect(() => {
    if (profile?.reading_settings && Object.keys(profile.reading_settings).length > 0) {
      const remoteSettings = profile.reading_settings as ReadingSettings;

      setSettings((prev) => {
        // Only update if remote settings are actually different AND not older than local
        // If remote has no timestamp but local has, we might want to keep local
        const remoteTimestamp = remoteSettings.lastUpdated || 0;
        const localTimestamp = prev.lastUpdated || 0;

        if (remoteTimestamp < localTimestamp) {
          console.log("Keeping local settings as they are newer than remote profile");
          return prev;
        }

        const remoteStr = JSON.stringify(remoteSettings);
        const prevStr = JSON.stringify(prev);
        if (remoteStr === prevStr) return prev;

        console.log("Updating settings from remote profile");
        return { ...prev, ...remoteSettings };
      });
    }
    setIsLoading(false);
  }, [profile?.reading_settings]);

  useEffect(() => {
    const isMobile = typeof window !== "undefined" && window.innerWidth < 1024;
    const key = isMobile ? "cathedra_reading_settings_mobile" : "cathedra_reading_settings_desktop";
    localStorage.setItem(key, JSON.stringify(settings));
    // Keep legacy for compatibility
    localStorage.setItem("cathedra_reading_settings", JSON.stringify(settings));
  }, [settings]);

  const settingsRef = useRef(settings);
  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);

  const updateSettings = useCallback(
    async (newSettings: Partial<ReadingSettings>) => {
      const updated = { ...settingsRef.current, ...newSettings, lastUpdated: Date.now() };
      setSettings(updated);

      if (user) {
        const { error } = await supabase
          .from("profiles")
          .update({
            reading_settings: updated as any,
            notification_settings: {
              daily_reminder: updated.reminders,
            },
          })
          .eq("id", user.id);

        if (error) {
          console.error("Error syncing reading settings:", error);
        } else {
          refreshProfile();
        }
      }
    },
    [user, refreshProfile],
  ); // Removed settings dependency

  const resetSettings = useCallback(async () => {
    const reset = { ...defaultSettings, lastUpdated: Date.now() };
    setSettings(reset);
    if (user) {
      await supabase
        .from("profiles")
        .update({
          reading_settings: reset as any,
        })
        .eq("id", user.id);
      refreshProfile();
    }
  }, [user, refreshProfile]);

  useEffect(() => {
    const handleToggle = (e: any) => {
      const newValue = e.detail;
      updateSettings({ totalSilence: newValue });
      toast.success(newValue ? "Silêncio Total Ativado" : "Silêncio Total Desativado", {
        description: newValue ? "Ambiente de oração absoluta." : "Interface e áudio restaurados.",
        icon: newValue ? "🤫" : "🔊",
      });
    };

    const handleKeyboardShortcut = (e: KeyboardEvent) => {
      // Alt + S or Option + S
      if (e.altKey && e.key.toLowerCase() === "s") {
        e.preventDefault();
        const newValue = !settings.totalSilence;
        updateSettings({ totalSilence: newValue });
        toast.success(newValue ? "Silêncio Total Ativado" : "Silêncio Total Desativado", {
          description: newValue ? "Ambiente de oração absoluta." : "Interface e áudio restaurados.",
          icon: newValue ? "🤫" : "🔊",
        });
      }
    };

    window.addEventListener("toggle-total-silence", handleToggle);
    window.addEventListener("keydown", handleKeyboardShortcut);
    return () => {
      window.removeEventListener("toggle-total-silence", handleToggle);
      window.removeEventListener("keydown", handleKeyboardShortcut);
    };
  }, [updateSettings, settings.totalSilence]);

  // Modo noturno agendado (transição gradual via CSS)
  useEffect(() => {
    const sch = settings.nightSchedule;
    if (!sch?.enabled) return;
    const check = () => {
      const now = new Date();
      const m = now.getHours() * 60 + now.getMinutes();
      const [sh, sm] = sch.start.split(":").map(Number);
      const [eh, em] = sch.end.split(":").map(Number);
      const a = sh * 60 + sm;
      const b = eh * 60 + em;
      const inNight = a <= b ? m >= a && m < b : m >= a || m < b;
      if (inNight && settings.theme !== "night") updateSettings({ theme: "night" });
      else if (!inNight && settings.theme === "night") updateSettings({ theme: "paper" });
    };
    check();
    const id = window.setInterval(check, 60_000);
    return () => window.clearInterval(id);
  }, [settings.nightSchedule, settings.theme, updateSettings]);

  const value = useMemo(
    () => ({ settings, updateSettings, resetSettings, isLoading }),
    [settings, updateSettings, resetSettings, isLoading],
  );

  return (
    <ReadingSettingsContext.Provider value={value}>
      <SettingsSideEffects />
      {children}
    </ReadingSettingsContext.Provider>
  );
};

export const useReadingSettings = () => {
  const context = useContext(ReadingSettingsContext);
  if (context === undefined) {
    throw new Error("useReadingSettings must be used within a ReadingSettingsProvider");
  }
  return context;
};

/**
 * JourneyAdapter — camada de compatibilidade `itineraria*` → `journeys*`.
 *
 * Uso interno do Journey Core. NÃO exportar pelo barrel.
 *
 * Estratégia:
 * - IDs de itineraria são prefixados com `itin:` para evitar colisão com
 *   UUIDs reais de `journeys`. Consumidores tratam o Journey como opaco.
 * - Conteúdo é normalizado: `html` ↔ `interpretation` (fallback bidirecional).
 * - Escrita no path legado é bloqueada nesta fase (Fase D fará a migração
 *   definitiva).
 */

import type { Journey, JourneyStep, JourneyStepContent } from "./types";

export const LEGACY_ID_PREFIX = "itin:";

export const JourneyAdapter = {
  isLegacyId(id: string): boolean {
    return typeof id === "string" && id.startsWith(LEGACY_ID_PREFIX);
  },

  toLegacyId(rawId: string): string {
    return `${LEGACY_ID_PREFIX}${rawId}`;
  },

  fromLegacyId(id: string): string {
    return id.startsWith(LEGACY_ID_PREFIX) ? id.slice(LEGACY_ID_PREFIX.length) : id;
  },

  normalizeContent(content: unknown): JourneyStepContent {
    const c: JourneyStepContent =
      content && typeof content === "object" ? { ...(content as JourneyStepContent) } : {};
    if (!c.interpretation && typeof c.html === "string") {
      c.interpretation = c.html;
    } else if (!c.html && typeof c.interpretation === "string") {
      c.html = c.interpretation;
    }
    return c;
  },

  fromItineraria(row: Record<string, any>): Journey {
    return {
      id: JourneyAdapter.toLegacyId(row.id),
      title: row.title,
      subtitle: row.subtitle ?? null,
      description: row.description ?? null,
      icon: row.icon ?? null,
      cover_url: row.cover_url ?? null,
      category: row.category ?? null,
      difficulty: row.difficulty ?? null,
      estimated_days: row.estimated_days ?? null,
      is_premium: !!row.is_premium,
      is_active: row.is_active !== false,
      sort_order: row.sort_order ?? 0,
      tags: row.tags ?? null,
      created_at: row.created_at,
      updated_at: row.updated_at,
      is_legacy: true,
    };
  },

  fromItinerariaStep(row: Record<string, any>): JourneyStep {
    return {
      id: JourneyAdapter.toLegacyId(row.id),
      journey_id: JourneyAdapter.toLegacyId(row.itinerarium_id),
      step_order: row.step_order,
      title: row.title,
      subtitle: row.subtitle ?? null,
      step_type: row.step_type,
      content: JourneyAdapter.normalizeContent(row.content),
      duration_minutes: row.duration_minutes ?? null,
      is_free: row.is_free !== false,
      created_at: row.created_at,
      updated_at: row.updated_at,
      is_legacy: true,
    };
  },

  fromJourneyRow(row: Record<string, any>): Journey {
    return {
      id: row.id,
      title: row.title,
      subtitle: row.subtitle ?? null,
      description: row.description ?? null,
      icon: row.icon ?? null,
      cover_url: row.cover_url ?? null,
      category: row.category ?? null,
      difficulty: row.difficulty ?? null,
      estimated_days: row.estimated_days ?? null,
      is_premium: !!row.is_premium,
      is_active: row.is_active !== false,
      sort_order: row.sort_order ?? 0,
      tags: row.tags ?? null,
      created_at: row.created_at,
      updated_at: row.updated_at,
      is_legacy: false,
    };
  },

  fromJourneyStepRow(row: Record<string, any>): JourneyStep {
    return {
      id: row.id,
      journey_id: row.journey_id,
      step_order: row.step_order,
      title: row.title,
      subtitle: row.subtitle ?? null,
      step_type: row.step_type,
      content: JourneyAdapter.normalizeContent(row.content),
      duration_minutes: row.duration_minutes ?? null,
      is_free: row.is_free !== false,
      created_at: row.created_at,
      updated_at: row.updated_at,
      is_legacy: false,
    };
  },
};

/**
 * JourneyService — API pública oficial do domínio Journey.
 *
 * Regra: nenhum componente de UI consulta o backend diretamente para
 * `journeys | journey_steps | journey_progress | itineraria*`. Todo acesso
 * passa por este service.
 *
 * Fluxo: UI → JourneyService → JourneyAdapter → backend.
 *
 * Compatibilidade: `itineraria` é lida via adapter durante a Fase C. Escrita
 * no path legado é bloqueada — admin edita apenas `journeys` reais.
 */

import { supabase } from "@/lib/db";
import { JourneyAdapter } from "./JourneyAdapter";
import type {
  Journey,
  JourneyCreateInput,
  JourneyGlobalStats,
  JourneyListFilters,
  JourneyNexusLink,
  JourneyPatch,
  JourneyProgress,
  JourneyRecommendation,
  JourneyStats,
  JourneyStep,
  JourneyStepUpsertInput,
  ServiceResult,
} from "./types";

type SB = typeof supabase;

function ok<T>(data: T): ServiceResult<T> {
  return { data, error: null };
}
function fail<T>(error: unknown): ServiceResult<T> {
  const err = error instanceof Error ? error : new Error(String(error));
  return { data: null, error: err };
}

const LEGACY_WRITE_ERROR = new Error(
  "[JourneyService] Escrita bloqueada em conteúdo legado (itineraria). Migre para journeys antes de editar.",
);

async function fetchJourneyById(id: string): Promise<Journey | null> {
  if (JourneyAdapter.isLegacyId(id)) {
    const raw = JourneyAdapter.fromLegacyId(id);
    const { data, error } = await (supabase as SB)
      .from("itineraria" as any)
      .select("*")
      .eq("id", raw)
      .maybeSingle();
    if (error) throw error;
    return data ? JourneyAdapter.fromItineraria(data as any) : null;
  }
  const { data, error } = await supabase.from("journeys").select("*").eq("id", id).maybeSingle();
  if (error) throw error;
  return data ? JourneyAdapter.fromJourneyRow(data as any) : null;
}

export const JourneyService = {
  // ─────────────────────────── Leitura ───────────────────────────

  async list(filters: JourneyListFilters = {}): Promise<ServiceResult<Journey[]>> {
    try {
      let q = supabase.from("journeys").select("*");
      if (filters.category) q = q.eq("category", filters.category);
      if (filters.difficulty) q = q.eq("difficulty", filters.difficulty);
      if (typeof filters.is_premium === "boolean") q = q.eq("is_premium", filters.is_premium);
      if (typeof filters.is_active === "boolean") q = q.eq("is_active", filters.is_active);
      if (filters.tags?.length) q = q.overlaps("tags", filters.tags);
      if (filters.search) q = q.ilike("title", `%${filters.search}%`);
      q = q.order("sort_order", { ascending: true });
      if (filters.limit) q = q.limit(filters.limit);
      if (filters.offset) q = q.range(filters.offset, filters.offset + (filters.limit ?? 50) - 1);

      const { data, error } = await q;
      if (error) throw error;
      return ok((data ?? []).map((r) => JourneyAdapter.fromJourneyRow(r as any)));
    } catch (e) {
      return fail(e);
    }
  },

  /**
   * Busca por slug. Como o schema atual não tem coluna `slug`, tratamos o
   * parâmetro como `id` (UUID puro ou prefixado `itin:`). Deep links legados
   * `/jornadas/:id` continuam funcionando.
   */
  async getBySlug(slug: string): Promise<ServiceResult<Journey>> {
    return JourneyService.getById(slug);
  },

  async getById(id: string): Promise<ServiceResult<Journey>> {
    try {
      const j = await fetchJourneyById(id);
      return ok(j as Journey);
    } catch (e) {
      return fail(e);
    }
  },

  async listSteps(journeyId: string): Promise<ServiceResult<JourneyStep[]>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) {
        const raw = JourneyAdapter.fromLegacyId(journeyId);
        const { data, error } = await (supabase as SB)
          .from("itineraria_steps" as any)
          .select("*")
          .eq("itinerarium_id", raw)
          .order("step_order", { ascending: true });
        if (error) throw error;
        return ok((data ?? []).map((r) => JourneyAdapter.fromItinerariaStep(r as any)));
      }
      const { data, error } = await supabase
        .from("journey_steps")
        .select("*")
        .eq("journey_id", journeyId)
        .order("step_order", { ascending: true });
      if (error) throw error;
      return ok((data ?? []).map((r) => JourneyAdapter.fromJourneyStepRow(r as any)));
    } catch (e) {
      return fail(e);
    }
  },

  async getStep(journeyId: string, order: number): Promise<ServiceResult<JourneyStep>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) {
        const raw = JourneyAdapter.fromLegacyId(journeyId);
        const { data, error } = await (supabase as SB)
          .from("itineraria_steps" as any)
          .select("*")
          .eq("itinerarium_id", raw)
          .eq("step_order", order)
          .maybeSingle();
        if (error) throw error;
        return ok(data ? JourneyAdapter.fromItinerariaStep(data as any) : (null as any));
      }
      const { data, error } = await supabase
        .from("journey_steps")
        .select("*")
        .eq("journey_id", journeyId)
        .eq("step_order", order)
        .maybeSingle();
      if (error) throw error;
      return ok(data ? JourneyAdapter.fromJourneyStepRow(data as any) : (null as any));
    } catch (e) {
      return fail(e);
    }
  },

  async getFirstStep(journeyId: string): Promise<ServiceResult<JourneyStep>> {
    return JourneyService.getStep(journeyId, 1);
  },

  async getRelated(journeyId: string, limit = 4): Promise<ServiceResult<Journey[]>> {
    try {
      const { data: base } = await JourneyService.getById(journeyId);
      if (!base) return ok([]);
      let q = supabase
        .from("journeys")
        .select("*")
        .eq("is_active", true)
        .neq("id", JourneyAdapter.isLegacyId(journeyId) ? "" : journeyId)
        .limit(limit);
      if (base.category) q = q.eq("category", base.category);
      const { data, error } = await q;
      if (error) throw error;
      return ok((data ?? []).map((r) => JourneyAdapter.fromJourneyRow(r as any)));
    } catch (e) {
      return fail(e);
    }
  },

  // ─────────────────────────── Progresso ───────────────────────────

  async getProgress(userId: string, journeyId: string): Promise<ServiceResult<JourneyProgress[]>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) {
        const raw = JourneyAdapter.fromLegacyId(journeyId);
        const { data, error } = await (supabase as SB)
          .from("itineraria_progress" as any)
          .select("*")
          .eq("user_id", userId)
          .eq("itinerarium_id", raw);
        if (error) throw error;
        return ok(
          (data ?? []).map((r: any) => ({
            id: r.id,
            user_id: r.user_id,
            journey_id: JourneyAdapter.toLegacyId(r.itinerarium_id),
            step_id: r.step_id ? JourneyAdapter.toLegacyId(r.step_id) : null,
            completed_at: r.completed_at,
            reflection: r.reflection ?? null,
          })),
        );
      }
      const { data, error } = await supabase
        .from("journey_progress")
        .select("*")
        .eq("user_id", userId)
        .eq("journey_id", journeyId);
      if (error) throw error;
      return ok((data ?? []) as JourneyProgress[]);
    } catch (e) {
      return fail(e);
    }
  },

  async startJourney(userId: string, journeyId: string): Promise<ServiceResult<JourneyProgress>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) return fail(LEGACY_WRITE_ERROR);
      const { data: first } = await JourneyService.getFirstStep(journeyId);
      const { data, error } = await supabase
        .from("journey_progress")
        .insert({
          user_id: userId,
          journey_id: journeyId,
          step_id: first?.id ?? null,
        })
        .select()
        .maybeSingle();
      if (error) throw error;
      return ok(data as JourneyProgress);
    } catch (e) {
      return fail(e);
    }
  },

  async completeStep(
    userId: string,
    journeyId: string,
    stepOrder: number,
    reflection?: string,
  ): Promise<ServiceResult<JourneyProgress>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) return fail(LEGACY_WRITE_ERROR);
      const { data: step } = await JourneyService.getStep(journeyId, stepOrder);
      if (!step) throw new Error(`Passo ${stepOrder} não encontrado`);
      const { data, error } = await supabase
        .from("journey_progress")
        .insert({
          user_id: userId,
          journey_id: journeyId,
          step_id: step.id,
          reflection: reflection ?? null,
        })
        .select()
        .maybeSingle();
      if (error) throw error;
      return ok(data as JourneyProgress);
    } catch (e) {
      return fail(e);
    }
  },

  async resumeJourney(userId: string, journeyId: string): Promise<ServiceResult<JourneyStep>> {
    try {
      const { data: progress } = await JourneyService.getProgress(userId, journeyId);
      const { data: steps } = await JourneyService.listSteps(journeyId);
      if (!steps || steps.length === 0) return ok(null as any);
      const doneIds = new Set((progress ?? []).map((p) => p.step_id));
      const next = steps.find((s) => !doneIds.has(s.id)) ?? steps[steps.length - 1];
      return ok(next);
    } catch (e) {
      return fail(e);
    }
  },

  async listUserJourneys(userId: string): Promise<ServiceResult<Journey[]>> {
    try {
      const { data, error } = await supabase
        .from("journey_progress")
        .select("journey_id")
        .eq("user_id", userId);
      if (error) throw error;
      const ids = Array.from(new Set((data ?? []).map((r: any) => r.journey_id).filter(Boolean)));
      if (ids.length === 0) return ok([]);
      const { data: js, error: e2 } = await supabase.from("journeys").select("*").in("id", ids);
      if (e2) throw e2;
      return ok((js ?? []).map((r) => JourneyAdapter.fromJourneyRow(r as any)));
    } catch (e) {
      return fail(e);
    }
  },

  async resetProgress(userId: string, journeyId: string): Promise<ServiceResult<true>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) return fail(LEGACY_WRITE_ERROR);
      const { error } = await supabase
        .from("journey_progress")
        .delete()
        .eq("user_id", userId)
        .eq("journey_id", journeyId);
      if (error) throw error;
      return ok(true);
    } catch (e) {
      return fail(e);
    }
  },

  // ─────────────────────────── Admin ───────────────────────────

  async createJourney(input: JourneyCreateInput): Promise<ServiceResult<Journey>> {
    try {
      const { data, error } = await supabase.from("journeys").insert(input).select().maybeSingle();
      if (error) throw error;
      return ok(JourneyAdapter.fromJourneyRow(data as any));
    } catch (e) {
      return fail(e);
    }
  },

  async updateJourney(id: string, patch: JourneyPatch): Promise<ServiceResult<Journey>> {
    try {
      if (JourneyAdapter.isLegacyId(id)) return fail(LEGACY_WRITE_ERROR);
      const { data, error } = await supabase
        .from("journeys")
        .update(patch)
        .eq("id", id)
        .select()
        .maybeSingle();
      if (error) throw error;
      return ok(JourneyAdapter.fromJourneyRow(data as any));
    } catch (e) {
      return fail(e);
    }
  },

  async upsertStep(
    journeyId: string,
    step: JourneyStepUpsertInput,
  ): Promise<ServiceResult<JourneyStep>> {
    try {
      if (JourneyAdapter.isLegacyId(journeyId)) return fail(LEGACY_WRITE_ERROR);
      const payload = { ...step, journey_id: journeyId };
      const { data, error } = await supabase
        .from("journey_steps")
        .upsert(payload as any)
        .select()
        .maybeSingle();
      if (error) throw error;
      return ok(JourneyAdapter.fromJourneyStepRow(data as any));
    } catch (e) {
      return fail(e);
    }
  },

  async deleteJourney(id: string): Promise<ServiceResult<true>> {
    try {
      if (JourneyAdapter.isLegacyId(id)) return fail(LEGACY_WRITE_ERROR);
      const { error } = await supabase.from("journeys").delete().eq("id", id);
      if (error) throw error;
      return ok(true);
    } catch (e) {
      return fail(e);
    }
  },

  // ─────────────────────────── Stats / Nexus ───────────────────────────

  async getStats(journeyId: string): Promise<ServiceResult<JourneyStats>> {
    try {
      const { data: steps } = await JourneyService.listSteps(journeyId);
      const total_steps = steps?.length ?? 0;

      if (JourneyAdapter.isLegacyId(journeyId)) {
        return ok({
          journey_id: journeyId,
          total_steps,
          users_started: 0,
          users_completed: 0,
          completion_rate: 0,
        });
      }
      const { data, error } = await supabase
        .from("journey_progress")
        .select("user_id, step_id")
        .eq("journey_id", journeyId);
      if (error) throw error;
      const rows = data ?? [];
      const users_started = new Set(rows.map((r: any) => r.user_id)).size;
      // completed = usuário concluiu todos os passos
      const byUser = new Map<string, Set<string>>();
      for (const r of rows as any[]) {
        if (!r.step_id) continue;
        if (!byUser.has(r.user_id)) byUser.set(r.user_id, new Set());
        byUser.get(r.user_id)!.add(r.step_id);
      }
      let users_completed = 0;
      byUser.forEach((set) => {
        if (total_steps > 0 && set.size >= total_steps) users_completed += 1;
      });
      const completion_rate = users_started ? users_completed / users_started : 0;
      return ok({
        journey_id: journeyId,
        total_steps,
        users_started,
        users_completed,
        completion_rate,
      });
    } catch (e) {
      return fail(e);
    }
  },

  async getGlobalStats(): Promise<ServiceResult<JourneyGlobalStats>> {
    try {
      const [j, p] = await Promise.all([
        supabase.from("journeys").select("id", { count: "exact", head: true }),
        supabase.from("journey_progress").select("user_id, id"),
      ]);
      if (j.error) throw j.error;
      if (p.error) throw p.error;
      const rows = (p.data ?? []) as any[];
      return ok({
        total_journeys: j.count ?? 0,
        total_active_users: new Set(rows.map((r) => r.user_id)).size,
        total_completions: rows.length,
      });
    } catch (e) {
      return fail(e);
    }
  },

  /**
   * Retorna links do Nexus associados a um passo (best-effort).
   * Se a tabela `nexus_relations` não expuser `step_id` diretamente,
   * consumidores devem cair para `KnowledgeGraph`.
   */
  async getNexusForStep(stepId: string): Promise<ServiceResult<JourneyNexusLink[]>> {
    try {
      const rawId = JourneyAdapter.fromLegacyId(stepId);
      const { data, error } = await (supabase as SB)
        .from("nexus_relations" as any)
        .select("*")
        .or(`source_id.eq.${rawId},target_id.eq.${rawId}`)
        .limit(50);
      if (error) throw error;
      return ok(
        (data ?? []).map((r: any) => ({
          step_id: stepId,
          target_type: r.target_type ?? r.relation_type ?? "unknown",
          target_id: r.target_id ?? r.source_id,
          label: r.label ?? undefined,
        })),
      );
    } catch (e) {
      return fail(e);
    }
  },

  /** Recomendações simples baseadas em categoria + atividade recente. */
  async recommend(userId: string, limit = 3): Promise<ServiceResult<JourneyRecommendation[]>> {
    try {
      const { data: mine } = await JourneyService.listUserJourneys(userId);
      const seen = new Set((mine ?? []).map((j) => j.id));
      const categories = Array.from(new Set((mine ?? []).map((j) => j.category).filter(Boolean)));
      const { data, error } = await supabase
        .from("journeys")
        .select("*")
        .eq("is_active", true)
        .limit(20);
      if (error) throw error;
      const all = (data ?? []).map((r) => JourneyAdapter.fromJourneyRow(r as any));
      const scored = all
        .filter((j) => !seen.has(j.id))
        .map((j) => ({
          journey: j,
          reason:
            j.category && categories.includes(j.category)
              ? `Continua sua formação em ${j.category}`
              : "Novo caminho recomendado",
          score: (j.category && categories.includes(j.category) ? 2 : 0) + (j.is_premium ? 0 : 1),
        }))
        .sort((a, b) => b.score - a.score)
        .slice(0, limit);
      return ok(scored);
    } catch (e) {
      return fail(e);
    }
  },
};

export type JourneyServiceType = typeof JourneyService;

import { BIBLE_DATA } from "./bible-books";

export const getBibleAuditReport = async (
  fetchVerses: (abbr: string, ch: number) => Promise<any[]>,
) => {
  const allBooks = Object.values(BIBLE_DATA)
    .flat()
    .flatMap((cat) => cat.books);
  const report: {
    book: string;
    chapter: number;
    status: "ok" | "empty" | "missing_verses" | "language_violation";
    verseCount: number;
    languageIssues?: string[];
  }[] = [];

  const FORBIDDEN_EN = [
    "the",
    "and",
    "shall",
    "unto",
    "from",
    "Tobit",
    "Judith",
    "Wisdom",
    "Sirach",
    "Baruch",
    "Maccabees",
    "Chapter",
    "Verse",
  ];

  // Comprehensive Sanity Check for Premium Certification
  const booksToSanityCheck = [
    ...allBooks.filter((b) =>
      [
        "Tobias",
        "Judite",
        "Sabedoria",
        "Baruc",
        "1 Macabeus",
        "2 Macabeus",
        "Eclesiástico",
        "Abdias",
      ].includes(b.name),
    ),
    allBooks.find((b) => b.name === "Salmos")!,
    allBooks.find((b) => b.name === "Gênesis")!,
    allBooks.find((b) => b.name === "Mateus")!,
    allBooks.find((b) => b.name === "Apocalipse")!,
  ].filter(Boolean);

  for (const book of booksToSanityCheck) {
    const chaptersToCheck = [1, book.chapters];
    if (book.name === "Salmos") chaptersToCheck.push(23, 119, 151);

    for (const ch of [...new Set(chaptersToCheck)]) {
      if (ch > book.chapters && book.name !== "Salmos") continue;

      try {
        const verses = await fetchVerses(book.abbr, ch);
        if (!verses || verses.length === 0) {
          report.push({ book: book.name, chapter: ch, status: "empty", verseCount: 0 });
        } else {
          // Check for English terms (Language Consistency Validation)
          const languageIssues: string[] = [];
          verses.forEach((v) => {
            const text = v.text || "";
            FORBIDDEN_EN.forEach((term) => {
              const regex = new RegExp(`\\b${term}\\b`, "i");
              if (regex.test(text)) {
                languageIssues.push(`V${v.number}: "${term}" detected`);
              }
            });
          });

          if (languageIssues.length > 0) {
            report.push({
              book: book.name,
              chapter: ch,
              status: "language_violation",
              verseCount: verses.length,
              languageIssues: [...new Set(languageIssues)].slice(0, 5), // Top 5 issues
            });
          } else {
            report.push({ book: book.name, chapter: ch, status: "ok", verseCount: verses.length });
          }
        }
      } catch (e) {
        report.push({ book: book.name, chapter: ch, status: "empty", verseCount: 0 });
      }
    }
  }

  return report;
};

/**
 * Hooks CRUD do Cathedra Collections Studio.
 *
 * Todas as mutações respeitam a RLS existente (`admins manage collections`).
 * Regra de governança: criação sempre em `draft`; publicação só via mutação
 * explícita (transição admin, sem bypass).
 */
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import type {
  Collection,
  CollectionItem,
  CollectionItemMetadata,
  CollectionItemType,
} from "./types";

export type CollectionStatus = "draft" | "review" | "published" | "archived";

/** Lista todas as coleções (admin — inclui rascunhos). */
export function useAdminCollections() {
  return useQuery<Collection[]>({
    queryKey: ["admin", "collections"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("collections")
        .select("*")
        .order("updated_at", { ascending: false });
      if (error) throw error;
      return (data ?? []) as unknown as Collection[];
    },
    staleTime: 30_000,
  });
}

/** Uma coleção + itens (admin — ignora status). */
export function useAdminCollection(id: string | undefined) {
  return useQuery({
    queryKey: ["admin", "collection", id],
    enabled: !!id,
    queryFn: async () => {
      const [{ data: c, error: e1 }, { data: items, error: e2 }] = await Promise.all([
        supabase.from("collections").select("*").eq("id", id!).maybeSingle(),
        supabase
          .from("collection_items")
          .select("*")
          .eq("collection_id", id!)
          .order("order_index", { ascending: true }),
      ]);
      if (e1) throw e1;
      if (e2) throw e2;
      return {
        collection: (c as unknown as Collection) ?? null,
        items: (items ?? []) as unknown as CollectionItem[],
      };
    },
  });
}

export interface CollectionInput {
  slug: string;
  title: string;
  subtitle?: string | null;
  description?: string | null;
  cover?: string | null;
  category: string;
  featured?: boolean;
  space?: "church" | "library" | "cloister" | "atrium";
  eyebrow?: string | null;
  // Metadados editoriais estendidos (Onda 3 · Coleções Inteligentes)
  estimated_reading_time_minutes?: number | null;
  difficulty_level?: "iniciante" | "intermediario" | "avancado" | null;
  hero_quote?: string | null;
  hero_quote_author?: string | null;
  learning_objectives?: string[] | null;
  prerequisites?: string[] | null;
  completion_message?: string | null;
  certificate_eligible?: boolean | null;
}

export function useCreateCollection() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: CollectionInput) => {
      const { data, error } = await supabase
        .from("collections")
        .insert({
          slug: input.slug,
          title: input.title,
          subtitle: input.subtitle ?? null,
          description: input.description ?? null,
          cover: input.cover ?? null,
          category: input.category,
          featured: input.featured ?? false,
          status: "draft", // governança: sempre nasce draft
          nexus_refs: [],
          metadata: {
            space: input.space ?? "church",
            ...(input.eyebrow ? { eyebrow: input.eyebrow } : {}),
          },
        })
        .select("*")
        .single();
      if (error) throw error;
      return data as unknown as Collection;
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin", "collections"] }),
  });
}

export function useUpdateCollection(id: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (patch: Partial<CollectionInput>) => {
      const dbPatch: Record<string, unknown> = {};
      const keys: (keyof CollectionInput)[] = [
        "slug",
        "title",
        "subtitle",
        "description",
        "cover",
        "category",
        "featured",
        "estimated_reading_time_minutes",
        "difficulty_level",
        "hero_quote",
        "hero_quote_author",
        "learning_objectives",
        "prerequisites",
        "completion_message",
        "certificate_eligible",
      ];
      keys.forEach((k) => {
        if (patch[k] !== undefined) dbPatch[k] = patch[k];
      });
      if (patch.space !== undefined || patch.eyebrow !== undefined) {
        const { data: current } = await supabase
          .from("collections")
          .select("metadata")
          .eq("id", id)
          .maybeSingle();
        const meta = (current?.metadata as Record<string, unknown>) ?? {};
        dbPatch.metadata = {
          ...meta,
          ...(patch.space !== undefined ? { space: patch.space } : {}),
          ...(patch.eyebrow !== undefined ? { eyebrow: patch.eyebrow || undefined } : {}),
        };
      }
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await supabase
        .from("collections")
        .update(dbPatch as any)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["admin", "collection", id] });
      qc.invalidateQueries({ queryKey: ["admin", "collections"] });
    },
  });
}

export function useSetCollectionStatus(id: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (status: CollectionStatus) => {
      const { error } = await supabase.from("collections").update({ status }).eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["admin", "collection", id] });
      qc.invalidateQueries({ queryKey: ["admin", "collections"] });
    },
  });
}

export interface AddItemInput {
  collectionId: string;
  itemType: CollectionItemType;
  itemSlug: string;
  titleOverride?: string | null;
  descriptionOverride?: string | null;
  metadata?: CollectionItemMetadata;
}

export function useAddCollectionItem() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: AddItemInput) => {
      // próxima ordem
      const { data: existing } = await supabase
        .from("collection_items")
        .select("order_index")
        .eq("collection_id", input.collectionId)
        .order("order_index", { ascending: false })
        .limit(1);
      const nextOrder = (existing?.[0]?.order_index ?? 0) + 1;

      const { data, error } = await supabase
        .from("collection_items")
        .insert({
          collection_id: input.collectionId,
          item_type: input.itemType,
          item_slug: input.itemSlug,
          order_index: nextOrder,
          title_override: input.titleOverride ?? null,
          description_override: input.descriptionOverride ?? null,
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          metadata: (input.metadata ?? {}) as any,
        })
        .select("*")
        .single();
      if (error) throw error;
      return data as unknown as CollectionItem;
    },
    onSuccess: (_d, vars) =>
      qc.invalidateQueries({ queryKey: ["admin", "collection", vars.collectionId] }),
  });
}

export function useRemoveCollectionItem(collectionId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (itemId: string) => {
      const { error } = await supabase.from("collection_items").delete().eq("id", itemId);
      if (error) throw error;
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin", "collection", collectionId] }),
  });
}

export function useReorderCollectionItems(collectionId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (orderedIds: string[]) => {
      // Atualiza em bloco. Cada update é rápido; N ≤ ~50 na prática.
      await Promise.all(
        orderedIds.map((id, idx) =>
          supabase
            .from("collection_items")
            .update({ order_index: idx + 1 })
            .eq("id", id)
            .then(({ error }) => {
              if (error) throw error;
            }),
        ),
      );
    },
    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin", "collection", collectionId] }),
  });
}

/**
 * Analytics de Coleções — eventos editoriais para gtag/GA4 + Sentry breadcrumb.
 *
 * Emitidos apenas no cliente. Silenciosos em SSR/dev sem gtag. Nunca lançam.
 *
 * Eventos padronizados:
 * - `collection_completed`      → 100% dos itens concluídos, Nexus recomendações visíveis
 * - `collection_prerequisites_viewed` → seção de pré-requisitos renderizada e visível
 * - `collection_certificate_completed` → trilha `certificate_eligible` finalizada
 * - `collection_search_result_clicked` → clique em card de coleção na busca do Acervo
 */

export type CollectionAnalyticsEvent =
  | "collection_completed"
  | "collection_prerequisites_viewed"
  | "collection_certificate_completed"
  | "collection_search_result_clicked";

export interface CollectionEventPayload {
  collection_id?: string;
  collection_slug?: string;
  collection_title?: string;
  category?: string | null;
  difficulty_level?: string | null;
  estimated_reading_time_minutes?: number | null;
  items_total?: number;
  items_completed?: number;
  has_certificate?: boolean;
  extra?: Record<string, unknown>;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Gtag = (...args: any[]) => void;

function getGtag(): Gtag | null {
  if (typeof window === "undefined") return null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const g = (window as any).gtag;
  return typeof g === "function" ? g : null;
}

function getSentry(): { addBreadcrumb: (b: unknown) => void } | null {
  if (typeof window === "undefined") return null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const s = (window as any).Sentry;
  return s && typeof s.addBreadcrumb === "function" ? s : null;
}

export function trackCollectionEvent(
  event: CollectionAnalyticsEvent,
  payload: CollectionEventPayload = {},
): void {
  try {
    const gtag = getGtag();
    if (gtag) {
      gtag("event", event, {
        collection_id: payload.collection_id,
        collection_slug: payload.collection_slug,
        collection_title: payload.collection_title,
        category: payload.category ?? undefined,
        difficulty_level: payload.difficulty_level ?? undefined,
        estimated_reading_time_minutes: payload.estimated_reading_time_minutes ?? undefined,
        items_total: payload.items_total,
        items_completed: payload.items_completed,
        has_certificate: payload.has_certificate,
        ...(payload.extra ?? {}),
      });
    }
    const sentry = getSentry();
    if (sentry) {
      sentry.addBreadcrumb({
        category: "collections",
        type: "info",
        level: "info",
        message: event,
        data: payload,
      });
    }
    if (import.meta.env.DEV) {
      // eslint-disable-next-line no-console
      console.debug("[collections/analytics]", event, payload);
    }
  } catch {
    // Analytics jamais quebra a UI
  }
}

/**
 * searchCollections — busca simples em `collections` (published) por título,
 * subtítulo, descrição e track. Usada pela busca do Acervo para incluir
 * trilhas de formação junto aos trechos patrísticos.
 *
 * Sem RPC dedicada: `.ilike` cobre bem o volume atual de coleções curadas
 * (dezenas). Se ultrapassar centenas, migrar para FTS `tsvector`.
 */
import { supabase } from "@/lib/db";
import type { Collection } from "./types";

export interface CollectionSearchHit {
  slug: string;
  title: string;
  subtitle: string | null;
  description: string | null;
  cover: string | null;
  estimated_reading_time_minutes: number | null;
  difficulty_level: string | null;
  track: string | null;
  certificate_eligible: boolean | null;
  items_count: number | null;
}

export async function searchCollections(query: string, limit = 6): Promise<CollectionSearchHit[]> {
  const q = query.trim();
  if (q.length < 2) return [];
  const pattern = `%${q.replace(/[%_]/g, (m) => `\\${m}`)}%`;

  const { data, error } = await supabase
    .from("collections")
    .select(
      "slug,title,subtitle,description,cover,estimated_reading_time_minutes,difficulty_level,track,certificate_eligible",
    )
    .eq("status", "published")
    .or(
      `title.ilike.${pattern},subtitle.ilike.${pattern},description.ilike.${pattern},track.ilike.${pattern}`,
    )
    .limit(limit);

  if (error) {
    // eslint-disable-next-line no-console
    console.warn("[searchCollections]", error.message);
    return [];
  }

  return ((data ?? []) as Partial<Collection>[]).map((c) => ({
    slug: c.slug as string,
    title: c.title as string,
    subtitle: c.subtitle ?? null,
    description: c.description ?? null,
    cover: c.cover ?? null,
    estimated_reading_time_minutes: c.estimated_reading_time_minutes ?? null,
    difficulty_level: (c.difficulty_level as string | null) ?? null,
    track: (c.track as string | null) ?? null,
    certificate_eligible: c.certificate_eligible ?? null,
    items_count: null,
  }));
}

/**
 * Sprint UX · Área do Usuário — contadores unificados.
 *
 * Um único hook para alimentar os badges da sidebar da conta.
 * Sem alteração de schema: apenas count queries nas tabelas existentes.
 */
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";

export interface AccountCounters {
  notes: number;
  favorites: number;
  journalEntries: number;
  journeys: number;
  collections: number;
  prayerSessions: number;
  readingsMarks: number;
}

const EMPTY: AccountCounters = {
  notes: 0,
  favorites: 0,
  journalEntries: 0,
  journeys: 0,
  collections: 0,
  prayerSessions: 0,
  readingsMarks: 0,
};

export function useAccountCounters() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["account-counters", user?.id],
    enabled: !!user?.id,
    staleTime: 60_000,
    queryFn: async (): Promise<AccountCounters> => {
      if (!user?.id) return EMPTY;
      const uid = user.id;
      const head = { count: "exact" as const, head: true };

      // Cada count é independente; falhas silenciosas viram 0 (não bloqueiam a UI).
      const safe = async (p: PromiseLike<{ count: number | null }>) => {
        try {
          const r = await p;
          return r.count ?? 0;
        } catch {
          return 0;
        }
      };

      const [notes, favorites, journal, journeys, collections, prayers, readings] =
        await Promise.all([
          safe(supabase.from("user_notes").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("bible_favorites").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("spiritual_journal").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("journey_progress").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("collection_progress").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("prayer_sessions").select("id", head).eq("user_id", uid) as any),
          safe(supabase.from("reading_marks").select("id", head).eq("user_id", uid) as any),
        ]);

      return {
        notes,
        favorites,
        journalEntries: journal,
        journeys,
        collections,
        prayerSessions: prayers,
        readingsMarks: readings,
      };
    },
  });
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";

export interface AdminStats {
  totalUsers: number;
  premiumUsers: number;
  totalVisits: number;
  totalDownloads: number;
  totalRevenue: number;
  pendingRevenue: number;
  pwaInstalls: number;
  pwaOpens: number;
  activeToday: number;
  activeLast30Days: number;
  inactiveUsers: number;
  journeysInProgress: number;
  totalReflections: number;
  totalJourneysStarted: number;
  totalJourneysCompleted: number;
  returnRate: number;
  recentTransactions: any[];
  userGrowth: { name: string; total: number }[];
  revenueData: { name: string; amount: number }[];
  diocesesStats: { name: string; count: number }[];
  statesStats: { name: string; count: number }[];
  movementsStats: { name: string; count: number }[];
  users: AdminUser[];
}

export interface AdminUser {
  id: string;
  name: string;
  email: string;
  role: string | null;
  is_premium: boolean;
  created_at: string;
  xp: number | null;
  level: number | null;
  streak: number | null;
  last_visit: string | null;
  reflections_count?: number;
  depth_level?: string;
  current_journey?: string;
  access_frequency?: string;
}

export const useAdminDashboardData = (page = 0, pageSize = 20) => {
  return useQuery({
    queryKey: ["admin-dashboard-stats", page, pageSize],
    queryFn: async (): Promise<AdminStats> => {
      const thirtyDaysAgoStart = new Date();
      thirtyDaysAgoStart.setDate(new Date().getDate() - 30);
      const iso30 = thirtyDaysAgoStart.toISOString();

      const from = page * pageSize;
      const to = from + pageSize - 1;

      // Executamos queries em paralelo, mas limitamos a listagem de usuários
      const [
        statsRes,
        profilesRes,
        metricsRes,
        transactionsRes,
        journalRes,
        journeysStartedRes,
        journeysCompletedRes,
        crmRes,
      ] = await Promise.all([
        supabase.from("profiles").select("*", { count: "exact", head: true }),
        supabase
          .from("profiles")
          .select(
            "id, is_premium, created_at, last_visit, diocese, estado, movimento_pastoral, name, role, xp, level, streak",
          )
          .range(from, to),
        supabase
          .from("app_metrics")
          .select("metric_type, created_at")
          .gte("created_at", iso30)
          .limit(5000), // Cap para evitar estouro
        supabase
          .from("transactions")
          .select("amount, status, created_at, profiles(name)")
          .order("created_at", { ascending: false })
          .limit(100),
        supabase.from("spiritual_journal").select("user_id", { count: "exact", head: true }),
        supabase.from("journey_progress").select("user_id", { count: "exact", head: true }),
        supabase
          .from("journey_progress")
          .select("user_id", { count: "exact", head: true })
          .not("completed_at", "is", null),
        supabase
          .from("user_management_stats")
          .select("id, email, classification, reflections_count, current_journey, last_activity")
          .range(from, to),
      ]);

      if (profilesRes.error) throw profilesRes.error;
      if (metricsRes.error) throw metricsRes.error;
      if (transactionsRes.error) throw transactionsRes.error;

      const profiles = profilesRes.data || [];
      const metrics = metricsRes.data || [];
      const transactions = transactionsRes.data || [];
      const totalCount = statsRes.count || 0;

      // Stats globais baseadas nos profiles (Idealmente isso viria de uma view ou RPC consolidado se o volume for MUITO alto)
      // Por enquanto, as métricas de crescimento e geolocalização serão baseadas na amostragem ou queries específicas se necessário.
      // Para manter a performance abaixo de 800ms, evitamos processar 100% dos dados no client.

      const premiumCount = profiles.filter((p) => p.is_premium).length; // Amostragem (ou query de count específica)
      const visitsCount = metrics.filter((m) => m.metric_type === "visit").length;
      const downloadsCount = metrics.filter((m) => m.metric_type === "download").length;
      const pwaInstalls = metrics.filter((m) => m.metric_type === "pwa_install").length;
      const pwaOpens = metrics.filter((m) => m.metric_type === "pwa_open").length;
      const totalRevenue = transactions
        .filter((t) => t.status === "approved")
        .reduce((acc, curr) => acc + Number(curr.amount), 0);
      const pendingRevenue = transactions
        .filter((t) => t.status === "pending")
        .reduce((acc, curr) => acc + Number(curr.amount), 0);

      const now = new Date();
      const activeToday = profiles.filter((p) => {
        if (!p.last_visit) return false;
        const visitDate = new Date(p.last_visit);
        return visitDate.toDateString() === now.toDateString();
      }).length;

      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(now.getDate() - 30);
      const activeLast30Days = profiles.filter((p) => {
        if (!p.last_visit) return false;
        const visitDate = new Date(p.last_visit);
        return visitDate >= thirtyDaysAgo;
      }).length;

      const inactiveUsers = profiles.filter((p) => {
        if (!p.last_visit) return true;
        const diff = (now.getTime() - new Date(p.last_visit).getTime()) / (1000 * 60 * 60);
        return diff >= 48;
      }).length;

      const returnRate = totalCount > 0 ? ((totalCount - inactiveUsers) / totalCount) * 100 : 0;

      const months = [
        "Jan",
        "Fev",
        "Mar",
        "Abr",
        "Mai",
        "Jun",
        "Jul",
        "Ago",
        "Set",
        "Out",
        "Nov",
        "Dez",
      ];
      const currentYear = new Date().getFullYear();

      const userGrowth = months
        .map((month, index) => {
          const count = profiles.filter((p) => {
            const date = new Date(p.created_at);
            return date.getMonth() <= index && date.getFullYear() <= currentYear;
          }).length;
          return { name: month, total: count };
        })
        .slice(0, new Date().getMonth() + 1);

      const revenueData = [3, 2, 1, 0].map((weeksAgo) => {
        const start = new Date(now);
        start.setDate(now.getDate() - (weeksAgo + 1) * 7);
        const end = new Date(now);
        end.setDate(now.getDate() - weeksAgo * 7);

        const amount = transactions
          .filter((t) => {
            const date = new Date(t.created_at);
            return t.status === "approved" && date >= start && date <= end;
          })
          .reduce((acc, curr) => acc + Number(curr.amount), 0);

        return { name: `Sem ${4 - weeksAgo}`, amount };
      });

      const dioceseMap = new Map<string, number>();
      const stateMap = new Map<string, number>();
      const movementMap = new Map<string, number>();

      profiles.forEach((p) => {
        if (p.diocese) dioceseMap.set(p.diocese, (dioceseMap.get(p.diocese) || 0) + 1);
        if (p.estado) stateMap.set(p.estado, (stateMap.get(p.estado) || 0) + 1);
        if (p.movimento_pastoral)
          movementMap.set(p.movimento_pastoral, (movementMap.get(p.movimento_pastoral) || 0) + 1);
      });

      return {
        totalUsers: totalCount,
        premiumUsers: premiumCount,
        totalVisits: visitsCount,
        totalDownloads: downloadsCount,
        pwaInstalls,
        pwaOpens,
        activeToday,
        activeLast30Days,
        inactiveUsers,
        journeysInProgress: journeysStartedRes.count || 0,
        totalReflections: journalRes.count || 0,
        totalJourneysStarted: journeysStartedRes.count || 0,
        totalJourneysCompleted: journeysCompletedRes.count || 0,
        returnRate,
        totalRevenue,
        pendingRevenue,
        recentTransactions: transactions.slice(0, 10),
        userGrowth,
        revenueData,
        diocesesStats: Array.from(dioceseMap.entries())
          .map(([name, count]) => ({ name, count }))
          .sort((a, b) => b.count - a.count),
        statesStats: Array.from(stateMap.entries())
          .map(([name, count]) => ({ name, count }))
          .sort((a, b) => b.count - a.count),
        movementsStats: Array.from(movementMap.entries())
          .map(([name, count]) => ({ name, count }))
          .sort((a, b) => b.count - a.count),
        users: profiles.map((p) => {
          const crm = ((crmRes.data || []) as any[]).find((u) => u.id === p.id) || {};
          return {
            ...p,
            email: crm.email || "",
            depth_level: crm.classification || "Novo",
            reflections_count: crm.reflections_count || 0,
            current_journey: crm.current_journey || "Nenhuma",
            last_visit: crm.last_activity || p.last_visit,
            name: (p as any).name || "Usuário",
          } as AdminUser;
        }),
      };
    },
    refetchInterval: 60000,
  });
};

import {
  createContext,
  createElement,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { supabase } from "@/lib/db";
import { checkNewBadges, getBadgeById, type BadgeContext } from "@/lib/badges";
import confetti from "canvas-confetti";
import { toast } from "sonner";
import type { User as SupabaseUser } from "@supabase/supabase-js";
import { setSentryUser } from "@/lib/sentry";

export type UserLevelClass = "iniciante" | "intermediário" | "avançado";

export interface SensitiveData {
  email: string;
  diagnosis_result: Record<string, string> | null;
}

export interface Profile {
  id: string;
  name: string;
  bio?: string;
  is_premium: boolean;
  role: "user" | "admin" | string | null;
  premium_status?: string | null;
  premium_expires_at?: string | null;
  mercado_pago_subscription_id?: string | null;
  avatar_url: string | null;
  xp?: number;
  streak?: number;
  max_streak?: number;
  level?: number;
  last_visit?: string;
  completed_books?: string[];
  badges?: string[];
  total_minutes_read?: number;
  estado?: string;
  diocese?: string;
  paroquia?: string;
  movimento_pastoral?: string;
  reading_settings?: Record<string, any>;
  journey_reminder_time?: string;
  weekly_goal?: number;
  spiritual_themes?: string[];
  contemplative_preferences?: Record<string, any>;
  notification_settings?: Record<string, any>;
  _sensitive?: SensitiveData;
}

interface AuthContextValue {
  user: SupabaseUser | null;
  profile: Profile | null;
  loading: boolean;
  signOut: () => Promise<void>;
  isPremium: boolean;
  userLevel: UserLevelClass;
  refreshProfile: () => Promise<void>;
  authenticated: boolean;
}

export const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<SupabaseUser | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const authRequestId = useRef(0);

  const fetchProfile = useCallback(async (currentUser: SupabaseUser) => {
    const [profileResult, sensitiveResult, premiumResult] = await Promise.all([
      supabase.from("profiles").select("*").eq("id", currentUser.id).maybeSingle(),
      (supabase as any)
        .from("user_sensitive_data")
        .select("email, diagnosis_result")
        .eq("user_id", currentUser.id)
        .maybeSingle(),
      supabase
        .from("transactions")
        .select("id", { count: "exact", head: true })
        .eq("user_id", currentUser.id)
        .eq("status", "approved"),
    ]);

    if (profileResult.error) {
      console.error("Erro ao buscar perfil:", profileResult.error);
      return null;
    }

    if (premiumResult.error) {
      console.error("Erro ao verificar acesso premium:", premiumResult.error);
    }

    if (!profileResult.data) {
      return null;
    }

    return {
      ...profileResult.data,
      is_premium: Boolean(profileResult.data.is_premium || (premiumResult.count ?? 0) > 0),
      _sensitive: sensitiveResult.data as SensitiveData | undefined,
    } as Profile & { _sensitive?: { email: string; diagnosis_result: any } };
  }, []);

  const updateStreak = useCallback(async (currentUser: SupabaseUser, currentProfile: Profile) => {
    try {
      const now = new Date();
      const todayStr = now.toISOString().split("T")[0];
      const lastVisit = currentProfile.last_visit ? new Date(currentProfile.last_visit) : null;
      const lastVisitStr = lastVisit ? lastVisit.toISOString().split("T")[0] : null;

      // Already visited today
      if (lastVisitStr === todayStr) {
        // Still check badges even if already visited today
        await checkAndAwardBadges(currentUser, currentProfile, currentProfile.streak || 0);
        return;
      }

      const yesterday = new Date(now);
      yesterday.setDate(yesterday.getDate() - 1);
      const yesterdayStr = yesterday.toISOString().split("T")[0];

      let newStreak = 1;
      if (lastVisitStr === yesterdayStr) {
        newStreak = (currentProfile.streak || 0) + 1;
      }

      await supabase
        .from("profiles")
        .update({ streak: newStreak, last_visit: now.toISOString() })
        .eq("id", currentUser.id);

      // Check badges after streak update
      await checkAndAwardBadges(currentUser, currentProfile, newStreak);
    } catch (err) {
      console.error("Erro ao atualizar ofensiva (streak):", err);
    }
  }, []);

  const checkAndAwardBadges = useCallback(
    async (currentUser: SupabaseUser, currentProfile: Profile, streak: number) => {
      try {
        // 1. Fetch all necessary stats for badge conditions
        const [journeyRes, postsRes, likesRes, notesRes] = await Promise.all([
          supabase
            .from("journey_progress")
            .select("journey_id", { count: "exact", head: true })
            .eq("user_id", currentUser.id),
          supabase
            .from("community_posts")
            .select("id", { count: "exact", head: true })
            .eq("user_id", currentUser.id),
          supabase
            .from("community_likes")
            .select("id", { count: "exact", head: true })
            .eq("user_id", currentUser.id),
          supabase
            .from("user_notes")
            .select("id", { count: "exact", head: true })
            .eq("user_id", currentUser.id),
        ]);

        const currentBadges = currentProfile.badges || [];
        const ctx: BadgeContext = {
          completedBooks: new Set(currentProfile.completed_books || []),
          chaptersRead: {},
          totalMinutesRead: currentProfile.total_minutes_read || 0,
          streak,
          completedJourneys: journeyRes.count || 0,
          posts: postsRes.count || 0,
          likes: likesRes.count || 0,
          notes: notesRes.count || 0,
        } as any;

        const newBadgeIds = checkNewBadges(currentBadges, ctx);
        if (newBadgeIds.length > 0) {
          const updatedBadges = [...currentBadges, ...newBadgeIds];
          await supabase
            .from("profiles")
            .update({ badges: updatedBadges })
            .eq("id", currentUser.id);

          // Celebrate!
          confetti({
            particleCount: 120,
            spread: 80,
            origin: { y: 0.6 },
            colors: ["#FFD700", "#FF6B35", "#4ECDC4", "#8B5CF6"],
          });
          for (const id of newBadgeIds) {
            const badge = getBadgeById(id);
            if (badge) {
              toast.success(`${badge.icon} ${badge.name}`, {
                description: badge.description,
                duration: 5000,
              });
            }
          }
        }
      } catch (err) {
        console.error("Erro ao verificar medalhas:", err);
      }
    },
    [],
  );

  const syncAuthState = useCallback(
    async (currentUser: SupabaseUser | null) => {
      const requestId = ++authRequestId.current;

      // If user is same as current state, skip (unless initial/loading)
      if (user?.id === currentUser?.id && !loading && requestId > 1) {
        return;
      }

      setUser(currentUser);
      setSentryUser(currentUser ? { id: currentUser.id, email: currentUser.email } : null);
      setLoading(true);

      if (!currentUser) {
        setProfile(null);
        setLoading(false);
        return;
      }

      try {
        const resolvedProfile = await fetchProfile(currentUser);

        if (requestId !== authRequestId.current) return;

        setProfile(resolvedProfile);

        if (resolvedProfile) {
          void updateStreak(currentUser, resolvedProfile);
        }
      } catch (error) {
        if (requestId !== authRequestId.current) return;
        console.error("Erro na sincronização de sessão:", error);
        setProfile(null);
      } finally {
        if (requestId === authRequestId.current) {
          setLoading(false);
        }
      }
    },
    [fetchProfile, updateStreak, user?.id, loading],
  );

  useEffect(() => {
    let active = true;

    // Safety timeout: never stay in loading state for more than 8 seconds
    const safetyTimeout = setTimeout(() => {
      if (active && loading) {
        console.warn(
          "Tempo limite de carregamento de autenticação atingido. Forçando estado de carregamento como falso.",
        );
        setLoading(false);
      }
    }, 8000);

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (!active || event === "INITIAL_SESSION" || event === "TOKEN_REFRESHED") return;
      void syncAuthState(session?.user ?? null);
    });

    const initSession = async (retryCount = 0) => {
      try {
        const {
          data: { session },
          error,
        } = await supabase.auth.getSession();
        if (!active) return;

        if (error) {
          if (error.name === "AbortError" && retryCount < 3) {
            console.warn(
              "Inicialização de sessão abortada (bloqueio roubado), tentando novamente...",
            );
            setTimeout(() => initSession(retryCount + 1), 500);
            return;
          }
          console.error("Erro ao obter sessão:", error);
        }

        await syncAuthState(session?.user ?? null);
      } catch (error: any) {
        if (!active) return;

        if (error?.name === "AbortError" && retryCount < 3) {
          console.warn(
            "Inicialização de sessão abortada (bloqueio roubado), tentando novamente...",
          );
          setTimeout(() => initSession(retryCount + 1), 500);
          return;
        }

        if (error?.name !== "AbortError") {
          console.error("Erro de inicialização de sessão:", error);
        }

        setUser(null);
        setProfile(null);
        setLoading(false);
      }
    };

    void initSession();

    return () => {
      active = false;
      clearTimeout(safetyTimeout);
      authRequestId.current += 1;
      subscription.unsubscribe();
    };
  }, [syncAuthState]);

  const refreshProfile = useCallback(async () => {
    if (!user) return;
    const resolvedProfile = await fetchProfile(user);
    if (resolvedProfile) setProfile(resolvedProfile);
  }, [user, fetchProfile]);

  // Realtime: sincroniza perfil entre dispositivos
  useEffect(() => {
    if (!user) return;
    const channel = supabase
      .channel(`profile-sync-${user.id}`)
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "profiles", filter: `id=eq.${user.id}` },
        () => {
          refreshProfile();
        },
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, refreshProfile]);

  const signOut = useCallback(async () => {
    authRequestId.current += 1;
    await supabase.auth.signOut();
    setUser(null);
    setProfile(null);
    setLoading(false);
  }, []);

  const userLevel = useMemo<UserLevelClass>(() => {
    if (!profile) return "iniciante";

    // Check diagnosis from sensitive data
    const diagnosis = profile._sensitive?.diagnosis_result as any;
    if (diagnosis) {
      const knowledge = diagnosis.knowledge;
      if (knowledge === "basic") return "iniciante";
      if (knowledge === "moderate") return "intermediário";
      if (knowledge === "advanced" || knowledge === "theological") return "avançado";
    }

    // Fallback to integer level
    const levelNum = profile.level || 1;
    if (levelNum >= 10) return "avançado";
    if (levelNum >= 4) return "intermediário";
    return "iniciante";
  }, [profile]);

  const value = useMemo<AuthContextValue>(
    () => ({
      user,
      profile,
      loading,
      signOut,
      isPremium: profile?.is_premium ?? false,
      userLevel,
      refreshProfile,
      authenticated: !!user,
    }),
    [user, profile, loading, signOut, userLevel, refreshProfile],
  );

  return createElement(AuthContext.Provider, { value }, children);
}

export function useAuth() {
  const context = useContext(AuthContext);

  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }

  return context;
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { getCachedCatechismParagraph, cacheCatechismParagraph } from "@/lib/offlineCache";
import { DeepContent } from "@/types";
import { CATECHISM_LOCAL_DATA } from "@/data/catechism";
import { logCatechismDiag, classifyCatechismError } from "@/lib/catechismDiagnostics";

export interface CatechismParagraph extends Partial<DeepContent> {
  paragraph: number;
  content: string;
  language: string;
  status?: string;
  explicacao?: string;
  interpretacaoProfunda?: string;
  aplicacaoPratica?: string;
  reflexaoFinal?: string;
  exercicio?: string;
}

export class CatechismFetchError extends Error {
  code: "unauthorized" | "forbidden" | "not_found" | "network" | "unknown";
  status?: number;
  paragraph: number;
  constructor(
    paragraph: number,
    code: CatechismFetchError["code"],
    message: string,
    status?: number,
  ) {
    super(message);
    this.name = "CatechismFetchError";
    this.code = code;
    this.status = status;
    this.paragraph = paragraph;
  }
}

export const fetchCatechismParagraph = async (
  paragraph: number,
  forceGenerate = false,
): Promise<CatechismParagraph> => {
  const isOfflineMode = localStorage.getItem("cathedra_offline_mode") === "true";

  // 1) IndexedDB cache
  const cached = await getCachedCatechismParagraph(paragraph);
  if (cached && !forceGenerate) {
    logCatechismDiag({ paragraph, step: "cache_hit" });
    return cached;
  }

  // 2) Direct table read (now allowed by RLS public read policy)
  try {
    logCatechismDiag({ paragraph, step: "official_query" });
    // Use .limit(1) + array destructuring instead of .maybeSingle()
    // to avoid spurious 406 responses from PostgREST when 0 rows match.
    const { data: officialRows, error: officialError } = await supabase
      .from("catechism_official")
      .select("*")
      .eq("paragraph", paragraph)
      .limit(1);
    const officialData =
      Array.isArray(officialRows) && officialRows.length > 0 ? officialRows[0] : null;

    if (officialError) {
      const classified = classifyCatechismError(officialError);
      logCatechismDiag({
        paragraph,
        step:
          classified.code === "unauthorized"
            ? "unauthorized"
            : classified.code === "forbidden"
              ? "forbidden"
              : "official_error",
        status: classified.status,
        message: officialError.message,
        meta: { hint: (officialError as any)?.hint, details: (officialError as any)?.details },
      });
    } else if (officialData) {
      const result: CatechismParagraph = {
        paragraph: officialData.paragraph,
        content: officialData.content,
        language: "pt",
        status: "official",
        textoBase: officialData.texto_base,
        explicacao: officialData.explicacao,
        interpretacaoProfunda: officialData.interpretacao_profunda,
        aplicacaoPratica: officialData.aplicacao_pratica,
        reflexaoFinal: officialData.reflexao_final,
        exercicio: officialData.exercicio,
      };
      logCatechismDiag({ paragraph, step: "official_hit", meta: { source: "catechism_official" } });
      cacheCatechismParagraph(paragraph, result);
      return result;
    }
  } catch (e: any) {
    const classified = classifyCatechismError(e);
    logCatechismDiag({
      paragraph,
      step: "official_error",
      status: classified.status,
      message: e?.message,
    });
  }

  // 3) Local static data
  const localData = (CATECHISM_LOCAL_DATA as any)[paragraph];
  if (localData && !forceGenerate) {
    const result: CatechismParagraph = {
      paragraph: localData.paragraph,
      content: localData.conteudo,
      language: "pt",
      status: "static",
      textoBase: localData.textoBase,
    };
    logCatechismDiag({ paragraph, step: "local_hit" });
    cacheCatechismParagraph(paragraph, result);
    return result;
  }

  // 4) Offline mode hard stop
  if (isOfflineMode && !forceGenerate) {
    if (cached) return cached;
    const err = new CatechismFetchError(
      paragraph,
      "network",
      "Modo Somente-Cache ativo: Texto não disponível offline.",
    );
    logCatechismDiag({ paragraph, step: "final_error", message: err.message });
    throw err;
  }

  // 5) Edge function (service-role backed)
  try {
    logCatechismDiag({ paragraph, step: "edge_invoke" });
    const { data, error } = await supabase.functions.invoke("catechism-text", {
      body: { paragraph, action: "fetch" },
    });

    if (error) {
      const classified = classifyCatechismError(error);
      logCatechismDiag({
        paragraph,
        step:
          classified.code === "unauthorized"
            ? "unauthorized"
            : classified.code === "forbidden"
              ? "forbidden"
              : "edge_error",
        status: classified.status,
        message: error.message,
      });
      if (cached) return cached;
      throw new CatechismFetchError(
        paragraph,
        classified.code,
        classified.message,
        classified.status,
      );
    }

    const parsed = typeof data === "string" ? JSON.parse(data) : data;

    if (!parsed || parsed.status === "not_found" || parsed.status === "not_cached") {
      logCatechismDiag({ paragraph, step: "edge_not_found", status: parsed?.status });
      throw new CatechismFetchError(
        paragraph,
        "not_found",
        `Parágrafo §${paragraph} não disponível no banco oficial.`,
        404,
      );
    }

    // Enfileirado sob demanda — devolver marcador para o hook fazer polling
    if (parsed.status === "queued" || parsed.code === "queued_for_import") {
      logCatechismDiag({ paragraph, step: "edge_hit", meta: { source: "queued" } });
      return {
        paragraph,
        content: parsed.message || `Parágrafo §${paragraph} está sendo importado.`,
        language: "pt",
        status: "queued",
      };
    }

    const result: CatechismParagraph = {
      paragraph: parsed.paragraph || paragraph,
      content: parsed.content || `Parágrafo §${paragraph} — conteúdo não disponível.`,
      language: parsed.language || "pt",
      status: parsed.status,
      textoBase: parsed.textoBase,
      explicacao: parsed.explicacao,
      interpretacaoProfunda: parsed.interpretacaoProfunda,
      aplicacaoPratica: parsed.aplicacaoPratica,
      reflexaoFinal: parsed.reflexaoFinal,
      exercicio: parsed.exercicio,
    };

    logCatechismDiag({ paragraph, step: "edge_hit", meta: { source: parsed.status } });
    cacheCatechismParagraph(paragraph, result);
    return result;
  } catch (error: any) {
    if (error instanceof CatechismFetchError) throw error;
    window.dispatchEvent(new CustomEvent("supabase-unreachable"));
    if (cached) {
      logCatechismDiag({ paragraph, step: "fallback_cached", message: error?.message });
      return cached;
    }
    const classified = classifyCatechismError(error);
    logCatechismDiag({
      paragraph,
      step: "final_error",
      status: classified.status,
      message: error?.message,
    });
    throw new CatechismFetchError(
      paragraph,
      classified.code,
      classified.message,
      classified.status,
    );
  }
};

export const isCatechismParagraphImporting = (data?: CatechismParagraph | null) =>
  data?.status === "queued";

export const useCatechismParagraph = (paragraph: number, enabled = true) => {
  return useQuery({
    queryKey: ["catechism-paragraph", paragraph],
    queryFn: () => fetchCatechismParagraph(paragraph),
    staleTime: 1000 * 60 * 60 * 24,
    gcTime: 1000 * 60 * 60 * 24 * 7,
    retry: (failureCount, err: any) => {
      // No reintenta erros semânticos (not_found / 401 / 403)
      if (
        err instanceof CatechismFetchError &&
        ["not_found", "unauthorized", "forbidden"].includes(err.code)
      ) {
        return false;
      }
      return failureCount < 1;
    },
    retryDelay: 2000,
    // Enquanto o § estiver enfileirado, refazer consulta a cada 4s até o worker concluir.
    refetchInterval: (query) =>
      isCatechismParagraphImporting(query.state.data as CatechismParagraph | undefined)
        ? 4000
        : false,
    refetchIntervalInBackground: false,
    enabled,
  });
};

export const useGenerateCatechismParagraph = () => {
  const queryClient = useQueryClient();
  return async (paragraph: number) => {
    const result = await fetchCatechismParagraph(paragraph, true);
    queryClient.setQueryData(["catechism-paragraph", paragraph], result);
    return result;
  };
};

export const usePrefetchCatechismParagraph = () => {
  const queryClient = useQueryClient();
  const prefetch = (paragraph: number) => {
    if (paragraph < 1 || paragraph > 2865) return;
    queryClient.prefetchQuery({
      queryKey: ["catechism-paragraph", paragraph],
      queryFn: () => fetchCatechismParagraph(paragraph),
      staleTime: 1000 * 60 * 60 * 24,
    });
  };
  return prefetch;
};

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useMemo, useState } from "react";
import { useDailyLiturgy } from "@/hooks/useDailyLiturgy";
import { useSaintOfDay, type SaintOfDay } from "@/hooks/useSaintOfDay";
import {
  toIsoDateKey,
  type DailyLiturgy,
  type Reading,
  type Psalm,
} from "@/core/liturgy/LiturgyProvider";
import {
  resolveLiturgicalDay,
  msUntilNextMidnight,
  type LiturgicalDay,
  type CelebrationRank,
  type LiturgicalSeason,
  type YearCycle,
  type WeekCycle,
} from "@/core/church/liturgicalCalendar";
import { getSaintsByDate } from "@/services/saintsService";
import { supabase } from "@/lib/db";

/**
 * Church Context Engine — Contexto Eclesial Global (SSoT · KERNEL).
 *
 * Camada única e congelada. Toda a plataforma (Home, Biblioteca, Logos, Nexus,
 * Reader, Liturgia, Missal, Orações, Perfil, Widgets) consome exclusivamente
 * `useChurchContext()`. Nenhum módulo deve consultar Papa, Santo, Calendário,
 * Tempo Litúrgico ou Leituras de forma independente.
 *
 * Atualização automática à meia-noite local (timezone do dispositivo).
 */

export interface PopeContext {
  id: string;
  name: string;
  title: string;
  image: string;
  reign: string;
  isSaint: boolean;
  status: "current" | "historical";
  /** Intenção mensal do Papa, quando disponível. */
  intention: string | null;
}

export interface SaintsContext {
  /** Santo principal do dia. */
  principal: SaintOfDay | null;
  /** Santos secundários celebrados na mesma data. */
  secondary: SaintOfDay[];
  /** Bem-aventurados do dia. */
  blessed: SaintOfDay[];
  /** Mártires do dia. */
  martyrs: SaintOfDay[];
}

export interface ReadingsContext {
  first: Reading | null;
  psalm: Psalm | null;
  second: Reading | null;
  gospel: Reading | null;
  entranceAntiphon: string | null;
  communionAntiphon: string | null;
}

export interface ChurchSeasonFlags {
  isAdvent: boolean;
  isChristmas: boolean;
  isLent: boolean;
  isHolyWeek: boolean;
  isEaster: boolean;
  isPentecost: boolean;
  isCorpusChristi: boolean;
  isAssumption: boolean;
  isAllSaints: boolean;
  isOrdinaryTime: boolean;
}

export interface ChurchContext {
  // ── Igreja ──────────────────────────────────────────────
  currentPope: PopeContext | null;
  /** Ano Santo / Jubileu em curso, quando aplicável. */
  jubilee: { active: boolean; name: string | null; year: number | null };

  // ── Santos ──────────────────────────────────────────────
  saints: SaintsContext;
  /** Atalho para o santo principal (compatibilidade). */
  todaySaint: SaintOfDay | null;

  // ── Calendário ──────────────────────────────────────────
  calendar: LiturgicalDay;
  liturgicalSeason: LiturgicalSeason;
  liturgicalWeek: number;
  liturgicalYear: number;
  yearCycle: YearCycle;
  weekCycle: WeekCycle;
  liturgicalColor: string;
  rank: CelebrationRank;
  celebration: string | null;
  seasonFlags: ChurchSeasonFlags;

  // ── Liturgia ────────────────────────────────────────────
  liturgy: DailyLiturgy | null;
  readings: ReadingsContext;
  gospel: Reading | null;
  psalm: Psalm | null;

  // ── Meta ────────────────────────────────────────────────
  isoDate: string;
  isToday: boolean;
  isLoading: boolean;
  /** Incrementa a cada virada de meia-noite — força consumidores a re-renderizar. */
  dayTick: number;
}

// Fallback do Papa caso a base falhe
export const FALLBACK_POPE: PopeContext = {
  id: "leo-xiv",
  name: "Leão XIV",
  title: "Bispo de Roma, Vigário de Jesus Cristo",
  image: "",
  reign: "2025 – Presente",
  isSaint: false,
  status: "current",
  intention: null,
};

const JUBILEE_YEARS: Record<number, string> = {
  2025: "Jubileu Ordinário de 2025 — Peregrinos da Esperança",
};

function mapSaint(s: any): SaintOfDay {
  return {
    name: s.name,
    title: s.title ?? null,
    slug: s.slug ?? null,
    image: s.image ?? null,
    source: "santoral",
  };
}

/**
 * Sincroniza o kernel com a virada do dia (meia-noite local).
 * Reagenda a cada virada e também ao voltar do background / mudar de aba.
 */
function useMidnightTick(): number {
  const [tick, setTick] = useState(0);
  const [dayKey, setDayKey] = useState(() => toIsoDateKey(new Date()));
  const queryClient = useQueryClient();

  useEffect(() => {
    let timer: number | undefined;

    const fire = () => {
      const nowKey = toIsoDateKey(new Date());
      if (nowKey !== dayKey) {
        setDayKey(nowKey);
        setTick((t) => t + 1);
        // Refresh consistente de todo o contexto eclesial
        queryClient.invalidateQueries({ queryKey: ["church-pope"] });
        queryClient.invalidateQueries({ queryKey: ["saint-of-day"] });
        queryClient.invalidateQueries({ queryKey: ["church-saints"] });
        queryClient.invalidateQueries({ queryKey: ["daily-liturgy"] });
        queryClient.invalidateQueries({ queryKey: ["liturgy"] });
      }
      schedule();
    };

    const schedule = () => {
      if (timer) window.clearTimeout(timer);
      timer = window.setTimeout(fire, msUntilNextMidnight());
    };

    schedule();

    // Dispositivo suspenso / aba em background pode atrasar o timeout
    const onVisible = () => {
      if (document.visibilityState === "visible") fire();
    };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("focus", onVisible);

    return () => {
      if (timer) window.clearTimeout(timer);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("focus", onVisible);
    };
  }, [dayKey, queryClient]);

  return tick;
}

export function useChurchContext(date?: Date): ChurchContext {
  const dayTick = useMidnightTick();

  // Quando nenhuma data é informada, o kernel segue "hoje" e reavalia na virada.
  const effectiveDate = useMemo(() => date ?? new Date(), [date, dayTick]);

  const isoDate = toIsoDateKey(effectiveDate);
  const isToday = isoDate === toIsoDateKey(new Date());

  const calendar = useMemo(() => resolveLiturgicalDay(effectiveDate), [isoDate]);

  // ── 1. Papa Atual (P0) ────────────────────────────────
  const { data: currentPope, isLoading: loadingPope } = useQuery({
    queryKey: ["church-pope", "current"],
    queryFn: async (): Promise<PopeContext> => {
      const { data, error } = await supabase
        .from("library_items_v1")
        .select("*")
        .eq("status", "current")
        .limit(1)
        .maybeSingle();

      if (data && !error && data.title) {
        return {
          id: data.id || "current-pope",
          name: data.title,
          title: data.author_label || "Bispo de Roma",
          image: data.cover_image_url || FALLBACK_POPE.image,
          reign: data.published_at || FALLBACK_POPE.reign,
          isSaint: data.category === "saint",
          status: "current",
          intention: null,
        };
      }

      return FALLBACK_POPE;
    },
    staleTime: 1000 * 60 * 60 * 12,
  });

  // ── 2. Santos do dia ──────────────────────────────────
  const { data: principalSaint, isLoading: loadingSaint } = useSaintOfDay(effectiveDate);

  const { data: saintsOfDate, isLoading: loadingSaints } = useQuery({
    queryKey: ["church-saints", isoDate],
    queryFn: async () => {
      const list = await getSaintsByDate(effectiveDate.getMonth() + 1, effectiveDate.getDate());
      return (list ?? []) as any[];
    },
    staleTime: 1000 * 60 * 60 * 6,
  });

  // ── 3. Liturgia do dia ────────────────────────────────
  const { liturgy, isLoading: loadingLiturgy } = useDailyLiturgy(effectiveDate);

  const saints = useMemo<SaintsContext>(() => {
    const all = (saintsOfDate ?? []).map(mapSaint);
    const principalName = principalSaint?.name?.toLowerCase();
    const rest = all.filter((s) => s.name?.toLowerCase() !== principalName);

    const isBlessed = (s: SaintOfDay) =>
      /^be(a|á)t[oa]\b|bem-aventurad/i.test(`${s.name} ${s.title ?? ""}`);
    const isMartyr = (s: SaintOfDay) => /m[áa]rtir/i.test(`${s.title ?? ""}`);

    return {
      principal: principalSaint ?? all[0] ?? null,
      secondary: rest,
      blessed: all.filter(isBlessed),
      martyrs: all.filter(isMartyr),
    };
  }, [saintsOfDate, principalSaint]);

  const readings = useMemo<ReadingsContext>(
    () => ({
      first: liturgy?.primeiraLeitura ?? null,
      psalm: liturgy?.salmo ?? null,
      second: liturgy?.segundaLeitura ?? null,
      gospel: liturgy?.evangelho ?? null,
      entranceAntiphon: (liturgy as any)?.antifonaEntrada ?? null,
      communionAntiphon: (liturgy as any)?.antifonaComunhao ?? null,
    }),
    [liturgy],
  );

  const seasonFlags = useMemo<ChurchSeasonFlags>(() => {
    const k = calendar.keyDates;
    const iso = (d: Date) => toIsoDateKey(d);
    return {
      isAdvent: calendar.season === "Advento",
      isChristmas: calendar.season === "Natal",
      isLent: calendar.season === "Quaresma",
      isHolyWeek: calendar.isHolyWeek,
      isEaster: calendar.season === "Tempo Pascal" || calendar.season === "Tríduo Pascal",
      isPentecost: isoDate === iso(k.pentecost),
      isCorpusChristi: isoDate === iso(k.corpusChristi),
      isAssumption: isoDate === iso(k.assumption),
      isAllSaints: isoDate === iso(k.allSaints),
      isOrdinaryTime: calendar.season === "Tempo Comum",
    };
  }, [calendar, isoDate]);

  const jubileeYear = effectiveDate.getFullYear();

  return useMemo<ChurchContext>(
    () => ({
      currentPope: currentPope ?? FALLBACK_POPE,
      jubilee: {
        active: Boolean(JUBILEE_YEARS[jubileeYear]),
        name: JUBILEE_YEARS[jubileeYear] ?? null,
        year: JUBILEE_YEARS[jubileeYear] ? jubileeYear : null,
      },

      saints,
      todaySaint: saints.principal,

      calendar,
      liturgicalSeason: calendar.season,
      liturgicalWeek: calendar.seasonWeek,
      liturgicalYear: calendar.liturgicalYear,
      yearCycle: calendar.yearCycle,
      weekCycle: calendar.weekCycle,
      liturgicalColor: liturgy?.colorToken ?? "liturgical-green",
      rank: calendar.rank,
      celebration: calendar.celebration ?? liturgy?.liturgia ?? null,
      seasonFlags,

      liturgy: liturgy ?? null,
      readings,
      gospel: readings.gospel,
      psalm: readings.psalm,

      isoDate,
      isToday,
      isLoading: loadingPope || loadingSaint || loadingSaints || loadingLiturgy,
      dayTick,
    }),
    [
      currentPope,
      jubileeYear,
      saints,
      calendar,
      liturgy,
      readings,
      seasonFlags,
      isoDate,
      isToday,
      loadingPope,
      loadingSaint,
      loadingSaints,
      loadingLiturgy,
      dayTick,
    ],
  );
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { getSaintsByDate } from "@/services/saintsService";
import { User } from "@/types";
import { ProfileId } from "@/components/cathedra/SpiritualQuiz";

export const useDashboardData = (user: User | null) => {
  const userId = user?.id;

  // Spiritual Profile
  const spiritualProfileQuery = useQuery({
    queryKey: ["spiritual-profile", userId],
    queryFn: async () => {
      if (!userId) return null;
      const { data } = await (supabase as any)
        .from("user_sensitive_data")
        .select("diagnosis_result")
        .eq("user_id", userId)
        .maybeSingle();

      const sp = data?.diagnosis_result?.spiritual_profile;
      if (sp) return sp as ProfileId;

      const spiritualProfileMap: Record<string, string> = {
        beginning: "sedento_de_sentido",
        deepening: "firme_aprofundando",
        struggling: "ferido_em_busca",
        serving: "ardente_missionario",
      };
      return (spiritualProfileMap[data?.diagnosis_result?.moment] || null) as ProfileId | null;
    },
    enabled: !!userId,
  });

  // Active Journeys
  const activeJourneysQuery = useQuery({
    queryKey: ["active-journeys", userId],
    queryFn: async () => {
      if (!userId) return [];
      const { data: progress } = await supabase
        .from("journey_progress")
        .select("journey_id, step_id")
        .eq("user_id", userId);
      if (!progress?.length) return [];

      const journeyIds = [...new Set(progress.map((p) => p.journey_id))];
      const { data: journeys } = await supabase
        .from("journeys")
        .select("id, title, icon")
        .in("id", journeyIds);
      if (!journeys) return [];

      const { data: steps } = await supabase
        .from("journey_steps")
        .select("id, journey_id")
        .in("journey_id", journeyIds);
      const stepsByJourney: Record<string, number> = {};
      steps?.forEach((s) => {
        stepsByJourney[s.journey_id] = (stepsByJourney[s.journey_id] || 0) + 1;
      });

      const completedByJourney: Record<string, number> = {};
      progress.forEach((p) => {
        completedByJourney[p.journey_id] = (completedByJourney[p.journey_id] || 0) + 1;
      });

      return journeys.map((j) => ({
        id: j.id,
        title: j.title,
        icon: j.icon,
        totalSteps: stepsByJourney[j.id] || 0,
        completedSteps: completedByJourney[j.id] || 0,
      }));
    },
    enabled: !!userId,
  });

  // Saints of the Day
  const saintsTodayQuery = useQuery({
    queryKey: ["saints-today"],
    queryFn: async () => {
      try {
        const { data, error } = await supabase.functions.invoke("saint-of-the-day");
        if (data && !error) {
          return [data];
        }
      } catch (e) {
        console.error("Error fetching saint of the day:", e);
      }

      const today = new Date();
      const matched = await getSaintsByDate(today.getMonth() + 1, today.getDate());
      return matched.length > 0 ? matched : [];
    },
    staleTime: 1000 * 60 * 60, // 1 hour cache
  });

  // Next Up (Enhanced for Continuity)
  const nextUpQuery = useQuery({
    queryKey: ["next-up", userId],
    queryFn: async () => {
      if (!userId) return null;

      const [
        lastBible,
        lastCatechism,
        lastJourney,
        lastReflection,
        lastJournal,
        history,
        lastRead,
      ] = await Promise.all([
        (supabase as any)
          .from("bible_chapters_read")
          .select("book_abbr, chapter")
          .eq("user_id", userId)
          .order("read_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from("catechism_paragraphs_read")
          .select("paragraph")
          .eq("user_id", userId)
          .order("read_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from("journey_progress")
          .select("journey_id, step_id")
          .eq("user_id", userId)
          .order("completed_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from("reading_reflections")
          .select("content, reading_type, created_at")
          .eq("user_id", userId)
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from("spiritual_journal")
          .select("content, mood, created_at")
          .eq("user_id", userId)
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        supabase
          .from("user_history")
          .select("*")
          .eq("user_id", userId)
          .order("visited_at", { ascending: false })
          .limit(5),
        supabase
          .from("reading_marks")
          .select("*")
          .eq("user_id", userId)
          .eq("is_last_read", true)
          .order("updated_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
      ]);

      const results: any = {
        history: history.data || [],
      };

      if (lastRead.data) {
        results.primaryResume = {
          type: lastRead.data.content_type,
          label: lastRead.data.label,
          route: lastRead.data.url,
          subtitle: "Retomar de onde parei",
        };
      }

      if (lastJourney.data) {
        const { data: steps } = await supabase
          .from("journey_steps")
          .select("id, title")
          .eq("journey_id", lastJourney.data.journey_id)
          .order("step_order", { ascending: true });
        const currentIndex = steps?.findIndex((s) => s.id === lastJourney.data.step_id) ?? -1;
        if (steps && currentIndex !== -1 && currentIndex < steps.length - 1) {
          const next = steps[currentIndex + 1];
          results.nextJourney = {
            type: "journey",
            label: next.title,
            route: `/jornadas/${lastJourney.data.journey_id}/step?step=${next.id}`,
            subtitle: "Próxima Etapa da Jornada",
          };
        }
      }

      if (lastBible.data) {
        results.nextBible = {
          type: "bible",
          label: `${lastBible.data.book_abbr} ${lastBible.data.chapter + 1}`,
          route: `/bible?book=${lastBible.data.book_abbr}&ch=${lastBible.data.chapter + 1}`,
          subtitle: "Continuar Leitura da Bíblia",
          lastBible: lastBible.data,
        };
      }

      if (lastCatechism.data) {
        results.nextCatechism = {
          type: "catechism",
          label: `§${lastCatechism.data.paragraph + 1}`,
          route: `/catechism?p=${lastCatechism.data.paragraph + 1}`,
          subtitle: "Continuar Estudo do Catecismo",
        };
      }

      if (lastReflection.data) {
        results.lastReflection = {
          type: "reflection",
          content: lastReflection.data.content,
          date: lastReflection.data.created_at,
          readingType: lastReflection.data.reading_type,
        };
      }

      if (lastJournal.data) {
        results.lastJournal = {
          type: "journal",
          content: lastJournal.data.content,
          mood: lastJournal.data.mood,
          date: lastJournal.data.created_at,
        };
      }

      return results;
    },
    enabled: !!userId,
  });

  // Weekly Stats
  const weeklyStatsQuery = useQuery({
    queryKey: ["weekly-stats", userId],
    queryFn: async () => {
      if (!userId) return { chaptersRead: 0, journeySteps: 0, catechismParagraphs: 0 };
      const weekAgo = new Date();
      weekAgo.setDate(weekAgo.getDate() - 7);
      const iso = weekAgo.toISOString();

      const [chapRes, jpRes, catRes] = await Promise.all([
        supabase
          .from("bible_chapters_read")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .gte("read_at", iso),
        supabase
          .from("journey_progress")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .gte("completed_at", iso),
        supabase
          .from("catechism_paragraphs_read")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId)
          .gte("read_at", iso),
      ]);

      return {
        chaptersRead: chapRes.count || 0,
        journeySteps: jpRes.count || 0,
        catechismParagraphs: catRes.count || 0,
      };
    },
    enabled: !!userId,
  });

  return {
    spiritualProfile: spiritualProfileQuery.data,
    activeJourneys: activeJourneysQuery.data || [],
    saintsToday: saintsTodayQuery.data || [],
    nextUp: nextUpQuery.data,
    weeklyStats: weeklyStatsQuery.data || {
      chaptersRead: 0,
      journeySteps: 0,
      catechismParagraphs: 0,
    },
    isLoading:
      spiritualProfileQuery.isLoading ||
      activeJourneysQuery.isLoading ||
      saintsTodayQuery.isLoading ||
      nextUpQuery.isLoading ||
      weeklyStatsQuery.isLoading,
  };
};

/**
 * useDevotionalFavorites — CRUD sobre `bible_favorites` estendida para
 * suportar orações e trechos devocionais genéricos (content_type != 'bible_verse').
 */

import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";

export interface DevotionalFavorite {
  id: string;
  content_type: string;
  content_id: string | null;
  title: string | null;
  content: string | null;
  url: string | null;
  metadata: Record<string, unknown>;
  created_at: string;
}

export interface FavoriteInput {
  contentType: string; // ex.: 'prayer', 'rosary_mystery', 'viacrucis_station'
  contentId: string;
  title: string;
  content?: string | null;
  url?: string | null;
  metadata?: Record<string, unknown>;
}

export function useDevotionalFavorites(filterContentType?: string) {
  const { user } = useAuth();
  const [items, setItems] = useState<DevotionalFavorite[]>([]);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!user) {
      setItems([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    let q = supabase
      .from("bible_favorites")
      .select("id, content_type, content_id, title, content, url, metadata, created_at")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false });
    if (filterContentType) q = q.eq("content_type", filterContentType);
    const { data, error } = await q;
    if (!error && data) {
      setItems(
        data.map((d: any) => ({
          ...d,
          metadata: d.metadata ?? {},
        })),
      );
    }
    setLoading(false);
  }, [user, filterContentType]);

  useEffect(() => {
    load();
  }, [load]);

  const add = useCallback(
    async (input: FavoriteInput) => {
      if (!user) throw new Error("auth-required");
      const { error } = await supabase.from("bible_favorites").insert({
        user_id: user.id,
        content_type: input.contentType,
        content_id: input.contentId,
        title: input.title,
        content: input.content ?? null,
        url: input.url ?? null,
        metadata: (input.metadata ?? {}) as any,
      });
      if (error && !String(error.message).includes("duplicate")) throw error;
      await load();
    },
    [user, load],
  );

  const remove = useCallback(
    async (params: { contentType: string; contentId: string }) => {
      if (!user) throw new Error("auth-required");
      const { error } = await supabase
        .from("bible_favorites")
        .delete()
        .eq("user_id", user.id)
        .eq("content_type", params.contentType)
        .eq("content_id", params.contentId);
      if (error) throw error;
      await load();
    },
    [user, load],
  );

  const isFavorited = useCallback(
    (contentType: string, contentId: string) =>
      items.some((i) => i.content_type === contentType && i.content_id === contentId),
    [items],
  );

  const toggle = useCallback(
    async (input: FavoriteInput) => {
      if (isFavorited(input.contentType, input.contentId)) {
        await remove({ contentType: input.contentType, contentId: input.contentId });
      } else {
        await add(input);
      }
    },
    [isFavorited, remove, add],
  );

  return { items, loading, add, remove, toggle, isFavorited, reload: load };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";

export function useEnhancedRecommendations() {
  const { user, profile, userLevel } = useAuth();

  return useQuery({
    queryKey: ["enhanced-recommendations", user?.id, userLevel],
    queryFn: async () => {
      if (!user)
        return {
          type: "ritual",
          title: "Ritual do Dia",
          subtitle: "Prática Espiritual",
          description: "Mantenha sua constância diária no caminho de santidade.",
          route: "/hoje",
        };

      // 1. Fetch reading marks (recent activity)
      const { data: marks } = await supabase
        .from("reading_marks")
        .select("*")
        .eq("user_id", user.id)
        .order("updated_at", { ascending: false })
        .limit(3);

      // 2. Fetch journal entries (emotional state/topics)
      const { data: journal } = await supabase
        .from("spiritual_journal")
        .select("mood, content")
        .eq("user_id", user.id)
        .order("entry_date", { ascending: false })
        .limit(1);

      // 3. Fetch active journey progress
      const { data: activeJourney } = await supabase
        .from("journey_progress")
        .select("journey_id, step_id")
        .eq("user_id", user.id)
        .order("completed_at", { ascending: false })
        .limit(1);

      // Simple recommendation engine logic:
      // Priority 1: Continue Journey
      if (activeJourney?.[0]) {
        const { data: journey } = await supabase
          .from("journeys")
          .select("*")
          .eq("id", activeJourney[0].journey_id)
          .single();

        if (journey) {
          const { data: nextStep } = await supabase
            .from("journey_steps")
            .select("*")
            .eq("journey_id", journey.id)
            .order("step_order", { ascending: true })
            .gt("step_order", 0) // This is simplified
            .limit(1); // Real logic would find the actual NEXT step

          return {
            type: "journey",
            title: journey.title,
            subtitle: "Continuar sua caminhada",
            description: `Você está progredindo bem. Próximo passo: ${nextStep?.[0]?.title || "Finalizar"}`,
            route: `/jornadas/${journey.id}/step`,
            metadata: { journey, nextStep: nextStep?.[0] },
          };
        }
      }

      // Priority 2: Based on mood/journal
      if (journal?.[0]?.mood === "struggle") {
        return {
          type: "bible",
          title: "Salmo de Confiança",
          subtitle: "Conforto na tribulação",
          description: "Leia o Salmo 23 e encontre descanso no Bom Pastor.",
          route: "/bible?book=Salmos&ch=23",
        };
      }

      // Priority 3: Based on level/profile
      const diagnosis = profile?._sensitive?.diagnosis_result as any;
      if (diagnosis?.goal === "knowledge" || userLevel === "iniciante") {
        return {
          type: "catechism",
          title: "Fundamentos da Fé",
          subtitle: "O Símbolo dos Apóstolos",
          description: "Aprofunde-se no que cremos através do Catecismo.",
          route: "/catechism?p=1",
        };
      }

      // Default
      return {
        type: "ritual",
        title: "Ritual do Dia",
        subtitle: "Prática Espiritual",
        description: "Mantenha sua constância diária no caminho de santidade.",
        route: "/hoje",
      };
    },
    enabled: true,
    staleTime: 1000 * 60 * 15,
  });
}

/**
 * useFuzzySearch — shared client for fuzzy-search RPCs.
 *
 * Encapsulates the pattern repeated across Saints, Glossary, Community and
 * Themes pages: debounce the query, call a Postgres `search_*_fuzzy` RPC,
 * and decorate each row with a client-side `similarityScore` so the UI can
 * render <RelevanceBadge /> instantly without waiting for a second round-trip.
 *
 * Usage:
 *   const { results, isSearching, isPending } = useFuzzySearch({
 *     rpc: 'search_saints_fuzzy',
 *     query,
 *     primaryField: 'name',
 *     secondaryField: 'title',
 *   });
 */
import { useEffect, useState } from "react";
import { supabase } from "@/lib/db";
import { useDebounce } from "./useDebounce";
import { combinedSimilarity } from "@/lib/similarity";

/**
 * Names of the RPCs that follow the `search_*_fuzzy(search_query, result_limit)`
 * contract. Using a string union keeps Supabase's typed client happy while
 * letting callers pass the function name as a value.
 */
export type FuzzyRpcName =
  | "search_saints_fuzzy"
  | "search_glossary_fuzzy"
  | "search_community_posts_fuzzy"
  | "search_tags_fuzzy"
  | "search_journeys_fuzzy";

export interface UseFuzzySearchOptions<TRow> {
  /** Name of the Postgres RPC. Must match the FuzzyRpcName union. */
  rpc: FuzzyRpcName;
  /** Raw user input. The hook debounces it internally. */
  query: string;
  /** Field used as the primary similarity signal (e.g. "name", "term", "label"). */
  primaryField: keyof TRow;
  /** Optional secondary signal (e.g. "title", "definition", "content"). */
  secondaryField?: keyof TRow;
  /** Weight applied to the secondary similarity. Defaults to 0.7. */
  secondaryWeight?: number;
  /** Minimum query length before firing a request. Defaults to 2. */
  minLength?: number;
  /** Debounce delay in ms. Defaults to 300. */
  debounceMs?: number;
  /** Hard cap on returned rows. Defaults to 50. */
  resultLimit?: number;
}

export interface FuzzyRow {
  similarityScore?: number;
}

export interface UseFuzzySearchResult<TRow> {
  /** Ranked rows from the RPC, or `null` when the query is too short. */
  results: (TRow & FuzzyRow)[] | null;
  /** True while a network request is in flight. */
  isSearching: boolean;
  /** True while the debounce timer is pending (query !== debouncedQuery). */
  isPending: boolean;
  /** Last RPC error, if any. */
  error: Error | null;
  /** Re-executes the last query, useful after a transient backend error. */
  refetch: () => void;
}

export function useFuzzySearch<TRow>(
  options: UseFuzzySearchOptions<TRow>,
): UseFuzzySearchResult<TRow> {
  const {
    rpc,
    query,
    primaryField,
    secondaryField,
    secondaryWeight = 0.7,
    minLength = 2,
    debounceMs = 300,
    resultLimit = 50,
  } = options;

  const debouncedQuery = useDebounce(query, debounceMs);
  const [results, setResults] = useState<(TRow & FuzzyRow)[] | null>(null);
  const [isSearching, setIsSearching] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [retryTick, setRetryTick] = useState(0);

  const trimmed = debouncedQuery.trim();
  const isPending = query.trim().length >= minLength && (query.trim() !== trimmed || isSearching);

  useEffect(() => {
    if (trimmed.length < minLength) {
      setResults(null);
      setIsSearching(false);
      setError(null);
      return;
    }

    let cancelled = false;
    setIsSearching(true);
    setError(null);

    (async () => {
      const { data, error: rpcError } = await (
        supabase.rpc as unknown as (
          fn: string,
          args: { search_query: string; result_limit: number },
        ) => Promise<{ data: TRow[] | null; error: Error | null }>
      )(rpc, {
        search_query: trimmed,
        result_limit: resultLimit,
      });

      if (cancelled) return;

      if (rpcError) {
        console.error(`[useFuzzySearch] ${rpc} failed:`, rpcError);
        setError(rpcError);
        setResults(null);
      } else {
        const rows = (data ?? []).map((row) => {
          const r = row as Record<string, unknown>;
          return {
            ...row,
            similarityScore: combinedSimilarity(
              trimmed,
              String(r[primaryField as string] ?? ""),
              secondaryField ? String(r[secondaryField as string] ?? "") : undefined,
              secondaryWeight,
            ),
          };
        }) as (TRow & FuzzyRow)[];
        setResults(rows);
      }
      setIsSearching(false);
    })();

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    rpc,
    trimmed,
    primaryField,
    secondaryField,
    secondaryWeight,
    minLength,
    resultLimit,
    retryTick,
  ]);

  return { results, isSearching, isPending, error, refetch: () => setRetryTick((t) => t + 1) };
}

/**
 * useLiturgyHoursOffice — Próprio da Liturgia das Horas por (iso_date, hour_slug).
 *
 * Mesmo padrão de `useLiturgyMeditation` / `useMissalProper`:
 * - Consulta `liturgy_hours_offices` (público, read-only).
 * - Se ausente, dispara a edge function `liturgy-hours-office`.
 * - Cache React Query 24h + IndexedDB persistente (offline-first).
 * - Habilitado apenas quando existe uma hora selecionada.
 * - Dedupe via `queryKey` — chamadas simultâneas para o mesmo par
 *   (isoDate, hour) compartilham a mesma Promise.
 */
import { useEffect } from "react";
import { useQuery, useQueryClient, type QueryClient } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import type { DailyLiturgy } from "@/core/liturgy/LiturgyProvider";
import { getCachedHoursOffice, cacheHoursOffice } from "@/lib/offlineCache";

export type HourSlug = "oficio" | "laudes" | "tercia" | "sexta" | "noa" | "vesperas" | "completas";

export const ALL_HOUR_SLUGS: HourSlug[] = [
  "oficio",
  "laudes",
  "tercia",
  "sexta",
  "noa",
  "vesperas",
  "completas",
];

export interface OfficePsalmody {
  antiphon: string;
  reference: string;
  text: string;
}

export interface OfficeGospelCanticle {
  antiphon: string;
  reference: string;
  text: string;
}

export interface LiturgyHoursOfficeRow {
  iso_date: string;
  hour_slug: HourSlug;
  antiphon_opening: string | null;
  psalmody: OfficePsalmody[];
  brief_reading_ref: string | null;
  brief_reading_text: string | null;
  responsory: string | null;
  gospel_canticle: OfficeGospelCanticle | null;
  intercessions: string[];
  concluding_prayer: string;
  season_note: string | null;
  version: number | null;
  model: string | null;
  provider: string | null;
  prompt_hash: string | null;
  generated_at: string;
}

const queryKeyFor = (isoDate: string, hour: HourSlug) =>
  ["liturgy-hours-office", isoDate, hour] as const;

async function fetchExisting(
  isoDate: string,
  hour: HourSlug,
): Promise<LiturgyHoursOfficeRow | null> {
  const { data, error } = await supabase
    .from("liturgy_hours_offices" as any)
    .select("*")
    .eq("iso_date", isoDate)
    .eq("hour_slug", hour)
    .maybeSingle();
  if (error) return null;
  return (data as unknown as LiturgyHoursOfficeRow | null) ?? null;
}

async function generate(
  isoDate: string,
  hour: HourSlug,
  readings: DailyLiturgy | null,
): Promise<LiturgyHoursOfficeRow | null> {
  const { data, error } = await supabase.functions.invoke("liturgy-hours-office", {
    body: {
      iso_date: isoDate,
      hour_slug: hour,
      readings: readings
        ? {
            liturgia: readings.liturgia,
            dia: readings.dia,
            season: readings.season,
            primeiraLeitura: readings.primeiraLeitura,
            salmo: readings.salmo,
            segundaLeitura: readings.segundaLeitura,
            evangelho: readings.evangelho,
          }
        : undefined,
    },
  });
  if (error) return null;
  return (data as { office?: LiturgyHoursOfficeRow })?.office ?? null;
}

export interface OfficeResolution {
  office: LiturgyHoursOfficeRow | null;
  source: "remote" | "cache" | "generated" | "none";
}

/**
 * Estratégia offline-first:
 *  1. Supabase table → autoridade (revalida IDB).
 *  2. IDB → fallback quando a rede falha (retorna `source: 'cache'`).
 *  3. Edge function → gera + persiste.
 * IDB é gravado a cada sucesso de rede.
 */
async function resolveOffice(
  isoDate: string,
  hour: HourSlug,
  readings: DailyLiturgy | null,
): Promise<OfficeResolution> {
  const remote = await fetchExisting(isoDate, hour);
  if (remote) {
    await cacheHoursOffice(isoDate, hour, remote);
    return { office: remote, source: "remote" };
  }
  const cached = (await getCachedHoursOffice(isoDate, hour)) as LiturgyHoursOfficeRow | null;
  if (cached) return { office: cached, source: "cache" };
  const generated = await generate(isoDate, hour, readings);
  if (generated) {
    await cacheHoursOffice(isoDate, hour, generated);
    return { office: generated, source: "generated" };
  }
  return { office: null, source: "none" };
}

export function useLiturgyHoursOffice(
  isoDate: string,
  hour: HourSlug | null,
  readings: DailyLiturgy | null,
) {
  const qc = useQueryClient();
  const enabled = !!hour;

  const query = useQuery({
    queryKey: hour ? queryKeyFor(isoDate, hour) : ["liturgy-hours-office", isoDate, "none"],
    queryFn: async () =>
      hour ? resolveOffice(isoDate, hour, readings) : { office: null, source: "none" as const },
    enabled,
    staleTime: 1000 * 60 * 60 * 24,
    gcTime: 1000 * 60 * 60 * 24 * 7,
    retry: 0,
    initialData: undefined,
  });

  // Hidratação síncrona a partir do IDB — evita flicker enquanto o remoto chega.
  useEffect(() => {
    if (!hour) return;
    let cancelled = false;
    (async () => {
      const key = queryKeyFor(isoDate, hour);
      if (qc.getQueryData(key)) return;
      const cached = (await getCachedHoursOffice(isoDate, hour)) as LiturgyHoursOfficeRow | null;
      if (!cancelled && cached && !qc.getQueryData(key)) {
        qc.setQueryData(key, { office: cached, source: "cache" as const });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [isoDate, hour, qc]);

  const result = query.data ?? { office: null, source: "none" as const };
  return {
    office: result.office,
    source: result.source,
    fromCache: result.source === "cache",
    isLoading: query.isLoading,
    isError: query.isError,
  };
}

/**
 * Pré-carrega as 7 horas canônicas para (isoDate). Idempotente:
 *  - Reusa entradas já hidratadas (React Query dedupe por `queryKey`).
 *  - Nunca dispara requisições paralelas para o mesmo par.
 *  - Silencia erros individuais (best-effort).
 */
export function prefetchAllHoursForDay(
  qc: QueryClient,
  isoDate: string,
  readings: DailyLiturgy | null,
): Promise<void> {
  const jobs = ALL_HOUR_SLUGS.map((hour) =>
    qc
      .prefetchQuery({
        queryKey: queryKeyFor(isoDate, hour),
        queryFn: () => resolveOffice(isoDate, hour, readings),
        staleTime: 1000 * 60 * 60 * 24,
        gcTime: 1000 * 60 * 60 * 24 * 7,
      })
      .catch(() => {
        /* silent */
      }),
  );
  return Promise.allSettled(jobs).then(() => undefined);
}

/**
 * useLiturgyMeditation — busca o pacote editorial do dia.
 *
 * Fluxo:
 *   1. Habilitado apenas depois que `useDailyLiturgy` retornou (evangelho).
 *   2. Consulta `liturgy_meditations` (público, read-only) por iso_date.
 *   3. Se ausente, chama a edge function `liturgy-meditation` (que gera
 *      e persiste). Ao chegar novo resultado, invalida a query.
 *   4. Cache de 24h no React Query + espelho em localStorage para
 *      sobreviver a refresh e alimentar fallback quando IA falhar.
 */

import { useCallback, useEffect, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { telemetry } from "@/utils/navigation-telemetry";
import type { DailyLiturgy } from "@/core/liturgy/LiturgyProvider";

export interface FatherCitation {
  author: string;
  work: string;
  reference: string;
  quote: string;
}
export interface CatechismCitation {
  paragraph: number;
  quote: string;
}
export interface MagisteriumCitation {
  document: string;
  pope: string;
  section: string;
  quote: string;
}
export interface LogosMeditation {
  observe: string;
  reflect: string;
  pray: string;
  live: string;
}
export interface ChurchHistoryBlock {
  saint: string | null;
  council: string | null;
  pope: string | null;
  document: string | null;
}

export type MeditationFailureCode = "ai_credits_exhausted" | "ai_rate_limited" | "ai_unavailable";

export interface LiturgyMeditationRow {
  iso_date: string;
  theme: string | null;
  reading_key: string | null;
  fathers: FatherCitation[];
  catechism: CatechismCitation[];
  magisterium: MagisteriumCitation[];
  logos: LogosMeditation | null;
  final_prayer: string | null;
  church_history: ChurchHistoryBlock | null;
  action_of_day: string | null;
  version: number | null;
  model: string | null;
  provider: string | null;
  prompt_hash: string | null;
  generated_at: string;
  fallback?: boolean;
  fallback_code?: MeditationFailureCode | string;
  fallback_message?: string;
  /** Fonte do último fallback: cache local anterior, banco antigo, ou builder local. */
  fallback_source?: "local-cache" | "local-builder" | "previous-day";
  /** Estimativa (ISO) para próxima tentativa automática, quando aplicável. */
  fallback_retry_at?: string;
}

type LiturgyMeditationResponse = {
  meditation?: LiturgyMeditationRow;
  code?: string;
  message?: string;
};

const DEFAULT_AI_FALLBACK_MESSAGE =
  "A meditação editorial automática está temporariamente indisponível. As leituras permanecem disponíveis para oração.";

const AI_CREDITS_EXHAUSTED_MESSAGE =
  "Os créditos de IA da plataforma se esgotaram. A meditação editorial voltará assim que forem recarregados.";

const AI_RATE_LIMIT_MESSAGE =
  "Muitas requisições simultâneas ao gerador de meditação. Tente novamente em instantes.";

/** Janela estimada até nova tentativa automática, em minutos, por código. */
const RETRY_WINDOW_MINUTES: Record<MeditationFailureCode, number> = {
  ai_credits_exhausted: 60,
  ai_rate_limited: 2,
  ai_unavailable: 10,
};

const CACHE_KEY_PREFIX = "cathedra:liturgy-meditation:v1:";
const CACHE_MAX_ENTRIES = 14;
const FALLBACK_EVENTS_KEY = "cathedra:liturgy-meditation:fallback-events:v1";
const FALLBACK_EVENTS_MAX = 500;

export interface FallbackEventLog {
  at: string;
  iso_date: string;
  code: MeditationFailureCode | string;
  source: "local-cache" | "local-builder" | "previous-day";
  retry_at: string | null;
  message: string | null;
}

function persistFallbackEvent(evt: FallbackEventLog): void {
  const s = safeStorage();
  if (!s) return;
  try {
    const raw = s.getItem(FALLBACK_EVENTS_KEY);
    const list: FallbackEventLog[] = raw ? JSON.parse(raw) : [];
    // Dedupe por (iso_date|code|source) numa janela de 6h.
    const dedupeKey = `${evt.iso_date}|${evt.code}|${evt.source}`;
    const sixHoursAgo = Date.now() - 6 * 60 * 60_000;
    const isDup = list.some(
      (e) =>
        `${e.iso_date}|${e.code}|${e.source}` === dedupeKey &&
        new Date(e.at).getTime() > sixHoursAgo,
    );
    if (isDup) return;
    list.unshift(evt);
    if (list.length > FALLBACK_EVENTS_MAX) list.length = FALLBACK_EVENTS_MAX;
    s.setItem(FALLBACK_EVENTS_KEY, JSON.stringify(list));
  } catch {
    /* quota — ignora */
  }
}

export function readFallbackEvents(): FallbackEventLog[] {
  const s = safeStorage();
  if (!s) return [];
  try {
    const raw = s.getItem(FALLBACK_EVENTS_KEY);
    return raw ? (JSON.parse(raw) as FallbackEventLog[]) : [];
  } catch {
    return [];
  }
}

export function clearFallbackEvents(): void {
  const s = safeStorage();
  if (!s) return;
  try {
    s.removeItem(FALLBACK_EVENTS_KEY);
  } catch {
    /* ignora */
  }
}

// ── Persistência local ─────────────────────────────────────────────
function safeStorage(): Storage | null {
  try {
    if (typeof window === "undefined") return null;
    return window.localStorage;
  } catch {
    return null;
  }
}

function cacheKey(isoDate: string) {
  return `${CACHE_KEY_PREFIX}${isoDate}`;
}

function readLocalMeditation(isoDate: string): LiturgyMeditationRow | null {
  const s = safeStorage();
  if (!s) return null;
  try {
    const raw = s.getItem(cacheKey(isoDate));
    if (!raw) return null;
    return JSON.parse(raw) as LiturgyMeditationRow;
  } catch {
    return null;
  }
}

function writeLocalMeditation(row: LiturgyMeditationRow) {
  // Nunca persistir um fallback: só o conteúdo editorial real deve virar cache reutilizável.
  if (row.fallback) return;
  const s = safeStorage();
  if (!s) return;
  try {
    s.setItem(cacheKey(row.iso_date), JSON.stringify(row));
    pruneCache(s);
  } catch {
    /* quota — silencia */
  }
}

function pruneCache(storage: Storage) {
  try {
    const keys: string[] = [];
    for (let i = 0; i < storage.length; i++) {
      const k = storage.key(i);
      if (k && k.startsWith(CACHE_KEY_PREFIX)) keys.push(k);
    }
    if (keys.length <= CACHE_MAX_ENTRIES) return;
    keys.sort(); // iso_date lexicográfico == cronológico
    for (const k of keys.slice(0, keys.length - CACHE_MAX_ENTRIES)) {
      storage.removeItem(k);
    }
  } catch {
    /* ignore */
  }
}

function readMostRecentLocal(beforeIso: string): LiturgyMeditationRow | null {
  const s = safeStorage();
  if (!s) return null;
  try {
    const candidates: LiturgyMeditationRow[] = [];
    for (let i = 0; i < s.length; i++) {
      const k = s.key(i);
      if (!k || !k.startsWith(CACHE_KEY_PREFIX)) continue;
      try {
        const row = JSON.parse(s.getItem(k) ?? "null") as LiturgyMeditationRow | null;
        if (row && !row.fallback && row.iso_date && row.iso_date < beforeIso) {
          candidates.push(row);
        }
      } catch {
        /* pula entrada inválida */
      }
    }
    if (candidates.length === 0) return null;
    candidates.sort((a, b) => b.iso_date.localeCompare(a.iso_date));
    return candidates[0];
  } catch {
    return null;
  }
}

function messageForCode(code: MeditationFailureCode | string | undefined): string {
  switch (code) {
    case "ai_credits_exhausted":
      return AI_CREDITS_EXHAUSTED_MESSAGE;
    case "ai_rate_limited":
      return AI_RATE_LIMIT_MESSAGE;
    default:
      return DEFAULT_AI_FALLBACK_MESSAGE;
  }
}

function retryAtFor(code: MeditationFailureCode | string | undefined): string {
  const known =
    (code as MeditationFailureCode) in RETRY_WINDOW_MINUTES
      ? (code as MeditationFailureCode)
      : "ai_unavailable";
  const minutes = RETRY_WINDOW_MINUTES[known];
  return new Date(Date.now() + minutes * 60_000).toISOString();
}

async function fetchExisting(isoDate: string): Promise<LiturgyMeditationRow | null> {
  const { data, error } = await supabase
    .from("liturgy_meditations" as any)
    .select("*")
    .eq("iso_date", isoDate)
    .maybeSingle();
  if (error) return null;
  return (data as unknown as LiturgyMeditationRow | null) ?? null;
}

async function readInvokeFailure(
  error: unknown,
): Promise<{ code: MeditationFailureCode; message: string }> {
  const context = (error as { context?: unknown })?.context;
  if (context instanceof Response) {
    try {
      const payload = (await context.clone().json()) as {
        code?: string;
        message?: string;
        detail?: string;
      };
      const code =
        (payload.code as MeditationFailureCode) ??
        inferCode(context.status, payload.message ?? payload.detail);
      return {
        code,
        message: payload.message ?? messageForCode(code),
      };
    } catch {
      const code = inferCode(context.status);
      return { code, message: messageForCode(code) };
    }
  }
  const msg = (error as { message?: string })?.message;
  const code = inferCode(undefined, msg);
  return { code, message: messageForCode(code) };
}

function inferCode(status?: number, message?: string): MeditationFailureCode {
  if (status === 402 || /402|payment required|credit|insufficient|quota/i.test(message ?? "")) {
    return "ai_credits_exhausted";
  }
  if (status === 429 || /429|rate limit|too many requests/i.test(message ?? "")) {
    return "ai_rate_limited";
  }
  return "ai_unavailable";
}

function buildClientFallbackMeditation(
  isoDate: string,
  readings: DailyLiturgy,
  failure?: { code: MeditationFailureCode | string; message: string },
): LiturgyMeditationRow {
  // 1. Preferir cache local do MESMO dia (meditação editorial anterior real).
  const localSame = readLocalMeditation(isoDate);
  if (localSame && !localSame.fallback) {
    return {
      ...localSame,
      fallback: true,
      fallback_code: (failure?.code as MeditationFailureCode) ?? "ai_unavailable",
      fallback_message: failure?.message ?? messageForCode(failure?.code),
      fallback_source: "local-cache",
      fallback_retry_at: retryAtFor(failure?.code),
    };
  }

  // 2. Reaproveitar meditação editorial de dia anterior armazenada localmente.
  const previous = readMostRecentLocal(isoDate);
  if (previous) {
    return {
      ...previous,
      iso_date: isoDate,
      fallback: true,
      fallback_code: (failure?.code as MeditationFailureCode) ?? "ai_unavailable",
      fallback_message: failure?.message ?? messageForCode(failure?.code),
      fallback_source: "previous-day",
      fallback_retry_at: retryAtFor(failure?.code),
    };
  }

  // 3. Último recurso: montar a partir das leituras do dia.
  const gospelRef = readings.evangelho?.referencia ?? "Evangelho do dia";
  const celebration = readings.liturgia || readings.dia || "Liturgia do dia";
  const psalmRefrain = readings.salmo?.refrao;

  return {
    iso_date: isoDate,
    theme: celebration,
    reading_key: psalmRefrain
      ? `Permaneça com o refrão do salmo: “${psalmRefrain}”. Ele oferece uma chave segura de oração enquanto a meditação editorial não está disponível.`
      : `Permaneça com ${gospelRef}. Leia o texto lentamente e identifique uma palavra para levar à oração do dia.`,
    fathers: [],
    catechism: [],
    magisterium: [],
    logos: {
      observe: `Leia novamente ${gospelRef} e acolha o gesto central de Cristo sem pressa.`,
      reflect:
        "Pergunte onde essa Palavra toca sua vida concreta hoje, especialmente nas decisões pequenas.",
      pray: "Fale com o Senhor a partir da frase que mais permaneceu no coração.",
      live: "Escolha um ato simples de fidelidade antes do fim do dia.",
    },
    final_prayer:
      "Senhor, guardai em mim a vossa Palavra. Dai-me um coração atento, humilde e perseverante, para que a liturgia deste dia se torne vida concreta. Amém.",
    church_history: null,
    action_of_day:
      "Releia o Evangelho em silêncio por três minutos e pratique uma obra concreta de caridade.",
    version: null,
    model: null,
    provider: "local-fallback",
    prompt_hash: null,
    generated_at: new Date().toISOString(),
    fallback: true,
    fallback_code: (failure?.code as MeditationFailureCode) ?? "ai_unavailable",
    fallback_message: failure?.message ?? messageForCode(failure?.code),
    fallback_source: "local-builder",
    fallback_retry_at: retryAtFor(failure?.code),
  };
}

async function generate(
  isoDate: string,
  readings: DailyLiturgy,
): Promise<LiturgyMeditationRow | null> {
  const { data, error } = await supabase.functions.invoke("liturgy-meditation", {
    body: {
      iso_date: isoDate,
      readings: {
        liturgia: readings.liturgia,
        dia: readings.dia,
        season: readings.season,
        primeiraLeitura: readings.primeiraLeitura,
        salmo: readings.salmo,
        segundaLeitura: readings.segundaLeitura,
        evangelho: readings.evangelho,
      },
    },
  });
  if (error) {
    const failure = await readInvokeFailure(error);
    return buildClientFallbackMeditation(isoDate, readings, failure);
  }
  const payload = data as LiturgyMeditationResponse | null;
  const row = payload?.meditation ?? null;
  if (row) {
    // A edge function pode devolver um fallback (200) — só cacheia quando é real.
    if (!row.fallback) writeLocalMeditation(row);
    else {
      // Enriquecer fallback do servidor com fonte local se disponível.
      return buildClientFallbackMeditation(isoDate, readings, {
        code:
          (payload?.code as MeditationFailureCode) ??
          (row.fallback_code as MeditationFailureCode) ??
          "ai_unavailable",
        message: payload?.message ?? row.fallback_message ?? messageForCode(row.fallback_code),
      });
    }
    return row;
  }
  if (payload?.code || payload?.message) {
    return buildClientFallbackMeditation(isoDate, readings, {
      code: (payload.code as MeditationFailureCode) ?? "ai_unavailable",
      message: payload.message ?? DEFAULT_AI_FALLBACK_MESSAGE,
    });
  }
  return null;
}

export function useLiturgyMeditation(isoDate: string, readings: DailyLiturgy | null) {
  const qc = useQueryClient();
  const enabled = !!readings?.evangelho?.texto;

  const query = useQuery({
    queryKey: ["liturgy-meditation", isoDate],
    queryFn: async () => {
      const cached = await fetchExisting(isoDate);
      if (cached) {
        if (!cached.fallback) writeLocalMeditation(cached);
        return cached;
      }
      if (!readings) return null;
      return await generate(isoDate, readings);
    },
    enabled,
    staleTime: 1000 * 60 * 60 * 24,
    gcTime: 1000 * 60 * 60 * 24 * 7,
    retry: 0,
    // Enquanto carrega, oferece imediatamente o cache local como placeholder.
    placeholderData: () => readLocalMeditation(isoDate) ?? undefined,
  });

  // Ao carregar do banco por hit rápido mas leituras ausentes, dispara geração
  // silenciosa em background (útil na primeira vez do dia).
  useEffect(() => {
    if (!enabled || !readings) return;
    if (query.data || query.isFetching) return;
    (async () => {
      const row = await generate(isoDate, readings);
      if (row) qc.setQueryData(["liturgy-meditation", isoDate], row);
    })().catch(() => {
      /* silencia — bloco degrada */
    });
  }, [enabled, readings, isoDate, query.data, query.isFetching, qc]);

  const retry = useCallback(async () => {
    if (!readings) return;
    await qc.invalidateQueries({ queryKey: ["liturgy-meditation", isoDate] });
    await query.refetch();
  }, [qc, isoDate, readings, query]);

  // ── Telemetria de fallback ──
  // Sempre que a meditação em cache/essencial for exibida, emitimos um
  // evento único (dedupe por date+code+source) para acompanharmos com
  // que frequência a IA falha e qual código dispara — visível no
  // TelemetryDashboard / navigation-telemetry buffer + buffer local
  // consumido pelo painel /admin/liturgia-meditation-fallback.
  const lastLoggedRef = useRef<string | null>(null);
  useEffect(() => {
    const row = query.data;
    if (!row || !row.fallback) return;
    const code = (row.fallback_code as MeditationFailureCode | undefined) ?? "ai_unavailable";
    const source = row.fallback_source ?? "local-builder";
    const key = `${row.iso_date}|${code}|${source}`;
    if (lastLoggedRef.current === key) return;
    lastLoggedRef.current = key;
    const payload = {
      iso_date: row.iso_date,
      code,
      source,
      retry_at: row.fallback_retry_at ?? null,
      message: row.fallback_message ?? null,
    };
    telemetry.log("liturgy.meditation.fallback", "warn", payload);
    persistFallbackEvent({ ...payload, at: new Date().toISOString() });
  }, [query.data]);

  return {
    meditation: query.data ?? null,
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    isError: query.isError,
    retry,
  };
}

