import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/lib/db";
import { useAuth } from "./useAuth";
import { saveUserPsychology } from "@/lib/psychologicalProfile";

export interface UserNote {
  id: string;
  content_type: string;
  content_id: string;
  note_text: string;
  highlight_color: string;
  book_abbr?: string;
  chapter?: number;
  paragraph?: number;
  verse?: number;
  created_at: string;
  updated_at: string;
}

export function useNotes(contentType: string, contentId?: string) {
  const { user } = useAuth();
  const [notes, setNotes] = useState<UserNote[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchNotes = useCallback(async () => {
    if (!user) {
      setNotes([]);
      return;
    }
    setLoading(true);
    let query = supabase
      .from("user_notes")
      .select("*")
      .eq("user_id", user.id)
      .eq("content_type", contentType)
      .order("created_at", { ascending: false });

    if (contentId) query = query.eq("content_id", contentId);

    const { data } = await query;
    setNotes((data as UserNote[]) || []);
    setLoading(false);
  }, [user, contentType, contentId]);

  useEffect(() => {
    fetchNotes();
  }, [fetchNotes]);

  // Realtime synchronization
  useEffect(() => {
    if (!user) return;

    const channel = supabase
      .channel(`user_notes_realtime_${contentType}_${contentId || "all"}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "user_notes",
          filter: `user_id=eq.${user.id}`,
        },
        (payload) => {
          // Only refresh if it matches the content type filter (if not 'all')
          const newNote = payload.new as any;
          if (contentType === "all" || (newNote && newNote.content_type === contentType)) {
            fetchNotes();
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, fetchNotes, contentType, contentId]);

  const addNote = useCallback(
    async (
      cId: string,
      text: string,
      color = "yellow",
      context?: { book_abbr?: string; chapter?: number; paragraph?: number; verse?: number },
    ) => {
      if (!user || !text.trim()) return null;

      // Create temporary item for optimistic UI
      const tempId = crypto.randomUUID();
      const tempNote: UserNote = {
        id: tempId,
        content_type: contentType,
        content_id: cId,
        note_text: text.trim(),
        highlight_color: color,
        ...context,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      // Optimistic update
      setNotes((prev) => [tempNote, ...prev]);

      try {
        const { data, error } = await supabase
          .from("user_notes")
          .insert({
            user_id: user.id,
            content_type: contentType,
            content_id: cId,
            note_text: text.trim(),
            highlight_color: color,
            ...context,
          })
          .select()
          .single();

        if (!error && data) {
          // Replace temp note with real data from server
          setNotes((prev) => prev.map((n) => (n.id === tempId ? (data as UserNote) : n)));

          // Save psychological profile (backgrounded)
          saveUserPsychology(user.id, text.trim(), `note_${contentType}`);

          return data as UserNote;
        } else {
          throw error || new Error("Failed to save note");
        }
      } catch (err) {
        console.error("Error adding note:", err);
        // Rollback optimistic update
        setNotes((prev) => prev.filter((n) => n.id !== tempId));
        return null;
      }
    },
    [user, contentType],
  );

  const updateNote = useCallback(
    async (noteId: string, text: string, color?: string) => {
      if (!user) return;
      const updates: any = { note_text: text.trim(), updated_at: new Date().toISOString() };
      if (color) updates.highlight_color = color;

      await supabase.from("user_notes").update(updates).eq("id", noteId);
      setNotes((prev) => prev.map((n) => (n.id === noteId ? { ...n, ...updates } : n)));
    },
    [user],
  );

  const deleteNote = useCallback(
    async (noteId: string) => {
      if (!user) return;
      await supabase.from("user_notes").delete().eq("id", noteId);
      setNotes((prev) => prev.filter((n) => n.id !== noteId));
    },
    [user],
  );

  return { notes, loading, addNote, updateNote, deleteNote, refetch: fetchNotes };
}

/**
 * useReaderTypography — preferências de conforto de leitura persistidas.
 * Três presets (compact | normal | large) combinando fator de zoom + line-height.
 * Persistência: localStorage (funciona offline, cross-session).
 */
import { useCallback, useEffect, useState } from "react";

export type ReaderDensity = "compact" | "normal" | "large";

const STORAGE_KEY = "cathedra:reader-density";

const PRESETS: Record<ReaderDensity, { zoom: number; lineHeight: number; label: string }> = {
  compact: { zoom: 0.92, lineHeight: 1.45, label: "Compacto" },
  normal: { zoom: 1.0, lineHeight: 1.65, label: "Normal" },
  large: { zoom: 1.15, lineHeight: 1.85, label: "Amplo" },
};

function readStored(): ReaderDensity {
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    if (v === "compact" || v === "normal" || v === "large") return v;
  } catch {
    /* silent */
  }
  return "normal";
}

export function useReaderTypography() {
  const [density, setDensityState] = useState<ReaderDensity>(readStored);

  const setDensity = useCallback((d: ReaderDensity) => {
    setDensityState(d);
    try {
      localStorage.setItem(STORAGE_KEY, d);
    } catch {
      /* silent */
    }
  }, []);

  // Sincroniza entre abas.
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY && e.newValue) setDensityState(readStored());
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const preset = PRESETS[density];
  const wrapperStyle: React.CSSProperties = {
    // `zoom` escala fonte e espaçamento proporcionalmente — cobrindo padding,
    // gaps e imagens. Suportado em todos os navegadores modernos.
    zoom: preset.zoom,
    // Custom property consumida por seletores escopados dentro do wrapper.
    ["--reader-line-height" as any]: String(preset.lineHeight),
  };

  return { density, setDensity, wrapperStyle, presets: PRESETS };
}

import React, { useState, useEffect, useCallback } from "react";

const useReadingAutoHide = (enabled: boolean = true) => {
  useEffect(() => {
    if (!enabled) {
      document.documentElement.classList.remove("reading-scroll-down");
      document.documentElement.classList.remove("reveal-chrome");
      return;
    }

    let lastScrollY = window.scrollY;
    let ticking = false;

    const updateScrollDir = () => {
      const scrollY = window.scrollY;

      if (Math.abs(scrollY - lastScrollY) < 10) {
        ticking = false;
        return;
      }

      if (scrollY > lastScrollY && scrollY > 100) {
        document.documentElement.classList.add("reading-scroll-down");
        // Hide chrome if revealed by tap when starting to scroll down again
        document.documentElement.classList.remove("reveal-chrome");
      } else {
        document.documentElement.classList.remove("reading-scroll-down");
      }

      lastScrollY = scrollY > 0 ? scrollY : 0;
      ticking = false;
    };

    const onScroll = () => {
      if (!ticking) {
        window.requestAnimationFrame(updateScrollDir);
        ticking = true;
      }
    };

    const onTap = (e: MouseEvent | TouchEvent) => {
      // If UI is hidden, a tap should reveal it
      if (document.documentElement.classList.contains("reading-scroll-down")) {
        // Check if the click is on a link or button - if so, don't just toggle UI
        const target = e.target as HTMLElement;
        if (target.closest('button, a, [role="button"]')) return;

        document.documentElement.classList.toggle("reveal-chrome");

        // Vibrate for feedback if supported
        if ("vibrate" in navigator) {
          navigator.vibrate(10);
        }
      } else {
        document.documentElement.classList.remove("reveal-chrome");
      }
    };

    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("click", onTap as any);

    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("click", onTap as any);
      document.documentElement.classList.remove("reading-scroll-down");
      document.documentElement.classList.remove("reveal-chrome");
    };
  }, [enabled]);
};

export default useReadingAutoHide;

import { useEffect, useRef } from "react";

/**
 * Lightweight render performance probe.
 *
 * Padronizado para coletar APENAS o essencial:
 *  - contagem de renders
 *  - duração da montagem até o primeiro effect
 *
 * Em produção é praticamente um no-op (sem PerformanceObserver, sem inserts
 * no banco, sem breadcrumbs Sentry por render). Isso evita re-renders e
 * escrita excessiva de logs durante a navegação.
 *
 * Para habilitar amostragem mínima em produção, defina
 * `window.__PERF_SAMPLE__ = 0.05` (5%) via console ou flag.
 */
export function useRenderPerf(componentName: string, _threshold = 5) {
  const renderCount = useRef(0);
  const mountedAt = useRef<number>(0);
  renderCount.current++;

  useEffect(() => {
    mountedAt.current = performance.now();

    return () => {
      if (!import.meta.env.DEV) {
        const sample = (globalThis as any).__PERF_SAMPLE__ ?? 0;
        if (Math.random() > sample) return;
      }
      const duration = performance.now() - mountedAt.current;
      // Single, cheap log line. No table, no group, no network.
      // eslint-disable-next-line no-console
      console.debug(
        `[perf] ${componentName} renders=${renderCount.current} dur=${duration.toFixed(0)}ms`,
      );
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [componentName]);
}

