/**
 * useSaintOfDay — hook único para o Santo do Dia.
 *
 * Unifica duas fontes historicamente desconectadas:
 *   1. Edge function `saint-of-the-day` (nome/título oficiais do dia).
 *   2. Fallback local via `getSaintsByDate` (santoral persistido).
 *
 * Consumo previsto: LiturgiaPage, DailyLiturgy (Átrio), Header, LiturgyAdapter.
 */

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { getSaintsByDate } from "@/services/saintsService";
import { toIsoDateKey } from "@/core/liturgy/LiturgyProvider";

export interface SaintOfDay {
  name: string;
  title?: string | null;
  slug?: string | null;
  image?: string | null;
  source: "official" | "santoral" | "none";
}

interface OfficialSaintPayload {
  name?: string | null;
  title?: string | null;
  slug?: string | null;
  image?: string | null;
}

async function fetchOfficial(): Promise<OfficialSaintPayload | null> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 12_000);
  try {
    const { data, error } = await supabase.functions.invoke("saint-of-the-day", {
      // signal é suportado pelo runtime do supabase-js
      signal: controller.signal,
    } as any);
    if (error) {
      window.dispatchEvent(new CustomEvent("supabase-unreachable"));
      return null;
    }

    if (!data || typeof data !== "object") return null;
    const d = data as OfficialSaintPayload;
    if (!d.name || d.name === "Santo do Dia") return null;
    return d;
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

async function fetchFor(date: Date): Promise<SaintOfDay | null> {
  const now = new Date();
  const isToday = toIsoDateKey(date) === toIsoDateKey(now);

  // Fonte oficial só cobre "hoje". Para outras datas, vamos direto ao santoral.
  if (isToday) {
    const official = await fetchOfficial();
    if (official?.name) {
      return {
        name: official.name,
        title: official.title ?? null,
        slug: official.slug ?? null,
        image: official.image ?? null,
        source: "official",
      };
    }
  }

  const list = await getSaintsByDate(date.getMonth() + 1, date.getDate());
  if (list && list.length > 0) {
    const s = list[0];
    return {
      name: s.name,
      title: s.title ?? null,
      slug: (s as any).slug ?? null,
      image: s.image ?? null,
      source: "santoral",
    };
  }

  return null;
}

export function useSaintOfDay(date: Date = new Date()) {
  return useQuery({
    queryKey: ["saint-of-day", toIsoDateKey(date)],
    queryFn: () => fetchFor(date),
    staleTime: 1000 * 60 * 60, // 1h
    gcTime: 1000 * 60 * 60 * 24,
    retry: 1,
    refetchOnWindowFocus: false,
  });
}

import { useCallback } from "react";
import { toast } from "sonner";

interface ShareData {
  title: string;
  text: string;
  url?: string;
}

export const useShare = () => {
  const share = useCallback(async ({ title, text, url }: ShareData) => {
    const shareUrl = url || window.location.href;

    // Try native Web Share API first (mobile / PWA)
    if (navigator.share) {
      try {
        await navigator.share({ title, text, url: shareUrl });
        return;
      } catch (err: any) {
        if (err.name === "AbortError") return; // user cancelled
      }
    }

    // Fallback: copy to clipboard
    const fullText = `${title}\n\n${text}\n\n${shareUrl}`;
    try {
      await navigator.clipboard.writeText(fullText);
      toast.success("Copiado para a área de transferência!");
    } catch {
      toast.error("Não foi possível compartilhar.");
    }
  }, []);

  return share;
};

/**
 * Memória espiritual do usuário — não é gamificação, é presença.
 *
 * Consolida contagens simples (leituras, orações, jornadas) e o streak
 * atual/recorde para exibir "Sua caminhada" no Átrio.
 */
import { useEffect, useState } from "react";
import { supabase } from "@/lib/db";

export interface SpiritualMemory {
  streakDays: number;
  maxStreak: number;
  readings: number;
  prayers: number;
  journeys: number;
  loading: boolean;
}

const INITIAL: SpiritualMemory = {
  streakDays: 0,
  maxStreak: 0,
  readings: 0,
  prayers: 0,
  journeys: 0,
  loading: true,
};

export function useSpiritualMemory(
  userId: string | null | undefined,
  streakDays: number = 0,
  maxStreak: number = 0,
): SpiritualMemory {
  const [state, setState] = useState<SpiritualMemory>(INITIAL);

  useEffect(() => {
    if (!userId) {
      setState({ ...INITIAL, loading: false });
      return;
    }

    let active = true;

    (async () => {
      const [readingsRes, prayersRes, journeysRes] = await Promise.all([
        supabase
          .from("user_notes")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId),
        (supabase as any)
          .from("prayer_sessions")
          .select("id", { count: "exact", head: true })
          .eq("user_id", userId),
        supabase
          .from("journey_progress")
          .select("journey_id", { count: "exact", head: true })
          .eq("user_id", userId),
      ]);

      if (!active) return;
      setState({
        streakDays,
        maxStreak: Math.max(maxStreak, streakDays),
        readings: readingsRes.count ?? 0,
        prayers: prayersRes.count ?? 0,
        journeys: journeysRes.count ?? 0,
        loading: false,
      });
    })().catch(() => {
      if (active) setState({ ...INITIAL, streakDays, maxStreak, loading: false });
    });

    return () => {
      active = false;
    };
  }, [userId, streakDays, maxStreak]);

  return state;
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { ProfileId } from "@/components/cathedra/SpiritualQuiz";

/**
 * Reusable hook to retrieve the current user's spiritual profile.
 * Used to highlight suggested bubbles across all pages where the
 * Nexus theological bubbles appear.
 */
export const useSpiritualProfile = (): { profileId: ProfileId | null; isLoading: boolean } => {
  const { user } = useAuth();
  const userId = user?.id;

  const query = useQuery({
    queryKey: ["spiritual-profile", userId],
    queryFn: async () => {
      if (!userId) return null;
      const { data } = await (supabase as any)
        .from("user_sensitive_data")
        .select("diagnosis_result")
        .eq("user_id", userId)
        .maybeSingle();

      const sp = data?.diagnosis_result?.spiritual_profile;
      if (sp) return sp as ProfileId;

      const spiritualProfileMap: Record<string, string> = {
        beginning: "sedento_de_sentido",
        deepening: "firme_aprofundando",
        struggling: "ferido_em_busca",
        serving: "ardente_missionario",
      };
      return (spiritualProfileMap[data?.diagnosis_result?.moment] || null) as ProfileId | null;
    },
    enabled: !!userId,
    staleTime: 1000 * 60 * 10,
  });

  return { profileId: (query.data ?? null) as ProfileId | null, isLoading: query.isLoading };
};

import { useEffect, useRef } from "react";
import { telemetry } from "@/utils/navigation-telemetry";

interface SwipeOptions {
  onSwipeLeft?: () => void; // próximo
  onSwipeRight?: () => void; // anterior
  onTap?: () => void; // tap rápido para revelar UI
  threshold?: number; // px mínimos (opcional, sobrescreve env)
  ratio?: number; // razão diagonal (opcional, sobrescreve env)
  enabled?: boolean;
}

// Configurações via variáveis de ambiente com fallbacks seguros
const SWIPE_THRESHOLD = Number(import.meta.env.VITE_SWIPE_THRESHOLD) || 80;
const SWIPE_RATIO = Number(import.meta.env.VITE_SWIPE_RATIO) || 2.5;

/**
 * Hook de navegação por gestos no mobile.
 * Detecta swipe horizontal (>= threshold) e tap curto (sem deslocamento).
 * Ignora scroll vertical para não interferir na leitura.
 */
export function useSwipeNavigation({
  onSwipeLeft,
  onSwipeRight,
  onTap,
  threshold = SWIPE_THRESHOLD,
  ratio = SWIPE_RATIO,
  enabled = true,
}: SwipeOptions) {
  const startX = useRef(0);
  const startY = useRef(0);
  const startT = useRef(0);
  const moved = useRef(false);

  useEffect(() => {
    if (!enabled) return;

    const onStart = (e: TouchEvent) => {
      const t = e.touches[0];
      startX.current = t.clientX;
      startY.current = t.clientY;
      startT.current = Date.now();
      moved.current = false;
    };

    const onMove = (e: TouchEvent) => {
      const t = e.touches[0];
      if (Math.abs(t.clientX - startX.current) > 8 || Math.abs(t.clientY - startY.current) > 8) {
        moved.current = true;
      }
    };

    const onEnd = (e: TouchEvent) => {
      const t = e.changedTouches[0];
      const dx = t.clientX - startX.current;
      const dy = t.clientY - startY.current;
      const dt = Date.now() - startT.current;

      // Tap rápido sem deslocamento significativo
      if (!moved.current && dt < 280 && Math.abs(dx) < 8 && Math.abs(dy) < 8) {
        onTap?.();
        return;
      }

      // Swipe horizontal (predominante sobre vertical)
      // Increased ratio from 1.5 to 2.5 to be more strict
      if (Math.abs(dx) > threshold && Math.abs(dx) > Math.abs(dy) * ratio) {
        telemetry.log("Valid Swipe Triggered", "info", { dx, dy, threshold });
        if (dx < 0) onSwipeLeft?.();
        else onSwipeRight?.();
      } else if (Math.abs(dx) > 0 || Math.abs(dy) > 0) {
        telemetry.log("Swipe Below Threshold or Ratio", "warn", { dx, dy, threshold });
        window.dispatchEvent(
          new CustomEvent("nav-blocked", {
            detail: { reason: "threshold_not_met", dx, dy, threshold },
          }),
        );
      }
    };

    const onKeyDown = (e: KeyboardEvent) => {
      // Navegação por setas (acessibilidade e conveniência desktop)
      if (e.key === "ArrowLeft") {
        onSwipeRight?.();
        onTap?.(); // Revela a UI brevemente como feedback visual
      }
      if (e.key === "ArrowRight") {
        onSwipeLeft?.();
        onTap?.(); // Revela a UI brevemente como feedback visual
      }
      // Espaço ou Enter para revelar a UI no modo contemplativo
      if (e.key === " " || e.key === "Enter") {
        if (
          document.activeElement?.tagName === "BODY" ||
          document.activeElement?.tagName === "DIV"
        ) {
          onTap?.();
        }
      }
    };

    window.addEventListener("touchstart", onStart, { passive: true });
    window.addEventListener("touchmove", onMove, { passive: true });
    window.addEventListener("touchend", onEnd, { passive: true });
    window.addEventListener("keydown", onKeyDown);

    return () => {
      window.removeEventListener("touchstart", onStart);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onEnd);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [enabled, threshold, onSwipeLeft, onSwipeRight, onTap]);
}

/**
 * useWakeLock — mantém a tela acordada durante a celebração.
 * Fallback silencioso quando a API não é suportada.
 */
import { useCallback, useEffect, useRef, useState } from "react";

type WakeLockSentinel = {
  released: boolean;
  release: () => Promise<void>;
  addEventListener: (t: string, cb: () => void) => void;
};

export function useWakeLock(active: boolean) {
  const sentinelRef = useRef<WakeLockSentinel | null>(null);
  const [supported, setSupported] = useState(false);
  const [engaged, setEngaged] = useState(false);

  useEffect(() => {
    setSupported(typeof navigator !== "undefined" && "wakeLock" in navigator);
  }, []);

  const request = useCallback(async () => {
    try {
      // @ts-ignore experimental API
      const s = await navigator.wakeLock?.request("screen");
      if (s) {
        sentinelRef.current = s;
        setEngaged(true);
        s.addEventListener?.("release", () => setEngaged(false));
      }
    } catch {
      setEngaged(false);
    }
  }, []);

  const release = useCallback(async () => {
    try {
      await sentinelRef.current?.release();
    } catch {}
    sentinelRef.current = null;
    setEngaged(false);
  }, []);

  useEffect(() => {
    if (!supported) return;
    if (active) {
      request();
      const onVis = () => {
        if (document.visibilityState === "visible" && active) request();
      };
      document.addEventListener("visibilitychange", onVis);
      return () => {
        document.removeEventListener("visibilitychange", onVis);
        release();
      };
    } else {
      release();
    }
  }, [active, supported, request, release]);

  return { supported, engaged };
}

// This file is automatically generated. Do not edit it directly.

// On a Lovable preview surface, broker the auth session to the editor over
// postMessage so the project's preview surfaces share one login; else localStorage.
export function brokeredPreviewStorage() {
  if (typeof window === "undefined") return undefined;
  const host = location.hostname;
  const PREVIEW_ZONES = [
    "lovableproject.com",
    "lovableproject-dev.com",
    "lovable.app",
    "gpt-eng.com",
    "gptengineer.run",
  ];
  const onPreviewZone = PREVIEW_ZONES.some((z) => host === z || host.endsWith("." + z));
  // Read the id only from non-user-controlled host positions, so a user-named
  // preview--<name> host can't smuggle another project's id.
  const UUID = "[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}";
  const projectId = onPreviewZone
    ? (host.match(
        new RegExp("^(?:id-preview(?:-[a-z0-9]+)?|project)--(" + UUID + ")(?:-dev)?(?=\\.|$)", "i"),
      )?.[1] ?? host.match(new RegExp("^(" + UUID + ")(?=[.-])", "i"))?.[1])
    : undefined;
  const framed = window.parent && window.parent !== window;
  if (!projectId || !framed) return localStorage;

  // Post only to the real editor ancestor, validated as a Lovable origin, so the
  // session token can never reach an untrusted embedder.
  const dev = host.endsWith(".lovableproject-dev.com") || host.endsWith(".gpt-eng.com");
  const EDITOR = dev
    ? /^https:\/\/([a-z0-9-]+\.)*(lovable\.dev|gptengineer\.app)$|^http:\/\/localhost:3000$/
    : /^https:\/\/([a-z0-9-]+\.)*(lovable\.dev|gptengineer\.app)$/;
  const ancestor =
    (location.ancestorOrigins && location.ancestorOrigins[0]) ||
    (document.referrer ? new URL(document.referrer).origin : "");
  const editorOrigins =
    ancestor && EDITOR.test(ancestor)
      ? [ancestor]
      : dev
        ? ["https://lovable.dev", "http://localhost:3000"]
        : ["https://lovable.dev"];
  const RESULT = "lovable-preview-auth:result";
  const TIMEOUT = 2000;
  const newId = () => Math.random().toString(36).slice(2) + Date.now().toString(36);

  const request = (
    type: string,
    key: string,
    value?: string,
  ): Promise<{ ok: boolean; value?: string | null } | null> =>
    new Promise((resolve) => {
      const requestId = newId();
      let done = false;
      let timer: ReturnType<typeof setTimeout>;
      const finish = (r: { ok: boolean; value?: string | null } | null) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        window.removeEventListener("message", onMessage);
        resolve(r);
      };
      const onMessage = (e: MessageEvent) => {
        if (editorOrigins.indexOf(e.origin) < 0) return;
        const d = e.data;
        if (d && d.type === RESULT && d.requestId === requestId) finish(d);
      };
      window.addEventListener("message", onMessage);
      const msg: Record<string, unknown> = { type, requestId, projectId, key };
      if (value !== undefined) msg["value"] = value;
      // targetOrigin per trusted editor origin, so a session token never reaches an arbitrary embedder.
      for (const origin of editorOrigins) window.parent.postMessage(msg, origin);
      timer = setTimeout(() => finish(null), TIMEOUT);
    });

  // The editor may not be listening yet at the first getItem, so retry once.
  let firstGet = true;
  const RETRY_DELAY = 250;

  return {
    getItem: async (key: string) => {
      let res = await request("lovable-preview-auth:get", key);
      if (!res && firstGet) {
        await new Promise((r) => setTimeout(r, RETRY_DELAY));
        res = await request("lovable-preview-auth:get", key);
      }
      firstGet = false;
      // '' is the logout tombstone: clear the local copy too so it can't resurrect if
      // the broker later goes silent. A null reply means never-synced -> keep local.
      if (res && res.ok && typeof res.value === "string") {
        if (res.value === "") {
          localStorage.removeItem(key);
          return null;
        }
        return res.value;
      }
      return localStorage.getItem(key);
    },
    setItem: (key: string, value: string) => {
      localStorage.setItem(key, value);
      return request("lovable-preview-auth:set", key, value).then(() => undefined);
    },
    removeItem: (key: string) => {
      localStorage.removeItem(key);
      return request("lovable-preview-auth:remove", key).then(() => undefined);
    },
  };
}

