/**
 * Returns badge IDs that should be awarded but aren't yet.
 */
export function checkNewBadges(currentBadges: string[], ctx: BadgeContext): string[] {
  const current = new Set(currentBadges);
  return BADGE_DEFINITIONS.filter((b) => !current.has(b.id) && b.condition(ctx)).map((b) => b.id);
}

export function getBadgeById(id: string): BadgeDef | undefined {
  return BADGE_DEFINITIONS.find((b) => b.id === id);
}

/**
 * Bible chapter load performance instrumentation.
 *
 * Mede as fases do fluxo de carregamento de capítulo:
 *   cache:check → text → connections → render → progress
 *
 * Cada execução produz uma entrada com durações por fase.
 * Acessível em runtime via `window.__biblePerf` e `window.__biblePerf.print()`.
 */

export type BiblePerfPhase =
  | "cache:check"
  | "cache:hit"
  | "text:start"
  | "text:end"
  | "connections:start"
  | "connections:end"
  | "render"
  | "progress:start"
  | "progress:end"
  | "end";

export interface BiblePerfRun {
  id: string;
  abbr: string;
  chapter: number;
  startedAt: number;
  marks: Partial<Record<BiblePerfPhase, number>>;
  source?: string;
  versesCount?: number;
  connectionsCount?: number;
  cacheHit?: boolean;
  status?: "ok" | "error" | "400" | "404" | "304" | "empty";
}

const MAX_RUNS = 50;
const runs: BiblePerfRun[] = [];

function now(): number {
  return typeof performance !== "undefined" ? performance.now() : Date.now();
}

function ensureGlobal() {
  if (typeof window === "undefined") return;
  const w = window as any;
  if (!w.__biblePerf) {
    w.__biblePerf = {
      runs,
      print: printTable,
      summary: summary,
      clear: () => {
        runs.length = 0;
      },
    };
  }
}

export function start(id: string, abbr: string, chapter: number): BiblePerfRun {
  ensureGlobal();
  const run: BiblePerfRun = {
    id,
    abbr,
    chapter,
    startedAt: now(),
    marks: {},
  };
  runs.unshift(run);
  if (runs.length > MAX_RUNS) runs.length = MAX_RUNS;
  try {
    performance.mark?.(`bible:${id}:start`);
  } catch {}
  return run;
}

export function mark(id: string, phase: BiblePerfPhase) {
  const run = runs.find((r) => r.id === id);
  if (!run) return;
  run.marks[phase] = now() - run.startedAt;
  try {
    performance.mark?.(`bible:${id}:${phase}`);
  } catch {}
}

export function end(id: string, patch?: Partial<BiblePerfRun>) {
  const run = runs.find((r) => r.id === id);
  if (!run) return;
  run.marks.end = now() - run.startedAt;
  if (patch) Object.assign(run, patch);
  logRun(run);
}

function durationsOf(run: BiblePerfRun) {
  const m = run.marks;
  const v = (a?: number, b?: number) =>
    typeof a === "number" && typeof b === "number" ? Math.round(b - a) : undefined;
  return {
    cache_ms: v(0, m["cache:check"]),
    text_ms: v(m["text:start"], m["text:end"]),
    connections_ms: v(m["connections:start"], m["connections:end"]),
    render_ms: v(m["text:end"], m.render),
    progress_ms: v(m["progress:start"], m["progress:end"]),
    total_ms: Math.round(m.end ?? 0),
  };
}

function logRun(run: BiblePerfRun) {
  const d = durationsOf(run);
  // Pretty console group for the run.
  /* eslint-disable no-console */
  const label = `🕮 Bible perf · ${run.abbr} ${run.chapter} · ${d.total_ms}ms${run.cacheHit ? " (cache)" : ""}`;
  try {
    console.groupCollapsed(label);
    console.table({
      "Capítulo (total)": { ms: d.total_ms ?? "—" },
      "Cache check": { ms: d.cache_ms ?? "—" },
      "Busca texto": { ms: d.text_ms ?? "—" },
      "Busca conexões": { ms: d.connections_ms ?? "—" },
      Renderiza: { ms: d.render_ms ?? "—" },
      "Salva progresso": { ms: d.progress_ms ?? "—" },
    });
    console.log(
      "Status:",
      run.status,
      "· Source:",
      run.source,
      "· Versículos:",
      run.versesCount,
      "· Conexões:",
      run.connectionsCount,
    );
    console.groupEnd();
  } catch {
    console.log(label, d);
  }
  /* eslint-enable no-console */
}

export function printTable() {
  /* eslint-disable no-console */
  const rows = runs.map((r) => ({
    livro: `${r.abbr} ${r.chapter}`,
    status: r.status ?? "—",
    ...durationsOf(r),
    source: r.source ?? "—",
  }));
  console.table(rows);
  /* eslint-enable no-console */
  return rows;
}

export function summary() {
  const completed = runs.filter((r) => r.marks.end != null);
  if (!completed.length) return { count: 0 };
  const ds = completed.map(durationsOf);
  const avg = (k: keyof ReturnType<typeof durationsOf>) => {
    const vals = ds.map((d) => d[k]).filter((v): v is number => typeof v === "number");
    return vals.length ? Math.round(vals.reduce((s, v) => s + v, 0) / vals.length) : 0;
  };
  return {
    count: completed.length,
    avg_total_ms: avg("total_ms"),
    avg_text_ms: avg("text_ms"),
    avg_connections_ms: avg("connections_ms"),
    avg_render_ms: avg("render_ms"),
    avg_progress_ms: avg("progress_ms"),
    cache_hit_rate: Math.round(
      (completed.filter((r) => r.cacheHit).length / completed.length) * 100,
    ),
  };
}

export function getRuns(): BiblePerfRun[] {
  return runs.slice();
}

export function getDurations(run: BiblePerfRun) {
  return durationsOf(run);
}

export const biblePerf = { start, mark, end, printTable, summary, getRuns, getDurations };
export default biblePerf;

/**
 * Bible Recovery Mode — automated checker.
 *
 * Abre o capítulo 1 de cada livro do cânone, valida idioma, ausência
 * de capítulos vazios e tempo de abertura. Pode ser usado pelo painel
 * de diagnóstico e por um teste automatizado de regressão.
 */
import { supabase } from "@/lib/db";
import { BIBLE_DATA, type BibleBook } from "@/data/bible-books";
import { FORBIDDEN_ENGLISH_WORDS } from "@/constants/language-config";
import {
  bibleRecoveryStore,
  inspectChapterResult,
  reportNavigationError,
} from "./bibleRecoveryStore";

export interface ValidationRow {
  book: string;
  abbr: string;
  chapter: number;
  language: "Português" | "Inglês" | "Desconhecido";
  openMs: number;
  result: "OK" | "VAZIO" | "INGLÊS" | "LENTO" | "ERRO";
  evidence?: string;
}

const FORBIDDEN_RX = new RegExp(
  `\\b(${FORBIDDEN_ENGLISH_WORDS.join("|")}|Tobit|Judith|Wisdom|Sirach|Baruch|Maccabees)\\b`,
  "i",
);

const SLOW_MS = 1500;

export function getAllBooks(): BibleBook[] {
  return Object.values(BIBLE_DATA)
    .flat()
    .flatMap((cat) => cat.books);
}

export async function checkBookChapter(book: BibleBook, chapter = 1): Promise<ValidationRow> {
  const t0 = performance.now();
  try {
    const { data, error } = await supabase.functions.invoke("bible-text", {
      body: { abbrev: book.abbr, chapter },
    });
    const openMs = Math.round(performance.now() - t0);

    if (error || !data) {
      reportNavigationError(book.name, chapter, error || "sem resposta");
      return {
        book: book.name,
        abbr: book.abbr,
        chapter,
        language: "Desconhecido",
        openMs,
        result: "ERRO",
      };
    }

    const verses = (data as any).verses as Array<{ number: number; text: string }> | undefined;
    inspectChapterResult(book.name, chapter, verses);

    if (!verses || verses.length === 0) {
      return {
        book: book.name,
        abbr: book.abbr,
        chapter,
        language: "Desconhecido",
        openMs,
        result: "VAZIO",
      };
    }

    const sample = verses
      .map((v) => v.text)
      .join(" ")
      .slice(0, 600);
    const enHit = FORBIDDEN_RX.exec(sample);
    if (enHit) {
      return {
        book: book.name,
        abbr: book.abbr,
        chapter,
        language: "Inglês",
        openMs,
        result: "INGLÊS",
        evidence: enHit[0],
      };
    }

    return {
      book: book.name,
      abbr: book.abbr,
      chapter,
      language: "Português",
      openMs,
      result: openMs > SLOW_MS ? "LENTO" : "OK",
    };
  } catch (e) {
    const openMs = Math.round(performance.now() - t0);
    reportNavigationError(book.name, chapter, e);
    return {
      book: book.name,
      abbr: book.abbr,
      chapter,
      language: "Desconhecido",
      openMs,
      result: "ERRO",
    };
  }
}

export async function runRecoveryCheck(
  onProgress?: (done: number, total: number, row: ValidationRow) => void,
): Promise<ValidationRow[]> {
  bibleRecoveryStore.clear();
  const books = getAllBooks();
  const rows: ValidationRow[] = [];
  const CONCURRENCY = 4;
  let i = 0;

  async function worker() {
    while (i < books.length) {
      const idx = i++;
      const row = await checkBookChapter(books[idx], 1);
      rows.push(row);
      onProgress?.(rows.length, books.length, row);
    }
  }

  await Promise.all(Array.from({ length: CONCURRENCY }, worker));
  // sort canonically by original order
  const order = new Map(books.map((b, idx) => [b.abbr, idx]));
  rows.sort((a, b) => order.get(a.abbr)! - order.get(b.abbr)!);
  return rows;
}

export function summarize(rows: ValidationRow[]) {
  return {
    total: rows.length,
    ok: rows.filter((r) => r.result === "OK").length,
    empty: rows.filter((r) => r.result === "VAZIO").length,
    english: rows.filter((r) => r.result === "INGLÊS").length,
    slow: rows.filter((r) => r.result === "LENTO").length,
    error: rows.filter((r) => r.result === "ERRO").length,
    avgMs: rows.length ? Math.round(rows.reduce((s, r) => s + r.openMs, 0) / rows.length) : 0,
  };
}

/**
 * Catechism Diagnostics
 * Logging detalhado e telemetria leve (client-side) para falhas de
 * carregamento de parágrafos do Catecismo.
 *
 * - Mantém um buffer circular dos últimos eventos em memória.
 * - Persiste os últimos 50 erros em localStorage (`cathedra_catechism_diag`).
 * - Dispara `CustomEvent('catechism-diagnostic')` para o painel de diagnóstico
 *   reagir em tempo real.
 * - Envia eventos para `analytics_events` quando possível (best-effort, silencioso).
 */
import { supabase } from "@/lib/db";

export type CatechismDiagStep =
  | "cache_hit"
  | "official_query"
  | "official_hit"
  | "official_error"
  | "local_hit"
  | "edge_invoke"
  | "edge_hit"
  | "edge_not_found"
  | "edge_error"
  | "fallback_cached"
  | "unauthorized"
  | "forbidden"
  | "final_error";

export interface CatechismDiagEvent {
  ts: number;
  paragraph: number;
  step: CatechismDiagStep;
  status?: number | string;
  message?: string;
  route?: string;
  meta?: Record<string, unknown>;
}

const STORAGE_KEY = "cathedra_catechism_diag";
const TIMELINE_KEY = "cathedra_catechism_diag_timeline";
const MAX_PERSISTED = 50;
const MAX_BUFFER = 200;
const PERSIST_DEBOUNCE_MS = 400;

/** Reidrata a timeline persistida no boot do módulo (só em browser). */
const rehydrateBuffer = (): CatechismDiagEvent[] => {
  try {
    if (typeof window === "undefined") return [];
    const raw = window.localStorage.getItem(TIMELINE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.slice(0, MAX_BUFFER);
  } catch {
    return [];
  }
};

const buffer: CatechismDiagEvent[] = rehydrateBuffer();

let persistTimer: ReturnType<typeof setTimeout> | null = null;
const schedulePersistTimeline = () => {
  if (typeof window === "undefined") return;
  if (persistTimer) return; // já agendado
  persistTimer = setTimeout(() => {
    persistTimer = null;
    try {
      window.localStorage.setItem(TIMELINE_KEY, JSON.stringify(buffer.slice(0, MAX_BUFFER)));
    } catch {
      /* quota / privacy mode — silencioso */
    }
  }, PERSIST_DEBOUNCE_MS);
};

const isDebug = (): boolean => {
  try {
    if (typeof window === "undefined") return false;
    const params = new URLSearchParams(window.location.search);
    if (params.get("debug") === "1") return true;
    return localStorage.getItem("cathedra_catechism_debug") === "1";
  } catch {
    return false;
  }
};

export const enableCatechismDebug = (on: boolean) => {
  try {
    if (on) localStorage.setItem("cathedra_catechism_debug", "1");
    else localStorage.removeItem("cathedra_catechism_debug");
  } catch {}
};

export const isCatechismDebugOn = (): boolean => isDebug();

const persistError = (ev: CatechismDiagEvent) => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const list: CatechismDiagEvent[] = raw ? JSON.parse(raw) : [];
    list.unshift(ev);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list.slice(0, MAX_PERSISTED)));
  } catch {}
};

const isErrorStep = (step: CatechismDiagStep) =>
  step === "official_error" ||
  step === "edge_error" ||
  step === "edge_not_found" ||
  step === "unauthorized" ||
  step === "forbidden" ||
  step === "final_error";

export const logCatechismDiag = (ev: Omit<CatechismDiagEvent, "ts" | "route">) => {
  const full: CatechismDiagEvent = {
    ...ev,
    ts: Date.now(),
    route:
      typeof window !== "undefined" ? window.location.pathname + window.location.search : undefined,
  };

  buffer.unshift(full);
  if (buffer.length > MAX_BUFFER) buffer.length = MAX_BUFFER;
  schedulePersistTimeline();

  if (isErrorStep(full.step)) {
    persistError(full);
  }

  if (isDebug() || isErrorStep(full.step)) {
    const fn = isErrorStep(full.step) ? console.error : console.info;
    fn(
      "[Catechism][%s] §%s status=%s msg=%s",
      full.step,
      full.paragraph,
      full.status ?? "-",
      full.message ?? "",
    );
  }

  try {
    window.dispatchEvent(new CustomEvent("catechism-diagnostic", { detail: full }));
  } catch {}

  // Best-effort remote telemetry on errors only — never throws.
  if (isErrorStep(full.step)) {
    void sendRemote(full);
  }
};

const sendRemote = async (ev: CatechismDiagEvent) => {
  try {
    const { data: userData } = await supabase.auth.getUser();
    await supabase.from("analytics_events").insert({
      event_name: `catechism.${ev.step}`,
      user_id: userData?.user?.id ?? null,
      metadata: {
        paragraph: ev.paragraph,
        status: ev.status ?? null,
        message: ev.message ?? null,
        route: ev.route ?? null,
        ...(ev.meta ?? {}),
      } as any,
    } as any);
  } catch {
    /* silent */
  }
};

export const getCatechismDiagBuffer = (): CatechismDiagEvent[] => [...buffer];

export const getPersistedCatechismErrors = (): CatechismDiagEvent[] => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
};

export const clearCatechismDiag = () => {
  buffer.length = 0;
  if (persistTimer) {
    clearTimeout(persistTimer);
    persistTimer = null;
  }
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {}
  try {
    localStorage.removeItem(TIMELINE_KEY);
  } catch {}
  try {
    window.dispatchEvent(new CustomEvent("catechism-diagnostic-cleared"));
  } catch {}
};

/** Normaliza erros do Supabase/Edge em um código semântico. */
export const classifyCatechismError = (
  err: any,
): {
  code: "unauthorized" | "forbidden" | "not_found" | "network" | "unknown";
  status?: number;
  message: string;
} => {
  const status: number | undefined = err?.status ?? err?.context?.status ?? err?.response?.status;
  const raw = (err?.message || err?.error_description || String(err || "")).toLowerCase();

  if (status === 401 || raw.includes("jwt") || raw.includes("unauthorized")) {
    return { code: "unauthorized", status, message: "Sessão inválida ou expirada." };
  }
  if (
    status === 403 ||
    raw.includes("forbidden") ||
    raw.includes("permission denied") ||
    raw.includes("row-level security")
  ) {
    return { code: "forbidden", status, message: "Sem permissão para ler este parágrafo." };
  }
  if (
    status === 404 ||
    raw.includes("not_found") ||
    raw.includes("não encontrado") ||
    raw.includes("not found") ||
    raw.includes("não disponível")
  ) {
    return { code: "not_found", status, message: "Parágrafo não encontrado no banco oficial." };
  }
  if (raw.includes("failed to fetch") || raw.includes("network")) {
    return { code: "network", status, message: "Falha de rede ao consultar o servidor." };
  }
  return { code: "unknown", status, message: err?.message || "Erro desconhecido." };
};

/**
 * Utility to ensure consistent usage of Catechism types across the app.
 * Supports both 'catechism' (Nexus/Logic) and 'catecismo' (UI/Portuguese).
 */

export type CatechismType = "catechism" | "catecismo";

/**
 * Normalizes any variation of catechism type to the target format.
 */
export function normalizeCatechismType(type: string): "catechism" {
  const t = type.toLowerCase();
  if (t === "catechism" || t === "catecismo" || t === "cic") {
    return "catechism";
  }
  return t as any;
}

/**
 * Returns the user-facing label for the catechism type.
 */
export function getCatechismLabel(type: string): string {
  const norm = normalizeCatechismType(type);
  return norm === "catechism" ? "Catecismo" : type;
}

/**
 * Validates if a content item is of catechism type.
 */
export function isCatechism(item: { type?: string; tipo?: string }): boolean {
  const type = item.type || item.tipo || "";
  return normalizeCatechismType(type) === "catechism";
}

import { supabase } from "@/lib/db";
import { getContrastRatio, getWCAGLevel } from "./a11y-utils";
import { jsPDF } from "jspdf";
import "jspdf-autotable";

// Type extension for jsPDF to include autoTable
interface jsPDFWithAutoTable extends jsPDF {
  autoTable: (options: any) => jsPDF;
}

export interface ContrastIssue {
  element: string;
  ratio: number;
  expected: number;
  level: string;
  suggestion?: string;
}

export interface AuditResult {
  page: string;
  timestamp: string;
  wcagScore: number;
  typographyErrors: string[];
  gridIssues: string[];
  contrastIssues: ContrastIssue[];
  status: "premium" | "degraded";
}

/**
 * Find the actual background color of an element by traversing up the DOM tree
 * and blending transparent/semi-transparent layers.
 */
const getActualBackgroundColor = (element: HTMLElement): string => {
  let current: HTMLElement | null = element;
  let colors: string[] = [];

  while (current) {
    const style = window.getComputedStyle(current);
    const bg = style.backgroundColor;

    if (bg && bg !== "rgba(0, 0, 0, 0)" && bg !== "transparent") {
      colors.unshift(bg);
      // If the color is fully opaque, we can stop
      if (!bg.includes("rgba") || bg.match(/rgba\(.*,\s*1\)$/)) {
        break;
      }
    }
    current = current.parentElement;
  }

  // If no background found, default to white
  if (colors.length === 0) return "#FFFFFF";

  // Actually we should return the most specific one for now,
  // but a better approach would be blending all of them.
  // For simplicity, let's use the first opaque or semi-transparent background we found.
  return colors[colors.length - 1];
};

/**
 * Validates WCAG AAA and Typography consistency.
 */
export const runDesignSystemAudit = async (pageName: string): Promise<AuditResult> => {
  const typographyErrors: string[] = [];
  const gridIssues: string[] = [];
  const contrastIssues: ContrastIssue[] = [];

  // Get current theme from body or root
  const currentTheme = document.documentElement.classList.contains("dark") ? "dark" : "light";
  const isHighContrast = document.documentElement.classList.contains("high-contrast");

  // 1. Check Typography Tokens
  const elements = document.querySelectorAll("h1, h2, h3, h4, p, span, button");
  const allowedFonts = [
    "Inter",
    "Playfair Display",
    "Cinzel",
    "Merriweather",
    "system-ui",
    "serif",
    "sans-serif",
    "monospace",
    "Courier",
  ];
  const allowedWeights = ["400", "500", "600", "700", "800", "900"];

  elements.forEach((el) => {
    const style = window.getComputedStyle(el);

    // Check Font Family
    const fontFamily = style.fontFamily;
    const isFontAllowed = allowedFonts.some((f) => fontFamily.includes(f));
    if (!isFontAllowed) {
      typographyErrors.push(`Fonte não permitida: "${fontFamily}" em ${el.tagName}`);
    }

    // Check Font Weight
    const fontWeight = style.fontWeight;
    if (!allowedWeights.includes(fontWeight)) {
      typographyErrors.push(`Peso tipográfico irregular: ${fontWeight} em ${el.tagName}`);
    }

    // Check for inline styles that override tokens
    if (
      el instanceof HTMLElement &&
      (el.getAttribute("style")?.includes("font-family") ||
        el.getAttribute("style")?.includes("font-weight"))
    ) {
      typographyErrors.push(`Estilo inline detectado em ${el.tagName} (deve usar tokens)`);
    }
  });

  // 2. Check Grids & Alignment
  const containers = document.querySelectorAll(".container, .grid, .flex-col");
  containers.forEach((container) => {
    const style = window.getComputedStyle(container);
    if (
      container.classList.contains("grid") &&
      !style.gap &&
      !container.classList.value.includes("gap-")
    ) {
      gridIssues.push(`Grid sem espaçamento padronizado (gap) em ${container.tagName}`);
    }
  });

  // 3. Check Contrast for key elements
  const interactiveElements = document.querySelectorAll(
    'button, a, input, [role="button"], p, h1, h2, h3, span',
  );
  interactiveElements.forEach((el) => {
    if (!(el instanceof HTMLElement)) return;

    const style = window.getComputedStyle(el);
    const bg = getActualBackgroundColor(el);
    const fg = style.color;

    // Skip invisible elements
    if (style.display === "none" || style.visibility === "hidden" || style.opacity === "0") return;

    try {
      const ratio = getContrastRatio(fg, bg);
      const level = getWCAGLevel(ratio);
      const minRatio = isHighContrast ? 7 : 4.5;

      if (ratio < minRatio) {
        contrastIssues.push({
          element: `${el.tagName}${el.className ? "." + el.className.split(" ").slice(0, 2).join(".") : ""}`,
          ratio,
          expected: minRatio,
          level,
          suggestion:
            ratio < 3
              ? "Contraste Crítico: Aumentar saturação ou mudar cor."
              : "Ajuste fino necessário para atingir conformidade.",
        });
      }
    } catch (e) {
      // Skip elements with complex background colors or parsing errors
    }
  });

  const result: AuditResult = {
    page: pageName,
    timestamp: new Date().toISOString(),
    wcagScore: Math.max(
      0,
      Math.min(100, 100 - typographyErrors.length * 5 - contrastIssues.length * 10),
    ),
    typographyErrors,
    gridIssues,
    contrastIssues,
    status:
      typographyErrors.length === 0 && gridIssues.length === 0 && contrastIssues.length === 0
        ? "premium"
        : "degraded",
  };

  return result;
};

/**
 * Saves audit result to Supabase
 */
export const saveAuditResult = async (runId: string, result: AuditResult) => {
  const { error } = await supabase.from("visual_regression_snapshots").insert({
    run_id: runId,
    page_name: result.page,
    route: window.location.pathname,
    viewport: `${window.innerWidth}x${window.innerHeight}`,
    status: result.status === "premium" ? "pass" : "fail",
    typography_errors: result.typographyErrors,
    wcag_score: result.wcagScore,
  });

  return !error;
};

/**
 * Generates and downloads a JSON report
 */
export const exportAuditReport = (result: AuditResult, format: "json" | "pdf" = "json") => {
  const currentTheme = document.documentElement.classList.contains("dark") ? "Escuro" : "Claro";
  const isHighContrast = document.documentElement.classList.contains("high-contrast")
    ? "Sim"
    : "Não";

  if (format === "json") {
    const reportData = {
      ...result,
      meta: {
        theme: currentTheme,
        highContrast: isHighContrast,
        browser: navigator.userAgent,
        screenSize: `${window.innerWidth}x${window.innerHeight}`,
      },
    };
    const blob = new Blob([JSON.stringify(reportData, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const downloadAnchorNode = document.createElement("a");
    downloadAnchorNode.setAttribute("href", url);
    downloadAnchorNode.setAttribute(
      "download",
      `cathedra_design_audit_${result.page.replace(/\//g, "_")}_${new Date().getTime()}.json`,
    );
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
    URL.revokeObjectURL(url);
  } else {
    const doc = new jsPDF() as jsPDFWithAutoTable;

    // Add Header
    doc.setFontSize(24);
    doc.setTextColor(181, 139, 58); // Sovereign Gold
    doc.text("Relatório de Conformidade - Cathedra Digital", 20, 25);

    doc.setDrawColor(181, 139, 58);
    doc.line(20, 30, 190, 30);

    doc.setFontSize(10);
    doc.setTextColor(100, 100, 100);
    doc.text(`Gerado em: ${new Date(result.timestamp).toLocaleString()}`, 20, 38);

    // Metadata Section
    doc.setFontSize(14);
    doc.setTextColor(0, 0, 0);
    doc.text("Informações do Ambiente", 20, 50);

    const metaData = [
      ["Página Auditada", result.page],
      ["Tema Ativo", currentTheme],
      ["Alto Contraste", isHighContrast],
      ["Score WCAG", `${result.wcagScore}%`],
      ["Status Geral", result.status.toUpperCase()],
    ];

    doc.autoTable({
      startY: 55,
      body: metaData,
      theme: "plain",
      styles: { fontSize: 10, cellPadding: 2 },
    });

    let currentY = (doc as any).lastAutoTable.finalY + 15;

    // Contrast Issues Detailed
    if (result.contrastIssues.length > 0) {
      doc.setFontSize(16);
      doc.setTextColor(181, 139, 58);
      doc.text("Análise Detalhada de Contraste", 20, currentY);

      const tableData = result.contrastIssues.map((issue) => [
        issue.element,
        issue.ratio.toFixed(2),
        issue.expected.toFixed(2),
        issue.level,
        issue.suggestion || "Revisar tokens de cores.",
      ]);

      doc.autoTable({
        startY: currentY + 5,
        head: [["Componente", "Ratio", "Min", "Nível", "Recomendação"]],
        body: tableData,
        theme: "striped",
        headStyles: { fillColor: [181, 139, 58], textColor: [255, 255, 255] },
        styles: { fontSize: 8 },
      });

      currentY = (doc as any).lastAutoTable.finalY + 15;
    }

    // Recommendations Section
    doc.setFontSize(16);
    doc.setTextColor(181, 139, 58);
    doc.text("Recomendações Técnicas", 20, currentY);

    const recommendations = [];
    if (result.wcagScore < 100) {
      recommendations.push([
        "Contraste",
        "Substituir cores de texto por variantes mais escuras (no modo claro) ou mais claras (no modo escuro) do Design System.",
      ]);
      recommendations.push([
        "Tipografia",
        "Garantir que todos os componentes utilizam a fonte Cinzel para títulos e Inter para corpo de texto.",
      ]);
      recommendations.push([
        "Tokens",
        "Evitar o uso de estilos inline e cores hexadecimais manuais fora do sacredPalette.ts.",
      ]);
    } else {
      recommendations.push([
        "Excelente",
        "O sistema mantém conformidade total com os padrões estabelecidos. Continue utilizando os tokens globais.",
      ]);
    }

    doc.autoTable({
      startY: currentY + 5,
      head: [["Categoria", "Ação Corretiva"]],
      body: recommendations,
      theme: "grid",
      headStyles: { fillColor: [80, 80, 80] },
    });

    doc.save(`cathedra_a11y_detailed_report_${result.page.replace(/\//g, "_")}.pdf`);
  }
};

/**
 * Dev-only DOM inspector.
 * Toggle with Ctrl/Cmd + Shift + I. ESC to exit. L to fixar.
 */

export type FiberSource = { fileName?: string; lineNumber?: number; columnNumber?: number };
export type MatchedRule = {
  selector: string;
  specificity: [number, number, number];
  origin: string;
  originKind: "inline" | "style-tag" | "stylesheet" | "shadow";
  selectorKind: "id" | "class" | "tag" | "mixed";
  cssText: string;
  declarations: Record<string, string>;
};
export type Conflict = {
  prop: string;
  winner: MatchedRule;
  losers: MatchedRule[];
};
export type CssVarUsage = {
  name: string; // --foo
  resolved: string; // computed value
  usedIn: string[]; // CSS props in winners that reference it
  fromSelector: string | null; // selector that defines the var
  fromOrigin: string | null; // origin label
  fromElement: string | null; // tag/path of ancestor providing it
};
export type LogEntry = {
  ts: string;
  route: string;
  component: string | null;
  source: string | null;
  selector: string;
  domPath: string;
  classes: string;
  size: { w: number; h: number };
  viewport: { w: number; h: number; dpr: number; breakpoint: string };
  styles: Record<string, string>;
  matchedRules: MatchedRule[];
  conflicts: Conflict[];
  cssVars: CssVarUsage[];
  outerHTML: string;
  inShadow: boolean;
};
export type Filters = {
  origin: "all" | "inline" | "style-tag" | "stylesheet" | "shadow";
  selectorKind: "all" | "id" | "class" | "tag" | "mixed";
  file: string;
};
export type SessionState = {
  logs: LogEntry[];
  filters: Filters;
  locked: boolean;
};

export const STORAGE_KEY = "cathedra_inspector_session_v1";

export const DEFAULT_FILTERS: Filters = { origin: "all", selectorKind: "all", file: "all" };

export function loadSession(storage: Storage = localStorage): SessionState {
  const fallback: SessionState = { logs: [], filters: { ...DEFAULT_FILTERS }, locked: false };
  try {
    const raw = storage.getItem(STORAGE_KEY);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw);
    return {
      logs: Array.isArray(parsed.logs) ? parsed.logs : [],
      filters: { ...DEFAULT_FILTERS, ...(parsed.filters || {}) },
      locked: !!parsed.locked,
    };
  } catch {
    return fallback;
  }
}

export function saveSession(state: SessionState, storage: Storage = localStorage): void {
  try {
    storage.setItem(
      STORAGE_KEY,
      JSON.stringify({ logs: state.logs.slice(-50), filters: state.filters, locked: state.locked }),
    );
  } catch {
    /* noop */
  }
}

function getFiberFromNode(node: Element): any | null {
  const key = Object.keys(node).find(
    (k) => k.startsWith("__reactFiber$") || k.startsWith("__reactInternalInstance$"),
  );
  return key ? (node as any)[key] : null;
}

function findSource(fiber: any): { source: FiberSource | null; name: string | null } {
  let current = fiber;
  while (current) {
    const src: FiberSource | undefined = current._debugSource;
    const owner = current._debugOwner;
    if (src) {
      const name =
        typeof current.type === "string"
          ? current.type
          : current.type?.displayName || current.type?.name || owner?.type?.name || null;
      return { source: src, name };
    }
    current = current.return;
  }
  return { source: null, name: null };
}

function cssSelector(el: Element): string {
  if (el.id) return `#${CSS.escape(el.id)}`;
  const parts: string[] = [];
  let cur: Element | null = el;
  while (cur && cur.nodeType === 1 && parts.length < 5) {
    let s = cur.tagName.toLowerCase();
    if (cur.id) {
      parts.unshift(`${s}#${CSS.escape(cur.id)}`);
      break;
    }
    if (cur.className && typeof cur.className === "string") {
      const cls = cur.className
        .trim()
        .split(/\s+/)
        .slice(0, 2)
        .map((c) => CSS.escape(c))
        .join(".");
      if (cls) s += "." + cls;
    }
    const parent = cur.parentElement;
    if (parent) {
      const idx = Array.from(parent.children).indexOf(cur) + 1;
      s += `:nth-child(${idx})`;
    }
    parts.unshift(s);
    cur = cur.parentElement;
  }
  return parts.join(" > ");
}

/**
 * DOM path with Shadow DOM awareness — when we cross a ShadowRoot boundary we
 * mark it as `::shadow` and continue from the shadow host.
 */
export function domPath(el: Element): string {
  const parts: string[] = [];
  let cur: Node | null = el;
  let safety = 0;
  while (cur && cur.nodeType === 1 && safety++ < 20) {
    const e = cur as Element;
    let s = e.tagName.toLowerCase();
    if (e.id) s += `#${e.id}`;
    else if (e.className && typeof e.className === "string")
      s += "." + e.className.trim().split(/\s+/).slice(0, 2).join(".");
    parts.unshift(s);
    if (e.parentElement) {
      cur = e.parentElement;
    } else {
      const root = e.getRootNode();
      if (root instanceof ShadowRoot) {
        parts.unshift("::shadow");
        cur = root.host;
      } else {
        cur = null;
      }
    }
  }
  return parts.join(" > ");
}

function pickStyles(el: Element): Record<string, string> {
  const cs = window.getComputedStyle(el);
  const keys = [
    "font-family",
    "font-size",
    "font-weight",
    "line-height",
    "letter-spacing",
    "color",
    "padding",
    "margin",
    "text-transform",
    "border-top-width",
    "border-top-style",
    "border-top-color",
  ];
  const out: Record<string, string> = {};
  for (const k of keys) out[k] = cs.getPropertyValue(k).trim();
  return out;
}

/** Scans matched-rule cssText for var(--x) refs and walks ancestors to find the declarer. */
export function extractCssVars(el: Element, rules: MatchedRule[]): CssVarUsage[] {
  const usage = new Map<string, Set<string>>(); // varName -> set of props using it
  const re = /var\(\s*(--[\w-]+)/g;
  for (const r of rules) {
    for (const [prop, val] of Object.entries(r.declarations)) {
      let m: RegExpExecArray | null;
      const local = new RegExp(re.source, "g");
      while ((m = local.exec(val))) {
        if (!usage.has(m[1])) usage.set(m[1], new Set());
        usage.get(m[1])!.add(prop);
      }
    }
  }
  if (!usage.size) return [];
  const out: CssVarUsage[] = [];
  for (const [name, props] of usage) {
    const resolved = window.getComputedStyle(el).getPropertyValue(name).trim();
    let fromSelector: string | null = null;
    let fromOrigin: string | null = null;
    let fromElement: string | null = null;
    // Walk ancestors (including el) looking for a matched rule that declares the var
    let cur: Element | null = el;
    outer: while (cur) {
      const ruleSet = getMatchedRules(cur);
      for (const r of ruleSet) {
        if (name in r.declarations) {
          fromSelector = r.selector;
          fromOrigin = r.origin;
          fromElement =
            cur.tagName.toLowerCase() +
            (cur.id
              ? `#${cur.id}`
              : cur.className && typeof cur.className === "string"
                ? "." + cur.className.trim().split(/\s+/)[0]
                : "");
          break outer;
        }
      }
      cur = cur.parentElement;
    }
    if (!fromSelector) {
      // Fallback: :root via documentElement computed style
      const rootVal = window
        .getComputedStyle(document.documentElement)
        .getPropertyValue(name)
        .trim();
      if (rootVal) {
        fromSelector = ":root";
        fromOrigin = "computed";
        fromElement = "html";
      }
    }
    out.push({ name, resolved, usedIn: Array.from(props), fromSelector, fromOrigin, fromElement });
  }
  return out.sort((a, b) => a.name.localeCompare(b.name));
}

function specificity(selector: string): [number, number, number] {
  const s = selector.replace(/\/\*.*?\*\//g, "").trim();
  const ids = (s.match(/#[\w-]+/g) || []).length;
  const classes = (s.match(/\.[\w-]+/g) || []).length;
  const attrs = (s.match(/\[[^\]]+\]/g) || []).length;
  const pseudoClasses = (s.match(/:(?!:)[\w-]+(\([^)]*\))?/g) || []).length;
  const pseudoElements = (s.match(/::[\w-]+/g) || []).length;
  const tags = (s.match(/(^|[\s>+~])([a-zA-Z][\w-]*)/g) || []).length;
  return [ids, classes + attrs + pseudoClasses, tags + pseudoElements];
}

function classifySelector(sel: string): "id" | "class" | "tag" | "mixed" {
  const hasId = /#[\w-]+/.test(sel);
  const hasClass = /\.[\w-]+/.test(sel);
  const hasTag = /(^|[\s>+~])[a-zA-Z]/.test(sel);
  const types = [hasId, hasClass, hasTag].filter(Boolean).length;
  if (types > 1) return "mixed";
  if (hasId) return "id";
  if (hasClass) return "class";
  return "tag";
}

function ruleOrigin(
  sheet: CSSStyleSheet,
  fromShadow: boolean,
): { label: string; kind: MatchedRule["originKind"] } {
  if (fromShadow) return { label: "shadow-root", kind: "shadow" };
  if (sheet.href) {
    try {
      return {
        label: new URL(sheet.href).pathname.split("/").pop() || sheet.href,
        kind: "stylesheet",
      };
    } catch {
      return { label: sheet.href, kind: "stylesheet" };
    }
  }
  return { label: "<style>", kind: "style-tag" };
}

function parseDeclarations(cssText: string): Record<string, string> {
  const out: Record<string, string> = {};
  cssText.split(";").forEach((d) => {
    const idx = d.indexOf(":");
    if (idx === -1) return;
    const k = d.slice(0, idx).trim();
    const v = d.slice(idx + 1).trim();
    if (k) out[k] = v;
  });
  return out;
}

function collectSheetsFor(el: Element): Array<{ sheet: CSSStyleSheet; fromShadow: boolean }> {
  const sheets: Array<{ sheet: CSSStyleSheet; fromShadow: boolean }> = [];
  for (const s of Array.from(document.styleSheets) as CSSStyleSheet[])
    sheets.push({ sheet: s, fromShadow: false });
  const root = el.getRootNode();
  if (root instanceof ShadowRoot) {
    for (const s of Array.from(root.styleSheets) as CSSStyleSheet[])
      sheets.push({ sheet: s, fromShadow: true });
    // adoptedStyleSheets (Constructable)
    const adopted = (root as any).adoptedStyleSheets as CSSStyleSheet[] | undefined;
    if (Array.isArray(adopted))
      for (const s of adopted) sheets.push({ sheet: s, fromShadow: true });
  }
  return sheets;
}

function getMatchedRules(el: Element): MatchedRule[] {
  const out: MatchedRule[] = [];
  const inline = (el as HTMLElement).style?.cssText;
  if (inline) {
    out.push({
      selector: 'style="..."',
      specificity: [1, 0, 0],
      origin: "inline",
      originKind: "inline",
      selectorKind: "id",
      cssText: inline,
      declarations: parseDeclarations(inline),
    });
  }
  for (const { sheet, fromShadow } of collectSheetsFor(el)) {
    let rules: CSSRuleList | null = null;
    try {
      rules = sheet.cssRules;
    } catch {
      continue;
    }
    if (!rules) continue;
    walkRules(rules, sheet, el, out, fromShadow);
    if (out.length > 300) break;
  }
  out.sort((a, b) => {
    for (let i = 0; i < 3; i++)
      if (b.specificity[i] !== a.specificity[i]) return b.specificity[i] - a.specificity[i];
    return 0;
  });
  return out.slice(0, 80);
}

function walkRules(
  rules: CSSRuleList,
  sheet: CSSStyleSheet,
  el: Element,
  out: MatchedRule[],
  fromShadow: boolean,
) {
  const origin = ruleOrigin(sheet, fromShadow);
  for (const rule of Array.from(rules)) {
    if (rule instanceof CSSStyleRule) {
      const selectorText = rule.selectorText;
      for (const sel of selectorText.split(",").map((s) => s.trim())) {
        const cleaned = sel.replace(/::[\w-]+$/, "").trim() || "*";
        try {
          if (el.matches(cleaned)) {
            out.push({
              selector: sel,
              specificity: specificity(sel),
              origin: origin.label,
              originKind: origin.kind,
              selectorKind: classifySelector(sel),
              cssText: rule.style.cssText,
              declarations: parseDeclarations(rule.style.cssText),
            });
            break;
          }
        } catch {
          /* invalid selector */
        }
      }
    } else if ((rule as CSSGroupingRule).cssRules) {
      walkRules((rule as CSSGroupingRule).cssRules, sheet, el, out, fromShadow);
    }
  }
}

function detectConflicts(rules: MatchedRule[]): Conflict[] {
  const props = [
    "font-size",
    "line-height",
    "padding",
    "padding-top",
    "padding-right",
    "padding-bottom",
    "padding-left",
    "margin",
    "color",
    "font-weight",
    "font-family",
  ];
  const conflicts: Conflict[] = [];
  for (const prop of props) {
    const declarers = rules.filter((r) => prop in r.declarations);
    if (declarers.length < 2) continue;
    const uniqueValues = new Set(declarers.map((r) => r.declarations[prop]));
    if (uniqueValues.size < 2) continue;
    conflicts.push({ prop, winner: declarers[0], losers: declarers.slice(1) });
  }
  return conflicts;
}

function getViewportInfo() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  const bp =
    w < 640 ? "xs" : w < 768 ? "sm" : w < 1024 ? "md" : w < 1280 ? "lg" : w < 1536 ? "xl" : "2xl";
  return { w, h, dpr: window.devicePixelRatio || 1, breakpoint: bp };
}

/** Pierces shadow boundaries using composedPath() to find deepest element under the pointer. */
function elementFromEvent(e: MouseEvent): Element | null {
  const path = (e.composedPath?.() ?? []) as EventTarget[];
  for (const t of path) {
    if (t instanceof Element) return t;
  }
  return document.elementFromPoint(e.clientX, e.clientY);
}

export function initDevInspector() {
  if (typeof window === "undefined") return;

  const saved = loadSession();
  const logs: LogEntry[] = saved.logs;
  const filters: Filters = saved.filters;
  let locked = saved.locked;
  let lockedEntry: LogEntry | null = logs.length && locked ? logs[logs.length - 1] : null;
  let lockedEl: Element | null = null;

  let active = false;
  let highlight: HTMLDivElement | null = null;
  let hoverLabel: HTMLDivElement | null = null;
  let panel: HTMLDivElement | null = null;

  // Compare mode
  let compareMode = false;
  let compareA: { entry: LogEntry; el: Element } | null = null;
  let compareB: { entry: LogEntry; el: Element } | null = null;

  // Winners panel UI state (search + category)
  type WinnerCat = "all" | "typography" | "cssvars" | "color" | "border";
  let winnersQuery = "";
  let winnersCategory: WinnerCat = "all";

  function categoryOf(prop: string): Exclude<WinnerCat, "all" | "cssvars"> | "other" {
    if (/^(font|line-height|letter-spacing|text-|white-space|word-|writing-)/.test(prop))
      return "typography";
    if (/(^color$|background|fill|stroke|caret-color|accent-color)/.test(prop)) return "color";
    if (/^(border|outline|box-shadow|border-radius)/.test(prop)) return "border";
    return "other";
  }

  function computeWinners(rules: MatchedRule[]) {
    const seen = new Set<string>();
    const winners: Array<{
      prop: string;
      value: string;
      selector: string;
      origin: string;
      cat: ReturnType<typeof categoryOf>;
    }> = [];
    for (const r of rules) {
      for (const prop of Object.keys(r.declarations)) {
        if (seen.has(prop)) continue;
        seen.add(prop);
        winners.push({
          prop,
          value: r.declarations[prop],
          selector: r.selector,
          origin: r.origin,
          cat: categoryOf(prop),
        });
      }
    }
    return winners;
  }

  function persist() {
    saveSession({ logs, filters, locked });
  }

  function ensureOverlay() {
    if (highlight) return;
    highlight = document.createElement("div");
    Object.assign(highlight.style, {
      position: "fixed",
      pointerEvents: "none",
      zIndex: "2147483645",
      border: "2px solid #C8A96A",
      background: "rgba(200,169,106,0.10)",
      borderRadius: "3px",
      transition: "all 60ms linear",
      display: "none",
      boxShadow: "0 0 0 1px rgba(11,31,58,0.6)",
    } as CSSStyleDeclaration);
    hoverLabel = document.createElement("div");
    Object.assign(hoverLabel.style, {
      position: "fixed",
      pointerEvents: "none",
      zIndex: "2147483646",
      background: "#0B1F3A",
      color: "#fff",
      font: "11px/1.4 ui-monospace,monospace",
      padding: "3px 7px",
      borderRadius: "3px",
      whiteSpace: "nowrap",
      display: "none",
      boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
    } as CSSStyleDeclaration);
    document.body.appendChild(highlight);
    document.body.appendChild(hoverLabel);
  }

  function hideHover() {
    if (highlight) highlight.style.display = "none";
    if (hoverLabel) hoverLabel.style.display = "none";
  }

  function moveHighlight(el: Element) {
    ensureOverlay();
    const r = el.getBoundingClientRect();
    highlight!.style.display = "block";
    highlight!.style.left = `${r.left}px`;
    highlight!.style.top = `${r.top}px`;
    highlight!.style.width = `${r.width}px`;
    highlight!.style.height = `${r.height}px`;
    highlight!.style.borderColor = locked ? "#ef4444" : compareMode ? "#3b82f6" : "#C8A96A";
    hoverLabel!.style.display = "block";
    const tag = el.tagName.toLowerCase();
    const prefix = locked ? "🔒 " : compareMode ? `⇄ ${compareA ? "B" : "A"} · ` : "";
    hoverLabel!.textContent = `${prefix}${tag} · ${Math.round(r.width)}×${Math.round(r.height)}`;
    const top = r.top - 22 < 4 ? r.bottom + 4 : r.top - 22;
    hoverLabel!.style.left = `${Math.max(4, r.left)}px`;
    hoverLabel!.style.top = `${top}px`;
  }

  function onMove(e: MouseEvent) {
    if (!active) return;
    if (locked && lockedEl) {
      moveHighlight(lockedEl);
      return;
    }
    const el = elementFromEvent(e);
    if (!el || el === highlight || el === hoverLabel || (panel && panel.contains(el))) return;
    moveHighlight(el);
  }

  function buildEntry(el: Element): LogEntry {
    const fiber = getFiberFromNode(el);
    const { source, name } = fiber ? findSource(fiber) : { source: null, name: null };
    const r = el.getBoundingClientRect();
    const srcStr = source
      ? `src/${source.fileName?.split("/src/").pop() ?? source.fileName}:${source.lineNumber}:${source.columnNumber ?? 0}`
      : null;
    const matchedRules = getMatchedRules(el);
    return {
      ts: new Date().toISOString(),
      route: window.location.pathname,
      component: name,
      source: srcStr,
      selector: cssSelector(el),
      domPath: domPath(el),
      classes: (el.getAttribute("class") || "").trim(),
      size: { w: Math.round(r.width), h: Math.round(r.height) },
      viewport: getViewportInfo(),
      styles: pickStyles(el),
      matchedRules,
      conflicts: detectConflicts(matchedRules),
      cssVars: extractCssVars(el, matchedRules),
      outerHTML: el.outerHTML.slice(0, 50000),
      inShadow: el.getRootNode() instanceof ShadowRoot,
    };
  }

  function applyFilters(rules: MatchedRule[]): MatchedRule[] {
    return rules.filter((r) => {
      if (filters.origin !== "all" && r.originKind !== filters.origin) return false;
      if (filters.selectorKind !== "all" && r.selectorKind !== filters.selectorKind) return false;
      if (filters.file !== "all" && r.origin !== filters.file) return false;
      return true;
    });
  }

  function ensurePanel() {
    if (panel) return;
    panel = document.createElement("div");
    Object.assign(panel.style, {
      position: "fixed",
      right: "12px",
      top: "12px",
      width: "440px",
      maxHeight: "calc(100vh - 24px)",
      overflow: "auto",
      zIndex: "2147483647",
      background: "#0B1F3A",
      color: "#fff",
      font: "12px/1.45 ui-monospace,SFMono-Regular,monospace",
      padding: "12px 14px",
      borderRadius: "8px",
      boxShadow: "0 12px 40px rgba(0,0,0,0.45)",
      border: "1px solid rgba(200,169,106,0.4)",
    } as CSSStyleDeclaration);
    document.body.appendChild(panel);
  }

  function renderPanel(entry: LogEntry, el: Element) {
    ensurePanel();
    const filteredRules = applyFilters(entry.matchedRules);
    const files = Array.from(new Set(entry.matchedRules.map((r) => r.origin)));
    const stylesRows = Object.entries(entry.styles)
      .map(
        ([k, v]) =>
          `<tr><td style="opacity:.6;padding-right:8px">${k}</td><td>${escapeHtml(v)}</td></tr>`,
      )
      .join("");
    const conflictsBlock = entry.conflicts.length
      ? entry.conflicts
          .map(
            (c) => `
        <div style="margin-top:6px;padding:6px 8px;background:rgba(239,68,68,0.10);border-left:2px solid #ef4444;border-radius:0 4px 4px 0">
          <div style="font-size:11px;color:#fca5a5"><strong>${escapeHtml(c.prop)}</strong> · ${c.losers.length + 1} regras conflitantes</div>
          <div style="margin-top:4px;font-size:11px"><span style="color:#86efac">✓ winner</span> <code style="color:#C8A96A">${escapeHtml(c.winner.selector)}</code> → ${escapeHtml(c.winner.declarations[c.prop])} <span style="opacity:.6">(${escapeHtml(c.winner.origin)})</span></div>
          ${c.losers.map((l) => `<div style="font-size:11px;opacity:.75"><span style="color:#fca5a5">✗ loser</span> <code>${escapeHtml(l.selector)}</code> → ${escapeHtml(l.declarations[c.prop])} <span style="opacity:.6">(${escapeHtml(l.origin)})</span></div>`).join("")}
        </div>`,
          )
          .join("")
      : '<div style="opacity:.5;font-size:11px">Nenhum conflito detectado nas propriedades comuns.</div>';

    const cascadeRows = filteredRules.length
      ? filteredRules
          .map(
            (r, i) => `
          <div style="margin-top:6px;padding:6px 8px;border-left:2px solid #C8A96A;background:rgba(255,255,255,0.04);border-radius:0 4px 4px 0">
            <div style="display:flex;justify-content:space-between;gap:8px;font-size:10px;opacity:.7">
              <span>#${i + 1} · spec ${r.specificity.join(",")} · ${r.originKind} · ${r.selectorKind}</span>
              <span>${escapeHtml(r.origin)}</span>
            </div>
            <div style="color:#C8A96A;word-break:break-all">${escapeHtml(r.selector)}</div>
            <div style="opacity:.85;word-break:break-all;font-size:11px">${escapeHtml(r.cssText)}</div>
          </div>`,
          )
          .join("")
      : '<div style="opacity:.5;font-size:11px">Nenhuma regra com os filtros atuais.</div>';

    const vp = entry.viewport;
    const sel = (val: string, opts: string[], key: string) =>
      `<select data-filter="${key}" style="background:#0B1F3A;color:#fff;border:1px solid rgba(200,169,106,0.4);border-radius:4px;padding:2px 4px;font:10px ui-monospace,monospace">${opts.map((o) => `<option ${o === val ? "selected" : ""} value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join("")}</select>`;

    panel!.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px">
        <strong style="color:#C8A96A;font-size:11px;letter-spacing:.15em;text-transform:uppercase">Inspector ${locked ? "🔒" : ""}${entry.inShadow ? " · shadow" : ""}</strong>
        <div style="display:flex;gap:4px;flex-wrap:wrap">
          <button data-act="lock" style="${btn()}">${locked ? "Desafixar" : "Fixar"}</button>
          <button data-act="compare" style="${btn()}">${compareMode ? "Sair cmp" : "Comparar"}</button>
          <button data-act="package" style="${btn(true)}" title="P">📎 Pacote</button>
          <button data-act="copy" style="${btn()}">Copiar</button>
          <button data-act="html" style="${btn()}">HTML</button>
          <button data-act="winners" style="${btn()}">Winners</button>
          <button data-act="cascade" style="${btn()}" title="Cascata completa">Cascade</button>
          <button data-act="export" style="${btn()}">NDJSON</button>
          <button data-act="clear" style="${btn()}">Limpar</button>
          <button data-act="close" style="${btn()}">×</button>
        </div>
      </div>
      <div style="font-size:11px;opacity:.6">${escapeHtml(entry.route)} · elem ${entry.size.w}×${entry.size.h}px · vp ${vp.w}×${vp.h} · ${vp.breakpoint} · dpr ${vp.dpr}</div>

      <div style="margin-top:6px;padding:5px 7px;background:rgba(200,169,106,0.08);border:1px dashed rgba(200,169,106,0.35);border-radius:4px;font-size:10px;opacity:.9;display:flex;gap:8px;flex-wrap:wrap">
        <span><kbd style="${kbd()}">F</kbd> Fixar</span>
        <span><kbd style="${kbd()}">C</kbd> Comparar</span>
        <span><kbd style="${kbd()}">P</kbd> Pacote</span>
        <span><kbd style="${kbd()}">Esc</kbd> Sair / cancelar Comparar</span>
        <span style="opacity:.7"><kbd style="${kbd()}">Ctrl/Cmd</kbd>+<kbd style="${kbd()}">Shift</kbd>+<kbd style="${kbd()}">I</kbd> liga/desliga</span>
      </div>

      <div style="margin-top:8px"><span style="color:#C8A96A">${escapeHtml(entry.component || el.tagName.toLowerCase())}</span></div>
      ${entry.source ? `<div style="opacity:.85;margin-top:2px">${escapeHtml(entry.source)}</div>` : '<div style="opacity:.5;margin-top:2px">sem _debugSource</div>'}
      <div style="margin-top:10px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em">Seletor</div><div style="word-break:break-all">${escapeHtml(entry.selector)}</div></div>
      <div style="margin-top:8px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em">DOM path</div><div style="word-break:break-all">${escapeHtml(entry.domPath)}</div></div>

      <div style="margin-top:10px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em">Conflitos CSS</div>${conflictsBlock}</div>

      <div style="margin-top:10px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em">Estilos computados</div>
        <table style="width:100%;margin-top:4px;border-collapse:collapse">${stylesRows}</table>
      </div>

      <div style="margin-top:10px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em">CSS Variables (var(--…))</div>
        ${
          entry.cssVars.length
            ? entry.cssVars
                .map(
                  (v) => `
          <div style="margin-top:4px;padding:5px 7px;background:rgba(255,255,255,0.04);border-left:2px solid #3b82f6;border-radius:0 4px 4px 0;font-size:11px">
            <div><code style="color:#93c5fd">${escapeHtml(v.name)}</code> → <span style="color:#C8A96A">${escapeHtml(v.resolved || "(vazio)")}</span></div>
            <div style="opacity:.65;font-size:10px">usada em: ${v.usedIn.map(escapeHtml).join(", ")}</div>
            <div style="opacity:.65;font-size:10px">origem: <code>${escapeHtml(v.fromSelector || "?")}</code> @ ${escapeHtml(v.fromOrigin || "?")} (${escapeHtml(v.fromElement || "?")})</div>
          </div>`,
                )
                .join("")
            : '<div style="opacity:.5;font-size:11px">Nenhuma var(--…) usada pelas regras vencedoras.</div>'
        }
      </div>

      ${renderWinnersBlock(entry)}

      <div style="margin-top:10px">
        <div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:4px">Cascata CSS · filtros</div>
        <div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:6px">
          <label style="font-size:10px;opacity:.7">origem ${sel(filters.origin, ["all", "inline", "style-tag", "stylesheet", "shadow"], "origin")}</label>
          <label style="font-size:10px;opacity:.7">tipo ${sel(filters.selectorKind, ["all", "id", "class", "tag", "mixed"], "selectorKind")}</label>
          <label style="font-size:10px;opacity:.7">arquivo ${sel(filters.file, ["all", ...files], "file")}</label>
        </div>
        ${cascadeRows}
      </div>
      <div style="margin-top:10px;opacity:.5;font-size:10px">logs: ${logs.length} · sessão salva em localStorage</div>
    `;

    panel!.querySelectorAll("[data-filter]").forEach((s) => {
      s.addEventListener("change", (e) => {
        const t = e.target as HTMLSelectElement;
        const key = t.getAttribute("data-filter") as keyof Filters;
        (filters as any)[key] = t.value;
        persist();
        renderPanel(entry, el);
      });
    });
    panel!.querySelectorAll("[data-winners-cat]").forEach((b) => {
      b.addEventListener("click", () => {
        winnersCategory = (b as HTMLElement).getAttribute("data-winners-cat") as WinnerCat;
        renderPanel(entry, el);
      });
    });
    const qInput = panel!.querySelector("[data-winners-q]") as HTMLInputElement | null;
    if (qInput) {
      qInput.addEventListener("input", (e) => {
        winnersQuery = (e.target as HTMLInputElement).value;
        // re-render preserving focus
        const pos = qInput.selectionStart ?? winnersQuery.length;
        renderPanel(entry, el);
        const re = panel!.querySelector("[data-winners-q]") as HTMLInputElement | null;
        if (re) {
          re.focus();
          try {
            re.setSelectionRange(pos, pos);
          } catch {
            /* noop */
          }
        }
      });
    }

    panel!.querySelector('[data-act="close"]')?.addEventListener("click", () => {
      panel?.remove();
      panel = null;
    });
    panel!.querySelector('[data-act="copy"]')?.addEventListener("click", () => copyEntry(entry));
    panel!
      .querySelector('[data-act="package"]')
      ?.addEventListener("click", () => copyPackage(entry));
    panel!.querySelector('[data-act="export"]')?.addEventListener("click", exportNDJSON);
    panel!.querySelector('[data-act="html"]')?.addEventListener("click", () => downloadHTML(entry));
    panel!
      .querySelector('[data-act="winners"]')
      ?.addEventListener("click", () => downloadWinners(entry));
    panel!
      .querySelector('[data-act="cascade"]')
      ?.addEventListener("click", () => downloadCascade(entry));
    panel!
      .querySelector('[data-act="compare"]')
      ?.addEventListener("click", () => toggleCompareMode());
    panel!.querySelector('[data-act="lock"]')?.addEventListener("click", () => {
      locked = !locked;
      lockedEntry = locked ? entry : null;
      lockedEl = locked ? el : null;
      persist();
      renderPanel(entry, el);
      moveHighlight(el);
    });
    panel!.querySelector('[data-act="clear"]')?.addEventListener("click", () => {
      logs.length = 0;
      locked = false;
      lockedEntry = null;
      lockedEl = null;
      persist();
      panel?.remove();
      panel = null;
      hideHover();
    });
  }

  function renderComparePanel() {
    ensurePanel();
    if (!compareA || !compareB) {
      panel!.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
          <strong style="color:#3b82f6;font-size:11px;letter-spacing:.15em;text-transform:uppercase">Comparar — selecione ${compareA ? "B" : "A"}</strong>
          <button data-act="cancel-cmp" style="${btn()}">Cancelar</button>
        </div>
        <div style="font-size:11px;opacity:.7">Clique em ${compareA ? "outro" : "um"} elemento para definir <strong>${compareA ? "B" : "A"}</strong>.${compareA ? `<br/>A: ${escapeHtml(compareA.entry.selector)}` : ""}</div>
      `;
      panel!
        .querySelector('[data-act="cancel-cmp"]')
        ?.addEventListener("click", () => exitCompareMode());
      return;
    }
    const a = compareA.entry,
      b = compareB.entry;
    const winners = (e: LogEntry) => {
      const seen = new Set<string>();
      return e.matchedRules
        .filter((r) => {
          const k = Object.keys(r.declarations).find((p) => !seen.has(p));
          if (k) {
            Object.keys(r.declarations).forEach((p) => seen.add(p));
            return true;
          }
          return false;
        })
        .slice(0, 10);
    };
    const renderSide = (e: LogEntry, label: string) => `
      <div style="flex:1;min-width:0">
        <div style="color:#3b82f6;font-size:11px;text-transform:uppercase;letter-spacing:.1em">${label}</div>
        <div style="font-size:11px;word-break:break-all">${escapeHtml(e.selector)}</div>
        <div style="opacity:.6;font-size:10px;margin-top:2px">${e.size.w}×${e.size.h}px${e.inShadow ? " · shadow" : ""}</div>
        <div style="margin-top:6px">
          ${winners(e)
            .map(
              (r) => `
            <div style="margin-top:4px;padding:4px 6px;border-left:2px solid #C8A96A;background:rgba(255,255,255,0.04);font-size:11px">
              <div style="color:#C8A96A;word-break:break-all">${escapeHtml(r.selector)}</div>
              <div style="opacity:.8;word-break:break-all">${escapeHtml(r.cssText)}</div>
              <div style="opacity:.5;font-size:10px">${escapeHtml(r.origin)} · spec ${r.specificity.join(",")}</div>
            </div>`,
            )
            .join("")}
        </div>
      </div>`;
    const diffRows = [
      "font-family",
      "font-size",
      "font-weight",
      "line-height",
      "letter-spacing",
      "color",
      "padding",
      "margin",
      "text-transform",
    ]
      .map((k) => {
        const va = a.styles[k] ?? "—",
          vb = b.styles[k] ?? "—";
        const diff = va !== vb;
        return `<tr style="${diff ? "background:rgba(239,68,68,0.10)" : ""}"><td style="opacity:.6;padding:2px 6px">${k}</td><td style="padding:2px 6px">${escapeHtml(va)}</td><td style="padding:2px 6px">${escapeHtml(vb)}</td></tr>`;
      })
      .join("");
    const dW = b.size.w - a.size.w,
      dH = b.size.h - a.size.h;
    panel!.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px">
        <strong style="color:#3b82f6;font-size:11px;letter-spacing:.15em;text-transform:uppercase">Comparar A ⇄ B</strong>
        <div style="display:flex;gap:4px">
          <button data-act="cmp-reset" style="${btn()}">Resetar</button>
          <button data-act="cmp-exit" style="${btn()}">Sair</button>
        </div>
      </div>
      <div style="display:flex;gap:10px">${renderSide(a, "A")}${renderSide(b, "B")}</div>
      <div style="margin-top:10px;padding:6px 8px;background:rgba(59,130,246,0.10);border-radius:4px;font-size:11px">
        Caixa: A ${a.size.w}×${a.size.h} · B ${b.size.w}×${b.size.h} · Δ ${dW >= 0 ? "+" : ""}${dW}w · ${dH >= 0 ? "+" : ""}${dH}h
      </div>
      <div style="margin-top:10px"><div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:4px">Diferenças de estilo</div>
        <table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr><th></th><th style="text-align:left;color:#3b82f6">A</th><th style="text-align:left;color:#3b82f6">B</th></tr></thead><tbody>${diffRows}</tbody></table>
      </div>
    `;
    panel!
      .querySelector('[data-act="cmp-exit"]')
      ?.addEventListener("click", () => exitCompareMode());
    panel!.querySelector('[data-act="cmp-reset"]')?.addEventListener("click", () => {
      compareA = null;
      compareB = null;
      renderComparePanel();
    });
  }

  function toggleCompareMode() {
    compareMode = !compareMode;
    compareA = null;
    compareB = null;
    if (compareMode) renderComparePanel();
    else if (lockedEntry && lockedEl) renderPanel(lockedEntry, lockedEl);
  }
  function exitCompareMode() {
    compareMode = false;
    compareA = null;
    compareB = null;
    panel?.remove();
    panel = null;
  }

  function btn(primary = false) {
    return `background:${primary ? "#C8A96A" : "rgba(200,169,106,0.15)"};color:${primary ? "#0B1F3A" : "#fff"};border:1px solid rgba(200,169,106,0.4);border-radius:4px;padding:3px 8px;font:11px ui-monospace,monospace;cursor:pointer`;
  }

  function kbd() {
    return "display:inline-block;background:#0B1F3A;color:#C8A96A;border:1px solid rgba(200,169,106,0.5);border-radius:3px;padding:0 4px;font:10px ui-monospace,monospace;line-height:1.4";
  }

  function chip(active: boolean) {
    return `background:${active ? "#C8A96A" : "transparent"};color:${active ? "#0B1F3A" : "#fff"};border:1px solid rgba(200,169,106,0.4);border-radius:99px;padding:2px 8px;font:10px ui-monospace,monospace;cursor:pointer`;
  }

  function renderWinnersBlock(entry: LogEntry): string {
    const winners = computeWinners(entry.matchedRules);
    const q = winnersQuery.trim().toLowerCase();
    const cats: Array<{ k: WinnerCat; label: string }> = [
      { k: "all", label: "Todas" },
      { k: "typography", label: "Tipografia" },
      { k: "cssvars", label: "CSS Variables" },
      { k: "color", label: "Cor" },
      { k: "border", label: "Border" },
    ];
    const chips = cats
      .map(
        (c) =>
          `<button data-winners-cat="${c.k}" style="${chip(winnersCategory === c.k)}">${c.label}</button>`,
      )
      .join("");

    let body = "";
    if (winnersCategory === "cssvars") {
      const vars = entry.cssVars.filter(
        (v) =>
          !q || v.name.toLowerCase().includes(q) || (v.resolved || "").toLowerCase().includes(q),
      );
      body = vars.length
        ? vars
            .map(
              (v) => `
          <div style="margin-top:4px;padding:5px 7px;background:rgba(255,255,255,0.04);border-left:2px solid #3b82f6;border-radius:0 4px 4px 0;font-size:11px">
            <div><code style="color:#93c5fd">${escapeHtml(v.name)}</code> → <span style="color:#C8A96A">${escapeHtml(v.resolved || "(vazio)")}</span></div>
            <div style="opacity:.65;font-size:10px">origem: <code>${escapeHtml(v.fromSelector || "?")}</code> @ ${escapeHtml(v.fromOrigin || "?")}</div>
          </div>`,
            )
            .join("")
        : '<div style="opacity:.5;font-size:11px;margin-top:6px">Nenhuma var(--…) corresponde.</div>';
    } else {
      const list = winners.filter((w) => {
        if (winnersCategory !== "all" && w.cat !== winnersCategory) return false;
        if (
          q &&
          !w.prop.toLowerCase().includes(q) &&
          !w.value.toLowerCase().includes(q) &&
          !w.selector.toLowerCase().includes(q)
        )
          return false;
        return true;
      });
      body = list.length
        ? `<table style="width:100%;margin-top:4px;border-collapse:collapse;font-size:11px">
            ${list
              .map(
                (w) => `
              <tr style="border-top:1px solid rgba(255,255,255,0.06)">
                <td style="padding:3px 4px;color:#93c5fd;white-space:nowrap"><code>${escapeHtml(w.prop)}</code></td>
                <td style="padding:3px 4px;color:#C8A96A;word-break:break-all">${escapeHtml(w.value)}</td>
                <td style="padding:3px 4px;opacity:.7;word-break:break-all"><code>${escapeHtml(w.selector)}</code></td>
              </tr>`,
              )
              .join("")}
          </table>`
        : '<div style="opacity:.5;font-size:11px;margin-top:6px">Nenhuma regra vencedora corresponde.</div>';
    }

    return `
      <div style="margin-top:10px">
        <div style="opacity:.5;font-size:10px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:4px">Regras vencedoras</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:6px">
          <input data-winners-q value="${escapeHtml(winnersQuery)}" placeholder="buscar prop, valor ou seletor…" style="flex:1;min-width:160px;background:#0B1F3A;color:#fff;border:1px solid rgba(200,169,106,0.4);border-radius:4px;padding:3px 6px;font:11px ui-monospace,monospace" />
          ${chips}
        </div>
        ${body}
      </div>`;
  }

  function escapeHtml(s: string) {
    return s.replace(
      /[&<>"']/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!,
    );
  }

  async function copyToClipboard(text: string, okMsg = "Copiado ✓") {
    try {
      await navigator.clipboard.writeText(text);
      flashPanel(okMsg);
    } catch {
      flashPanel("Falha ao copiar");
    }
  }

  async function copyEntry(entry: LogEntry) {
    await copyToClipboard(
      [
        `Component: ${entry.component ?? "(unknown)"}`,
        `Source:    ${entry.source ?? "(unavailable)"}`,
        `Route:     ${entry.route}`,
        `Selector:  ${entry.selector}`,
        `DOM path:  ${entry.domPath}`,
      ].join("\n"),
    );
  }

  /** "Pacote" = bloco markdown pronto para ticket/issue. */
  function buildPackage(entry: LogEntry): string {
    return [
      "### Inspector capture",
      "",
      `- **Timestamp:** ${entry.ts}`,
      `- **Rota:** \`${entry.route}\``,
      `- **Componente:** ${entry.component ?? "(desconhecido)"}`,
      `- **Arquivo:linha:** \`${entry.source ?? "(indisponível)"}\``,
      `- **Selector:** \`${entry.selector}\``,
      `- **DOM path:** \`${entry.domPath}\``,
      `- **Viewport:** ${entry.viewport.w}×${entry.viewport.h} · ${entry.viewport.breakpoint} · dpr ${entry.viewport.dpr}`,
      `- **Box:** ${entry.size.w}×${entry.size.h}px${entry.inShadow ? " · em Shadow DOM" : ""}`,
      "",
    ].join("\n");
  }
  async function copyPackage(entry: LogEntry) {
    await copyToClipboard(buildPackage(entry), "Pacote copiado ✓");
  }

  function flashPanel(msg: string) {
    if (!panel) return;
    const tip = document.createElement("div");
    Object.assign(tip.style, {
      position: "absolute",
      top: "8px",
      right: "12px",
      background: "#C8A96A",
      color: "#0B1F3A",
      padding: "2px 8px",
      borderRadius: "4px",
      fontSize: "10px",
      fontWeight: "700",
    } as CSSStyleDeclaration);
    tip.textContent = msg;
    panel.appendChild(tip);
    setTimeout(() => tip.remove(), 1200);
  }

  function exportNDJSON() {
    if (!logs.length) {
      flashPanel("Sem logs");
      return;
    }
    const blob = new Blob(
      logs.map((l) => JSON.stringify(l) + "\n"),
      { type: "application/x-ndjson" },
    );
    triggerDownload(blob, `inspector-${stamp()}.ndjson`);
  }

  function downloadHTML(entry: LogEntry) {
    const doc = `<!doctype html>
<html><head><meta charset="utf-8"><title>Inspector capture · ${escapeHtml(entry.selector)}</title></head>
<body>
<!--
  Route:    ${entry.route}
  Selector: ${entry.selector}
  DOM path: ${entry.domPath}
  Source:   ${entry.source ?? "(n/a)"}
  Captured: ${entry.ts}
-->
${entry.outerHTML}
</body></html>`;
    triggerDownload(new Blob([doc], { type: "text/html" }), `inspector-${stamp()}.html`);
  }

  /** Resumo das regras vencedoras para tipografia, cor, peso e bordas — inclui var() resolvidas e source. */
  function downloadWinners(entry: LogEntry) {
    const target = [
      "font-size",
      "line-height",
      "font-family",
      "font-weight",
      "color",
      "padding",
      "padding-top",
      "padding-right",
      "padding-bottom",
      "padding-left",
      "border",
      "border-width",
      "border-style",
      "border-color",
      "border-top",
      "border-top-width",
      "border-top-style",
      "border-top-color",
      "border-right",
      "border-right-width",
      "border-right-style",
      "border-right-color",
      "border-bottom",
      "border-bottom-width",
      "border-bottom-style",
      "border-bottom-color",
      "border-left",
      "border-left-width",
      "border-left-style",
      "border-left-color",
    ];
    const winners: Array<{
      prop: string;
      value: string;
      selector: string;
      origin: string;
      source: string | null;
      cssText: string;
    }> = [];
    for (const prop of target) {
      const r = entry.matchedRules.find((m) => prop in m.declarations);
      if (r)
        winners.push({
          prop,
          value: r.declarations[prop],
          selector: r.selector,
          origin: r.origin,
          source: entry.source,
          cssText: r.cssText,
        });
    }
    const payload = {
      ts: entry.ts,
      route: entry.route,
      selector: entry.selector,
      domPath: entry.domPath,
      source: entry.source,
      component: entry.component,
      computed: entry.styles,
      cssVars: entry.cssVars,
      winners,
    };
    triggerDownload(
      new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }),
      `inspector-winners-${stamp()}.json`,
    );
  }

  /** Exporta a cascata CSS completa (matchedRules na ordem de especificidade). */
  function downloadCascade(entry: LogEntry) {
    const meta = {
      ts: entry.ts,
      route: entry.route,
      selector: entry.selector,
      domPath: entry.domPath,
      source: entry.source,
      component: entry.component,
      inShadow: entry.inShadow,
    };
    const lines = [JSON.stringify({ kind: "meta", ...meta })];
    entry.matchedRules.forEach((r, i) =>
      lines.push(JSON.stringify({ kind: "rule", order: i + 1, ...r })),
    );
    triggerDownload(
      new Blob([lines.join("\n") + "\n"], { type: "application/x-ndjson" }),
      `inspector-cascade-${stamp()}.ndjson`,
    );
  }

  function stamp() {
    return new Date().toISOString().replace(/[:.]/g, "-");
  }

  function triggerDownload(blob: Blob, name: string) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  function onClick(e: MouseEvent) {
    if (!active) return;
    if (panel && panel.contains(e.target as Node)) return;
    e.preventDefault();
    e.stopPropagation();
    const el = elementFromEvent(e);
    if (!el) return;

    if (compareMode) {
      const entry = buildEntry(el);
      if (!compareA) compareA = { entry, el };
      else if (!compareB) compareB = { entry, el };
      else {
        compareA = { entry, el };
        compareB = null;
      }
      moveHighlight(el);
      renderComparePanel();
      return;
    }

    if (locked && lockedEntry && lockedEl) {
      renderPanel(lockedEntry, lockedEl);
      return;
    }
    const entry = buildEntry(el);
    logs.push(entry);
    persist();
    moveHighlight(el);
    renderPanel(entry, el);
    // eslint-disable-next-line no-console
    console.log("[Inspector]", entry);
  }

  let dockToggleBtn: HTMLButtonElement | null = null;
  function renderDock() {
    const dock = document.createElement("div");
    Object.assign(dock.style, {
      position: "fixed",
      bottom: "12px",
      right: "12px",
      zIndex: "2147483647",
      display: "flex",
      gap: "6px",
      padding: "6px",
      background: "#0B1F3A",
      borderRadius: "999px",
      boxShadow: "0 6px 20px rgba(0,0,0,0.35)",
      border: "1px solid rgba(200,169,106,0.4)",
    } as CSSStyleDeclaration);
    dockToggleBtn = document.createElement("button");
    dockToggleBtn.style.cssText = btn() + ";border-radius:999px;padding:4px 10px";
    dockToggleBtn.textContent = "🔍 Inspect";
    dockToggleBtn.onclick = () => toggle();
    const exportBtn = document.createElement("button");
    exportBtn.style.cssText = btn() + ";border-radius:999px;padding:4px 10px";
    exportBtn.textContent = "⬇ NDJSON";
    exportBtn.onclick = exportNDJSON;
    dock.append(dockToggleBtn, exportBtn);
    document.body.appendChild(dock);

    if (locked && lockedEntry) {
      try {
        const el = document.querySelector(lockedEntry.selector);
        if (el) {
          lockedEl = el;
          moveHighlight(el);
          renderPanel(lockedEntry, el);
          active = true;
          document.body.style.cursor = "crosshair";
          updateDockState();
        }
      } catch {
        /* ignore */
      }
    }
  }

  function updateDockState() {
    if (!dockToggleBtn) return;
    dockToggleBtn.style.background = active ? "#C8A96A" : "rgba(200,169,106,0.15)";
    dockToggleBtn.style.color = active ? "#0B1F3A" : "#fff";
  }

  function toggle() {
    active = !active;
    document.body.style.cursor = active ? "crosshair" : "";
    updateDockState();
    if (!active) {
      hideHover();
      panel?.remove();
      panel = null;
      compareMode = false;
      compareA = null;
      compareB = null;
    }
    // eslint-disable-next-line no-console
    console.log(`%c[Inspector] ${active ? "ATIVO" : "off"}`, "color:#C8A96A");
  }

  function isTypingTarget(t: EventTarget | null): boolean {
    const el = t as HTMLElement | null;
    if (!el) return false;
    const tag = el.tagName;
    return (
      tag === "INPUT" ||
      tag === "TEXTAREA" ||
      tag === "SELECT" ||
      (el as HTMLElement).isContentEditable
    );
  }

  window.addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === "I" || e.key === "i")) {
      e.preventDefault();
      toggle();
      return;
    }
    if (e.key === "Escape" && active) {
      toggle();
      return;
    }
    if (!active) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (isTypingTarget(e.target)) return;
    const k = e.key.toLowerCase();
    const lastEntry = logs[logs.length - 1];
    if (k === "l" || k === "f") {
      // L (legado) ou F = alternar Fixar usando última seleção
      e.preventDefault();
      if (locked) {
        locked = false;
        lockedEntry = null;
        lockedEl = null;
      } else if (lastEntry) {
        locked = true;
        lockedEntry = lastEntry; /* lockedEl: tenta resolver */
        try {
          lockedEl = document.querySelector(lastEntry.selector);
        } catch {
          lockedEl = null;
        }
      }
      persist();
      if (lockedEntry && lockedEl) renderPanel(lockedEntry, lockedEl);
    } else if (k === "c") {
      e.preventDefault();
      toggleCompareMode();
    } else if (k === "p") {
      if (!lastEntry) return;
      e.preventDefault();
      copyPackage(lastEntry);
    }
  });
  window.addEventListener("mousemove", onMove, true);
  window.addEventListener("click", onClick, true);

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", renderDock);
  } else {
    renderDock();
  }

  (window as any).__cathedraInspector = {
    toggle,
    logs,
    exportNDJSON,
    filters,
    get locked() {
      return locked;
    },
    get compareMode() {
      return compareMode;
    },
    buildPackage,
  };
  // eslint-disable-next-line no-console
  console.log(
    "%c[Inspector] pronto — Ctrl/Cmd+Shift+I alterna · F fixar · C comparar · P pacote · Esc sai",
    "color:#C8A96A",
  );
}

/**
 * Hook genérico do Editorial Engine.
 *
 * Consome o snapshot mais recente por `manifest.id` (fonte da verdade) para
 * alimentar Mission Control e outros consumidores agregadores. O painel
 * detalhado (`EditorialAudit.tsx`) continua fazendo sua própria auditoria
 * completa; este hook expõe a mesma superfície de dados em forma resumida.
 */

import { useEffect, useState } from "react";
import { supabase } from "@/lib/db";
import type { EntityManifest, EntitySnapshot } from "./types";
import { iceTier, type IceTier } from "./ice";
import { computeFreezeCriteria, isFrozen } from "./freeze-manager";

export interface EditorialSummary {
  loading: boolean;
  ready: boolean;
  snapshot: EntitySnapshot | null;
  ice: number;
  editorial: number;
  nexus: number;
  gatePassing: number;
  gateTotal: number;
  tier: IceTier;
  frozen: boolean;
  freezePassCount: number;
  freezeTotalCount: number;
  capturedAt: string | null;
}

const EMPTY: EditorialSummary = {
  loading: true,
  ready: false,
  snapshot: null,
  ice: 0,
  editorial: 0,
  nexus: 0,
  gatePassing: 0,
  gateTotal: 0,
  tier: "review",
  frozen: false,
  freezePassCount: 0,
  freezeTotalCount: 5,
  capturedAt: null,
};

export function useEditorialSummary(manifest: EntityManifest): EditorialSummary {
  const [state, setState] = useState<EditorialSummary>(EMPTY);

  useEffect(() => {
    if (!manifest.ready) {
      setState({ ...EMPTY, loading: false, ready: false });
      return;
    }
    let cancelled = false;
    (async () => {
      const { data } = await (supabase as any)
        .from("editorial_snapshots")
        .select(
          "id,module,captured_at,total,gold,silver,bronze,needs_review,avg_ice,avg_editorial,avg_nexus,gate_passing,gate_failing",
        )
        .eq("module", manifest.id)
        .order("captured_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (cancelled) return;
      if (!data) {
        setState({ ...EMPTY, loading: false, ready: true });
        return;
      }
      const snap = data as EntitySnapshot;
      const gateTotal = snap.gate_passing + snap.gate_failing;
      const totals = {
        total: snap.total,
        published: snap.total, // sem coluna dedicada no snapshot; usamos total como proxy p/ isFrozen
        drafts: 0,
        gold: snap.gold,
        silver: snap.silver,
        bronze: snap.bronze,
        needs_review: snap.needs_review,
        avg: Math.round(snap.avg_ice),
        avg_editorial: Math.round(snap.avg_editorial),
        avg_nexus: Math.round(snap.avg_nexus),
        avg_weighted: Math.round(snap.avg_ice),
      };
      const criteria = computeFreezeCriteria(totals);
      setState({
        loading: false,
        ready: true,
        snapshot: snap,
        ice: Number(snap.avg_ice),
        editorial: Number(snap.avg_editorial),
        nexus: Number(snap.avg_nexus),
        gatePassing: snap.gate_passing,
        gateTotal,
        tier: iceTier(Number(snap.avg_ice)),
        frozen: isFrozen(totals),
        freezePassCount: criteria.filter((c) => c.ok).length,
        freezeTotalCount: criteria.length,
        capturedAt: snap.captured_at,
      });
    })();
    return () => {
      cancelled = true;
    };
  }, [manifest.id, manifest.ready]);

  return state;
}

import { trackEvent } from "@/lib/analytics";

/**
 * Sanitização de FAQs vindos do banco/glossário.
 *
 * Regras:
 * - `question` deve ser string não-vazia (após trim); caso contrário o item é descartado.
 * - `answer` é normalizada: `undefined`/`null`/tipos inválidos viram `''` (item marcado como "normalizado").
 * - Retorna também contadores (dropped, normalized) para observabilidade em dev/testes.
 * - Para uso em JSON-LD, filtre apenas itens com `answer` não-vazia via `filterFaqForJsonLd`.
 */

export interface FaqItem {
  question: string;
  answer: string;
}

export interface SanitizeFaqStats {
  total: number;
  kept: number;
  dropped: number;
  normalized: number;
}

export interface SanitizeFaqResult {
  items: FaqItem[];
  stats: SanitizeFaqStats;
}

export function sanitizeFaqItemsDetailed(raw: unknown, slug?: string): SanitizeFaqResult {
  const stats: SanitizeFaqStats = { total: 0, kept: 0, dropped: 0, normalized: 0 };
  if (!Array.isArray(raw)) return { items: [], stats };

  stats.total = raw.length;
  const items: FaqItem[] = [];
  const isDev =
    typeof import.meta !== "undefined" && (import.meta as any).env && (import.meta as any).env.DEV;

  raw.forEach((item, idx) => {
    if (!item || typeof item !== "object") {
      stats.dropped += 1;
      if (isDev) {
        console.warn(`[Glossary/FAQ] item #${idx} inválido em "${slug ?? "?"}"`, item);
      }
      return;
    }
    const q = (item as any).question;
    const a = (item as any).answer;
    if (typeof q !== "string" || !q.trim()) {
      stats.dropped += 1;
      if (isDev) {
        console.warn(`[Glossary/FAQ] item #${idx} sem question em "${slug ?? "?"}"`, item);
      }
      return;
    }

    let answer = "";
    if (typeof a === "string") {
      answer = a;
    } else if (a !== undefined && a !== null) {
      stats.normalized += 1;
      if (isDev) {
        console.warn(
          `[Glossary/FAQ] item #${idx} answer de tipo inválido (${typeof a}) em "${slug ?? "?"}" — normalizado para ''`,
        );
      }
    } else if (a === undefined || a === null) {
      stats.normalized += 1;
      if (isDev) {
        console.warn(
          `[Glossary/FAQ] item #${idx} answer ausente em "${slug ?? "?"}" — normalizado para ''`,
        );
      }
    }

    items.push({ question: q.trim(), answer });
    stats.kept += 1;
  });

  if (isDev && (stats.dropped > 0 || stats.normalized > 0)) {
    console.info(
      `[Glossary/FAQ] sanitize "${slug ?? "?"}" — total=${stats.total} kept=${stats.kept} dropped=${stats.dropped} normalized=${stats.normalized}`,
    );
  }

  return { items, stats };
}

/** Wrapper simples que retorna apenas os itens sanitizados. */
export function sanitizeFaqItems(raw: unknown, slug?: string): FaqItem[] {
  return sanitizeFaqItemsDetailed(raw, slug).items;
}

/**
 * Filtra itens aptos ao JSON-LD FAQPage: exige `answer` não-vazia após trim.
 * O Google rejeita entradas com Answer vazio, então esse filtro garante
 * conformidade com o schema.org/FAQPage.
 */
export function filterFaqForJsonLd(items: FaqItem[] | null | undefined): FaqItem[] {
  if (!Array.isArray(items)) return [];
  return items.filter(
    (it) =>
      !!it &&
      typeof it.question === "string" &&
      it.question.trim().length > 0 &&
      typeof it.answer === "string" &&
      it.answer.trim().length > 0,
  );
}

/* -------------------------------------------------------------------- */
/* JSON-LD builder + validação Zod                                      */
/* -------------------------------------------------------------------- */

import { z } from "zod";
import { reportSanitizationIssue, getSanitizePolicy } from "./sanitizePolicy";

const nonEmptyString = z.string().trim().min(1);

export const FaqPageJsonLdSchema = z.object({
  "@type": z.literal("FAQPage"),
  mainEntity: z
    .array(
      z.object({
        "@type": z.literal("Question"),
        name: nonEmptyString,
        acceptedAnswer: z.object({
          "@type": z.literal("Answer"),
          text: nonEmptyString,
        }),
      }),
    )
    .min(1),
});

export type FaqPageJsonLd = z.infer<typeof FaqPageJsonLdSchema>;

/**
 * Constrói o objeto JSON-LD `FAQPage` a partir de itens já sanitizados,
 * aplicando `filterFaqForJsonLd` + validação Zod em runtime.
 *
 * Retorna `null` quando não há itens válidos (não emitir schema vazio).
 * Em dev, loga erro de validação; em prod, retorna `null` silenciosamente
 * para nunca enviar structured data malformado ao Google.
 */
const JSON_LD_CACHE = new WeakMap<object, FaqPageJsonLd | null>();

export function buildFaqPageJsonLd(items: FaqItem[] | null | undefined): FaqPageJsonLd | null {
  if (Array.isArray(items) && JSON_LD_CACHE.has(items)) {
    return JSON_LD_CACHE.get(items)!;
  }

  const eligible = filterFaqForJsonLd(items);
  const store = (v: FaqPageJsonLd | null) => {
    if (Array.isArray(items)) JSON_LD_CACHE.set(items, v);
    return v;
  };

  if (eligible.length === 0) return store(null);

  const candidate = {
    "@type": "FAQPage" as const,
    mainEntity: eligible
      .map((f) => ({
        "@type": "Question" as const,
        name: sanitizeAnswerForJsonLd(f.question),
        acceptedAnswer: {
          "@type": "Answer" as const,
          text: sanitizeAnswerForJsonLd(f.answer),
        },
      }))
      .filter((q) => q.name.length > 0 && q.acceptedAnswer.text.length > 0),
  };
  if (candidate.mainEntity.length === 0) return store(null);

  const parsed = FaqPageJsonLdSchema.safeParse(candidate);
  if (!parsed.success) {
    const details = parsed.error.issues.map((iss) => ({
      path: iss.path.join("."),
      code: iss.code,
      message: iss.message,
    }));
    // Política por ambiente controla severidade — mas a rejeição dos campos
    // obrigatórios do FAQPage é SEMPRE garantida (retorna null).
    reportSanitizationIssue("Glossary/FAQ", "JSON-LD FAQPage rejeitado pelo schema Zod", {
      totalIssues: details.length,
      firstIssues: details.slice(0, 10),
      questionCount: candidate.mainEntity.length,
    });
    return store(null);
  }
  return store(parsed.data);
}

/**
 * Validação em tempo real usada por painéis de preview.
 * Retorna estrutura enxuta para renderização em UI.
 */
export interface FaqJsonLdValidation {
  ok: boolean;
  jsonLd: FaqPageJsonLd | null;
  issues: Array<{ path: string; code: string; message: string }>;
  droppedIndices: number[];
  /** Versão da SanitizePolicy que produziu esse resultado. */
  policyVersion: string;
  /** Ambiente resolvido (dev/prod/test). */
  policyEnv: "dev" | "prod" | "test";
  /** Instante em que a validação rodou (ISO). */
  appliedAt: string;
}

export function validateFaqJsonLdLive(items: FaqItem[] | null | undefined): FaqJsonLdValidation {
  const policy = getSanitizePolicy();
  const meta = {
    policyVersion: policy.version,
    policyEnv: policy.env,
    appliedAt: new Date().toISOString(),
  } as const;
  const raw = Array.isArray(items) ? items : [];
  const eligible = filterFaqForJsonLd(raw);
  const droppedIndices: number[] = [];
  raw.forEach((it, i) => {
    if (!eligible.includes(it)) droppedIndices.push(i);
  });
  const candidate = {
    "@type": "FAQPage" as const,
    mainEntity: eligible.map((f) => ({
      "@type": "Question" as const,
      name: sanitizeAnswerForJsonLd(f.question),
      acceptedAnswer: {
        "@type": "Answer" as const,
        text: sanitizeAnswerForJsonLd(f.answer),
      },
    })),
  };
  if (candidate.mainEntity.length === 0) {
    return {
      ok: false,
      jsonLd: null,
      issues: [{ path: "mainEntity", code: "empty", message: "nenhum item elegível" }],
      droppedIndices,
      ...meta,
    };
  }
  const parsed = FaqPageJsonLdSchema.safeParse(candidate);
  if (!parsed.success) {
    trackEvent("glossary_faq_sanitized", { count: candidate.mainEntity.length });
    return {
      ok: false,
      jsonLd: null,
      issues: parsed.error.issues.map((i) => ({
        path: i.path.join("."),
        code: i.code,
        message: i.message,
      })),
      droppedIndices,
      ...meta,
    };
  }
  return { ok: true, jsonLd: parsed.data, issues: [], droppedIndices, ...meta };
}

/**
 * Explica, por item, o que a sanitização removeu ou normalizou entre a
 * versão bruta e a versão emitida no JSON-LD. Usado apenas por painéis
 * de dev/QA — não deve ser importado em código de produção crítico.
 */
export interface FaqSanitizationDiff {
  index: number;
  rawQuestion: unknown;
  rawAnswer: unknown;
  sanitizedQuestion: string;
  sanitizedAnswer: string;
  questionChanged: boolean;
  answerChanged: boolean;
  removedFromQuestion: string[];
  removedFromAnswer: string[];
  dropped: boolean;
  reason?: string;
}

function collectRemoved(raw: unknown): string[] {
  if (typeof raw !== "string") return [];
  const hits: string[] = [];
  for (const rx of [
    DANGEROUS_TAG_BLOCK,
    DANGEROUS_TAG_LOOSE,
    INLINE_EVENT_HANDLER,
    DANGEROUS_URI,
  ]) {
    const re = new RegExp(rx.source, rx.flags);
    const matches = raw.match(re);
    if (matches) hits.push(...matches);
  }
  if (/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/.test(raw)) hits.push("[control-chars]");
  return hits;
}

export function explainFaqSanitization(rawList: unknown): FaqSanitizationDiff[] {
  if (!Array.isArray(rawList)) return [];
  return rawList.map((item, index) => {
    const rawQuestion = item && typeof item === "object" ? (item as any).question : undefined;
    const rawAnswer = item && typeof item === "object" ? (item as any).answer : undefined;
    const sanitizedQuestion = sanitizeAnswerForJsonLd(rawQuestion);
    const sanitizedAnswer = sanitizeAnswerForJsonLd(rawAnswer);
    const dropped = sanitizedQuestion.length === 0 || sanitizedAnswer.length === 0;
    const reason = !sanitizedQuestion
      ? "question vazia após sanitização"
      : !sanitizedAnswer
        ? "answer vazia após sanitização"
        : undefined;
    return {
      index,
      rawQuestion,
      rawAnswer,
      sanitizedQuestion,
      sanitizedAnswer,
      questionChanged: typeof rawQuestion === "string" && rawQuestion !== sanitizedQuestion,
      answerChanged: typeof rawAnswer === "string" && rawAnswer !== sanitizedAnswer,
      removedFromQuestion: collectRemoved(rawQuestion),
      removedFromAnswer: collectRemoved(rawAnswer),
      dropped,
      reason,
    };
  });
}

/* -------------------------------------------------------------------- */
/* Sanitização de HTML e caracteres de controle para JSON-LD            */
/* -------------------------------------------------------------------- */

// Tags perigosas cujos conteúdos devem ser DESCARTADOS por inteiro
// (script/style/iframe podem executar código ou exfiltrar dados mesmo escapados
// se um consumidor decidir renderizar como HTML por engano).
const DANGEROUS_TAG_BLOCK =
  /<\s*(script|style|iframe|object|embed|noscript|template)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi;
// Também remove tags "solitárias" perigosas sem fechamento
const DANGEROUS_TAG_LOOSE =
  /<\s*\/?\s*(script|style|iframe|object|embed|noscript|template|link|meta|base|form|input|button|svg|math)\b[^>]*>/gi;
// Handlers inline (onerror=, onclick=, etc.) — mesmo após escape, evitamos deixar padrões suspeitos
const INLINE_EVENT_HANDLER = /\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi;
// javascript:/data: URIs em atributos href/src
const DANGEROUS_URI = /(?:href|src)\s*=\s*(?:"|')?\s*(?:javascript|data|vbscript):[^"'>\s]*/gi;
// Caracteres de controle (exceto \t \n \r) — quebram JSON-LD e podem esconder payloads
const CONTROL_CHARS = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g;

function escapeHtmlEntities(input: string): string {
  return input
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Sanitiza um `answer`/`question` antes de emiti-lo dentro do JSON-LD `FAQPage`.
 *
 * Etapas:
 *  1. Remove blocos de tags perigosas (script/style/iframe...) incluindo o conteúdo.
 *  2. Remove qualquer tag perigosa solitária remanescente.
 *  3. Remove handlers inline (onerror=, onclick=) e URIs javascript:/data:.
 *  4. Remove caracteres de controle.
 *  5. Escapa entidades HTML restantes (`< > & " '`).
 *  6. Normaliza espaços e faz trim final.
 *
 * O objetivo é garantir que o `text` do `Answer` seja seguro para consumo
 * por buscadores e por qualquer renderer que trate o conteúdo como HTML.
 */
export function sanitizeAnswerForJsonLd(input: unknown): string {
  if (typeof input !== "string") return "";
  let out = input;
  out = out.replace(DANGEROUS_TAG_BLOCK, " ");
  out = out.replace(DANGEROUS_TAG_LOOSE, " ");
  out = out.replace(INLINE_EVENT_HANDLER, "");
  out = out.replace(DANGEROUS_URI, "");
  out = out.replace(CONTROL_CHARS, "");
  out = escapeHtmlEntities(out);
  out = out
    .replace(/[ \t]+/g, " ")
    .replace(/\s+\n/g, "\n")
    .trim();
  return out;
}

/**
 * Política de sanitização por ambiente para o pipeline de FAQ do glossário.
 *
 * A rejeição dos campos obrigatórios do `FAQPage` (question/answer não vazios,
 * `@type` corretos) é **sempre** garantida — a política controla apenas a
 * severidade dos avisos e do comportamento em anomalias não fatais.
 *
 * - `dev`  → `warn`  · loga stack, expõe painéis de inspeção, mantém badge.
 * - `prod` → `strict` · silencioso, rejeita e emite métrica; nada em console.
 * - `test` → `throw` · dev pipeline agressivo (fail-fast em CI de unidade).
 */

export type SanitizeSeverity = "warn" | "strict" | "throw";

/**
 * Versão da política de sanitização. Bump obrigatório sempre que:
 *  - as regras de descarte (schema Zod, sanitizers) mudarem;
 *  - o mapeamento env → severity mudar;
 *  - novos flags forem adicionados/removidos de `SanitizePolicy`.
 * Registrada no JSON-LD preview e nos exports para auditoria/reprodutibilidade.
 */
export const SANITIZE_POLICY_VERSION = "1.1.0";

export interface SanitizePolicy {
  /** Versão da política aplicada (semver). */
  version: string;
  env: "dev" | "prod" | "test";
  severity: SanitizeSeverity;
  /** Loga descartes/normalizações no console. */
  verboseLogs: boolean;
  /** Expõe painéis de inspeção (raw/diff/jsonld) na UI. */
  exposeDevPanels: boolean;
  /** Envia métricas (`faq_sanitization`) para GA/Sentry. */
  emitMetrics: boolean;
}

function detectEnv(): "dev" | "prod" | "test" {
  // Vitest
  if (typeof process !== "undefined" && process.env?.VITEST) return "test";
  if (typeof process !== "undefined" && process.env?.NODE_ENV === "test") return "test";
  // Vite
  try {
    const meta: any = import.meta as any;
    if (meta?.env?.DEV) return "dev";
    if (meta?.env?.PROD) return "prod";
  } catch {
    // fallthrough
  }
  if (typeof process !== "undefined" && process.env?.NODE_ENV === "production") return "prod";
  return "dev";
}

let cached: SanitizePolicy | null = null;

export function getSanitizePolicy(): SanitizePolicy {
  if (cached) return cached;
  const env = detectEnv();
  const base = { version: SANITIZE_POLICY_VERSION } as const;
  cached =
    env === "prod"
      ? {
          ...base,
          env,
          severity: "strict",
          verboseLogs: false,
          exposeDevPanels: false,
          emitMetrics: true,
        }
      : env === "test"
        ? {
            ...base,
            env,
            severity: "throw",
            verboseLogs: false,
            exposeDevPanels: false,
            emitMetrics: false,
          }
        : {
            ...base,
            env,
            severity: "warn",
            verboseLogs: true,
            exposeDevPanels: true,
            emitMetrics: true,
          };
  return cached;
}

/** Reseta o cache — utilitário para testes. */
export function __resetSanitizePolicyForTests(override?: Partial<SanitizePolicy>) {
  if (!override) {
    cached = null;
    return;
  }
  const base = getSanitizePolicy();
  cached = { ...base, ...override };
}

/**
 * Reporta uma anomalia respeitando a severidade configurada.
 * Nunca lança em `warn`/`strict`; só lança em `throw` (usado em test).
 */
export function reportSanitizationIssue(
  scope: string,
  message: string,
  extra?: Record<string, unknown>,
) {
  const policy = getSanitizePolicy();
  const payload = { scope, message, ...extra };
  if (policy.severity === "throw") {
    throw new Error(`[${scope}] ${message} :: ${JSON.stringify(extra ?? {})}`);
  }
  if (policy.severity === "warn") {
    console.warn(`[${scope}]`, message, payload);
    return;
  }
  // strict: apenas error estruturado (interceptado por Sentry em prod).
  console.error(`[${scope}]`, message, payload);
}

import { defineTool } from "@lovable.dev/mcp-js";
import { createClient } from "@supabase/supabase-js";
import { z } from "zod";

export default defineTool({
  name: "related_content",
  title: "Conteúdo Relacionado",
  description:
    "Dado um nó (kind+ref), retorna conteúdos relacionados hidratados: verbetes, santos, orações e coleções alcançados via Nexus.",
  inputSchema: {
    kind: z.enum(["glossary", "saint", "prayer", "bible", "catechism", "collection", "journey"]),
    ref: z.string().trim().min(1).max(200),
    limit: z.number().int().min(1).max(50).optional(),
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ kind, ref, limit }) => {
    const sb = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_PUBLISHABLE_KEY!, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const max = limit ?? 20;
    const [outgoing, incoming] = await Promise.all([
      sb
        .from("nexus_relations")
        .select("relation_type,target_kind,target_ref,note")
        .eq("source_kind", kind)
        .eq("source_ref", ref)
        .limit(max),
      sb
        .from("nexus_relations")
        .select("relation_type,source_kind,source_ref,note")
        .eq("target_kind", kind)
        .eq("target_ref", ref)
        .limit(max),
    ]);
    const nodes = new Map<string, { kind: string; ref: string; via: string[] }>();
    for (const r of outgoing.data ?? []) {
      const k = `${r.target_kind}:${r.target_ref}`;
      if (!nodes.has(k)) nodes.set(k, { kind: r.target_kind, ref: r.target_ref, via: [] });
      nodes.get(k)!.via.push(`→ ${r.relation_type}`);
    }
    for (const r of incoming.data ?? []) {
      const k = `${r.source_kind}:${r.source_ref}`;
      if (!nodes.has(k)) nodes.set(k, { kind: r.source_kind, ref: r.source_ref, via: [] });
      nodes.get(k)!.via.push(`← ${r.relation_type}`);
    }
    const bucket = (kk: string) => [...nodes.values()].filter((n) => n.kind === kk);
    const glossarySlugs = bucket("glossary").map((n) => n.ref);
    const saintIds = bucket("saint").map((n) => n.ref);
    const prayerSlugs = bucket("prayer").map((n) => n.ref);
    const collectionSlugs = bucket("collection").map((n) => n.ref);

    const [g, s, p, c] = await Promise.all([
      glossarySlugs.length
        ? sb
            .from("glossary")
            .select("slug,term,short_definition,category")
            .in("slug", glossarySlugs)
            .eq("status", "published")
        : Promise.resolve({ data: [] as any[] }),
      saintIds.length
        ? sb.from("saints").select("id,name,title,feast_day,bio,category").in("id", saintIds)
        : Promise.resolve({ data: [] as any[] }),
      prayerSlugs.length
        ? sb
            .from("prayers")
            .select("slug,title,category,kicker")
            .in("slug", prayerSlugs)
            .eq("is_published", true)
        : Promise.resolve({ data: [] as any[] }),
      collectionSlugs.length
        ? sb
            .from("collections")
            .select("slug,title,subtitle,category")
            .in("slug", collectionSlugs)
            .eq("status", "published")
        : Promise.resolve({ data: [] as any[] }),
    ]);

    const payload = {
      node: { kind, ref },
      glossary: g.data ?? [],
      saints: s.data ?? [],
      prayers: p.data ?? [],
      collections: c.data ?? [],
      bible: bucket("bible"),
      catechism: bucket("catechism"),
      relations_meta: [...nodes.values()],
    };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload,
    };
  },
});

import { AppRoute } from "@/types";

/**
 * Checks if the "Hoje" route should be considered active based on the current path.
 * The "Hoje" tab is active for the root path, /hoje, and any sub-routes of /hoje.
 */
export const isHojeActive = (currentPath: string): boolean => {
  if (!currentPath) return false;

  // Normalize path by removing query strings and hashes
  const path = currentPath.split(/[?#]/)[0];

  // If it's exactly root, /hoje, or starts with /hoje/
  return path === "/" || path === "/hoje" || path === "/hoje/" || path.startsWith("/hoje/");
};

/**
 * Checks if a specific route is active given the current path.
 * Handles exact matches and nested routes, with special logic for "Hoje".
 */
export const isRouteActive = (itemRoute: string, currentPath: string): boolean => {
  if (!itemRoute) return false;

  // Clean currentPath of query strings/hashes for comparison
  const path = currentPath.split(/[?#]/)[0];

  if (itemRoute === AppRoute.HOJE || itemRoute === "/") {
    return isHojeActive(path);
  }

  // Exact match
  if (path === itemRoute) return true;

  // Nested route match (e.g. /bible/verse matches /bible)
  if (itemRoute !== "/" && path.startsWith(itemRoute)) {
    // Ensure it's a subpath match (e.g. /bibletest shouldn't match /bible)
    return path.charAt(itemRoute.length) === "/" || itemRoute.endsWith("/");
  }

  return false;
};

/**
 * Checks if a click/touch event is legitimate to prevent ghost clicks or accidental navigation.
 * Particularly useful for mobile to ensure navigation only happens on deliberate user action.
 */
let lastNavTime = 0;
const NAV_THROTTLE = 400; // ms

export const isLegitimateClick = (event: any): boolean => {
  // Throttle navigation to prevent double-tap issues
  const now = Date.now();
  if (now - lastNavTime < NAV_THROTTLE) {
    return false;
  }

  // Always allow keyboard events (Enter, Space) which often have detail === 0
  const isKeyboard =
    event instanceof KeyboardEvent ||
    event.type === "keydown" ||
    event.type === "keyup" ||
    (event.nativeEvent && event.nativeEvent instanceof KeyboardEvent) ||
    event.key === "Enter" ||
    event.key === " ";

  if (isKeyboard) {
    lastNavTime = now;
    return true;
  }

  // If it's a touch event, ensure it's a single touch
  if (event.touches && event.touches.length > 1) {
    return false;
  }

  // Protection against ghost clicks (synthetic clicks triggered by mobile browsers)
  if (event.type === "click" && event.detail === 0) {
    const nativeEvent = event.nativeEvent || event;
    // If it's a pointer event, check if it was triggered by a real pointer
    if (
      nativeEvent.pointerType === "mouse" ||
      nativeEvent.pointerType === "touch" ||
      nativeEvent.pointerType === "pen"
    ) {
      lastNavTime = now;
      return true;
    }
    // If no pointer info and not keyboard, it's likely a ghost click or accidental touch
    return false;
  }

  lastNavTime = now;
  return true;
};

import { z } from "zod";
import { supabase } from "@/lib/db";
import { getSearchTermsForTag } from "./tagNormalization";
import { getAllLocalCatechism } from "@/data/catechism";
import { BIBLE_CANON } from "./bibleCanon";

export interface TagContent {
  id: string;
  type: string;
  content_text: string;
  title: string;
  metadata: any;
}

// FIX BOLHA NEXUS BÍBLIA: metadata vem vazia no banco; deriva book/chapter/verse
// a partir de reference_id ("Jo 14, 6", "1Cor 13,4", "Mt 11, 29") para que
// resolveLink()/BibleVersePopover funcionem e o item não seja filtrado como no-route.
const BIBLE_ABBR_BY_LOWER = new Map(BIBLE_CANON.map((b) => [b.abbr.toLowerCase(), b.abbr]));

// Schemas zod para normalização segura em runtime — evitam que payloads
// malformados vindos do banco/cache atinjam o parser e produzam NaN/undefined
// silenciosos no resolveLink.
export const ReferenceIdSchema = z
  .unknown()
  .transform((v) => (typeof v === "string" ? v.trim() : ""))
  .pipe(z.string().max(120));

export const NexusMetadataSchema = z
  .unknown()
  .transform((v) =>
    v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {},
  )
  .pipe(z.record(z.string(), z.unknown()));

export const ParsedBibleReferenceSchema = z.object({
  book: z.string().min(1).optional(),
  chapter: z.number().int().positive().optional(),
  verse: z.number().int().positive().optional(),
});

export type ParsedBibleReference = z.infer<typeof ParsedBibleReferenceSchema>;

function parseBibleReference(ref: unknown): ParsedBibleReference {
  const safe = ReferenceIdSchema.safeParse(ref);
  if (!safe.success || !safe.data) return {};
  // Normaliza prefixo romano ("I Co" → "1 Co", "II Sm" → "2 Sm", "III Jo" → "3 Jo").
  // Só aplica quando romano é seguido por espaço, evitando conflito com "Is", "It" etc.
  const ROMAN: Record<string, string> = { I: "1", II: "2", III: "3" };
  const normalized = safe.data.replace(/^(III|II|I)\s+/i, (_, r) => `${ROMAN[r.toUpperCase()]} `);
  // Separadores aceitos entre capítulo e versículo: , : . -
  const m = normalized.match(/^([1-3]?\s?[A-Za-zÀ-ÿ]+)\.?\s+(\d+)(?:\s*[,:.\-]\s*(\d+))?/);
  if (!m) return {};
  const rawBook = m[1].replace(/\s+/g, "").toLowerCase();
  const abbr = BIBLE_ABBR_BY_LOWER.get(rawBook);
  if (!abbr) return {};
  const chapter = Number(m[2]);
  const verse = m[3] ? Number(m[3]) : undefined;
  const out = ParsedBibleReferenceSchema.safeParse({ book: abbr, chapter, verse });
  return out.success ? out.data : {};
}

export { parseBibleReference };

/**
 * Standardizes the formatting of spiritual and journey content.
 * Ensures references are never empty and have meaningful fallbacks.
 */
export function formatNexusContent(data: any, type: string): TagContent {
  const isJourney = type === "journey";

  if (isJourney) {
    return {
      id: data.id,
      type: "journey",
      content_text: data.description || data.subtitle || "",
      title: data.title || "Jornada Espiritual",
      metadata: { ...data, is_direct_journey: true },
    };
  }

  // Spiritual contents (Bible, Catechism, Magisterium)
  let fallbackReference = "Tradição";
  if (data.type === "bible") fallbackReference = "Escritura";
  else if (data.type === "catechism") fallbackReference = "Catecismo";
  else if (data.type === "magisterium") fallbackReference = "Magistério";

  // Normaliza metadata com zod: aceita apenas objeto plano; qualquer outra
  // forma (array, null, string, number) vira {} — evita spread inseguro.
  const safeMeta = NexusMetadataSchema.parse((data as any)?.metadata);
  const safeTags = Array.isArray((data as any)?.tags) ? (data as any).tags : [];
  const baseMeta: any = { ...safeMeta, tags: safeTags };

  // Enriquecimento: itens bíblicos frequentemente vêm com metadata {} no banco.
  // Parseia reference_id para popular book/chapter/verse, evitando reason:no-route.
  if (data?.type === "bible" && (!baseMeta.book || !baseMeta.chapter)) {
    const parsed = parseBibleReference((data as any)?.reference_id);
    if (parsed.book && parsed.chapter) {
      baseMeta.book = baseMeta.book || parsed.book;
      baseMeta.chapter = baseMeta.chapter || parsed.chapter;
      if (parsed.verse && !baseMeta.verse) baseMeta.verse = parsed.verse;
    }
  }

  return {
    id: data.id,
    type: data.type,
    content_text: typeof data.content_text === "string" ? data.content_text : "",
    title: safeTitle(data.reference_id) ?? safeTitle(data.title) ?? fallbackReference,
    metadata: baseMeta,
  };
}

/**
 * Fallback de UI: nunca renderiza "undefined", "NaN" ou "null" como texto
 * visível. Retorna string trimada ou null se o valor não for exibível.
 */
function safeTitle(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const t = raw.trim();
  if (!t) return null;
  if (/^(undefined|null|nan)$/i.test(t)) return null;
  // Remove tokens "undefined"/"NaN" no meio (ex.: "Mt undefined:NaN").
  const cleaned = t
    .replace(/\b(undefined|NaN|null)\b/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  return cleaned || null;
}

/**
 * Fetches and formats content for a specific tag.
 */
// STAB-003A: aceita apenas UUID v1-v5 para evitar `theme_id=eq.undefined`
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const isValidUuid = (v: unknown): v is string => typeof v === "string" && UUID_RE.test(v);

export async function fetchNexusTagContent(
  tag: { label: string; slug: string; id?: string },
  signal?: AbortSignal,
): Promise<TagContent[]> {
  const searchTerms = getSearchTermsForTag(tag);

  const spiritualQuery = supabase
    .from("spiritual_contents")
    .select("*")
    .overlaps("tags", searchTerms)
    .limit(15);

  const journeyQuery = supabase
    .from("journeys")
    .select("*")
    .overlaps("tags", searchTerms)
    .limit(10);

  // STAB-003A: só consulta theme_contents quando há theme_id UUID válido.
  // Antes: `.eq('theme_id', (tag as any).id)` disparava `theme_id=eq.undefined`
  // no viewer do Magistério, gerando 400/22P02 em `/rest/v1/theme_contents`.
  const themeId = (tag as any).id;
  const themeContentQuery = isValidUuid(themeId)
    ? supabase.from("theme_contents").select("*").eq("theme_id", themeId).limit(10)
    : null;

  if (signal) {
    spiritualQuery.abortSignal(signal);
    journeyQuery.abortSignal(signal);
    themeContentQuery?.abortSignal(signal);
  }

  const [spiritualResponse, journeyResponse, themeContentResponse] = await Promise.all([
    spiritualQuery,
    journeyQuery,
    themeContentQuery ?? Promise.resolve({ data: [], error: null } as { data: any[]; error: null }),
  ]);

  if (spiritualResponse.error) throw spiritualResponse.error;
  if (journeyResponse.error) throw journeyResponse.error;
  if (themeContentResponse.error) throw themeContentResponse.error;

  const spiritual = (spiritualResponse.data || []).map((d) => formatNexusContent(d, d.type));
  const journeys = (journeyResponse.data || []).map((d) => formatNexusContent(d, "journey"));
  const themeContents = (themeContentResponse.data || []).map((d) => ({
    id: d.id,
    type: d.content_type,
    content_text: d.text_content || "",
    title: d.reference || d.title || "Tradição",
    metadata: { ...d, is_theme_content: true },
  }));

  // Add local catechism data that matches search terms
  const localCatechism = getAllLocalCatechism()
    .filter((cat) => cat.tags.some((t) => searchTerms.includes(t)))
    .map((cat) => ({
      id: cat.id,
      type: "catechism",
      content_text: cat.conteudo,
      title: `Catecismo §${cat.paragraph}`,
      metadata: { ...cat, tags: cat.tags },
    }));

  const all = [...spiritual, ...journeys, ...themeContents, ...localCatechism];
  // Unique by ID
  return Array.from(new Map(all.map((item) => [item.id, item])).values());
}

/**
 * Nexus telemetry — STAB-NEXUS-P0 (Etapa 5).
 *
 * Registra os 4 eventos-chave da experiência do Nexus:
 *   nexus.shown        → painel montado com >=1 bubble navegável
 *   nexus.click        → usuário clicou em um bubble
 *   nexus.destination  → navegação concluída (rota final resolvida)
 *   nexus.failed       → bubble não pôde ser resolvido em rota
 *
 * Reutiliza a tabela `analytics_events` já em uso por
 * `catechismDiagnostics.ts` e `Bible.tsx` — nenhum backend novo.
 * Silencia erros de gravação para não poluir o console de produção.
 */
import { supabase } from "@/lib/db";

export type NexusTelemetryEvent =
  "nexus.shown" | "nexus.click" | "nexus.destination" | "nexus.failed";

interface NexusEventBase {
  tagId?: string;
  tagSlug?: string;
  from?: string;
}

export interface NexusShownPayload extends NexusEventBase {
  itemCount: number;
  kinds: string[];
}

export interface NexusClickPayload extends NexusEventBase {
  type: string;
  id?: string;
  destination?: string;
}

export interface NexusDestinationPayload extends NexusEventBase {
  type: string;
  id?: string;
  url: string;
}

export interface NexusFailedPayload extends NexusEventBase {
  type: string;
  id?: string;
  reason: string;
}

type NexusPayload =
  NexusShownPayload | NexusClickPayload | NexusDestinationPayload | NexusFailedPayload;

const emit = async (event: NexusTelemetryEvent, payload: NexusPayload) => {
  // Dev/E2E: log estruturado + mirror em window para asserções determinísticas.
  if (import.meta.env.DEV) {
    // eslint-disable-next-line no-console
    console.log(`[Nexus] ${event}`, payload);
  }
  if (typeof window !== "undefined") {
    const w = window as unknown as {
      __nexusEvents__?: Array<{ event: NexusTelemetryEvent; payload: NexusPayload; t: number }>;
    };
    if (!w.__nexusEvents__) w.__nexusEvents__ = [];
    w.__nexusEvents__.push({ event, payload, t: Date.now() });
  }
  try {
    const { data: userData } = await supabase.auth.getUser();
    await supabase.from("analytics_events").insert({
      event_name: event,
      user_id: userData?.user?.id ?? null,
      metadata: {
        ...payload,
        path:
          typeof window !== "undefined" ? window.location.pathname + window.location.search : null,
      } as any,
    } as any);
  } catch {
    /* silent — telemetria nunca deve quebrar UX */
  }
};

