}

// ─── Pre-load logic ───

export async function preloadCatechism(
  start: number,
  count: number,
  onProgress?: (p: number) => void,
): Promise<void> {
  for (let i = 0; i < count; i++) {
    const paragraph = start + i;
    if (paragraph > 2865) break;

    const cached = await getCachedCatechismParagraph(paragraph);
    if (cached) continue;

    try {
      const { data, error } = await supabase.functions.invoke("catechism-text", {
        body: { paragraph },
      });
      if (!error && data) {
        const parsed = typeof data === "string" ? JSON.parse(data) : data;
        if (!parsed.status || parsed.status !== "not_cached") {
          await cacheCatechismParagraph(paragraph, {
            paragraph,
            content: parsed.content,
            language: parsed.language || "pt",
            status: parsed.status,
            textoBase: parsed.textoBase,
          });
        }
      }
    } catch (e) {
      console.error(`Failed to preload catechism §${paragraph}`, e);
    }

    onProgress?.(Math.round(((i + 1) / count) * 100));
  }
}

export async function preloadBible(
  bookAbbr: string,
  startChapter: number,
  count: number,
  onProgress?: (p: number) => void,
): Promise<void> {
  for (let i = 0; i < count; i++) {
    const chapter = startChapter + i;

    const cached = await getCachedBibleChapter(bookAbbr, chapter);
    if (cached) continue;

    try {
      const { data, error } = await supabase.functions.invoke("bible-text", {
        body: { book: bookAbbr, chapter },
      });
      if (!error && data) {
        await cacheBibleChapter(bookAbbr, chapter, data);
      }
    } catch (e) {
      console.error(`Failed to preload bible ${bookAbbr} ${chapter}`, e);
    }

    onProgress?.(Math.round(((i + 1) / count) * 100));
  }
}

/**
 * OpenTelemetry — bootstrap opcional
 * ---------------------------------------------------------------
 * No-op por padrão. Só carrega o SDK web quando `VITE_OTEL_ENABLED=1`.
 * Isso mantém o bundle enxuto e não introduz nenhuma alteração
 * funcional enquanto o time não decidir ativar.
 *
 * Ver docs/OBSERVABILITY-OTEL.md para o desenho completo.
 */

type TraceDbFn = <T>(queryId: string, fn: () => Promise<T>) => Promise<T>;

const enabled = import.meta.env.VITE_OTEL_ENABLED === "1";

let tracer: any = null;

export async function initOtel(): Promise<void> {
  if (!enabled || typeof window === "undefined") return;
  try {
    // Import dinâmico: só resolve se as libs foram instaladas.
    const dyn = (m: string) =>
      (new Function("m", "return import(m)") as (m: string) => Promise<any>)(m);
    const api = await dyn("@opentelemetry/api");
    const web = await dyn("@opentelemetry/sdk-trace-web");
    const otlp = await dyn("@opentelemetry/exporter-trace-otlp-http");

    const provider = new web.WebTracerProvider({
      resource: {
        attributes: {
          "service.name": import.meta.env.VITE_OTEL_SERVICE_NAME ?? "cathedra-web",
        },
      },
    });
    const endpoint = import.meta.env.VITE_OTEL_ENDPOINT ?? "http://localhost:4318/v1/traces";
    provider.addSpanProcessor(
      new web.BatchSpanProcessor(new otlp.OTLPTraceExporter({ url: endpoint })),
    );
    provider.register();
    tracer = api.trace.getTracer("cathedra-web");
    // eslint-disable-next-line no-console
    console.info("[otel] inicializado →", endpoint);
  } catch (e) {
    // eslint-disable-next-line no-console
    console.warn("[otel] libs ausentes ou falha no init; seguindo sem tracing.", e);
  }
}

/**
 * Envolve uma chamada de banco em um span nomeado.
 *
 * Uso:
 *   const res = await traceDb('app_metrics:window30d', () =>
 *     supabase.from('app_metrics').select(...)
 *   );
 *
 * Contrato: se OTel estiver desligado, é `fn()` puro — zero overhead
 * observável, nenhuma alteração de dados.
 */
export const traceDb: TraceDbFn = async (queryId, fn) => {
  if (!tracer) return fn();
  const span = tracer.startSpan(`db:${queryId}`, {
    attributes: {
      "db.system": "postgresql",
      "db.query_id": queryId,
    },
  });
  const started = performance.now();
  try {
    const res = await fn();
    const rows = Array.isArray((res as any)?.data)
      ? (res as any).data.length
      : ((res as any)?.count ?? undefined);
    if (rows !== undefined) span.setAttribute("db.rows_returned", rows);
    span.setAttribute("perf.duration_ms", performance.now() - started);
    span.end();
    return res;
  } catch (err) {
    span.recordException(err as Error);
    span.setStatus({ code: 2, message: (err as Error).message });
    span.end();
    throw err;
  }
};

/**
 * Telemetria estruturada para falhas do Prayer Engine.
 * Coleta contexto rico (slug, params, sessão, hierarquia) e envia para
 * console + Sentry + analytics_events via runtimeErrorLogger.
 *
 * Sprint · Bug React #300 (/oracao/rosario contemplative)
 */
import * as Sentry from "@sentry/react";
import { trackNavigationError } from "@/lib/telemetry";

export interface PrayerErrorContext {
  slug?: string | null;
  searchParams?: Record<string, string>;
  userId?: string | null;
  engineVersion?: number | null;
  hierarchyStatus?: "idle" | "loading" | "ready" | "error";
  blocksCount?: number;
  activeSectionSlug?: string | null;
  mysteriesCount?: number;
  route?: string;
}

/**
 * Registra falha de renderização/hook do Prayer com contexto completo.
 * Retorna refId para exibição ao usuário.
 */
export function reportPrayerError(
  error: Error,
  ctx: PrayerErrorContext,
  extra?: { componentStack?: string },
): string {
  const payload = {
    ...ctx,
    error_name: error.name,
    error_message: error.message,
    react_error_code: extractReactErrorCode(error.message),
    ts: new Date().toISOString(),
  };

  // Console estruturado — visível em dev e no console dos usuários.
  // eslint-disable-next-line no-console
  console.error("[PrayerEngine:error]", payload, error);

  Sentry.withScope((scope) => {
    scope.setTag("surface", "prayer-engine");
    scope.setTag("prayer_slug", ctx.slug ?? "unknown");
    if (payload.react_error_code) {
      scope.setTag("react_error_code", payload.react_error_code);
    }
    scope.setContext("prayer_context", payload as Record<string, unknown>);
    Sentry.captureException(error, {
      extra: { componentStack: extra?.componentStack ?? null },
    });
  });

  // Reaproveita pipeline global (retorna refId e persiste em analytics_events).
  return trackNavigationError(error, {
    componentStack: extra?.componentStack,
    ...payload,
  } as never);
}

/**
 * Loga contexto de diagnóstico sem erro (breadcrumb) — útil para reproduzir
 * o estado exato antes de uma falha React #300.
 */
export function logPrayerDiagnostics(label: string, ctx: PrayerErrorContext): void {
  if (typeof window === "undefined") return;
  // eslint-disable-next-line no-console
  console.debug("[PrayerEngine:diag]", label, ctx);
  Sentry.addBreadcrumb({
    category: "prayer-engine",
    level: "info",
    message: label,
    data: ctx as Record<string, unknown>,
  });
}

function extractReactErrorCode(message: string): string | null {
  // "Minified React error #300" ou "Error: Minified React error #185"
  const m = message.match(/Minified React error #(\d+)/);
  return m ? `#${m[1]}` : null;
}

export function serializeSearchParams(sp: URLSearchParams): Record<string, string> {
  const out: Record<string, string> = {};
  sp.forEach((v, k) => {
    // Sanitiza tokens conhecidos.
    if (/token|secret|key|password/i.test(k)) {
      out[k] = "[REDACTED]";
    } else {
      out[k] = v;
    }
  });
  return out;
}

// Prefetch lazy-loaded route chunks on hover/touch
const prefetched = new Set<string>();

const routeImports: Record<string, () => Promise<any>> = {
  "/dashboard": () => import("@/components/cathedra/Dashboard"),
  "/hoje": () => import("@/components/cathedra/HojePage"),
  "/jornadas": () => import("@/components/cathedra/JornadasPage"),
  "/biblioteca": () => import("@/components/cathedra/BibliotecaPage"),
  "/community": () => import("@/components/cathedra/CommunityPage"),
  "/profile": () => import("@/components/cathedra/ProfilePage"),
  "/bible": () => import("@/components/cathedra/Bible"),
  "/catechism": () => import("@/components/cathedra/Catechism"),
  "/santos": () => import("@/components/cathedra/Saints"),
  "/liturgia": () => import("@/components/cathedra/LiturgiaPage"),
  "/study": () => import("@/components/cathedra/StudyMode"),
  "/rosary": () => import("@/components/cathedra/Rosary"),
  "/oracao": () => import("@/components/cathedra/PrayerPage"),
  "/login": () => import("@/components/cathedra/Auth"),
  "/auth": () => import("@/components/cathedra/Auth"),
  "/magisterium": () => import("@/components/cathedra/Magisterium"),
  "/diagnostico": () => import("@/components/cathedra/DiagnosticoPage"),
  "/viacrucis": () => import("@/components/cathedra/ViaCrucis"),
  "/checkout": () => import("@/components/cathedra/CheckoutPage"),
  "/logos": () => import("@/components/cathedra/LogosAI"),
};

export function prefetchRoute(route: string) {
  if (prefetched.has(route)) return;
  const loader = routeImports[route];
  if (loader) {
    prefetched.add(route);
    const doLoad = () => loader().catch(() => prefetched.delete(route));
    if ("requestIdleCallback" in window) {
      (window as any).requestIdleCallback(doLoad);
    } else {
      setTimeout(doLoad, 100);
    }
  }
}

// Prefetch core modules after initial page load
export function prefetchCoreModules() {
  // Skip on save-data mode
  if ("connection" in navigator && (navigator as any).connection?.saveData) return;

  const coreRoutes = [
    "/dashboard",
    "/hoje",
    "/bible",
    "/catechism",
    "/jornadas",
    "/biblioteca",
    "/community",
    "/profile",
  ];
  let i = 0;
  const prefetchNext = () => {
    if (i < coreRoutes.length) {
      prefetchRoute(coreRoutes[i++]);
      if ("requestIdleCallback" in window) {
        (window as any).requestIdleCallback(prefetchNext);
      } else {
        setTimeout(prefetchNext, 300);
      }
    }
  };

  // Start after 3s to not compete with initial load
  setTimeout(() => {
    if ("requestIdleCallback" in window) {
      (window as any).requestIdleCallback(prefetchNext);
    } else {
      prefetchNext();
    }
  }, 3000);
}

// Prefetch essential data for offline availability
export async function prefetchEssentialContent() {
  const { supabase } = await import("@/lib/db");

  // Check if Supabase is healthy before syncing
  try {
    const { error } = await supabase.from("profiles").select("id").limit(1).single();
    if (error) throw error;
  } catch (e) {
    console.warn("Sync aborted: Supabase unreachable");
    return;
  }

  // 1) Liturgia do dia (respeita o guard `litcal_no_prefetch=1`)
  const today = new Date();
  const day = today.getDate();
  const month = today.getMonth() + 1;

  const { cacheLiturgy } = await import("./offlineCache");
  const { isLiturgicalPrefetchDisabled } = await import("./litcalPrefetchGuard");

  if (!isLiturgicalPrefetchDisabled()) {
    try {
      const { data } = await supabase.functions.invoke("liturgical-calendar", {
        body: { action: "readings", day, month },
      });
      if (data) await cacheLiturgy(today.toDateString(), data);
    } catch (e) {
      console.warn("Auto-sync failed for liturgy:", e);
    }
  }

  // 2) Prefetch next Catechism paragraph if we have a current one
  try {
    const stored = localStorage.getItem("cathedra_last_catechism_para");
    if (stored) {
      const p = parseInt(stored);
      const { fetchCatechismParagraph } = await import("@/hooks/useCatechismParagraph");
      if (p < 2865) await fetchCatechismParagraph(p + 1);
    }
  } catch (e) {
    console.warn("Prefetch error for last catechism paragraph:", e);
  }
}

import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export interface DonationRow {
  created_at: string | null;
  amount: number;
  status: string | null;
  description: string | null;
  payment_id: string | null;
  is_donation: boolean | null;
}

export interface AuditRow {
  created_at: string | null;
  event_type: string;
  path: string | null;
  metadata: any;
}

interface ExportInput {
  userName: string;
  userEmail: string;
  donations: DonationRow[];
  audit: AuditRow[];
}

const fmtDate = (iso: string | null) => (iso ? new Date(iso).toLocaleString("pt-BR") : "—");

const fmtBRL = (v: number) =>
  new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v / 100);

export async function exportProfilePdf({ userName, userEmail, donations, audit }: ExportInput) {
  const doc = new jsPDF({ unit: "pt", format: "a4" });
  const now = new Date().toLocaleString("pt-BR");

  // Cabeçalho
  doc.setFont("helvetica", "bold");
  doc.setFontSize(18);
  doc.text("Cathedra — Relatório Pessoal", 40, 50);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(`Usuário: ${userName || "—"}  ·  ${userEmail}`, 40, 68);
  doc.text(`Gerado em: ${now}`, 40, 82);

  // Doações
  const donationsStartY = 120;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(13);
  doc.text("Histórico de Doações & Apoio", 40, donationsStartY - 8);

  autoTable(doc, {
    startY: donationsStartY,
    head: [["Data", "Descrição", "Valor", "Status", "Tipo", "ID Pagamento"]],
    body: donations.length
      ? donations.map((d) => [
          fmtDate(d.created_at),
          d.description || "—",
          fmtBRL(d.amount || 0),
          d.status || "—",
          d.is_donation ? "Doação" : "Assinatura",
          d.payment_id || "—",
        ])
      : [["—", "Nenhuma doação registrada", "—", "—", "—", "—"]],
    styles: { fontSize: 9, cellPadding: 4 },
    headStyles: { fillColor: [11, 31, 58], textColor: 255 },
    theme: "striped",
  });

  // Auditoria
  const afterDonations = (doc as any).lastAutoTable.finalY + 24;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(13);
  doc.text("Trilha de Auditoria (Premium)", 40, afterDonations);

  autoTable(doc, {
    startY: afterDonations + 8,
    head: [["Data", "Evento", "Rota", "Metadata"]],
    body: audit.length
      ? audit.map((a) => [
          fmtDate(a.created_at),
          a.event_type,
          a.path || "—",
          a.metadata ? JSON.stringify(a.metadata).slice(0, 80) : "—",
        ])
      : [["—", "Nenhum evento registrado", "—", "—"]],
    styles: { fontSize: 8, cellPadding: 4 },
    headStyles: { fillColor: [11, 31, 58], textColor: 255 },
    theme: "striped",
  });

  // Rodapé
  const pageCount = (doc as any).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(120);
    doc.text(
      `Cathedra Digital · pág. ${i}/${pageCount} · Documento gerado localmente`,
      40,
      doc.internal.pageSize.getHeight() - 24,
    );
  }

  const stamp = new Date().toISOString().slice(0, 10);
  doc.save(`cathedra-relatorio-${stamp}.pdf`);
}

import { supabase } from "@/lib/db";
import { detectCategories } from "./smartRouter";

export interface EmotionRecord {
  emotion_type: string;
  score: number;
  context_text?: string;
  source_feature: string;
}

export interface PsychologicalProfile {
  dominant_emotion?: string;
  mood_history: string[];
  traits: Record<string, any>;
  last_updated: string;
}

/**
 * Persists detected emotions and updates the user's psychological profile.
 */
export async function saveUserPsychology(
  userId: string,
  text: string,
  source: string,
): Promise<void> {
  if (!userId || !text.trim()) return;

  const scores = detectCategories(text);

  // Only save if there's at least one match
  const topCategory = Object.entries(scores)
    .sort(([, a], [, b]) => b - a)
    .filter(([, score]) => score > 0)[0];

  if (!topCategory) return;

  const [emotionType, score] = topCategory;

  try {
    // 1. Log the individual emotion detection
    const { error: logError } = await supabase.from("user_emotions").insert({
      user_id: userId,
      emotion_type: emotionType,
      score,
      context_text: text.slice(0, 1000), // Cap length
      source_feature: source,
    });

    if (logError) throw logError;

    // 2. Fetch current profile or create it
    const { data: profile, error: fetchError } = await supabase
      .from("user_psychological_profiles")
      .select("*")
      .eq("user_id", userId)
      .maybeSingle();

    if (fetchError) throw fetchError;

    const moodHistory = profile?.mood_history ? [...(profile.mood_history as string[])] : [];
    moodHistory.push(emotionType);
    if (moodHistory.length > 20) moodHistory.shift(); // Keep last 20

    // Update traits based on frequency
    const traits = profile?.traits ? { ...(profile.traits as Record<string, any>) } : {};
    traits[emotionType] = (traits[emotionType] || 0) + 1;

    // Determine dominant emotion from history
    const counts = moodHistory.reduce(
      (acc, val) => {
        acc[val] = (acc[val] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>,
    );

    const dominantEmotion = Object.entries(counts).sort(([, a], [, b]) => b - a)[0][0];

    // 3. Update the aggregated profile
    const { error: upsertError } = await supabase.from("user_psychological_profiles").upsert(
      {
        user_id: userId,
        dominant_emotion: dominantEmotion,
        mood_history: moodHistory,
        traits,
        last_updated: new Date().toISOString(),
      },
      { onConflict: "user_id" },
    );

    if (upsertError) throw upsertError;

    console.log(`Psychological profile updated for user ${userId}: dominant=${dominantEmotion}`);
  } catch (err) {
    console.error("Error saving user psychology:", err);
  }
}

/**
 * Hook or function to fetch the profile
 */
export async function getUserPsychology(userId: string): Promise<PsychologicalProfile | null> {
  const { data, error } = await supabase
    .from("user_psychological_profiles")
    .select("*")
    .eq("user_id", userId)
    .maybeSingle();

  if (error) {
    console.error("Error fetching user psychology:", error);
    return null;
  }

  return data as PsychologicalProfile | null;
}

/**
 * Compatibility shim: implements the react-router-dom v6 API surface used by
 * the legacy app on top of the TanStack Router history/location.
 * Supports nested <Routes>/<Route> trees, path params, splats, relative
 * navigation, search params and basename.
 */
import * as React from "react";
import { useRouter, useRouterState, type AnyRouter } from "@tanstack/react-router";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface RouteDef {
  path?: string;
  index?: boolean;
  element?: React.ReactNode;
  children?: RouteDef[];
}

interface BranchMeta {
  route: RouteDef;
  pathnameBase: string;
}

interface MatchedBranch {
  routesMeta: BranchMeta[];
  params: Record<string, string>;
}

interface LocationShape {
  pathname: string;
  search: string;
  hash: string;
  state: unknown;
  key: string;
}

interface RouteContextValue {
  outlet: React.ReactNode;
  params: Record<string, string>;
  pathnameBase: string;
}

interface RouterContextValue {
  location: LocationShape;
  basename: string;
  navigate: (to: string | number, options?: NavigateOptions) => void;
  router: AnyRouter;
}

interface NavigateOptions {
  replace?: boolean;
  state?: unknown;
}

const RouterCtx = React.createContext<RouterContextValue | null>(null);
const RouteCtx = React.createContext<RouteContextValue>({
  outlet: null,
  params: {},
  pathnameBase: "/",
});

// ---------------------------------------------------------------------------
// Path utilities
// ---------------------------------------------------------------------------

function stripBasename(pathname: string, basename: string): string {
  if (!basename || basename === "/") return pathname;
  if (pathname === basename) return "/";
  if (pathname.startsWith(basename + "/")) return pathname.slice(basename.length);
  return pathname;
}

function joinPaths(paths: string[]): string {
  return paths.join("/").replace(/\/\/+/g, "/");
}

function normalizePathname(pathname: string): string {
  let p = pathname.replace(/\/+/g, "/");
  if (p.length > 1 && p.endsWith("/")) p = p.slice(0, -1);
  return p || "/";
}

/** Resolve a possibly-relative `to` against a route pathname base. */
function resolvePath(
  to: string,
  fromPathname: string,
): { pathname: string; search: string; hash: string } {
  const hashIdx = to.indexOf("#");
  let hash = "";
  if (hashIdx >= 0) {
    hash = to.slice(hashIdx);
    to = to.slice(0, hashIdx);
  }
  const searchIdx = to.indexOf("?");
  let search = "";
  if (searchIdx >= 0) {
    search = to.slice(searchIdx);
    to = to.slice(0, searchIdx);
  }
  let pathname: string;
  if (to.startsWith("/")) {
    pathname = to;
  } else if (to === "") {
    pathname = fromPathname;
  } else {
    const segments = fromPathname.replace(/\/+$/, "").split("/");
    for (const seg of to.split("/")) {
      if (seg === "..") segments.pop();
      else if (seg !== "." && seg !== "") segments.push(seg);
    }
    pathname = segments.join("/") || "/";
    if (!pathname.startsWith("/")) pathname = "/" + pathname;
  }
  return { pathname: normalizePathname(pathname), search, hash };
}

/** Compile a path pattern like `admin/:id/*` into a regex. */
function compilePath(pattern: string, end: boolean): { regexp: RegExp; paramNames: string[] } {
  const paramNames: string[] = [];
  let source = "^";
  const trimmed = pattern.replace(/^\/*/, "/");
  const segments = trimmed.split("/").filter((s) => s !== "");
  for (const segment of segments) {
    source += "/";
    if (segment === "*") {
      paramNames.push("*");
      source += "(.*)";
      end = false;
      break;
    } else if (segment.startsWith(":")) {
      paramNames.push(segment.slice(1));
      source += "([^/]+)";
    } else {
      source += segment.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    }
  }
  if (segments.length === 0) source += "/";
  source += end ? "/?$" : "(?:\\/|$)";
  return { regexp: new RegExp(source, "i"), paramNames };
}

function scoreSegment(segment: string): number {
  if (segment === "*") return -2;
  if (segment.startsWith(":")) return 3;
  if (segment === "") return 0;
  return 10;
}

function flattenBranches(
  routes: RouteDef[],
  parentPath = "",
  parentRoutes: BranchMeta[] = [],
): Array<{ score: number; routesMeta: BranchMeta[]; path: string }> {
  const branches: Array<{ score: number; routesMeta: BranchMeta[]; path: string }> = [];
  for (const route of routes) {
    const path = route.path ?? "";
    const joinedPath = path.startsWith("/") ? path : joinPaths([parentPath, path]);
    const meta: BranchMeta[] = [
      ...parentRoutes,
      { route, pathnameBase: joinedPath.replace(/\/\*$/, "") || "/" },
    ];
    if (route.children && route.children.length > 0) {
      branches.push(...flattenBranches(route.children, joinedPath, meta));
    }
    if (
      route.index ||
      (route.element != null && (!route.children || route.children.length === 0))
    ) {
      const effectivePath = route.index ? parentPath : joinedPath;
      const score =
        effectivePath
          .split("/")
          .filter(Boolean)
          .reduce((acc, seg) => acc + scoreSegment(seg), 0) + (route.index ? 2 : 0);
      branches.push({
        score,
        routesMeta: route.index
          ? parentRoutes.length
            ? [...parentRoutes, { route, pathnameBase: parentPath || "/" }]
            : meta
          : meta,
        path: effectivePath || "/",
      });
    }
  }
  return branches;
}

function matchBranches(routes: RouteDef[], pathname: string): MatchedBranch | null {
  const branches = flattenBranches(routes);
  branches.sort((a, b) => b.score - a.score);
  const target = normalizePathname(pathname);
  for (const branch of branches) {
    const lastMeta = branch.routesMeta[branch.routesMeta.length - 1];
    const isSplat = branch.path.endsWith("/*") || branch.path === "*";
    const { regexp, paramNames } = compilePath(branch.path, !isSplat);
    const match = target.match(regexp);
    if (!match) continue;
    // For non-splat branches, require a full match.
    if (!isSplat && match[0].replace(/\/$/, "") !== target && branch.path !== target) {
      // full-match enforced by end regex; this is a safety check
    }
    const params: Record<string, string> = {};
    paramNames.forEach((name, i) => {
      params[name] = decodeURIComponent(match[i + 1] ?? "");
    });
    void lastMeta;
    return { routesMeta: branch.routesMeta, params };
  }
  return null;
}

// ---------------------------------------------------------------------------
// Router provider
// ---------------------------------------------------------------------------

function useRouterContext(): RouterContextValue {
  const ctx = React.useContext(RouterCtx);
  if (!ctx) throw new Error("rr-compat: router context missing");
  return ctx;
}

export function BrowserRouter({
  children,
  basename = "/",
}: {
  children?: React.ReactNode;
  basename?: string;
  /** Aceito por compatibilidade com MemoryRouter (ignorado). */
  initialEntries?: string[];
}) {
  const router = useRouter();
  const routerState = useRouterState({ select: (s) => s.location });
  const rawPathname = routerState.pathname;
  const pathname = stripBasename(rawPathname, basename);

  const location: LocationShape = React.useMemo(
    () => ({
      pathname,
      search: routerState.searchStr ?? "",
      hash: routerState.hash ? `#${routerState.hash}` : "",
      state: routerState.state,
      key: routerState.href,
    }),
    [pathname, routerState.searchStr, routerState.hash, routerState.state, routerState.href],
  );

  const navigate = React.useCallback(
    (to: string | number, options?: NavigateOptions) => {
      if (typeof to === "number") {
        if (to === -1) router.history.back();
        else if (to === 1) router.history.forward();
        else router.history.go(to);
        return;
      }
      const resolved = resolvePath(to, pathname);
      const href =
        normalizePathname(joinPaths([basename === "/" ? "" : basename, resolved.pathname])) +
        resolved.search +
        resolved.hash;
      void router.navigate({
        to: href as never,
        replace: options?.replace,
        state: options?.state as never,
        resetScroll: true,
      });
    },
    [router, basename, pathname],
  );

  const value = React.useMemo(
    () => ({ location, basename, navigate, router }),
    [location, basename, navigate, router],
  );

  return <RouterCtx.Provider value={value}>{children}</RouterCtx.Provider>;
}

export const MemoryRouter = BrowserRouter;
export const HashRouter = BrowserRouter;

// ---------------------------------------------------------------------------
// Hooks
// ---------------------------------------------------------------------------

export function useLocation(): LocationShape {
  return useRouterContext().location;
}

export type NavigateFunction = (to: string | number, options?: NavigateOptions) => void;

export function useNavigate(): NavigateFunction {
  return useRouterContext().navigate;
}

export function useParams<
  Params extends Record<string, string> = Record<string, string>,
>(): Params {
  return React.useContext(RouteCtx).params as Params;
}

export type SetURLSearchParams = (
  init:
    | URLSearchParams
    | string
    | Record<string, string>
    | ((prev: URLSearchParams) => URLSearchParams | string | Record<string, string>),
  options?: NavigateOptions,
) => void;

export function useSearchParams(
  defaultInit?: URLSearchParams | string,
): [URLSearchParams, SetURLSearchParams] {
  const { location, navigate } = useRouterContext();
  const params = React.useMemo(
    () => new URLSearchParams(location.search || (defaultInit ? defaultInit.toString() : "")),
    [location.search, defaultInit],
  );
  const setParams = React.useCallback<SetURLSearchParams>(
    (init, options) => {
      const resolved =
        typeof init === "function" ? init(new URLSearchParams(location.search)) : init;
      const next =
        typeof resolved === "string"
          ? resolved
          : new URLSearchParams(resolved as Record<string, string>).toString();
      navigate(`${location.pathname}?${next}`, options);
    },
    [navigate, location.pathname, location.search],
  );
  return [params, setParams];
}

export function useNavigationType(): string {
  return "POP";
}

export function matchPath(
  pattern: string,
  pathname: string,
): { params: Record<string, string> } | null {
  const end = !pattern.endsWith("*");
  const { regexp, paramNames } = compilePath(pattern, end);
  const match = normalizePathname(pathname).match(regexp);
  if (!match) return null;
  const params: Record<string, string> = {};
  paramNames.forEach((name, i) => {
    params[name] = decodeURIComponent(match[i + 1] ?? "");
  });
  return { params };
}

