import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/lib/db";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RefreshCw, RotateCcw, Play, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { CATECHISM_RANGES, rangeForParagraph, normalizeErrorKey } from "@/lib/catechismRanges";

type QueueStatus = "pending" | "processing" | "completed" | "error";

type QueueRow = {
  id: string;
  paragraph: number;
  status: QueueStatus;
  attempts: number;
  last_error: string | null;
  requested_at: string;
  processed_at: string | null;
  next_attempt_at: string | null;
  attempts_log: Array<{
    attempt: number;
    started_at: string;
    duration_ms: number;
    status: "completed" | "error";
    error?: string;
    next_attempt_at?: string | null;
    gave_up?: boolean;
    source?: string;
  }> | null;
};

const STATUS_LABEL: Record<QueueStatus, string> = {
  pending: "Pendente",
  processing: "Processando",
  completed: "Concluído",
  error: "Erro",
};

const statusVariant: Record<QueueStatus, "default" | "secondary" | "destructive" | "outline"> = {
  pending: "secondary",
  processing: "outline",
  completed: "default",
  error: "destructive",
};

const ALL_STATUSES: QueueStatus[] = ["pending", "processing", "completed", "error"];

export default function CatechismImportQueuePage() {
  const [rows, setRows] = useState<QueueRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [running, setRunning] = useState(false);
  const [statusFilter, setStatusFilter] = useState<"all" | QueueStatus>("all");
  const [selected, setSelected] = useState<Set<string>>(new Set());

  const load = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("catechism_import_queue")
      .select("*")
      .order("requested_at", { ascending: false })
      .limit(500);
    if (error) {
      toast.error("Falha ao carregar fila", { description: error.message });
    } else if (data) {
      setRows(data as unknown as QueueRow[]);
      setSelected(new Set());
    }
    setLoading(false);
  };

  useEffect(() => {
    load();
    // Auto-refresh a cada 10s quando houver itens em processamento/pendentes
    const id = setInterval(() => {
      setRows((prev) => {
        const hasLive = prev.some((r) => r.status === "pending" || r.status === "processing");
        if (hasLive) load();
        return prev;
      });
    }, 10_000);
    return () => clearInterval(id);
  }, []);

  const counts = useMemo(() => {
    const c: Record<QueueStatus, number> = { pending: 0, processing: 0, completed: 0, error: 0 };
    for (const r of rows) c[r.status] = (c[r.status] ?? 0) + 1;
    return c;
  }, [rows]);

  const avgProcessingMs = useMemo(() => {
    const completed = rows.filter((r) => r.status === "completed" && r.processed_at);
    if (!completed.length) return null;
    const total = completed.reduce(
      (acc, r) => acc + (new Date(r.processed_at!).getTime() - new Date(r.requested_at).getTime()),
      0,
    );
    return Math.round(total / completed.length);
  }, [rows]);

  const avgAttemptDurationMs = useMemo(() => {
    let n = 0;
    let sum = 0;
    for (const r of rows) {
      for (const a of r.attempts_log ?? []) {
        if (typeof a.duration_ms === "number") {
          sum += a.duration_ms;
          n += 1;
        }
      }
    }
    return n > 0 ? Math.round(sum / n) : null;
  }, [rows]);

  const errorGroups = useMemo(() => {
    const groups = new Map<
      string,
      { key: string; count: number; paragraphs: number[]; sample: string }
    >();
    for (const r of rows) {
      if (r.status !== "error") continue;
      const key = normalizeErrorKey(r.last_error);
      const g = groups.get(key) ?? { key, count: 0, paragraphs: [], sample: r.last_error ?? key };
      g.count += 1;
      g.paragraphs.push(r.paragraph);
      groups.set(key, g);
    }
    return [...groups.values()].sort((a, b) => b.count - a.count);
  }, [rows]);

  const rangeCounts = useMemo(() => {
    const map = new Map<
      string,
      {
        label: string;
        part: string;
        total: number;
        error: number;
        completed: number;
        pending: number;
      }
    >();
    for (const r of rows) {
      const range = rangeForParagraph(r.paragraph);
      if (!range) continue;
      const cur = map.get(range.label) ?? {
        label: range.label,
        part: range.part,
        total: 0,
        error: 0,
        completed: 0,
        pending: 0,
      };
      cur.total += 1;
      if (r.status === "error") cur.error += 1;
      else if (r.status === "completed") cur.completed += 1;
      else cur.pending += 1;
      map.set(range.label, cur);
    }
    return CATECHISM_RANGES.map((r) => map.get(r.label)).filter((x): x is NonNullable<typeof x> =>
      Boolean(x),
    );
  }, [rows]);

  const filtered = useMemo(
    () => (statusFilter === "all" ? rows : rows.filter((r) => r.status === statusFilter)),
    [rows, statusFilter],
  );

  const toggleSelect = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });

  const requeueIds = async (ids: string[]) => {
    if (!ids.length) return;
    const { error } = await supabase
      .from("catechism_import_queue")
      .update({
        status: "pending",
        last_error: null,
        next_attempt_at: null,
        updated_at: new Date().toISOString(),
      })
      .in("id", ids);
    if (error) {
      toast.error("Falha ao re-enfileirar", { description: error.message });
      return;
    }
    toast.success(`${ids.length} item(ns) re-enfileirado(s).`);
    await load();
  };

  const runWorker = async (paragraphs?: number[]) => {
    setRunning(true);
    try {
      const { data, error } = await supabase.functions.invoke("catechism-import-worker", {
        body: paragraphs?.length ? { paragraphs } : { limit: 20 },
      });
      if (error) throw error;
      toast.success("Worker executado", {
        description: `${(data as any)?.completed ?? 0} concluído(s) · ${(data as any)?.errors ?? 0} erro(s)`,
      });
      await load();
    } catch (err: any) {
      toast.error("Falha ao executar worker", { description: err?.message ?? String(err) });
    } finally {
      setRunning(false);
    }
  };

  const requeueAllErrors = () => {
    const ids = rows.filter((r) => r.status === "error").map((r) => r.id);
    if (!ids.length) {
      toast.info("Nenhum item com erro.");
      return;
    }
    requeueIds(ids);
  };

  const requeueSelected = () => requeueIds(Array.from(selected));

  const formatMs = (ms: number | null) => {
    if (ms == null) return "—";
    if (ms < 1000) return `${ms}ms`;
    if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
    return `${(ms / 60_000).toFixed(1)}min`;
  };

  return (
    <div className="container mx-auto max-w-5xl px-4 py-8 space-y-6">
      <header className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-semibold">Fila de Importação — Catecismo</h1>
          <p className="text-sm text-muted-foreground">
            Parágrafos solicitados por leitores que ainda não constam no banco oficial.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={load} disabled={loading}>
            <RefreshCw className="mr-2 h-4 w-4" /> Atualizar
          </Button>
          <Button size="sm" onClick={() => runWorker()} disabled={running}>
            <Play className="mr-2 h-4 w-4" /> Rodar worker (20)
          </Button>
        </div>
      </header>

      <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
        {ALL_STATUSES.map((s) => (
          <Card key={s}>
            <CardContent className="pt-6">
              <div className="text-xs uppercase text-muted-foreground">{STATUS_LABEL[s]}</div>
              <div className="text-2xl font-semibold">{counts[s]}</div>
            </CardContent>
          </Card>
        ))}
        <Card>
          <CardContent className="pt-6">
            <div className="text-xs uppercase text-muted-foreground">Tempo médio total</div>
            <div className="text-2xl font-semibold">{formatMs(avgProcessingMs)}</div>
            <div className="text-[10px] text-muted-foreground">enfileiramento → conclusão</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="text-xs uppercase text-muted-foreground">Tempo médio/tentativa</div>
            <div className="text-2xl font-semibold">{formatMs(avgAttemptDurationMs)}</div>
            <div className="text-[10px] text-muted-foreground">duração do fetch</div>
          </CardContent>
        </Card>
      </div>

      {errorGroups.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <AlertTriangle className="h-4 w-4 text-destructive" />
              Erros agrupados ({errorGroups.length})
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {errorGroups.map((g) => (
              <div
                key={g.key}
                className="flex items-start justify-between gap-3 rounded-md border p-3"
              >
                <div className="min-w-0 flex-1">
                  <div className="text-sm font-medium truncate" title={g.sample}>
                    {g.sample}
                  </div>
                  <div className="text-xs text-muted-foreground mt-1">
                    {g.count} ocorrência(s) · §{g.paragraphs.slice(0, 8).join(", §")}
                    {g.paragraphs.length > 8 ? ` +${g.paragraphs.length - 8}` : ""}
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() =>
                      requeueIds(
                        rows
                          .filter(
                            (r) =>
                              r.status === "error" && normalizeErrorKey(r.last_error) === g.key,
                          )
                          .map((r) => r.id),
                      )
                    }
                  >
                    <RotateCcw className="mr-2 h-3 w-3" />
                    Re-enfileirar
                  </Button>
                  <Button
                    size="sm"
                    onClick={() => runWorker(g.paragraphs.slice(0, 20))}
                    disabled={running}
                  >
                    <Play className="mr-2 h-3 w-3" />
                    Reprocessar
                  </Button>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Contagem por faixa (parte / capítulo)</CardTitle>
        </CardHeader>
        <CardContent>
          {rangeCounts.length === 0 ? (
            <p className="text-sm text-muted-foreground">Nenhuma solicitação registrada ainda.</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {rangeCounts.map((r) => (
                <div
                  key={r.label}
                  className="flex items-center justify-between rounded border px-3 py-2 text-sm"
                >
                  <div className="min-w-0">
                    <div className="truncate font-medium">{r.label}</div>
                    <div className="text-[10px] uppercase text-muted-foreground">{r.part}</div>
                  </div>
                  <div className="flex items-center gap-2 text-xs shrink-0">
                    <span title="Total">{r.total}</span>
                    {r.completed > 0 && (
                      <Badge variant="default" className="h-5">
                        {r.completed} ok
                      </Badge>
                    )}
                    {r.pending > 0 && (
                      <Badge variant="secondary" className="h-5">
                        {r.pending} pend
                      </Badge>
                    )}
                    {r.error > 0 && (
                      <Badge variant="destructive" className="h-5">
                        {r.error} err
                      </Badge>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between gap-3 flex-wrap">
          <CardTitle className="text-base">Solicitações</CardTitle>
          <div className="flex items-center gap-2">
            <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v as any)}>
              <SelectTrigger className="h-8 w-40 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos ({rows.length})</SelectItem>
                {ALL_STATUSES.map((s) => (
                  <SelectItem key={s} value={s}>
                    {STATUS_LABEL[s]} ({counts[s]})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              variant="outline"
              size="sm"
              onClick={requeueSelected}
              disabled={selected.size === 0}
            >
              <RotateCcw className="mr-2 h-4 w-4" />
              Re-enfileirar ({selected.size})
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={requeueAllErrors}
              disabled={counts.error === 0}
            >
              <RotateCcw className="mr-2 h-4 w-4" />
              Re-enfileirar erros
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 6 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full" />
              ))}
            </div>
          ) : filtered.length === 0 ? (
            <p className="text-sm text-muted-foreground">Nenhuma solicitação nesse filtro.</p>
          ) : (
            <div className="divide-y">
              {filtered.map((r) => {
                const lastLog = r.attempts_log?.[r.attempts_log.length - 1];
                const isRetryable = r.status === "error" || r.status === "pending";
                return (
                  <div key={r.id} className="flex items-center justify-between py-2 gap-3">
                    <div className="flex items-center gap-3 min-w-0">
                      <input
                        type="checkbox"
                        checked={selected.has(r.id)}
                        onChange={() => toggleSelect(r.id)}
                        aria-label={`Selecionar §${r.paragraph}`}
                        className="h-4 w-4"
                      />
                      <span className="font-mono text-sm w-16">§{r.paragraph}</span>
                      <Badge variant={statusVariant[r.status]}>{STATUS_LABEL[r.status]}</Badge>
                      {r.attempts > 0 && (
                        <span className="text-xs text-muted-foreground">{r.attempts} tent.</span>
                      )}
                      {r.next_attempt_at && r.status === "error" && (
                        <span className="text-[10px] text-muted-foreground">
                          próx: {new Date(r.next_attempt_at).toLocaleTimeString("pt-BR")}
                        </span>
                      )}
                    </div>
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="text-xs text-muted-foreground text-right max-w-[320px] truncate">
                        {r.last_error
                          ? r.last_error
                          : lastLog
                            ? `${formatMs(lastLog.duration_ms)} · ${new Date(lastLog.started_at).toLocaleString("pt-BR")}`
                            : new Date(r.requested_at).toLocaleString("pt-BR")}
                      </div>
                      {isRetryable && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => runWorker([r.paragraph])}
                          disabled={running}
                          title="Executar worker para este parágrafo agora"
                        >
                          <Play className="h-3 w-3" />
                        </Button>
                      )}
                      {r.status === "error" && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => requeueIds([r.id])}
                          title="Re-enfileirar (limpa backoff)"
                        >
                          <RotateCcw className="h-3 w-3" />
                        </Button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useIsAdmin } from "@/hooks/useIsAdmin";
import { Button } from "@/components/ui/button";
import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Icons } from "@/constants";
import { supabase } from "@/lib/db";
import { toast } from "sonner";
import { useAuth } from "@/hooks/useAuth";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

interface CacheEntry {
  id: string;
  paragraph: number;
  content: string;
  texto_base?: string;
  explicacao?: string;
  interpretacao_profunda?: string;
  aplicacao_pratica?: string;
  reflexao_final?: string;
  exercicio?: string;
  status: "generated" | "error_402" | "error" | "official" | "static";
  last_error: string | null;
  retry_count: number;
  created_at: string;
}

interface ExecutionLog {
  id: string;
  paragraph: number;
  status: string;
  duration_ms: number;
  error_message: string | null;
  admin_id: string | null;
  created_at: string;
}

const CatechismDebug: React.FC = () => {
  const { profile } = useAuth();
  const [cache, setCache] = useState<CacheEntry[]>([]);
  const [logs, setLogs] = useState<ExecutionLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [isReprocessing, setIsReprocessing] = useState(false);
  const [filter, setFilter] = useState<"all" | "generated" | "error" | "incomplete">("all");
  const [view, setView] = useState<"cache" | "logs" | "integrity">("cache");
  const [dateRange, setDateRange] = useState({ start: "", end: "" });
  const [integrityData, setIntegrityData] = useState<any[]>([]);

  const { isAdmin } = useIsAdmin();

  const loadData = async () => {
    setLoading(true);
    const [cacheRes, logsRes] = await Promise.all([
      supabase.from("catechism_cache").select("*").order("paragraph", { ascending: true }),
      supabase
        .from("catechism_execution_logs")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(100),
    ]);

    if (cacheRes.error) toast.error("Erro ao carregar cache");
    else setCache(cacheRes.data as CacheEntry[]);

    if (logsRes.error) console.error("Erro ao carregar logs:", logsRes.error);
    else setLogs(logsRes.data as ExecutionLog[]);

    setLoading(false);
  };

  useEffect(() => {
    if (isAdmin) loadData();
  }, [isAdmin]);

  const reprocessAllErrors = async () => {
    if (!isAdmin) return;
    const pending = cache.filter((c) => c.status === "error_402" || c.status === "error");
    if (pending.length === 0) {
      toast.info("Nenhum parágrafo com erro para reprocessar");
      return;
    }

    setIsReprocessing(true);
    let successCount = 0;
    let failCount = 0;

    toast.loading(`Reprocessando ${pending.length} parágrafos...`, { id: "reprocess" });

    // Process in chunks to respect concurrency limit
    const CHUNK_SIZE = 5;
    for (let i = 0; i < pending.length; i += CHUNK_SIZE) {
      const chunk = pending.slice(i, i + CHUNK_SIZE);
      await Promise.all(
        chunk.map(async (item) => {
          if (item.retry_count >= 5) return;
          try {
            const { data, error } = await supabase.functions.invoke("catechism-text", {
              body: { paragraph: item.paragraph, action: "reprocess" },
            });
            if (!error && (data?.status === "generated" || data?.status === "official"))
              successCount++;
            else failCount++;
          } catch {
            failCount++;
          }
        }),
      );
    }

    toast.dismiss("reprocess");
    toast.success(`Concluído: ${successCount} reprocessados, ${failCount} falharam.`);
    setIsReprocessing(false);
    loadData();
  };

  const reprocessIncomplete = async () => {
    if (!isAdmin) return;
    const incomplete = cache.filter((c) => {
      const isActuallyIncomplete = !c.content || c.content.length < 50; // Basic check, will be refined in backend
      // In a real scenario, we'd check all fields, but frontend CacheEntry only has basic fields
      // The backend 'fix_incomplete' will do the deep check.
      return isActuallyIncomplete || c.status === "error" || c.status === "error_402";
    });

    if (incomplete.length === 0) {
      toast.info("Nenhum parágrafo incompleto para reprocessar");
      return;
    }

    setIsReprocessing(true);
    let successCount = 0;
    let failCount = 0;

    toast.loading(`Reparando ${incomplete.length} parágrafos...`, { id: "reprocess-inc" });

    const CHUNK_SIZE = 5;
    for (let i = 0; i < incomplete.length; i += CHUNK_SIZE) {
      const chunk = incomplete.slice(i, i + CHUNK_SIZE);
      await Promise.all(
        chunk.map(async (item) => {
          try {
            const { data, error } = await supabase.functions.invoke("catechism-text", {
              body: { paragraph: item.paragraph, action: "fix_incomplete" },
            });
            if (!error && data?.status === "generated") successCount++;
            else failCount++;
          } catch {
            failCount++;
          }
        }),
      );
    }

    toast.dismiss("reprocess-inc");
    toast.success(`Integridade: ${successCount} corrigidos, ${failCount} falharam.`);
    setIsReprocessing(false);
    loadData();
  };

  const exportLogsToPDF = () => {
    if (logs.length === 0) return;

    let filtered = logs;
    if (dateRange.start)
      filtered = filtered.filter((l) => new Date(l.created_at) >= new Date(dateRange.start));
    if (dateRange.end)
      filtered = filtered.filter((l) => new Date(l.created_at) <= new Date(dateRange.end));

    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Catechism Execution Logs", 14, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Exportado em: ${new Date().toLocaleString()}`, 14, 30);

    const tableData = filtered.map((l) => [
      l.paragraph,
      l.status,
      `${l.duration_ms}ms`,
      l.error_message || "-",
      new Date(l.created_at).toLocaleDateString(),
    ]);

    autoTable(doc, {
      startY: 35,
      head: [["Parágrafo", "Status", "Duração", "Erro", "Data"]],
      body: tableData,
    });

    doc.save(`catechism_logs_${new Date().toISOString().split("T")[0]}.pdf`);
  };

  const exportIntegrityToCSV = () => {
    const headers = ["§", "Texto", "Explicação", "Profundo", "Aplicação", "Exercício"];
    const rows = cache.map((item) => [
      item.paragraph,
      item.content?.length > 50 ? "OK" : "Incompleto",
      item.explicacao?.length > 10 ? "OK" : "Incompleto",
      item.interpretacao_profunda?.length > 10 ? "OK" : "Incompleto",
      item.aplicacao_pratica?.length > 10 ? "OK" : "Incompleto",
      item.exercicio?.length > 10 ? "OK" : "Incompleto",
    ]);

    const csvContent =
      "data:text/csv;charset=utf-8," +
      headers.join(",") +
      "\n" +
      rows.map((e) => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute(
      "download",
      `catechism_integrity_${new Date().toISOString().split("T")[0]}.csv`,
    );
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportIntegrityToPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text("Relatório de Integridade do Catecismo", 14, 22);

    const tableData = cache
      .slice(0, 100)
      .map((item) => [
        item.paragraph,
        item.content?.length > 50 ? "OK" : "X",
        item.explicacao?.length > 10 ? "OK" : "X",
        item.interpretacao_profunda?.length > 10 ? "OK" : "X",
        item.aplicacao_pratica?.length > 10 ? "OK" : "X",
        item.exercicio?.length > 10 ? "OK" : "X",
      ]);

    autoTable(doc, {
      startY: 35,
      head: [["§", "Texto", "Explicação", "Profundo", "Aplicação", "Exercício"]],
      body: tableData,
    });

    doc.save(`catechism_integrity_${new Date().toISOString().split("T")[0]}.pdf`);
  };

  const clearInvalidCache = async () => {
    if (!isAdmin) return;
    const invalid = cache.filter((c) => c.content.length < 50);
    if (invalid.length === 0) {
      toast.info("Nenhum cache inválido detectado");
      return;
    }

    const { error } = await supabase
      .from("catechism_cache")
      .delete()
      .in(
        "id",
        invalid.map((c) => c.id),
      );

    if (!error) {
      toast.success(`${invalid.length} registros removidos`);
      loadData();
    }
  };

  const exportLogsToCSV = () => {
    if (logs.length === 0) return;

    let filtered = logs;
    if (dateRange.start)
      filtered = filtered.filter((l) => new Date(l.created_at) >= new Date(dateRange.start));
    if (dateRange.end)
      filtered = filtered.filter((l) => new Date(l.created_at) <= new Date(dateRange.end));

    const headers = ["ID", "Parágrafo", "Status", "Duração(ms)", "Erro", "AdminID", "Data"];
    const rows = filtered.map((l) => [
      l.id,
      l.paragraph,
      l.status,
      l.duration_ms,
      `"${(l.error_message || "").replace(/"/g, '""')}"`,
      l.admin_id || "",
      new Date(l.created_at).toISOString(),
    ]);

    const csvContent =
      "data:text/csv;charset=utf-8," +
      headers.join(",") +
      "\n" +
      rows.map((e) => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `catechism_logs_${new Date().toISOString().split("T")[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const filteredCache = cache.filter((item) => {
    if (filter === "all") return true;
    if (filter === "generated") return item.status === "generated";
    if (filter === "error") return item.status === "error_402" || item.status === "error";
    return true;
  });

  const stats = {
    total: cache.length,
    generated: cache.filter(
      (c) => c.status === "generated" || c.status === "official" || c.status === "static",
    ).length,
    pending: cache.filter((c) => c.status === "error_402" || c.status === "error").length,
    invalid: cache.filter((c) => c.content.length < 50).length,
  };

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-spacing-xl">
        <Icons.Lock className="w-spacing-3xl h-spacing-3xl text-destructive mb-spacing-md opacity-20" />
        <h2 className="text-premium-xl font-bold mb-spacing-xs">Acesso Restrito</h2>
        <p className="text-muted-foreground">Esta área é exclusiva para administradores.</p>
      </div>
    );
  }

  return (
    <div className="max-w-spacing-4xl mx-auto p-spacing-lg space-y-spacing-xl animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-spacing-md">
        <div>
          <h1 className="text-premium-2xl font-serif font-bold text-foreground">
            Depuração do Catecismo
          </h1>
          <p className="text-premium-sm text-muted-foreground">
            Monitore o estado da geração automática via IA
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-spacing-xs">
          <Button
            onClick={loadData}
            disabled={loading}
            className="p-spacing-xs rounded-premium-full bg-card border border-border hover:bg-primary/10 transition-all disabled:opacity-50"
            title="Atualizar"
          >
            <Icons.RotateCcw
              className={`w-spacing-md h-spacing-md ${loading ? "animate-spin" : ""}`}
            />
          </Button>
          <Button
            onClick={reprocessAllErrors}
            disabled={isReprocessing || stats.pending === 0}
            className="px-spacing-md py-spacing-xs rounded-premium-full bg-primary text-primary-foreground text-premium-xs font-black uppercase tracking-widest hover:brightness-110 transition-all disabled:opacity-50 flex items-center gap-spacing-xs"
          >
            <Icons.Zap className="w-spacing-sm h-spacing-sm" /> Reprocessar Erros
          </Button>
          <Button
            onClick={reprocessIncomplete}
            disabled={isReprocessing}
            className="px-spacing-md py-spacing-xs rounded-premium-full bg-orange-500 text-white text-premium-xs font-black uppercase tracking-widest hover:brightness-110 transition-all disabled:opacity-50 flex items-center gap-spacing-xs shadow-premium-md"
          >
            <Icons.PenTool className="w-spacing-sm h-spacing-sm" /> Reparar Incompletos
          </Button>
          <Button
            onClick={() => (window.location.href = "/catechism/integrity")}
            className="px-spacing-md py-spacing-xs rounded-premium-full bg-blue-500 text-white text-premium-xs font-black uppercase tracking-widest hover:brightness-110 transition-all flex items-center gap-spacing-xs shadow-premium-md"
          >
            <Icons.Activity className="w-spacing-sm h-spacing-sm" /> Painel de Integridade
          </Button>
          <Button
            onClick={clearInvalidCache}
            className="px-spacing-md py-spacing-xs rounded-premium-full bg-destructive/10 text-destructive text-premium-xs font-black uppercase tracking-widest hover:bg-destructive/20 transition-all flex items-center gap-spacing-xs"
          >
            <Icons.Trash2 className="w-spacing-sm h-spacing-sm" /> Limpar Inválidos
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-spacing-md">
        <div className="bg-card border border-border rounded-premium p-spacing-md">
          <span className="text-premium-xs font-black uppercase tracking-widest text-muted-foreground">
            Total no Banco
          </span>
          <div className="text-premium-2xl font-serif font-bold text-foreground">{stats.total}</div>
        </div>
        <div className="bg-card border border-border rounded-premium p-spacing-md">
          <span className="text-premium-xs font-black uppercase tracking-widest text-success text-green-500">
            Gerados OK
          </span>
          <div className="text-premium-2xl font-serif font-bold text-foreground">
            {stats.generated}
          </div>
        </div>
        <div className="bg-card border border-border rounded-premium p-spacing-md">
          <span className="text-premium-xs font-black uppercase tracking-widest text-primary">
            Pendentes (402)
          </span>
          <div className="text-premium-2xl font-serif font-bold text-foreground">
            {stats.pending}
          </div>
        </div>
        <div className="bg-card border border-border rounded-premium p-spacing-md">
          <span className="text-premium-xs font-black uppercase tracking-widest text-destructive">
            Inválidos/Curtos
          </span>
          <div className="text-premium-2xl font-serif font-bold text-foreground">
            {stats.invalid}
          </div>
        </div>
      </div>

      <div className="bg-card border border-border rounded-premium overflow-hidden shadow-premium-md">
        <div className="p-spacing-md border-b border-border bg-muted/30 flex items-center justify-between">
          <div className="flex items-center gap-spacing-md">
            <div className="flex items-center gap-spacing-xs bg-background/50 border border-border rounded-premium p-spacing-2xs">
              <Button
                onClick={() => setView("cache")}
                className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${view === "cache" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
              >
                Cache
              </Button>
              <Button
                onClick={() => setView("logs")}
                className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${view === "logs" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
              >
                Logs
              </Button>
              <Button
                onClick={() => setView("integrity")}
                className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${view === "integrity" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
              >
                Integridade
              </Button>
            </div>
            {view === "cache" && (
              <div className="flex items-center gap-spacing-xs bg-background/50 border border-border rounded-premium p-spacing-2xs">
                <Button
                  onClick={() => setFilter("all")}
                  className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${filter === "all" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
                >
                  Todos
                </Button>
                <Button
                  onClick={() => setFilter("generated")}
                  className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${filter === "generated" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
                >
                  Sucesso
                </Button>
                <Button
                  onClick={() => setFilter("error")}
                  className={`px-spacing-sm py-spacing-2xs text-premium-xs font-black uppercase tracking-widest rounded-premium-full transition-all ${filter === "error" ? "bg-primary text-primary-foreground shadow-premium-md" : "text-muted-foreground hover:text-foreground"}`}
                >
                  Erros
                </Button>
              </div>
            )}
            {view === "integrity" && (
              <div className="flex items-center gap-spacing-xs">
                <Button
                  onClick={exportIntegrityToCSV}
                  className="p-spacing-xs rounded-premium-full bg-primary/10 text-primary hover:bg-primary/20 transition-all"
                  title="Exportar CSV"
                >
                  <Icons.FileText className="w-spacing-sm h-spacing-sm" />
                </Button>
                <Button
                  onClick={exportIntegrityToPDF}
                  className="p-spacing-xs rounded-premium-full bg-red-500/10 text-red-600 hover:bg-red-500/20 transition-all"
                  title="Exportar PDF"
                >
                  <Icons.Download className="w-spacing-sm h-spacing-sm" />
                </Button>
              </div>
            )}
          </div>
          <div className="flex items-center gap-spacing-md">
            {view === "logs" && (
              <div className="flex items-center gap-spacing-xs">
                <input
                  type="date"
                  value={dateRange.start}
