import { fetchCatechismParagraph, CatechismFetchError } from "@/hooks/useCatechismParagraph";

interface Props {
  startPara: number;
  endPara: number;
  onJumpTo?: (p: number) => void;
}

type RunStatus = "pending" | "recovered" | "error" | "cancelled" | "backoff";

interface ParaState {
  paragraph: number;
  status: RunStatus;
  attempts: number;
  lastAttemptAt?: string;
  nextAttemptAt?: string;
  responseTimeMs?: number;
  errorCode?: string;
  errorMessage?: string;
  httpStatus?: number;
}

const reasonLabel = (code?: string) => {
  switch (code) {
    case "not_found":
      return "não encontrado no banco oficial";
    case "network":
      return "falha de rede";
    case "unauthorized":
      return "sessão expirada";
    case "forbidden":
      return "sem permissão";
    default:
      return "erro desconhecido";
  }
};

const isTransient = (code?: string) => code === "network" || code === "unknown";

const sleep = (ms: number, signal: { cancelled: boolean }) =>
  new Promise<void>((resolve) => {
    const start = Date.now();
    const tick = () => {
      if (signal.cancelled || Date.now() - start >= ms) return resolve();
      setTimeout(tick, Math.min(250, ms - (Date.now() - start)));
    };
    tick();
  });

const triggerDownload = (filename: string, mime: string, content: string) => {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

const csvEscape = (v: unknown) => {
  const s = v == null ? "" : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

const CONCURRENCY_KEY = "cathedra.catechism.verifyConcurrency";
const MAX_RETRIES_KEY = "cathedra.catechism.verifyMaxRetries";
const BASE_BACKOFF_KEY = "cathedra.catechism.verifyBaseBackoffMs";

const readNum = (key: string, fallback: number, min: number, max: number) => {
  if (typeof window === "undefined") return fallback;
  const raw = Number(window.localStorage.getItem(key));
  return Number.isFinite(raw) && raw >= min && raw <= max ? raw : fallback;
};

const CatechismPendingPanel: React.FC<Props> = ({ startPara, endPara, onJumpTo }) => {
  const { pending, clearPending } = useCatechismPending();
  const queryClient = useQueryClient();
  const [isRunning, setIsRunning] = useState(false);
  const [progress, setProgress] = useState({ done: 0, total: 0 });
  const [results, setResults] = useState<Record<number, ParaState>>({});
  const [runStatus, setRunStatus] = useState<"idle" | "running" | "cancelled" | "completed">(
    "idle",
  );
  const [paused, setPaused] = useState(false);
  const [confirmCancelOpen, setConfirmCancelOpen] = useState(false);
  const [exportFilter, setExportFilter] = useState<"all" | "pending" | "backoff" | "error">("all");
  const [now, setNow] = useState(() => Date.now());

  const [concurrency, setConcurrency] = useState<number>(() => readNum(CONCURRENCY_KEY, 4, 1, 8));
  const [maxRetries, setMaxRetries] = useState<number>(() => readNum(MAX_RETRIES_KEY, 3, 0, 6));
  const [baseBackoffMs, setBaseBackoffMs] = useState<number>(() =>
    readNum(BASE_BACKOFF_KEY, 600, 100, 5000),
  );

  const cancelRef = useRef({ cancelled: false });
  const pausedRef = useRef(false);
  const autoResumedRef = useRef(false);
  const sessionKey = `cathedra.catechism.verifyRun.${startPara}-${endPara}`;

  // Persistência das configurações.
  useEffect(() => {
    try {
      localStorage.setItem(CONCURRENCY_KEY, String(concurrency));
    } catch {}
  }, [concurrency]);
  useEffect(() => {
    try {
      localStorage.setItem(MAX_RETRIES_KEY, String(maxRetries));
    } catch {}
  }, [maxRetries]);
  useEffect(() => {
    try {
      localStorage.setItem(BASE_BACKOFF_KEY, String(baseBackoffMs));
    } catch {}
  }, [baseBackoffMs]);

  // Restaura estado salvo da seção.
  useEffect(() => {
    autoResumedRef.current = false;
    try {
      const raw = sessionStorage.getItem(sessionKey);
      if (!raw) {
        setProgress({ done: 0, total: 0 });
        setResults({});
        setRunStatus("idle");
        setPaused(false);
        pausedRef.current = false;
        return;
      }
      const saved = JSON.parse(raw);
      setProgress(saved.progress ?? { done: 0, total: 0 });
      setResults(saved.results ?? {});
      setRunStatus(saved.runStatus ?? "idle");
      const wasPaused = Boolean(saved.paused);
      setPaused(wasPaused);
      pausedRef.current = wasPaused;
    } catch {}
  }, [sessionKey]);

  // Persiste estado a cada mudança.
  useEffect(() => {
    try {
      sessionStorage.setItem(sessionKey, JSON.stringify({ progress, results, runStatus, paused }));
    } catch {}
  }, [sessionKey, progress, results, runStatus, paused]);

  // Tick global apenas quando há countdown ativo.
  useEffect(() => {
    const hasCountdown = Object.values(results).some(
      (r) => r.status === "backoff" && r.nextAttemptAt,
    );
    if (!hasCountdown && !isRunning) return;
    const id = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(id);
  }, [results, isRunning]);

  const inRange = pending.filter((p) => p >= startPara && p <= endPara);

  const recordResult = (p: number, patch: Partial<ParaState>) => {
    setResults((prev) => ({
      ...prev,
      [p]: { paragraph: p, status: "pending", attempts: 0, ...prev[p], ...patch },
    }));
  };

  const fetchWithBackoff = async (
    p: number,
    cfg: { maxRetries: number; baseBackoffMs: number },
  ): Promise<{ ok: boolean; err?: any; attempts: number }> => {
    let attempts = 0;
    let lastErr: any = null;
    while (attempts <= cfg.maxRetries) {
      if (cancelRef.current.cancelled)
        return { ok: false, err: lastErr ?? new Error("cancelled"), attempts };
      attempts += 1;
      const t0 = performance.now();
      try {
        const result = await fetchCatechismParagraph(p);
        const elapsed = Math.round(performance.now() - t0);
        queryClient.setQueryData(["catechism-paragraph", p], result);
        clearPending(p);
        recordResult(p, {
          status: "recovered",
          attempts,
          lastAttemptAt: new Date().toISOString(),
          nextAttemptAt: undefined,
          responseTimeMs: elapsed,
          errorCode: undefined,
          errorMessage: undefined,
          httpStatus: undefined,
        });
        return { ok: true, attempts };
      } catch (err: any) {
        const elapsed = Math.round(performance.now() - t0);
        lastErr = err;
        const code = err instanceof CatechismFetchError ? err.code : "unknown";
        const willRetry = isTransient(code) && attempts <= cfg.maxRetries;
        const backoffMs = willRetry ? cfg.baseBackoffMs * Math.pow(2, attempts - 1) : 0;
        recordResult(p, {
          status: willRetry ? "backoff" : "error",
          attempts,
          lastAttemptAt: new Date().toISOString(),
          nextAttemptAt: willRetry ? new Date(Date.now() + backoffMs).toISOString() : undefined,
          responseTimeMs: elapsed,
          errorCode: code,
          errorMessage: err?.message,
          httpStatus: err?.status,
        });
        if (!willRetry) return { ok: false, err, attempts };
        await sleep(backoffMs, cancelRef.current);
        if (cancelRef.current.cancelled) return { ok: false, err, attempts };
      }
    }
    return { ok: false, err: lastErr, attempts };
  };

  const waitWhilePaused = async () => {
    while (pausedRef.current && !cancelRef.current.cancelled) {
      await new Promise((r) => setTimeout(r, 200));
    }
  };

  const runWorkers = async (
    queue: number[],
    cfg: { maxRetries: number; baseBackoffMs: number; concurrency: number },
  ) => {
    const total = queue.length;
    let recovered = 0;
    let stillMissing = 0;
    let cancelled = 0;
    let idx = 0;
    const workerCount = Math.max(1, Math.min(cfg.concurrency, total));
    const workers = Array.from({ length: workerCount }, async () => {
      while (idx < queue.length) {
        if (cancelRef.current.cancelled) {
          const remaining = queue.length - idx;
          cancelled += remaining;
          for (let i = idx; i < queue.length; i += 1) {
            recordResult(queue[i], { status: "cancelled", nextAttemptAt: undefined });
          }
          idx = queue.length;
          break;
        }
        if (pausedRef.current) {
          await waitWhilePaused();
          if (cancelRef.current.cancelled) continue;
        }
        const p = queue[idx++];
        const attemptIdx = idx;
        const res = await fetchWithBackoff(p, {
          maxRetries: cfg.maxRetries,
          baseBackoffMs: cfg.baseBackoffMs,
        });
        if (res.ok === true) {
          recovered += 1;
        } else if (!cancelRef.current.cancelled) {
          stillMissing += 1;
          const errAny: any = res.err;
          const code = errAny instanceof CatechismFetchError ? errAny.code : "unknown";
          toast.error(`§${p} — ${reasonLabel(code)}`, {
            description: `Item ${attemptIdx}/${total} · ${res.attempts} tentativa(s)${errAny?.status ? ` · HTTP ${errAny.status}` : ""}`,
          });
        }
        setProgress((prev) => ({ done: prev.done + 1, total: prev.total || total }));
      }
    });
    await Promise.all(workers);
    return { recovered, stillMissing, cancelled };
  };

  const startRun = async (queue: number[], opts: { resume: boolean }) => {
    if (isRunning || queue.length === 0) return;
    cancelRef.current = { cancelled: false };
    setIsRunning(true);
    setRunStatus("running");
    if (!opts.resume) {
      setResults({});
      setProgress({ done: 0, total: queue.length });
    } else {
      setProgress((prev) => ({ done: prev.done, total: prev.total || prev.done + queue.length }));
    }
    try {
      const summary = await runWorkers(queue, { maxRetries, baseBackoffMs, concurrency });
      if (cancelRef.current.cancelled) {
        setRunStatus("cancelled");
        toast.message("Verificação cancelada.", {
          description: `${summary.recovered} recuperado(s) · ${summary.stillMissing} com erro · ${summary.cancelled} não processado(s).`,
        });
      } else {
        setRunStatus("completed");
        if (summary.recovered > 0 && summary.stillMissing === 0) {
          toast.success(
            `${summary.recovered} parágrafo${summary.recovered > 1 ? "s" : ""} carregado${summary.recovered > 1 ? "s" : ""} com sucesso.`,
          );
        } else if (summary.recovered > 0) {
          toast.success(`${summary.recovered} recuperado(s).`, {
            description: `${summary.stillMissing} ainda não disponível(eis) no banco oficial.`,
          });
        } else {
          toast.error(`Nenhum parágrafo disponível ainda. ${summary.stillMissing} pendente(s).`);
        }
      }
    } finally {
      cancelRef.current.cancelled = false;
      setIsRunning(false);
    }
  };

  const verifyAll = () => startRun(inRange, { resume: false });

  const confirmCancel = () => {
    cancelRef.current.cancelled = true;
    pausedRef.current = false;
    setPaused(false);
    setRunStatus("cancelled");
    setConfirmCancelOpen(false);
  };

  const handlePause = () => {
    if (!isRunning) return;
    pausedRef.current = true;
    setPaused(true);
    toast.message("Execução pausada.", {
      description: "Workers em andamento concluirão o item atual.",
    });
  };

  const handleResume = () => {
    pausedRef.current = false;
    setPaused(false);
    if (!isRunning && runStatus === "running") {
      // Pausa estava ativa entre refresh: retomar com o que restar.
      const processed = new Set(
        Object.values(results)
          .filter((r) => r.status === "recovered" || r.status === "error")
          .map((r) => r.paragraph),
      );
      const remaining = inRange.filter((p) => !processed.has(p));
      if (remaining.length > 0) startRun(remaining, { resume: true });
    } else {
      toast.message("Execução retomada.");
    }
  };

  // Retomada automática após refresh: só se 'running' E não pausado/cancelado/concluído.
  useEffect(() => {
    if (autoResumedRef.current) return;
    if (runStatus !== "running") return;
    if (paused) return;
    if (isRunning) return;
    if (inRange.length === 0) return;
    autoResumedRef.current = true;
    const processed = new Set(
      Object.values(results)
        .filter((r) => r.status === "recovered" || r.status === "error")
        .map((r) => r.paragraph),
    );
    const remaining = inRange.filter((p) => !processed.has(p));
    if (remaining.length === 0) {
      setRunStatus("completed");
      return;
    }
    toast.message("Retomando verificação…", {
      description: `${remaining.length} parágrafo(s) restantes.`,
    });
    startRun(remaining, { resume: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runStatus, paused, inRange.length]);

  const errorRows = useMemo(
    () =>
      Object.values(results)
        .filter((r) => r.status === "error" || (r.status === "backoff" && r.errorCode))
        .sort((a, b) => a.paragraph - b.paragraph),
    [results],
  );

  if (inRange.length === 0 && Object.keys(results).length === 0) return null;

  const buildExportRows = (): ParaState[] => {
    const map = new Map<number, ParaState>();
    inRange.forEach((p) =>
      map.set(p, results[p] ?? { paragraph: p, status: "pending", attempts: 0 }),
    );
    Object.values(results).forEach((r) => {
      if (!map.has(r.paragraph)) map.set(r.paragraph, r);
    });
    let rows = Array.from(map.values()).sort((a, b) => a.paragraph - b.paragraph);
    if (exportFilter !== "all") {
      rows = rows.filter((r) => r.status === exportFilter);
    }
    return rows;
  };

  const exportJSON = () => {
    const payload = {
      generated_at: new Date().toISOString(),
      section: { start: startPara, end: endPara },
      run_status: runStatus,
      config: { concurrency, max_retries: maxRetries, base_backoff_ms: baseBackoffMs },
      progress,
      paragraphs: buildExportRows(),
    };
    triggerDownload(
      `catechism-pending-${startPara}-${endPara}.json`,
      "application/json",
      JSON.stringify(payload, null, 2),
    );
  };

  const exportCSV = () => {
    const rows = [
      "paragraph,section_start,section_end,status,attempts,last_attempt_at,next_attempt_at,response_time_ms,error_code,http_status,error_message",
    ];
    buildExportRows().forEach((r) => {
      rows.push(
        [
          r.paragraph,
          startPara,
          endPara,
          r.status,
          r.attempts,
          r.lastAttemptAt ?? "",
          r.nextAttemptAt ?? "",
          r.responseTimeMs ?? "",
          r.errorCode ?? "",
          r.httpStatus ?? "",
          r.errorMessage ?? "",
        ]
          .map(csvEscape)
          .join(","),
      );
    });
    triggerDownload(
      `catechism-pending-${startPara}-${endPara}.csv`,
      "text/csv;charset=utf-8",
      rows.join("\n"),
    );
  };

  const pct = progress.total > 0 ? Math.round((progress.done / progress.total) * 100) : 0;
  const hasExportable = inRange.length > 0 || Object.keys(results).length > 0;

  const secondsUntil = (iso?: string) => {
    if (!iso) return 0;
    const diff = new Date(iso).getTime() - now;
    return diff > 0 ? Math.ceil(diff / 1000) : 0;
  };

  return (
    <aside
      role="status"
      aria-live="polite"
      data-testid="catechism-pending-panel"
      className="mb-spacing-md rounded-premium border border-dashed border-primary/15 bg-muted/20 p-spacing-md space-y-spacing-sm"
    >
      <div className="flex items-start justify-between gap-spacing-md flex-wrap">
        <div className="space-y-spacing-2xs">
          <div className="flex items-center gap-spacing-xs text-premium-xs font-display uppercase tracking-[0.2em] text-primary/60">
            <Icons.Catechism className="w-spacing-sm h-spacing-sm" />
            Parágrafos em preparação ({inRange.length})
          </div>
          <p className="text-premium-xs italic text-muted-foreground font-serif">
            Ainda não importados para o banco oficial em português nesta seção.
          </p>
        </div>
        <div className="flex items-center gap-spacing-2xs flex-wrap">
          <Select value={exportFilter} onValueChange={(v: any) => setExportFilter(v)}>
            <SelectTrigger
              aria-label="Filtro da exportação"
              className="h-8 w-spacing-5xl text-premium-xs"
              data-testid="catechism-export-filter"
            >
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos</SelectItem>
              <SelectItem value="pending">Pendentes</SelectItem>
              <SelectItem value="backoff">Em backoff</SelectItem>
              <SelectItem value="error">Com erro</SelectItem>
            </SelectContent>
          </Select>
          <Button
            onClick={exportCSV}
            disabled={!hasExportable}
            variant="ghost"
            size="sm"
            data-testid="catechism-export-csv"
          >
            CSV
          </Button>
          <Button
            onClick={exportJSON}
            disabled={!hasExportable}
            variant="ghost"
            size="sm"
            data-testid="catechism-export-json"
          >
            JSON
          </Button>
          {isRunning && !paused && (
            <Button
              onClick={handlePause}
              variant="outline"
              size="sm"
              data-testid="catechism-verify-pause"
            >
              Pausar
            </Button>
          )}
          {(isRunning && paused) || (runStatus === "running" && paused && !isRunning) ? (
            <Button
              onClick={handleResume}
              variant="outline"
              size="sm"
              data-testid="catechism-verify-resume"
            >
              Retomar
            </Button>
          ) : null}
          {isRunning || (runStatus === "running" && paused) ? (
            <Button
              onClick={() => setConfirmCancelOpen(true)}
              variant="outline"
              size="sm"
              data-testid="catechism-verify-cancel"
            >
              Cancelar
            </Button>
          ) : (
            <Button
              onClick={verifyAll}
              variant="outline"
              size="sm"
              data-testid="catechism-verify-all"
              disabled={inRange.length === 0}
            >
              Verificar todos ({inRange.length})
            </Button>
          )}
        </div>
      </div>

      <AlertDialog open={confirmCancelOpen} onOpenChange={setConfirmCancelOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancelar verificação em lote?</AlertDialogTitle>
            <AlertDialogDescription>
              Os workers em andamento concluirão o item atual e os parágrafos restantes serão
              marcados como “cancelados”. A retomada automática após refresh ficará bloqueada — só
              uma nova execução manual irá processá-los novamente.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel data-testid="catechism-cancel-modal-keep">
              Continuar verificando
            </AlertDialogCancel>
            <AlertDialogAction onClick={confirmCancel} data-testid="catechism-cancel-modal-confirm">
              Cancelar mesmo assim
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <div className="grid gap-spacing-sm sm:grid-cols-3" data-testid="catechism-verify-config">
        <div className="flex items-center gap-spacing-xs">
          <label
            htmlFor="cat-concurrency"
            className="text-premium-xs font-display tracking-[0.1em] uppercase text-primary/60 whitespace-nowrap"
          >
            Concorrência
          </label>
          <Slider
            id="cat-concurrency"
            min={1}
            max={8}
            step={1}
            value={[concurrency]}
            onValueChange={(v) => setConcurrency(v[0] ?? 4)}
            disabled={isRunning}
            className="flex-1"
            aria-label="Requisições simultâneas"
          />
          <span className="text-premium-xs font-display text-primary/70 tabular-nums w-spacing-xl text-right">
            {concurrency}x
          </span>
        </div>
        <div className="flex items-center gap-spacing-xs">
          <label
            htmlFor="cat-max-retries"
            className="text-premium-xs font-display tracking-[0.1em] uppercase text-primary/60 whitespace-nowrap"
          >
            Máx. tentativas
          </label>
          <Input
            id="cat-max-retries"
            type="number"
            min={0}
            max={6}
            step={1}
            value={maxRetries}
            onChange={(e) => setMaxRetries(Math.max(0, Math.min(6, Number(e.target.value) || 0)))}
            disabled={isRunning}
            className="h-8 w-spacing-3xl text-premium-xs"
          />
        </div>
        <div className="flex items-center gap-spacing-xs">
          <label
            htmlFor="cat-backoff"
            className="text-premium-xs font-display tracking-[0.1em] uppercase text-primary/60 whitespace-nowrap"
          >
            Backoff inicial (ms)
          </label>
          <Input
            id="cat-backoff"
            type="number"
            min={100}
            max={5000}
            step={100}
            value={baseBackoffMs}
            onChange={(e) =>
              setBaseBackoffMs(Math.max(100, Math.min(5000, Number(e.target.value) || 600)))
            }
            disabled={isRunning}
            className="h-8 w-spacing-4xl text-premium-xs"
          />
        </div>
      </div>

      {(isRunning || progress.done > 0) && (
        <div className="space-y-spacing-2xs" data-testid="catechism-verify-progress">
          <div className="flex items-center justify-between text-premium-xs font-display tracking-[0.1em] uppercase text-primary/60">
            <span>
              {paused
                ? "Pausada"
                : isRunning
                  ? "Verificando…"
                  : runStatus === "cancelled"
                    ? "Cancelada"
                    : runStatus === "completed"
                      ? "Concluída"
                      : "Última execução"}
            </span>
            <span>
              {progress.done}/{progress.total} · {pct}%
            </span>
          </div>
          <Progress value={pct} />
        </div>
      )}

      <ul className="flex flex-wrap gap-spacing-2xs" aria-label="Lista de parágrafos pendentes">
        {inRange.map((p) => {
          const r = results[p];
          const tone =
            r?.status === "recovered"
              ? "text-emerald-600 border-emerald-500/30"
              : r?.status === "error"
                ? "text-destructive border-destructive/30"
                : r?.status === "cancelled"
                  ? "text-amber-600 border-amber-500/30"
                  : r?.status === "backoff"
                    ? "text-sky-600 border-sky-500/30 animate-pulse"
                    : "text-primary/60 border-primary/10 hover:border-primary/30";
          const countdown = r?.status === "backoff" ? secondsUntil(r.nextAttemptAt) : 0;
          const label =
            countdown > 0
              ? `§${p} · ${countdown}s`
              : `§${p}${r?.attempts ? ` ·${r.attempts}` : ""}${r?.responseTimeMs ? ` · ${r.responseTimeMs}ms` : ""}`;
          const title =
            r?.status === "backoff"
              ? `Próxima tentativa em ${countdown}s`
              : (r?.errorMessage ?? r?.status ?? "pendente");
          return (
            <li key={p}>
              <button
                type="button"
                onClick={() => onJumpTo?.(p)}
                className={`text-premium-xs font-display tracking-[0.1em] border rounded-premium-full px-spacing-sm py-spacing-2xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/40 ${tone}`}
                aria-label={`Ir para parágrafo ${p}${r ? ` (${r.status})` : ""}`}
                title={title}
              >
                {label}
              </button>
            </li>
          );
        })}
      </ul>

      {errorRows.length > 0 && (
        <details className="mt-spacing-xs" data-testid="catechism-error-details">
          <summary className="cursor-pointer text-premium-xs font-display tracking-[0.1em] uppercase text-primary/60 hover:text-primary">
            Falhas com detalhe ({errorRows.length})
          </summary>
          <div className="mt-spacing-xs overflow-x-auto">
            <table className="w-full text-premium-xs font-mono">
              <thead>
                <tr className="text-left text-muted-foreground border-b border-primary/10">
                  <th className="py-spacing-2xs pr-spacing-sm">§</th>
                  <th className="py-spacing-2xs pr-spacing-sm">Tentativas</th>
                  <th className="py-spacing-2xs pr-spacing-sm">Última</th>
                  <th className="py-spacing-2xs pr-spacing-sm">HTTP</th>
                  <th className="py-spacing-2xs pr-spacing-sm">Código</th>
                  <th className="py-spacing-2xs">Mensagem</th>
                </tr>
              </thead>
              <tbody>
                {errorRows.map((r) => (
                  <tr key={r.paragraph} className="border-b border-primary/5 align-top">
                    <td className="py-spacing-2xs pr-spacing-sm">
                      <button
                        type="button"
                        onClick={() => onJumpTo?.(r.paragraph)}
                        className="text-primary/80 hover:text-primary underline-offset-2 hover:underline"
                      >
                        §{r.paragraph}
                      </button>
                    </td>
                    <td className="py-spacing-2xs pr-spacing-sm tabular-nums">{r.attempts}</td>
                    <td className="py-spacing-2xs pr-spacing-sm text-muted-foreground">
                      {r.lastAttemptAt ? new Date(r.lastAttemptAt).toLocaleTimeString() : "—"}
                    </td>
                    <td className="py-spacing-2xs pr-spacing-sm tabular-nums">
                      {r.httpStatus ?? "—"}
                    </td>
                    <td className="py-spacing-2xs pr-spacing-sm">{r.errorCode ?? "—"}</td>
                    <td className="py-spacing-2xs text-destructive/80 break-all">
                      {r.errorMessage ?? "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </details>
      )}
    </aside>
  );
};

export default CatechismPendingPanel;

/**
 * CatechismPopover — adapter fino sobre `ReferencePopover` canônico.
 *
 * Reader Architecture Rule (COS §10): este arquivo NÃO pode importar
 * `@radix-ui/react-popover` nem `@/components/ui/popover` diretamente.
 * Toda referência inline usa `ReferencePopover`.
 */

import React, { memo } from "react";
import { Link } from "@/lib/rr-compat";
import { ReferencePopover } from "@/components/reader";
import { Icons } from "@/constants";
import { useCatechismParagraph } from "@/hooks/useCatechismParagraph";
import { catechismInternalPath } from "@/lib/nexusNavigation";

interface CatechismPopoverProps {
  paragraph: number;
  onNavigate?: (paragraph: number) => void;
  variant?: "default" | "mini";
}

const CatechismPopoverBody: React.FC<{ paragraph: number; onNavigate?: (p: number) => void }> = ({
  paragraph,
  onNavigate,
}) => {
  const { data, isLoading, isFetched, error } = useCatechismParagraph(paragraph);
  const [showDiag, setShowDiag] = React.useState(false);

  const content = data?.content || "";
  const err = error as any;
  const diag = {
    status: err?.code || data?.status || (isFetched && !content ? "empty" : "ok"),
    httpStatus: err?.status ?? "—",
    requestId: `cic-${paragraph}-${Date.now().toString(36)}`,
    message:
      err?.message || (isFetched && !content ? "Conteúdo vazio retornado pelo servidor." : ""),
  };
  const hasIssue = Boolean(err) || (isFetched && !content);

  return (
    <div className="space-y-spacing-sm">
      {onNavigate && (
        <button
          type="button"
          onClick={() => onNavigate(paragraph)}
          className="text-premium-xs font-bold text-muted-foreground hover:text-primary transition-colors flex items-center gap-spacing-2xs"
        >
          Abrir completo <Icons.ArrowDown className="w-spacing-sm h-spacing-sm -rotate-90" />
        </button>
      )}
      {isLoading && (
        <div className="space-y-spacing-xs py-spacing-xs">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="h-spacing-sm bg-muted rounded animate-pulse"
              style={{ width: `${50 + i * 15}%` }}
            />
          ))}
        </div>
      )}
      {!isLoading && isFetched && content && (
        <p className="text-premium-xs leading-relaxed text-foreground/90 font-serif">
          {content.length > 300 ? content.slice(0, 300) + "…" : content}
        </p>
      )}
      {!isLoading && isFetched && !content && (
        <div className="space-y-spacing-xs">
          <p className="text-premium-xs text-muted-foreground italic">
            Texto ainda não importado para o banco oficial.
          </p>
          <Link
            to={catechismInternalPath(paragraph)}
            className="inline-flex items-center gap-spacing-2xs text-premium-xs font-bold text-primary hover:underline"
            data-testid="catechism-open-internal"
            data-cic-paragraph={paragraph}
            data-cic-origin="nexus-popover"
          >
            <Icons.ArrowDown className="w-spacing-sm h-spacing-sm -rotate-90" />
            Abrir §{paragraph} no Catecismo
          </Link>
        </div>
      )}

      {!isLoading && hasIssue && (
        <div className="border-t border-border pt-spacing-xs">
          <button
            type="button"
            onClick={() => setShowDiag((v) => !v)}
            className="text-premium-xs font-bold text-muted-foreground hover:text-primary transition-colors flex items-center gap-spacing-2xs"
            data-testid="catechism-diag-toggle"
          >
            <Icons.AlertTriangle className="w-spacing-sm h-spacing-sm" />
            Diagnóstico {showDiag ? "▾" : "▸"}
          </button>
          {showDiag && (
            <dl className="mt-spacing-xs space-y-spacing-2xs text-premium-xs font-mono bg-muted/40 rounded-premium p-spacing-xs">
              <div className="flex justify-between gap-spacing-xs">
                <dt className="text-muted-foreground">status</dt>
                <dd className="text-foreground">{String(diag.status)}</dd>
              </div>
              <div className="flex justify-between gap-spacing-xs">
                <dt className="text-muted-foreground">http</dt>
                <dd className="text-foreground">{String(diag.httpStatus)}</dd>
              </div>
              <div className="flex justify-between gap-spacing-xs">
                <dt className="text-muted-foreground">request_id</dt>
                <dd className="text-foreground break-all">{diag.requestId}</dd>
              </div>
              {diag.message && (
                <div>
                  <dt className="text-muted-foreground mb-spacing-2xs">message</dt>
                  <dd className="text-foreground whitespace-pre-wrap break-words">
                    {diag.message}
                  </dd>
                </div>
              )}
            </dl>
          )}
        </div>
      )}
    </div>
  );
};

const CatechismPopover: React.FC<CatechismPopoverProps> = memo(
  ({ paragraph, onNavigate, variant = "default" }) => (
    <ReferencePopover
      kind="catechism"
      label={variant === "mini" ? "§" : `§${paragraph}`}
      ariaLabel={`Abrir referência: Catecismo §${paragraph}`}
      title={`CIC §${paragraph}`}
      renderContent={() => <CatechismPopoverBody paragraph={paragraph} onNavigate={onNavigate} />}
    />
  ),
);

export default CatechismPopover;

import { useIsAdmin } from "@/hooks/useIsAdmin";
import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Icons } from "@/constants";
import { supabase } from "@/lib/db";
import { toast } from "sonner";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "@/lib/rr-compat";
import { CIC_SECTIONS, CATECHISM_LOCAL_DATA } from "@/data/catechism";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { cacheCatechismParagraph } from "@/lib/offlineCache";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

interface VerificationResult {
  paragraph: number;
  section: string;
  status: "ok" | "missing" | "divergent";
  details?: string;
}

const CatechismVerification: React.FC = () => {
  const { profile } = useAuth();
  const navigate = useNavigate();
  const [results, setResults] = useState<VerificationResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [stats, setStats] = useState({ total: 0, ok: 0, missing: 0, divergent: 0 });
  const [filter, setFilter] = useState<"all" | "missing" | "divergent">("all");
  const [officialDataMap, setOfficialDataMap] = useState<Map<number, any>>(new Map());

  const { isAdmin } = useIsAdmin();

  const runVerification = async () => {
    setLoading(true);
    try {
      // 1. Fetch all paragraphs from official table
      const { data: officialData, error } = await supabase
        .from("catechism_official")
        .select("paragraph, content");

      if (error) throw error;

      const officialMap = new Map(officialData.map((d) => [d.paragraph, d.content]));
      setOfficialDataMap(new Map(officialData.map((d) => [d.paragraph, d])));
      const newResults: VerificationResult[] = [];

      // 2. Iterate through sections defined in the site
      CIC_SECTIONS.forEach((part) => {
        part.sections.forEach((section) => {
          const [start, end] = section.paragraphs;
          for (let p = start; p <= end; p++) {
            const officialContent = officialMap.get(p);
            const localData = CATECHISM_LOCAL_DATA[p];

            if (!officialContent) {
              newResults.push({
                paragraph: p,
                section: section.title,
                status: "missing",
                details: "Ausente na tabela catechism_official",
              });
            } else if (localData && localData.conteudo !== officialContent) {
              newResults.push({
                paragraph: p,
                section: section.title,
                status: "divergent",
                details: "Conteúdo local difere do banco oficial",
              });
            } else {
              newResults.push({
                paragraph: p,
                section: section.title,
                status: "ok",
              });
            }
          }
        });
      });

      setResults(newResults);

      const ok = newResults.filter((r) => r.status === "ok").length;
      const missing = newResults.filter((r) => r.status === "missing").length;
      const divergent = newResults.filter((r) => r.status === "divergent").length;

      setStats({
        total: newResults.length,
        ok,
        missing,
        divergent,
      });

      toast.success("Verificação concluída!");
    } catch (err: any) {
      console.error(err);
      toast.error("Erro ao verificar integridade: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async () => {
    setIsSyncing(true);
    let syncedCount = 0;

    try {
      const divergentOrMissing = results.filter(
        (r) => r.status === "missing" || r.status === "divergent",
      );

      for (const res of divergentOrMissing) {
        const official = officialDataMap.get(res.paragraph);
        if (official) {
          await cacheCatechismParagraph(res.paragraph, {
            paragraph: res.paragraph,
            content: official.content,
            language: "pt",
            status: "official",
          });
          syncedCount++;
        }
      }

      toast.success(`${syncedCount} parágrafos sincronizados com o cache local.`);
      runVerification();
    } catch (err: any) {
      toast.error("Erro na sincronização: " + err.message);
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (isAdmin) runVerification();
  }, [isAdmin]);

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-spacing-xl">
        <Icons.Lock className="w-spacing-3xl h-spacing-3xl text-destructive mb-spacing-md opacity-20" />
        <h2 className="text-premium-xl font-bold mb-spacing-xs">Acesso Restrito</h2>
        <p className="text-muted-foreground">Esta página é para administradores.</p>
      </div>
    );
  }

  const filteredResults = results.filter((r) => {
    if (filter === "all") return true;
    return r.status === filter;
  });

  return (
    <div className="w-full p-spacing-lg space-y-spacing-xl animate-in fade-in duration-500 pb-spacing-3xl">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-spacing-md">
        <div>
          <h1 className="text-premium-2xl font-serif font-bold text-foreground">
            Verificação de Conteúdo
          </h1>
          <p className="text-premium-sm text-muted-foreground">
            Comparação entre seções do site e banco de dados oficial
          </p>
        </div>

        <div className="flex items-center gap-spacing-sm">
          {(stats.missing > 0 || stats.divergent > 0) && (
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button
                  variant="default"
                  className="rounded-premium-full bg-emerald-600 hover:bg-emerald-700"
                >
                  <Icons.CheckCircle className="w-spacing-md h-spacing-md mr-spacing-xs" />
                  Sincronizar {stats.missing + stats.divergent} Divergências
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent className="rounded-premium-full border-border bg-card">
                <AlertDialogHeader>
                  <AlertDialogTitle className="font-serif">
                    Sincronizar com o Banco?
                  </AlertDialogTitle>
                  <AlertDialogDescription>
