const CatechismContent: React.FC<{
  paragraph: number;
  onNavigateToBible?: (abbr: string, chapter: number) => void;
  isVisible?: boolean;
  onHighlightClick?: (note: UserNote) => void;
  highlights?: UserNote[];
}> = ({ paragraph, onNavigateToBible, isVisible = true, onHighlightClick, highlights = [] }) => {
  const { data, isLoading, isError, error, refetch, isFetching } = useCatechismParagraph(
    paragraph,
    isVisible,
  );
  const prefetch = usePrefetchCatechismParagraph();
  const { settings } = useReadingSettings();
  const { markPending, clearPending } = useCatechismPending();

  // Pré-carrega uma janela de §§ vizinhos (±5) em background para reduzir latência
  // ao navegar. `prefetch` é idempotente e reaproveita cache do React Query;
  // quando o § não existe no banco, dispara o enfileiramento automático via edge.
  useEffect(() => {
    if (!isVisible) return;
    const offsets = [1, 2, 3, 4, 5, -1, -2];
    const handles: number[] = [];
    offsets.forEach((off, idx) => {
      const target = paragraph + off;
      if (target < 1 || target > 2865) return;
      // Escalona para não competir com o fetch do § atual
      handles.push(window.setTimeout(() => prefetch(target), 120 + idx * 180));
    });
    return () => handles.forEach(clearTimeout);
  }, [paragraph, prefetch, isVisible]);

  // Sincroniza este parágrafo com o painel de pendências da seção.
  useEffect(() => {
    if (isError && (error as any)?.code === "not_found") {
      markPending(paragraph);
    } else if (data) {
      clearPending(paragraph);
    }
  }, [isError, error, data, paragraph, markPending, clearPending]);

  const handleRetry = useCallback(async () => {
    const readNum = (k: string, fb: number, min: number, max: number) => {
      const v = Number(localStorage.getItem(k));
      return Number.isFinite(v) && v >= min && v <= max ? v : fb;
    };
    const MAX_RETRIES = readNum("cathedra.catechism.verifyMaxRetries", 3, 0, 6);
    const BASE_MS = readNum("cathedra.catechism.verifyBaseBackoffMs", 600, 100, 5000);
    let attempt = 0;
    let lastResult: any = null;
    while (attempt <= MAX_RETRIES) {
      attempt += 1;
      lastResult = await refetch();
      if (!lastResult.error) break;
      const code = (lastResult.error as any)?.code ?? "unknown";
      const transient = code === "network" || code === "unknown";
      if (!transient || attempt > MAX_RETRIES) break;
      await new Promise((r) => setTimeout(r, BASE_MS * Math.pow(2, attempt - 1)));
    }
    if (lastResult?.error) {
      const err: any = lastResult.error;
      const code = err?.code ?? "unknown";
      const reason =
        code === "not_found"
          ? "não encontrado no banco oficial"
          : code === "network"
            ? "falha de rede"
            : code === "unauthorized"
              ? "sessão expirada"
              : code === "forbidden"
                ? "sem permissão"
                : "erro desconhecido";
      toast.error(`§${paragraph} — ${reason}`, {
        description: `Tentativa ${attempt}${err?.status ? ` · HTTP ${err.status}` : ""}${err?.message ? ` · ${err.message}` : ""}`,
      });
    } else if (lastResult?.data) {
      toast.success(`§${paragraph} carregado com sucesso.`);
    }
  }, [refetch, paragraph]);

  const normalization = useMemo(() => {
    if (!data?.content || data.status === "not_cached") return null;
    return normalizeCatechismTextCached(paragraph, data.content);
  }, [data?.content, data?.status]);

  // (segments antigos removidos — parsing agora é feito por parágrafo no render)

  // Telemetria: registra quando a normalização alterou o conteúdo do §.
  useEffect(() => {
    if (!normalization?.changed) return;
    trackEvent("catechism_normalization_diff", {
      paragraph,
      total_changes: totalChanges(normalization.changes),
      original_length: normalization.originalLength,
      normalized_length: normalization.normalizedLength,
      duration_ms: Number(normalization.durationMs.toFixed(3)),
      ...normalization.changes,
    });
  }, [normalization, paragraph]);

  if (!isVisible) {
    return (
      <div className="reader-text text-foreground/30 leading-[2] text-premium-lg py-spacing-md h-spacing-4xl flex items-center">
        <span className="text-premium-sm text-muted-foreground italic">
          Rolar para carregar §{paragraph}...
        </span>
      </div>
    );
  }

  if (isLoading) {
    return <CatechismParagraphSkeleton paragraph={paragraph} />;
  }

  // Refetch em andamento após erro: mostra skeleton em vez de bolha vazia.
  if (isError && isFetching) {
    return <CatechismParagraphSkeleton paragraph={paragraph} />;
  }

  if (isError) {
    const err: any = error;
    const code: string = err?.code ?? "unknown";
    const status = err?.status;

    // Fallback Offline: se for erro de rede, verifica se existe no cache IndexedDB
    // via CatechismOfflineFallback (que já é injetado no módulo).
    const isNetworkError =
      code === "network" || err?.message?.toLowerCase().includes("failed to fetch");

    if (code === "not_found") {
      return (
        <div
          role="note"
          aria-live="polite"
          data-testid={`catechism-placeholder-${paragraph}`}
          className="reader-text bg-muted/30 border border-dashed border-primary/15 rounded-premium p-spacing-md font-serif text-premium-sm italic text-muted-foreground space-y-spacing-xs"
        >
          <h2 className="flex items-center gap-spacing-xs not-italic font-display tracking-[0.1em] uppercase text-premium-xs text-primary/50">
            <Icons.Catechism className="w-spacing-sm h-spacing-sm" />
            Texto em preparação
          </h2>
          <p>
            O parágrafo §{paragraph} ainda não foi importado para o banco oficial em português.
            Estamos preparando o texto soberano para que esteja disponível em breve.
          </p>
          <div className="pt-spacing-xs">
            <Button
              onClick={handleRetry}
              disabled={isFetching}
              variant="ghost"
              size="sm"
              data-testid={`catechism-retry-${paragraph}`}
              className="text-primary/60 hover:text-primary"
            >
              {isFetching ? "Verificando…" : "Verificar novamente"}
            </Button>
          </div>
        </div>
      );
    }

    if (isNetworkError) {
      return (
        <div className="reader-text space-y-spacing-md animate-fade-in">
          <div className="bg-destructive/5 border border-destructive/10 rounded-premium p-spacing-md text-destructive font-serif text-premium-sm space-y-spacing-xs">
            <div className="font-bold flex items-center gap-spacing-xs">
              <Icons.ShieldAlert className="w-spacing-md h-spacing-md" />
              Sem conexão com o depósito da fé
            </div>
            <p className="font-serif italic opacity-80">
              Não conseguimos carregar o parágrafo §{paragraph} do servidor. Tentando recuperar do
              cache local do mosteiro...
            </p>
            <div className="flex items-center gap-spacing-xs pt-spacing-xs">
              <Button onClick={handleRetry} disabled={isFetching} variant="outline" size="sm">
                {isFetching ? "Reconectando…" : "Tentar Novamente"}
              </Button>
            </div>
          </div>
          <CatechismOfflineFallback paragraph={paragraph} />
        </div>
      );
    }

    const title =
      code === "unauthorized"
        ? `Sessão expirada — faça login para ler §${paragraph}.`
        : code === "forbidden"
          ? `Sem permissão para acessar §${paragraph}.`
          : `Ops! Não conseguimos carregar §${paragraph}.`;
    return (
      <div
        role="alert"
        aria-live="polite"
        data-testid={`catechism-error-${paragraph}`}
        className="reader-text bg-destructive/5 border border-destructive/10 rounded-premium p-spacing-md text-destructive font-serif text-premium-sm py-spacing-md space-y-spacing-xs"
      >
        <div className="font-bold flex items-center gap-spacing-xs">
          <Icons.Cross className="w-spacing-md h-spacing-md" />
          {title}
        </div>
        {err?.message && (
          <div className="text-premium-xs text-destructive/80 font-sans">
            {err.message}
            {status ? ` (HTTP ${status})` : ""}
          </div>
        )}
        <div className="flex items-center gap-spacing-xs pt-spacing-xs">
          <Button
            onClick={handleRetry}
            disabled={isFetching}
            variant="outline"
            size="sm"
            data-testid={`catechism-retry-${paragraph}`}
          >
            {isFetching ? "Tentando…" : "Tentar novamente"}
          </Button>
        </div>
      </div>
    );
  }

  // Enfileirado para importação: worker está buscando o texto oficial; o hook faz polling.
  if (data?.status === "queued") {
    return (
      <div
        role="status"
        aria-live="polite"
        data-testid={`catechism-importing-${paragraph}`}
        className="reader-text bg-muted/30 border border-dashed border-primary/20 rounded-premium p-spacing-md font-serif text-premium-sm italic text-muted-foreground space-y-spacing-xs"
      >
        <h2 className="flex items-center gap-spacing-xs not-italic font-display tracking-[0.1em] uppercase text-premium-xs text-primary/60">
          <Icons.Catechism className="w-spacing-sm h-spacing-sm animate-pulse" />
          Importando §{paragraph}…
        </h2>
        <p>
          Estamos buscando o texto oficial deste parágrafo no arquivo da Santa Sé. Ele aparecerá
          automaticamente em instantes.
        </p>
      </div>
    );
  }

  const activeHighlight = highlights.find((n) => n.paragraph === paragraph && n.highlight_color);
  // Divide o texto normalizado em parágrafos reais (quebras duplas),
  // depois aplica o parser de referências dentro de cada parágrafo.
  // Isso evita que conectivos curtos entre refs (ex.: " e ") virem parágrafos soltos.
  const paragraphsText = (normalization?.text ?? "")
    .split(/\n{2,}/)
    .map((s) => s.trim())
    .filter(Boolean);

  return (
    <div
      className={cn(
        "reader-text text-foreground/90 font-size-",
        settings.fontSize,
        "font-family-",
        settings.fontFamily,
        "prose prose-lg dark:prose-invert max-w-none transition-all",
        settings.reduceAnimations ? "duration-0" : "duration-300",
      )}
    >
      {normalization && data?.content && (
        <CatechismNormalizationDiff
          paragraph={paragraph}
          original={data.content}
          report={normalization}
        />
      )}
      {paragraphsText.map((paraText, pi) => {
        const paraSegments = parseTheologicalReferences(paraText);
        const inline = paraSegments.map((seg, i) => {
          if (seg.type === "bibleRef" && seg.abbr) {
            return (
              <BibleVersePopover
                key={i}
                abbr={seg.abbr}
                chapter={seg.chapter!}
                verse={seg.verse}
                label={seg.value}
                onNavigate={onNavigateToBible}
              />
            );
          }
          if (seg.type === "catechismRef" && seg.paragraph) {
            return <CatechismPopover key={i} paragraph={seg.paragraph} />;
          }
          // Texto puro: preserva quebras de linha simples como espaço, sem virar bloco.
          return <React.Fragment key={i}>{seg.value.replace(/\n/g, " ")}</React.Fragment>;
        });

        if (activeHighlight) {
          return (
            <p
              key={pi}
              onClick={() => onHighlightClick?.(activeHighlight)}
              className={`highlight-${activeHighlight.highlight_color} px-spacing-2xs py-spacing-2xs mb-spacing-md last:mb-0 rounded-premium-sm cursor-pointer hover:brightness-95 transition-all leading-relaxed`}
            >
              {inline}
            </p>
          );
        }
        return (
          <p key={pi} className="mb-spacing-md last:mb-0 leading-relaxed">
            {inline}
          </p>
        );
      })}
      {data?.content && (
        <div className="mt-spacing-md pt-spacing-sm border-t border-primary/[0.06]">
          <PassageActions
            text={data.content}
            reference={`CIC §${paragraph}`}
            title={`Cathedra — CIC §${paragraph}`}
            passage={{ kind: "catechism", paragraph }}
          />
        </div>
      )}
    </div>
  );
};

const LazyParagraph: React.FC<{
  paragraph: number;
  currentParagraph: number;
  paragraphsRead: Set<number>;
  isFavorite: (type: string, title: string) => boolean;
  toggleFavorite: (item: any) => void;
  handleNavigateToBible: (abbr: string, chapter: number) => void;
  onHighlightClick?: (note: UserNote) => void;
  highlights?: UserNote[];
}> = ({
  paragraph: p,
  currentParagraph,
  paragraphsRead,
  isFavorite,
  toggleFavorite,
  handleNavigateToBible,
  onHighlightClick,
  highlights = [],
}) => {
  const { settings } = useReadingSettings();

  const ref = React.useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "300px 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <article
      ref={ref}
      id={`p${p}`}
      className={cn(
        "scroll-mt-spacing-4xl transition-all pb-spacing-lg md:pb-spacing-2xl border-b border-primary/[0.03] last:border-0 last:pb-spacing-0",
        settings.reduceAnimations ? "duration-0" : "duration-700",
        currentParagraph === p ? "relative" : "opacity-70 hover:opacity-100",
      )}
      aria-labelledby={`heading-p${p}`}
    >
      <div className="flex items-center gap-spacing-md mb-spacing-lg">
        <div className="flex items-center gap-spacing-sm">
          <h2
            id={`heading-p${p}`}
            className="text-premium-base md:text-premium-lg font-display tracking-[0.18em] text-secondary/70 uppercase"
          >
            §{p}
          </h2>
          <div className="flex items-center gap-spacing-3xs opacity-0 group-hover:opacity-100 focus-within:opacity-100 transition-opacity">
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={() =>
                toggleFavorite({
                  type: "catechism",
                  title: `CIC §${p}`,
                  content: `Catecismo da Igreja Católica, parágrafo §${p}`,
                })
              }
              className="rounded-premium-full hover:bg-primary/5 transition-all focus-visible:ring-2 focus-visible:ring-primary focus-visible:outline-none"
              aria-label={`${isFavorite("catechism", `CIC §${p}`) ? "Remover dos favoritos" : "Adicionar aos favoritos"} - Parágrafo ${p}`}
            >
              <Icons.Heart
                className={`w-spacing-sm h-spacing-sm transition-all ${isFavorite("catechism", `CIC §${p}`) ? "fill-primary text-primary" : "text-muted-foreground/40"}`}
              />
            </Button>
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={() =>
                (window as any).dispatchEvent(
                  new CustomEvent("open-logos-ai", {
                    detail: { context: `Catecismo §${p}`, type: "catechism" },
                  }),
                )
              }
              className="rounded-premium-full hover:bg-primary/5 transition-all text-muted-foreground/40 hover:text-primary focus-visible:ring-2 focus-visible:ring-primary focus-visible:outline-none"
              aria-label={`Perguntar à Logos IA sobre o Parágrafo ${p}`}
            >
              <Icons.Sparkles className="w-spacing-sm h-spacing-sm" />
            </Button>
            <ReadingMarkComponent
              contentType="catechism"
              contentId={`${p}`}
              label={`Catecismo §${p}`}
              paragraph={p}
            />
          </div>
        </div>
        <div className="h-[0.5px] flex-1 bg-gradient-to-r from-primary/[0.05] via-transparent to-transparent" />
      </div>
      <CatechismContent
        paragraph={p}
        onNavigateToBible={handleNavigateToBible}
        isVisible={isVisible}
        onHighlightClick={onHighlightClick}
        highlights={highlights}
      />
    </article>
  );
};

type ViewMode = "parts" | "sections" | "reading";

const Catechism: React.FC = memo(() => {
  useRenderPerf("Catechism", 15);
  const { settings } = useReadingSettings();
  const navigate = useNavigate();
  useAutoFocus();
  const [searchParams] = useSearchParams();
  const initialParagraph = useMemo(() => {
    const raw = getParagraphParam(searchParams);
    if (raw == null) return null;
    const n = parseInt(raw, 10);
    return isValidCatechismParagraph(n) ? n : ("invalid" as const);
  }, [searchParams]);
  const [viewMode, setViewMode] = useState<ViewMode>(() =>
    typeof initialParagraph === "number" ? "reading" : "parts",
  );
  const [selectedPart, setSelectedPart] = useState<(typeof CIC_SECTIONS)[0] | null>(null);
  const [selectedSection, setSelectedSection] = useState<
    (typeof CIC_SECTIONS)[0]["sections"][0] | null
  >(null);
  const [currentParagraph, setCurrentParagraph] = useState(() =>
    typeof initialParagraph === "number" ? initialParagraph : 1,
  );
  const [lastFocusedElement, setLastFocusedElement] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [showLogosAI, setShowLogosAI] = useState(false);
  const { toggleFavorite, isFavorite } = useFavorites();
  const {
    notes: chapterNotes,
    addNote,
    updateNote,
    deleteNote: deleteChapterNote,
  } = useNotes("catechism");
  const [readingProgress, setReadingProgress] = useState(0);
  const [activeParagraphId, setActiveParagraphId] = useState<string | null>(null);
  const [activeHighlight, setActiveHighlight] = useState<UserNote | null>(null);
  const [isNoteModalOpen, setIsNoteModalOpen] = useState(false);

  useEffect(() => {
    if (initialParagraph === "invalid") {
      toast.error("Referência inválida do Catecismo — abrindo o índice.", { duration: 4000 });
    }
    // Só notifica uma vez por mudança de query.
  }, [initialParagraph]);

  // Deep-link ?p=N: resolve part+section para entrar em modo leitura.
  useEffect(() => {
    if (typeof initialParagraph !== "number") return;
    const part = CIC_SECTIONS.find((pt) =>
      pt.sections.some(
        (s) => initialParagraph >= s.paragraphs[0] && initialParagraph <= s.paragraphs[1],
      ),
    );
    if (!part) return;
    const section =
      part.sections.find(
        (s) => initialParagraph >= s.paragraphs[0] && initialParagraph <= s.paragraphs[1],
      ) || null;
    setSelectedPart(part);
    setSelectedSection(section);
    setViewMode("reading");
    setCurrentParagraph(initialParagraph);
  }, [initialParagraph]);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        if (viewMode === "reading") {
          setViewMode("sections");
          setTimeout(() => {
            if (lastFocusedElement) {
              document.getElementById(lastFocusedElement)?.focus();
            }
          }, 100);
        } else if (viewMode === "sections") {
          setViewMode("parts");
          setSelectedPart(null);
          setTimeout(() => {
            if (lastFocusedElement) {
              document.getElementById(lastFocusedElement)?.focus();
            }
          }, 100);
        }
      }
    };
    window.addEventListener("keydown", handleEsc);
    return () => window.removeEventListener("keydown", handleEsc);
  }, [viewMode, lastFocusedElement]);

  useEffect(() => {
    if (viewMode !== "reading") return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveParagraphId(entry.target.id);
            const pNum = parseInt(entry.target.id.replace("p", ""));
            if (!isNaN(pNum)) setCurrentParagraph(pNum);
          }
        });
      },
      { threshold: 0.5, rootMargin: "-10% 0px -70% 0px" },
    );
    document.querySelectorAll('[id^="p"]').forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [viewMode, selectedSection]);

  const goBack = () => {
    if (viewMode === "reading") {
      setViewMode("sections");
      setTimeout(() => {
        if (lastFocusedElement) document.getElementById(lastFocusedElement)?.focus();
      }, 100);
    } else if (viewMode === "sections") {
      setViewMode("parts");
      setSelectedPart(null);
      setTimeout(() => {
        if (lastFocusedElement) document.getElementById(lastFocusedElement)?.focus();
      }, 100);
    }
  };

  const jumpToParagraph = (p: number) => {
    const part = CIC_SECTIONS.find((pt) =>
      pt.sections.some((s) => p >= s.paragraphs[0] && p <= s.paragraphs[1]),
    );
    if (part) {
      const section = part.sections.find((s) => p >= s.paragraphs[0] && p <= s.paragraphs[1]);
      setSelectedPart(part);
      setSelectedSection(section || null);
      setCurrentParagraph(p);
      setViewMode("reading");
      setTimeout(() => {
        document.getElementById(`p${p}`)?.scrollIntoView({ behavior: "smooth", block: "center" });
      }, 300);
    }
  };

  const handleNavigateToBible = (abbr: string, chapter: number) =>
    navigate(`/bible?book=${abbr}&ch=${chapter}`);
  const handleNavigateToDoc = (docId: string) => navigate(`/magisterium?doc=${docId}`);

  const startPara = selectedSection?.paragraphs[0] || 1;
  const endPara = selectedSection?.paragraphs[1] || 2865;

  const currentChapterNotes = useMemo(() => {
    if (!selectedSection) return [];
    return chapterNotes.filter(
      (n) => (n.paragraph || 0) >= startPara && (n.paragraph || 0) <= endPara,
    );
  }, [chapterNotes, selectedSection, startPara, endPara]);

  // Localização canônica (Parte/Seção/Capítulo/Artigo/Tema) e moldura editorial.
  // Memoizadas por parágrafo — sem recomputar a cada scroll dentro do mesmo artigo.
  const location = useMemo(() => resolveCatechismLocation(currentParagraph), [currentParagraph]);
  const editorial = useMemo(() => resolveCatechismEditorial(location), [location]);
  const catechismClosure = useMemo(() => {
    const nextParagraph = Math.min(location.articleRange[1] + 1, 2865);
    const next =
      nextParagraph > currentParagraph
        ? {
            kicker: "Continuar",
            label: `Prosseguir em §${nextParagraph}`,
            href: `${AppRoute.CATECHISM}?p=${nextParagraph}`,
          }
        : undefined;
    return resolveEditorialClosure(buildCatechismClosure(location, editorial, next));
  }, [location, editorial, currentParagraph]);

  const nextUnreadParagraph = 1; // Simplified for template consistency

  // Nexus heurístico + relações curadas do grafo (Catecismo ⇄ Santos, Bíblia, Patrística…).
  const sectionNexus = useCatechismNexus(currentParagraph, location.articleRange);

  if (viewMode === "reading" && selectedSection && selectedPart) {
    return (
      <CatechismPendingProvider>
        <div className="flex flex-col md:flex-row w-full min-h-screen">
          {/* Desktop Sidebar: Sacred Visuals */}
          <div className="hidden md:flex md:w-[40%] sticky top-0 h-screen overflow-hidden bg-primary/5 border-r border-primary/5">
            <SacredImage
              src={undefined} // Generic sacred visual for Catechism
              className="w-full h-full object-cover opacity-40 mix-blend-multiply"
              alt="Catecismo da Igreja Católica"
            />
            <div className="absolute inset-0 bg-gradient-to-l from-background via-transparent to-transparent" />
            <div className="absolute inset-0 flex items-center justify-center p-spacing-xl">
              <div className="text-center space-y-spacing-md">
                <div className="w-spacing-4xl h-spacing-4xl mx-auto rounded-full bg-secondary/10 flex items-center justify-center border border-secondary/20 shadow-premium">
                  <Icons.BookOpen className="w-spacing-xl h-spacing-xl text-secondary" />
                </div>
                <h2 className="font-display text-4xl text-primary/40 tracking-widest uppercase italic">
                  Catechismus
                </h2>
                <p className="text-[10px] uppercase tracking-[0.4em] text-secondary/60 font-bold">
                  Ecclesiae Catholicae
                </p>
              </div>
            </div>
          </div>

          <div className="flex-1">
            <ReaderShell
              ariaLabel={`Catecismo — ${selectedSection.title}`}
              contentMaxWidth="max-w-4xl"
              hero={
                <EditorialHero
                  kicker={`Catecismo · ${selectedPart.part}`}
                  title={selectedSection.title}
                  subtitle={`${selectedPart.title} · §${startPara} — §${endPara}`}
                  size="md"
                  parchment
                  align="left"
                />
              }
              headerContext={
                <CatechesisContext
                  moduleTitle="Catecismo da Igreja Católica"
                  part={`${location.part} — ${location.partTitle}`}
                  section={location.section}
                  chapter={location.chapter}
                  article={location.article}
                  theme={location.theme}
                />
              }
              nexus={
                <NexusPanel
                  output={sectionNexus}
                  title="Nexus Theologicus"
                  kicker={`Conexões de §${currentParagraph}`}
                />
              }
              continuation={
                <div className="flex flex-col gap-spacing-2xl">
                  {catechismClosure && <EditorialClosure {...catechismClosure} />}

                  <ReaderContinuation
                    context={{
                      kind: "catechism",
                      id: String(currentParagraph),
                      graphNodeId: sectionNexus.selfId ?? undefined,
                      meta: {
                        paragraph: currentParagraph,
                        nextParagraph: currentParagraph + 1,
                      },
                    }}
                    suggestions={
                      sectionNexus.suggestions.length > 0 ? sectionNexus.suggestions : undefined
                    }
                  />
                </div>
              }
            >
              <div
                className="w-full editorial-column editorial-section"
                data-testid={`secao-${selectedSection.id}-conteudo`}
              >
                {/* Unified Reading Navigation */}
                <div className="flex items-center justify-between gap-spacing-md py-spacing-xs border-b border-primary/5 mb-spacing-md">
                  <Button
                    variant="ghost"
                    onClick={() => {
                      goBack();
                      setTimeout(() => {
                        if (lastFocusedElement)
                          document.getElementById(lastFocusedElement)?.focus();
                      }, 100);
                    }}
                    id="back-to-summary"
                    className="text-[10px] font-bold uppercase tracking-widest text-primary/40 hover:text-primary"
                    aria-label="Voltar para o sumário de seções"
                  >
                    ← Sumário
                  </Button>
                  <div className="flex items-center gap-spacing-lg">
                    <Button
                      disabled={selectedSection.id <= 1}
                      onClick={() => {
                        const prev = selectedPart.sections.find(
                          (s) => s.id === selectedSection.id - 1,
                        );
                        if (prev) {
                          setSelectedSection(prev);
                          setCurrentParagraph(prev.paragraphs[0]);
                          window.scrollTo(0, 0);
                        }
                      }}
                      data-testid="catechism-section-prev"
                      variant="ghost"
                      className="text-[10px] font-bold uppercase tracking-widest opacity-40 hover:opacity-100"
                    >
                      Anterior
                    </Button>
                    <span className="text-premium-xs font-serif italic text-primary/20">
                      Seção {selectedSection.id}
                    </span>
                    <Button
                      disabled={selectedSection.id >= 10}
                      onClick={() => {
                        const next = selectedPart.sections.find(
                          (s) => s.id === selectedSection.id + 1,
                        );
                        if (next) {
                          setSelectedSection(next);
                          setCurrentParagraph(next.paragraphs[0]);
                          window.scrollTo(0, 0);
                        }
                      }}
                      data-testid="catechism-section-next"
                      variant="ghost"
                      className="text-[10px] font-bold uppercase tracking-widest opacity-40 hover:opacity-100"
                    >
                      Próxima
                    </Button>
                  </div>
                  <ReadingControlPanel />
                </div>

                <CatechismPendingPanel
                  startPara={startPara}
                  endPara={endPara}
                  onJumpTo={(p) =>
                    document
                      .getElementById(`p${p}`)
                      ?.scrollIntoView({ behavior: "smooth", block: "center" })
                  }
                />

                <CatechismEditorialOpening location={location} editorial={editorial} />

                <div className="space-y-spacing-xl md:space-y-spacing-3xl">
                  {Array.from({ length: endPara - startPara + 1 }, (_, i) => startPara + i).map(
                    (p) => (
                      <LazyParagraph
                        key={p}
                        paragraph={p}
                        currentParagraph={currentParagraph}
                        paragraphsRead={new Set()}
                        isFavorite={isFavorite}
                        toggleFavorite={toggleFavorite}
                        handleNavigateToBible={handleNavigateToBible}
                        highlights={currentChapterNotes}
                      />
                    ),
                  )}
                </div>

                <CatechismFurtherReading editorial={editorial} />

                <EditorialDivider
                  variant="gold-fade"
                  className="max-w-[240px] mx-auto mt-spacing-4xl mb-spacing-2xl"
                />
                <div>
                  <Relatio
                    context={{ type: "catechism", paragraph: currentParagraph }}
                    onNavigateToBible={handleNavigateToBible}
                    onNavigateToCIC={jumpToParagraph}
                    onNavigateToDoc={handleNavigateToDoc}
                  />
                </div>
              </div>
            </ReaderShell>
          </div>
        </div>
        <CatechismDiagnosticPanel />
      </CatechismPendingProvider>
    );
  }

  if (viewMode === "sections" && selectedPart) {
    return (
      <ContemplativeLayout>
        <div className="w-full space-y-spacing-lg md:space-y-spacing-2xl pb-spacing-2xl md:pb-spacing-4xl">
          <EditorialHero
            kicker={`Catecismo · ${selectedPart.part}`}
            title={selectedPart.title}
            subtitle={`Selecione uma seção para iniciar a leitura · ${selectedPart.sections.length} seções`}
            size="sm"
            parchment
          />

          <div className="flex justify-center">
            <Button
              variant="ghost"
              onClick={goBack}
              className="px-spacing-xl py-spacing-sm h-auto rounded-premium-full text-[9px] font-black uppercase tracking-[0.3em] text-primary/40 hover:text-primary border border-primary/5 transition-all"
            >
              <Icons.ChevronLeft className="w-spacing-sm h-spacing-sm mr-spacing-xs" /> Voltar às
              Partes
            </Button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-spacing-md">
            {selectedPart.sections.map((sec, idx) => (
              <CathedraCard
                key={sec.id}
                id={`section-card-${sec.id}`}
                data-testid={`secao-${sec.id}`}
                variant="interactive"
                padding="none"
                role="button"
                tabIndex={0}
                aria-label={`Seção ${sec.id}: ${sec.title}`}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    setLastFocusedElement(`section-card-${sec.id}`);
                    setSelectedSection(sec);
                    setViewMode("reading");
                    setCurrentParagraph(sec.paragraphs[0]);
                    window.scrollTo(0, 0);
                  }
                }}
                onClick={() => {
                  setLastFocusedElement(`section-card-${sec.id}`);
                  setSelectedSection(sec);
                  setViewMode("reading");
                  setCurrentParagraph(sec.paragraphs[0]);
                  window.scrollTo(0, 0);
                }}
                className="group focus-within:ring-2 focus-within:ring-primary focus-within:outline-none"
              >
                <div className="p-spacing-lg flex items-center justify-between h-full">
                  <div className="space-y-spacing-xs text-left">
                    <span className="text-[8px] font-black uppercase tracking-widest text-primary/30">
                      Seção {sec.id}
                    </span>
                    <h3 className="text-premium-base font-display font-light text-foreground/80 group-hover:text-primary transition-colors leading-snug">
                      {sec.title}
                    </h3>
                    <p className="text-[9px] text-muted-foreground/50 italic tracking-wider uppercase">
                      §{sec.paragraphs[0]} — §{sec.paragraphs[1]}
                    </p>
                  </div>
                  <Icons.ChevronRight className="w-spacing-sm h-spacing-sm text-primary/10 group-hover:text-primary group-hover:translate-x-0.5 transition-all shrink-0" />
                </div>
              </CathedraCard>
            ))}
          </div>
        </div>
      </ContemplativeLayout>
    );
  }

  return (
    <ContemplativeLayout maxW="max-w-5xl w-full">
      <SEOHead
        title="Catecismo da Igreja Católica | Cathedra Digital"
        description="Doutrina católica organizada por parágrafos."
        path="/catechism"
      />
      <div className="w-full space-y-8 md:space-y-14 pb-spacing-2xl md:pb-spacing-4xl">
        {/* HERO Noir & Gold */}
        <div className="text-center space-y-4 pt-spacing-sm md:pt-spacing-xl">
          <div className="flex items-center justify-center gap-3" aria-hidden="true">
            <span className="h-px w-10 md:w-16" style={{ backgroundColor: "#c9a84c" }} />
            <span
              className="text-[9px] md:text-[10px] uppercase"
              style={{
                color: "var(--gold-text)",
                fontFamily: "Inter, sans-serif",
                letterSpacing: "0.32em",
              }}
            >
              Sacra Doctrina
            </span>
            <span className="h-px w-10 md:w-16" style={{ backgroundColor: "#c9a84c" }} />
          </div>
          <h1
            className="leading-none"
            style={{
              fontFamily: "'Playfair Display', serif",
              fontWeight: 500,
              fontSize: "clamp(2.25rem, 6vw, 4rem)",
              letterSpacing: "0.01em",
            }}
          >
            Catecismo<span style={{ color: "var(--gold-text)" }}>.</span>
          </h1>
          <p
            className="mx-auto"
            style={{
              fontFamily: "'Playfair Display', serif",
              fontStyle: "italic",
              fontSize: "clamp(0.95rem, 1.5vw, 1.1rem)",
              color: "hsl(var(--muted-foreground))",
              maxWidth: "48ch",
              lineHeight: 1.65,
            }}
          >
            A doutrina da Igreja em quatro partes —{" "}
            <span style={{ color: "var(--gold-text)" }}>Credo</span>,{" "}
            <span style={{ color: "var(--gold-text)" }}>Sacramentos</span>,{" "}
            <span style={{ color: "var(--gold-text)" }}>Vida em Cristo</span> e{" "}
            <span style={{ color: "var(--gold-text)" }}>Oração</span>.
          </p>
        </div>

        {/* BUSCA */}
        <div className="sticky top-0 z-20 bg-background/85 backdrop-blur-md py-3 -mx-spacing-md px-spacing-md">
          <div className="relative group max-w-2xl mx-auto">
            <Icons.Search
              className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 transition-colors"
              style={{ color: "var(--gold-text)", opacity: 0.6 }}
            />
            <input
              type="text"
              placeholder="Buscar por parágrafo (§) ou tema..."
              aria-label="Buscar no Catecismo por parágrafo ou tema"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onKeyDown={(e) =>
                e.key === "Enter" && jumpToParagraph(parseInt(searchQuery.replace("§", "")))
              }
              className="w-full bg-transparent border-0 border-b py-3 pl-12 pr-4 focus:outline-none focus:ring-0"
              style={{
                borderBottomColor: "#c9a84c",
                borderBottomWidth: 1,
                fontFamily: "'Playfair Display', serif",
                fontStyle: "italic",
                fontSize: "1rem",
                color: "hsl(var(--foreground))",
              }}
            />
          </div>
        </div>

        {/* CARDS DE PARTES */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5 md:gap-6">
          {CIC_SECTIONS.map((part, idx) => (
            <div
              key={part.part}
              id={`part-card-${idx}`}
              onClick={() => {
                setLastFocusedElement(`part-card-${idx}`);
                setSelectedPart(part);
                setViewMode("sections");
              }}
              className="group cursor-pointer p-6 md:p-8 flex flex-col justify-between min-h-[180px] text-left transition-all duration-500 rounded-none focus-visible:outline-none"
              style={{
                border: "1px solid rgba(201, 168, 76, 0.35)",
                background: "transparent",
              }}
              tabIndex={0}
              role="button"
              aria-label={`Ver ${part.part}: ${part.title}`}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  setLastFocusedElement(`part-card-${idx}`);
                  setSelectedPart(part);
                  setViewMode("sections");
                }
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = "#c9a84c";
                e.currentTarget.style.background = "rgba(201, 168, 76, 0.04)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = "rgba(201, 168, 76, 0.35)";
                e.currentTarget.style.background = "transparent";
              }}
            >
              <div className="space-y-3">
                <div className="flex items-center gap-3">
                  <span
                    className="text-[10px] uppercase shrink-0"
                    style={{
                      color: "var(--gold-text)",
                      fontFamily: "Inter, sans-serif",
                      letterSpacing: "0.32em",
                    }}
                  >
                    {part.part}
                  </span>
                  <div
                    className="h-px flex-1"
                    style={{ backgroundColor: "#c9a84c", opacity: 0.4 }}
                  />
                </div>
                <h2
                  className="leading-tight break-words"
                  style={{
                    fontFamily: "'Playfair Display', serif",
                    fontWeight: 400,
                    fontSize: "clamp(1.35rem, 2.4vw, 1.75rem)",
                    color: "hsl(var(--foreground))",
                  }}
                >
                  {part.title}
                </h2>
              </div>
              <div className="flex items-center justify-between pt-6">
                <p
                  className="text-[10px] uppercase"
                  style={{
                    color: "hsl(var(--muted-foreground))",
                    fontFamily: "Inter, sans-serif",
                    letterSpacing: "0.28em",
                  }}
                >
                  {part.sections.length} seções
                </p>
                <Icons.ChevronRight
                  className="w-4 h-4 transition-transform group-hover:translate-x-1"
                  style={{ color: "var(--gold-text)" }}
                />
              </div>
            </div>
          ))}
        </div>
      </div>
      <CatechismDiagnosticPanel />
    </ContemplativeLayout>
  );
});

export default Catechism;

/**
 * AtriumCommunityPage — Etapa M10 (Comunidade).
 *
 * Feed editorial com lista de discussões aprovadas, seletor de categoria,
 * criação de post inline e links para /community/post/:id e /community/user/:userId.
 * A versão anterior (fórum + ranking + busca fuzzy) segue em /community-legacy.
 */

import React, { useCallback, useEffect, useMemo, useState } from "react";
import { Helmet } from "@/lib/helmet-compat";
import { Link, useNavigate } from "@/lib/rr-compat";
import {
  MessageCircle,
  Plus,
  Heart,
  Sparkles,
  Users,
  ArrowRight,
  User,
  Calendar,
  BookOpen,
} from "lucide-react";
import { EditorialHero } from "@/components/editorial/harmony";
import { SpaceLayout, SpaceHeader, SpaceFooter } from "@/components/cathedra/space/SpaceLayout";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { AppRoute } from "@/types";
import { toast } from "sonner";

const CATEGORIES = [
  { id: "geral", label: "Geral" },
  { id: "testemunho", label: "Testemunho" },
  { id: "partilha", label: "Partilha" },
  { id: "teologia", label: "Teologia" },
  { id: "biblia", label: "Bíblia" },
  { id: "liturgia", label: "Liturgia" },
  { id: "moral", label: "Moral" },
  { id: "espiritualidade", label: "Espiritualidade" },
];

type Post = {
  id: string;
  user_id: string;
  title: string | null;
  content: string;
  category: string;
  likes_count: number;
  created_at: string;
  status: string | null;
  author_name?: string;
  replies_count?: number;
};

function timeAgo(dateStr: string) {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "agora";
  if (mins < 60) return `${mins}min`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h`;
  const days = Math.floor(hours / 24);
  return `${days}d`;
}

const AtriumCommunityPage: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [category, setCategory] = useState("geral");
  const [posts, setPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [showNew, setShowNew] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newContent, setNewContent] = useState("");
  const [newCategory, setNewCategory] = useState("geral");
  const [submitting, setSubmitting] = useState(false);

  const fetchPosts = useCallback(async () => {
    setLoading(true);
    let q = supabase
      .from("community_posts")
      .select("*")
      .is("parent_id", null)
      .order("created_at", { ascending: false })
      .limit(50);
    if (category !== "geral") q = q.eq("category", category);
    const { data, error } = await q;
    if (error) {
      setLoading(false);
      return;
    }
    const rows = data || [];
    const userIds = [...new Set(rows.map((r) => r.user_id))];
    let profileMap = new Map<string, string>();
    if (userIds.length) {
      const { data: profiles } = (await supabase
        .from("public_profiles" as any)
        .select("id, name")
        .in("id", userIds)) as { data: { id: string; name: string }[] | null };
      profileMap = new Map((profiles || []).map((p) => [p.id, p.name]));
    }
    // count replies
    const replyCounts = new Map<string, number>();
    if (rows.length) {
      const { data: replies } = await supabase
        .from("community_posts")
        .select("parent_id")
        .in(
          "parent_id",
          rows.map((r) => r.id),
        );
      (replies || []).forEach((r: any) => {
        if (!r.parent_id) return;
        replyCounts.set(r.parent_id, (replyCounts.get(r.parent_id) || 0) + 1);
      });
    }
    const enriched: Post[] = rows
      .map((p) => ({
        ...p,
        author_name: profileMap.get(p.user_id) || "Anônimo",
        replies_count: replyCounts.get(p.id) || 0,
      }))
      .filter((p) => p.status === "approved" || p.user_id === user?.id);
    setPosts(enriched);
    setLoading(false);
  }, [category, user?.id]);

  useEffect(() => {
    fetchPosts();
  }, [fetchPosts]);

  const submitPost = async () => {
    if (!user) {
      navigate(AppRoute.LOGIN);
      return;
    }
    const content = newContent.trim();
    if (!content) return;
    setSubmitting(true);
    const { error } = await supabase.from("community_posts").insert({
      user_id: user.id,
      title: newTitle.trim() || null,
      content,
      category: newCategory,
      status: "pending",
    });
    setSubmitting(false);
    if (error) {
      toast.error("Não foi possível publicar");
      return;
    }
    toast.success("Enviado para moderação");
    setNewTitle("");
    setNewContent("");
    setShowNew(false);
    fetchPosts();
  };

  const emptyState = useMemo(() => !loading && posts.length === 0, [loading, posts.length]);

  return (
    <>
      <Helmet>
        <title>Comunidade — Cathedra</title>
        <meta
          name="description"
          content="Discussões, testemunhos e partilhas entre irmãos na fé."
        />
        <link rel="canonical" href="https://cathedradigital.com.br/community" />
      </Helmet>

      <SpaceLayout>
        <EditorialHero density="minimal">
          <EditorialHero.Eyebrow>Communitas Fidelium</EditorialHero.Eyebrow>
          <EditorialHero.Title>Igreja Viva</EditorialHero.Title>
          <EditorialHero.Subtitle>
            Um lugar para partilhar a caminhada — testemunhos, dúvidas e leituras entre irmãos na
            fé.
          </EditorialHero.Subtitle>
        </EditorialHero>

        {/* ─── IGREJA VIVA: SSoT Grouping ─── */}
        <section className="mt-8 mb-12">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="p-4 border border-border/20 bg-accent rounded-premium text-center">
              <span className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-gold-text mb-2">
                <Sparkles className="w-3 h-3" /> SANTO DO DIA
              </span>
              <p className="font-display text-sm italic text-primary">São João Batista</p>
            </div>
            <div className="p-4 border border-border/20 bg-accent rounded-premium text-center">
              <span className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-gold-text mb-2">
                <User className="w-3 h-3" /> PAPA ATUAL
              </span>
              <p className="font-display text-sm italic text-primary">Francisco</p>
            </div>
            <div className="p-4 border border-border/20 bg-accent rounded-premium text-center">
              <span className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-gold-text mb-2">
                <BookOpen className="w-3 h-3" /> LITURGIA
              </span>
              <p className="font-display text-sm italic text-primary">Féria da Semana</p>
            </div>
            <div className="p-4 border border-border/20 bg-accent rounded-premium text-center">
              <span className="flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest text-gold-text mb-2">
                <Calendar className="w-3 h-3" /> CALENDÁRIO
              </span>
              <p className="font-display text-sm italic text-primary">24 Jun 2026</p>
            </div>
          </div>
        </section>

        {/* Barra de ações */}
        <section className="max-w-4xl mx-auto px-6 pt-8 flex flex-wrap items-center gap-3">
          <div className="flex-1 min-w-0 flex gap-2 overflow-x-auto scrollbar-hide">
            {CATEGORIES.map((c) => (
              <button
                key={c.id}
                onClick={() => setCategory(c.id)}
                className={`shrink-0 px-3 py-1.5 rounded-full text-xs font-semibold uppercase tracking-wider border transition-colors ${
                  category === c.id
                    ? "bg-foreground text-background border-foreground"
                    : "bg-card text-muted-foreground border-border hover:text-foreground"
                }`}
                aria-pressed={category === c.id}
              >
                {c.label}
              </button>
            ))}
          </div>
          <button
            onClick={() => (user ? setShowNew((v) => !v) : navigate(AppRoute.LOGIN))}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-primary text-primary-foreground text-xs font-bold uppercase tracking-widest shadow-sm hover:opacity-90"
          >
            <Plus className="w-4 h-4" />
            Nova
          </button>
        </section>

        {/* Criação de post */}
        {showNew && (
          <section className="max-w-4xl mx-auto px-6 mt-6">
            <div className="rounded-2xl border border-border bg-card p-5 space-y-3">
              <input
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                placeholder="Título (opcional)"
                className="w-full bg-background border border-border rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/40"
              />
              <textarea
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Partilhe algo edificante..."
                rows={4}
                className="w-full bg-background border border-border rounded-xl px-3 py-2 text-sm resize-y focus:outline-none focus:ring-2 focus:ring-primary/40"
              />
              <div className="flex items-center gap-2 flex-wrap">
                <select
                  value={newCategory}
                  onChange={(e) => setNewCategory(e.target.value)}
                  className="bg-background border border-border rounded-full px-3 py-1.5 text-xs uppercase tracking-widest font-semibold"
                >
                  {CATEGORIES.filter((c) => c.id !== "geral").map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.label}
                    </option>
                  ))}
                </select>
                <span className="text-[11px] text-muted-foreground">
                  Enviado para moderação antes de aparecer no feed.
                </span>
                <div className="ml-auto flex gap-2">
                  <button
                    onClick={() => setShowNew(false)}
                    className="px-3 py-1.5 text-xs uppercase tracking-widest text-muted-foreground hover:text-foreground"
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={submitPost}
                    disabled={submitting || !newContent.trim()}
                    className="px-4 py-2 rounded-full bg-foreground text-background text-xs font-bold uppercase tracking-widest disabled:opacity-40"
                  >
                    {submitting ? "Enviando…" : "Publicar"}
                  </button>
                </div>
              </div>
            </div>
          </section>
        )}

        {/* Feed */}
        <section className="max-w-4xl mx-auto px-6 py-10">
          {loading ? (
            <div className="space-y-3">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className="h-28 rounded-2xl bg-muted/40 animate-pulse" />
              ))}
            </div>
          ) : emptyState ? (
            <div
              className="text-center py-20 space-y-5 max-w-lg mx-auto"
              role="status"
              aria-live="polite"
            >
              <Sparkles className="w-8 h-8 mx-auto text-primary/50" aria-hidden />
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-primary/15 bg-primary/5 text-[10px] uppercase tracking-[0.3em] text-primary font-semibold">
                Silentium
              </div>
              <h2 className="font-serif text-2xl md:text-3xl leading-snug text-foreground">
                A praça ainda repousa em silêncio
              </h2>
              <p className="text-muted-foreground font-serif italic text-base leading-relaxed">
                Nenhuma partilha aprovada por aqui — nem toda estação tem palavras. Volte em breve
                ou seja a primeira voz a ecoar nesta categoria.
              </p>
              {user ? (
                <button
                  onClick={() => setShowNew(true)}
                  className="inline-flex items-center gap-2 px-5 py-2.5 rounded-full bg-foreground text-background text-xs font-bold uppercase tracking-widest hover:opacity-90"
                >
                  <Plus className="w-4 h-4" aria-hidden />
                  Abrir a primeira partilha
                </button>
              ) : (
                <button
                  onClick={() => navigate(AppRoute.LOGIN)}
                  className="text-primary text-sm font-semibold underline underline-offset-4"
                >
                  Entrar para partilhar
                </button>
              )}
            </div>
          ) : (
            <ul className="space-y-3">
              {posts.map((p) => (
                <li key={p.id}>
                  <Link
                    to={`/community/post/${p.id}`}
                    className="block rounded-2xl border border-border bg-card p-5 hover:border-primary/40 transition-colors"
                  >
                    <div className="flex items-center gap-3 mb-2 text-xs text-muted-foreground">
                      <Link
                        to={`/community/user/${p.user_id}`}
                        onClick={(e) => e.stopPropagation()}
                        className="inline-flex items-center gap-2 hover:text-foreground"
                      >
                        <span className="w-7 h-7 rounded-full bg-muted flex items-center justify-center font-bold text-foreground text-[11px]">
                          {(p.author_name || "A").charAt(0).toUpperCase()}
                        </span>
                        <span className="font-semibold text-foreground">{p.author_name}</span>
                      </Link>
                      <span>·</span>
                      <span>{timeAgo(p.created_at)}</span>
                      <span className="ml-auto uppercase tracking-widest text-[10px] font-bold text-primary">
                        {CATEGORIES.find((c) => c.id === p.category)?.label || p.category}
                      </span>
                    </div>
                    {p.title && (
                      <h2 className="font-serif text-xl md:text-2xl leading-snug mb-1">
                        {p.title}
                      </h2>
                    )}
                    <p className="text-sm text-foreground/80 line-clamp-3 whitespace-pre-wrap">
                      {p.content}
                    </p>
                    <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
                      <span className="inline-flex items-center gap-1">
                        <Heart className="w-3.5 h-3.5" /> {p.likes_count}
                      </span>
                      <span className="inline-flex items-center gap-1">
                        <MessageCircle className="w-3.5 h-3.5" /> {p.replies_count}
                      </span>
                      {p.status !== "approved" && (
                        <span className="ml-auto text-[10px] uppercase tracking-widest text-amber-600">
                          Aguardando moderação
                        </span>
                      )}
                      <ArrowRight className="ml-auto w-4 h-4 text-muted-foreground/60" />
                    </div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </section>

        <SpaceFooter
          note="Onde dois ou três estiverem reunidos em meu nome, eu estarei no meio deles."
          links={[
            { label: "Átrio", to: "/", hint: "Entrada do Mosteiro" },
            { label: "Biblioteca", to: "/biblioteca", hint: "Mosteiro do Conhecimento" },
            { label: "Sacrário", to: "/oracao", hint: "Silenciar e rezar" },
          ]}
        />
      </SpaceLayout>
    </>
  );
};

export default AtriumCommunityPage;

/**
 * AtriumCommunityPostPage — Detalhe de post público em /community/post/:id.
 * Mostra o post original, respostas aprovadas e formulário de resposta.
 */

import React, { useCallback, useEffect, useState } from "react";
import { Helmet } from "@/lib/helmet-compat";
import { Link, useNavigate, useParams } from "@/lib/rr-compat";
import { ArrowLeft, Heart, MessageCircle } from "lucide-react";
import { supabase } from "@/lib/db";
import { useAuth } from "@/hooks/useAuth";
import { AppRoute } from "@/types";
import { toast } from "sonner";

type Post = {
  id: string;
  user_id: string;
  parent_id: string | null;
  title: string | null;
  content: string;
  category: string;
  likes_count: number;
  created_at: string;
  status: string | null;
  author_name?: string;
  user_liked?: boolean;
};

function timeAgo(dateStr: string) {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "agora";
  if (mins < 60) return `${mins}min`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h`;
  const days = Math.floor(hours / 24);
  return `${days}d`;
}

const AtriumCommunityPostPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [post, setPost] = useState<Post | null>(null);
  const [replies, setReplies] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [replyContent, setReplyContent] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const fetch = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    const { data: p, error } = await supabase
      .from("community_posts")
      .select("*")
      .eq("id", id)
      .maybeSingle();
    if (error || !p) {
      setNotFound(true);
      setLoading(false);
      return;
    }
    const { data: replyRows } = await supabase
      .from("community_posts")
      .select("*")
      .eq("parent_id", id)
      .order("created_at", { ascending: true });

    const userIds = [...new Set([p.user_id, ...(replyRows || []).map((r) => r.user_id)])];
    const { data: profiles } = (await supabase
      .from("public_profiles" as any)
      .select("id, name")
      .in("id", userIds)) as { data: { id: string; name: string }[] | null };
    const profileMap = new Map((profiles || []).map((x) => [x.id, x.name]));

    let userLiked = false;
    if (user) {
      const { data: like } = await supabase
        .from("community_likes")
        .select("post_id")
        .eq("post_id", p.id)
        .eq("user_id", user.id)
        .maybeSingle();
      userLiked = !!like;
    }

    setPost({
      ...p,
      author_name: profileMap.get(p.user_id) || "Anônimo",
      user_liked: userLiked,
    });
    setReplies(
      (replyRows || [])
        .filter((r) => r.status === "approved" || r.user_id === user?.id)
        .map((r) => ({
          ...r,
          author_name: profileMap.get(r.user_id) || "Anônimo",
        })),
    );
    setLoading(false);
  }, [id, user]);

  useEffect(() => {
    fetch();
  }, [fetch]);

  const toggleLike = async () => {
    if (!user || !post) {
      navigate(AppRoute.LOGIN);
      return;
    }
    if (post.user_liked) {
      await supabase.from("community_likes").delete().eq("post_id", post.id).eq("user_id", user.id);
    } else {
      await supabase.from("community_likes").insert({ post_id: post.id, user_id: user.id });
    }
    fetch();
  };

  const submitReply = async () => {
    if (!user || !post) {
      navigate(AppRoute.LOGIN);
      return;
    }
    const content = replyContent.trim();
    if (!content) return;
    setSubmitting(true);
    const { error } = await supabase.from("community_posts").insert({
      user_id: user.id,
      parent_id: post.id,
      content,
      category: post.category,
      status: "pending",
    });
    setSubmitting(false);
    if (error) {
      toast.error("Não foi possível responder");
      return;
    }
    toast.success("Resposta enviada para moderação");
    setReplyContent("");
    fetch();
  };

  if (loading) {
    return (
      <div className="max-w-3xl mx-auto px-6 py-16 space-y-4">
        <div className="h-6 w-32 bg-muted/40 rounded animate-pulse" />
        <div className="h-40 rounded-2xl bg-muted/40 animate-pulse" />
      </div>
    );
  }

  if (notFound || !post) {
    return (
      <div className="max-w-3xl mx-auto px-6 py-16 text-center space-y-4">
        <p className="text-muted-foreground">Discussão não encontrada.</p>
        <Link
          to="/community"
          className="inline-flex items-center gap-2 text-primary text-sm font-semibold"
        >
          <ArrowLeft className="w-4 h-4" /> Voltar à comunidade
        </Link>
      </div>
    );
  }

  return (
    <>
      <Helmet>
        <title>{post.title ? `${post.title} — Comunidade` : "Discussão — Comunidade"}</title>
        <meta name="description" content={post.content.slice(0, 155)} />
      </Helmet>

      <section className="min-h-screen bg-background text-foreground">
        <div className="max-w-3xl mx-auto px-6 py-8 space-y-6">
          <Link
            to="/community"
            className="inline-flex items-center gap-2 text-xs uppercase tracking-widest text-muted-foreground hover:text-foreground"
          >
            <ArrowLeft className="w-4 h-4" /> Comunidade
          </Link>

          <article className="rounded-2xl border border-border bg-card p-6 space-y-4">
            <div className="flex items-center gap-3 text-xs text-muted-foreground">
              <Link
                to={`/community/user/${post.user_id}`}
                className="inline-flex items-center gap-2 hover:text-foreground"
              >
                <span className="w-8 h-8 rounded-full bg-muted flex items-center justify-center font-bold text-foreground text-xs">
                  {(post.author_name || "A").charAt(0).toUpperCase()}
                </span>
                <span className="font-semibold text-foreground">{post.author_name}</span>
              </Link>
              <span>·</span>
              <span>{timeAgo(post.created_at)}</span>
              <span className="ml-auto uppercase tracking-widest text-[10px] font-bold text-primary">
                {post.category}
              </span>
            </div>
            {post.title && (
              <h1 className="font-serif text-3xl md:text-4xl leading-tight">{post.title}</h1>
            )}
            <p className="text-foreground/85 leading-relaxed whitespace-pre-wrap">{post.content}</p>
            <div className="pt-3 border-t border-border flex items-center gap-4">
              <button
                onClick={toggleLike}
                aria-pressed={post.user_liked}
                className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-primary"
              >
                <Heart
                  className={`w-4 h-4 ${post.user_liked ? "fill-primary text-primary" : ""}`}
                />
                {post.likes_count}
              </button>
              <span className="inline-flex items-center gap-2 text-sm text-muted-foreground">
                <MessageCircle className="w-4 h-4" />
                {replies.length}
              </span>
              {post.status !== "approved" && (
                <span className="ml-auto text-[10px] uppercase tracking-widest text-amber-600">
                  Aguardando moderação
                </span>
              )}
            </div>
          </article>

          <section className="space-y-3">
            <h2 className="text-xs uppercase tracking-[0.3em] text-muted-foreground font-semibold">
              Respostas
            </h2>
            {replies.length === 0 ? (
              <p className="text-sm text-muted-foreground italic">Nenhuma resposta ainda.</p>
            ) : (
              <ul className="space-y-3">
                {replies.map((r) => (
                  <li key={r.id} className="rounded-2xl border border-border bg-card p-4">
                    <div className="flex items-center gap-2 mb-2 text-xs text-muted-foreground">
                      <Link
                        to={`/community/user/${r.user_id}`}
                        className="inline-flex items-center gap-2 hover:text-foreground"
                      >
                        <span className="w-6 h-6 rounded-full bg-muted flex items-center justify-center font-bold text-foreground text-[10px]">
                          {(r.author_name || "A").charAt(0).toUpperCase()}
                        </span>
                        <span className="font-semibold text-foreground">{r.author_name}</span>
                      </Link>
                      <span>·</span>
                      <span>{timeAgo(r.created_at)}</span>
                      {r.status !== "approved" && (
                        <span className="ml-auto text-[10px] uppercase tracking-widest text-amber-600">
                          Em moderação
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-foreground/85 whitespace-pre-wrap">{r.content}</p>
                  </li>
                ))}
              </ul>
            )}
          </section>

          {user ? (
            <div className="rounded-2xl border border-border bg-card p-4 space-y-3">
              <textarea
                value={replyContent}
                onChange={(e) => setReplyContent(e.target.value)}
                placeholder="Escreva sua resposta…"
                rows={3}
                className="w-full bg-background border border-border rounded-xl px-3 py-2 text-sm resize-y focus:outline-none focus:ring-2 focus:ring-primary/40"
              />
              <div className="flex justify-end">
                <button
                  onClick={submitReply}
                  disabled={submitting || !replyContent.trim()}
                  className="px-4 py-2 rounded-full bg-foreground text-background text-xs font-bold uppercase tracking-widest disabled:opacity-40"
                >
                  {submitting ? "Enviando…" : "Responder"}
                </button>
              </div>
            </div>
          ) : (
            <button
              onClick={() => navigate(AppRoute.LOGIN)}
              className="w-full py-3 rounded-full border border-border text-sm font-semibold hover:border-primary/50"
            >
              Faça login para responder
            </button>
          )}
        </div>
      </section>
    </>
  );
};

