import { useEffect, useState } from "react";
import { useSearchParams } from "@/lib/rr-compat";
import { Helmet } from "@/lib/helmet-compat";
import { supabase } from "@/lib/db";

// Rota /.lovable/oauth/consent — tela de consentimento OAuth 2.1 para clientes MCP
// externos (ChatGPT, Claude, Cursor, etc.) autorizarem acesso à conta Cathedra.
type OAuthApi = {
  getAuthorizationDetails: (id: string) => Promise<{ data: any; error: any }>;
  approveAuthorization: (id: string) => Promise<{ data: any; error: any }>;
  denyAuthorization: (id: string) => Promise<{ data: any; error: any }>;
};

function oauth(): OAuthApi {
  return (supabase.auth as unknown as { oauth: OAuthApi }).oauth;
}

export default function OAuthConsent() {
  const [params] = useSearchParams();
  const authorizationId = params.get("authorization_id") ?? "";
  const [details, setDetails] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let active = true;
    (async () => {
      if (!authorizationId) {
        setError("Requisição inválida: authorization_id ausente.");
        return;
      }
      const { data: sess } = await supabase.auth.getSession();
      if (!sess.session) {
        const next = window.location.pathname + window.location.search;
        window.location.href = "/auth?next=" + encodeURIComponent(next);
        return;
      }
      try {
        const { data, error } = await oauth().getAuthorizationDetails(authorizationId);
        if (!active) return;
        if (error) {
          setError(error.message ?? "Não foi possível carregar esta autorização.");
          return;
        }
        const immediate = data?.redirect_url ?? data?.redirect_to;
        if (immediate && !data?.client) {
          window.location.href = immediate;
          return;
        }
        setDetails(data);
      } catch (e: any) {
        if (active) setError(e?.message ?? String(e));
      }
    })();
    return () => {
      active = false;
    };
  }, [authorizationId]);

  async function decide(approve: boolean) {
    setBusy(true);
    setError(null);
    try {
      const { data, error } = approve
        ? await oauth().approveAuthorization(authorizationId)
        : await oauth().denyAuthorization(authorizationId);
      if (error) {
        setBusy(false);
        setError(error.message ?? "Falha ao registrar decisão.");
        return;
      }
      const target = data?.redirect_url ?? data?.redirect_to;
      if (!target) {
        setBusy(false);
        setError("Servidor de autorização não retornou URL de redirecionamento.");
        return;
      }
      window.location.href = target;
    } catch (e: any) {
      setBusy(false);
      setError(e?.message ?? String(e));
    }
  }

  const clientName = details?.client?.name ?? details?.client?.client_name ?? "um aplicativo";
  const scopes: string[] = details?.requested_scopes ?? details?.scopes ?? [];

  return (
    <section className="cathedra-noir min-h-screen w-full flex items-center justify-center px-6 py-16">
      <Helmet>
        <title>Autorizar acesso · Cathedra</title>
        <meta name="robots" content="noindex,nofollow" />
      </Helmet>
      <div className="w-full max-w-md rounded-2xl border border-[var(--noir-line)] bg-black/30 backdrop-blur p-8">
        <h1 className="text-2xl font-serif text-[var(--noir-text)] mb-2">
          Conectar {clientName} à sua conta
        </h1>
        <p className="text-sm text-[var(--noir-text-muted)] mb-6">
          Este cliente poderá usar as ferramentas da Cathedra como você enquanto estiver conectado.
          As permissões e políticas do backend continuam válidas.
        </p>

        {error && (
          <div className="rounded border border-red-500/40 bg-red-500/10 px-4 py-3 text-sm text-red-200 mb-4">
            {error}
          </div>
        )}

        {!details && !error && (
          <p className="text-sm text-[var(--noir-text-muted)]">Carregando autorização…</p>
        )}

        {details && (
          <>
            {details.client?.redirect_uri && (
              <div className="text-xs text-[var(--noir-text-muted)] mb-4 break-all">
                Redirect: <code>{details.client.redirect_uri}</code>
              </div>
            )}
            {scopes.length > 0 && (
              <ul className="text-sm text-[var(--noir-text)] mb-6 space-y-1">
                {scopes.map((s) => (
                  <li key={s}>• {s}</li>
                ))}
              </ul>
            )}
            <div className="flex gap-3">
              <button
                disabled={busy}
                onClick={() => decide(true)}
                className="flex-1 rounded bg-[var(--gold)] text-black py-2 font-medium disabled:opacity-50"
              >
                Aprovar
              </button>
              <button
                disabled={busy}
                onClick={() => decide(false)}
                className="flex-1 rounded border border-[var(--noir-line-strong)] text-[var(--noir-text)] py-2 disabled:opacity-50"
              >
                Recusar
              </button>
            </div>
          </>
        )}
      </div>
    </section>
  );
}

import { Icons } from "@/constants";
import React, { useEffect, useState, useMemo } from "react";
import { supabase } from "@/lib/db";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import SecurityRescanReportCard from "@/components/cathedra/SecurityRescanReportCard";

const PAGE_SIZE = 20;

const SecurityDashboard = () => {
  const [logs, setLogs] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(0);

  // Filters
  const [userFilter, setUserFilter] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [resourceFilter, setResourceFilter] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [actionFilter, setActionFilter] = useState("");

  // Selection
  const [selectedLog, setSelectedLog] = useState<any>(null);

  useEffect(() => {
    fetchLogs();
  }, [currentPage, typeFilter]);

  const fetchLogs = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from("security_audit_logs" as any)
        .select(
          `
          *,
          profiles:metadata->>'userId'
        `,
          { count: "exact" },
        )
        .order("created_at", { ascending: false })
        .range(currentPage * PAGE_SIZE, (currentPage + 1) * PAGE_SIZE - 1);

      if (typeFilter !== "all") {
        query = query.eq("event_type", typeFilter);
      }

      const { data, error, count } = await query;

      if (error) {
        console.error("Error fetching logs:", error);
        toast.error("Erro ao carregar logs de segurança");
      } else {
        setLogs(data || []);
        setTotalCount(count || 0);
      }
    } catch (err) {
      console.error("Unexpected error:", err);
    } finally {
      setLoading(false);
    }
  };

  const filteredLogs = useMemo(() => {
    return logs.filter((log) => {
      const matchesUser =
        !userFilter ||
        log.metadata?.userId?.toLowerCase().includes(userFilter.toLowerCase()) ||
        log.description?.toLowerCase().includes(userFilter.toLowerCase());

      const matchesResource =
        !resourceFilter || log.event_type?.toLowerCase().includes(resourceFilter.toLowerCase());

      const matchesAction =
        !actionFilter || log.severity?.toLowerCase().includes(actionFilter.toLowerCase());

      const logDate = new Date(log.created_at).getTime();
      const matchesStart = !startDate || logDate >= new Date(startDate).getTime();
      const matchesEnd = !endDate || logDate <= new Date(endDate).getTime();

      return matchesUser && matchesResource && matchesAction && matchesStart && matchesEnd;
    });
  }, [logs, userFilter, resourceFilter, actionFilter, startDate, endDate]);

  const exportData = (format: "json" | "csv") => {
    if (filteredLogs.length === 0) {
      toast.error("Nenhum dado para exportar");
      return;
    }

    let content = "";
    let fileName = `security-audit-logs-${new Date().toISOString()}`;

    if (format === "json") {
      content = JSON.stringify(filteredLogs, null, 2);
      fileName += ".json";
    } else {
      const headers = ["Data", "Evento", "Severidade", "Descrição", "Metadados"];
      const rows = filteredLogs.map((log) => [
        new Date(log.created_at).toLocaleString(),
        log.event_type,
        log.severity,
        log.description,
        JSON.stringify(log.metadata),
      ]);
      content = [headers, ...rows].map((e) => e.join(",")).join("\n");
      fileName += ".csv";
    }

    const blob = new Blob([content], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(url);
    toast.success(`Logs exportados como ${format.toUpperCase()}`);
  };

  const getSeverityBadge = (severity: string) => {
    switch (severity) {
      case "critical":
        return (
          <Badge variant="destructive" className="font-bold uppercase tracking-tighter">
            Crítico
          </Badge>
        );
      case "warning":
        return (
          <Badge
            variant="outline"
            className="border-amber-500 text-amber-600 font-bold uppercase tracking-tighter"
          >
            Aviso
          </Badge>
        );
      default:
        return <Badge variant="secondary">{severity}</Badge>;
    }
  };

  const totalPages = Math.ceil(totalCount / PAGE_SIZE);

  return (
    <div className="p-spacing-md sm:p-spacing-xl space-y-spacing-xl animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-spacing-md">
        <div>
          <h1 className="text-premium-3xl font-black uppercase tracking-tight flex items-center gap-spacing-xs text-primary">
            <Icons.ShieldAlert className="w-spacing-xl h-spacing-xl" />
            Auditoria de Segurança
          </h1>
          <p className="text-muted-foreground font-serif italic">
            Monitoramento de acessos e operações críticas.
          </p>
        </div>
        <div className="flex gap-spacing-xs">
          <Button
            onClick={() => exportData("csv")}
            variant="outline"
            size="sm"
            className="rounded-premium-full gap-spacing-xs"
          >
            <Icons.Download className="w-spacing-sm h-spacing-sm" /> CSV
          </Button>
          <Button
            onClick={() => exportData("json")}
            variant="outline"
            size="sm"
            className="rounded-premium-full gap-spacing-xs"
          >
            <Icons.FileText className="w-spacing-sm h-spacing-sm" /> JSON
          </Button>
          <Button
            onClick={fetchLogs}
            variant="outline"
            size="sm"
            className="rounded-premium-full gap-spacing-xs"
          >
            <Icons.RefreshCw
              className={`w-spacing-sm h-spacing-sm ${loading ? "animate-spin" : ""}`}
            />
            Atualizar
          </Button>
        </div>
      </div>

      <SecurityRescanReportCard />

      <Card className="rounded-[2rem] border-primary/10 shadow-premium overflow-hidden">
        <CardHeader className="bg-muted/30 border-b border-border/40">
          <CardTitle className="text-premium-lg font-black uppercase tracking-widest">
            Filtros Avançados
          </CardTitle>
          <CardDescription>Busca e refinamento temporal</CardDescription>
        </CardHeader>
        <CardContent className="p-spacing-lg">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-spacing-md">
            <div className="space-y-spacing-xs">
              <label className="text-[10px] font-black uppercase tracking-widest opacity-60">
                Usuário
              </label>
              <Input
                placeholder="Nome ou ID"
                value={userFilter}
                onChange={(e) => setUserFilter(e.target.value)}
                className="rounded-premium"
              />
            </div>
            <div className="space-y-spacing-xs">
              <label className="text-[10px] font-black uppercase tracking-widest opacity-60">
                Tipo de Evento
              </label>
              <Input
                placeholder="Ex: invalid_signature"
                value={resourceFilter}
                onChange={(e) => setResourceFilter(e.target.value)}
                className="rounded-premium"
              />
            </div>
            <div className="space-y-spacing-xs">
              <label className="text-[10px] font-black uppercase tracking-widest opacity-60">
                Severidade
              </label>
              <Select value={actionFilter} onValueChange={setActionFilter}>
                <SelectTrigger className="rounded-premium">
                  <SelectValue placeholder="Todas" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todas</SelectItem>
                  <SelectItem value="critical">Crítico</SelectItem>
                  <SelectItem value="warning">Aviso</SelectItem>
                  <SelectItem value="info">Info</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-spacing-xs">
              <label className="text-[10px] font-black uppercase tracking-widest opacity-60">
                Data Início
              </label>
              <Input
                type="datetime-local"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="rounded-premium"
              />
            </div>
            <div className="space-y-spacing-xs">
              <label className="text-[10px] font-black uppercase tracking-widest opacity-60">
                Data Fim
              </label>
              <Input
                type="datetime-local"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="rounded-premium"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      <Card className="rounded-[2rem] border-primary/10 shadow-premium overflow-hidden">
        <CardContent className="p-0">
          <div className="overflow-x-auto">
            <Table>
              <TableHeader className="bg-muted/30">
                <TableRow className="border-border/40">
                  <TableHead className="text-premium-xs font-black uppercase tracking-widest py-spacing-lg px-spacing-lg">
                    Data/Hora
                  </TableHead>
                  <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                    Evento
                  </TableHead>
                  <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                    Severidade
                  </TableHead>
                  <TableHead className="text-premium-xs font-black uppercase tracking-widest">
                    Descrição
                  </TableHead>
                  <TableHead className="text-premium-xs font-black uppercase tracking-widest text-right px-spacing-lg">
                    Detalhes
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  Array(5)
                    .fill(0)
                    .map((_, i) => (
                      <TableRow key={i}>
                        <TableCell colSpan={6} className="p-spacing-lg">
                          <Skeleton className="h-spacing-lg w-full rounded-premium" />
                        </TableCell>
                      </TableRow>
                    ))
                ) : filteredLogs.length > 0 ? (
                  filteredLogs.map((log) => (
                    <TableRow
                      key={log.id}
                      className="hover:bg-muted/10 transition-colors border-border/40"
                    >
                      <TableCell className="px-spacing-lg py-spacing-md font-mono text-[10px]">
                        {new Date(log.created_at).toLocaleString("pt-BR")}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline" className="text-[10px] font-bold uppercase">
                          {log.event_type}
                        </Badge>
                      </TableCell>
                      <TableCell>{getSeverityBadge(log.severity)}</TableCell>
                      <TableCell className="font-medium text-premium-sm max-w-[300px] truncate">
                        {log.description}
                      </TableCell>
                      <TableCell className="text-right px-spacing-lg">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-spacing-xl w-spacing-xl p-0 rounded-premium-full hover:bg-primary/5 text-primary"
                          onClick={() => setSelectedLog(log)}
                        >
                          <Icons.Info className="w-spacing-md h-spacing-md" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell
                      colSpan={6}
                      className="text-center py-spacing-3xl text-muted-foreground font-serif italic"
                    >
                      Nenhum log encontrado para os filtros selecionados.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>

          <div className="p-spacing-lg bg-muted/20 border-t border-border/40 flex items-center justify-between">
            <p className="text-premium-xs text-muted-foreground">
              Mostrando {filteredLogs.length} de {totalCount} registros
            </p>
            <div className="flex gap-spacing-xs">
              <Button
                variant="outline"
                size="sm"
                disabled={currentPage === 0}
                onClick={() => setCurrentPage((p) => p - 1)}
                className="rounded-premium-full"
              >
                Anterior
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={currentPage >= totalPages - 1}
                onClick={() => setCurrentPage((p) => p + 1)}
                className="rounded-premium-full"
              >
                Próximo
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Details Dialog */}
      <Dialog open={!!selectedLog} onOpenChange={() => setSelectedLog(null)}>
        <DialogContent className="max-w-spacing-4xl rounded-[2rem]">
          <DialogHeader>
            <DialogTitle className="text-premium-xl font-black uppercase tracking-tight flex items-center gap-spacing-xs">
              <Icons.ShieldAlert className="text-primary" />
              Detalhes do Evento
