export default function Audit77Dashboard() {
  const [items, setItems] = useState<AuditItem[]>(initialAuditItems);
  const [isOffline, setIsOffline] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isChecking, setIsChecking] = useState(false);

  const checkStatus = async () => {
    setIsChecking(true);
    try {
      const { error } = await supabase
        .from("app_feature_flags")
        .select("count", { count: "exact", head: true });
      if (error && (error.message.includes("paused") || error.code === "PGRST301")) {
        setIsPaused(true);
      } else {
        const wasPaused = isPaused;
        setIsPaused(false);
        if (wasPaused) {
          setItems(initialAuditItems);
        }
      }
    } catch (e) {
      console.error("Audit status check failed", e);
    } finally {
      setIsChecking(false);
    }
  };

  useEffect(() => {
    checkStatus();
  }, []);

  useEffect(() => {
    const handleUnreachable = () => {
      setIsOffline(true);
      setItems((prev) =>
        prev.map((item) => ({
          ...item,
          status: item.status === "PASS" ? "BLOCKED" : item.status,
          deviceStatus: item.deviceStatus
            ? {
                mobile: item.deviceStatus.mobile === "PASS" ? "BLOCKED" : item.deviceStatus.mobile,
                desktop:
                  item.deviceStatus.desktop === "PASS" ? "BLOCKED" : item.deviceStatus.desktop,
              }
            : undefined,
          evidence:
            item.status === "PASS"
              ? {
                  message: "Backend inacessível. Certificação funcional impedida.",
                  timestamp: new Date().toISOString(),
                }
              : item.evidence,
        })),
      );
    };
    window.addEventListener("supabase-unreachable", handleUnreachable);
    return () => window.removeEventListener("supabase-unreachable", handleUnreachable);
  }, []);

  const totalItems = items.length;
  const passItems = items.filter((i) => i.status === "PASS").length;
  const failItems = items.filter((i) => i.status === "FAIL").length;
  const blockedItems = items.filter((i) => i.status === "BLOCKED").length;
  const progress = Math.round((passItems / totalItems) * 100);

  const exportReport = (format: "json" | "pdf") => {
    const report = {
      audit: "7.7",
      timestamp: new Date().toISOString(),
      summary: { totalItems, passItems, failItems, blockedItems, progress },
      performance_metrics: items.map((i) => ({
        module: i.module,
        loadTime: i.loadTime,
        ttfb: i.ttfb,
        lcp: i.lcp,
      })),
      accessibility_results: items.map((i) => ({
        module: i.module,
        accessibility: i.accessibility,
      })),
      items,
    };

    if (format === "json") {
      const blob = new Blob([JSON.stringify(report, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `audit-7-7-full-report-${new Date().getTime()}.json`;
      a.click();
    } else {
      window.print();
    }
  };

  return (
    <div className="mx-auto max-w-4xl px-4 py-8">
      <Helmet>
        <title>Cathedra · AUDIT 7.7 Dashboard</title>
      </Helmet>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="font-serif text-2xl">AUDIT 7.7 — Certificação Funcional Real</h1>
          <p className="text-sm text-muted-foreground">
            Monitoramento de jornadas críticas do peregrino
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={checkStatus} disabled={isChecking}>
            <RefreshCw className={`mr-2 h-4 w-4 ${isChecking ? "animate-spin" : ""}`} /> Sincronizar
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportReport("json")}>
            <Download className="mr-2 h-4 w-4" /> JSON
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportReport("pdf")}>
            <FileText className="mr-2 h-4 w-4" /> PDF / Imprimir
          </Button>
        </div>
      </div>

      {isPaused && (
        <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-lg flex items-center justify-between gap-3 text-amber-800">
          <div className="flex items-center gap-3">
            <ShieldAlert className="h-5 w-5" />
            <div className="text-sm">
              <span className="font-bold">Infraestrutura Pausada:</span> O projeto Supabase precisa
              ser reativado para prosseguir com a certificação real.
            </div>
          </div>
          <Button variant="outline" size="sm" className="bg-white" asChild>
            <a href="/admin/site-health">Ver Health Check</a>
          </Button>
        </div>
      )}

      {isOffline && !isPaused && (
        <div className="mb-6 p-4 bg-amber-50 border border-amber-200 rounded-lg flex items-center gap-3 text-amber-800">
          <WifiOff className="h-5 w-5" />
          <div className="text-sm">
            <span className="font-bold">Backend Indisponível:</span> Falhas de infraestrutura
            detectadas. Status BLOCKED aplicado automaticamente.
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-[10px] text-muted-foreground uppercase tracking-wider">
              Progresso Geral
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-2xl font-serif">{progress}%</p>
            <Progress value={progress} className="h-1.5 mt-2" />
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-[10px] text-muted-foreground uppercase tracking-wider">
              Pass
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-2xl font-serif text-emerald-600">{passItems}</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-[10px] text-muted-foreground uppercase tracking-wider">
              Fail (Corrigir)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-2xl font-serif text-red-600">{failItems}</p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-[10px] text-muted-foreground uppercase tracking-wider">
              Blocked (Infra)
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-2xl font-serif text-amber-600">{blockedItems}</p>
          </CardContent>
        </Card>
      </div>

      <div className="space-y-4">
        {items.map((item) => (
          <Card
            key={item.id}
            className={`border-l-4 ${
              item.status === "PASS"
                ? "border-l-emerald-500"
                : item.status === "FAIL"
                  ? "border-l-red-500"
                  : "border-l-amber-500"
            }`}
          >
            <CardContent className="p-4">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-3">
                    <Badge variant="secondary" className="text-[10px]">
                      {item.p}
                    </Badge>
                    <h2 className="font-serif text-lg">{item.module}</h2>
                    <code className="text-[10px] bg-muted px-1.5 py-0.5 rounded text-muted-foreground">
                      {item.route}
                    </code>
                  </div>

                  <div className="mt-3 flex flex-wrap gap-4 text-[11px] text-muted-foreground">
                    <div className="flex items-center gap-1.5" title="Tempo de carregamento total">
                      <Clock className="h-3.5 w-3.5" />
                      {item.loadTime ? `${item.loadTime}ms` : "—"}
                    </div>
                    <div className="flex items-center gap-1.5" title="TTFB (Time to First Byte)">
                      <Activity className="h-3.5 w-3.5 text-blue-500" />
                      {item.ttfb ? `${item.ttfb}ms` : "—"}
                    </div>
                    <div
                      className="flex items-center gap-1.5"
                      title="LCP (Largest Contentful Paint)"
                    >
                      <Zap className="h-3.5 w-3.5 text-amber-500" />
                      {item.lcp ? `${item.lcp}ms` : "—"}
                    </div>
                    <div className="flex items-center gap-3 border-x px-3">
                      <div className="flex items-center gap-1">
                        <Smartphone className="h-3.5 w-3.5" />
                        <StatusIcon status={item.deviceStatus?.mobile} />
                      </div>
                      <div className="flex items-center gap-1">
                        <Monitor className="h-3.5 w-3.5" />
                        <StatusIcon status={item.deviceStatus?.desktop} />
                      </div>
                    </div>
                    {item.accessibility && (
                      <div className="flex items-center gap-3">
                        <Accessibility className="h-3.5 w-3.5 text-indigo-500" />
                        <div className="flex gap-2">
                          <span
                            className={
                              item.accessibility.contrast === "PASS"
                                ? "text-emerald-600"
                                : "text-red-600"
                            }
                          >
                            Contraste
                          </span>
                          <span
                            className={
                              item.accessibility.keyboard === "PASS"
                                ? "text-emerald-600"
                                : "text-red-600"
                            }
                          >
                            Teclado
                          </span>
                          <span
                            className={
                              item.accessibility.labels === "PASS"
                                ? "text-emerald-600"
                                : "text-red-600"
                            }
                          >
                            Labels
                          </span>
                        </div>
                      </div>
                    )}
                  </div>

                  {item.evidence && (
                    <div className="mt-4 p-3 bg-red-50 border border-red-100 rounded text-[11px] text-red-900">
                      <div className="flex items-start gap-2">
                        <AlertCircle className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                        <div>
                          <p className="font-bold">EVIDÊNCIA DE FALHA:</p>
                          <p className="mt-1">{item.evidence.message}</p>
                          <p className="mt-1 text-[9px] opacity-70 italic">
                            {item.evidence.timestamp}
                          </p>
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-3 shrink-0">
                  <div className="text-right">
                    <Badge
                      variant={
                        item.status === "PASS"
                          ? "secondary"
                          : item.status === "FAIL"
                            ? "destructive"
                            : "outline"
                      }
                      className={
                        item.status === "PASS"
                          ? "bg-emerald-100 text-emerald-700"
                          : item.status === "BLOCKED"
                            ? "bg-amber-100 text-amber-700"
                            : ""
                      }
                    >
                      {item.status}
                    </Badge>
                  </div>
                  {item.status === "PASS" && <CheckCircle2 className="h-6 w-6 text-emerald-500" />}
                  {item.status === "FAIL" && <XCircle className="h-6 w-6 text-red-500" />}
                  {item.status === "BLOCKED" && <ShieldAlert className="h-6 w-6 text-amber-500" />}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

function StatusIcon({ status }: { status?: "PASS" | "FAIL" | "BLOCKED" }) {
  if (!status) return <span>—</span>;
  if (status === "PASS") return <CheckCircle2 className="h-3 w-3 text-emerald-500" />;
  if (status === "FAIL") return <XCircle className="h-3 w-3 text-red-500" />;
  return <ShieldAlert className="h-3 w-3 text-amber-500" />;
}

/**
 * Admin — Trilha de Auditoria (`/admin/audit-logs`).
 *
 * Consolida três fontes já existentes e protegidas por RLS admin-only:
 *  - `governance_audit_log`  → mudanças editoriais/governança (inclui operações
 *    executadas por funções SECURITY DEFINER, via `actor_role`).
 *  - `security_audit_logs`   → eventos de segurança (grants, hardening, scans).
 *  - `rls_denial_events`     → tentativas de acesso negadas por RLS.
 *
 * Somente leitura: filtros, paginação server-side e exportação CSV do
 * conjunto filtrado (até 5.000 linhas).
 */
import React, { useMemo, useState } from "react";
import { Helmet } from "@/lib/helmet-compat";
import { useQuery } from "@tanstack/react-query";
import { Link } from "@/lib/rr-compat";
import {
  Download,
  ChevronLeft,
  ChevronRight,
  ShieldAlert,
  ScrollText,
  Lock,
  ExternalLink,
} from "lucide-react";
import { supabase } from "@/lib/db";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toast } from "sonner";

type Source = "governance" | "security" | "denials";

interface SourceConfig {
  table: "governance_audit_log" | "security_audit_logs" | "rls_denial_events";
  dateColumn: string;
  columns: string;
  /** Colunas exibidas na tabela (ordem importa). */
  fields: Array<{ key: string; label: string }>;
  /** Colunas usadas pela busca textual (ilike). */
  searchable: string[];
  /** Filtro categórico opcional. */
  facet?: { column: string; label: string; options: string[] };
  /** Coluna do usuário responsável, quando existir (filtro por autor). */
  actorColumn?: string;
  icon: React.ElementType;
  label: string;
  hint: string;
}

const SOURCES: Record<Source, SourceConfig> = {
  governance: {
    table: "governance_audit_log",
    dateColumn: "occurred_at",
    columns:
      "id, occurred_at, actor_id, actor_role, entity_type, entity_id, operation, correlation_id",
    fields: [
      { key: "occurred_at", label: "Data" },
      { key: "operation", label: "Operação" },
      { key: "entity_type", label: "Entidade" },
      { key: "entity_id", label: "ID" },
      { key: "actor_role", label: "Papel" },
      { key: "actor_id", label: "Autor" },
      { key: "correlation_id", label: "Correlação" },
    ],
    searchable: ["entity_type", "operation", "correlation_id"],
    facet: {
      column: "actor_role",
      label: "Papel do executor",
      options: ["authenticated", "service_role", "system", "anon"],
    },
    actorColumn: "actor_id",

    icon: ScrollText,
    label: "Governança",
    hint: "Alterações registradas por gatilhos e funções SECURITY DEFINER (actor_role = system/service_role).",
  },
  security: {
    table: "security_audit_logs",
    dateColumn: "created_at",
    columns: "id, created_at, event_type, severity, description",
    fields: [
      { key: "created_at", label: "Data" },
      { key: "severity", label: "Severidade" },
      { key: "event_type", label: "Evento" },
      { key: "description", label: "Descrição" },
    ],
    searchable: ["event_type", "description"],
    facet: {
      column: "severity",
      label: "Severidade",
      options: ["info", "warning", "error", "critical"],
    },
    icon: ShieldAlert,
    label: "Segurança e grants",
    hint: "Eventos de segurança: revogação/concessão de grants, scans e hardening de policies.",
  },
  denials: {
    table: "rls_denial_events",
    dateColumn: "created_at",
    columns: "id, created_at, user_id, table_name, action, reason",
    fields: [
      { key: "created_at", label: "Data" },
      { key: "table_name", label: "Tabela" },
      { key: "action", label: "Ação" },
      { key: "reason", label: "Motivo" },
      { key: "user_id", label: "Usuário" },
    ],
    searchable: ["table_name", "action", "reason"],
    facet: { column: "action", label: "Ação", options: ["select", "insert", "update", "delete"] },
    actorColumn: "user_id",

    icon: Lock,
    label: "Negações RLS",
    hint: "Tentativas de leitura/escrita bloqueadas por Row Level Security.",
  },
};

const PAGE_SIZE = 25;
const CSV_LIMIT = 5000;
const PERIODS = [
  { value: "1", label: "Últimas 24h" },
  { value: "7", label: "7 dias" },
  { value: "30", label: "30 dias" },
  { value: "90", label: "90 dias" },
  { value: "0", label: "Todo o período" },
];

const sinceIso = (days: number) => new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString();

type Row = Record<string, unknown>;

interface Filters {
  days: number;
  facet: string;
  search: string;
  /** UUID (ou prefixo) do usuário responsável pelo evento. */
  actor: string;
}

/** Severidade normalizada para leitura rápida da trilha. */
type Severity = "info" | "warning" | "critical";

const SEVERITY_LABEL: Record<Severity, string> = {
  info: "Info",
  warning: "Atenção",
  critical: "Crítico",
};

const SEVERITY_CLASS: Record<Severity, string> = {
  info: "border-border bg-muted text-muted-foreground",
  warning: "border-amber-500/40 bg-amber-500/10 text-amber-700 dark:text-amber-300",
  critical: "border-destructive/40 bg-destructive/10 text-destructive",
};

function severityOf(source: Source, row: Row): Severity {
  if (source === "security") {
    const raw = String(row.severity ?? "").toLowerCase();
    if (raw === "critical" || raw === "error") return "critical";
    if (raw === "warning" || raw === "warn") return "warning";
    return "info";
  }
  if (source === "denials") {
    const action = String(row.action ?? "").toLowerCase();
    return action === "select" ? "warning" : "critical";
  }
  const op = String(row.operation ?? "").toLowerCase();
  if (op.includes("delete") || op.includes("revoke")) return "critical";
  if (op.includes("update") || op.includes("publish") || op.includes("grant")) return "warning";
  return "info";
}

/**
 * Rota administrativa do recurso relacionado ao evento — atalho para
 * investigar a entidade sem sair da trilha.
 */
const ENTITY_ROUTES: Record<string, (id: string) => string> = {
  nexus_relation: () => "/admin/nexus-audit",
  translation_source: () => "/admin/bible-sources",
  editorial_closure_migration: () => "/admin/editorial-closure-validator",
  glossary: () => "/admin/glossario",
  glossary_term: () => "/admin/glossario",
  saint: () => "/admin/saints",
  saints: () => "/admin/saints",
  prayer: () => "/admin/oracoes",
  catechism: () => "/admin/catechism-queue",
  catechism_official: () => "/admin/catechism-queue",
  collection: (id) => (id ? `/admin/collections/${id}` : "/admin/collections"),
  collections: (id) => (id ? `/admin/collections/${id}` : "/admin/collections"),
  saint_works: () => "/admin/biblioteca-patristica",
};

const TABLE_ROUTES: Record<string, string> = {
  glossary: "/admin/glossario",
  catechism_official: "/admin/catechism-queue",
  saints: "/admin/saints",
  collections: "/admin/collections",
  secret_leaks: "/admin/security-audit",
  community_likes: "/admin/site-health",
};

function relatedHref(source: Source, row: Row): string | null {
  if (source === "governance") {
    const type = String(row.entity_type ?? "");
    const build = ENTITY_ROUTES[type];
    return build ? build(String(row.entity_id ?? "")) : null;
  }
  if (source === "denials") {
    return TABLE_ROUTES[String(row.table_name ?? "")] ?? null;
  }
  return null;
}

function buildQuery(source: Source, filters: Filters) {
  const cfg = SOURCES[source];
  // Tabelas resolvidas dinamicamente: os tipos gerados explodem em união
  // profunda demais para o TS, então o builder é tratado de forma opaca.
  const client = supabase as unknown as {
    from: (table: string) => {
      select: (cols: string, opts: { count: "exact" }) => any;
    };
  };
  let query = client.from(cfg.table).select(cfg.columns, { count: "exact" });
  if (filters.days > 0) query = query.gte(cfg.dateColumn, sinceIso(filters.days));
  if (filters.facet !== "all" && cfg.facet) query = query.eq(cfg.facet.column, filters.facet);
  const actor = filters.actor.trim();
  if (actor && cfg.actorColumn) {
    const safeActor = actor.replace(/[,()*%]/g, "");
    if (safeActor) query = query.ilike(`${cfg.actorColumn}::text`, `%${safeActor}%`);
  }
  const term = filters.search.trim();
  if (term) {
    const safe = term.replace(/[,()*]/g, " ").trim();
    if (safe) query = query.or(cfg.searchable.map((c) => `${c}.ilike.%${safe}%`).join(","));
  }
  return query.order(cfg.dateColumn, { ascending: false }) as {
    range: (
      from: number,
      to: number,
    ) => Promise<{ data: Row[] | null; count: number | null; error: { message: string } | null }>;
  };
}

function formatCell(key: string, value: unknown): string {
  if (value === null || value === undefined || value === "") return "—";
  if (key.endsWith("_at")) return new Date(String(value)).toLocaleString("pt-BR");
  const text = typeof value === "object" ? JSON.stringify(value) : String(value);
  return text;
}

function toCsv(fields: Array<{ key: string; label: string }>, rows: Row[]): string {
  const escape = (v: unknown) => {
    const s =
      v === null || v === undefined ? "" : typeof v === "object" ? JSON.stringify(v) : String(v);
    return `"${s.replace(/"/g, '""')}"`;
  };
  const head = fields.map((f) => escape(f.label)).join(",");
  const body = rows.map((r) => fields.map((f) => escape(r[f.key])).join(",")).join("\n");
  return `${head}\n${body}`;
}

const AuditTable: React.FC<{ source: Source }> = ({ source }) => {
  const cfg = SOURCES[source];
  // A severidade vira badge dedicado; a coluna crua sai da tabela (segue no CSV).
  const visibleFields = cfg.fields.filter((f) => f.key !== "severity");
  const colCount = visibleFields.length + 2;
  const [days, setDays] = useState(30);
  const [facet, setFacet] = useState("all");
  const [searchInput, setSearchInput] = useState("");
  const [search, setSearch] = useState("");
  const [actorInput, setActorInput] = useState("");
  const [actor, setActor] = useState("");
  const [page, setPage] = useState(0);
  const [exporting, setExporting] = useState(false);

  const filters: Filters = useMemo(
    () => ({ days, facet, search, actor }),
    [days, facet, search, actor],
  );

  const { data, isLoading, isError } = useQuery({
    queryKey: ["admin-audit-logs", source, filters, page],
    staleTime: 30_000,
    queryFn: async () => {
      const from = page * PAGE_SIZE;
      const {
        data: rows,
        count,
        error,
      } = await buildQuery(source, filters).range(from, from + PAGE_SIZE - 1);
      if (error) throw error;
      return { rows: (rows ?? []) as unknown as Row[], count: count ?? 0 };
    },
  });

  const total = data?.count ?? 0;
  const maxPage = Math.max(0, Math.ceil(total / PAGE_SIZE) - 1);

  const applySearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(0);
    setSearch(searchInput);
    setActor(actorInput);
  };

  const handleExport = async () => {
    setExporting(true);
    try {
      const { data: rows, error } = await buildQuery(source, filters).range(0, CSV_LIMIT - 1);
      if (error) throw error;
      const csv = toCsv(cfg.fields, (rows ?? []) as unknown as Row[]);
      const blob = new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${cfg.table}-${new Date().toISOString().slice(0, 10)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success(`${rows?.length ?? 0} registro(s) exportado(s).`);
    } catch (err) {
      toast.error("Falha ao exportar CSV.", {
        description: String((err as Error)?.message ?? err),
      });
    } finally {
      setExporting(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <cfg.icon aria-hidden="true" className="h-4 w-4 text-primary" />
          {cfg.label}
        </CardTitle>
        <p className="text-sm text-muted-foreground">{cfg.hint}</p>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-col gap-3 md:flex-row md:items-end">
          <form onSubmit={applySearch} className="flex flex-1 flex-col gap-2 sm:flex-row">
            <div className="flex-1">
              <label
                htmlFor={`search-${source}`}
                className="mb-1 block text-xs font-semibold uppercase tracking-wider text-muted-foreground"
              >
                Buscar
              </label>
              <Input
                id={`search-${source}`}
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                placeholder={cfg.searchable.join(", ")}
              />
            </div>
            {cfg.actorColumn && (
              <div className="sm:w-56">
                <label
                  htmlFor={`actor-${source}`}
                  className="mb-1 block text-xs font-semibold uppercase tracking-wider text-muted-foreground"
                >
                  Usuário responsável
                </label>
                <Input
                  id={`actor-${source}`}
                  value={actorInput}
                  onChange={(e) => setActorInput(e.target.value)}
                  placeholder="ID do usuário"
                />
              </div>
            )}
            <Button type="submit" variant="secondary" className="self-end">
              Filtrar
            </Button>
          </form>

          <div className="w-full md:w-44">
            <span className="mb-1 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              Período
            </span>
            <Select
              value={String(days)}
              onValueChange={(v) => {
                setPage(0);
                setDays(Number(v));
              }}
            >
              <SelectTrigger aria-label="Período">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {PERIODS.map((p) => (
                  <SelectItem key={p.value} value={p.value}>
                    {p.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {cfg.facet && (
            <div className="w-full md:w-52">
              <span className="mb-1 block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                {cfg.facet.label}
              </span>
              <Select
                value={facet}
                onValueChange={(v) => {
                  setPage(0);
                  setFacet(v);
                }}
              >
                <SelectTrigger aria-label={cfg.facet.label}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  {cfg.facet.options.map((o) => (
                    <SelectItem key={o} value={o}>
                      {o}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <Button
            onClick={handleExport}
            disabled={exporting || total === 0}
            className="self-end gap-2"
          >
            <Download aria-hidden="true" className="h-4 w-4" />
            {exporting ? "Exportando…" : "CSV"}
          </Button>
        </div>

        <div className="overflow-x-auto rounded-lg border border-border">
          <table className="w-full min-w-[720px] text-sm">
            <caption className="sr-only">{cfg.label} — registros de auditoria</caption>
            <thead className="bg-muted/50">
              <tr>
                <th
                  scope="col"
                  className="px-3 py-2 text-left text-xs font-bold uppercase tracking-wider text-muted-foreground"
                >
                  Severidade
                </th>
                {visibleFields.map((f) => (
                  <th
                    key={f.key}
                    scope="col"
                    className="px-3 py-2 text-left text-xs font-bold uppercase tracking-wider text-muted-foreground"
                  >
                    {f.label}
                  </th>
                ))}
                <th
                  scope="col"
                  className="px-3 py-2 text-left text-xs font-bold uppercase tracking-wider text-muted-foreground"
                >
                  Recurso
                </th>
              </tr>
            </thead>
            <tbody>
              {isLoading && (
                <tr>
                  <td colSpan={colCount} className="px-3 py-6 text-center text-muted-foreground">
                    Carregando…
                  </td>
                </tr>
              )}
              {isError && (
                <tr>
                  <td colSpan={colCount} className="px-3 py-6 text-center text-destructive">
                    Falha ao carregar registros.
                  </td>
                </tr>
              )}
              {!isLoading && !isError && (data?.rows.length ?? 0) === 0 && (
                <tr>
                  <td colSpan={colCount} className="px-3 py-6 text-center text-muted-foreground">
                    Nenhum registro no filtro atual.
                  </td>
                </tr>
              )}
              {data?.rows.map((row, i) => {
                const severity = severityOf(source, row);
                const href = relatedHref(source, row);
                return (
                  <tr key={String(row.id ?? i)} className="border-t border-border align-top">
                    <td className="px-3 py-2">
                      <span
                        className={`inline-flex rounded-full border px-2 py-0.5 text-xs font-semibold ${SEVERITY_CLASS[severity]}`}
                      >
                        {SEVERITY_LABEL[severity]}
                      </span>
                    </td>
                    {visibleFields.map((f) => (
                      <td
                        key={f.key}
                        className="max-w-[280px] truncate px-3 py-2"
                        title={formatCell(f.key, row[f.key])}
                      >
                        {formatCell(f.key, row[f.key])}
                      </td>
                    ))}
                    <td className="px-3 py-2">
                      {href ? (
                        <Link
                          to={href}
                          className="inline-flex items-center gap-1 text-xs font-semibold text-primary hover:underline"
                        >
                          <ExternalLink aria-hidden="true" className="h-3.5 w-3.5" />
                          Abrir recurso
                        </Link>
                      ) : (
                        <span className="text-xs text-muted-foreground">—</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="flex items-center justify-between text-sm text-muted-foreground">
          <span aria-live="polite">
            {total} registro(s) · página {Math.min(page + 1, maxPage + 1)} de {maxPage + 1}
          </span>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              disabled={page === 0}
              onClick={() => setPage((p) => Math.max(0, p - 1))}
            >
              <ChevronLeft aria-hidden="true" className="h-4 w-4" /> Anterior
            </Button>
            <Button
              variant="outline"
              size="sm"
              disabled={page >= maxPage}
              onClick={() => setPage((p) => p + 1)}
            >
              Próxima <ChevronRight aria-hidden="true" className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

