interface Job {
  id: string;
  status: string;
  progress: number;
  total: number;
  current_book: string | null;
  message: string | null;
  error: string | null;
  started_at: string | null;
  finished_at: string | null;
  created_at: string;
  verification: any;
  audit_log?: any;
  source_code?: string | null;
  translation?: string | null;
}

type Period = "all" | "24h" | "7d" | "30d";
const PERIOD_MS: Record<Period, number | null> = {
  all: null,
  "24h": 24 * 3600_000,
  "7d": 7 * 86400_000,
  "30d": 30 * 86400_000,
};

const STATUS_VARIANT: Record<string, "default" | "destructive" | "secondary" | "outline"> = {
  succeeded: "default",
  running: "secondary",
  queued: "outline",
  failed: "destructive",
  cancelled: "outline",
};

function formatDuration(startISO: string | null, endISO: string | null): string {
  if (!startISO) return "—";
  const start = new Date(startISO).getTime();
  const end = endISO ? new Date(endISO).getTime() : Date.now();
  const ms = Math.max(0, end - start);
  const s = Math.round(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  const rs = s % 60;
  return rs === 0 ? `${m}min` : `${m}min ${rs}s`;
}

function versesFromAudit(audit: any): number {
  if (!Array.isArray(audit)) return 0;
  return audit.reduce(
    (sum: number, e: any) => sum + (typeof e?.verses === "number" ? e.verses : 0),
    0,
  );
}

function revalidationLabel(v: any): {
  label: string;
  variant: "default" | "secondary" | "destructive" | "outline";
} {
  if (!v) return { label: "—", variant: "outline" };
  const retry = v?.revalidation_retry;
  if (retry?.pending) return { label: "imediata · retry pendente", variant: "secondary" };
  if (retry?.ran) return { label: "imediata + 3min", variant: "default" };
  if (v?.ran) return { label: "imediata", variant: "default" };
  return { label: "—", variant: "outline" };
}

async function invoke(action: string, body: Record<string, unknown> = {}) {
  const { data, error } = await supabase.functions.invoke("bible-import-missing", {
    body: { action, ...body },
  });
  if (error) throw new Error(error.message);
  return data;
}

export default function BibleImportJobs() {
  const q = useQuery({
    queryKey: ["bible-import-jobs"],
    queryFn: async (): Promise<Job[]> => (await invoke("list_jobs", { limit: 200 }))?.jobs ?? [],
    refetchInterval: 5000,
  });

  const [status, setStatus] = useState<string>("all");
  const [source, setSource] = useState<string>("all");
  const [period, setPeriod] = useState<Period>("all");
  const [search, setSearch] = useState<string>("");

  const all = q.data ?? [];

  const sources = useMemo(() => {
    const set = new Set<string>();
    for (const j of all) if (j.translation) set.add(j.translation);
    return Array.from(set).sort();
  }, [all]);

  const counts = useMemo(() => {
    const c: Record<string, number> = { all: all.length };
    for (const j of all) c[j.status] = (c[j.status] ?? 0) + 1;
    return c;
  }, [all]);

  const filtered = useMemo(() => {
    const cutoff = PERIOD_MS[period] ? Date.now() - (PERIOD_MS[period] as number) : null;
    const term = search.trim().toLowerCase();
    return all.filter((j) => {
      if (status !== "all" && j.status !== status) return false;
      if (source !== "all" && j.translation !== source) return false;
      if (cutoff && new Date(j.created_at).getTime() < cutoff) return false;
      if (term) {
        const hay =
          `${j.id} ${j.message ?? ""} ${j.error ?? ""} ${j.current_book ?? ""} ${j.translation ?? ""}`.toLowerCase();
        if (!hay.includes(term)) return false;
      }
      return true;
    });
  }, [all, status, source, period, search]);

  const hasFilter =
    status !== "all" || source !== "all" || period !== "all" || search.trim() !== "";

  return (
    <div className="container mx-auto max-w-6xl py-8 space-y-6">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-serif">Histórico de importações</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Últimos 200 jobs de <code>bible-import-missing</code>.
          </p>
        </div>
        <Link to="/admin/bible-import-missing" className="text-sm text-primary hover:underline">
          ← Nova importação
        </Link>
      </header>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Filtros</CardTitle>
          <CardDescription>
            Total: <strong>{counts.all ?? 0}</strong> ·{" "}
            {["succeeded", "running", "queued", "failed", "cancelled"].map((s) => (
              <span key={s} className="mr-2">
                {s}: <strong>{counts[s] ?? 0}</strong>
              </span>
            ))}
          </CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-4 gap-3">
          <div>
            <Label htmlFor="f-status" className="text-xs">
              Status
            </Label>
            <Select value={status} onValueChange={setStatus}>
              <SelectTrigger id="f-status">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos ({counts.all ?? 0})</SelectItem>
                <SelectItem value="succeeded">succeeded ({counts.succeeded ?? 0})</SelectItem>
                <SelectItem value="running">running ({counts.running ?? 0})</SelectItem>
                <SelectItem value="queued">queued ({counts.queued ?? 0})</SelectItem>
                <SelectItem value="failed">failed ({counts.failed ?? 0})</SelectItem>
                <SelectItem value="cancelled">cancelled ({counts.cancelled ?? 0})</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="f-source" className="text-xs">
              Fonte (tradução)
            </Label>
            <Select value={source} onValueChange={setSource}>
              <SelectTrigger id="f-source">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todas</SelectItem>
                {sources.map((s) => (
                  <SelectItem key={s} value={s}>
                    {s}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="f-period" className="text-xs">
              Período
            </Label>
            <Select value={period} onValueChange={(v) => setPeriod(v as Period)}>
              <SelectTrigger id="f-period">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos</SelectItem>
                <SelectItem value="24h">Últimas 24h</SelectItem>
                <SelectItem value="7d">Últimos 7 dias</SelectItem>
                <SelectItem value="30d">Últimos 30 dias</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label htmlFor="f-search" className="text-xs">
              Busca (id, mensagem, livro)
            </Label>
            <div className="relative">
              <Input
                id="f-search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="ex.: Gn, err, retry…"
              />
              {search && (
                <button
                  type="button"
                  onClick={() => setSearch("")}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                >
                  <X className="w-3 h-3" />
                </button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">
            Jobs{" "}
            {hasFilter && (
              <span className="text-sm text-muted-foreground font-normal">
                — {filtered.length} de {all.length}
              </span>
            )}
          </CardTitle>
          <CardDescription>Atualiza a cada 5s.</CardDescription>
        </CardHeader>
        <CardContent>
          {q.isLoading ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="w-4 h-4 animate-spin" /> Carregando…
            </div>
          ) : filtered.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              {hasFilter ? "Nenhum job corresponde aos filtros." : "Nenhum job executado ainda."}
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Job</TableHead>
                  <TableHead>Fonte</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Progresso</TableHead>
                  <TableHead>Duração</TableHead>
                  <TableHead>Versos</TableHead>
                  <TableHead>Revalidação</TableHead>
                  <TableHead>Início</TableHead>
                  <TableHead>Mensagem</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filtered.map((j) => {
                  const reval = revalidationLabel(j.verification);
                  return (
                    <TableRow key={j.id}>
                      <TableCell>
                        <Link
                          to={`/admin/bible-import-jobs/${j.id}`}
                          className="font-mono text-xs text-primary hover:underline"
                        >
                          {j.id.slice(0, 8)}
                        </Link>
                      </TableCell>
                      <TableCell className="text-xs">{j.translation ?? "—"}</TableCell>
                      <TableCell>
                        <Badge variant={STATUS_VARIANT[j.status] ?? "outline"}>{j.status}</Badge>
                      </TableCell>
                      <TableCell className="text-xs">
                        {j.progress}/{j.total}
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">
                        {formatDuration(j.started_at, j.finished_at)}
                      </TableCell>
                      <TableCell className="text-xs">
                        {versesFromAudit(j.audit_log).toLocaleString("pt-BR")}
                      </TableCell>
                      <TableCell>
                        <Badge variant={reval.variant} className="text-[10px]">
                          {reval.label}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground">
                        {j.started_at ? new Date(j.started_at).toLocaleString("pt-BR") : "—"}
                      </TableCell>
                      <TableCell className="text-xs max-w-md truncate">
                        {j.error ? (
                          <span className="text-destructive">{j.error}</span>
                        ) : (
                          (j.message ?? "—")
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * /admin/bible-import-missing — importa os 64 livros faltantes via bolls.life
 * e revalida o gate automaticamente ao final.
 */
import { useEffect, useState } from "react";
import { Link } from "@/lib/rr-compat";
import { supabase } from "@/lib/db";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/cathedra/CathedraCard";
import { CathedraButton as Button } from "@/components/cathedra/CathedraButton";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Loader2,
  PlayCircle,
  Search,
  CheckCircle2,
  AlertTriangle,
  ShieldCheck,
  FlaskConical,
  History,
  ChevronDown,
  ChevronRight,
} from "lucide-react";
import { toast } from "sonner";

interface PreviewDetail {
  abbrev: string;
  name: string;
  chapters: number;
  chapter_numbers?: number[];
}
interface Preview {
  translation: string;
  books_missing: number;
  chapters_missing: number;
  detail: PreviewDetail[];
}
interface Job {
  id: string;
  status: string;
  progress: number;
  total: number;
  current_book: string | null;
  message: string | null;
  error: string | null;
  verification: any;
  audit_log: any;
  started_at: string | null;
  finished_at: string | null;
}
interface Validation {
  ok: boolean;
  translation: string;
  reachable: boolean;
  bolls_books_total?: number;
  expected_books?: number;
  covered_books?: number;
  issues: Array<{ level: "error" | "warning"; code: string; message: string }>;
}
interface DryRun {
  dry_run: true;
  translation: string;
  books_missing: number;
  chapters_missing_total: number;
  samples: Array<{
    abbrev: string;
    name: string;
    chapters_missing: number;
    chapter_numbers?: number[];
    sample_chapter: number;
    sample_verses: number;
    first_verse: string | null;
    error?: string;
  }>;
}

async function invoke(action: string, body: Record<string, unknown> = {}) {
  const { data, error } = await supabase.functions.invoke("bible-import-missing", {
    body: { action, ...body },
  });
  if (error) {
    // supabase-js embute o body em `context` quando o status >= 400
    let detail = "";
    try {
      const ctx = (error as any).context;
      if (ctx?.body)
        detail = ` — ${typeof ctx.body === "string" ? ctx.body : JSON.stringify(ctx.body)}`;
    } catch {
      /* noop */
    }
    throw new Error(`${error.message}${detail}`);
  }
  return data;
}

export default function BibleImportMissing() {
  const [translation, setTranslation] = useState("NVIPT");
  const [preview, setPreview] = useState<Preview | null>(null);
  const [validation, setValidation] = useState<Validation | null>(null);
  const [dryRun, setDryRun] = useState<DryRun | null>(null);
  const [loadingPreview, setLoadingPreview] = useState(false);
  const [loadingValidation, setLoadingValidation] = useState(false);
  const [loadingDryRun, setLoadingDryRun] = useState(false);
  const [job, setJob] = useState<Job | null>(null);
  const [starting, setStarting] = useState(false);

  // Seleção manual: Map<abbrev, Set<chapter>|null>. null = livro inteiro.
  const [selection, setSelection] = useState<Map<string, Set<number> | null>>(new Map());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [useSelection, setUseSelection] = useState(false);

  function buildSelectionPayload(): Array<{ abbrev: string; chapters?: number[] }> | undefined {
    if (!useSelection || selection.size === 0) return undefined;
    return Array.from(selection.entries()).map(([abbrev, chapters]) => ({
      abbrev,
      chapters: chapters ? Array.from(chapters).sort((a, b) => a - b) : undefined,
    }));
  }

  function toggleBook(abbrev: string, all: number[]) {
    setSelection((prev) => {
      const next = new Map(prev);
      if (next.has(abbrev)) next.delete(abbrev);
      else next.set(abbrev, null); // livro inteiro por padrão
      return next;
    });
  }

  function toggleChapter(abbrev: string, chapter: number, all: number[]) {
    setSelection((prev) => {
      const next = new Map(prev);
      const cur = next.get(abbrev);
      const set = new Set<number>(cur ? Array.from(cur) : all); // null vira "todos"
      if (set.has(chapter)) set.delete(chapter);
      else set.add(chapter);
      if (set.size === 0) next.delete(abbrev);
      else if (set.size === all.length) next.set(abbrev, null);
      else next.set(abbrev, set);
      return next;
    });
  }

  function toggleExpand(abbrev: string) {
    setExpanded((prev) => {
      const next = new Set(prev);
      next.has(abbrev) ? next.delete(abbrev) : next.add(abbrev);
      return next;
    });
  }

  async function runValidation() {
    setLoadingValidation(true);
    setValidation(null);
    try {
      setValidation(await invoke("validate", { translation }));
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setLoadingValidation(false);
    }
  }

  async function runDryRun() {
    setLoadingDryRun(true);
    setDryRun(null);
    try {
      const sel = buildSelectionPayload();
      setDryRun(await invoke("dry_run", { translation, selection: sel }));
      toast.success(
        sel
          ? `Dry-run da seleção (${sel.length} livros) — nada gravado.`
          : "Dry-run concluído — nada foi gravado.",
      );
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setLoadingDryRun(false);
    }
  }

  async function loadPreview() {
    setLoadingPreview(true);
    try {
      const res = await invoke("preview", { translation });
      setPreview(res);
    } catch (e: any) {
      toast.error(e.message);
    } finally {
      setLoadingPreview(false);
    }
  }

  async function start() {
    setStarting(true);
    try {
      const sel = buildSelectionPayload();
      const res = await invoke("start", { translation, selection: sel });
      if (!res?.job_id) throw new Error("Job não iniciado");
      toast.success(
        sel ? `Importação da seleção iniciada (${sel.length} livros)` : "Importação iniciada",
      );
      pollJob(res.job_id);
    } catch (e: any) {
      toast.error(e.message);
      setStarting(false);
    }
  }

  function pollJob(jobId: string) {
    let stop = false;
    (async function loop() {
      while (!stop) {
        try {
          const { job: j } = await invoke("status", { job_id: jobId });
          setJob(j);
          if (["succeeded", "failed", "cancelled"].includes(j.status)) {
            setStarting(false);
            if (j.status === "succeeded") {
              toast.success("Import concluído e gate revalidado");
              loadPreview();
            } else {
              toast.error(`Import ${j.status}: ${j.error ?? ""}`);
            }
            return;
          }
        } catch (e: any) {
          /* continua tentando */
        }
        await new Promise((r) => setTimeout(r, 2000));
      }
    })();
    return () => {
      stop = true;
    };
  }

  useEffect(() => {
    loadPreview(); /* eslint-disable-next-line */
  }, []);

  const pct =
    job && job.total > 0 ? Math.min(100, Math.round((job.progress / job.total) * 100)) : 0;
  const gateBlocked = job?.verification?.gate?.blocked ?? job?.verification?.gate?.[0]?.blocked;

  return (
    <div className="container mx-auto max-w-5xl py-8 space-y-6">
      <header className="flex items-start justify-between gap-3 flex-wrap">
        <div>
          <h1 className="text-2xl font-serif">Importar livros faltantes da Bíblia</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Preenche o cânon a partir da API pública bolls.life. Livros deuterocanônicos (Tb, Jdt,
            Sb, Eclo, Br, 1Mc, 2Mc) e cânones católicos estendidos (Sl 151, Dn 13-14) NÃO são
            tocados — mantidos pelo import-deutero.
          </p>
        </div>
        <Link
          to="/admin/bible-import-jobs"
          className="inline-flex items-center gap-2 text-sm text-primary hover:underline"
        >
          <History className="w-4 h-4" /> Histórico de jobs
        </Link>
      </header>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Fonte</CardTitle>
          <CardDescription>
            Código da tradução no bolls.life (ex.: NVIPT, NAA, ARA). Valide antes de importar.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-wrap items-end gap-2">
          <div className="flex-1 min-w-[180px] max-w-xs">
            <Label htmlFor="tr">Tradução</Label>
            <Input
              id="tr"
              value={translation}
              onChange={(e) => setTranslation(e.target.value.toUpperCase())}
            />
          </div>
          <Button variant="outline" onClick={runValidation} disabled={loadingValidation}>
            {loadingValidation ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <ShieldCheck className="w-4 h-4 mr-2" />
            )}
            Validar fonte
          </Button>
          <Button variant="outline" onClick={runDryRun} disabled={loadingDryRun}>
            {loadingDryRun ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <FlaskConical className="w-4 h-4 mr-2" />
            )}
            Dry-run (não grava)
          </Button>
          <Button variant="outline" onClick={loadPreview} disabled={loadingPreview}>
            {loadingPreview ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Search className="w-4 h-4 mr-2" />
            )}
            Recalcular pendências
          </Button>
        </CardContent>
      </Card>

      {validation && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              Validação da fonte
              <Badge variant={validation.ok ? "default" : "destructive"}>
                {validation.ok ? "ok" : "falhou"}
              </Badge>
            </CardTitle>
            <CardDescription>
              {validation.reachable
                ? `${validation.covered_books}/${validation.expected_books} livros protocanônicos cobertos · ${validation.bolls_books_total} livros totais no bolls`
                : "Fonte inacessível"}
            </CardDescription>
          </CardHeader>
          <CardContent>
            {validation.issues.length === 0 ? (
              <p className="text-sm text-green-700 flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4" /> Sem problemas.
              </p>
            ) : (
              <ul className="space-y-1 text-sm">
                {validation.issues.map((i, idx) => (
                  <li key={idx} className="flex items-start gap-2">
                    <Badge
                      variant={i.level === "error" ? "destructive" : "secondary"}
                      className="text-[10px]"
                    >
                      {i.level}
                    </Badge>
                    <span className="text-muted-foreground text-xs font-mono">{i.code}</span>
                    <span>{i.message}</span>
                  </li>
                ))}
              </ul>
            )}
          </CardContent>
        </Card>
      )}

      {dryRun && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              Dry-run · {dryRun.translation}
              <Badge variant="outline">simulação</Badge>
            </CardTitle>
            <CardDescription>
              Nenhuma escrita foi feita. Confira o plano antes de confirmar a importação.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
              <div className="border rounded p-3">
                <div className="text-muted-foreground text-xs">Livros</div>
                <div className="text-xl font-semibold">{dryRun.books_missing}</div>
              </div>
              <div className="border rounded p-3">
                <div className="text-muted-foreground text-xs">Capítulos</div>
                <div className="text-xl font-semibold">{dryRun.chapters_missing_total}</div>
              </div>
              <div className="border rounded p-3">
                <div className="text-muted-foreground text-xs">Amostras OK</div>
                <div className="text-xl font-semibold">
                  {dryRun.samples.filter((s) => !s.error).length}
                </div>
              </div>
              <div className="border rounded p-3">
                <div className="text-muted-foreground text-xs">Amostras com erro</div>
                <div
                  className={`text-xl font-semibold ${dryRun.samples.some((s) => s.error) ? "text-destructive" : ""}`}
                >
                  {dryRun.samples.filter((s) => s.error).length}
                </div>
              </div>
            </div>

            <div className="max-h-96 overflow-auto text-xs space-y-2">
