                {preview.books_missing} livros / {preview.chapters_missing} capítulos
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {preview.books_missing === 0 ? (
              <p className="text-sm flex items-center gap-2 text-green-700">
