              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div>
                  <Label>Objetivos da trilha (um por linha)</Label>
                  <Textarea
                    rows={5}
                    value={form.learning_objectives}
                    onChange={(e) => setForm({ ...form, learning_objectives: e.target.value })}
                    placeholder={
                      "Compreender a doutrina da graça\nRelacionar Escritura e Tradição\n..."
                    }
                  />
                  <p className="text-[11px] text-muted-foreground mt-1">
                    {
                      form.learning_objectives
                        .split("\n")
                        .map((l) => l.trim())
                        .filter(Boolean).length
                    }{" "}
                    objetivo(s)
                  </p>
                </div>
                <div>
                  <Label>Pré-requisitos (um por linha)</Label>
                  <Textarea
                    rows={5}
                    value={form.prerequisites}
                    onChange={(e) => setForm({ ...form, prerequisites: e.target.value })}
                    placeholder={"Leitura básica do Credo\nFamiliaridade com o CIC §§1-100\n..."}
                  />
                  <p className="text-[11px] text-muted-foreground mt-1">
                    {
                      form.prerequisites
                        .split("\n")
                        .map((l) => l.trim())
                        .filter(Boolean).length
                    }{" "}
                    pré-requisito(s)
                  </p>
                </div>
              </div>

              <div>
                <Label>Mensagem de conclusão</Label>
                <Textarea
                  rows={3}
                  value={form.completion_message}
