                  Trilha certificável — libera{" "}
                  <code className="text-xs">/colecoes/{form.slug || ":slug"}/certificado</code>
                </Label>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">Itens da coleção ({data.items.length})</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <CollectionItemsList
                items={data.items}
                onReorder={(ids) => reorder.mutate(ids)}
                onRemove={(itemId) => removeItem.mutate(itemId)}
                disabled={reorder.isPending || removeItem.isPending}
              />
              <ContentPicker
                disabled={addItem.isPending}
                onPick={async (p) => {
                  try {
                    await addItem.mutateAsync({
                      collectionId: c.id,
                      itemType: p.itemType,
                      itemSlug: p.itemSlug,
                      titleOverride: p.titleOverride ?? null,
                    });
                    toast.success("Item adicionado.");
                  } catch (e) {
                    toast.error(e instanceof Error ? e.message : "Falha ao adicionar.");
                  }
                }}
              />
            </CardContent>
          </Card>
        </div>

        <aside className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Nexus da coleção</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3 text-sm">
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Total de itens</span>
                <Badge variant="outline">{nexusMetrics?.total ?? 0}</Badge>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-muted-foreground">Itens órfãos</span>
                <Badge variant={nexusMetrics?.orphans ? "destructive" : "outline"}>
                  {nexusMetrics?.orphans ?? 0}
                </Badge>
              </div>
              <div className="pt-2 border-t border-border">
                <div className="text-xs uppercase text-muted-foreground mb-2">Distribuição</div>
                <ul className="space-y-1">
                  {Object.entries(nexusMetrics?.byType ?? {}).map(([k, n]) => (
                    <li key={k} className="flex items-center justify-between">
                      <span className="capitalize">{k}</span>
                      <span className="font-mono text-xs">{n}</span>
                    </li>
                  ))}
                  {(!nexusMetrics || nexusMetrics.total === 0) && (
                    <li className="text-xs text-muted-foreground">Nenhum item ainda.</li>
                  )}
                </ul>
              </div>
              <p className="pt-2 border-t border-border text-xs text-muted-foreground">
                Mesma linguagem de{" "}
                <Link to="/admin/nexus-audit" className="underline">
                  /admin/nexus-audit
                </Link>
                .
              </p>
            </CardContent>
          </Card>
        </aside>
      </div>
    </div>
  );
}

/**
 * /admin/editorial-audit — Sprint 6 · Consolidação Editorial do Glossário.
 *
 * Refinamentos Sprint 6 (pré-Santos):
 *  1. Índice de Confiança Editorial (ICE) — Ouro/Prata/Bronze/Revisão
 *  2. Scores separados: Editorial × Nexus
 *  3. Pendências Inteligentes com sugestões de fontes
 *  4. Histórico Editorial por verbete (criado/revisado/publicado/versão)
 *  5. Dashboard de Produção cross-módulo (Glossário, Santos, Orações, etc.)
 *  6. Sprint 6.5 · Selo de Congelamento Editorial
 *
 * Toda geração via IA rebaixa o verbete para draft.
 */
