const FILTERS = [
  { key: "all", label: "Todos" },
  { key: "published", label: "Publicados" },
  { key: "draft", label: "Drafts" },
  { key: "gold", label: "ICE Ouro (≥95)" },
  { key: "silver", label: "ICE Prata (85–94)" },
  { key: "bronze", label: "ICE Bronze (70–84)" },
  { key: "review", label: "Revisão obrigatória (<70)" },
  { key: "no_deep", label: "Sem interpretação" },
  { key: "no_faq", label: "Sem FAQ" },
  { key: "no_logos", label: "Sem Logos" },
  { key: "no_nexus", label: "Nexus incompleto" },
  { key: "no_fathers", label: "Sem Patrística" },
  { key: "no_mag", label: "Sem Magistério" },
] as const;
type FilterKey = (typeof FILTERS)[number]["key"];

/** Índice de Confiança Editorial */
function ice(score: number) {
  if (score >= 95)
    return {
      tier: "gold" as const,
      label: "Ouro",
      emoji: "🟢",
      cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-700",
    };
  if (score >= 85)
    return {
      tier: "silver" as const,
      label: "Prata",
      emoji: "🔵",
      cls: "border-sky-500/40 bg-sky-500/10 text-sky-700",
    };
  if (score >= 70)
    return {
      tier: "bronze" as const,
      label: "Bronze",
      emoji: "🟡",
      cls: "border-amber-500/40 bg-amber-500/10 text-amber-700",
    };
  return {
    tier: "review" as const,
    label: "Revisão obrigatória",
    emoji: "🔴",
    cls: "border-red-500/40 bg-red-500/10 text-red-700",
  };
}

function computeChecks(r: any): Check[] {
  const nz = (v: any) => typeof v === "string" && v.trim().length >= 20;
  const arr = (v: any, min = 1) => Array.isArray(v) && v.length >= min;
  const nexusCount = Array.isArray(r.nexus_refs) ? r.nexus_refs.length : 0;
  return [
    {
      field: "short_definition",
      label: "Definição curta",
      weight: 4,
      ok: nz(r.short_definition),
      generable: false,
      group: "editorial",
    },
    {
      field: "definition",
      label: "Definição",
      weight: 8,
      ok: nz(r.definition),
      generable: false,
      group: "editorial",
    },
    {
      field: "deep_interpretation",
      label: "Interpretação profunda",
      weight: 15,
      ok: nz(r.deep_interpretation),
      generable: true,
      group: "editorial",
    },
    {
      field: "etymology",
      label: "Etimologia",
      weight: 8,
      ok: nz(r.etymology),
      generable: true,
      group: "editorial",
    },
    {
      field: "historical_context",
      label: "Contexto histórico",
      weight: 8,
      ok: nz(r.historical_context),
      generable: true,
      group: "editorial",
    },
    {
      field: "practical_application",
      label: "Aplicação prática",
      weight: 8,
      ok: nz(r.practical_application),
      generable: true,
      group: "editorial",
    },
    {
      field: "logos_meditation",
      label: "Meditação Logos",
      weight: 8,
      ok: nz(r.logos_meditation),
      generable: true,
      group: "editorial",
    },
    {
      field: "faq",
      label: "FAQ (≥3)",
      weight: 8,
      ok: arr(r.faq, 3),
      generable: true,
      group: "editorial",
    },
    {
      field: "bibliography",
      label: "Bibliografia (≥3)",
      weight: 7,
      ok: arr(r.bibliography, 3),
      generable: true,
      group: "editorial",
    },
    {
      field: "bible_verses",
      label: "Bíblia (≥3)",
      weight: 6,
      ok: arr(r.bible_verses, 3),
      generable: true,
      group: "nexus",
    },
    {
      field: "catechism_references",
      label: "CIC (≥2)",
      weight: 6,
      ok: arr(r.catechism_references, 2),
      generable: true,
      group: "nexus",
    },
    {
      field: "fathers_refs",
      label: "Padres (≥1)",
      weight: 5,
      ok: arr(r.fathers_refs, 1),
      generable: true,
      group: "nexus",
    },
    {
      field: "magisterium_references",
      label: "Magistério (≥1)",
      weight: 5,
      ok: arr(r.magisterium_references, 1),
      generable: true,
      group: "nexus",
    },
    {
      field: "nexus",
      label: `Nexus ${nexusCount}/${GOLD_MIN}`,
      weight: 4,
      ok: nexusCount >= GOLD_MIN,
      generable: false,
      group: "nexus",
    },
  ];
}

function scoreOfGroup(checks: Check[], group?: Group): number {
  const sel = group ? checks.filter((c) => c.group === group) : checks;
  const total = sel.reduce((s, c) => s + c.weight, 0) || 1;
  const earned = sel.filter((c) => c.ok).reduce((s, c) => s + c.weight, 0);
  return Math.round((earned / total) * 100);
}

