interface Snapshot {
  id: string;
  captured_at: string;
  avg_ice: number;
  avg_editorial: number;
  avg_nexus: number;
  gold: number;
  silver: number;
  bronze: number;
  review: number;
  gate_passing: number;
  gate_failing: number;
