async function loadModuleStats(): Promise<ModuleStat[]> {
  const results = await Promise.allSettled([
    supabase.from("glossary").select("status", { count: "exact", head: false }),
    supabase.from("saints").select("id", { count: "exact", head: true }),
    supabase.from("prayers").select("is_published", { count: "exact", head: false }),
    supabase.from("collections").select("status", { count: "exact", head: false }),
    supabase.from("journeys").select("status", { count: "exact", head: false }),
    supabase.from("bible_verses").select("id", { count: "exact", head: true }),
    supabase.from("liturgy_meditations").select("id", { count: "exact", head: true }),
    supabase.from("library_items_v1").select("status", { count: "exact", head: false }),
    supabase.from("library_items_v1").select("status", { count: "exact", head: false }),
  ]);

  const stat = (
    label: string,
    key: string,
    res: any,
    isPub: (r: any) => boolean,
    note?: string,
  ): ModuleStat => {
    if (res.status !== "fulfilled" || res.value.error) {
      return { key, label, published: 0, total: 0, note: "sem acesso" };
    }
    const rows = res.value.data ?? [];
    const total = res.value.count ?? rows.length;
    const published = rows.filter(isPub).length;
    return { key, label, published, total, note };
  };

  return [
    stat("Glossário", "glossary", results[0], (r) => r.status === "published"),
    // Santos: tratamos "todos publicados" (import massivo)
    (() => {
      const res = results[1];
      if (res.status !== "fulfilled" || res.value.error) {
        return { key: "saints", label: "Santos", published: 0, total: 0, note: "sem acesso" };
      }
      const t = res.value.count ?? 0;
      return { key: "saints", label: "Santos", published: t, total: t, note: "sem status" };
    })(),
    stat("Orações", "prayers", results[2], (r) => r.is_published === true),
    stat("Coleções", "collections", results[3], (r) => r.status === "published"),
    stat("Jornadas", "journeys", results[4], (r) => r.status === "published"),
    // Bíblia: tratamos "todos publicados"
    (() => {
      const res = results[5];
      if (res.status !== "fulfilled" || res.value.error) {
        return { key: "bible", label: "Bíblia", published: 0, total: 0, note: "sem acesso" };
      }
      const t = res.value.count ?? 0;
      return { key: "bible", label: "Bíblia", published: t, total: t };
    })(),
    (() => {
      const res = results[6];
      if (res.status !== "fulfilled" || res.value.error) {
        return { key: "liturgy", label: "Liturgia", published: 0, total: 0, note: "sem acesso" };
      }
      const t = res.value.count ?? 0;
      return { key: "liturgy", label: "Liturgia", published: t, total: t };
    })(),
    stat("Patrística", "patristic", results[7], (r) => r.status === "published"),
    stat("Magistério", "magisterium", results[8], (r) => r.status === "published"),
  ];
}

function ScoreBar({ label, value }: { label: string; value: number }) {
  const tone =
    value >= 95
      ? "text-emerald-600"
      : value >= 85
        ? "text-sky-700"
        : value >= 70
          ? "text-amber-700"
          : "text-red-700";
  return (
    <div className="flex items-center gap-2">
      <span className="w-16 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
        {label}
      </span>
      <Progress value={value} className="h-1.5 flex-1" />
      <span className={`w-10 text-right text-xs font-bold tabular-nums ${tone}`}>{value}%</span>
    </div>
  );
}

function Summary({
  label,
  value,
  tone = "neutral",
}: {
  label: string;
  value: string | number;
  tone?: "ok" | "warn" | "bad" | "neutral";
}) {
  const cls =
    tone === "ok"
      ? "border-emerald-500/30 bg-emerald-500/5"
      : tone === "warn"
        ? "border-amber-500/30 bg-amber-500/5"
        : tone === "bad"
          ? "border-red-500/30 bg-red-500/5"
          : "border-border";
  return (
    <div className={`rounded-lg border p-3 ${cls}`}>
      <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
        {label}
      </p>
      <p className="mt-1 text-lg font-bold tabular-nums">{value}</p>
    </div>
  );
}

type KpiTone = "ok" | "warn" | "bad" | "neutral";
function toneFor(v: number): KpiTone {
  if (v >= 95) return "ok";
  if (v >= 85) return "neutral";
  if (v >= 70) return "warn";
  return "bad";
}
function Kpi({
  label,
  value,
  tone = "neutral",
  hint,
}: {
  label: string;
  value: string | number;
  tone?: KpiTone;
  hint?: string;
}) {
  const cls =
    tone === "ok"
      ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-700"
      : tone === "warn"
        ? "border-amber-500/40 bg-amber-500/10 text-amber-700"
        : tone === "bad"
          ? "border-red-500/40 bg-red-500/10 text-red-700"
          : "border-border bg-background";
  return (
    <div className={`rounded-md border px-2.5 py-2 ${cls}`}>
      <p className="text-[9px] font-bold uppercase tracking-widest opacity-70">{label}</p>
      <p className="mt-0.5 text-base font-bold tabular-nums leading-tight">{value}</p>
      {hint && <p className="text-[9px] opacity-60">{hint}</p>}
    </div>
  );
}

/**
 * EditorialBulk — painel genérico de geração em fila por entidade.
 *
 * Reaproveita os wrappers `editorial_correction_priority(entity)` e a Edge
 * Function `editorial-generate`. Suporta glossary/prayers/catechism (todas
 * as entidades já plugadas no motor). Escolha via `?entity=<name>`.
 *
 * Foi criado como página enxuta para não regressar EditorialAudit (1.7k linhas,
 * hardcoded em glossary). Aqui vive o fluxo genérico de bulk generation.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams, Link } from "@/lib/rr-compat";
import { supabase } from "@/lib/db";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toast } from "sonner";
import { Sparkles, Pause, Play, Square, ArrowLeft, Loader2 } from "lucide-react";

type Entity = "glossary" | "prayers" | "catechism";

const ENTITY_LABEL: Record<Entity, string> = {
  glossary: "Glossário",
  prayers: "Orações",
  catechism: "Catecismo",
};

type PriorityRow = {
  slug: string;
  term: string;
  area: string | null;
  status: string | null;
  ice: number | null;
  editorial: number | null;
  nexus: number | null;
  missing_deep: boolean;
  missing_faq: boolean;
  missing_logos: boolean;
  missing_bible: boolean;
  missing_cic: boolean;
  missing_fathers: boolean;
  missing_count: number;
  effort_tier: string | null;
  inbound_refs: number | null;
  impact_tier: string | null;
  priority: string | null;
};

type Task = { slug: string; term: string; field: string };
type Result = Task & { ok: boolean; error?: string };

const FIELD_MAP: Array<{ key: keyof PriorityRow; field: string; label: string }> = [
  { key: "missing_deep", field: "deep_interpretation", label: "Interpretação profunda" },
  { key: "missing_faq", field: "faq", label: "FAQ" },
  { key: "missing_logos", field: "logos_meditation", label: "Meditação Logos" },
  { key: "missing_bible", field: "bible_verses", label: "Bíblia" },
  { key: "missing_cic", field: "catechism_references", label: "CIC" },
  { key: "missing_fathers", field: "fathers_refs", label: "Patrística" },
];

export default function EditorialBulk() {
  const [params, setParams] = useSearchParams();
  const entity = (params.get("entity") ?? "catechism") as Entity;
  const [rows, setRows] = useState<PriorityRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [bucket, setBucket] = useState<"quick_win" | "red" | "orange" | "yellow" | "all">(
    "quick_win",
  );
  const [limit, setLimit] = useState(5);

  const [queue, setQueue] = useState<Task[]>([]);
  const [done, setDone] = useState(0);
  const [current, setCurrent] = useState<Task | null>(null);
  const [results, setResults] = useState<Result[]>([]);
  const [running, setRunning] = useState(false);
  const ctrl = useRef<{ paused: boolean; cancelled: boolean }>({ paused: false, cancelled: false });

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    (supabase as any)
      .rpc("editorial_correction_priority", { _entity: entity })
      .then(({ data, error }: any) => {
        if (cancelled) return;
        if (error) {
          toast.error(`Falha ao carregar prioridade: ${error.message}`);
          setRows([]);
        } else {
          setRows((data ?? []) as PriorityRow[]);
        }
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [entity]);

  const buckets = useMemo(() => {
    const out = {
      quick_win: [] as PriorityRow[],
      red: [] as PriorityRow[],
      orange: [] as PriorityRow[],
      yellow: [] as PriorityRow[],
      all: [] as PriorityRow[],
    };
    for (const r of rows) {
      const p = (r.priority ?? "").toLowerCase();
      out.all.push(r);
      if (p === "quick_win") out.quick_win.push(r);
      else if (p === "red") out.red.push(r);
      else if (p === "orange") out.orange.push(r);
      else if (p === "yellow") out.yellow.push(r);
    }
    return out;
  }, [rows]);

  const preview = useMemo(() => {
    const src = buckets[bucket].slice(0, limit);
    const tasks: Task[] = [];
    for (const r of src) {
      for (const m of FIELD_MAP)
        if (r[m.key]) tasks.push({ slug: r.slug, term: r.term, field: m.field });
    }
    return { entries: src, tasks };
  }, [buckets, bucket, limit]);

  const run = useCallback(async () => {
    if (running) return;
    const tasks = preview.tasks;
    if (tasks.length === 0) {
      toast.info("Nada a gerar neste bucket.");
      return;
    }
    if (
      !window.confirm(
        `Gerar ${tasks.length} campo(s) em ${preview.entries.length} verbete(s) via IA?`,
      )
    )
      return;
    ctrl.current = { paused: false, cancelled: false };
    setQueue(tasks);
    setDone(0);
    setResults([]);
    setRunning(true);
    for (let i = 0; i < tasks.length; i++) {
      while (ctrl.current.paused && !ctrl.current.cancelled)
        await new Promise((r) => setTimeout(r, 300));
      if (ctrl.current.cancelled) break;
      const t = tasks[i];
      setCurrent(t);
      try {
        const { data, error } = await supabase.functions.invoke("editorial-generate", {
          body: { entity, slug: t.slug, field: t.field },
        });
        if (error) throw error;
        if ((data as any)?.error) throw new Error((data as any).error);
        setResults((prev) => [...prev, { ...t, ok: true }]);
      } catch (e: any) {
        const msg = e?.message ?? String(e);
        setResults((prev) => [...prev, { ...t, ok: false, error: msg }]);
        if (msg?.includes("429")) toast.error("Rate limit — aguarde e continue.");
        if (msg?.includes("402")) {
          toast.error("Créditos IA esgotados.");
          ctrl.current.cancelled = true;
        }
      }
      setDone(i + 1);
    }
    setCurrent(null);
    setRunning(false);
    toast.success("Fila finalizada.");
  }, [preview, running, entity]);

  const retryFailed = useCallback(async () => {
    const failed = results
      .filter((r) => !r.ok)
      .map(({ slug, term, field }) => ({ slug, term, field }));
    if (failed.length === 0) return;
    ctrl.current = { paused: false, cancelled: false };
    setQueue(failed);
    setDone(0);
    setResults([]);
    setRunning(true);
    for (let i = 0; i < failed.length; i++) {
      if (ctrl.current.cancelled) break;
      const t = failed[i];
      setCurrent(t);
      try {
        const { data, error } = await supabase.functions.invoke("editorial-generate", {
          body: { entity, slug: t.slug, field: t.field },
        });
        if (error) throw error;
        if ((data as any)?.error) throw new Error((data as any).error);
        setResults((prev) => [...prev, { ...t, ok: true }]);
      } catch (e: any) {
        setResults((prev) => [...prev, { ...t, ok: false, error: e?.message ?? String(e) }]);
      }
      setDone(i + 1);
    }
    setCurrent(null);
    setRunning(false);
  }, [results, entity]);

  const pct = queue.length > 0 ? Math.round((done / queue.length) * 100) : 0;
  const ok = results.filter((r) => r.ok).length;
  const fail = results.length - ok;

  return (
    <div className="mx-auto max-w-6xl p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <Link
            to="/admin/mission-control"
            className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
          >
            <ArrowLeft className="h-4 w-4" /> Mission Control
          </Link>
          <h1 className="mt-1 text-2xl font-serif">Bulk Editorial · {ENTITY_LABEL[entity]}</h1>
          <p className="text-sm text-muted-foreground">
            Geração em fila por bucket de prioridade. Todos os itens voltam para <code>draft</code>{" "}
            após IA.
          </p>
        </div>
        <Select value={entity} onValueChange={(v) => setParams({ entity: v })}>
          <SelectTrigger className="w-44">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="catechism">Catecismo</SelectItem>
            <SelectItem value="glossary">Glossário</SelectItem>
            <SelectItem value="prayers">Orações</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <Card className="p-8 flex items-center justify-center text-muted-foreground">
          <Loader2 className="mr-2 h-4 w-4 animate-spin" /> Carregando prioridade…
        </Card>
      ) : (
        <>
          <Card className="p-4">
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
              {(["quick_win", "red", "orange", "yellow", "all"] as const).map((k) => (
                <button
                  key={k}
                  onClick={() => setBucket(k)}
                  className={`rounded border p-3 text-left transition ${bucket === k ? "border-primary bg-primary/5" : "border-border hover:border-primary/50"}`}
                >
                  <div className="text-xs uppercase tracking-wide text-muted-foreground">
                    {k === "quick_win"
                      ? "🟢 Quick wins"
                      : k === "red"
                        ? "🔴 Alto impacto"
                        : k === "orange"
                          ? "🟠 Médio"
                          : k === "yellow"
                            ? "🟡 Baixo"
                            : "Todos"}
                  </div>
                  <div className="text-2xl font-bold tabular-nums">{buckets[k].length}</div>
                </button>
              ))}
            </div>
          </Card>

          <Card className="p-4 space-y-3">
            <div className="flex flex-wrap items-center gap-3">
              <label className="text-sm">Limite:</label>
              <Select value={String(limit)} onValueChange={(v) => setLimit(Number(v))}>
                <SelectTrigger className="w-24">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {[3, 5, 10, 20, 50].map((n) => (
                    <SelectItem key={n} value={String(n)}>
                      {n}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Badge variant="secondary">
                {preview.entries.length} verbete(s) · {preview.tasks.length} campo(s)
              </Badge>
              <div className="ml-auto flex gap-2">
                {running && (
                  <>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => {
                        ctrl.current.paused = !ctrl.current.paused;
                      }}
                    >
                      {ctrl.current.paused ? (
                        <>
                          <Play className="mr-1 h-3 w-3" /> Continuar
                        </>
                      ) : (
                        <>
                          <Pause className="mr-1 h-3 w-3" /> Pausar
                        </>
                      )}
                    </Button>
                    <Button
                      size="sm"
                      variant="destructive"
                      onClick={() => {
                        ctrl.current.cancelled = true;
                      }}
                    >
                      <Square className="mr-1 h-3 w-3" /> Cancelar
                    </Button>
                  </>
                )}
                {!running && fail > 0 && (
                  <Button size="sm" variant="outline" onClick={retryFailed}>
                    Reprocessar {fail} falha(s)
                  </Button>
                )}
                <Button size="sm" onClick={run} disabled={running || preview.tasks.length === 0}>
                  {running ? (
                    <>
                      <Loader2 className="mr-1 h-3 w-3 animate-spin" /> {done}/{queue.length}
                    </>
                  ) : (
                    <>
                      <Sparkles className="mr-1 h-3 w-3" /> Gerar
                    </>
                  )}
                </Button>
              </div>
            </div>

            {queue.length > 0 && (
              <div className="space-y-1">
                <Progress value={pct} />
                <div className="flex justify-between text-xs text-muted-foreground tabular-nums">
                  <span>
                    {done}/{queue.length} · {pct}% · ✔ {ok} · ✖ {fail}
                  </span>
                  {current && running && (
                    <span>
                      → {current.term} · {current.field}
                    </span>
                  )}
                </div>
              </div>
            )}

            <div className="max-h-96 overflow-auto rounded border">
              <table className="w-full text-sm">
                <thead className="bg-muted/50 text-xs uppercase text-muted-foreground">
                  <tr>
                    <th className="p-2 text-left">Verbete</th>
                    <th className="p-2 text-left">Área</th>
                    <th className="p-2 text-right">ICE</th>
                    <th className="p-2 text-right">Faltando</th>
                    <th className="p-2 text-right">Refs</th>
                  </tr>
                </thead>
                <tbody>
                  {preview.entries.map((r) => (
                    <tr key={r.slug} className="border-t">
                      <td className="p-2 font-medium">
                        {r.term}
                        <div className="text-xs text-muted-foreground">{r.slug}</div>
                      </td>
                      <td className="p-2 text-muted-foreground">{r.area ?? "—"}</td>
                      <td className="p-2 text-right tabular-nums">
                        {r.ice != null ? Number(r.ice).toFixed(0) : "—"}
                      </td>
                      <td className="p-2 text-right tabular-nums">{r.missing_count}</td>
                      <td className="p-2 text-right tabular-nums">{r.inbound_refs ?? 0}</td>
                    </tr>
                  ))}
                  {preview.entries.length === 0 && (
                    <tr>
                      <td colSpan={5} className="p-6 text-center text-muted-foreground">
                        Bucket vazio.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </Card>

          {results.length > 0 && (
            <Card className="p-4">
              <div className="mb-2 text-sm font-medium">Resultado</div>
              <div className="max-h-64 overflow-auto text-xs font-mono space-y-1">
                {results.map((r, i) => (
                  <div key={i} className={r.ok ? "text-emerald-700" : "text-red-700"}>
                    {r.ok ? "✔" : "✖"} {r.slug} · {r.field}
                    {r.error ? ` — ${r.error}` : ""}
                  </div>
                ))}
              </div>
            </Card>
          )}
        </>
      )}
    </div>
  );
}

/**
 * /admin/editorial-integrity — Cathedra Index · Integridade Editorial.
 *
 * Cruza `glossary` e `nexus_relations` para expor inconsistências no padrão
 * Logos 2030 + Nexus Ouro. Permite regeração assistida por IA do
 * `deep_interpretation` (verbete volta para status='draft' após gerar).
 */
import { useCallback, useEffect, useMemo, useState } from "react";
import { Helmet } from "@/lib/helmet-compat";
import { Link } from "@/lib/rr-compat";
import { supabase } from "@/lib/db";
import { toast } from "sonner";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Loader2, Sparkles, AlertCircle, CheckCircle2, ExternalLink } from "lucide-react";

const GOLD_MIN = 20;

interface Row {
  slug: string;
  term: string;
  status: string;
  editorial_completeness: string | null;
  no_deep: boolean;
  no_etym: boolean;
  no_logos: boolean;
  no_bib: boolean;
  no_faq: boolean;
  no_next: boolean;
  nexus_count: number;
  issues: string[];
}

export default function EditorialIntegrityPage() {
  const [rows, setRows] = useState<Row[]>([]);
  const [totals, setTotals] = useState<{ published: number; complete: number; broken: number }>({
    published: 0,
    complete: 0,
    broken: 0,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busySlug, setBusySlug] = useState<string | null>(null);
  const [batchRunning, setBatchRunning] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const { data: allRows, error: e1 } = await supabase
        .from("glossary")
        .select(
          "slug,term,status,editorial_completeness,deep_interpretation,etymology,logos_meditation,bibliography,faq,next_steps,nexus_refs",
        )
        .order("term");
      if (e1) throw e1;

      const published = (allRows ?? []).filter((r: any) => r.status === "published");
      const complete = published.filter((r: any) => r.editorial_completeness === "complete");

      const out: Row[] = [];
      for (const r of complete as any[]) {
        const nexus = Array.isArray(r.nexus_refs) ? r.nexus_refs.length : 0;
        const flags = {
          no_deep: !r.deep_interpretation || String(r.deep_interpretation).trim() === "",
          no_etym: !r.etymology || String(r.etymology).trim() === "",
          no_logos: r.logos_meditation == null,
          no_bib: !r.bibliography || (Array.isArray(r.bibliography) && r.bibliography.length === 0),
          no_faq: !r.faq || (Array.isArray(r.faq) && r.faq.length === 0),
          no_next: !r.next_steps || (Array.isArray(r.next_steps) && r.next_steps.length === 0),
        };
        const issues: string[] = [];
        if (flags.no_deep) issues.push("sem interpretação profunda");
        if (flags.no_etym) issues.push("sem etimologia");
        if (flags.no_logos) issues.push("sem meditação Logos");
        if (flags.no_bib) issues.push("sem bibliografia");
        if (flags.no_faq) issues.push("sem FAQ");
        if (flags.no_next) issues.push("sem próximos passos");
        if (nexus < GOLD_MIN) issues.push(`Nexus ${nexus}/${GOLD_MIN}`);

        if (issues.length > 0) {
          out.push({
            slug: r.slug,
            term: r.term,
            status: r.status,
            editorial_completeness: r.editorial_completeness,
            ...flags,
            nexus_count: nexus,
            issues,
          });
        }
      }

      setRows(out);
      setTotals({
        published: published.length,
        complete: complete.length,
        broken: out.length,
      });
    } catch (e: any) {
      setError(e?.message ?? String(e));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const integrity = useMemo(() => {
    if (totals.complete === 0) return 100;
    return Math.round(((totals.complete - totals.broken) / totals.complete) * 1000) / 10;
  }, [totals]);

  const generateOne = useCallback(
    async (slug: string) => {
      setBusySlug(slug);
      try {
        const { data, error } = await supabase.functions.invoke("glossary-generate-deep", {
          body: { slug },
        });
        if (error) throw error;
        if ((data as any)?.error) throw new Error((data as any).error);
        toast.success(
          `${slug}: interpretação gerada (${(data as any)?.chars} caracteres). Verbete voltou para rascunho.`,
        );
        await load();
      } catch (e: any) {
        toast.error(`${slug}: ${e?.message ?? String(e)}`);
      } finally {
        setBusySlug(null);
      }
    },
    [load],
  );

  const generateAll = useCallback(async () => {
    const targets = rows.filter((r) => r.no_deep).map((r) => r.slug);
    if (targets.length === 0) {
      toast.info("Nenhum verbete sem interpretação profunda.");
      return;
    }
    if (
      !confirm(
        `Gerar interpretação profunda para ${targets.length} verbetes via Logos AI? Todos voltam para rascunho.`,
      )
    )
      return;

    setBatchRunning(true);
    let ok = 0,
      fail = 0;
    for (const slug of targets) {
      setBusySlug(slug);
      try {
        const { data, error } = await supabase.functions.invoke("glossary-generate-deep", {
          body: { slug },
        });
        if (error || (data as any)?.error) throw new Error(error?.message ?? (data as any)?.error);
        ok += 1;
      } catch (e: any) {
        console.error(`[batch] ${slug}:`, e);
        fail += 1;
      }
      // pequeno delay para respeitar rate limit
      await new Promise((r) => setTimeout(r, 800));
    }
    setBusySlug(null);
    setBatchRunning(false);
    toast[fail === 0 ? "success" : "warning"](
      `Batch concluído · ${ok} ok · ${fail} falha(s). Revise em /admin/glossario antes de republicar.`,
    );
    await load();
  }, [rows, load]);

  return (
    <div className="mx-auto max-w-6xl px-4 py-8">
      <Helmet>
        <title>Integridade Editorial · Cathedra Admin</title>
        <meta name="robots" content="noindex,nofollow" />
      </Helmet>

      <header className="mb-6">
        <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
          Cathedra Index
        </p>
        <h1 className="text-3xl font-serif">Integridade Editorial</h1>
        <p className="mt-1 text-sm text-muted-foreground max-w-2xl">
          Verbetes marcados como <code>complete</code> mas com campos obrigatórios vazios ou padrão
          Nexus Ouro (≥ {GOLD_MIN}) não atingido.
        </p>
      </header>

      {loading && <p className="text-sm text-muted-foreground">Carregando…</p>}
      {error && <p className="text-sm text-destructive">Erro: {error}</p>}

      {!loading && !error && (
        <>
          <div className="mb-8 grid grid-cols-2 gap-3 md:grid-cols-4">
            <Summary label="Publicados" value={totals.published} />
            <Summary label="Marcados complete" value={totals.complete} />
            <Summary
              label="Com inconsistência"
              value={totals.broken}
              tone={totals.broken === 0 ? "ok" : "warn"}
            />
            <Summary
              label="Integridade"
              value={`${integrity}%`}
              tone={integrity >= 95 ? "ok" : integrity >= 80 ? "warn" : "bad"}
            />
          </div>

          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <p className="text-sm text-muted-foreground">
              {rows.length} verbete(s) precisam de revisão.
            </p>
            <Button
              onClick={generateAll}
              disabled={batchRunning || rows.filter((r) => r.no_deep).length === 0}
            >
              {batchRunning ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" /> Gerando…
                </>
              ) : (
                <>
                  <Sparkles className="mr-2 h-4 w-4" /> Gerar todos (
                  {rows.filter((r) => r.no_deep).length}) via Logos AI
                </>
              )}
            </Button>
          </div>

          <div className="space-y-3">
            {rows.length === 0 && (
              <Card>
                <CardContent className="flex items-center gap-3 py-6 text-emerald-700">
                  <CheckCircle2 className="h-5 w-5" />
                  <span>Nenhuma inconsistência — todos os verbetes complete estão íntegros.</span>
                </CardContent>
              </Card>
            )}
            {rows.map((r) => (
              <Card key={r.slug}>
                <CardHeader className="flex flex-row items-start justify-between gap-4 pb-3">
                  <div className="min-w-0">
                    <CardTitle className="text-lg flex items-center gap-2 flex-wrap">
                      <Link to={`/glossario/${r.slug}`} className="hover:underline">
                        {r.term}
                      </Link>
                      <ExternalLink className="h-3 w-3 text-muted-foreground" />
                      <Badge variant="outline" className="text-[10px]">
                        {r.editorial_completeness}
                      </Badge>
                    </CardTitle>
                    <div className="mt-2 flex flex-wrap gap-1.5">
                      {r.issues.map((iss) => (
                        <Badge key={iss} variant="secondary" className="text-[10px]">
                          <AlertCircle className="mr-1 h-3 w-3" />
                          {iss}
                        </Badge>
                      ))}
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    {r.no_deep && (
                      <Button
                        size="sm"
                        variant="outline"
                        disabled={busySlug === r.slug || batchRunning}
                        onClick={() => generateOne(r.slug)}
                      >
                        {busySlug === r.slug ? (
                          <>
                            <Loader2 className="mr-2 h-3 w-3 animate-spin" /> Gerando…
                          </>
                        ) : (
                          <>
                            <Sparkles className="mr-2 h-3 w-3" /> Gerar via IA
                          </>
                        )}
                      </Button>
                    )}
                    <Link
                      to={`/admin/glossario?slug=${r.slug}`}
                      className="text-xs text-muted-foreground hover:underline"
                    >
                      editar manualmente →
                    </Link>
                  </div>
                </CardHeader>
                <CardContent className="pt-0">
                  <div className="grid grid-cols-2 gap-2 md:grid-cols-4 text-[11px]">
                    <Field ok={!r.no_deep} label="Interpretação profunda" />
                    <Field ok={!r.no_etym} label="Etimologia" />
                    <Field ok={!r.no_bib} label="Bibliografia" />
                    <Field ok={!r.no_faq} label="FAQ" />
                    <Field ok={!r.no_next} label="Próximos passos" />
                    <Field ok={!r.no_logos} label="Meditação Logos" />
                    <Field
                      ok={r.nexus_count >= GOLD_MIN}
                      label={`Nexus ${r.nexus_count}/${GOLD_MIN}`}
                    />
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function Summary({
  label,
  value,
  tone = "neutral",
}: {
  label: string;
  value: string | number;
  tone?: "ok" | "warn" | "bad" | "neutral";
}) {
  const cls =
    tone === "ok"
      ? "border-emerald-500/30 bg-emerald-500/5"
      : tone === "warn"
        ? "border-amber-500/30 bg-amber-500/5"
        : tone === "bad"
          ? "border-red-500/30 bg-red-500/5"
          : "border-border";
  return (
    <div className={`rounded-lg border p-4 ${cls}`}>
      <p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
        {label}
      </p>
      <p className="mt-1 text-2xl font-bold">{value}</p>
    </div>
  );
}

function Field({ ok, label }: { ok: boolean; label: string }) {
  return (
    <div
      className={`flex items-center gap-1 rounded border px-2 py-1 ${
        ok
          ? "border-emerald-500/20 bg-emerald-500/5 text-emerald-700"
          : "border-amber-500/30 bg-amber-500/5 text-amber-700"
      }`}
    >
      {ok ? <CheckCircle2 className="h-3 w-3" /> : <AlertCircle className="h-3 w-3" />}
      <span>{label}</span>
    </div>
  );
}

