  const [dateFrom, setDateFrom] = useState<string>("");
  const [dateTo, setDateTo] = useState<string>("");
  const [page, setPage] = useState(1);
  const pageSize = 10;

  const loadHistory = useCallback(async () => {
    setHistoryLoading(true);
    const { data, error } = await supabase
      .from("integration_test_runs")
      .select("id, integration_id, ok, message, latency_ms, created_at")
      .order("created_at", { ascending: false })
      .limit(500);
    setHistoryLoading(false);
    if (error) {
      // 403 => usuário não é admin. Silenciar para não poluir.
      if (!/permission|denied|403/i.test(error.message)) {
        toast.error(`Histórico: ${error.message}`);
      }
      return;
    }
    setHistory((data ?? []) as HistoryRow[]);
  }, []);

  useEffect(() => {
    loadHistory();
  }, [loadHistory]);

  const runTest = async (id: string) => {
    setLoading((s) => ({ ...s, [id]: true }));
    let result: TestResult;
    try {
      const { data, error } = await supabase.functions.invoke("integrations-test", {
        body: { id },
      });
      if (error) throw error;
      result = data as TestResult;
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Falha no teste";
      result = { ok: false, message: msg };
    }
    setResults((s) => ({ ...s, [id]: result }));
    result.ok ? toast.success(`${id}: ${result.message}`) : toast.error(`${id}: ${result.message}`);

    // Persistir no histórico (best-effort; ignora se não for admin)
    try {
      const { data: userRes } = await supabase.auth.getUser();
      const uid = userRes.user?.id;
      if (uid) {
        const { error: insErr } = await supabase.from("integration_test_runs").insert({
          integration_id: id,
          ok: result.ok,
          message: result.message.slice(0, 500),
          latency_ms: result.latencyMs ?? null,
          tested_by: uid,
        });
        if (!insErr) {
          loadHistory();
        }
      }
    } catch {
      /* silencioso */
    }

    setLoading((s) => ({ ...s, [id]: false }));
  };

  const grouped = integrations.reduce<Record<string, Integration[]>>((acc, item) => {
    (acc[item.category] ||= []).push(item);
    return acc;
  }, {});

  const integrationName = useMemo(
    () => Object.fromEntries(integrations.map((i) => [i.id, i.name])),
    [],
  );

  const filteredHistory = useMemo(() => {
    const fromTs = dateFrom ? new Date(dateFrom + "T00:00:00").getTime() : null;
    const toTs = dateTo ? new Date(dateTo + "T23:59:59.999").getTime() : null;
    return history.filter((row) => {
      if (filterIntegration !== "all" && row.integration_id !== filterIntegration) return false;
      if (filterStatus === "ok" && !row.ok) return false;
      if (filterStatus === "fail" && row.ok) return false;
      const ts = new Date(row.created_at).getTime();
      if (fromTs !== null && ts < fromTs) return false;
      if (toTs !== null && ts > toTs) return false;
      return true;
    });
  }, [history, filterIntegration, filterStatus, dateFrom, dateTo]);

  const pageCount = Math.max(1, Math.ceil(filteredHistory.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const pagedHistory = filteredHistory.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  useEffect(() => {
    setPage(1);
  }, [filterIntegration, filterStatus, dateFrom, dateTo]);

  const hasFilters =
    filterIntegration !== "all" || filterStatus !== "all" || dateFrom !== "" || dateTo !== "";
  const clearFilters = () => {
    setFilterIntegration("all");
    setFilterStatus("all");
    setDateFrom("");
    setDateTo("");
  };

  const total = integrations.length;
  const connected = integrations.filter((i) => i.status === "connected").length;
  const disconnected = integrations.filter((i) => i.status === "disconnected").length;
  const partial = integrations.filter((i) => i.status === "partial").length;

  return (
    <div className="container mx-auto max-w-5xl px-4 py-8">
      <Helmet>
        <title>Status das Integrações — Admin</title>
        <meta
          name="description"
          content="Visão geral do que está conectado, desconectado e como configurar cada integração do projeto."
        />
      </Helmet>

      <header className="mb-8">
        <h1 className="text-3xl font-serif font-semibold tracking-tight">Status das Integrações</h1>
        <p className="mt-2 text-muted-foreground">
          Visão geral de todos os conectores, chaves e serviços do projeto.
        </p>
      </header>

      <div className="mb-8 grid grid-cols-2 gap-3 md:grid-cols-4">
        <StatCard label="Total" value={total} />
        <StatCard label="Conectados" value={connected} tone="emerald" />
        <StatCard label="Desconectados" value={disconnected} tone="red" />
        <StatCard label="Parciais" value={partial} tone="amber" />
      </div>

      <div className="space-y-8">
        {Object.entries(grouped).map(([category, items]) => (
          <section key={category}>
            <h2 className="mb-3 text-lg font-semibold text-muted-foreground uppercase tracking-wide text-sm">
              {category}
            </h2>
            <div className="grid gap-3 md:grid-cols-2">
              {items.map((item) => {
                const meta = statusMeta[item.status];
                const Icon = meta.icon;
                return (
                  <Card key={item.name} className="flex flex-col">
                    <CardHeader className="pb-3">
                      <div className="flex items-start justify-between gap-2">
                        <CardTitle className="text-base">{item.name}</CardTitle>
                        <Badge variant="outline" className={meta.className}>
                          <Icon className="mr-1 h-3 w-3" />
                          {meta.label}
                        </Badge>
                      </div>
                    </CardHeader>
                    <CardContent className="flex flex-1 flex-col gap-3">
                      <p className="text-sm text-muted-foreground">{item.description}</p>
                      <div className="rounded-md bg-muted/50 p-3 text-sm">
                        <p className="font-medium mb-1">Como configurar</p>
                        <p className="text-muted-foreground">{item.howTo}</p>
                      </div>
                      {results[item.id] && (
                        <div
                          className={`rounded-md p-3 text-sm border ${
                            results[item.id].ok
                              ? "bg-emerald-500/5 border-emerald-500/30 text-emerald-700 dark:text-emerald-400"
                              : "bg-red-500/5 border-red-500/30 text-red-700 dark:text-red-400"
                          }`}
                          role="status"
                          aria-live="polite"
                        >
                          <p className="font-medium mb-0.5">
                            {results[item.id].ok ? "✓ Teste OK" : "✗ Falha no teste"}
                            {results[item.id].latencyMs != null && (
                              <span className="ml-2 text-xs opacity-70">
                                {results[item.id].latencyMs}ms
                              </span>
                            )}
                          </p>
                          <p className="opacity-90">{results[item.id].message}</p>
                        </div>
                      )}
                      <div className="flex flex-wrap gap-2">
                        <Button
                          variant="secondary"
                          size="sm"
                          onClick={() => runTest(item.id)}
                          disabled={loading[item.id]}
                        >
                          {loading[item.id] ? (
                            <Loader2 className="mr-1 h-3 w-3 animate-spin" />
                          ) : (
                            <PlayCircle className="mr-1 h-3 w-3" />
                          )}
                          Testar conexão
                        </Button>
                        {item.docsUrl && (
                          <Button variant="outline" size="sm" asChild>
                            <a href={item.docsUrl} target="_blank" rel="noreferrer">
                              Documentação <ExternalLink className="ml-1 h-3 w-3" />
                            </a>
                          </Button>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </section>
        ))}
      </div>

      <section className="mt-10" aria-labelledby="history-heading">
        <div className="mb-3 flex items-center justify-between">
          <h2 id="history-heading" className="text-lg font-semibold flex items-center gap-2">
            <History className="h-4 w-4" />
            Histórico de testes
            <span className="text-xs text-muted-foreground font-normal">
              ({filteredHistory.length}
              {hasFilters ? ` de ${history.length}` : ""})
            </span>
          </h2>
          <Button variant="ghost" size="sm" onClick={loadHistory} disabled={historyLoading}>
            {historyLoading ? (
              <Loader2 className="mr-1 h-3 w-3 animate-spin" />
            ) : (
              <RefreshCw className="mr-1 h-3 w-3" />
            )}
            Atualizar
          </Button>
        </div>

        <Card className="mb-3">
          <CardContent className="p-4">
            <div className="grid gap-3 md:grid-cols-4">
              <div>
                <Label
                  htmlFor="flt-integration"
                  className="text-xs uppercase tracking-wide text-muted-foreground"
                >
                  Integração
                </Label>
                <Select value={filterIntegration} onValueChange={setFilterIntegration}>
                  <SelectTrigger id="flt-integration" className="mt-1">
                    <SelectValue placeholder="Todas" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todas</SelectItem>
                    {integrations.map((i) => (
                      <SelectItem key={i.id} value={i.id}>
                        {i.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label
                  htmlFor="flt-status"
                  className="text-xs uppercase tracking-wide text-muted-foreground"
                >
                  Status
                </Label>
                <Select
                  value={filterStatus}
                  onValueChange={(v) => setFilterStatus(v as "all" | "ok" | "fail")}
                >
                  <SelectTrigger id="flt-status" className="mt-1">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todos</SelectItem>
                    <SelectItem value="ok">OK</SelectItem>
                    <SelectItem value="fail">Falha</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label
                  htmlFor="flt-from"
                  className="text-xs uppercase tracking-wide text-muted-foreground"
                >
                  De
                </Label>
                <Input
                  id="flt-from"
                  type="date"
                  value={dateFrom}
                  onChange={(e) => setDateFrom(e.target.value)}
                  className="mt-1"
                />
              </div>
              <div>
                <Label
                  htmlFor="flt-to"
                  className="text-xs uppercase tracking-wide text-muted-foreground"
                >
                  Até
                </Label>
                <Input
                  id="flt-to"
                  type="date"
                  value={dateTo}
                  onChange={(e) => setDateTo(e.target.value)}
                  className="mt-1"
                />
              </div>
            </div>
            {hasFilters && (
              <div className="mt-3 flex justify-end">
                <Button variant="ghost" size="sm" onClick={clearFilters}>
                  <X className="mr-1 h-3 w-3" /> Limpar filtros
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-0">
            {history.length === 0 ? (
              <p className="p-6 text-sm text-muted-foreground text-center">
                {historyLoading
                  ? "Carregando…"
                  : 'Nenhum teste registrado ainda. Clique em "Testar conexão" acima.'}
              </p>
            ) : filteredHistory.length === 0 ? (
              <p className="p-6 text-sm text-muted-foreground text-center">
                Nenhum registro para os filtros aplicados.
              </p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-muted/50 text-left text-xs uppercase tracking-wide text-muted-foreground">
                    <tr>
                      <th className="px-4 py-2 font-medium">Data / hora</th>
                      <th className="px-4 py-2 font-medium">Integração</th>
                      <th className="px-4 py-2 font-medium">Resultado</th>
                      <th className="px-4 py-2 font-medium">Latência</th>
                      <th className="px-4 py-2 font-medium">Mensagem / Erro</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pagedHistory.map((row) => (
                      <tr key={row.id} className="border-t border-border/60 align-top">
                        <td className="px-4 py-2 whitespace-nowrap text-muted-foreground">
                          {new Date(row.created_at).toLocaleString("pt-BR", {
                            dateStyle: "short",
                            timeStyle: "medium",
                          })}
                        </td>
                        <td className="px-4 py-2 whitespace-nowrap font-medium">
                          {integrationName[row.integration_id] ?? row.integration_id}
                        </td>
                        <td className="px-4 py-2">
                          <Badge
                            variant="outline"
                            className={
                              row.ok
                                ? "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-emerald-500/30"
                                : "bg-red-500/10 text-red-700 dark:text-red-400 border-red-500/30"
                            }
                          >
                            {row.ok ? (
                              <CheckCircle2 className="mr-1 h-3 w-3" />
                            ) : (
                              <XCircle className="mr-1 h-3 w-3" />
                            )}
                            {row.ok ? "OK" : "Falha"}
                          </Badge>
                        </td>
                        <td className="px-4 py-2 whitespace-nowrap text-muted-foreground">
                          {row.latency_ms != null ? `${row.latency_ms}ms` : "—"}
                        </td>
                        <td className="px-4 py-2 text-muted-foreground max-w-md break-words">
                          {row.message}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            {filteredHistory.length > pageSize && (
              <div className="flex items-center justify-between border-t border-border/60 px-4 py-2 text-sm">
                <span className="text-muted-foreground">
                  Página {currentPage} de {pageCount}
                </span>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    disabled={currentPage <= 1}
                  >
                    <ChevronLeft className="h-3 w-3" /> Anterior
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage((p) => Math.min(pageCount, p + 1))}
                    disabled={currentPage >= pageCount}
                  >
                    Próxima <ChevronRight className="h-3 w-3" />
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </section>

      <footer className="mt-10 border-t pt-6 text-sm text-muted-foreground">
        <p>
          Painel relacionado:{" "}
          <Link to="/admin/seo" className="underline underline-offset-4 hover:text-foreground">
            Admin SEO
          </Link>
        </p>
      </footer>
    </div>
  );
}

function StatCard({
  label,
  value,
  tone,
}: {
  label: string;
  value: number;
  tone?: "emerald" | "red" | "amber";
}) {
  const toneClass =
    tone === "emerald"
      ? "text-emerald-600 dark:text-emerald-400"
      : tone === "red"
        ? "text-red-600 dark:text-red-400"
        : tone === "amber"
          ? "text-amber-600 dark:text-amber-400"
          : "text-foreground";
  return (
    <Card>
      <CardContent className="p-4">
        <p className="text-xs uppercase tracking-wide text-muted-foreground">{label}</p>
        <p className={`mt-1 text-2xl font-semibold ${toneClass}`}>{value}</p>
      </CardContent>
    </Card>
  );
}

/**
 * Cathedra Mission Control — sala de controle do ecossistema editorial.
 *
 * Lê os manifestos registrados no Editorial Engine e mostra, por entidade,
 * ICE, Nexus, tier e status do gate. Entidades ainda não plugadas aparecem
 * como placeholders "Não configurado" até seu manifesto ganhar `ready: true`.
 */
import { useMemo } from "react";
import { Helmet } from "@/lib/helmet-compat";
import { Link } from "@/lib/rr-compat";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import {
  Target,
  ArrowRight,
  Lock,
  ShieldCheck,
  Trophy,
  PieChart,
  Activity,
  Mail,
} from "lucide-react";
import { IACalculator } from "@/components/admin/IACalculator";
import { IAMetricsDashboard } from "@/components/admin/IAMetricsDashboard";
import { LandingAnalyticsDashboard } from "@/components/admin/LandingAnalyticsDashboard";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { LeadsDashboard } from "@/components/admin/LeadsDashboard";
import { editorialRegistry } from "@/lib/editorial-engine/manifests";
import { useEditorialSummary } from "@/lib/editorial-engine/useEditorialAudit";
import { iceTierLabel } from "@/lib/editorial-engine/ice";
import type { EntityManifest } from "@/lib/editorial-engine/types";

function tierClasses(tier: string) {
  switch (tier) {
    case "gold":
      return { text: "text-emerald-700", bar: "bg-emerald-500", border: "border-l-emerald-500" };
    case "silver":
      return { text: "text-sky-700", bar: "bg-sky-500", border: "border-l-sky-500" };
    case "bronze":
      return { text: "text-amber-700", bar: "bg-amber-500", border: "border-l-amber-500" };
    default:
      return { text: "text-red-700", bar: "bg-red-500", border: "border-l-red-500" };
  }
}

function statusLabel(s: {
  frozen: boolean;
  ice: number;
  gatePassing: number;
  gateTotal: number;
  ready: boolean;
}): string {
  if (!s.ready) return "Não configurado";
  if (s.gateTotal === 0) return "Aguardando primeira auditoria";
  if (s.frozen) return "Pronto para Certificação";
  if (s.ice >= 85) return "Em progresso · Prata";
  if (s.ice >= 70) return "Em progresso · Bronze";
  return "Fase Fundação";
}

function EntityRow({ manifest }: { manifest: EntityManifest }) {
  const s = useEditorialSummary(manifest);
  const t = tierClasses(s.tier);
  const status = statusLabel({ ...s, ready: manifest.ready });
  const pct = Math.round(s.ice);

  return (
    <Card className={`border-l-4 ${manifest.ready ? t.border : "border-l-muted"}`}>
      <CardContent className="p-4">
        <div className="flex items-start gap-4">
          <div className="flex-1 min-w-0">
            <div className="flex items-baseline gap-2">
              <h3 className="font-serif text-lg leading-none">{manifest.label}</h3>
              {manifest.ready ? (
                <Badge variant="outline" className={`text-[10px] ${t.text}`}>
                  {iceTierLabel(s.tier)}
                </Badge>
              ) : (
                <Badge variant="outline" className="text-[10px] text-muted-foreground">
                  Placeholder
                </Badge>
              )}
              {s.frozen && (
                <Badge
                  variant="outline"
                  className="border-amber-500/50 bg-amber-500/10 text-[10px] text-amber-700"
                >
                  <Trophy className="mr-1 h-2.5 w-2.5" /> Certificável
                </Badge>
              )}
            </div>
            <p className="mt-0.5 text-[11px] text-muted-foreground">{status}</p>

            <div className="mt-3">
              <div className="mb-1 flex items-center justify-between text-[11px]">
                <span className="text-muted-foreground">ICE</span>
                <span
                  className={`font-semibold tabular-nums ${manifest.ready ? t.text : "text-muted-foreground"}`}
                >
                  {manifest.ready && s.snapshot ? `${pct}%` : "—"}
                </span>
              </div>
              <div className="h-2 w-full overflow-hidden rounded-full bg-muted">
                <div
                  className={`h-full transition-all ${t.bar}`}
                  style={{ width: manifest.ready ? `${pct}%` : "0%" }}
                />
              </div>
            </div>

            <div className="mt-3 grid grid-cols-4 gap-3 text-[11px]">
              <Stat
                label="Editorial"
                value={manifest.ready && s.snapshot ? `${Math.round(s.editorial)}%` : "—"}
              />
              <Stat
                label="Nexus"
                value={manifest.ready && s.snapshot ? `${Math.round(s.nexus)}%` : "—"}
              />
              <Stat
                label="Gate"
                value={manifest.ready && s.gateTotal > 0 ? `${s.gatePassing}/${s.gateTotal}` : "—"}
              />
              <Stat
                label="Freeze"
                value={manifest.ready ? `${s.freezePassCount}/${s.freezeTotalCount}` : "—"}
              />
            </div>
          </div>

          {manifest.ready ? (
            <div className="flex gap-1">
              <Button asChild variant="ghost" size="sm">
                <Link to={manifest.auditRoute}>
                  Abrir <ArrowRight className="ml-1 h-3.5 w-3.5" />
                </Link>
              </Button>
              {(["glossary", "prayers", "catechism"] as const).includes(manifest.id as any) && (
                <Button asChild variant="outline" size="sm">
                  <Link to={`/admin/editorial-bulk?entity=${manifest.id}`}>Bulk IA</Link>
                </Button>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-1 text-[11px] text-muted-foreground">
              <Lock className="h-3 w-3" /> Aguardando manifesto
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</p>
      <p className="text-sm font-semibold tabular-nums">{value}</p>
    </div>
  );
}

/** Painel agregado do "Sistema" — média ponderada de todas as entidades prontas. */
function SystemPanel() {
  const summaries = editorialRegistry.map((m) => ({ m, s: useEditorialSummary(m) }));
  const ready = summaries.filter((x) => x.m.ready && x.s.snapshot);
  const totalWeight = ready.reduce((s, x) => s + x.m.weight, 0);
  const weightedIce = totalWeight
    ? Math.round(ready.reduce((s, x) => s + x.s.ice * x.m.weight, 0) / totalWeight)
    : 0;
  const readyCount = ready.length;
  const totalCount = editorialRegistry.length;
  const allFrozen = ready.length > 0 && ready.every((x) => x.s.frozen);

  const systemStatus = allFrozen
    ? "Pronto para Certificação"
    : readyCount < totalCount
      ? "Expansão em andamento"
      : weightedIce >= 85
        ? "Em consolidação"
        : "Em construção";

  return (
    <Card className="mb-6 border-l-4 border-l-primary">
      <CardHeader className="pb-2">
        <CardTitle className="text-base flex items-center gap-2">
          <ShieldCheck className="h-4 w-4 text-primary" />
          Sistema · Cathedra
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          <div>
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground">
              ICE global (ponderado)
            </p>
            <p className="font-serif text-3xl tabular-nums">{weightedIce}%</p>
            <Progress value={weightedIce} className="mt-2 h-1.5" />
          </div>
          <div>
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground">
              Módulos plugados
            </p>
            <p className="font-serif text-3xl tabular-nums">
              {readyCount}/{totalCount}
            </p>
          </div>
          <div>
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground">
              Certificáveis
            </p>
            <p className="font-serif text-3xl tabular-nums">
              {ready.filter((x) => x.s.frozen).length}
            </p>
          </div>
          <div>
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground">Status</p>
            <p className="text-sm font-semibold pt-1">{systemStatus}</p>
          </div>
