  useEffect(() => {
    if (q.trim().length < 2) {
      setHits([]);
      return;
    }
    setLoading(true);
    globalSearchV2(q)
      .then(setHits)
      .finally(() => setLoading(false));
  }, [q]);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim().length < 2) return;
    setParams({ q: input.trim() });
