import React, { useState, useMemo } from "react";
import { Link, useNavigate, useLocation, useSearchParams } from "@/lib/rr-compat";
import { X } from "lucide-react";

const BASE = "/prototype-2.0";

interface Hit {
  fonte: string;
  ref: string;
  excerpt: string;
  leitor: string;
  nexus?: boolean;
}

const CORPUS: Hit[] = [
  {
    fonte: "Bíblia",
    ref: "Jo 15,1",
    excerpt: '"Eu sou a videira verdadeira…"',
    leitor: "jo15",
    nexus: true,
  },
  { fonte: "Bíblia", ref: "Jo 15,5", excerpt: '"… sem mim nada podeis fazer."', leitor: "jo15" },
  { fonte: "Bíblia", ref: "Sl 80,9", excerpt: '"Do Egito trouxeste uma videira…"', leitor: "sl23" },
  {
    fonte: "Catecismo",
    ref: "§755",
    excerpt: "A Igreja é a videira mística escolhida por Deus.",
    leitor: "cic1234",
    nexus: true,
  },
  {
    fonte: "Catecismo",
    ref: "§787",
    excerpt: "Comunhão íntima entre Cristo e os discípulos.",
    leitor: "cic1234",
  },
  {
    fonte: "Padres",
    ref: "Agostinho · Tract. 81",
    excerpt: "Sobre a videira e os ramos…",
    leitor: "jo15",
    nexus: true,
  },
  {
    fonte: "Padres",
    ref: "Cirilo Alex. · Comm. Jo",
    excerpt: "Comentário ao capítulo 15.",
    leitor: "jo15",
  },
  {
    fonte: "Magistério",
    ref: "Lumen Gentium 6",
    excerpt: "Imagens da Igreja: videira, rebanho, edificação.",
    leitor: "jo15",
  },
  { fonte: "Orações", ref: "Oração pelo aumento da fé", excerpt: "…", leitor: "laudes" },
  {
    fonte: "Jornadas",
    ref: "Introdução à Fé",
    excerpt: "14 dias · Credo, sacramentos, moral.",
    leitor: "jo15",
  },
];

const Pesquisa: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [params] = useSearchParams();
  const [q, setQ] = useState(params.get("q") ?? "videira");

  const back = (location.state as any)?.from ?? `${BASE}/atrio`;

  const results = useMemo(() => {
    if (q.trim().length < 2) return [];
    const needle = q.toLowerCase();
    return CORPUS.filter(
      (h) =>
        h.ref.toLowerCase().includes(needle) ||
        h.excerpt.toLowerCase().includes(needle) ||
        h.fonte.toLowerCase().includes(needle),
    );
  }, [q]);

  const grouped = useMemo(() => {
    const g: Record<string, Hit[]> = {};
    for (const h of results) (g[h.fonte] ||= []).push(h);
    return g;
  }, [results]);

  const totalFontes = [
    "Bíblia",
    "Catecismo",
    "Padres",
    "Magistério",
    "Cânon",
    "Orações",
    "Jornadas",
  ];

  return (
    <div className="min-h-dvh bg-background/95 backdrop-blur text-foreground max-w-2xl mx-auto px-4 py-4">
      <div className="flex items-center gap-2 border-b border-border pb-3">
        <input
          autoFocus
          value={q}
          onChange={(e) => setQ(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Escape") navigate(back);
            if (e.key === "Enter" && results[0])
              navigate(`${BASE}/leitor?ref=${results[0].leitor}`);
          }}
          placeholder="Buscar em tudo…"
          className="flex-1 bg-transparent outline-none text-lg font-serif"
        />
        <button
          onClick={() => navigate(back)}
          aria-label="Fechar"
          className="p-1.5 rounded hover:bg-muted"
        >
          <X size={18} />
        </button>
      </div>

      {q.trim().length < 2 ? (
        <div className="mt-6">
          <p className="text-[10px] uppercase tracking-[0.25em] text-muted-foreground mb-3">
            Sugestões de sintaxe
          </p>
          <ul className="text-sm space-y-2 font-mono">
            <li>
              <button onClick={() => setQ("jo 15")} className="hover:text-primary">
                jo 15 → João 15
              </button>
            </li>
            <li>
              <button onClick={() => setQ("cic 1234")} className="hover:text-primary">
                cic 1234 → CIC §1234
              </button>
            </li>
            <li>
              <button onClick={() => setQ("cân 204")} className="hover:text-primary">
                cân 204 → Cânon 204
              </button>
            </li>
          </ul>
        </div>
      ) : (
        <div className="mt-4">
          {totalFontes.map((fonte) => {
            const hits = grouped[fonte] ?? [];
            return (
              <section key={fonte} className="mb-5">
                <p className="text-[10px] uppercase tracking-[0.25em] text-muted-foreground mb-2">
                  {fonte} ({hits.length})
                </p>
                {hits.length === 0 ? (
                  <p className="text-xs text-muted-foreground italic">
                    Sem resultados nesta fonte.
                  </p>
                ) : (
                  <ul className="space-y-1.5">
                    {hits.map((h, i) => (
                      <li key={i}>
                        <Link
                          to={`${BASE}/leitor?ref=${h.leitor}`}
                          className="block p-2 -mx-2 rounded hover:bg-muted/50"
                        >
                          <span className="text-sm font-medium">▸ {h.ref}</span>
                          {h.nexus && <span className="ml-1 text-primary text-xs">°</span>}
                          <span className="block text-xs text-muted-foreground truncate">
                            {h.excerpt}
                          </span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                )}
              </section>
            );
          })}
        </div>
      )}

      <div className="sticky bottom-0 -mx-4 px-4 py-2 border-t border-border bg-background/95 text-xs text-muted-foreground flex gap-2">
        Filtros:
        <button className="px-2 py-0.5 border border-border rounded">Tempo</button>
        <button className="px-2 py-0.5 border border-border rounded">Fonte</button>
        <button className="px-2 py-0.5 border border-border rounded">PT</button>
      </div>
    </div>
  );
};

export default Pesquisa;

/**
 * Prayer Engine — carregador da hierarquia do banco.
 *
 * Sprint 1.0 — Fase A/D. Lê `prayer_sections → prayer_mysteries → prayer_blocks`
 * do Supabase e produz um `PrayerBlock[]` linear compatível com o `PrayerEngineReader`
 * (que fará papel de `PrayerReader` unificado nesta primeira onda).
 *
 * A hierarquia continua no banco; o achatamento é apenas uma visão de leitura
 * para o Reader atual. Fase seguinte substitui o Reader por navegação
 * hierárquica nativa sem alterar o schema.
 */
import { supabase } from "@/lib/db";
import type { PrayerBlock } from "@/types/prayer";

export interface DBSection {
  id: string;
  slug: string;
  title: string;
  subtitle: string | null;
  order_index: number;
  weekdays: number[];
  meta: Record<string, unknown>;
}
export interface DBMystery {
  id: string;
  section_id: string;
  slug: string;
  title: string;
  subtitle: string | null;
  order_index: number;
  gospel_ref: string | null;
  meditation: string | null;
  fruit: string | null;
  meta: Record<string, unknown> | null;
}
export interface DBBlock {
  id: string;
  section_id: string | null;
  mystery_id: string | null;
  type: string;
  title: string | null;
  content: Record<string, unknown> | null;
  repeat_count: number;
  order_index: number;
  meta?: Record<string, unknown> | null;
}

export interface PrayerHierarchy {
  prayerId: string;
  sections: DBSection[];
  mysteries: DBMystery[];
  blocks: DBBlock[];
}

const BLOCK_KIND_MAP: Record<string, PrayerBlock["kind"]> = {
  announce: "mystery",
  pater_noster: "prayer",
  ave_maria: "decade",
  gloria: "prayer",
  fatima: "prayer",
  meditation: "meditation",
  intro: "intro",
  closing: "closing",
};

const REPEAT_LABEL: Record<string, string> = {
  ave_maria: "Ave-Maria",
};

/** Escolhe a seção para o dia da semana (0=Dom). */
export function pickSectionForDay(
  sections: DBSection[],
  day = new Date().getDay(),
): DBSection | null {
  if (!sections.length) return null;
  const match = sections.find((s) => (s.weekdays ?? []).includes(day));
  return match ?? sections[0];
}

export async function loadPrayerHierarchyBySlug(slug: string): Promise<PrayerHierarchy | null> {
  const { data: prayer, error: pe } = await supabase
    .from("prayers")
    .select("id, engine_version")
    .eq("slug", slug)
    .maybeSingle();
  if (pe || !prayer) return null;

  const [sectionsRes, mysteriesRes, blocksRes] = await Promise.all([
    supabase.from("prayer_sections").select("*").eq("prayer_id", prayer.id).order("order_index"),
    supabase
      .from("prayer_mysteries")
      .select("*, prayer_sections!inner(prayer_id)")
      .eq("prayer_sections.prayer_id", prayer.id)
      .order("order_index"),
    supabase.from("prayer_blocks").select("*").eq("prayer_id", prayer.id).order("order_index"),
  ]);

  if (sectionsRes.error || mysteriesRes.error || blocksRes.error) return null;

  return {
    prayerId: prayer.id,
    sections: (sectionsRes.data ?? []) as DBSection[],
    mysteries: (mysteriesRes.data ?? []).map((m: any) => ({
      id: m.id,
      section_id: m.section_id,
      slug: m.slug,
      title: m.title,
      subtitle: m.subtitle ?? null,
      order_index: m.order_index,
      gospel_ref: m.gospel_ref,
      meditation: m.meditation,
      fruit: m.fruit,
      meta: m.meta ?? null,
    })),
    blocks: (blocksRes.data ?? []) as DBBlock[],
  };
}

/** Achata a hierarquia (para uma seção específica) em `PrayerBlock[]`. */
export function flattenSectionToBlocks(
  hierarchy: PrayerHierarchy,
  section: DBSection,
): PrayerBlock[] {
  const mysteries = hierarchy.mysteries
    .filter((m) => m.section_id === section.id)
    .sort((a, b) => a.order_index - b.order_index);

  const out: PrayerBlock[] = [];
  let orderCounter = 0;

  const emitBlock = (b: DBBlock, mystery: DBMystery | null) => {
    const kind = BLOCK_KIND_MAP[b.type] ?? "prayer";
    const content = b.content ?? {};
    const text = typeof content.text === "string" ? content.text : undefined;
    const latin = typeof content.latin === "string" ? content.latin : undefined;
    const medText = typeof content.meditation === "string" ? content.meditation : undefined;
    const gospelRef =
      typeof content.gospel_ref === "string"
        ? content.gospel_ref
        : (mystery?.gospel_ref ?? undefined);
    const fruit = typeof content.fruit === "string" ? content.fruit : undefined;
    const rubric = typeof content.rubric === "string" ? content.rubric : undefined;

    const meta = (b.meta ?? {}) as Record<string, unknown>;
    const optionGroup = typeof meta.option_group === "string" ? meta.option_group : undefined;
    const optionKey = typeof meta.option_key === "string" ? meta.option_key : undefined;
    const optionLabel = typeof meta.option_label === "string" ? meta.option_label : undefined;

    const block: PrayerBlock = {
      id: b.id,
      kind,
      order: orderCounter++,
      title: b.type === "announce" && mystery ? mystery.title : (b.title ?? mystery?.title ?? ""),
      subtitle: b.type === "announce" ? section.title : undefined,
      body: text,
      latin,
      meditation:
        b.type === "announce"
          ? (medText ?? mystery?.meditation ?? undefined)
          : b.type === "meditation"
            ? (text ?? mystery?.meditation ?? undefined)
            : undefined,
      fruit: b.type === "meditation" ? (fruit ?? mystery?.fruit ?? undefined) : undefined,
      rubric,
      refs: gospelRef && b.type === "announce" ? { bible: [gospelRef] } : undefined,
      mysteryId: mystery?.id,
      sectionId: section.id,
      sourceType: b.type,
      optionGroup,
      optionKey,
      optionLabel,
    };

    if (b.repeat_count > 1) {
      block.repeat = {
        label: REPEAT_LABEL[b.type] ?? b.title ?? b.type,
        count: b.repeat_count,
        text: text ?? undefined,
      };
    }

    out.push(block);
  };

  if (mysteries.length === 0) {
    // Seção sem mistérios (ex.: Ordinário da Missa, orações simples).
    const sectionBlocks = hierarchy.blocks
      .filter((b) => b.section_id === section.id && !b.mystery_id)
      .sort((a, b) => a.order_index - b.order_index);
    for (const b of sectionBlocks) emitBlock(b, null);
    return out;
  }

  for (const mystery of mysteries) {
    const mysteryBlocks = hierarchy.blocks
      .filter((b) => b.mystery_id === mystery.id)
      .sort((a, b) => a.order_index - b.order_index);
    for (const b of mysteryBlocks) emitBlock(b, mystery);
  }
  return out;
}

/** Achata todas as seções (ordem canônica) em `PrayerBlock[]`. */
export function flattenAllSectionsToBlocks(hierarchy: PrayerHierarchy): PrayerBlock[] {
  const sorted = [...hierarchy.sections].sort((a, b) => a.order_index - b.order_index);
  const out: PrayerBlock[] = [];
  for (const s of sorted) out.push(...flattenSectionToBlocks(hierarchy, s));
  return out;
}

import { QueryClient } from "@tanstack/react-query";
import { createRouter as createRouterBase } from "@tanstack/react-router";

// O projeto legado roda sem strictNullChecks; o tipo público de createRouter
// exige essa flag. Mantemos o comportamento em runtime e relaxamos o tipo.
const createRouter = createRouterBase as unknown as (opts: any) => any;
import { routeTree } from "./routeTree.gen";

export const getRouter = () => {
  const queryClient = new QueryClient();

  const router = createRouter({
    routeTree,
    context: { queryClient },
    scrollRestoration: true,
    defaultPreloadStaleTime: 0,
  });

  return router;
};

import * as fs from "fs";
import * as path from "path";
import * as yaml from "js-yaml";
import { z } from "zod";

interface PageCompliance {
  name: string;
  path: string;
  layout: number;
  cards: number;
  theme: number;
  tokens: number;
  overall: number;
  violations: Violation[];
  trends?: any;
}

interface Violation {
  file: string;
  line: number;
  type: string;
  description: string;
  suggestion: string;
  codeSnippet?: string;
}

const HISTORY_FILE = "src/scripts/history/compliance-history.json";
const CONFIG_FILE = "compliance-config.yml";
const PAGES = [
  { name: "Home", path: "src/components/cathedra/HomeMainContent.tsx" },
  { name: "Bible", path: "src/components/cathedra/Bible.tsx" },
  { name: "Catechism", path: "src/components/cathedra/Catechism.tsx" },
  { name: "Library", path: "src/components/cathedra/BibliotecaPage.tsx" },
  { name: "Documents", path: "src/components/cathedra/DocumentViewer.tsx" },
  { name: "Search", path: "src/components/cathedra/GlobalSearchPage.tsx" },
];

function getCodeSnippet(filePath: string, line: number) {
  if (line === 0) return "";
  try {
    const content = fs.readFileSync(filePath, "utf-8");
    const lines = content.split("\n");
    const start = Math.max(0, line - 2);
    const end = Math.min(lines.length, line + 1);
    return lines.slice(start, end).join("\n");
  } catch (e) {
    return "";
  }
}

function runAudit() {
  const reports: PageCompliance[] = [];

  for (const page of PAGES) {
    const violations: Violation[] = [];

    if (!fs.existsSync(page.path)) continue;

    const content = fs.readFileSync(page.path, "utf-8");
    const lines = content.split("\n");

    lines.forEach((line, index) => {
      const lineNum = index + 1;

      if (line.includes("from 'lucide-react'") && !page.path.includes("constants.tsx")) {
        violations.push({
          file: page.path,
          line: lineNum,
          type: "Icon Violation",
          description: "Direct import from lucide-react detected.",
          suggestion: "Import icons from '@/constants' (Icons.Name) instead.",
          codeSnippet: getCodeSnippet(page.path, lineNum),
        });
      }

      const hexMatch = line.match(/#[0-9a-fA-F]{3,8}/);
      if (hexMatch && !line.includes("sacredPalette") && !line.includes("// audit-ignore")) {
        violations.push({
          file: page.path,
          line: lineNum,
          type: "Token Violation",
          description: `Hardcoded Hex color found: ${hexMatch[0]}`,
          suggestion: "Use Tailwind tokens (text-primary) or sacredPalette.",
          codeSnippet: getCodeSnippet(page.path, lineNum),
        });
      }

      if (line.includes("style={{") && !line.includes("// audit-ignore")) {
        violations.push({
          file: page.path,
          line: lineNum,
          type: "Layout Violation",
          description: "Inline style detected.",
          suggestion: "Use Tailwind classes or component variants.",
          codeSnippet: getCodeSnippet(page.path, lineNum),
        });
      }
    });

    if (
      content.includes("<div") &&
      content.includes("rounded") &&
      content.includes("shadow") &&
      !content.includes("CathedraCard")
    ) {
      violations.push({
        file: page.path,
        line: 0,
        type: "Card Violation",
        description: "Custom card-like div detected.",
        suggestion: "Replace with <CathedraCard /> for visual consistency.",
      });
    }

    const layout = Math.max(
      0,
      100 - violations.filter((v) => v.type === "Layout Violation").length * 15,
    );
    const cards = Math.max(
      0,
      100 - violations.filter((v) => v.type === "Card Violation").length * 25,
    );
    const theme = Math.max(
      0,
      100 - violations.filter((v) => v.type === "Token Violation").length * 10,
    );
    const tokens = Math.max(
      0,
      100 - violations.filter((v) => v.type === "Icon Violation").length * 20,
    );
    const overall = (layout + cards + theme + tokens) / 4;

    reports.push({
      name: page.name,
      path: page.path,
      layout,
      cards,
      theme,
      tokens,
      overall,
      violations: violations.slice(0, 10),
    });
  }

  let history: any[] = [];
  if (fs.existsSync(HISTORY_FILE)) {
    try {
      history = JSON.parse(fs.readFileSync(HISTORY_FILE, "utf-8"));
    } catch (e) {
      history = [];
    }
  }

  const lastBuild = history.length > 0 ? history[history.length - 1] : null;

  reports.forEach((report) => {
    if (lastBuild) {
      const prevPage = lastBuild.reports.find((p: any) => p.name === report.name);
      if (prevPage) {
        report.trends = {
          overall: report.overall - prevPage.overall,
          layout: report.layout - prevPage.layout,
          cards: report.cards - prevPage.cards,
          theme: report.theme - prevPage.theme,
          tokens: report.tokens - prevPage.tokens,
        };
      }
    }
  });

  history.push({
    timestamp: new Date().toISOString(),
    reports: reports.map(({ trends, ...r }) => r),
  });
  if (history.length > 50) history.shift();
  fs.mkdirSync(path.dirname(HISTORY_FILE), { recursive: true });
  fs.writeFileSync(HISTORY_FILE, JSON.stringify(history, null, 2));

  reports.sort((a, b) => a.overall - b.overall);

  return { reports, lastBuild, history };
}

const { reports, lastBuild, history } = runAudit();

// Schema Validation for compliance-config.yml
const ThresholdSchema = z
  .number({ error: "Threshold deve ser um número entre 0 e 100" })
  .min(0, "O valor mínimo é 0")
  .max(100, "O valor máximo é 100");

const PageThresholdsSchema = z.strictObject({
  layout: ThresholdSchema.optional(),
  cards: ThresholdSchema.optional(),
  theme: ThresholdSchema.optional(),
  tokens: ThresholdSchema.optional(),
  overall: ThresholdSchema.optional(),
});

const ComplianceConfigSchema = z.strictObject({
  compliance_thresholds: z.strictObject({
    overall: ThresholdSchema,
    pages: z.record(z.string(), PageThresholdsSchema).optional(),
    metrics: z
      .object({
        layout: ThresholdSchema.optional(),
        cards: ThresholdSchema.optional(),
        theme: ThresholdSchema.optional(),
        tokens: ThresholdSchema.optional(),
      })
      .optional()
      .superRefine((val, ctx) => {
        if (val) {
          const keys = Object.keys(val);
          const allowed = ["layout", "cards", "theme", "tokens"];
          keys.forEach((k) => {
            if (!allowed.includes(k)) {
              ctx.addIssue({
                code: z.ZodIssueCode.custom,
                message: `Métrica '${k}' não é reconhecida. Use: layout, cards, theme ou tokens.`,
                path: [k],
              });
            }
          });
        }
      }),
  }),
});

// Load and Validate Config
let config: z.infer<typeof ComplianceConfigSchema> = { compliance_thresholds: { overall: 80 } };
const configRawContent = fs.existsSync(CONFIG_FILE) ? fs.readFileSync(CONFIG_FILE, "utf-8") : null;

if (configRawContent) {
  try {
    const rawConfig = yaml.load(configRawContent);
    const result = ComplianceConfigSchema.safeParse(rawConfig);

    if (!result.success) {
      console.error("\x1b[31m%s\x1b[0m", "❌ ERRO DE VALIDAÇÃO DE CONFIGURAÇÃO");

      const configLines = configRawContent.split("\n");
      let annotationMd = `### ⚠️ Erro de Validação: \`${CONFIG_FILE}\`\n\n`;
      annotationMd += `A configuração de thresholds contém erros que bloqueiam o build. Corrija-os para prosseguir:\n\n`;

      // Group issues by path for better organization
      const groupedIssues: Record<string, z.ZodIssue[]> = {};
      result.error.issues.forEach((issue) => {
        const pathKey = issue.path.join(".") || "root";
        if (!groupedIssues[pathKey]) groupedIssues[pathKey] = [];
        groupedIssues[pathKey].push(issue);
      });

      Object.entries(groupedIssues).forEach(([pathKey, issues]) => {
        annotationMd += `#### 📍 Propriedade: \`${pathKey}\`\n`;

        issues.forEach((issue) => {
          // Find line number and column if possible
          const key = issue.path[issue.path.length - 1];
          let lineNum = 1;
          let colNum = 1;
          let lineContent = "";

          const lineIndex = configLines.findIndex((l) => l.includes(String(key)));
          if (lineIndex !== -1) {
            lineNum = lineIndex + 1;
            lineContent = configLines[lineIndex];
            colNum = lineContent.indexOf(String(key)) + 1;
          }

          const rawValue = lineIndex !== -1 ? lineContent.split(":")[1]?.trim() || "N/A" : "N/A";

          annotationMd += `##### ❌ Erro na Linha ${lineNum}${colNum > 1 ? `, Coluna ${colNum}` : ""}\n`;
          annotationMd += `- **Problema:** ${issue.message}\n`;
          annotationMd += `- **Valor recebido:** \`${rawValue}\`\n`;

          if (issue.code === "invalid_type") {
            annotationMd += `- **Esperado:** \`${issue.expected}\`\n`;
          } else if (issue.message.includes("0 e 100")) {
            annotationMd += `- **Esperado:** Número entre \`0\` e \`100\`\n`;
          }

          if (lineContent) {
            annotationMd += `\n\`\`\`yaml\n${lineNum} | ${lineContent}\n${" ".repeat(String(lineNum).length + 3 + (colNum - 1))}^\n\`\`\`\n`;
          }
          annotationMd += `\n---\n`;

          console.error(`  📍 Propriedade: \x1b[33m${pathKey}\x1b[0m (Linha ${lineNum}:${colNum})`);
          console.error(`     Erro: ${issue.message}\n`);
        });
      });

      fs.writeFileSync("compliance-report.md", annotationMd);
      process.exit(1);
    }
    config = result.data;

    // Additional check: Ensure page names in config match known pages
    const knownPageNames = PAGES.map((p) => p.name);
    const configPageNames = Object.keys(config.compliance_thresholds.pages || {});
    configPageNames.forEach((pageName) => {
      if (!knownPageNames.includes(pageName)) {
        console.warn(
          "\x1b[33m%s\x1b[0m",
          `⚠️  AVISO: A página '${pageName}' definida no config não existe no sistema.`,
        );
      }
    });
  } catch (e) {
    console.error("\x1b[31m%s\x1b[0m", `❌ ERRO CRÍTICO: Falha ao processar ${CONFIG_FILE}.`);
    process.exit(1);
  }
}

fs.writeFileSync("compliance-report.json", JSON.stringify(reports, null, 2));

