  last_updated: new Date().toISOString(),
  overall_score: reports.reduce((acc, r) => acc + r.overall, 0) / reports.length,
  page_metrics: reports.map((r) => ({
    name: r.name,
    overall: r.overall,
    variation: r.trends?.overall || 0,
    metrics: {
      layout: r.layout,
