function getTrendIcon(val: number = 0) {
  if (val > 0) return `<span style="color: #10b981;">↑ ${val.toFixed(1)}%</span>`;
  if (val < 0) return `<span style="color: #ef4444;">↓ ${Math.abs(val).toFixed(1)}%</span>`;
  return `<span style="color: #666;">--</span>`;
}

